"""Tests for the professional networking BFS shortest-path tool."""

import io;
import from contextlib { redirect_stdout }


def _build_network() {
    alice = Person(name="Alice", role="Engineer");
    bob = Person(name="Bob", role="Designer");
    carol = Person(name="Carol", role="PM");
    dave = Person(name="Dave", role="CTO");
    eve = Person(name="Eve", role="CEO");
    frank = Person(name="Frank", role="Analyst");

    root ++> alice
        ++> bob
        ++> carol
        ++> dave
        ++> eve
        ++> frank;

    alice +>:knows:+> bob;
    bob +>:knows:+> carol;
    carol +>:knows:+> dave;
    dave +>:knows:+> eve;
    frank +>:knows:+> eve;

    return [alice, bob, carol, dave, eve, frank];
}


test "finds full chain from Alice to Eve via Dave" {
    _build_network();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn FindPath(target_name="Eve");
    }
    out = buf.getvalue().strip();

    assert out == "Alice -> Bob -> Carol -> Dave -> Eve", f"unexpected chain: {out!r}";
    assert res.found is True, f"expected found=True, got {res.found}";
    assert len(res.path) == 5, f"expected path length 5, got {len(res.path)}: {res.path}";
}


test "shortest path prefers 2-hop route over longer alternates" {
    _build_network();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn FindPath(target_name="Eve");
    }
    out = buf.getvalue().strip();

    # Frank -> Eve is a direct 1-hop edge, but we start from Root and visit
    # the children of root in declaration order, so the first chain found is
    # the canonical one. Either way, path must end at Eve and contain Eve.
    assert out.endswith(" -> Eve"), f"chain must terminate at Eve, got: {out!r}";
    assert "Eve" in out, f"Eve missing from output: {out!r}";
    assert res.path[-1] == "Eve", f"last visited node should be Eve, got {res.path[-1]}";
}


test "reports the target as found and stops walking" {
    _build_network();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn FindPath(target_name="Carol");
    }
    out = buf.getvalue().strip();

    assert out == "Alice -> Bob -> Carol", f"expected direct chain to Carol, got {out!r}";
    assert res.found is True, f"expected found=True, got {res.found}";
    assert len(res.path) == 3, f"expected 3 nodes in path, got {len(res.path)}: {res.path}";
}


test "graph shape: chain via knows edges connects the six people" {
    people = _build_network();
    [alice, bob, carol, dave, eve, frank] = people;

    # Root has exactly one direct child (chain via ++>).
    assert len([root-->]) == 1, f"root should have one direct child, got {len([root-->])}";

    # Total reachable nodes from root via the chain is six.
    reachable = [root->:knows:->];
    # knows edges go between people; count them.
    knows_edges = [alice +>:knows:+> bob,
                   bob +>:knows:+> carol,
                   carol +>:knows:+> dave,
                   dave +>:knows:+> eve,
                   frank +>:knows:+> eve];

    assert bob in [alice ->:knows:->], "alice should know bob";
    assert eve in [dave ->:knows:->], "dave should know eve";
    assert eve in [frank ->:knows:->], "frank should know eve";
}


test "default target_name yields initial path state" {
    # Spawn without a target and just inspect the initial walker fields;
    # we don't fire it on the wrong type, just construct and verify defaults.
    w = FindPath();
    assert w.target_name == "", f"default target_name should be empty string, got {w.target_name!r}";
    assert w.path == [], f"default path should be empty list, got {w.path}";
    assert w.found is False, f"default found should be False, got {w.found}";
}

