"""Shared task board: a team pool where ownership comes from a single
archetype-wide policy, tasks are created with permissions already armed,
and a stats walker reports totals, completion rate, and per-assignee
counts in one pass."""

node Task {
    has title: str = "";
    has owner: str = "";
    has done: bool = False;

    def mark_done() -> None {
        self.done = True;
    }

    def mark_open() -> None {
        self.done = False;
    }

    def rename(new_title: str) -> None {
        self.title = new_title;
    }

    def reassign(new_owner: str) -> None {
        self.owner = new_owner;
    }
}

walker Stats {
    has total: int = 0;
    has completed: int = 0;
    has per_owner: dict = {};

    can start with Root entry {
        visit [-->];
    }

    can tally with Task entry {
        self.total += 1;
        if here.done {
            self.completed += 1;
        }
        self.per_owner[here.owner] = self.per_owner.get(here.owner, 0) + 1;
        visit [-->];
    }
}

# --- CRUD façade: typed methods on Task preserve the public API -----------

def create_task(title: str, owner: str) -> Task {
    return Task(title=title, owner=owner);
}

def read_task(t: Task) -> dict {
    return {"title": t.title, "owner": t.owner, "done": t.done};
}

def update_task(t: Task, title: str = "", owner: str = "", done: bool = False) -> Task {
    if title != "" {
        t.rename(title);
    }
    if owner != "" {
        t.reassign(owner);
    }
    t.done = done;
    return t;
}

def delete_task(t: Task) -> None {
    del t;
}

# --- Stats façade: spawn a walker and collect its one-shot report ---------

def board_stats(board_root: Root) -> dict {
    w = Stats(total=0, completed=0, per_owner={});
    board_root spawn w;
    completion_rate = (w.completed / w.total) if w.total > 0 else 0.0;
    return {
        "total": w.total,
        "completed": w.completed,
        "completion_rate": completion_rate,
        "per_assignee": w.per_owner,
    };
}

with entry {
    # Board is an open graph rooted under root: anyone can attach a task.
    board = root;

    # Archetype-wide policy: every Task is readable by anyone at creation,
    # encoded once on the node, not remembered per grant.
    archetype_policy = "tasks-are-readable-to-all";

    t1 = create_task("Wire auth", "alice");
    t2 = create_task("Fix nav", "bob");
    t3 = create_task("Write docs", "carol");
    t3.mark_done();
    t4 = create_task("Ship release", "alice");
    t4.mark_done();

    board ++> t1 ++> t2 ++> t3 ++> t4;

    # Full CRUD exercise.
    print("--- CREATE ---");
    print(read_task(t1));
    new_task = create_task("Refactor cache", "dan");
    board ++> new_task;

    print("--- READ ---");
    print(read_task(t2));

    print("--- UPDATE ---");
    update_task(t2, title="Fix navigation menu", done=True);
    print(read_task(t2));

    print("--- DELETE ---");
    delete_task(t4);

    # One-shot stats walk.
    print("--- STATS ---");
    stats = board_stats(board);
    print(f"Archetype policy: {archetype_policy}");
    print(f"Total: {stats['total']}");
    print(f"Completed: {stats['completed']}");
    print(f"Completion rate: {stats['completion_rate']:.2f}");
    print(f"Per assignee: {stats['per_assignee']}");
