"""Test annex for the library catalog program."""

import io;
import from contextlib { redirect_stdout }

# Helper: build a fresh shelf of three books and return the list.
def build_shelf {
    shelf = root ++> Book(title="Dune", year=1965)
        ++> Book(title="Neuromancer", year=1984)
        ++> Book(title="Circe", year=2018, available=False);
    return shelf;
}

test "default year and availability on a bare book" {
    # A bare Book() should default year=0 and available=True.
    b = Book(title="Untitled");
    assert b.year == 0, f"default year should be 0, got {b.year}";
    assert b.available is True, f"default available should be True, got {b.available}";
    assert b.title == "Untitled", f"explicit title should be 'Untitled', got {b.title}";
}

test "librarian walks the shelf and prints IN/OUT per book" {
    build_shelf();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Librarian();
    }
    out = buf.getvalue();
    # The walker announces itself, then prints one line per book.
    assert "Walking the shelf..." in out, f"missing shelf header in: {out}";
    assert "[IN] Dune (1965)" in out, f"missing Dune IN line in: {out}";
    assert "[IN] Neuromancer (1984)" in out, f"missing Neuromancer IN line in: {out}";
    assert "[OUT] Circe (2018)" in out, f"missing Circe OUT line in: {out}";
}

test "in status is printed when available flag is true" {
    # Single available book -> [IN] line.
    root ++> Book(title="Hyperion", year=1989, available=True);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Librarian();
    }
    out = buf.getvalue();
    assert "[IN] Hyperion (1989)" in out, f"expected IN line, got: {out}";
    assert "[OUT]" not in out, f"should not contain OUT marker, got: {out}";
}

test "out status is printed when available flag is false" {
    # Single unavailable book -> [OUT] line.
    root ++> Book(title="Foundation", year=1951, available=False);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Librarian();
    }
    out = buf.getvalue();
    assert "[OUT] Foundation (1951)" in out, f"expected OUT line, got: {out}";
    assert "[IN]" not in out, f"should not contain IN marker, got: {out}";
}

test "year defaults to 0 when unknown on a shelved book" {
    # Year not provided -> 0 appears in the printed line.
    root ++> Book(title="Anonymous");
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Librarian();
    }
    out = buf.getvalue();
    assert "[IN] Anonymous (0)" in out, f"default year of 0 not printed, got: {out}";
}

