    assert res.station_tally["S2"] >= 1, f"S2 should be served at least once: {res.station_tally}";
    assert res.station_tally["S3"] >= 1, f"S3 should be served at least once: {res.station_tally}";

    # robot_tally must reflect every robot visited on the walk.
    assert "R-1" in res.robot_tally, f"R-1 missing from robot_tally: {res.robot_tally}";
    assert "R-2" in res.robot_tally, f"R-2 missing from robot_tally: {res.robot_tally}";
    assert res.robot_tally["R-1"] >= 1, f"R-1 should be announced at least once: {res.robot_tally}";
    assert res.robot_tally["R-2"] >= 1, f"R-2 should be announced at least once: {res.robot_tally}";

    # Stations literally announce they are serving a robot.
    assert "is serving a robot" in out, f"missing station announcement: {out}";
    # Robots literally announce they stopped at a station.
    assert "stopped at a station" in out, f"missing robot announcement: {out}";
}


test "robot runner pulls up at each station and increments packed count" {
