    assert s1.packed == 2, f"S1 packed expected 2 got {s1.packed}";
    assert s2.packed == 2, f"S2 packed expected 2 got {s2.packed}";
    assert s3.packed == 2, f"S3 packed expected 2 got {s3.packed}";
