test "packer increments per-robot stops field on each visit" {
    # Robot's `stops` counter is bumped every time the packer's at_robot fires.
    root ++> Station(name="S1", packed=0);
    r1 = Robot(label="R-1", stops=0);
    r2 = Robot(label="R-2", stops=0);
    root ++> r1 ++> r2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Packer();
    }
    out = buf.getvalue();

    # Packer walks all reachable robots; both should have at least one stop recorded.
    assert r1.stops >= 1, f"R-1 stops expected >=1 got {r1.stops}";
    assert r2.stops >= 1, f"R-2 stops expected >=1 got {r2.stops}";
    # The packer's per-robot tally must agree with the per-robot stop counter
    # for the robots it actually walked (counts come from the same walker entry).
    assert res.robot_tally.get("R-1", 0) == r1.stops, (
        f"tally/tally mismatch R-1: packer says {res.robot_tally.get('R-1', 0)} robot says {r1.stops}"
    );
    assert res.robot_tally.get("R-2", 0) == r2.stops, (
        f"tally/tally mismatch R-2: packer says {res.robot_tally.get('R-2', 0)} robot says {r2.stops}"
    );
    assert "total stops=" in out, f"missing per-stop print line: {out}";
}


test "packer walks an isolated station-only graph and tallies it" {
    # Edge case: graph with only stations (no robots). Packer should still
    # announce each station it visits and tally them.
    s1 = Station(name="Alpha", packed=3);
    s2 = Station(name="Beta", packed=7);
    root ++> s1 ++> s2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Packer();
    }
    out = buf.getvalue();

    assert "Alpha" in res.station_tally, f"Alpha not tallied: {res.station_tally}";
    assert "Beta" in res.station_tally, f"Beta not tallied: {res.station_tally}";
    assert res.station_tally["Alpha"] == 1, f"Alpha tally expected 1 got {res.station_tally['Alpha']}";
    assert res.station_tally["Beta"] == 1, f"Beta tally expected 1 got {res.station_tally['Beta']}";
    # No robots in this graph -> robot_tally must stay empty.
    assert len(res.robot_tally) == 0, f"robot_tally should be empty, got {res.robot_tally}";
    # Station announce carries the packed count verbatim.
    assert "packed=3" in out, f"missing packed=3 in output: {out}";
    assert "packed=7" in out, f"missing packed=7 in output: {out}";
}

