import io;
import from contextlib { redirect_stdout }

def make_graph() {
    zone_a = Zone(name="Zone A");
    zone_b = Zone(name="Zone B");
    root ++> zone_a ++> zone_b;

    zone_a ++> TempSensor(label="Boiler-1", celsius=82.5);
    zone_a ++> SmokeSensor(label="Boiler-1 smoke", ppm=18.0);
    zone_a ++> TempSensor(label="Boiler-2", celsius=70.0);

    zone_b ++> SmokeSensor(label="Bay-3 smoke", ppm=63.0);
    zone_b ++> TempSensor(label="Bay-3 temp", celsius=55.0);
    zone_b ++> SmokeSensor(label="Bay-4 smoke", ppm=12.5);
    return zone_a;
}

test "all sensors printed in nominal or alert form" {
    make_graph();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        p = Patrol();
        root spawn p;
    }
    out = buf.getvalue();

    # Every sensor label must appear, tagged as nominal or ALERT
    for label in ["Boiler-1", "Boiler-1 smoke", "Boiler-2",
                  "Bay-3 smoke", "Bay-3 temp", "Bay-4 smoke"] {
        assert (f"[nominal] {label}" in out) or (f"[ALERT] {label}" in out),
               f"sensor {label} missing from output: {out}";
    }

    # Zone headers should be printed
    assert "-- patrolling zone: Zone A --" in out, f"zone A header missing: {out}";
    assert "-- patrolling zone: Zone B --" in out, f"zone B header missing: {out}";
}

test "threshold semantics: above threshold is alert, at/below is nominal" {
    make_graph();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        p = Patrol();
        root spawn p;
    }
    out = buf.getvalue();

    # Temp threshold: > 75 C => ALERT; 82.5 is alert, 70.0 and 55.0 are nominal
    assert "[ALERT] Boiler-1" in out, f"82.5 C should be ALERT: {out}";
    assert "[nominal] Boiler-2" in out, f"70.0 C should be nominal: {out}";
    assert "[nominal] Bay-3 temp" in out, f"55.0 C should be nominal: {out}";

    # Smoke threshold: > 50 ppm => ALERT; 63.0 is alert, 18.0 and 12.5 are nominal
    assert "[ALERT] Bay-3 smoke" in out, f"63.0 ppm should be ALERT: {out}";
    assert "[nominal] Boiler-1 smoke" in out, f"18.0 ppm should be nominal: {out}";
    assert "[nominal] Bay-4 smoke" in out, f"12.5 ppm should be nominal: {out}";
}

test "alerts list contains exactly the exceeding readings" {
    make_graph();
    p = Patrol();
    root spawn p;

    # Only Boiler-1 (temp 82.5) and Bay-3 smoke (63.0) exceed thresholds
    assert len(p.alerts) == 2, f"expected 2 alerts, got {p.alerts}";

    expected_alert_messages = [
        "Boiler-1 reading exceeds threshold",
        "Bay-3 smoke reading exceeds threshold",
