    for msg in expected_alert_messages {
        assert msg in p.alerts,
               f"expected alert '{msg}' in {p.alerts}";
    }
}

test "boundary values: exactly at threshold is nominal (strict greater-than)" {
    root ++> Zone(name="Edge") ++> TempSensor(label="Boundary-temp", celsius=75.0);
    root ++> Zone(name="Edge2") ++> SmokeSensor(label="Boundary-smoke", ppm=50.0);

    buf = io.StringIO();
