"""Test annex for wildlife park feeding rounds.

Builds its own graph in each test (the demo `with entry` is deleted by the
harness and never runs). Each test spawns walkers on graph state it built
itself and asserts on captured stdout.
"""

import io;
import from contextlib { redirect_stdout }

# Build a small park: kiosk -> simba -> polly -> ziggy, attached to a fresh
# Root. Each test uses its own Root so they stay isolated.
def build_park() {
    rt = Root();
    kiosk = InfoKiosk(kiosk_name="Savannah");
    simba = Lion(name="Simba", species="lion");
    polly = Parrot(name="Polly", species="parrot");
    ziggy = Zebra(name="Ziggy", species="zebra");

    rt ++> kiosk ++> simba ++> polly ++> ziggy;
    return (rt, kiosk, simba, polly, ziggy);
}

test "zookeeper feeds each animal its species-appropriate meal" {
    (rt, kiosk, simba, polly, ziggy) = build_park();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        zk = Zookeeper();
        rt spawn zk;
    }
    out = buf.getvalue();

    # Meat for the lion, seed for the parrot, standard feed for the zebra.
    assert "Zookeeper feeds Simba the lion: meat" in out, f"lion meal missing: {out}";
    assert "Zookeeper feeds Polly the parrot: seed" in out, f"parrot meal missing: {out}";
    assert "Zookeeper feeds Ziggy the zebra: standard feed" in out, f"zebra meal missing: {out}";

    # Each animal must be marked as fed.
    assert simba.fed is True, "simba not fed";
    assert polly.fed is True, "polly not fed";
    assert ziggy.fed is True, "ziggy not fed";

    # Exactly three feeding lines printed, one per animal.
    feed_lines = [l for l in out.splitlines() if l.startswith("Zookeeper feeds ")];
    assert len(feed_lines) == 3, f"expected 3 feed lines, got {len(feed_lines)}: {feed_lines}";
}

test "zookeeper is greeted at the info kiosk" {
    (rt, kiosk, simba, polly, ziggy) = build_park();

    zk = Zookeeper();
    rt spawn zk;

    # Kiosk greeted the zookeeper (union trigger accepts Zookeeper | SchoolGroup).
    assert zk.kiosk_visits == 1, f"expected 1 kiosk visit, got {zk.kiosk_visits}";

    # Sanity: the zookeeper also actually walked the whole chain and fed everyone.
    assert simba.fed and polly.fed and ziggy.fed, "zookeeper did not complete feeding round";
}

test "school group watches animals and is greeted at the kiosk" {
    (rt, kiosk, simba, polly, ziggy) = build_park();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        sg = SchoolGroup();
        rt spawn sg;
    }
    out = buf.getvalue();

    # Union kiosk trigger accepts the school group too.
    assert sg.kiosk_visits == 1, f"expected 1 kiosk visit, got {sg.kiosk_visits}";

    # School group only observes -- it prints each animal's preferred meal
    # but never sets fed.
    assert "School group watches Simba (meat)" in out, f"lion observation missing: {out}";
    assert "School group watches Polly (seed)" in out, f"parrot observation missing: {out}";
    assert "School group watches Ziggy (standard feed)" in out, f"zebra observation missing: {out}";

    # School group must NOT have fed anyone.
    assert simba.fed is False, "school group should not feed simba";
    assert polly.fed is False, "school group should not feed polly";
    assert ziggy.fed is False, "school group should not feed ziggy";

    # No zookeeper-style feeding lines should appear in this run.
    assert "Zookeeper feeds" not in out, f"unexpected zookeeper feed line in school run: {out}";
}

test "kiosk greets both parties via union trigger" {
    # Two independent runs: one with a zookeeper, one with a school group.
    # Both must bump their kiosk_visits counter exactly once.
    (rt1, kiosk1, simba1, polly1, ziggy1) = build_park();
    zk = Zookeeper();
    rt1 spawn zk;
    assert zk.kiosk_visits == 1, f"zk visits={zk.kiosk_visits}";
    assert zk.party_label == "Zookeepers", f"zk label={zk.party_label}";

    (rt2, kiosk2, simba2, polly2, ziggy2) = build_park();
    sg = SchoolGroup();
    rt2 spawn sg;
    assert sg.kiosk_visits == 1, f"sg visits={sg.kiosk_visits}";
    assert sg.party_label == "School Group", f"sg label={sg.party_label}";
}

test "graph topology from kiosk through animals" {
    # Confirm the chain shape we build is what the walkers traverse:
    # Root -> InfoKiosk -> Lion -> Parrot -> Zebra (4 nodes total).
    (rt, kiosk, simba, polly, ziggy) = build_park();

    assert len([rt-->]) == 1, f"root should have exactly 1 direct child, got {len([rt-->])}";

    # Walk the chain and verify the node-type sequence.
    chain = [n for n in [rt-->]];
    assert isinstance(chain[0], InfoKiosk), f"root's child should be InfoKiosk, got {type(chain[0])}";

    # From kiosk, follow forward edges to enumerate the rest of the chain.
    cur = chain[0];
    seen_types = [type(cur).__name__];
    while len([cur-->]) > 0 {
        nxt = [cur-->][0];
        seen_types.append(type(nxt).__name__);
        cur = nxt;
    }
    assert seen_types == ["InfoKiosk", "Lion", "Parrot", "Zebra"], f"chain order wrong: {seen_types}";
}

