"""Tests for the tiny blogging service: public feed, article view, comments,
private drafts, publishing, and cascade delete."""

import io;
import from contextlib { redirect_stdout }

# ---------- Public feed ----------

test "public feed lists every published article with preview" {
    root ++> Article(title="Alpha", body="This is the alpha article body.");
    root ++> Article(title="Beta", body="Beta body content goes here.");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        w = PublicFeed();
        root spawn w;
    }

    assert len(w.feed) == 2, f"expected 2 entries, got {len(w.feed)}";
    titles = [a["title"] for a in w.feed];
    assert "Alpha" in titles and "Beta" in titles, f"missing titles: {titles}";
    previews = [a["preview"] for a in w.feed];
    assert all(len(p) <= 40 for p in previews), f"previews too long: {previews}";
}

# ---------- Article view ----------

test "article view prints body and comment count for matching title" {
    root ++> Article(title="Solo", body="the solo article body");
    solo_ref = [root -->][?:Article][0];
    solo_ref ++> Comment(author="x", body="hi");
    solo_ref ++> Comment(author="y", body="there");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn ArticleView(title_query="Solo");
    }
    out = buf.getvalue();

    assert "=== Solo ===" in out, f"missing title banner: {out}";
    assert "the solo article body" in out, f"missing body: {out}";
    assert "2 comment(s)" in out, f"missing comment count: {out}";
}

# ---------- Comments ----------

test "comment poster attaches comment to the right article only" {
    root ++> Article(title="Target", body="tgt");
    root ++> Article(title="Other",  body="oth");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        cp = CommentPoster(title_query="Target",
                           author_name="zoe",
                           comment_body="first!");
        root spawn cp;
    }
    out = buf.getvalue();

    assert cp.success, "poster reported failure";
    assert "Comment by zoe added to 'Target'" in out, f"missing log: {out}";

    target = [root -->][?:Article][0];
    other  = [root -->][?:Article][1];
    assert len([target -->]) == 1, f"target should have 1 comment, got {len([target -->])}";
    assert len([other  -->]) == 0, f"other should have 0 comments, got {len([other -->])}";

    the_comment = [target -->][?:Comment][0];
    assert the_comment.author == "zoe", f"wrong author: {the_comment.author}";
    assert the_comment.body == "first!", f"wrong body: {the_comment.body}";
}

# ---------- Cascade delete ----------

test "article deleter removes article and cascades its comments" {
    root ++> Article(title="Doomed", body="goodbye");
    doomed = [root -->][?:Article][0];
    doomed ++> Comment(author="a", body="x");
    doomed ++> Comment(author="b", body="y");
    doomed ++> Comment(author="c", body="z");

    assert len([root -->]) == 1, "graph setup wrong";
    assert len([doomed -->]) == 3, "comments setup wrong";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn ArticleDeleter(title_query="Doomed");
    }
