fixed.jac_tests:
"""Test annex for the hiking trail program."""

import io;
import from contextlib { redirect_stdout }

# ---------- helper: build a default 6-waypoint trail (head + 5 valid stops + summit-like extra) ----------
def build_default_trail {
    r = root;
    r ++> Waypoint(label="trailhead gate")
        ++> Waypoint(label="creek crossing")
        ++> Waypoint(label="oak overlook")
        ++> Waypoint(label="granite ledge")
        ++> Waypoint(label="false summit")
        ++> Waypoint(label="summit marker");
    return r;
}

# ---------- helper: run a Hiker on a freshly built trail graph and capture stdout ----------
def run_hiker_and_capture(goal: int) -> tuple {
    r = build_default_trail();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = r spawn Hiker(goal=goal);
    }
    return (buf.getvalue(), res);
}

test "hiker prints each stop number and a final completion line" {
    out = run_hiker_and_capture(goal=5)[0];

    # Each of the 5 waypoints visited (everything before the 6th) must produce a "Stop #N: <label>" line.
    assert "Stop #1: trailhead gate" in out, f"missing stop #1 line in output:\n{out}";
    assert "Stop #2: creek crossing" in out, f"missing stop #2 line in output:\n{out}";
    assert "Stop #3: oak overlook" in out, f"missing stop #3 line in output:\n{out}";
    assert "Stop #4: granite ledge" in out, f"missing stop #4 line in output:\n{out}";
    assert "Stop #5: false summit" in out, f"missing stop #5 line in output:\n{out}";

    # Completion message must appear exactly once and reference the stop count.
    assert "Reached the summit after 5 stops!" in out, f"missing completion line in output:\n{out}";
}

test "hiker disengages at the goal and does not visit waypoints beyond it" {
    out = run_hiker_and_capture(goal=5)[0];

    # The 6th waypoint ("summit marker") must NOT be printed — the walker should disengage at goal=5.
    assert "summit marker" not in out, f"hiker walked past goal; unexpected waypoint in output:\n{out}";
    assert "Stop #6" not in out, f"hiker logged a 6th stop beyond the goal:\n{out}";
}

test "hiker stops counter equals number of visited waypoints" {
    (out, res) = run_hiker_and_capture(goal=5);

    assert res.stops == 5, f"expected stops counter == 5, got {res.stops}";
}

test "hiker with a larger goal continues past the default stopping point" {
    # Build a short custom trail so we can prove the walker keeps going when goal is not yet reached.
    r = root;
    r ++> Waypoint(label="a")
        ++> Waypoint(label="b")
        ++> Waypoint(label="c")
        ++> Waypoint(label="d");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = r spawn Hiker(goal=4);
    }
    out = buf.getvalue();

    # All 4 waypoints should be announced and the completion line should fire.
    assert "Stop #1: a" in out, f"missing stop a:\n{out}";
    assert "Stop #2: b" in out, f"missing stop b:\n{out}";
    assert "Stop #3: c" in out, f"missing stop c:\n{out}";
    assert "Stop #4: d" in out, f"missing stop d:\n{out}";
    assert "Reached the summit after 4 stops!" in out, f"missing completion for goal=4:\n{out}";
    assert res.stops == 4, f"expected stops == 4, got {res.stops}";
}

test "hiker announces the trailhead start and handles a dead-end root gracefully" {
    # Root with no outgoing edges — Hiker should still print the start line and disengage cleanly.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker(goal=5);
    }
