"""Tests for the weather sweep program."""

import io;
import from contextlib { redirect_stdout }

test "walker reports each station and collects readings" {
    root ++> WeatherStation(location="North", celsius=12.5)
        ++> WeatherStation(location="East", celsius=18.0)
        ++> WeatherStation(location="South", celsius=9.25)
        ++> WeatherStation(location="West", celsius=22.75);

    sweep = WeatherSweep();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn sweep;
    }
    out = buf.getvalue();

    # Every station should be announced with its location and Celsius reading.
    assert "[North] 12.5 C" in out, f"missing North line in: {out}";
    assert "[East] 18.0 C" in out, f"missing East line in: {out}";
    assert "[South] 9.25 C" in out, f"missing South line in: {out}";
    assert "[West] 22.75 C" in out, f"missing West line in: {out}";

    # The walker accumulates every reading, in traversal order.
    assert res.readings == [12.5, 18.0, 9.25, 22.75], f"unexpected readings: {res.readings}";
    assert len(res.readings) == 4, f"expected 4 readings, got {len(res.readings)}";

    # Standard min/max over the readings must match the values we seeded.
    assert min(res.readings) == 9.25, f"unexpected min: {min(res.readings)}";
    assert max(res.readings) == 22.75, f"unexpected max: {max(res.readings)}";
}

test "walker handles a single station graph" {
    root ++> WeatherStation(location="Solo", celsius=-3.0);

    sweep = WeatherSweep();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn sweep;
    }
    out = buf.getvalue();

    assert "[Solo] -3.0 C" in out, f"missing Solo line in: {out}";
    assert res.readings == [-3.0], f"expected only -3.0, got {res.readings}";
    assert min(res.readings) == max(res.readings) == -3.0, "min and max must agree on a single reading";
}

test "walker with no stations yields an empty reading list" {
    # Graph exists but has no WeatherStation children.
    sweep = WeatherSweep();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn sweep;
    }
    out = buf.getvalue();

    # No station lines should have been printed.
    assert "C" not in out, f"unexpected station output: {out}";
    assert res.readings == [], f"expected no readings, got {res.readings}";
}

test "walker does not stop after reading the first station" {
    # If the walker stopped at the first node (a common regression), only the
    # first line would appear and the rest would be missing. Verify all four
    # were visited, in chain order.
    root ++> WeatherStation(location="A", celsius=1.0)
        ++> WeatherStation(location="B", celsius=2.0)
        ++> WeatherStation(location="C", celsius=3.0)
        ++> WeatherStation(location="D", celsius=4.0);

    sweep = WeatherSweep();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn sweep;
    }
    out = buf.getvalue();

    # Each location line must precede the next (strict ordering along the chain).
    idx_a = out.find("[A] 1.0 C");
    idx_b = out.find("[B] 2.0 C");
    idx_c = out.find("[C] 3.0 C");
    idx_d = out.find("[D] 4.0 C");

    assert idx_a != -1 and idx_b != -1 and idx_c != -1 and idx_d != -1, f"missing station line(s) in: {out}";
    assert idx_a < idx_b < idx_c < idx_d, f"stations not visited in order; output was: {out}";

    # And the readings list matches that order.
    assert res.readings == [1.0, 2.0, 3.0, 4.0], f"unexpected readings: {res.readings}";
}

