"""Tiny dungeon crawler: a chain of rooms with one vault holding the treasure.

A Hunter walker traverses rooms one by one, counting how many it has
inspected, and disengages the moment it finds the vault so that rooms
past it are never entered.
"""

node Room {
    has name: str = "";
    has is_vault: bool = False;
}

walker Hunter {
    has rooms_inspected: int = 0;
    has treasure_found: bool = False;

    can start with Root entry {
        print("Hunter enters the dungeon...");
        visit [-->];
    }

    can search with Room entry {
        self.rooms_inspected += 1;
        if here.is_vault {
            print(f"Found the treasure in '{here.name}' after inspecting "
                f"{self.rooms_inspected} room(s). Hunter stops.");
            self.treasure_found = True;
            disengage;
        } else {
            print(f"Inspected '{here.name}' (rooms seen: {self.rooms_inspected})");
            visit [-->];
        }
    }
}

with entry {
    root ++> Room(name="Entrance")
        ++> Room(name="Antechamber")
        ++> Room(name="Pillar Hall")
        ++> Room(name="Vault", is_vault=True)
        ++> Room(name="Forbidden Crypt")
        ++> Room(name="Hidden Cellar");

    hunter = Hunter();
    root spawn hunter;

    if hunter.treasure_found {
        print(f"Final report: treasure secured after {hunter.rooms_inspected} room(s).");
    } else {
        print("Final report: no treasure found.");
    }
}

