"""Test annex for the neighborhood mutual friendships program."""

import io;
import from contextlib { redirect_stdout }

test "bidirectional buddy edges in a single statement" {
    alice = House(name="Alice");
    bob = House(name="Bob");

    # The single statement that creates a bidirectional buddy link.
    alice +>:Buddy(since="2024"):+> bob;
    bob +>:Buddy(since="2024"):+> alice;

    root ++> alice ++> bob;

    # The link really points both ways.
    assert bob in [alice ->:Buddy:->], "Alice should reach Bob via Buddy";
    assert alice in [bob ->:Buddy:->], "Bob should reach Alice via Buddy";

    # Exactly one Buddy edge in each direction (no duplication).
    assert len([alice ->:Buddy:->]) == 1, "Alice should have exactly one Buddy neighbor";
    assert len([bob ->:Buddy:->]) == 1, "Bob should have exactly one Buddy neighbor";
}

test "greeter from Alice reaches Bob with forward traversal only" {
    alice = House(name="Alice");
    bob = House(name="Bob");
    alice +>:Buddy(since="2024"):+> bob;
    bob +>:Buddy(since="2024"):+> alice;
    root ++> alice ++> bob;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = alice spawn Greeter(target="Bob");
    }
    out = buf.getvalue();

    # The greeter must traverse from Alice's house to Bob's house.
    assert "Alice -> Bob: reached friend 'Bob'" in out, f"missing reach marker: {out!r}";

    # Forward-only proof: the walker must NOT loop back to Alice after reaching Bob,
    # and must not contain Bob -> Bob or Alice -> Alice entries.
    assert "Bob -> Alice" not in out, f"greeter should not ping-pong back: {out!r}";
    assert "Bob -> Bob" not in out, f"greeter should not self-loop: {out!r}";

    # The walker must actually disengage (terminates) once the target is hit.
    assert "Alice -> Bob" in out, f"expected single forward hop recorded: {out!r}";

    # Walker bookkeeping: visited list must contain start and target only,
    # never the start node a second time (i.e., no bounce).
    assert res.visited[0].name == "Alice", f"first visited should be Alice: {[n.name for n in res.visited]}";
    assert res.visited[-1].name == "Bob", f"last visited should be Bob: {[n.name for n in res.visited]}";
    visited_names = [n.name for n in res.visited];
    assert visited_names.count("Alice") == 1, f"Alice should appear once in visited, got {visited_names}";
