    assert "Bob -> Alice: reached friend 'Alice'" in out, f"missing reach marker: {out!r}";

    # Must not ping-pong: no Alice -> Bob line should appear, no self-loop.
    assert "Alice -> Bob" not in out, f"greeter should not bounce back to Bob: {out!r}";
    assert "Alice -> Alice" not in out, f"greeter should not self-loop: {out!r}";

    # Walker bookkeeping.
    assert res.visited[0].name == "Bob", f"first visited should be Bob: {[n.name for n in res.visited]}";
    assert res.visited[-1].name == "Alice", f"last visited should be Alice: {[n.name for n in res.visited]}";
