"""Order auditor: invalid orders are skipped, fraud orders halt the walk."""

node Order {
    has order_id: str = "";
    has amount: float = 0.0;
    has valid: bool = True;
    has fraud_flagged: bool = False;
}

walker OrderAuditor {
    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can audit with Order entry {
        action = "";
        if here.fraud_flagged {
            action = "HALT";
            print(f"[{action}] order {here.order_id} amount={here.amount} -> stopping walk");
            disengage;
        } elif not here.valid {
            action = "SKIP";
            print(f"[{action}] order {here.order_id} amount={here.amount} -> continuing");
            visit [-->] else { disengage; }
        } else {
            action = "OK";
            print(f"[{action}] order {here.order_id} amount={here.amount} -> continuing");
            visit [-->] else { disengage; }
        }
    }
}

with entry {
    root ++> Order(order_id="A1", amount=120.0)
        ++> Order(order_id="A2", amount=80.0, valid=False)
        ++> Order(order_id="A3", amount=300.0, fraud_flagged=True)
        ++> Order(order_id="A4", amount=200.0);
    root spawn OrderAuditor();
}

