"""Test annex for OrderAuditor: skip invalid, halt on fraud."""

import io;
import from contextlib { redirect_stdout }

test "audit prints OK and continues for valid orders" {
    root ++> Order(order_id="B1", amount=100.0)
        ++> Order(order_id="B2", amount=250.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[OK] order B1 amount=100.0 -> continuing" in out, f"missing OK line for B1: {out!r}";
    assert "[OK] order B2 amount=250.0 -> continuing" in out, f"missing OK line for B2: {out!r}";
    assert out.count("[OK]") == 2, f"expected 2 OK lines, got {out!r}";
    assert "[SKIP]" not in out, f"unexpected SKIP in all-valid run: {out!r}";
    assert "[HALT]" not in out, f"unexpected HALT in all-valid run: {out!r}";
}

test "audit skips invalid order but keeps walking" {
    root ++> Order(order_id="C1", amount=50.0)
        ++> Order(order_id="C2", amount=75.0, valid=False)
        ++> Order(order_id="C3", amount=125.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[OK] order C1 amount=50.0 -> continuing" in out, f"missing C1 OK: {out!r}";
    assert "[SKIP] order C2 amount=75.0 -> continuing" in out, f"missing C2 SKIP: {out!r}";
    assert "[OK] order C3 amount=125.0 -> continuing" in out, f"C3 must still be visited after skip: {out!r}";
    assert "[HALT]" not in out, f"no halt expected: {out!r}";
    assert "C2" in out.split("[OK] order C3")[0], f"C2 line must appear before C3: {out!r}";
}

test "audit halts immediately on fraud and never sees later orders" {
    root ++> Order(order_id="D1", amount=10.0)
        ++> Order(order_id="D2", amount=20.0, fraud_flagged=True)
        ++> Order(order_id="D3", amount=30.0)
        ++> Order(order_id="D4", amount=40.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[OK] order D1 amount=10.0 -> continuing" in out, f"D1 should print OK: {out!r}";
    assert "[HALT] order D2 amount=20.0 -> stopping walk" in out, f"fraud must halt: {out!r}";
    assert "D3" not in out, f"D3 must NOT be visited after halt: {out!r}";
    assert "D4" not in out, f"D4 must NOT be visited after halt: {out!r}";
    assert "[SKIP]" not in out, f"no skip expected here: {out!r}";
}

test "first order itself is fraud so nothing else runs" {
    root ++> Order(order_id="E1", amount=999.0, fraud_flagged=True)
        ++> Order(order_id="E2", amount=1.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[HALT] order E1 amount=999.0 -> stopping walk" in out, f"fraud-on-first must halt: {out!r}";
    assert "E2" not in out, f"E2 unreachable when first node is fraud: {out!r}";
    assert "[OK]" not in out and "[SKIP]" not in out, f"only HALT should appear: {out!r}";
}

test "skip followed by halt: invalid is logged, fraud stops, nothing after" {
    root ++> Order(order_id="F1", amount=15.0, valid=False)
        ++> Order(order_id="F2", amount=22.0, fraud_flagged=True)
        ++> Order(order_id="F3", amount=33.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[SKIP] order F1 amount=15.0 -> continuing" in out, f"F1 must be skipped, not stopped: {out!r}";
    assert "[HALT] order F2 amount=22.0 -> stopping walk" in out, f"F2 must halt: {out!r}";
