"""Tests for the weather sweep walker."""

import io;
import from contextlib { redirect_stdout }

test "sweeper reports each station and prints summary" {
    root ++> Station(location="Alpha", celsius=10.0)
        ++> Station(location="Beta", celsius=25.5)
        ++> Station(location="Gamma", celsius=17.3);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        sweeper = WeatherSweep();
        root spawn sweeper;
        readings = sweeper.readings;
        print(f"All readings: {readings}");

        temps = [r[1] for r in readings];
        lo = temps[0];
        for v in temps {
            lo = v if v < lo else lo;
        }
        hi = temps[0];
        for v in temps {
            hi = v if v > hi else hi;
        }
        print(f"Min: {lo} C, Max: {hi} C");
    }
    out = buf.getvalue();

    assert "Alpha: 10.0 C" in out, f"missing Alpha reading: {out}";
    assert "Beta: 25.5 C" in out, f"missing Beta reading: {out}";
    assert "Gamma: 17.3 C" in out, f"missing Gamma reading: {out}";
    assert "All readings:" in out, f"missing All readings line: {out}";
    assert "Min: 10.0 C, Max: 25.5 C" in out, f"missing min/max line: {out}";
}

test "readings list preserves walker traversal order" {
    root ++> Station(location="A", celsius=1.0)
        ++> Station(location="B", celsius=2.0)
        ++> Station(location="C", celsius=3.0);

    sweeper = WeatherSweep();
    root spawn sweeper;

    assert len(sweeper.readings) == 3, f"expected 3 readings, got {len(sweeper.readings)}";
    assert sweeper.readings[0][0] == "A", f"first reading should be A, got {sweeper.readings[0]}";
    assert sweeper.readings[1][0] == "B", f"second reading should be B, got {sweeper.readings[1]}";
    assert sweeper.readings[2][0] == "C", f"third reading should be C, got {sweeper.readings[2]}";
    assert sweeper.readings[0][1] == 1.0, f"first temp should be 1.0, got {sweeper.readings[0][1]}";
    assert sweeper.readings[2][1] == 3.0, f"third temp should be 3.0, got {sweeper.readings[2][1]}";
}

test "walker does not stop and visits every station" {
    a = Station(location="N1", celsius=5.0);
    b = Station(location="N2", celsius=6.0);
    c = Station(location="N3", celsius=7.0);
    root ++> a ++> b ++> c;

    sweeper = WeatherSweep();
    root spawn sweeper;

    stations_visited = {r[0] for r in sweeper.readings};
    assert "N1" in stations_visited, f"N1 not visited: {sweeper.readings}";
    assert "N2" in stations_visited, f"N2 not visited: {sweeper.readings}";
    assert "N3" in stations_visited, f"N3 not visited: {sweeper.readings}";
    assert len(sweeper.readings) == 3, f"expected 3 readings, got {len(sweeper.readings)}";
}

test "min and max computed correctly across all stations" {
    root ++> Station(location="Cold", celsius=-4.5)
        ++> Station(location="Warm", celsius=30.2)
        ++> Station(location="Mid", celsius=12.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        sweeper = WeatherSweep();
        root spawn sweeper;
        readings = sweeper.readings;

        temps = [r[1] for r in readings];
        lo = temps[0];
        for v in temps {
            lo = v if v < lo else lo;
        }
        hi = temps[0];
        for v in temps {
            hi = v if v > hi else hi;
        }
        print(f"Min: {lo} C, Max: {hi} C");
    }
    out = buf.getvalue();

    assert "-4.5" in out, f"min value -4.5 missing from output: {out}";
    assert "30.2" in out, f"max value 30.2 missing from output: {out}";
    assert "Min:" in out and "Max:" in out, f"missing Min/Max labels: {out}";
}

