"""Tests for bug tracker: connection expression returns the freshly created node."""

import io;
import from contextlib { redirect_stdout }

test "connection expression returns the new ticket node inline" {
    root ++> Project(name="API");
    fresh = (root +>:Filed:+> Ticket(title="Null pointer in handler", priority="high"));
    assert fresh is not None, "connect-and-grab must return the new ticket, not None";
    assert fresh.title == "Null pointer in handler", f"title not captured inline, got {fresh.title}";
    assert fresh.priority == "high", f"priority not captured inline, got {fresh.priority}";
}

test "filed edge connects the fresh ticket to the project" {
    root ++> Project(name="Mobile");
    fresh = (root +>:Filed:+> Ticket(title="App freezes on launch", priority="critical"));
    filed_edges = [root ->:Filed:->];
    assert len(filed_edges) == 1, f"expected exactly 1 Filed edge, got {len(filed_edges)}";
    target = filed_edges[0];
    assert target == fresh, "the Filed edge should point at the freshly filed ticket returned by the connect expression";
}

test "multiple connect-and-grab calls each return their own ticket and all are linked" {
    root ++> Project(name="Backend");
    fresh_a = (root +>:Filed:+> Ticket(title="Slow DB query", priority="medium"));
    fresh_b = (root +>:Filed:+> Ticket(title="Missing index", priority="low"));
    fresh_c = (root +>:Filed:+> Ticket(title="Auth token leak", priority="critical"));

    assert fresh_a.title == "Slow DB query", f"a.title={fresh_a.title}";
    assert fresh_b.title == "Missing index", f"b.title={fresh_b.title}";
    assert fresh_c.title == "Auth token leak", f"c.title={fresh_c.title}";

    assert fresh_a.priority == "medium", f"a.priority={fresh_a.priority}";
    assert fresh_b.priority == "low", f"b.priority={fresh_b.priority}";
    assert fresh_c.priority == "critical", f"c.priority={fresh_c.priority}";

    assert fresh_a != fresh_b and fresh_b != fresh_c and fresh_a != fresh_c, "each connect expression must return a distinct ticket instance";

    targets = [root ->:Filed:->];
    assert len(targets) == 3, f"expected 3 Filed edges off root, got {len(targets)}";
    assert fresh_a in targets, "fresh_a must be reachable via a Filed edge from root";
    assert fresh_b in targets, "fresh_b must be reachable via a Filed edge from root";
