"""Test annex for moderation sweep program."""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Test 1: Moderator audits all accounts (member + admin) in traversal order
# ---------------------------------------------------------------------------
test "moderator audits every account in order" {
    root ++> Member(title="Alice", year=2019, join_year=2019, reputation=20);
    root ++> Member(title="Bob", year=2021, join_year=2021, reputation=35);
    root ++> Admin(title="CarolRoot", year=2018, reputation=50, admin_level=2);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Moderator();
    }
    out = buf.getvalue();

    assert "Moderation sweep begins" in out, f"missing start banner: {out}";
    assert "audited Alice" in out, f"missing Alice audit: {out}";
    assert "audited Bob" in out, f"missing Bob audit: {out}";
    assert "audited CarolRoot" in out, f"missing CarolRoot audit: {out}";
    # reputation values printed in the audit line must reflect original state
    assert "rep=20" in out, f"missing Alice rep: {out}";
    assert "rep=35" in out, f"missing Bob rep: {out}";
    assert "rep=50" in out, f"missing CarolRoot rep: {out}";
    # three audit lines expected (one per account)
    audit_lines = [l for l in out.splitlines() if "audited" in l];
    assert len(audit_lines) == 3, f"expected 3 audit lines, got {len(audit_lines)}: {out}";
}

# ---------------------------------------------------------------------------
# Test 2: ReputationBooster only adds +5 to admin reputation, not admin's own audit log
# ---------------------------------------------------------------------------
test "reputation booster adds exactly 5 to admin" {
    member = Member(title="Alice", year=2019, join_year=2019, reputation=20);
    admin = Admin(title="CarolRoot", year=2018, reputation=50, admin_level=2);
    root ++> member;
    root ++> admin;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn ReputationBooster();
    }
    out = buf.getvalue();

    assert "Reputation boost pass begins" in out, f"missing start banner: {out}";
    # Both nodes get the boost ability (Account entry), so both should be boosted.
    # The key spec is the admin gets +5.
    assert "boosted CarolRoot: rep 55" in out, f"admin should be boosted to 55: {out}";
    # Confirm the printed rep matches admin's updated value (50 + 5 = 55)
    assert admin.reputation == 55, f"admin reputation should be 55, got {admin.reputation}";
}

# ---------------------------------------------------------------------------
# Test 3: WelcomeDesk greets every account and carries its desk_name
# ---------------------------------------------------------------------------
test "welcome desk greets every account with its label" {
    root ++> Member(title="Alice", year=2019, join_year=2019, reputation=20);
    root ++> Member(title="Bob", year=2021, join_year=2021, reputation=35);
    root ++> Admin(title="CarolRoot", year=2018, reputation=50, admin_level=2);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn WelcomeDesk(desk_name="Welcome-1");
    }
    out = buf.getvalue();

    assert "Welcome-1 desk is open" in out, f"missing desk banner: {out}";
    assert "hello, Alice!" in out, f"missing Alice greeting: {out}";
    assert "hello, Bob!" in out, f"missing Bob greeting: {out}";
    assert "hello, CarolRoot!" in out, f"missing CarolRoot greeting: {out}";
    # the desk_name field must appear in every greeting
    greeting_lines = [l for l in out.splitlines() if "hello," in l];
    assert len(greeting_lines) == 3, f"expected 3 greetings, got {len(greeting_lines)}: {out}";
    for g in greeting_lines {
        assert "Welcome-1" in g, f"desk_name missing from greeting: {g}";
    }
}

# ---------------------------------------------------------------------------
# Test 4: Bot walker passes through accounts (entry on Account fires for bots)
# ---------------------------------------------------------------------------
test "bot walker passes through every account" {
    root ++> Member(title="Alice", year=2019, join_year=2019, reputation=20);
    root ++> Admin(title="CarolRoot", year=2018, reputation=50, admin_level=2);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Bot(bot_id="Scout-1");
    }
    out = buf.getvalue();

    assert "bot Scout-1 enters the lobby" in out, f"missing bot lobby banner: {out}";
    assert "passing through Alice" in out, f"missing Alice pass: {out}";
    assert "passing through CarolRoot" in out, f"missing CarolRoot pass: {out}";
    pass_lines = [l for l in out.splitlines() if "passing through" in l];
    assert len(pass_lines) == 2, f"expected 2 pass-through lines, got {len(pass_lines)}: {out}";
}

# ---------------------------------------------------------------------------
# Test 5: Graph shape - accounts connected under root
# ---------------------------------------------------------------------------
test "graph links root to three account nodes" {
    m1 = Member(title="Alice", year=2019, join_year=2019, reputation=20);
    m2 = Member(title="Bob", year=2021, join_year=2021, reputation=35);
    a1 = Admin(title="CarolRoot", year=2018, reputation=50, admin_level=2);
    root ++> m1;
    root ++> m2;
    root ++> a1;

    children = [root -->];
    assert len(children) == 3, f"root should have 3 children, got {len(children)}";

    titles = sorted([c.title for c in children]);
    assert titles == ["Alice", "Bob", "CarolRoot"], f"unexpected titles: {titles}";

