test "services both device kinds and resets idle counters" {
    grove = Grove(name="Test Grove");
    pump = Pump(label="Pump-A", idle_hours=14);
    sprinkler = Sprinkler(label="Sprink-A", idle_hours=6);

    root ++> grove;
    grove ++> pump;
    grove ++> sprinkler;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Crew();
    }
    out = buf.getvalue();

    assert res.serviced == 2, f"expected 2 serviced devices, got {res.serviced}";
    assert pump.idle_hours == 0, f"pump was not reset: {pump.idle_hours}";
    assert sprinkler.idle_hours == 0, f"sprinkler was not reset: {sprinkler}";
    assert "[Pump] Pump-A idled 14h -> serviced" in out, f"missing pump log: {out}";
    assert "[Sprinkler] Sprink-A idled 6h -> serviced" in out, f"missing sprinkler log: {out}";
    assert "(total: 2)" in out, f"missing final service count: {out}";
}

test "walks multiple groves and counts every device" {
    north = Grove(name="North");
    south = Grove(name="South");
    pump_a = Pump(label="Pump-A", idle_hours=14);
    sprinkler_a = Sprinkler(label="Sprink-A", idle_hours=6);
    sprinkler_b = Sprinkler(label="Sprink-B", idle_hours=22);
    pump_b = Pump(label="Pump-B", idle_hours=3);
    sprinkler_c = Sprinkler(label="Sprink-C", idle_hours=11);

    root ++> north ++> south;
    north ++> pump_a;
    north ++> sprinkler_a;
    south ++> sprinkler_b;
    south ++> pump_b;
    south ++> sprinkler_c;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Crew();
    }
    out = buf.getvalue();

    assert res.serviced == 5, f"expected 5 serviced devices, got {res.serviced}";
    assert pump_a.idle_hours == 0, f"Pump-A was not reset: {pump_a.idle_hours}";
    assert sprinkler_a.idle_hours == 0, f"Sprink-A was not reset: {sprinkler_a.idle_hours}";
    assert sprinkler_b.idle_hours == 0, f"Sprink-B was not reset: {sprinkler_b.idle_hours}";
    assert pump_b.idle_hours == 0, f"Pump-B was not reset: {pump_b.idle_hours}";
    assert sprinkler_c.idle_hours == 0, f"Sprink-C was not reset: {sprinkler_c.idle_hours}";
    assert "[Pump] Pump-B idled 3h -> serviced" in out, f"missing Pump-B log: {out}";
    assert "[Sprinkler] Sprink-C idled 11h -> serviced" in out, f"missing Sprink-C log: {out}";
    assert "(total: 5)" in out, f"missing total of five: {out}";
}

test "reports zero serviced devices for an empty grove" {
    grove = Grove(name="Empty");
    root ++> grove;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Crew();
    }

    assert res.serviced == 0, f"expected zero serviced devices, got {res.serviced}";
}

