fixed.code:
"""Kitchen line health inspection: check station temperatures and log every visit.

A single inspector walker runs two checks at every station: one flags any
station whose temperature is above 40 C as a violation, the other logs
every visit regardless of temperature. Both abilities fire at every
station using union triggers over the shared ``celsius`` field.
"""

node Station {
    has name: str = "";
    has celsius: float = 0.0;
    has kind: str = "";
}

walker Inspector {
    has station_count: int = 0;
    has violations: int = 0;

    can start with Root entry {
        print("Kitchen inspection starting...");
        visit [-->];
    }

    # Temperature check: flags anything above 40 C as a violation.
    # Union trigger so it fires on every station subtype equally.
    can check_temp with Station | Station entry {
        if here.celsius > 40.0 {
            self.violations += 1;
            print(f"  [VIOLATION] {here.kind} '{here.name}' at {here.celsius}C exceeds 40C limit");
        } else {
            print(f"  [ok] {here.kind} '{here.name}' at {here.celsius}C within limit");
        }
    }

    # Visit log: runs at every station, independent of temperature.
    can log_visit with Station | Station entry {
        self.station_count += 1;
        print(f"  -> visited station #{self.station_count}: {here.kind} '{here.name}'");
        visit [-->];
    }
}

with entry {
    grill = Station(name="Salamander", celsius=82.0, kind="grill");
    fryer = Station(name="Deep Fryer", celsius=175.0, kind="fryer");
    cold_prep = Station(name="Salad Bar", celsius=4.5, kind="cold-prep");
    pastry = Station(name="Chocolate Work", celsius=22.0, kind="cold-prep");

    root ++> grill ++> fryer ++> cold_prep ++> pastry;

    inspector = Inspector();
    root spawn inspector;

    print(f"\nInspection complete: visited {inspector.station_count} stations, "
          f"flagged {inspector.violations} violations");
}

