"""Tests for the kitchen line health inspection walker."""

import io;
import from contextlib { redirect_stdout }

test "flag violations above 40C and log every visit" {
    # Build the kitchen line: grill (hot) -> fryer (hot) -> cold_prep (ok) -> pastry (ok)
    grill = Station(name="Salamander", celsius=82.0, kind="grill");
    fryer = Station(name="Deep Fryer", celsius=175.0, kind="fryer");
    cold_prep = Station(name="Salad Bar", celsius=4.5, kind="cold-prep");
    pastry = Station(name="Chocolate Work", celsius=22.0, kind="cold-prep");
    root ++> grill ++> fryer ++> cold_prep ++> pastry;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Inspector();
    }
    out = buf.getvalue();

    # Both checks must fire at EVERY station -> station_count == 4
    assert res.station_count == 4, f"expected 4 visits, got {res.station_count}";

    # Exactly 2 stations are above 40C (grill 82, fryer 175); cold_prep 4.5 and pastry 22 are fine
    assert res.violations == 2, f"expected 2 violations, got {res.violations}";

    # Violation markers for the two hot stations
    assert "[VIOLATION]" in out, f"missing VIOLATION marker: {out}";
    assert "Salamander" in out, f"grill name missing from output: {out}";
    assert "Deep Fryer" in out, f"fryer name missing from output: {out}";

    # Ok marker for the cold stations
    assert "[ok]" in out, f"missing ok marker: {out}";
    assert "Salad Bar" in out, f"cold_prep name missing: {out}";
    assert "Chocolate Work" in out, f"pastry name missing: {out}";

    # Visit log must show 4 separate entries
    assert out.count("-> visited station #") == 4, f"expected 4 visit logs, got {out.count('-> visited station #')}";
}

test "all-cold line produces zero violations but still logs every station" {
    cold_a = Station(name="Salad Bar A", celsius=3.0, kind="cold-prep");
    cold_b = Station(name="Salad Bar B", celsius=5.5, kind="cold-prep");
    cold_c = Station(name="Dessert Chiller", celsius=18.0, kind="cold-prep");
    root ++> cold_a ++> cold_b ++> cold_c;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Inspector();
    }
    out = buf.getvalue();

    # Both checks still run on every cold station
    assert res.station_count == 3, f"expected 3 visits, got {res.station_count}";
    # Nothing exceeds 40C
    assert res.violations == 0, f"expected 0 violations, got {res.violations}";
    # No violation markers in a clean cold line
    assert "[VIOLATION]" not in out, f"unexpected VIOLATION in clean cold line: {out}";
    # Every station still got an ok + visit-log line
    assert out.count("[ok]") == 3, f"expected 3 ok markers, got {out.count('[ok]')}";
    assert out.count("-> visited station #") == 3, f"expected 3 visit logs";
}

test "boundary at 40C is not flagged, just above is flagged" {
    # Exactly 40.0 must NOT count as a violation; 40.1 must.
    boundary = Station(name="Hot Hold A", celsius=40.0, kind="grill");
    just_over = Station(name="Hot Hold B", celsius=40.1, kind="grill");
    root ++> boundary ++> just_over;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Inspector();
    }
    out = buf.getvalue();

    assert res.station_count == 2, f"expected 2 visits, got {res.station_count}";
    # Only the >40.0 station is a violation
    assert res.violations == 1, f"expected 1 violation, got {res.violations}";
    assert "[VIOLATION]" in out and "Hot Hold B" in out, f"missing just-over violation: {out}";
    # The 40.0 station must show as ok
    assert "[ok] Hot Hold A" in out or "[ok]" in out, f"boundary station should be ok: {out}";
}

test "single hot station still logs visit and flags violation" {
    single = Station(name="Wok Range", celsius=200.0, kind="grill");
    root ++> single;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Inspector();
    }
    out = buf.getvalue();

    assert res.station_count == 1, f"expected 1 visit, got {res.station_count}";
    assert res.violations == 1, f"expected 1 violation, got {res.violations}";
    assert "[VIOLATION]" in out and "Wok Range" in out, f"violation missing: {out}";
    assert "-> visited station #1: grill 'Wok Range'" in out, f"visit log missing: {out}";
}

