"""Test annex for the restaurant kitchen line health inspection program."""

import io;
import from contextlib { redirect_stdout }


test "all stations visited and logged in order" {
    root ++> Station(name="Charbroiler", temperature=180.0)
        ++> Station(name="Deep Fryer", temperature=175.0)
        ++> Station(name="Salad Station", temperature=4.0)
        ++> Station(name="Dessert Display", temperature=22.0);

    inspector = Inspector();
    root spawn inspector;

    assert inspector.station_count == 4, f"expected 4 stations visited, got {inspector.station_count}";
    assert len(inspector.visited_stations) == 4, f"expected 4 log entries, got {len(inspector.visited_stations)}";

    expected_order = [
        "Charbroiler (180.0 C)",
        "Deep Fryer (175.0 C)",
        "Salad Station (4.0 C)",
        "Dessert Display (22.0 C)",
    ];
    assert inspector.visited_stations == expected_order, f"visit order mismatch: {inspector.visited_stations}";
}


test "high temperature stations flagged as violations" {
    root ++> Station(name="Charbroiler", temperature=180.0)
        ++> Station(name="Deep Fryer", temperature=175.0)
        ++> Station(name="Salad Station", temperature=4.0);

    inspector = Inspector();
    root spawn inspector;

    assert len(inspector.violations) == 2, f"expected 2 violations (grill + fryer), got {len(inspector.violations)}";

    violation_text = " ".join(inspector.violations);
    assert "Charbroiler" in violation_text, f"Charbroiler should be flagged: {inspector.violations}";
    assert "Deep Fryer" in violation_text, f"Deep Fryer should be flagged: {inspector.violations}";
    assert "Salad Station" not in violation_text, f"Salad Station must not be flagged: {inspector.violations}";
}


test "stations at or below 40 C are not violations" {
    root ++> Station(name="Cold Prep", temperature=3.5)
        ++> Station(name="Dessert Display", temperature=22.0)
        ++> Station(name="Walk-in Cooler", temperature=2.0)
        ++> Station(name="Boundary Station", temperature=40.0);

    inspector = Inspector();
    root spawn inspector;

    assert len(inspector.violations) == 0, f"no violations expected, got {inspector.violations}";
    assert inspector.station_count == 4, f"all 4 stations still visited, got {inspector.station_count}";
    assert len(inspector.visited_stations) == 4, f"all 4 stations logged, got {len(inspector.visited_stations)}";

    for label in inspector.visited_stations {
        assert "VIOLATION" not in label, f"log entry should not contain VIOLATION: {label}";
    }
}


test "both checks run at every station regardless of type" {
    root ++> Station(name="Grill A", temperature=200.0)
        ++> Station(name="Cold B", temperature=1.0)
        ++> Station(name="Grill C", temperature=90.0);

    inspector = Inspector();
    root spawn inspector;

    assert inspector.station_count == 3, f"visit count must equal station count: {inspector.station_count}";
    assert len(inspector.visited_stations) == 3, f"every station must be logged: {len(inspector.visited_stations)}";
    assert len(inspector.violations) == 2, f"both hot stations must be flagged: {len(inspector.violations)}";

    for i in range(3) {
