    can pick with Attraction entry {
        if here.stars >= self.threshold {
            self.chosen.append(here.name);
            print(f"  picked: {here.name} ({here.stars}*)");
        } else {
            print(f"  skipped: {here.name} ({here.stars}* < {self.threshold})");
        }
        visit [->:Connects:->];
    }

    can skip with Hotel entry {
        print(f"  (hotel ignored: {here.name})");
        visit [->:Connects:->];
    }

    can finish with Station | Attraction | Hotel entry {
        if len(self.chosen) > 0 {
            print(f"{self.station_name} itinerary: {self.chosen}");
        } else {
            print(f"{self.station_name} itinerary: (no attractions qualified)");
        }
        disengage;
    }
}

