"""Build dependency audit: count total build minutes across a DAG of tasks,
ensuring each task is counted exactly once even when the graph contains
diamonds (tasks reachable by multiple paths)."""

node Task {
    has name: str = "";
    has minutes: int = 0;
}

walker Auditor {
    # Per-walker duplicate guard. Walkers in jac 0.36 do not deduplicate
    # visits on diamond-shaped graphs, so we track visited tasks ourselves
    # and refuse to recurse from already-seen nodes. We also keep a small
    # lookup of minutes so the final summary doesn't have to re-walk.
    has seen: list = [];
    has minutes_map: dict = {};

    can start with Root entry {
        visit [-->] else { report self.totals(); }
    }

    can audit with Task entry {
        if here.name not in self.seen {
            self.seen.append(here.name);
            self.minutes_map[here.name] = here.minutes;
            print(f"[{here.minutes}m] {here.name}");
            visit [-->] else { report self.totals(); }
        }
        # else: already audited — do NOT recurse, do NOT count again.
    }

    def totals() -> dict {
        total = 0;
        for nm in self.seen {
            total += self.minutes_map.get(nm, 0);
        }
        return {"minutes": total, "count": len(self.seen), "tasks": list(self.seen)};
    }
}

