            print(f"CYCLE DETECTED: {' -> '.join(self.found)}");
            disengage;
        }
        # Already fully explored off-trail: nothing new to learn here.
        if here.build_order == -1 {
            visit [<--];
        }
        # Otherwise: mark and descend into dependencies.
        self.on_trail[here.name] = True;
        self.trail = self.trail + [here.name];
        # Step into every dependency; the engine enqueues them.
        visit [here ->:DependsOn:->];
        # Backtrack: pop this module from the trail.
        self.trail = self.trail[:-1];
        self.on_trail[here.name] = False;
        # Mark fully explored so siblings don't re-descend.
        here.build_order = -1;
        visit [<--];
    }
}

walker BuildOrder {
    has order: list = [];
    has visiting: set = set();

    can start with Root entry {
        visit [-->];
    }

    can order_modules with Module entry {
        if here.name in self.visiting {
            # Defensive: CycleHunter should have caught this first.
            print(f"  cycle touched BuildOrder: {here.name}");
            visit [<--];
        }
        if here.build_order > 0 {
            visit [<--];
        }
        self.visiting.add(here.name);
        visit [here ->:DependsOn:->];
        self.visiting.discard(here.name);
        here.build_order = len(self.order) + 1;
        self.order = self.order + [here.name];
        visit [<--];
    }
}

with entry {
    app = Module(name="app", build_order=0);
    ui = Module(name="ui", build_order=0);
    core = Module(name="core", build_order=0);
    utils = Module(name="utils", build_order=0);
    net = Module(name="net", build_order=0);

    # Build the graph: app -> ui -> core -> utils, and a deliberate
    # cycle net -> ui -> net (net depends on ui, ui depends on net).
    root ++> app ++> ui ++> core ++> utils ++> net;
    app +>:DependsOn(reason="render"):+> ui;
    ui +>:DependsOn(reason="data"):+> core;
    core +>:DependsOn(reason="helpers"):+> utils;
    utils +>:DependsOn(reason="http"):+> net;
    # The cycle: ui <-> net.
    net +>:DependsOn(reason="events"):+> ui;

    print("=== CycleHunter ===");
    root spawn CycleHunter();
    if CycleHunter.found if hasattr(CycleHunter, "found") else False {
        # No-op; CycleHunter is the walker instance the spawn just used.
    }

    # Re-run a fresh hunter to be explicit about the cycle report path.
    print("\n=== CycleHunter (fresh, typed-edge traversal) ===");
    hunter = CycleHunter();
    root spawn hunter;
    if hunter.found {
        print(f"Build aborted: cycle {' -> '.join(hunter.found)}");
    } else {
        print("No cycles found.");
    }

    # Show that BuildOrder refuses to topologically sort the cyclic graph.
    print("\n=== BuildOrder (would topologically sort, but graph is cyclic) ===");
    builder = BuildOrder();
    root spawn builder;
    if builder.order {
        print(f"Order: {builder.order}");
    } else {
        print("No ordering produced (graph contained a cycle).");
    }
}

