    has name: str = "";
}

edge DependsOn {
    has reason: str = "import";
}

walker CycleHunter {
    has trail: list = [];
    has on_trail: set = set();
    has found: list = [];

    can start with Root entry {
        # Seed: visit every top-level module, then follow typed edges.
        visit [-->];
