    app +>:DependsOn:+> ui;
    ui +>:DependsOn:+> core;
    core +>:DependsOn:+> utils;
    utils +>:DependsOn:+> net;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        hunter = CycleHunter();
        root spawn hunter;
    }
    out = buf.getvalue();

    # No cycle should be reported.
    assert "CYCLE DETECTED" not in out, f"unexpected cycle output: {out}";
    assert len(hunter.found) == 0, f"found should be empty, got {hunter.found}";
}

test "self-loop on a module is detected as a cycle" {
    # A module that depends on itself is the simplest cycle.
    solo = Module(name="solo");
    root ++> solo;
    solo +>:DependsOn:+> solo;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        hunter = CycleHunter();
        root spawn hunter;
    }
    out = buf.getvalue();

    assert "CYCLE DETECTED" in out, f"missing cycle marker: {out}";
    # The reported cycle should mention the solo node and form a path.
    assert len(hunter.found) > 0, "found list should be non-empty";
    assert "solo" in hunter.found, f"solo should appear in cycle: {hunter.found}";
    # For a self-loop, the path is solo -> solo.
    assert hunter.found[0] == hunter.found[-1], f"cycle endpoints should match: {hunter.found}";
}

test "two-node cycle alpha <-> beta is detected" {
    alpha = Module(name="alpha");
    beta = Module(name="beta");
    root ++> alpha ++> beta;
    alpha +>:DependsOn:+> beta;
    beta +>:DependsOn:+> alpha;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        hunter = CycleHunter();
        root spawn hunter;
    }
    out = buf.getvalue();

    assert "CYCLE DETECTED" in out, f"missing cycle marker: {out}";
    assert len(hunter.found) > 0, "found should be populated";
    # Both endpoints of the back-edge must appear in the cycle.
    assert "alpha" in hunter.found, f"alpha missing from cycle: {hunter.found}";
    assert "beta" in hunter.found, f"beta missing from cycle: {hunter.found}";
    # Cycle must start and end at the same node.
    assert hunter.found[0] == hunter.found[-1], f"cycle should close: {hunter.found}";
}

