"""Tests for Reports access model:
- Published reports return READ from access_hook.
- Unpublished reports return None from access_hook.
- Publisher walker flips the published flag and clears the grant.
- Auditor traversal prints READ/CLOSED labels appropriately."""

import io;
import from contextlib { redirect_stdout }

test "unpublished reports return None from access_hook" {
    q1 = Report(title="Q1 Earnings", year=2024);
    draft = Report(title="Acquisition Memo", year=2025, grant="board-only");
    root ++> q1 ++> draft;

    assert q1.access_hook() is None, f"q1 should be closed, got {q1.access_hook()}";
    assert draft.access_hook() is None, f"draft should be closed, got {draft.access_hook()}";
}

test "published report returns READ from access_hook" {
    r = Report(title="Launch Plan", year=2026, published=True);
    root ++> r;

    assert r.access_hook() == "READ", f"expected READ, got {r.access_hook()}";
    assert r.published is True, "published flag should be True";
}

test "publisher walker flips flag and drops grant on matching report" {
    draft = Report(title="Acquisition Memo", year=2025, grant="board-only");
    q1 = Report(title="Q1 Earnings", year=2024);
    root ++> q1 ++> draft;

    assert draft.published is False, "pre: draft should be unpublished";
    assert draft.grant == "board-only", f"pre: grant should be 'board-only', got '{draft.grant}'";

    root spawn Publisher(report_title="Acquisition Memo");

    assert draft.published is True, "post: Publisher should have flipped the flag";
    assert draft.grant == "", f"post: grant should be cleared, got '{draft.grant}'";
    assert draft.access_hook() == "READ", "post: hook should now return READ";
}

test "publisher walker leaves non-matching reports untouched" {
    q1 = Report(title="Q1 Earnings", year=2024, grant="owner-only");
    draft = Report(title="Acquisition Memo", year=2025, grant="board-only");
    root ++> q1 ++> draft;

    root spawn Publisher(report_title="Acquisition Memo");

    # q1 must be untouched: still unpublished, grant intact, hook returns None.
    assert q1.published is False, "q1 should remain unpublished";
    assert q1.grant == "owner-only", f"q1 grant must be intact, got '{q1.grant}'";
    assert q1.access_hook() is None, f"q1 hook should remain None, got {q1.access_hook()}";
}

test "auditor traversal labels reports READ or CLOSED based on published flag" {
    q1 = Report(title="Q1 Earnings", year=2024);
    q2 = Report(title="Q2 Earnings", year=2024, grant="owner-only");
    draft = Report(title="Acquisition Memo", year=2025, grant="board-only");
    root ++> q1 ++> q2 ++> draft;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
    out = buf.getvalue();

    # All three are unpublished at this point -> all CLOSED, grants visible.
    assert "[CLOSED] Q1 Earnings" in out, f"missing CLOSED Q1 line: {out}";
    assert "[CLOSED] Q2 Earnings (2024) grant=owner-only" in out, f"missing CLOSED Q2 with grant: {out}";
    assert "[CLOSED] Acquisition Memo (2025) grant=board-only" in out, f"missing CLOSED draft with grant: {out}";
    assert "[READ]" not in out, f"no READ expected before publishing: {out}";

    # Now publish the draft and re-audit; the draft should switch to READ with no grant suffix.
    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        root spawn Publisher(report_title="Acquisition Memo");
    }
    buf3 = io.StringIO();
    with redirect_stdout(buf3) {
        root spawn Auditor();
    }
    out2 = buf3.getvalue();

    assert "[READ] Acquisition Memo" in out2, f"draft should be READ after publish: {out2}";
    assert "grant=" not in out2.split("[READ]")[1].split("\n")[0], f"READ line should omit grant: {out2}";
    assert "[CLOSED] Q1 Earnings" in out2, f"q1 should remain CLOSED: {out2}";
    assert "[CLOSED] Q2 Earnings (2024) grant=owner-only" in out2, f"q2 should still show its grant: {out2}";
}

