import io;
import from contextlib { redirect_stdout }

test "trail has a four-waypoint chain from root to summit" {
    trailhead = Waypoint(label="Trailhead", elevation=1200);
    meadow = Waypoint(label="Wildflower Meadow", elevation=1450);
    ridge = Waypoint(label="Ridge Overlook", elevation=1800);
    summit = Waypoint(label="Summit", elevation=2200);
    root ++> trailhead ++> meadow ++> ridge ++> summit;

    # Root has exactly one outgoing edge to the trailhead
    assert len([root-->]) == 1, f"expected 1 outgoing edge from root, got {len([root-->])}";

    # Walk the chain and collect all reachable waypoints in order
    visited = [root-->][0];
    chain = [visited];
    while len([visited-->]) > 0 {
        visited = [visited-->][0];
        chain = chain + [visited];
    }

    assert len(chain) == 4, f"expected 4 waypoints in the chain, got {len(chain)}";
    assert chain[0].label == "Trailhead", f"first waypoint should be Trailhead, got {chain[0].label}";
    assert chain[1].label == "Wildflower Meadow", f"second waypoint should be Wildflower Meadow, got {chain[1].label}";
    assert chain[2].label == "Ridge Overlook", f"third waypoint should be Ridge Overlook, got {chain[2].label}";
    assert chain[3].label == "Summit", f"fourth waypoint should be Summit, got {chain[3].label}";

    # Summit has no outgoing edges (end of trail)
    assert len([chain[3]-->]) == 0, f"summit should have no outgoing edges, got {len([chain[3]-->])}";
}

test "hiker visits every waypoint and prints each stop number" {
    trailhead = Waypoint(label="Trailhead", elevation=1200);
    meadow = Waypoint(label="Wildflower Meadow", elevation=1450);
    ridge = Waypoint(label="Ridge Overlook", elevation=1800);
    summit = Waypoint(label="Summit", elevation=2200);
    root ++> trailhead ++> meadow ++> ridge ++> summit;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker(goal=4);
    }
    out = buf.getvalue();

    # The walker increments stop_count once per Waypoint entry,
    # so after traversing the full chain it must have counted all 4.
    assert res.stop_count == 4, f"expected stop_count=4 after visiting all waypoints, got {res.stop_count}";

    # Each stop line should be printed, in order, with labels and elevations.
    assert "stop #1 (Trailhead) reached at 1200m" in out, f"missing first stop line: {out}";
    assert "stop #2 (Wildflower Meadow) reached at 1450m" in out, f"missing second stop line: {out}";
    assert "stop #3 (Ridge Overlook) reached at 1800m" in out, f"missing third stop line: {out}";
    assert "stop #4 (Summit) reached at 2200m" in out, f"missing fourth stop line: {out}";

    # The intro line from the Root entry ability must fire first.
    assert out.startswith("Hiker sets off from the trailhead..."), f"missing intro line at start of output: {out}";
}

test "completion line fires only once stop_count reaches goal" {
    trailhead = Waypoint(label="Trailhead", elevation=1200);
    meadow = Waypoint(label="Wildflower Meadow", elevation=1450);
    ridge = Waypoint(label="Ridge Overlook", elevation=1800);
    summit = Waypoint(label="Summit", elevation=2200);
    root ++> trailhead ++> meadow ++> ridge ++> summit;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker(goal=4);
    }
    out = buf.getvalue();

    # Completion line must appear exactly once and after all stops are printed.
    assert "Trail complete: summit achieved!" in out, f"missing completion line: {out}";
    assert out.count("Trail complete: summit achieved!") == 1, f"completion line should fire exactly once, got {out.count('Trail complete: summit achieved!')}";
    assert out.index("Trail complete: summit achieved!") > out.index("stop #4"), f"completion should come after the last stop: {out}";
}

test "hiker with default goal=3 disengages after the third waypoint" {
    # With the default goal of 3, the walker should disengage at stop #3
    # (the Ridge Overlook) and never visit the summit.
    trailhead = Waypoint(label="Trailhead", elevation=1200);
    meadow = Waypoint(label="Wildflower Meadow", elevation=1450);
    ridge = Waypoint(label="Ridge Overlook", elevation=1800);
    summit = Waypoint(label="Summit", elevation=2200);
    root ++> trailhead ++> meadow ++> ridge ++> summit;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    # stop_count should be 3 — the walker disengaged before reaching the summit.
    assert res.stop_count == 3, f"expected stop_count=3 with default goal, got {res.stop_count}";

    # Three stop lines, no fourth.
    assert "stop #1 (Trailhead) reached at 1200m" in out, f"missing stop #1: {out}";
    assert "stop #2 (Wildflower Meadow) reached at 1450m" in out, f"missing stop #2: {out}";
    assert "stop #3 (Ridge Overlook) reached at 1800m" in out, f"missing stop #3: {out}";
    assert "stop #4" not in out, f"should not have printed stop #4 with default goal: {out}";
    assert "Summit" not in out, f"should not have reached summit with default goal: {out}";

    # Completion line still fires, just earlier.
    assert "Trail complete: summit achieved!" in out, f"missing completion line: {out}";
}

