gives shots to those who need one, and reports totals on itself."""

node Pet {
    has name: str = "";
    has species: str = "";
    has needs_vaccine: bool = False;
}

walker Vet {
    has patients: list[str] = [];
    has shots_given: int = 0;

    can start with Root entry {
        print(f"Vet beginning round");
        visit [-->] else { disengage; }
    }

    can examine with Pet entry {
        self.patients.append(here.name);
        if here.needs_vaccine {
            self.shots_given += 1;
            print(f"  Vaccinated {here.name} the {here.species}");
        } else {
            print(f"  {here.name} the {here.species} is up to date");
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    root ++> Pet(name="Mochi", species="cat", needs_vaccine=True)
        ++> Pet(name="Rex", species="dog", needs_vaccine=False)
        ++> Pet(name="Bella", species="rabbit", needs_vaccine=True)
        ++> Pet(name="Goldie", species="fish", needs_vaccine=False);

    vet = Vet();
    root spawn vet;

    print(f"\nRound complete.");
    print(f"Patients seen ({len(vet.patients)}): {vet.patients}");
    print(f"Shots given: {vet.shots_given}");
}

