"""Tests for the vet-clinic round walker behavior."""

import io;
import from contextlib { redirect_stdout }


def make_chain {
    root ++> Pet(name="Mochi", species="cat", needs_vaccine=True)
        ++> Pet(name="Rex", species="dog", needs_vaccine=False)
        ++> Pet(name="Bella", species="rabbit", needs_vaccine=True)
        ++> Pet(name="Goldie", species="fish", needs_vaccine=False);
}


test "vet visits every pet in the chain" {
    make_chain();
    buf = io.StringIO();
    res = Vet();
    with redirect_stdout(buf) {
        root spawn res;
    }
    assert len(res.patients) == 4, f"expected 4 patients, got {len(res.patients)}";
    assert "Mochi" in res.patients, f"Mochi missing from {res.patients}";
    assert "Rex" in res.patients, f"Rex missing from {res.patients}";
    assert "Bella" in res.patients, f"Bella missing from {res.patients}";
    assert "Goldie" in res.patients, f"Goldie missing from {res.patients}";
}


test "vet counts only pets that actually need a vaccine" {
    make_chain();
    buf = io.StringIO();
    res = Vet();
    with redirect_stdout(buf) {
        root spawn res;
    }
    # Mochi and Bella need vaccines; Rex and Goldie do not.
    assert res.shots_given == 2, f"expected 2 shots, got {res.shots_given}";
}


test "vet walker exposes patients and shots after the round" {
    make_chain();
    buf = io.StringIO();
    res = Vet();
    with redirect_stdout(buf) {
        root spawn res;
    }
    # Reading the totals straight off the spawned walker instance.
    assert len(res.patients) == res.shots_given + 2, f"unexpected totals: patients={res.patients}, shots={res.shots_given}";
    assert isinstance(res.patients, list), f"patients should be a list, got {type(res.patients)}";
    assert isinstance(res.shots_given, int), f"shots_given should be an int, got {type(res.shots_given)}";
}


test "vet prints a vaccination line for each pet that needs one" {
    make_chain();
    buf = io.StringIO();
    res = Vet();
    with redirect_stdout(buf) {
        root spawn res;
    }
    out = buf.getvalue();
    assert "Vaccinated Mochi the cat" in out, f"missing Mochi vaccine line: {out}";
    assert "Vaccinated Bella the rabbit" in out, f"missing Bella vaccine line: {out}";
    # Pets that don't need a vaccine should get the "up to date" line.
    assert "Rex the dog is up to date" in out, f"missing Rex up-to-date line: {out}";
    assert "Goldie the fish is up to date" in out, f"missing Goldie up-to-date line: {out}";
    # The walker's opening banner should appear.
    assert "Vet beginning round" in out, f"missing opening banner: {out}";
}


test "vet with no pets disengages without counting anything" {
    # No pets attached to root at all.
    buf = io.StringIO();
    res = Vet();
    with redirect_stdout(buf) {
        root spawn res;
    }
    out = buf.getvalue();
    assert len(res.patients) == 0, f"expected 0 patients, got {len(res.patients)}";
    assert res.shots_given == 0, f"expected 0 shots, got {res.shots_given}";
    assert "Vet beginning round" in out, f"opening banner should still print: {out}";
}

