    # Each floor's stop appears once, in spawn traversal order.
    assert out.count("Stop 1") == 1, f"floor 1 stop count: {out!r}";
    assert out.count("Stop 2") == 1, f"floor 2 stop count: {out!r}";
    assert out.count("Stop 3") == 1, f"floor 3 stop count: {out!r}";
    assert out.index("Stop 1") < out.index("Stop 2") < out.index("Stop 3"), f"stops not in order: {out!r}";

    # Graph shape: root has one direct child; total reachable nodes is 4.
    assert len([root-->]) == 1, f"root should have exactly one direct child, got {len([root-->])}";
    reachable = [root --> --> -->];
    assert f1 in [root-->], "f1 not directly linked from root";
    assert f2 in [f1-->], "f2 not linked from f1";
    assert f3 in [f2-->], "f3 not linked from f2";
}

