fixed.jac_tests:
"""Tests for the office tower tour walker."""

import io;
import from contextlib { redirect_stdout }

# Helper: build a fresh tower of 5 floors and run the tour.
def build_and_tour(tour_name: str = "Skyline Office Tower Tour") {
    root ++> Floor(number=1, department="Lobby & Reception")
        ++> Floor(number=2, department="Human Resources")
        ++> Floor(number=3, department="Engineering")
        ++> Floor(number=4, department="Executive Suites")
        ++> Floor(number=5, department="Rooftop Cafe");
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn TourGuide(tour_name=tour_name);
    }
    return buf.getvalue();
}

test "tour greeting announces the tour name at root" {
    out = build_and_tour(tour_name="Skyline Office Tower Tour");
    expected_greeting = "Welcome to the Skyline Office Tower Tour!";
    assert expected_greeting in out, f"missing greeting line in output: {out!r}";
    greeting_idx = out.index(expected_greeting);
    # First announcement should appear after the greeting.
    first_stop_idx = out.index("Stop 1:");
    assert greeting_idx < first_stop_idx, (
        f"greeting should come before first stop; greeting_idx={greeting_idx}, stop_idx={first_stop_idx}"
    );
}

test "every floor announces its own stop with number and department" {
    out = build_and_tour();
    expected_stops = [
        "Stop 1: Lobby & Reception",
        "Stop 2: Human Resources",
        "Stop 3: Engineering",
        "Stop 4: Executive Suites",
        "Stop 5: Rooftop Cafe",
    ];
    for stop_line in expected_stops {
        assert stop_line in out, f"missing stop line {stop_line!r} in output: {out!r}";
    }
}

test "tower graph is a chain of 5 floors off root" {
    root ++> Floor(number=1, department="Lobby & Reception")
        ++> Floor(number=2, department="Human Resources")
        ++> Floor(number=3, department="Engineering")
        ++> Floor(number=4, department="Executive Suites")
        ++> Floor(number=5, department="Rooftop Cafe");
    # Chain: root has exactly one direct child.
    assert len([root-->]) == 1, f"root should have exactly one direct child, got {len([root-->])}";
    # Walk down the chain and verify the 5 floors in order.
    current = [root-->][0];
    seen_numbers = [];
    seen_departments = [];
    steps = 0;
    while current is not None and steps < 20 {
        assert isinstance(current, Floor), f"expected Floor node, got {type(current)}";
        seen_numbers.append(current.number);
        seen_departments.append(current.department);
        steps += 1;
        children = [current-->];
        if len(children) == 0 {
            current = None;
        } else {
            assert len(children) == 1, (
                f"each floor should have at most one next floor; floor {current.number} had {len(children)}"
            );
            current = children[0];
        }
    }
    assert seen_numbers == [1, 2, 3, 4, 5], f"unexpected floor numbers: {seen_numbers}";
    assert seen_departments == [
        "Lobby & Reception",
        "Human Resources",
        "Engineering",
        "Executive Suites",
        "Rooftop Cafe",
    ], f"unexpected departments: {seen_departments}";
}

test "tour stops appear in order from floor 1 up to floor 5" {
    out = build_and_tour();
    # Greeting must precede stop 1.
    assert out.index("Welcome to") < out.index("Stop 1:"), "greeting must precede first stop";
    # Each stop must appear before the next.
    prev_idx = -1;
    for n in [1, 2, 3, 4, 5] {
        marker = f"Stop {n}:";
        idx = out.index(marker);
        assert idx > prev_idx, (
            f"Stop {n} appeared out of order; prev_idx={prev_idx}, idx={idx}, output={out!r}"
        );
        prev_idx = idx;
    }
}

test "custom tour name flows through to the greeting" {
    out = build_and_tour(tour_name="Penthouse Preview");
    assert "Welcome to the Penthouse Preview!" in out, (
        f"custom tour name should appear in greeting, got: {out!r}"
    );
    # The default tour name must NOT leak in when overridden.
    assert "Welcome to the Grand Tour" not in out, (
        f"default tour name leaked into greeting: {out!r}"
    );
}

