import io;
import from contextlib { redirect_stdout }

test "walker visits every station and collects readings" {
    root ++> Station(name="North", location="roof", celsius=12.5)
        ++> Station(name="East", location="shed", celsius=18.0)
        ++> Station(name="South", location="garden", celsius=22.3)
        ++> Station(name="West", location="garage", celsius=9.8);

    buf = io.StringIO();
    sweep = WeatherSweep();
    with redirect_stdout(buf) {
        root spawn sweep;
    }

    # Every station was visited in order, so readings has 4 entries.
    assert len(sweep.readings) == 4, f"expected 4 readings, got {len(sweep.readings)}";

    # Each reading preserves [name, location, celsius] in that order.
    expected = [
        ["North", "roof", 12.5],
        ["East", "shed", 18.0],
        ["South", "garden", 22.3],
        ["West", "garage", 9.8],
    ];
    assert sweep.readings == expected, f"readings mismatch: {sweep.readings}";

    # Sweep does not stop — it continues on to the next station each step.
    # If it had stopped, the chain after North/East/South/West would not
    # have been walked past; verify all four stations were logged.
    out = buf.getvalue();
    assert "12.5°C" in out, f"missing North reading in output: {out}";
    assert "18.0°C" in out, f"missing East reading in output: {out}";
    assert "22.3°C" in out, f"missing South reading in output: {out}";
    assert "9.8°C" in out, f"missing West reading in output: {out}";
}

