    root ++> Station(name="North", location="roof", celsius=12.5)
        ++> Station(name="East", location="shed", celsius=18.0)
        ++> Station(name="South", location="garden", celsius=22.3)
        ++> Station(name="West", location="garage", celsius=9.8);

    sweep = WeatherSweep();
    root spawn sweep;

    temps = [r[2] for r in sweep.readings];
    assert min(temps) == 9.8, f"expected min 9.8, got {min(temps)}";
    assert max(temps) == 22.3, f"expected max 22.3, got {max(temps)}";

    # The full list of readings (4 items) plus min/max are printed.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        print("\nFull readings:");
        for (name, loc, temp) in sweep.readings {
            print(f"  {name} ({loc}): {temp}°C");
        }
        print(f"\nMin: {min(temps)}°C   Max: {max(temps)}°C");
    }
    out = buf.getvalue();
    assert "Full readings:" in out, f"missing list header: {out}";
    assert "North (roof): 12.5°C" in out, f"missing North line: {out}";
    assert "West (garage): 9.8°C" in out, f"missing West line: {out}";
