            if here.celsius > self.max_t {
                self.max_t = here.celsius;
            }
        }
        self.count += 1;
        visit [-->];
    }

    can finish with Root exit {
        if self.count == 0 {
            print("No stations visited.");
            disengage;
        }
        print("All readings:");
        for (loc, temp) in self.readings {
            print(f"  {loc}: {temp} C");
        }
        print(f"Min: {self.min_t} C");
        print(f"Max: {self.max_t} C");
    }
}

