"""Regression tests for OrderAuditor: skip-invalid vs halt-on-fraud semantics."""

import io;
import from contextlib { redirect_stdout }


def make_stream(orders: list) {
    r = root;
    cur = r;
    for (lbl, amt, vld, frd) in orders {
        cur ++> Order(label=lbl, amount=amt, valid=vld, fraud=frd);
        cur = [cur -->][-1];
    }
    return r;
}


test "skip flavor: invalid orders are skipped, walk continues" {
    parent = make_stream([
        ("A-1001", 42.50, True, False),
        ("A-1002", 19.99, False, False),
        ("A-1003", 125.00, True, False),
        ("A-1004", 7.25, True, False),
    ]);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = parent spawn OrderAuditor();
    }
    out = buf.getvalue();
    assert "[OK]   A-1001" in out, f"missing OK for A-1001: {out}";
    assert "[SKIP] A-1002" in out, f"missing SKIP for A-1002: {out}";
    assert "[OK]   A-1003" in out, f"walk did not continue past skipped order: {out}";
    assert "[OK]   A-1004" in out, f"walk did not continue past skipped order: {out}";
    assert res.audited == 3, f"expected 3 audited, got {res.audited}";
    assert res.skipped == 1, f"expected 1 skipped, got {res.skipped}";
    assert res.halted_on == "", f"should not halt on invalid order, got halted_on={res.halted_on!r}";
}


test "halt flavor: fraud disengages the entire walk immediately" {
    parent = make_stream([
        ("A-1001", 42.50, True, False),
        ("A-1005", 999.99, True, True),
        ("A-1006", 55.00, True, False),
    ]);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = parent spawn OrderAuditor();
    }
    out = buf.getvalue();
    assert "[OK]   A-1001" in out, f"missing OK for A-1001: {out}";
    assert "[HALT] fraud detected on A-1005" in out, f"missing HALT for A-1005: {out}";
    assert "A-1006" not in out, f"walk should not reach A-1006 after fraud disengage: {out}";
    assert res.halted_on == "A-1005", f"halted_on should record the fraud label, got {res.halted_on!r}";
    assert res.audited == 1, f"only A-1001 should be audited, got {res.audited}";
    assert res.skipped == 0, f"no skips expected, got {res.skipped}";
}


test "fraud before any valid orders still halts and reports label" {
    parent = make_stream([
        ("A-1009", 500.00, False, False),
        ("A-1010", 50.00, True, True),
    ]);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = parent spawn OrderAuditor();
    }
