"""Tests for the restaurant recommender: FoodieFinder walker parameterized by min_rating."""

import io;
import from contextlib { redirect_stdout }

node Restaurant {
    has title: str = "";
    has cuisine: str = "";
    has rating: float = 0.0;
}

walker FoodieFinder {
    has min_rating: float = 0.0;
    has matches: list = [];

    can start with Root entry {
        visit [-->];
    }

    can search with Restaurant entry {
        if here.rating >= self.min_rating {
            self.matches.append(here);
        }
        visit [-->];
    }
}

test "date night 4.5+ picks only top tier restaurants" {
    root ++> Restaurant(title="Le Bernardin", cuisine="French", rating=4.8)
        ++> Restaurant(title="Joe's Diner", cuisine="American", rating=3.7)
        ++> Restaurant(title="Sushi Yasuda", cuisine="Japanese", rating=4.6)
        ++> Restaurant(title="Taco Truck", cuisine="Mexican", rating=3.4)
        ++> Restaurant(title="Osteria Mozza", cuisine="Italian", rating=4.5)
        ++> Restaurant(title="Pizza Palace", cuisine="Italian", rating=2.9);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        date_night = FoodieFinder(min_rating=4.5);
        root spawn date_night;
        print("Date night picks (4.5+):");
        for r in date_night.matches {
            print(f"  - {r.title} ({r.cuisine}) [{r.rating}]");
        }
    }
    out = buf.getvalue();

    # Header from the walker usage must appear
    assert "Date night picks (4.5+):" in out, f"missing header: {out}";

    # Exactly three restaurants have rating >= 4.5
    assert len(date_night.matches) == 3, f"expected 3 date-night picks, got {len(date_night.matches)}: {out}";

    # All matches must satisfy the threshold
    for r in date_night.matches {
        assert r.rating >= 4.5, f"{r.title} has rating {r.rating}, below 4.5";
    }

    # The three top-tier restaurants must all be named; lower-rated ones must not
    titles = [r.title for r in date_night.matches];
    assert "Le Bernardin" in titles, f"Le Bernardin missing from date-night: {out}";
    assert "Sushi Yasuda" in titles, f"Sushi Yasuda missing from date-night: {out}";
    assert "Osteria Mozza" in titles, f"Osteria Mozza missing from date-night: {out}";
    assert "Joe's Diner" not in titles, f"Joe's Diner should not appear in date-night: {out}";
    assert "Taco Truck" not in titles, f"Taco Truck should not appear in date-night: {out}";
    assert "Pizza Palace" not in titles, f"Pizza Palace should not appear in date-night: {out}";

    # Print format must include the rating value
    assert "[4.8]" in out, f"expected [4.8] rating marker: {out}";
    assert "[4.6]" in out, f"expected [4.6] rating marker: {out}";
    assert "[4.5]" in out, f"expected [4.5] rating marker: {out}";
}

test "casual lunch 3.5+ picks include mid-tier and exclude bottom tier" {
    root ++> Restaurant(title="Le Bernardin", cuisine="French", rating=4.8)
        ++> Restaurant(title="Joe's Diner", cuisine="American", rating=3.7)
        ++> Restaurant(title="Sushi Yasuda", cuisine="Japanese", rating=4.6)
        ++> Restaurant(title="Taco Truck", cuisine="Mexican", rating=3.4)
        ++> Restaurant(title="Osteria Mozza", cuisine="Italian", rating=4.5)
        ++> Restaurant(title="Pizza Palace", cuisine="Italian", rating=2.9);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        casual_lunch = FoodieFinder(min_rating=3.5);
        root spawn casual_lunch;
        print("Casual lunch picks (3.5+):");
        for r in casual_lunch.matches {
            print(f"  - {r.title} ({r.cuisine}) [{r.rating}]");
        }
    }
    out = buf.getvalue();

    # Header from the walker usage must appear
    assert "Casual lunch picks (3.5+):" in out, f"missing header: {out}";

    # 4.8, 4.6, 4.5, 3.7 all qualify => 4 picks; 3.4 and 2.9 do not
    assert len(casual_lunch.matches) == 4, f"expected 4 casual-lunch picks, got {len(casual_lunch.matches)}: {out}";

    # All matches must satisfy the lower threshold
    for r in casual_lunch.matches {
        assert r.rating >= 3.5, f"{r.title} has rating {r.rating}, below 3.5";
    }

    # Specifically: Taco Truck (3.4) and Pizza Palace (2.9) must be excluded
    titles = [r.title for r in casual_lunch.matches];
    assert "Taco Truck" not in titles, f"Taco Truck (3.4) must be excluded at 3.5+: {out}";
    assert "Pizza Palace" not in titles, f"Pizza Palace (2.9) must be excluded at 3.5+: {out}";

    # The casual pick (Joe's Diner, 3.7) must be included
    assert "Joe's Diner" in titles, f"Joe's Diner (3.7) must be included at 3.5+: {out}";
}

test "min_rating threshold is exclusive boundary — 3.5 excludes a 3.4 restaurant" {
    root ++> Restaurant(title="Borderline Bistro", cuisine="French", rating=3.5)
        ++> Restaurant(title="Just Below", cuisine="American", rating=3.4)
        ++> Restaurant(title="Above", cuisine="Italian", rating=3.6);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        finder = FoodieFinder(min_rating=3.5);
        root spawn finder;
    }

    # >= 3.5 should pick Bistro (3.5) and Above (3.6) but not Just Below (3.4)
    assert len(finder.matches) == 2, f"expected 2 matches at threshold 3.5, got {len(finder.matches)}";
    titles = [r.title for r in finder.matches];
    assert "Borderline Bistro" in titles, f"3.5 should be included at threshold 3.5: {titles}";
    assert "Above" in titles, f"3.6 should be included at threshold 3.5: {titles}";
    assert "Just Below" not in titles, f"3.4 must be excluded at threshold 3.5: {titles}";
}

test "min_rating default 0.0 picks every restaurant" {
    root ++> Restaurant(title="A", cuisine="X", rating=4.8)
        ++> Restaurant(title="B", cuisine="Y", rating=0.1)
        ++> Restaurant(title="C", cuisine="Z", rating=2.9)
        ++> Restaurant(title="D", cuisine="W", rating=3.7);

    finder = FoodieFinder();
    # default min_rating is 0.0; every restaurant has rating >= 0
    root spawn finder;

    assert len(finder.matches) == 4, f"expected all 4 restaurants with default min_rating=0.0, got {len(finder.matches)}";
    titles = sorted([r.title for r in finder.matches]);
    assert titles == ["A", "B", "C", "D"], f"unexpected titles at default threshold: {titles}";
}

test "high min_rating threshold returns zero matches for low-rated graph" {
    root ++> Restaurant(title="Diner One", cuisine="American", rating=3.0)
        ++> Restaurant(title="Diner Two", cuisine="American", rating=2.5)
        ++> Restaurant(title="Diner Three", cuisine="American", rating=1.8);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        picky = FoodieFinder(min_rating=4.5);
        root spawn picky;
        print("No matches above 4.5 in this graph");
    }

    assert len(picky.matches) == 0, f"expected no matches, got {len(picky.matches)}";
    out = buf.getvalue();
    # The loop body never executes, so no restaurant lines should be printed
    assert "Diner One" not in out, f"Diner One should not appear: {out}";
    assert "Diner Two" not in out, f"Diner Two should not appear: {out}";
    assert "Diner Three" not in out, f"Diner Three should not appear: {out}";
}

