import io;
import from contextlib { redirect_stdout }

test "invalid orders are skipped while later orders are audited" {
    root ++> Order(title="First", amount=120.50)
        ++> Order(title="Invalid", amount=75.00, valid=False)
        ++> Order(title="Later", amount=300.00);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
