    assert "[SKIP] 'Invalid' is invalid -- continuing audit" in out, f"missing skip output: {out}";
    assert "[OK]   'Later'" in out, f"later order was not audited: {out}";
    assert res.audited == 2, f"expected 2 audited orders, got {res.audited}";
}

test "fraud halts the walk before later orders" {
    root ++> Order(title="Before-Fraud", amount=120.50)
        ++> Order(title="Fraud", amount=75.00, fraud=True)
        ++> Order(title="After-Fraud", amount=300.00);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[OK]   'Before-Fraud'" in out, f"missing pre-fraud output: {out}";
    assert "[HALT] fraud flagged on 'Fraud' -- audit aborted" in out, f"missing halt output: {out}";
    assert "After-Fraud" not in out, f"walk continued after fraud: {out}";
    assert res.audited == 1, f"expected 1 audited order, got {res.audited}";
}

