    assert project_fresh.title == "Typed edges in 0.36.1", f"got {project_fresh.title}";
    assert project_fresh.priority == 3, f"got {project_fresh.priority}";

    # The freshly created ticket must hang off the project, not off root.
    assert project_fresh in [project-->], "fresh ticket should hang directly off project";
    assert project_fresh not in [root-->], "fresh ticket should NOT be at root's level";
}

test "immediate print after capture prints title and priority" {
    project = Project(title="Jac Runtime");
    root ++> project;

    buf = io.StringIO();
