"""Tests for Gallery security console: log visitors, record curator inspections."""

import io;
import from contextlib { redirect_stdout }

test "tourist logs generic entries only and counts visits" {
    gallery = Room(name="Gallery");
    storage = Room(name="Storage");
    root ++> gallery ++> storage;

    buf = io.StringIO();
    res = None;
    with redirect_stdout(buf) {
        t = Visitor(badge="T-9");
        res = root spawn t;
    }
    out = buf.getvalue();

    # Generic log line printed for every room entered (2 rooms).
    assert "[LOG] visitor T-9 entered room Gallery" in out, f"missing Gallery log: {out}";
    assert "[LOG] visitor T-9 entered room Storage" in out, f"missing Storage log: {out}";

    # Visitor must NOT produce any inspection lines (generic only).
    assert "[INSPECTION]" not in out, f"tourist must not trigger inspections: {out}";

    # Both rooms traversed -> visits counter == 2.
    assert res.visits == 2, f"expected 2 visits, got {res.visits}";

    # Tourist must not gain a curator-only attribute semantically:
    # inspections is a Curator field, but Visitor has none, so just confirm
    # the outcome field (default) was not used to fake an inspection count.
    assert not hasattr(res, "inspections"), "Visitor walker must not expose inspections";
}

test "curator records official inspection in each room with name" {
    gallery = Room(name="Gallery");
    storage = Room(name="Storage");
    root ++> gallery ++> storage;

    buf = io.StringIO();
    res = None;
    with redirect_stdout(buf) {
        c = Curator(badge="C-1");
        res = root spawn c;
    }
    out = buf.getvalue();

    # Inspection line printed under curator's name AND room name for every room.
    assert "[INSPECTION] curator C-1 officially inspected room Gallery" in out, f"missing Gallery inspection: {out}";
    assert "[INSPECTION] curator C-1 officially inspected room Storage" in out, f"missing Storage inspection: {out}";

    # Curator should also be logged generically? Spec says curators record an
    # OFFICIAL inspection *additionally*; the program does not print a [LOG]
    # line for curators, so confirm there are no generic [LOG] lines.
    assert "[LOG]" not in out, f"curator path should not emit generic [LOG], got: {out}";

    # Inspector counter and last room both reflect the second room visited.
    assert res.inspections == 2, f"expected 2 inspections, got {res.inspections}";
    assert res.current_room == "Storage", f"current_room should be last visited, got {res.current_room}";
}

test "tourist vs curator difference: only curator has inspections count" {
    gallery = Room(name="Gallery");
    storage = Room(name="Storage");
    root ++> gallery ++> storage;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        t = Visitor(badge="T-9");
        root spawn t;
        c = Curator(badge="C-1");
        root spawn c;
        print(
            f"difference: curator logged {c.inspections} official inspection(s), "
            f"tourist logged only generic entries."
        );
    }
    out = buf.getvalue();

    # Generic logs come ONLY from the tourist, exactly twice.
    assert out.count("[LOG] visitor T-9 entered room Gallery") == 1, f"Gallery log count wrong: {out}";
    assert out.count("[LOG] visitor T-9 entered room Storage") == 1, f"Storage log count wrong: {out}";

    # Inspection logs come ONLY from the curator, exactly once per room.
    assert out.count("[INSPECTION] curator C-1 officially inspected room Gallery") == 1, f"Gallery inspection count wrong: {out}";
    assert out.count("[INSPECTION] curator C-1 officially inspected room Storage") == 1, f"Storage inspection count wrong: {out}";

    # Final summary line carries the curator's inspection count.
    assert "difference: curator logged 2 official inspection(s)" in out, f"missing/wrong summary: {out}";

    # Cross-class sanity: tourist produced 0 inspection lines, curator produced 2.
    assert out.count("[INSPECTION]") == 2, f"expected exactly 2 inspection lines, got {out.count('[INSPECTION]')}";
    assert out.count("[LOG]") == 2, f"expected exactly 2 generic log lines, got {out.count('[LOG]')}";
}

test "graph shape: two rooms chained from root, no extra edges" {
    gallery = Room(name="Gallery");
    storage = Room(name="Storage");
    root ++> gallery ++> storage;

    # Root has exactly one outgoing edge (to Gallery).
    assert len([root-->]) == 1, f"root should have 1 child, got {len([root-->])}";

    # Gallery links to Storage; Storage is a leaf.
    assert gallery in [root-->], "Gallery must be a direct child of root";
    assert storage in [gallery-->], "Storage must be a direct child of Gallery";
    assert len([storage-->]) == 0, f"Storage should be leaf, got {len([storage-->])}";

    # Names preserved on nodes.
    rooms = [root-->];
    assert "Gallery" in [r.name for r in rooms], "Gallery node name not set";
}

