    buf_c = io.StringIO();
    res_c = None;
    with redirect_stdout(buf_c) {
        c = Curator(badge="C-1");
        res_c = root spawn c;
    }
    out_c = buf_c.getvalue();
    assert "[INSPECTION] curator C-1 officially inspected room Solo" in out_c, f"missing solo inspection: {out_c}";
    assert res_c.inspections == 1, f"single-room curator inspections should be 1, got {res_c.inspections}";
