"""Tests for the bug tracker ticket-filing flow."""

import io;
import from contextlib { redirect_stdout }

test "files a ticket off the project and reports it inline" {
    root ++> Project(name="Billing");
    p = [root -->][0];

    buf = io.StringIO();
    with redirect_stdout(buf) {
        p spawn Reporter();
    }
    out = buf.getvalue();

    assert "FILED on Billing" in out, f"missing 'FILED on Billing' in output: {out!r}";
    assert "Login fails on SSO redirect" in out, f"ticket title not printed: {out!r}";
    assert "priority 2" in out, f"ticket priority not printed: {out!r}";

    tickets = [p -->];
    assert len(tickets) == 1, f"expected 1 ticket linked from project, got {len(tickets)}";

    t = tickets[0];
    assert t.title == "Login fails on SSO redirect", f"title not captured on the new node: {t.title!r}";
    assert t.priority == 2, f"priority not captured on the new node: {t.priority!r}";
}

test "the new ticket is a fresh node, not a lookup of something pre-existing" {
    root ++> Project(name="Billing");
    p = [root -->][0];

    before = [p -->];
    assert len(before) == 0, f"project should start with no tickets, had {len(before)}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        p spawn Reporter();
    }
    out = buf.getvalue();

    after = [p -->];
    assert len(after) == 1, f"expected exactly one ticket after filing, got {len(after)}";

    t = after[0];
    assert isinstance(t, Ticket), f"connected node should be a Ticket, got {type(t)}";
    assert t.title != "", f"freshly filed ticket should carry its title inline: {t.title!r}";
    assert t.priority > 0, f"freshly filed ticket should carry a priority inline: {t.priority}";
}

test "filing twice produces two distinct tickets under the same project" {
    root ++> Project(name="Billing");
    p = [root -->][0];

    buf = io.StringIO();
    with redirect_stdout(buf) {
        p spawn Reporter();
        p spawn Reporter();
    }
    out = buf.getvalue();

    tickets = [p -->];
    assert len(tickets) == 2, f"expected 2 tickets after filing twice, got {len(tickets)}";

    titles = {t.title for t in tickets};
    assert titles == {"Login fails on SSO redirect"}, f"ticket titles inconsistent: {titles}";

    assert out.count("FILED on Billing") == 2, f"expected 2 FILED lines, got {out.count('FILED on Billing')}: {out!r}";
    assert out.count("priority 2") == 2, f"expected 2 priority prints, got {out.count('priority 2')}: {out!r}";
}

test "Reporter on a non-Project node does not file anything" {
    # Spawning Reporter on Root matches the `can start with Root entry` arm,
    # which only visits children — no Project visit means no ticket and no print.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Reporter();
