"""Test annex for warehouse packing line simulation."""

import io;
import from contextlib { redirect_stdout }

# ---------- Test 1: RobotMover increments stops and station boxes ----------
test "RobotMover counts stops and stations tally boxes" {
    buf = io.StringIO();
    root spawn RobotMover(name="R-Atlas");
    root spawn RobotMover(name="R-Bolt");
    s1 = Station(name="Pack-1");
    s2 = Station(name="Pack-2");
    s3 = Station(name="Pack-3");
    root ++> s1 ++> s2 ++> s3;
    with redirect_stdout(buf) {
        r1 = RobotMover(name="R-Atlas");
        r2 = RobotMover(name="R-Bolt");
        r1 spawn root;
        r2 spawn root;
    }
    out = buf.getvalue();
    assert "R-Atlas stops at Pack-1 (stops=1)" in out, f"missing first Atlas stop: {out}";
    assert "R-Atlas stops at Pack-2 (stops=2)" in out, f"missing second Atlas stop: {out}";
    assert "R-Atlas stops at Pack-3 (stops=3)" in out, f"missing third Atlas stop: {out}";
    assert "R-Bolt stops at Pack-1 (stops=1)" in out, f"missing first Bolt stop: {out}";
    assert "R-Bolt stops at Pack-2 (stops=2)" in out, f"missing second Bolt stop: {out}";
    assert "R-Bolt stops at Pack-3 (stops=3)" in out, f"missing third Bolt stop: {out}";
    assert r1.stops == 3, f"Atlas stops should be 3, got {r1.stops}";
    assert r2.stops == 3, f"Bolt stops should be 3, got {r2.stops}";
    assert s1.boxes_packed == 2, f"Pack-1 should have 2 boxes, got {s1.boxes_packed}";
    assert s2.boxes_packed == 2, f"Pack-2 should have 2 boxes, got {s2.boxes_packed}";
    assert s3.boxes_packed == 2, f"Pack-3 should have 2 boxes, got {s3.boxes_packed}";
}

# ---------- Test 2: StationAuditor reports per-station tally ----------
test "StationAuditor prints boxes packed per station" {
    buf = io.StringIO();
    s1 = Station(name="Pack-1");
    s2 = Station(name="Pack-2");
    s3 = Station(name="Pack-3");
    s1.boxes_packed = 5;
    s2.boxes_packed = 0;
    s3.boxes_packed = 7;
    root ++> s1 ++> s2 ++> s3;
    with redirect_stdout(buf) {
        StationAuditor() spawn root;
    }
    out = buf.getvalue();
    assert "Pack-1 packed 5 boxes" in out, f"missing Pack-1 report: {out}";
    assert "Pack-2 packed 0 boxes" in out, f"missing Pack-2 report: {out}";
    assert "Pack-3 packed 7 boxes" in out, f"missing Pack-3 report: {out}";
}

# ---------- Test 3: Graph shape — three-station line via Root ----------
test "three station line shape from Root" {
    s1 = Station(name="Pack-1");
    s2 = Station(name="Pack-2");
    s3 = Station(name="Pack-3");
    root ++> s1 ++> s2 ++> s3;
    assert len([root-->]) == 1, f"root should have one direct child, got {len([root-->])}";
    direct = [root-->][0];
    assert direct == s1, f"root direct child should be Pack-1";
    assert len([s1-->]) == 1, f"Pack-1 should have one direct child, got {len([s1-->])}";
    assert [s1-->][0] == s2, f"Pack-1 direct child should be Pack-2";
    assert len([s2-->]) == 1, f"Pack-2 should have one direct child, got {len([s2-->])}";
    assert [s2-->][0] == s3, f"Pack-2 direct child should be Pack-3";
    assert len([s3-->]) == 0, f"Pack-3 should have no children, got {len([s3-->])}";
}

# ---------- Test 4: RobotMover disengages when no outgoing station ----------
test "RobotMover disengages after last station in chain" {
    buf = io.StringIO();
    s1 = Station(name="Pack-1");
    s2 = Station(name="Pack-2");
    s3 = Station(name="Pack-3");
    root ++> s1 ++> s2 ++> s3;
    with redirect_stdout(buf) {
        r = RobotMover(name="R-Solo");
        r spawn root;
    }
    out = buf.getvalue();
    assert "R-Solo stops at Pack-1 (stops=1)" in out, f"missing Pack-1 stop: {out}";
    assert "R-Solo stops at Pack-2 (stops=2)" in out, f"missing Pack-2 stop: {out}";
    assert "R-Solo stops at Pack-3 (stops=3)" in out, f"missing Pack-3 stop: {out}";
    assert "R-Solo stops at Pack-4" not in out, f"should not print a Pack-4 stop: {out}";
    assert r.stops == 3, f"R-Solo stops should be 3, got {r.stops}";
    assert s3.boxes_packed == 1, f"Pack-3 should have 1 box, got {s3.boxes_packed}";
    assert s1.boxes_packed == 1, f"Pack-1 should have 1 box, got {s1.boxes_packed}";
    assert s2.boxes_packed == 1, f"Pack-2 should have 1 box, got {s2.boxes_packed}";
}

# ---------- Test 5: Single-station chain — only one stop recorded ----------
test "single station chain yields single stop" {
    buf = io.StringIO();
