import io;
import from contextlib { redirect_stdout }

# Build the standard 3-desk + 2-guest chain in one place.
def build_chain() {
    spa = ServiceDesk(label="spa session", price=85.0);
    dinner = ServiceDesk(label="room-service dinner", price=42.5);
    laundry = ServiceDesk(label="express laundry", price=18.0);
    alice = Guest(name="Alice");
    bob = Guest(name="Bob");
    root ++> spa ++> dinner ++> laundry ++> alice ++> bob;
    return [alice, bob];
}

test "alice total sums all three desks" {
    guests = build_chain();
    alice = guests[0];
    res = root spawn GuestPass(guest_name="Alice");
    assert alice.total == 145.5, f"expected 145.5, got {alice.total}";
}

test "bob total sums all three desks and does not touch alice" {
    guests = build_chain();
    alice = guests[0];
    bob = guests[1];
    res = root spawn GuestPass(guest_name="Bob");
    assert bob.total == 145.5, f"expected 145.5, got {bob.total}";
    assert alice.total == 0.0, f"expected alice untouched at 0.0, got {alice.total}";
}

test "each charge line and running owed prints in order" {
    build_chain();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn GuestPass(guest_name="Alice");
    }
    out = buf.getvalue();
    # Three incremental charge lines, in order, with running totals.
    expected_lines = [
        "Alice charged 85.0 for spa session -> owes 85.0",
        "Alice charged 42.5 for room-service dinner -> owes 127.5",
        "Alice charged 18.0 for express laundry -> owes 145.5",
        "Checkout: Alice owes 145.5",
    ];
    # Confirm each line appears and that the order matches.
    positions = [];
    for line in expected_lines {
        assert line in out, f"missing line '{line}' in output:\n{out}";
        positions.append(out.find(line));
    }
    is_sorted = True;
    for i in range(len(positions) - 1) {
        if not (positions[i] < positions[i + 1]) {
            is_sorted = False;
        }
    }
    assert is_sorted, f"lines not in expected order, positions={positions}";
}

