"""Tests for the wildlife park feeding rounds program."""

import io;
import from contextlib { redirect_stdout }

def _build_park(kiosk_name: str, lion_name: str, parrot_name: str) {
    kiosk = Kiosk(name=kiosk_name);
    simba = Lion(name=lion_name);
    polly = Parrot(name=parrot_name);
    root ++> kiosk ++> simba ++> polly;
    return root;
}

test "zookeeper feeds lion with meat and parrot with seed" {
    rt = _build_park("Safari Entrance", "Simba", "Polly");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ZooKeeper(keeper_id="Z-100");
    }
    out = buf.getvalue();

    # Kiosk must greet the zookeeper (union trigger fires for ZooKeeper).
    assert "Welcome to the park!" in out, f"kiosk missed zookeeper: {out!r}";
    # Zookeeper must check in at the named kiosk.
    assert "Z-100 checked in at Safari Entrance kiosk" in out, f"greet missing: {out!r}";
    # Zookeeper feeds lion meat (species-appropriate meal).
    assert "Z-100 serves meat to lion Simba" in out, f"lion meal missing: {out!r}";
    # Zookeeper feeds parrot seed (species-appropriate meal).
    assert "Z-100 offers seed to parrot Polly" in out, f"parrot meal missing: {out!r}";
    # Zookeeper must NOT observe animals like a school group would.
    assert "watch" not in out, f"zookeeper should not observe, got: {out!r}";
}

test "school group observes both animals but feeds none" {
    rt = _build_park("Safari Entrance", "Simba", "Polly");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SchoolGroup(grade=4);
    }
    out = buf.getvalue();

    # Kiosk must greet the school group (union trigger fires for SchoolGroup).
    assert "Welcome to the park!" in out, f"kiosk missed school group: {out!r}";
    # School group watches both animals.
    assert "Grade 4 students watch lion Simba" in out, f"lion watch missing: {out!r}";
    assert "Grade 4 students watch parrot Polly" in out, f"parrot watch missing: {out!r}";
    # School groups must NOT feed animals.
    assert "serves meat" not in out, f"school group must not serve meat: {out!r}";
    assert "offers seed" not in out, f"school group must not offer seed: {out!r}";
    # School groups have no keeper id / check-in line.
    assert "checked in" not in out, f"school group must not check in: {out!r}";
}

test "kiosk greets both visitor types via union trigger" {
    rt = _build_park("Gate A", "Leo", "Pico");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        _ = root spawn ZooKeeper(keeper_id="Z-200");
    }
    keeper_out = buf.getvalue();
    assert "Welcome to the park!" in keeper_out, f"kiosk missed zookeeper: {keeper_out!r}";

    # Fresh graph for the school group run.
    rt2 = _build_park("Gate A", "Leo", "Pico");

    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        _ = root spawn SchoolGroup(grade=2);
    }
    school_out = buf2.getvalue();
    assert "Welcome to the park!" in school_out, f"kiosk missed school group: {school_out!r}";
}

test "traversal visits kiosk then chained animals in order" {
    rt = _build_park("North Gate", "Aslan", "Kiwi");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        _ = root spawn ZooKeeper(keeper_id="Z-300");
    }
    out = buf.getvalue();

    # The welcome banner appears before any feeding lines (kiosk visited first).
    welcome_at = out.find("Welcome to the park!");
    lion_at = out.find("serves meat to lion Aslan");
    parrot_at = out.find("offers seed to parrot Kiwi");
    assert welcome_at >= 0, f"no welcome: {out!r}";
    assert lion_at > welcome_at, f"lion must come after welcome: {out!r}";
    assert parrot_at > lion_at, f"parrot must come after lion: {out!r}";
}

