fixed.jac_tests:
"""Tests for data center clearance enforcement.

Verifies the behavior the problem specifies:
- Grant when technician clearance >= room required_level.
- Deny when clearance is insufficient; record denied_room name.
- A denial disengages the walker, so deeper rooms are NEVER visited.
- rooms_visited only counts successfully granted entries.
- The walkthrough summary reports reached counts and the denial point.
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Test 1: Junior technician is granted up to their clearance and denied at
# the first room they cannot enter. After denial, deeper rooms must NOT be
# counted as visited.
# ---------------------------------------------------------------------------
test "junior clears two rooms then is denied and disengages" {
    root ++> ServerRoom(name="Lobby", required_level=1)
        ++> ServerRoom(name="Storage", required_level=2)
        ++> ServerRoom(name="Ops Floor", required_level=3)
        ++> ServerRoom(name="Crypto Vault", required_level=5);

    buf = io.StringIO();
    junior = Technician(name="Alice", clearance=2);
    with redirect_stdout(buf) {
        res = root spawn junior;
    }
    out = buf.getvalue();

    # Two rooms granted: Lobby (1) and Storage (2).
    assert junior.rooms_visited == 2, f"expected 2 rooms visited, got {junior.rooms_visited}";
    # Denied at the next room in line.
    assert junior.denied_room == "Ops Floor", f"expected denial at 'Ops Floor', got '{junior.denied_room}'";

    # The denial line must appear in output.
    assert "DENIED: Alice blocked at Ops Floor" in out, f"missing denial line in: {out}";
    # Both grants must appear.
    assert "GRANTED: Alice entered Lobby" in out, f"missing Lobby grant in: {out}";
    assert "GRANTED: Alice entered Storage" in out, f"missing Storage grant in: {out}";
    # Crucially: deeper rooms must NOT appear in output past the denial.
    assert "Crypto Vault" not in out, f"deeper room leaked into output after denial: {out}";
    assert "Quantum Lab" not in out or "Crypto Vault" not in out, f"deeper room visited after denial: {out}";
}

# ---------------------------------------------------------------------------
# Test 2: Senior technician with clearance >= every room requirement reaches
# every room and is never denied (denied_room stays empty string default).
# ---------------------------------------------------------------------------
test "senior technician with full clearance reaches every room" {
    root ++> ServerRoom(name="Lobby", required_level=1)
        ++> ServerRoom(name="Storage", required_level=2)
        ++> ServerRoom(name="Ops Floor", required_level=3)
        ++> ServerRoom(name="Crypto Vault", required_level=5)
        ++> ServerRoom(name="Quantum Lab", required_level=7);

    buf = io.StringIO();
    senior = Technician(name="Bob", clearance=10);
    with redirect_stdout(buf) {
        res = root spawn senior;
    }
    out = buf.getvalue();

    # All 5 rooms granted.
    assert senior.rooms_visited == 5, f"expected 5 rooms visited, got {senior.rooms_visited}";
    # No denial recorded.
    assert senior.denied_room == "", f"expected empty denied_room, got '{senior.denied_room}'";

    # No DENIED line for Bob anywhere in the output.
    assert "DENIED: Bob" not in out, f"unexpected denial line for senior: {out}";
    # All five rooms appear as granted.
    for name in ["Lobby", "Storage", "Ops Floor", "Crypto Vault", "Quantum Lab"] {
        assert f"GRANTED: Bob entered {name}" in out, f"missing grant for {name} in: {out}";
    }
}

# ---------------------------------------------------------------------------
# Test 3: Contractor with clearance=0 is denied at the very first room and
# visits zero rooms. Engagement must terminate before deeper traversal.
# ---------------------------------------------------------------------------
test "contractor with zero clearance is denied at the lobby" {
    root ++> ServerRoom(name="Lobby", required_level=1)
        ++> ServerRoom(name="Storage", required_level=2)
        ++> ServerRoom(name="Ops Floor", required_level=3);

    buf = io.StringIO();
    contractor = Technician(name="Eve", clearance=0);
    with redirect_stdout(buf) {
        res = root spawn contractor;
    }
    out = buf.getvalue();

    # Visited nothing.
    assert contractor.rooms_visited == 0, f"expected 0 rooms visited, got {contractor.rooms_visited}";
    # Denied at the first room.
    assert contractor.denied_room == "Lobby", f"expected denial at 'Lobby', got '{contractor.denied_room}'";

    # Denial line present, no grants, and no deeper rooms touched.
    assert "DENIED: Eve blocked at Lobby" in out, f"missing denial line in: {out}";
    assert "GRANTED: Eve" not in out, f"contractor should not be granted anywhere: {out}";
    assert "Storage" not in out, f"deeper room 'Storage' leaked into output: {out}";
    assert "Ops Floor" not in out, f"deeper room 'Ops Floor' leaked into output: {out}";
}

# ---------------------------------------------------------------------------
# Test 4: Boundary case — clearance exactly equal to required_level is
# granted. Verify equality (>=) rather than strict >.
# ---------------------------------------------------------------------------
test "clearance equal to required level is granted (boundary)" {
    root ++> ServerRoom(name="Lobby", required_level=3)
        ++> ServerRoom(name="Storage", required_level=3)
        ++> ServerRoom(name="Ops Floor", required_level=3);

    buf = io.StringIO();
    tech = Technician(name="Cara", clearance=3);
    with redirect_stdout(buf) {
        res = root spawn tech;
    }
    out = buf.getvalue();

    # All three rooms require exactly 3 and the tech has exactly 3.
    assert tech.rooms_visited == 3, f"expected 3 rooms visited at boundary, got {tech.rooms_visited}";
    assert tech.denied_room == "", f"expected no denial at boundary, got '{tech.denied_room}'";

    for name in ["Lobby", "Storage", "Ops Floor"] {
        assert f"GRANTED: Cara entered {name}" in out, f"missing grant for {name} at boundary: {out}";
    }
    assert "DENIED: Cara" not in out, f"unexpected denial at equality boundary: {out}";
}

# ---------------------------------------------------------------------------
# Test 5: Walkthrough summary — confirm the program's reporting contract:
# count of rooms reached and the room name where denial happened (or empty
# when none).
# ---------------------------------------------------------------------------
test "walkthrough summary reports reached count and denial point" {
    root ++> ServerRoom(name="Lobby", required_level=1)
        ++> ServerRoom(name="Storage", required_level=2)
        ++> ServerRoom(name="Ops Floor", required_level=3);

    # Junior — partial walkthrough.
    junior = Technician(name="Alice", clearance=2);
    res = root spawn junior;
    assert junior.rooms_visited == 2, f"Alice visited {junior.rooms_visited}";
    assert junior.denied_room == "Ops Floor", f"Alice denied at {junior.denied_room}";

    # Senior — full walkthrough, no denial recorded.
    senior = Technician(name="Bob", clearance=10);
    res = root spawn senior;
    assert senior.rooms_visited == 3, f"Bob visited {senior.rooms_visited}";
    assert senior.denied_room == "", f"Bob denied_room should be empty, got '{senior.denied_room}'";

    # Contractor — denied at first door.
    contractor = Technician(name="Eve", clearance=0);
    res = root spawn contractor;
    assert contractor.rooms_visited == 0, f"Eve visited {contractor.rooms_visited}";
    assert contractor.denied_room == "Lobby", f"Eve denied at {contractor.denied_room}";

    # Summary numbers must be consistent with the per-room behavior.
    assert junior.rooms_visited < senior.rooms_visited, "junior must reach fewer rooms than senior";
    assert contractor.rooms_visited == 0, "contractor must reach zero rooms";
}

