test "OrderAuditor visits every account on the lobby" {
    root ++> Member(owner="Alice", reputation=1);
    root ++> Admin(owner="Bob", reputation=1);
    root ++> Member(owner="Carol", reputation=1);
    root ++> Admin(owner="Dave", reputation=1);

