"""Test annex for the wildlife park feeding rounds program."""

import io;
import from contextlib { redirect_stdout }


def build_park {
    # Mirrors the demo graph: Kiosk -> chain of animals starting at Giraffe.
    return root ++> Kiosk()
        ++> Animal(name="Giraffe")
        ++> Lion(name="Leo")
        ++> Parrot(name="Polly")
        ++> Animal(name="Zebra");
}


test "zookeeper feeds each animal its species-appropriate meal" {
    root ++> Kiosk()
        ++> Animal(name="Giraffe")
        ++> Lion(name="Leo")
        ++> Parrot(name="Polly")
        ++> Animal(name="Zebra");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Zookeeper(zookeeper_name="Alex");
    }
    out = buf.getvalue();

    assert "Zookeeper Alex clocks in" in out, f"missing start line: {out}";
    assert "fed meat to lion Leo" in out, f"lion should get meat: {out}";
    assert "fed seed to parrot Polly" in out, f"parrot should get seed: {out}";
    assert "fed standard feed to Giraffe" in out, f"generic animal should get standard feed: {out}";
    assert "fed standard feed to Zebra" in out, f"second generic animal should get standard feed: {out}";

    # Default-meat/seed lines must not appear for non-matching species.
    assert "fed meat to lion Giraffe" not in out, f"generic animal wrongly fed meat: {out}";
    assert "fed seed to parrot Zebra" not in out, f"generic animal wrongly fed seed: {out}";
}

test "zookeeper marks every animal as fed (union ability)" {
    chain = build_park();
    giraffe = [chain ->:DependsOn:->][0] if False else chain;  # not used; we walk the chain
    # Grab each animal node off the chain by name via spawn-driven graph mutation.
    # Easier: locate each animal by traversing outgoing edges from root manually.
    root_node = root;
    # Walk the chain to collect nodes in order.
    nodes = [root_node];
    cur = root_node;
    for _ in range(0, 5) {
        kids = [cur-->];
        if not kids {
            break;
        }
        nodes.append(kids[0]);
        cur = kids[0];
    }
    animals = [n for n in nodes if isinstance(n, (Lion, Parrot, Animal))];
    assert len(animals) == 4, f"expected 4 animals in chain, got {len(animals)}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Zookeeper(zookeeper_name="Alex");
    }

    for a in animals {
        assert a.fed, f"{type(a).__name__} {a.name} should be fed after Zookeeper traversal";
    }
}

test "kiosk greets every tour party regardless of walker type" {
    root ++> Kiosk()
        ++> Animal(name="Giraffe");

    # SchoolGroup also passes the kiosk; check it prints the welcome marker.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn SchoolGroup(group_name="Maple Elementary");
    }
    out = buf.getvalue();
    # School group announces itself on Root entry before reaching kiosk.
    assert "Maple Elementary" in out, f"school group should announce itself: {out}";

    # TourParty greets via Root entry; kiosk entry must not produce extra greeting
    # because the kiosk has no greeting ability — only TourParty/Root does.
    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        root spawn TourParty(party_label="Smith family");
    }
    out2 = buf2.getvalue();
    assert "Tour party 'Smith family' enters the park" in out2, f"tour party greeting missing: {out2}";
    # Kiosk has no greeting ability, so no second hello line should appear.
    assert out2.count("Smith family") == 1, f"greeting should fire exactly once: {out2}";
}

test "school group watches animals but does not feed them" {
    root ++> Kiosk()
        ++> Animal(name="Giraffe")
        ++> Lion(name="Leo")
        ++> Parrot(name="Polly");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn SchoolGroup(group_name="Maple Elementary");
    }
    out = buf.getvalue();

    assert "School group 'Maple Elementary' is watching the animals" in out, f"missing announce: {out}";
    assert "Maple Elementary watches Giraffe" in out, f"should watch generic animal: {out}";
    assert "Maple Elementary watches Leo" in out, f"should watch lion: {out}";
    assert "Maple Elementary watches Polly" in out, f"should watch parrot: {out}";

    # School group must NOT trigger any feeding output.
    assert "fed meat" not in out, f"school group should not feed meat: {out}";
    assert "fed seed" not in out, f"school group should not feed seed: {out}";
    assert "fed standard feed" not in out, f"school group should not feed standard: {out}";

    # Confirm no animal was marked fed by the school group's traversal.
    cur = root;
    for _ in range(0, 5) {
        kids = [cur-->];
        if not kids {
            break;
        }
        n = kids[0];
        if isinstance(n, (Lion, Parrot, Animal)) {
            assert n.fed == False, f"{type(n).__name__} {n.name} should NOT be fed by SchoolGroup";
        }
        cur = n;
    }
}

test "graph shape mirrors the demo park layout" {
    build_park();

    # Root should have exactly one direct child (the kiosk) — the rest is a chain.
    root_kids = [root-->];
    assert len(root_kids) == 1, f"root should have 1 direct child, got {len(root_kids)}";

    kiosk = root_kids[0];
    assert isinstance(kiosk, Kiosk), f"root's only child should be Kiosk, got {type(kiosk)}";

    # Walk the chain and confirm names in order.
    expected_names = ["Giraffe", "Leo", "Polly", "Zebra"];
    cur = kiosk;
    seen = [];
    for _ in range(0, 10) {
        kids = [cur-->];
        if not kids {
            break;
        }
        cur = kids[0];
        seen.append(cur.name);
    }
    assert seen == expected_names, f"chain order mismatch: {seen} vs {expected_names}";
}

