}


test "stations above 40 C are flagged and violation_count increments" {
    grill = Grill(name="Grill #1", temperature=185.0);
    fryer = Fryer(name="Fryer #2", temperature=160.0);
    cold = ColdPrep(name="Salad Cold Prep", temperature=4.0);
    root ++> grill ++> fryer ++> cold;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Inspector();
    }

    assert grill.violation_count == 1, f"grill should have 1 violation, got {grill.violation_count}";
    assert fryer.violation_count == 1, f"fryer should have 1 violation, got {fryer.violation_count}";
    assert cold.violation_count == 0, f"cold prep should have 0 violations, got {cold.violation_count}";
    out = buf.getvalue();
    assert "VIOLATION at 'Grill #1': 185.0 C exceeds 40 C (total violations: 1)" in out, f"missing grill violation line: {out}";
    assert "VIOLATION at 'Fryer #2': 160.0 C exceeds 40 C (total violations: 1)" in out, f"missing fryer violation line: {out}";
    assert "OK: 'Salad Cold Prep' at 4.0 C" in out, f"missing cold prep OK line: {out}";
}


test "every station gets both a log_visit and a temperature check" {
    grill = Grill(name="Grill Z", temperature=185.0);
    fryer = Fryer(name="Fryer Z", temperature=160.0);
