    root ++> grill ++> fryer ++> cold;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Inspector();
    }
    out = buf.getvalue();

    # One visit log per station (3 total), using the overridden format per subclass.
    assert "grill station 'Grill Z' logged" in out, f"missing grill visit log: {out}";
    assert "fryer station 'Fryer Z' logged" in out, f"missing fryer visit log: {out}";
    assert "cold-prep station 'Cold Z' logged" in out, f"missing cold prep visit log: {out}";
    # And one temperature verdict per station.
    assert "VIOLATION at 'Grill Z'" in out, f"missing grill temperature verdict: {out}";
    assert "VIOLATION at 'Fryer Z'" in out, f"missing fryer temperature verdict: {out}";
    assert "OK: 'Cold Z'" in out, f"missing cold prep temperature verdict: {out}";
