    assert "Crypto Vault" not in out, f"Sam must not reach Crypto Vault: {out}";
}

test "exactly enough clearance grants every room" {
    # Same clearance as the highest required level — boundary case.
    root ++> Room(name="Lobby", required_level=0)
        ++> Room(name="Storage", required_level=1)
        ++> Room(name="App Servers", required_level=2)
        ++> Room(name="Database Tier", required_level=3)
        ++> Room(name="Crypto Vault", required_level=5);

    boundary = Technician(name="Riley", clearance=5);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn boundary;
    }
    out = buf.getvalue();

    assert boundary.rooms_visited == 5, f"expected 5 rooms, got {boundary.rooms_visited}";
    assert boundary.denied == False, f"expected denied=False, got {boundary.denied}";
    assert "[DENIED]" not in out, f"clearance-equal-to-max must never deny: {out}";
