test "denied technician never visits a room needing lower clearance later" {
    # A denied tech must end immediately — they cannot bounce into another
    # room just because that later room would have admitted them.
    root ++> Room(name="Lobby", required_level=0)
        ++> Room(name="Storage", required_level=1)
        ++> Room(name="App Servers", required_level=2)
        ++> Room(name="Database Tier", required_level=3)
        ++> Room(name="Crypto Vault", required_level=5);

    tech = Technician(name="Pat", clearance=2);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn tech;
    }
    out = buf.getvalue();

    # Pat reaches Database Tier, gets denied there. Even though the next
    # room is unreachable behind the denial, the walker must disengage —
    # rooms_visited must NOT advance beyond 3.
    assert tech.rooms_visited == 3, f"expected exactly 3 rooms, got {tech.rooms_visited}";
    assert tech.denied == True, f"expected denied=True, got {tech.denied}";
    # Confirm only three GRANTED lines were logged.
    granted_count = out.count("[GRANTED] Pat");
    assert granted_count == 3, f"expected 3 grant lines, got {granted_count}: {out}";
    # And exactly one DENIED line for Pat.
    denied_count = out.count("[DENIED] Pat");
    assert denied_count == 1, f"expected 1 denial line, got {denied_count}: {out}";
}

