    leg_lines = [ln for ln in out.splitlines() if ln.startswith("  [")];
    assert len(leg_lines) == 6, f"expected 6 route audits, got {len(leg_lines)}: {out}";

    # Every leg line must mention its specific title and weight.
    for needle in [
