    [root -->][0] +>:Serves:+> s_low1;
    d_b +>:Serves:+> s_low2;
    d_b +>:Serves:+> s_low3;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn StockAuditor();
    }
