    assert "[LOW] Low A" in out, f"missing [LOW] Low A in output: {out}";
    assert "[LOW] Low B" in out, f"missing [LOW] Low B in output: {out}";
    assert "[LOW] Boundary" in out, f"missing [LOW] Boundary in output: {out}";
}

