    assert "[OK] linker: 8 min" in out, f"missing linker line: {out}";
    assert "[OK] codegen: 12 min" in out, f"missing codegen line: {out}";
    assert "[BLOCKED] compiler: 15 min" in out, f"missing compiler line: {out}";
    # 5 + 10 + 8 + 12 + 15 = 50, NOT 50 + duplicates from diamond convergence
    assert auditor.total_minutes == 50, f"diamond double-counted: got {auditor.total_minutes}, want 50";
    assert len(auditor.visited_titles) == 5, f"visited count off: {auditor.visited_titles}";
