    assert "[BLOCKED] beta: 6 min" in out, f"missing beta BLOCKED line: {out}";
    assert "[BLOCKED] gamma: 7 min" in out, f"missing gamma BLOCKED line: {out}";
    # gamma only counted once even though reached via two parent edges
    assert auditor.total_minutes == 17, f"got {auditor.total_minutes}, want 17";
    assert len(auditor.visited_titles) == 3, f"visited: {auditor.visited_titles}";
}

