import io;
import from contextlib { redirect_stdout }

# Test 1: stable_id assignment is unique and formatted correctly, persisted flips True
test "stable id assignment and persisted flag" {
    root ++> Warehouse(name="W1");
    w1 = [root -->][?Warehouse][0];
    w1 +>:Stocks(aisle="A1"):+> Item(sku="SKU-001", qty=42);
    w1 +>:Stocks(aisle="A2"):+> Item(sku="SKU-002", qty=7);
    w1 +>:Stocks(aisle="A3"):+> Item(sku="SKU-003", qty=120);

    items = [w1 ->:Stocks:->][?Item];
    assert len(items) == 3, f"expected 3 items, got {len(items)}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = Auditor();
        root spawn auditor;
    }

    # Every item must have a unique stable_id, formatted ITEM-XXXX
    sids = [];
    for it in items {
        assert it.persisted == True, f"item {it.sku} not persisted";
        assert it.stable_id.startswith("ITEM-"), f"bad stable_id {it.stable_id}";
        sids.append(it.stable_id);
    }
    # uniqueness
    assert len(set(sids)) == len(sids), f"duplicate stable_ids: {sids}";
    # counter-driven format: ITEM-0001 .. ITEM-0003
    assert "ITEM-0001" in sids, f"missing ITEM-0001 in {sids}";
    assert "ITEM-0002" in sids, f"missing ITEM-0002 in {sids}";
    assert "ITEM-0003" in sids, f"missing ITEM-0003 in {sids}";
}

# Test 2: storage dict on walker is populated with the same records as items
test "storage dict populated with all items" {
    root ++> Warehouse(name="W1");
    w1 = [root -->][?Warehouse][0];
    w1 +>:Stocks(aisle="A1"):+> Item(sku="SKU-A", qty=5);
    w1 +>:Stocks(aisle="A2"):+> Item(sku="SKU-B", qty=10);

    auditor = Auditor();
    root spawn auditor;

    assert len(auditor.storage) == 2, f"expected 2 storage records, got {len(auditor.storage)}";

    # storage values must mirror each item's sku and qty and stable_id
    items = [w1 ->:Stocks:->][?Item];
    sids = [it.stable_id for it in items];
    for sid in sids {
        assert sid in auditor.storage, f"{sid} missing from storage";
        rec = auditor.storage[sid];
        # find matching item by stable_id
        match_item = None;
        for it in items {
            if it.stable_id == sid { match_item = it; break; }
        }
        assert match_item != None, "internal: no matching item";
        assert rec["sku"] == match_item.sku, f"sku mismatch for {sid}";
        assert rec["qty"] == match_item.qty, f"qty mismatch for {sid}";
        assert rec["stable_id"] == sid, f"stable_id mismatch in record";
    }
}

