"""Tests for the build-system circular dependency detector."""

import io;
import from contextlib { redirect_stdout }

# Helper: spawn CycleFinder on a freshly built graph and capture stdout.
def run_finder {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = Root() spawn CycleFinder();
    }
    return buf.getvalue();
}

# A -> B -> A is the canonical two-node cycle.
test "two-node cycle in dependency graph is reported" {
    rt = Root();
    a = Module(name="a");
    b = Module(name="b");
    rt ++> a ++> b;
    a +>:DependsOn:+> b;
    b +>:DependsOn:+> a;

    out = io.StringIO();
    with redirect_stdout(out) {
        res = rt spawn CycleFinder();
    }
    captured = out.getvalue();

    assert "CYCLE DETECTED" in captured, f"missing cycle marker: {captured}";
    # Path must include both modules and close back to a.
    assert "a -> b -> a" in captured, f"wrong cycle path: {captured}";
    assert res.reported is True, f"walker.reported should be True, got {res.reported}";
}

# A self-edge on a module: "lone -> lone" is a cycle.
test "self-dependency is detected as a cycle" {
    rt = Root();
    lone = Module(name="lone");
    rt ++> lone;
    lone +>:DependsOn:+> lone;

    out = io.StringIO();
    with redirect_stdout(out) {
        res = rt spawn CycleFinder();
    }
    captured = out.getvalue();

    assert "CYCLE DETECTED" in captured, f"missing cycle marker: {captured}";
    assert "lone -> lone" in captured, f"self-cycle path wrong: {captured}";
    assert res.reported is True, f"walker.reported should be True, got {res.reported}";
}

# A linear chain with no back-edges: nothing should be reported.
test "acyclic dependency graph produces no cycle report" {
    rt = Root();
    a = Module(name="alpha");
    b = Module(name="beta");
    c = Module(name="gamma");
    rt ++> a ++> b ++> c;
    a +>:DependsOn:+> b;
    b +>:DependsOn:+> c;

    out = io.StringIO();
    with redirect_stdout(out) {
        res = rt spawn CycleFinder();
    }
    captured = out.getvalue();

    assert "CYCLE DETECTED" not in captured, f"false cycle: {captured}";
    assert res.reported is False, f"walker.reported should be False, got {res.reported}";
}

# A long chain that exceeds the depth cap must halt cleanly without
# spuriously flagging a cycle.
test "depth cap halts traversal without false cycle report" {
    rt = Root();
    head = Module(name="head");
    rt ++> head;
    current = head;
    names = ["n0", "n1", "n2", "n3", "n4", "n5", "n6", "n7", "n8",
             "n9", "n10", "n11", "n12", "n13", "n14", "n15",
             "n16", "n17", "n18", "n19", "n20", "n21", "n22", "n23",
             "n24", "n25", "n26", "n27", "n28", "n29", "n30", "n31",
             "n32", "n33", "n34"];
    for nm in names {
        nxt = Module(name=nm);
        current +>:DependsOn:+> nxt;
        current = nxt;
    }

    out = io.StringIO();
    with redirect_stdout(out) {
        res = rt spawn CycleFinder();
    }
    captured = out.getvalue();

    assert "CYCLE DETECTED" not in captured, f"false cycle on long chain: {captured}";
    assert "depth cap" in captured, f"depth cap message missing: {captured}";
    assert res.reported is False, f"walker.reported should be False, got {res.reported}";
}

# A cycle buried deeper in the graph must still be found and reported.
test "cycle nested behind two acyclic hops is detected" {
    rt = Root();
    a = Module(name="a");
    b = Module(name="b");
    c = Module(name="c");
    d = Module(name="d");
    rt ++> a ++> b ++> c ++> d;
    a +>:DependsOn:+> b;
    b +>:DependsOn:+> c;
    c +>:DependsOn:+> d;
    d +>:DependsOn:+> c;

    out = io.StringIO();
    with redirect_stdout(out) {
        res = rt spawn CycleFinder();
    }
    captured = out.getvalue();

    assert "CYCLE DETECTED" in captured, f"missing cycle marker: {captured}";
    # Cycle must close back to c and include d.
    assert "c -> d -> c" in captured, f"wrong cycle path: {captured}";
    assert res.reported is True, f"walker.reported should be True, got {res.reported}";
}

