"""Regression tests for the build dependency auditor.

The problem promise:
- diamond dependency graph (shared libs under multiple parents)
- sum of build minutes across all tasks
- a task reachable by multiple paths is counted exactly once
"""

import io;
import from contextlib { redirect_stdout }

def make_diamond {
    app = Task(title="app", minutes=5);
    parser = Task(title="parser", minutes=10);
    renderer = Task(title="renderer", minutes=8);
    libcore = Task(title="libcore", minutes=20);
    codec = Task(title="codec", minutes=6);
    root ++> app ++> parser ++> libcore;
    root ++> renderer ++> libcore;
    parser ++> codec;
    renderer ++> codec;
    return [app, parser, renderer, libcore, codec];
}

test "diamond counts each task exactly once and skips repeats" {
    nodes = make_diamond();
    buf = io.StringIO();
    auditor = Auditor();
    with redirect_stdout(buf) {
        root spawn auditor;
    }
    out = buf.getvalue();

    # Sum of unique tasks: 5 + 10 + 8 + 20 + 6 = 49
    assert auditor.total_minutes == 49, f"expected 49 unique minutes, got {auditor.total_minutes}";

    # libcore is reachable from both parser and renderer -> must be counted once.
    assert out.count("[audit] libcore") == 1, f"libcore audited more than once:\n{out}";

    # codec is reachable from both parser and renderer -> must be counted once.
    assert out.count("[audit] codec") == 1, f"codec audited more than once:\n{out}";

    # libcore must be skipped on the second arrival (parser path vs renderer path).
    assert "[skip ] libcore already counted" in out, f"expected libcore skip log:\n{out}";
    assert "[skip ] codec already counted" in out, f"expected codec skip log:\n{out}";

    # Every distinct task got an audit line exactly once.
    for n in nodes {
        assert out.count(f"[audit] {n.title}") == 1, f"{n.title} audited != 1 time:\n{out}";
    }
}

test "naive count of all reachable tasks is higher than audited total" {
    # Demonstrates the diamond actually exists: if we summed every visit,
    # we'd get more than the audited total because libcore/codec are hit twice.
    nodes = make_diamond();
    buf = io.StringIO();
    auditor = Auditor();
    with redirect_stdout(buf) {
        root spawn auditor;
    }
    out = buf.getvalue();

    audit_lines = 0;
    skip_lines = 0;
    for line in out.split("\n") {
        if line.startswith("[audit]") {
            audit_lines = audit_lines + 1;
        } elif line.startswith("[skip ]") {
            skip_lines = skip_lines + 1;
        }
    }

    # 5 unique tasks audited, and at least 2 skips (libcore + codec each revisited).
    assert audit_lines == 5, f"expected 5 audit lines, got {audit_lines}:\n{out}";
    assert skip_lines >= 2, f"expected >=2 skip lines from diamond, got {skip_lines}:\n{out}";

    # The audited total must be strictly less than the sum of every arrival
    # (i.e. dedup is actually doing work).
    every_arrival = 5 + 10 + 8 + 20 + 20 + 6 + 6;
    assert auditor.total_minutes < every_arrival, (
        f"auditor did not dedup: total={auditor.total_minutes}, raw={every_arrival}"
    );
}

test "audited total equals sum of minutes of unique visited tasks" {
    nodes = make_diamond();
    auditor = Auditor();
    root spawn auditor;

    expected = 0;
    for n in nodes {
        if n.title in auditor.visited {
            expected = expected + n.minutes;
        }
    }
    assert auditor.total_minutes == expected, (
        f"total_minutes={auditor.total_minutes} != sum over visited={expected}"
    );
    # And every task's title ended up in visited exactly once.
    assert len(auditor.visited) == len(nodes), (
        f"visited length {len(auditor.visited)} != tasks {len(nodes)}: {auditor.visited}"
    );
}

test "two independent tasks with no shared dependency sum cleanly" {
    # Sanity check the auditor on a non-diamond graph: each task visited once,
    # no skips, total = sum of minutes.
    a = Task(title="alpha", minutes=3);
    b = Task(title="beta", minutes=7);
    c = Task(title="gamma", minutes=11);
    root ++> a ++> b;
    root ++> c;

    buf = io.StringIO();
    auditor = Auditor();
    with redirect_stdout(buf) {
        root spawn auditor;
    }
    out = buf.getvalue();

    assert auditor.total_minutes == 3 + 7 + 11, f"got {auditor.total_minutes}";
    assert "[skip ]" not in out, f"unexpected skip in linear graph:\n{out}";
    assert out.count("[audit]") == 3, f"expected 3 audit lines:\n{out}";
}

