"""Vending machine controller: model states as nodes and feed a sequence of inputs via a walker."""

node Idle {
    has name: str = "idle";
    has is_accepting: bool = True;
    has is_terminal: bool = False;
}

node Waiting {
    has name: str = "waiting";
    has is_accepting: bool = True;
    has is_terminal: bool = False;
}

node Vend {
    has name: str = "vend";
    has is_accepting: bool = False;
    has is_terminal: bool = True;
}

walker Controller {
    has inputs: list[str] = [];

    can start with Root entry {
        print(f"Starting with inputs: {self.inputs}");
        visit [-->] else { disengage; }
    }

    can drive with Idle entry {
        consumed = False;
        for input in self.inputs {
            if input == "coin" {
                print(f"in idle, coin inserted -> waiting");
                visit [-->] else { disengage; }
                consumed = True;
                break;
            } elif input == "button" {
                print(f"in idle, button pressed -> idle (no change)");
            } else {
                print(f"in idle, no transition for '{input}' -> idle");
            }
        }
        if not consumed {
            print(f"ended in state: {here.name}");
        }
    }

    can drive_wait with Waiting entry {
        for input in self.inputs {
            if input == "coin" {
                print(f"in waiting, coin inserted -> waiting");
            } elif input == "button" {
                print(f"in waiting, button pressed -> vend");
                visit [-->] else { disengage; }
                return;
            } else {
                print(f"in waiting, no transition for '{input}' -> waiting");
            }
        }
        print(f"ended in state: {here.name}");
    }

    can arrive with Vend entry {
        print(f"reached terminal state: {here.name}");
    }
}

with entry {
    inputs = ["coin", "coin", "button", "coin"];
    root ++> Idle(name="idle")
        ++> Waiting(name="waiting")
        ++> Vend(name="vend");
    root spawn Controller(inputs=inputs);
}

