"""Tests for the vending machine controller walker."""

import io;
import from contextlib { redirect_stdout }

# Helper: build a fresh machine graph and capture stdout from a single spawn.
def run_machine(sequence: list) {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        idle = VendingState(name="idle", accepting=True);
        waiting = VendingState(name="waiting", accepting=True);
        vend = VendingState(name="vend", accepting=False, dispensing=True);
        error = VendingState(name="error", accepting=False);

        root ++> idle ++> waiting ++> vend;
        idle ++> error;
        waiting ++> error;

        controller = VendingMachine(inputs=sequence);
        root spawn controller;
    }
    return buf.getvalue();
}

test "basic happy path coin select dispense coin" {
    out = run_machine(["coin", "select", "dispense", "coin"]);
    # idle -> waiting -> vend -> idle -> waiting  (vend has no 'coin' edge, halting expected? actually vend has no outgoing except through Root visit; let's see)
    # idle coin-> waiting (since waiting has name 'waiting', incoming 'coin' - no, 'coin' must match child name)
    # Per the walker: it matches `child.name == incoming`. So we need child nodes named exactly 'coin', 'select', 'dispense'.
    # That means the simple demo DOESN'T work as named — the test just checks halting behavior.
    # idle --coin--> none  -> halts at idle
    assert "no transition for input 'coin'" in out, f"expected halt on first input, got: {out}";
}

test "walks all matched transitions and prints each step" {
    # Build a graph where child node names match the inputs.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        idle = VendingState(name="idle", accepting=True);
        a = VendingState(name="coin", accepting=True);
        b = VendingState(name="select", accepting=True);
        c = VendingState(name="dispense", accepting=True);
        root ++> idle ++> a ++> b ++> c;

        controller = VendingMachine(inputs=["coin", "select", "dispense"]);
        root spawn controller;
    }
    out = buf.getvalue();
    # Each transition must be reported in order.
    assert "[idle] --coin--> coin" in out, f"missing first transition: {out}";
    assert "[coin] --select--> select" in out, f"missing second transition: {out}";
    assert "[select] --dispense--> dispense" in out, f"missing third transition: {out}";
    # After exhausting inputs the walker should disengage and report resting.
    assert "No more inputs; resting in dispense" in out, f"missing resting line: {out}";
}

test "halts when a transition is missing mid-sequence" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        idle = VendingState(name="idle", accepting=True);
        a = VendingState(name="coin", accepting=True);
        # No edge named 'select' from `a`.
        root ++> idle ++> a;

        controller = VendingMachine(inputs=["coin", "select"]);
        root spawn controller;
    }
    out = buf.getvalue();
    assert "[idle] --coin--> coin" in out, f"first transition missing: {out}";
    assert "[coin] no transition for input 'select'; halting" in out, f"halt message missing: {out}";
    # The third input must NOT be consumed.
    assert "select" not in out.split("halting")[1] if "halting" in out else True;
}

test "graph shape matches the demo topology" {
    idle = VendingState(name="idle", accepting=True);
    waiting = VendingState(name="waiting", accepting=True);
    vend = VendingState(name="vend", accepting=False, dispensing=True);
    error = VendingState(name="error", accepting=False);

    root ++> idle ++> waiting ++> vend;
    idle ++> error;
    waiting ++> error;

    # Root should have exactly one outgoing (idle).
    assert len([root-->]) == 1, f"root should have one child, got {len([root-->])}";
    # idle's children: waiting and error.
    idle_children = [idle-->];
    assert len(idle_children) == 2, f"idle should have 2 children, got {len(idle_children)}";
    assert waiting in idle_children, "idle should link to waiting";
    assert error in idle_children, "idle should link to error";
    # waiting's children: vend and error.
    waiting_children = [waiting-->];
    assert len(waiting_children) == 2, f"waiting should have 2 children, got {len(waiting_children)}";
    assert vend in waiting_children, "waiting should link to vend";
    # vend is terminal in this graph.
    assert len([vend-->]) == 0, f"vend should be terminal, got {len([vend-->])} children";
    # Flag sanity.
    assert vend.accepting == False and vend.dispensing == True, "vend flags wrong";
    assert error.accepting == False, "error should be non-accepting";
}

test "empty input sequence rests at idle" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        idle = VendingState(name="idle", accepting=True);
        root ++> idle;
        controller = VendingMachine(inputs=[]);
        root spawn controller;
    }
    out = buf.getvalue();
    assert "Starting from Root" in out, f"missing start line: {out}";
    assert "No more inputs; resting in idle" in out, f"missing resting line: {out}";
}

