"""Tests for org chart payroll rollup walker."""

import io;
import from contextlib { redirect_stdout }

# Helper: build the sample org graph from the problem spec.
def build_sample_org {
    ceo = Employee(name="CEO", salary=200000);
    cto = Employee(name="CTO", salary=180000);
    cfo = Employee(name="CFO", salary=175000);
    eng_director = Employee(name="Eng Director", salary=160000);
    product_director = Employee(name="Product Director", salary=155000);
    finance_director = Employee(name="Finance Director", salary=150000);
    senior_engineer = Employee(name="Senior Engineer", salary=140000);
    junior_engineer = Employee(name="Junior Engineer", salary=95000);
    analyst = Employee(name="Financial Analyst", salary=85000);

    ceo +>:ReportsTo:+> cto;
    ceo +>:ReportsTo:+> cfo;
    cto +>:ReportsTo:+> eng_director;
    cto +>:ReportsTo:+> product_director;
    cfo +>:ReportsTo:+> finance_director;
    eng_director +>:ReportsTo:+> senior_engineer;
    eng_director +>:ReportsTo:+> junior_engineer;
    finance_director +>:ReportsTo:+> analyst;

    root ++> ceo;
    return ceo;
}

test "ceo subtree rollup aggregates everyone" {
    ceo = build_sample_org();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn PayrollAuditor();
    }

    # CEO subtree: CEO + CTO + CFO + Eng Dir + Prod Dir + Fin Dir
    # + Senior Eng + Junior Eng + Analyst = 9 people.
    assert ceo.subtree_headcount == 9, f"CEO headcount expected 9, got {ceo.subtree_headcount}";

    # Sum of every salary in the chart:
    # 200000 + 180000 + 175000 + 160000 + 155000 + 150000
    # + 140000 + 95000 + 85000 = 1340000
    assert ceo.subtree_salary == 1340000, f"CEO salary expected 1340000, got {ceo.subtree_salary}";

    # CEO row should appear in the printed audit output.
    out = buf.getvalue();
    assert "CEO:" in out, f"expected CEO line in output: {out}";
    assert "subtree_salary=1340000" in out, f"missing aggregated CEO line: {out}";
    assert "subtree_headcount=9" in out, f"missing aggregated CEO headcount: {out}";
}

test "leaf nodes only count themselves" {
    leaf = Employee(name="Lone Analyst", salary=85000);
    root ++> leaf;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn PayrollAuditor();
    }

    assert leaf.subtree_salary == 85000, f"leaf subtree_salary expected 85000, got {leaf.subtree_salary}";
    assert leaf.subtree_headcount == 1, f"leaf headcount expected 1, got {leaf.subtree_headcount}";
}

test "middle manager totals include only descendants plus self" {
    # eng_director subtree: self + senior_engineer + junior_engineer
    ceo = build_sample_org();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn PayrollAuditor();
    }

    eng_director = [ceo ->:ReportsTo:-> ->:ReportsTo:->][0];
    assert eng_director.name == "Eng Director", f"unexpected node: {eng_director.name}";

    # 160000 + 140000 + 95000 = 395000
    assert eng_director.subtree_salary == 395000, f"Eng Dir salary expected 395000, got {eng_director.subtree_salary}";
    assert eng_director.subtree_headcount == 3, f"Eng Dir headcount expected 3, got {eng_director.subtree_headcount}";

    # The leaf engineers must also have been finalized.
    out = buf.getvalue();
    assert "Senior Engineer:" in out, f"missing Senior Engineer line: {out}";
    assert "Junior Engineer:" in out, f"missing Junior Engineer line: {out}";
}

test "cfo branch totals are isolated from cto branch" {
    ceo = build_sample_org();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn PayrollAuditor();
    }

    cto = [ceo ->:ReportsTo:->][0];
    cfo = [ceo ->:ReportsTo:->][1];

    # CTO branch: 180000 + 160000 + 155000 + 140000 + 95000 = 730000
    assert cto.subtree_salary == 730000, f"CTO salary expected 730000, got {cto.subtree_salary}";
    assert cto.subtree_headcount == 5, f"CTO headcount expected 5, got {cto.subtree_headcount}";

    # CFO branch: 175000 + 150000 + 85000 = 410000
    assert cfo.subtree_salary == 410000, f"CFO salary expected 410000, got {cfo.subtree_salary}";
    assert cfo.subtree_headcount == 3, f"CFO headcount expected 3, got {cfo.subtree_headcount}";

    # The two branches must sum to (CEO total minus CEO's own salary).
    branch_sum = cto.subtree_salary + cfo.subtree_salary;
    assert branch_sum == 1140000, f"branch sum expected 1140000, got {branch_sum}";
    assert branch_sum + ceo.salary == ceo.subtree_salary, "branches must reconcile into CEO total";
}

