"""Tests for the online store checkout walker."""

import io;
import from contextlib { redirect_stdout }

def run_checkout(items: list) -> dict {
    buf = io.StringIO();
    root ++> items[0];
    for i in range(1, len(items)) {
        items[i - 1] ++> items[i];
    }
    cashier = Checkout();
    with redirect_stdout(buf) {
        res = root spawn cashier;
    }
    cashier.total = cashier.subtotal + cashier.shipping_total + cashier.handling_total;
    return {
        "line_items": res.line_items,
        "subtotal": res.subtotal,
        "shipping_total": res.shipping_total,
        "handling_total": res.handling_total,
        "total": cashier.total,
        "out": buf.getvalue(),
    };
}

test "PaperBook shipping and handling math" {
    pb = PaperBook(name="Test Book", price=10.00, weight_lb=2.0);
    r = run_checkout([pb]);
    # shipping = 3.50 + 1.25*2.0 = 6.00 ; handling = 1.00 ; line = 17.00
    assert r["line_items"][0]["ship"] == 6.00, f"ship got {r['line_items'][0]['ship']}";
    assert r["line_items"][0]["handle"] == 1.00, f"handle got {r['line_items'][0]['handle']}";
