import io;
import from contextlib { redirect_stdout }

test "checkout full cart produces itemized receipt" {
    root ++> PaperBook(name="Dune", price=12.99, weight_lb=1.2);
    root ++> DigitalBook(name="Neuromancer", price=8.50, size_mb=4.2);
    root ++> Electronics(name="Headphones", price=89.00, warranty_months=24);
    root ++> Clothing(name="Hoodie", price=45.00, size="L");
    root ++> Clothing(name="Jacket", price=120.00, size="XL");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Checkout();
    }
    out = buf.getvalue();

    assert "----- Receipt -----" in out, f"missing receipt header: {out}";
    assert "Subtotal: $275.49" in out, f"subtotal wrong: {out}";
    # Dune 2.50 + 0.75*1.2 + 0.99 = 4.39
    # Neuromancer 0
    # Headphones 9.99 + 1.50 + 0.25*24 = 9.99 + 1.50 + 6.00 = 17.49
    # Hoodie 4.99 (< $50)
    # Jacket 0.00 (>= $50)
    # Total shipping = 4.39 + 0 + 17.49 + 4.99 + 0 = 26.87
    assert "Shipping: $26.87" in out, f"shipping wrong: {out}";
    # Total = 275.49 + 26.87 = 302.36
    assert "Total:    $302.36" in out, f"grand total wrong: {out}";
    assert len(res.lines) == 5, f"expected 5 line items, got {len(res.lines)}";
    assert abs(res.subtotal - 275.49) < 1e-6, f"walker subtotal: {res.subtotal}";
    assert abs(res.shipping - 26.87) < 1e-6, f"walker shipping: {res.shipping}";
}

test "digital books have no shipping or handling" {
    root ++> DigitalBook(name="Ebook1", price=9.99, size_mb=3.0);
    root ++> DigitalBook(name="Ebook2", price=15.00, size_mb=10.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Checkout();
    }
    out = buf.getvalue();

    assert "ship $ 0.00" in out, f"digital should show zero shipping: {out}";
    assert res.shipping == 0.0, f"digital shipping should be 0, got {res.shipping}";
    assert abs(res.subtotal - 24.99) < 1e-6, f"subtotal: {res.subtotal}";
    assert "Total:    $24.99" in out, f"total wrong: {out}";
}

test "clothing free shipping threshold at $50" {
    # cheap shirt: flat $4.99
    root ++> Clothing(name="Tee", price=20.00, size="S");
    # expensive coat: free shipping
    root ++> Clothing(name="Coat", price=200.00, size="XL");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Checkout();
    }
    out = buf.getvalue();

    # Two line items, sum of shipping should be 4.99
    assert res.shipping == 4.99, f"clothing shipping: {res.shipping}";
    assert abs(res.subtotal - 220.00) < 1e-6, f"subtotal: {res.subtotal}";
    assert "Total:    $224.99" in out, f"total wrong: {out}";
    # The expensive item's line should show $0.00 shipping
    assert "$ 0.00" in out, f"coat should show free shipping: {out}";
}

test "paper book shipping scales with weight" {
    root ++> PaperBook(name="Light", price=10.00, weight_lb=0.5);
    root ++> PaperBook(name="Heavy", price=10.00, weight_lb=4.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Checkout();
    }
    out = buf.getvalue();

    # Light: 2.50 + 0.75*0.5 + 0.99 = 2.50 + 0.375 + 0.99 = 3.865
    # Heavy: 2.50 + 0.75*4.0 + 0.99 = 2.50 + 3.00 + 0.99 = 6.49
    # Total shipping = 3.865 + 6.49 = 10.355
    expected = (2.50 + 0.75 * 0.5 + 0.99) + (2.50 + 0.75 * 4.0 + 0.99);
    assert abs(res.shipping - expected) < 1e-6, f"paper shipping: {res.shipping} vs {expected}";
    assert "handling $0.99" in out, f"paper handling fee missing: {out}";
    assert "Total:    $30.36" in out, f"grand total wrong: {out}";
}

test "electronics warranty adds to handling surcharge" {
    root ++> Electronics(name="Gadget", price=50.00, warranty_months=12);
    root ++> Electronics(name="BigGadget", price=50.00, warranty_months=0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Checkout();
    }
    out = buf.getvalue();

    # Gadget: ship 9.99, handling 1.50 + 0.25*12 = 4.50, total ship 14.49
    # BigGadget: ship 9.99, handling 1.50 + 0.25*0 = 1.50, total ship 11.49
    # Combined: 25.98
    expected = (9.99 + 1.50 + 0.25 * 12) + (9.99 + 1.50 + 0.25 * 0);
    assert abs(res.shipping - expected) < 1e-6, f"electronics shipping: {res.shipping} vs {expected}";
    assert abs(res.subtotal - 100.00) < 1e-6, f"subtotal: {res.subtotal}";
    # Each electronics line should show the $9.99 insured ship
    assert out.count("$ 9.99") == 2, f"expected two $9.99 ship lines: {out}";
    assert "Total:    $125.98" in out, f"total wrong: {out}";
}

