``merge_tags`` re-parents a source tag's children to the target tag, and if
the source happens to be the parent of the target, the survivor ends up
pointing at itself (parent_id == id). The sibling ``set_tag_parent`` already
rejects this with a ``tag_cycle`` error after walking the ancestor chain;
the merge path must mirror that guard.

The demo builds a small tag graph (zfs root -> homelab child -> two leaves),
then walks the ancestry from each leaf to surface the cycle as a list of
``Tag`` node ids — exactly the ancestor walk the original ``set_tag_parent``
guard performs.
"""

node Tag {
    has tag_id: int = 0;
    has label: str = "";
}

edge ChildOf {
    has order: int = 0;
}

walker AncestryAuditor {
    has trace: list[int] = [];

    can start with Root entry {
        visit [->:ChildOf:->];
    }

    can climb with Tag entry {
        # Record the current tag's id, then walk upward to its parent.
        # Guard against the self-cycle: if ChildOf points back to the
        # same node we just recorded, that's the bug the merge introduced.
        if self.trace.count(here.tag_id) > 0 {
            self.trace.append(here.tag_id);
            print(f"CYCLE detected at tag {here.tag_id}: trace = {self.trace}");
            disengage;
        }
        self.trace.append(here.tag_id);
        print(f"visited tag {here.tag_id} ({here.label}); trace so far = {self.trace}");
        visit [here->:ChildOf:->];
    }

    can climb with Tag exit {
        # Dead-end (root tag with no ChildOf) — nothing to do, just report.
        print(f"rooted at tag {here.tag_id} ({here.label})");
    }
}

walker MergeGuard {
    has source_id: int = 0;
    has target_id: int = 0;

    can start with Root entry {
        # Walk all tags, perform the merge-style re-parent, then audit.
        visit [->:ChildOf:->];
    }

    can merge with Tag entry {
        if here.tag_id == self.source_id {
            print(f"merge: source tag {self.source_id} is being folded into target {self.target_id}");
        }
        visit [->:ChildOf:->];
    }
}

with entry {
    # Build the taxonomy:
    #   zfs(2) --ChildOf--> homelab(1) --ChildOf--> backup(10)
    #                                     \--ChildOf--> snapshot(11)
    zfs = Tag(tag_id=2, label="zfs");
    homelab = Tag(tag_id=1, label="homelab");
    backup = Tag(tag_id=10, label="backup");
    snapshot = Tag(tag_id=11, label="snapshot");

    # Parent-of relationships (child --ChildOf--> parent).
    homelab +>:ChildOf:+> zfs;
    backup +>:ChildOf:+> homelab;
    snapshot +>:ChildOf:+> homelab;

    root ++> zfs ++> homelab ++> backup;
    root ++> snapshot;

    print("--- audit: walk ancestor chain from backup ---");
    backup spawn AncestryAuditor();

    print("--- audit: walk ancestor chain from snapshot ---");
    snapshot spawn AncestryAuditor();

    print("--- merge guard: try merge_tags(source=2 /*zfs*/, target=1 /*homelab*/) ---");
    print("expected: set_tag_parent-style rejection (tag_cycle) or null out survivor's parent");
    print("actual in buggy code: homelab.parent_id == homelab.id (self-cycle)");

    # Demonstrate the buggy merge by simulating it: re-wire homelab's
    # ChildOf edge so it points at itself, then re-audit to surface the cycle.
    print("--- simulating buggy merge: homelab now points at itself ---");
    # Disconnect homelab's existing ChildOf edge to zfs, then add a self-edge.
    homelab del ->:ChildOf:-> zfs;
    homelab +>:ChildOf:+> homelab;

    print("--- re-audit from backup after the buggy merge ---");
    backup spawn AncestryAuditor();
}

fixed.code:
"""Tag taxonomy: model the parent-child tag merge that can create a self-cycle.

The issue: ``merge_tags(source=parent_of_target, target=child)`` rewrites the
child's ``parent_id`` from ``source`` to ``target`` — so the child ends up
pointing at itself. The sibling ``set_tag_parent`` would raise ``tag_cycle``
on the same condition; the merge path does not.

This demo models the taxonomy as a graph: Tag nodes connected by a typed
``ParentOf`` edge. A walker that mimics ``set_tag_parent`` rejects any move
that would create a cycle (including a self-loop). A second walker mimics the
buggy ``merge_tags`` flow — it re-parents the source's children onto the
target, which is the exact mutation the issue complains about. A third walker
audits the graph for the invariant that the merge path broke: ``parent_id !=
id`` for every tag.
"""

node Tag {
    has name: str = "";
    has tag_id: int = 0;
    has parent_id: int = -1;
}

edge ParentOf { has since: str = ""; }

walker SetParent {
    """Mirror of ``set_tag_parent``: rejects self- and ancestor-cycles."""

    has target_id: int = 0;
    has new_parent_id: int = 0;
    has rejected: bool = False;
    has reject_reason: str = "";

    can start with Root entry {
        visit [-->];
    }

    can attempt with Tag entry {
        if here.tag_id != self.target_id {
            visit [-->];
            return;
        }
        if self.new_parent_id == here.tag_id {
            self.rejected = True;
            self.reject_reason = "tag_cycle(self)";
            disengage;
        }
        here.parent_id = self.new_parent_id;
        visit [-->];
    }
}

walker MergeTags {
    """Mirror of the buggy ``merge_tags``: re-parents source's children to target.

    When the merge source is the parent of the target, the UPDATE
    ``UPDATE tags SET parent_id = ? WHERE parent_id = ?`` rewrites the
    target's own ``parent_id`` from ``source_id`` to ``target_id`` — a
    self-cycle that this walker reproduces faithfully. The fix is *not*
    applied here on purpose: the demo shows the bug.
    """

    has source_id: int = 0;
    has target_id: int = 0;
    has moved: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can merge with Tag entry {
        if here.tag_id == self.source_id {
            visit [-->];
            return;
        }
        if here.parent_id == self.source_id {
            here.parent_id = self.target_id;
            self.moved += 1;
        }
        visit [-->];
    }
}

walker CycleAudit {
    """Walk the tag graph and assert the invariant: ``parent_id != tag_id``.

    This is the check the issue says is missing on the merge path.
    """

    has violations: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Tag entry {
        if here.parent_id == here.tag_id {
            self.violations.append(here.name);
        }
        visit [-->];
    }
}

with entry {
    zfs = Tag(name="zfs", tag_id=2, parent_id=-1);
    homelab = Tag(name="homelab", tag_id=1, parent_id=2);
    self_hosted = Tag(name="self-hosted", tag_id=3, parent_id=1);
    docker = Tag(name="docker", tag_id=4, parent_id=1);
    ansible = Tag(name="ansible", tag_id=5, parent_id=1);

    zfs +>:ParentOf:+> homelab;
    homelab +>:ParentOf:+> self_hosted;
    homelab +>:ParentOf:+> docker;
    homelab +>:ParentOf:+> ansible;
    root ++> zfs ++> homelab;

    print("=== baseline: set_tag_parent rejects self-cycle ===");
    sp = SetParent(target_id=2, new_parent_id=2);
    root spawn sp;
    print(f"rejected={sp.rejected} reason={sp.reject_reason}");

    print("\n=== buggy merge: source=parent_of_target, target=child ===");
    mt = MergeTags(source_id=2, target_id=1);
    root spawn mt;
    print(f"moved={mt.moved}");
    print(f"after merge: homelab.parent_id={homelab.parent_id} (self-cycle if == 1)");

    print("\n=== invariant audit: parent_id != tag_id for every tag ===");
    audit = CycleAudit();
    root spawn audit;
    print(f"violations={audit.violations}");
}

