"""Tests for tag taxonomy: self-cycle on merge vs guard on set_parent."""

import io;
import from contextlib { redirect_stdout }

test "SetParent rejects self-cycle when new_parent_id == tag_id" {
    a = Tag(name="a", tag_id=10, parent_id=-1);
    b = Tag(name="b", tag_id=20, parent_id=10);
    root ++> a;
    a +>:ParentOf:+> b;

    buf = io.StringIO();
    sp = SetParent(target_id=10, new_parent_id=10);
    with redirect_stdout(buf) {
        root spawn sp;
    }
    assert sp.rejected, f"expected rejected, got rejected={sp.rejected}";
    assert "self" in sp.reject_reason.lower() or "cycle" in sp.reject_reason.lower(), f"reason={sp.reject_reason}";
    assert a.parent_id == -1, f"parent_id should be unchanged, got {a.parent_id}";
}

test "CycleAudit on clean taxonomy reports no violations" {
    p = Tag(name="p", tag_id=1, parent_id=-1);
    c = Tag(name="c", tag_id=2, parent_id=1);
    g = Tag(name="g", tag_id=3, parent_id=2);
    root ++> p;
    p +>:ParentOf:+> c;
    c +>:ParentOf:+> g;

    buf = io.StringIO();
    audit = CycleAudit();
    with redirect_stdout(buf) {
        root spawn audit;
    }
    assert len(audit.violations) == 0, f"expected no violations, got {audit.violations}";
    assert p.parent_id != p.tag_id and c.parent_id != c.tag_id and g.parent_id != g.tag_id, "invariant broken";
}

test "MergeTags with source=parent_of_target creates self-cycle" {
    z = Tag(name="zfs", tag_id=2, parent_id=-1);
    h = Tag(name="homelab", tag_id=1, parent_id=2);
    sh = Tag(name="self-hosted", tag_id=3, parent_id=1);
    root ++> z;
    z +>:ParentOf:+> h;
    h +>:ParentOf:+> sh;

    buf = io.StringIO();
    mt = MergeTags(source_id=2, target_id=1);
    with redirect_stdout(buf) {
        root spawn mt;
    }
    assert h.parent_id == h.tag_id, f"expected self-cycle (parent_id==tag_id==1), got parent_id={h.parent_id}";

    audit = CycleAudit();
    with redirect_stdout(buf) {
        root spawn audit;
    }
    assert "homelab" in audit.violations, f"expected homelab in violations, got {audit.violations}";
    assert sh.parent_id == 1, f"child reparent should land on target_id=1, got {sh.parent_id}";
}

test "SetParent refuses the exact move MergeTags performs (asymmetry)" {
    p = Tag(name="parent", tag_id=5, parent_id=-1);
    ch = Tag(name="child", tag_id=6, parent_id=5);
    root ++> p;
    p +>:ParentOf:+> ch;

    buf = io.StringIO();
    sp = SetParent(target_id=6, new_parent_id=6);
    with redirect_stdout(buf) {
        root spawn sp;
    }
    assert sp.rejected, f"SetParent should reject self-cycle, got rejected={sp.rejected}";
    assert ch.parent_id == 5, f"SetParent should not have mutated parent_id, got {ch.parent_id}";

    mt = MergeTags(source_id=5, target_id=6);
    with redirect_stdout(buf) {
        root spawn mt;
    }
    assert ch.parent_id == ch.tag_id, f"MergeTags should have created self-cycle, got parent_id={ch.parent_id}";

    audit = CycleAudit();
    with redirect_stdout(buf) {
        root spawn audit;
    }
    assert "child" in audit.violations, f"asymmetry: set_parent guarded but merge unguarded, violations={audit.violations}";
}

