work-list. The naive Julia code mutates ``collector.objects`` (a Dict) while
iterating it, so newly inserted keys may or may not be visited depending on
rehash timing. Here we seed the work-list before traversal and use a visited
guard so double-insertion is impossible and silent skip is impossible.
"""

node Model {
    has name: str = "";
    has cascade_target: bool = True;
}

# A typed edge carries the relationship "deleting this model cascades to target".
edge CascadesTo {
    has on_delete: str = "CASCADE";
}

# Compatibility façade: build the cascade graph from a list of (parent, child) pairs,
# mirroring the public API of the source DeletionCollector.
def build_graph(pairs: list) -> object {
    root_node = Model(name="Root");
    # Use the first model created as the root if caller passed a name; else default.
    model_index = {};
    for (src, dst) in pairs {
        src_node = None;
        dst_node = None;
        if src in model_index {
            src_node = model_index[src];
        } else {
            src_node = Model(name=src);
            model_index[src] = src_node;
        }
        if dst in model_index {
            dst_node = model_index[dst];
        } else {
            dst_node = Model(name=dst, cascade_target=True);
            model_index[dst] = dst_node;
        }
        src_node +>:CascadesTo:+> dst_node;
    }
    return (root_node, model_index);
}

# The walker mirrors process_collector!: from each model it reaches, it follows
# cascade edges and accumulates targets into a list. Crucially, it snapshots
# the work-list before iterating and uses a visited set so insertion during
# traversal cannot cause double-visits or silent skips.
walker CascadeCollector {
    has visited: list = [] = [];
    has pending: list = [] = [];
    has collected: list = [] = [];

    can start with Root entry {
