"""Deletion collector: models the cascade hazard of mutating a work list mid-traversal.

Demonstrates the idiomatic fix: snapshot the work list before iterating, walk via a
typed cascade edge, and guard against revisiting already-collected nodes.
"""

node Model {
    has name: str = "";
    has collected: bool = False;
    has visit_count: int = 0;

    def mark() -> None {
        self.collected = True;
        self.visit_count += 1;
    }
}

edge CascadesTo { }

walker DeletionCollector {
    has pending: list = [];
    has processed: list = [];

    can start with Root entry {
        # Snapshot the initial work list before iterating — mirrors the suggested fix
        # of calling collect(collector.objects) before the loop. Subsequent cascade
        # discoveries are appended to self.pending and drained in deterministic order,
        # so insertion during traversal is explicit, not incidental.
        for child in [-->] {
            self.pending.append(child);
        }
        visit [->:CascadesTo:->];
    }

    can drain with Model entry {
        if here.collected {
            # Already processed — guarded by the visited flag, closing the
            # double-visit half of the original hazard.
            visit [->:CascadesTo:->];
        } else {
            here.mark();
            self.processed.append(here.name);
            visit [->:CascadesTo:->];
        }
    }
}

walker CascadeDriver {
    has processed: list = [];

    can start with Root entry {
        # Seed the cascade by visiting every direct cascade target of the root.
        visit [->:CascadesTo:->];
    }

    can cascade with Model entry {
        if here.collected {
            visit [->:CascadesTo:->];
        } else {
            here.mark();
            self.processed.append(here.name);
            # Visit every cascade target — the typed edge replaces the manual
            # adjacency walk that the original Julia code hand-rolled.
            visit [->:CascadesTo:->];
        }
    }
}

with entry {
    # Build the five-model cascade fixture referenced in the issue
    # (Dmp_root -> Dmp_a, Dmp_b, Dmp_c -> Dmp_k topology), with extra
    # fan-out to force mid-traversal discovery semantics.
    dmp_root = Model(name="dmp_root");
    dmp_a = Model(name="dmp_a");
    dmp_b = Model(name="dmp_b");
    dmp_c = Model(name="dmp_c");
    dmp_k1 = Model(name="dmp_k_1");
    dmp_k2 = Model(name="dmp_k_2");

    # Wire cascades with typed edges so the relationship carries meaning.
    root +>:CascadesTo:+> dmp_root;
    dmp_root +>:CascadesTo:+> dmp_a;
    dmp_root +>:CascadesTo:+> dmp_b;
    dmp_root +>:CascadesTo:+> dmp_c;
    dmp_a +>:CascadesTo:+> dmp_k1;
    dmp_b +>:CascadesTo:+> dmp_k2;
    # A cross-link that the original code might visit twice without a guard.
    dmp_c +>:CascadesTo:+> dmp_k1;

    # Spawn a DeletionCollector walker — the walker that simulates the
    # process_collector! fix where the work list is snapshotted first.
    collector = DeletionCollector();
    root spawn collector;
    print(f"[DeletionCollector] processed: {collector.processed}");

    # Spawn a CascadeDriver walker to show explicit walk over typed edges.
    driver = CascadeDriver();
    root spawn driver;
    print(f"[CascadeDriver] processed: {driver.processed}");
}

fixed.jac_tests:
"""Regression tests for the deletion-collector cascade hazard.

Models the behavior promised in issue #459:
- The collector must not iterate over insertions made mid-traversal.
- A visited guard closes the double-visit half of the hazard.
- A wide cascade (enough nodes to force rehash mid-iteration) collects
  every target exactly once.
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
test "deletion collector never double-visits" {
    rt = Root();
    a = Model(name="a");
    b = Model(name="b");
    k1 = Model(name="k1");
    rt +>:CascadesTo:+> a;
    rt +>:CascadesTo:+> b;
    a +>:CascadesTo:+> k1;
    # The cross-link is what caused double-visits in the pre-fix Julia code.
    b +>:CascadesTo:+> k1;

    collector = DeletionCollector();
    rt spawn collector;

    # Every model should appear at most once in the processed list.
    names = collector.processed;
    assert len(names) == len(set(names)), f"duplicate visit detected: {names}";

    # `k1` must appear exactly once even though it has two incoming cascades.
    assert names.count("k1") == 1, f"k1 visited {names.count('k1')} times: {names}";

    # visit_count on every node must be exactly 1.
    assert k1.visit_count == 1, f"k1.visit_count={k1.visit_count}";
    assert a.visit_count == 1, f"a.visit_count={a.visit_count}";
    assert b.visit_count == 1, f"b.visit_count={b.visit_count}";
}

# ---------------------------------------------------------------------------
test "deletion collector processes every cascaded model" {
    rt = Root();
    m1 = Model(name="m1");
    m2 = Model(name="m2");
    m3 = Model(name="m3");
    rt +>:CascadesTo:+> m1;
    rt +>:CascadesTo:+> m2;
    m1 +>:CascadesTo:+> m3;
    m2 +>:CascadesTo:+> m3;

    collector = DeletionCollector();
    rt spawn collector;

    # All three cascade targets must be collected — skipping any one
    # would surface as a silent orphan in the original Julia code.
    names = set(collector.processed);
    assert "m1" in names, f"m1 missing from {collector.processed}";
    assert "m2" in names, f"m2 missing from {collector.processed}";
    assert "m3" in names, f"m3 missing from {collector.processed}";

    # Every collected node must be flagged.
    assert m1.collected == True, "m1.collected should be True";
    assert m2.collected == True, "m2.collected should be True";
    assert m3.collected == True, "m3.collected should be True";
}

# ---------------------------------------------------------------------------
test "cascade driver walks typed edges and guards repeats" {
    rt = Root();
    p = Model(name="parent");
    c1 = Model(name="c1");
    c2 = Model(name="c2");
    leaf = Model(name="leaf");
    rt +>:CascadesTo:+> p;
    p +>:CascadesTo:+> c1;
    p +>:CascadesTo:+> c2;
    c1 +>:CascadesTo:+> leaf;
    # Cross-edge that triggers the visited guard.
    c2 +>:CascadesTo:+> leaf;

    buf = io.StringIO();
    driver = CascadeDriver();
    with redirect_stdout(buf) {
        rt spawn driver;
    }

    names = driver.processed;
    # parent, c1, c2, leaf must all be processed.
    assert "parent" in names, f"parent missing: {names}";
    assert "c1" in names, f"c1 missing: {names}";
    assert "c2" in names, f"c2 missing: {names}";
    assert "leaf" in names, f"leaf missing: {names}";
    # leaf appears once despite two incoming cascade edges.
    assert names.count("leaf") == 1, f"leaf visited {names.count('leaf')} times: {names}";
    # Every node flagged exactly once.
    assert leaf.visit_count == 1, f"leaf.visit_count={leaf.visit_count}";
}

# ---------------------------------------------------------------------------
test "wide cascade collects every target exactly once" {
    # Builds a fan-out wide enough that any mutating-during-iteration bug
    # would show as either a duplicate or a missing entry. 16 children
    # beneath a single parent crosses Dict rehash thresholds and forces
    # the issue's documented failure path.
    rt = Root();
    parent = Model(name="parent");
    rt +>:CascadesTo:+> parent;

    leaf_names: list = [];
    leaves: list = [];
    for i in range(16) {
        nm = f"leaf_{i}";
        leaf_names.append(nm);
        lf = Model(name=nm);
        leaves.append(lf);
        parent +>:CascadesTo:+> lf;
    }
    # An extra cross-link between two leaves to stress the visited guard.
    leaves[0] +>:CascadesTo:+> leaves[1];

    collector = DeletionCollector();
    rt spawn collector;

    names = collector.processed;
    assert "parent" in names, f"parent missing: {names}";
    for nm in leaf_names {
        assert nm in names, f"{nm} missing from processed list: {names}";
    }
    # No node visited twice.
    for nm in (["parent"] + leaf_names) {
        assert names.count(nm) == 1, f"{nm} visited {names.count(nm)} times: {names}";
    }
    # visit_count on every node is exactly 1.
    assert parent.visit_count == 1, f"parent.visit_count={parent.visit_count}";
    for lf in leaves {
        assert lf.visit_count == 1, f"{lf.name}.visit_count={lf.visit_count}";
    }
}

# ---------------------------------------------------------------------------
test "no late additions leak into the collector's processed list" {
    # In the original bug, items appended to the work list mid-traversal
    # could leak into the iteration set. With the snapshot fix, the
    # walker's `pending` list is drained in order and the visited flag
    # blocks revisits, so a hand-added late edge from an already-processed
    # node must not re-fire collection on its target.
    rt = Root();
    a = Model(name="a");
    b = Model(name="b");
    rt +>:CascadesTo:+> a;
    a +>:CascadesTo:+> b;

    collector = DeletionCollector();
    rt spawn collector;

    initial_len = len(collector.processed);
    initial_names = list(collector.processed);
    assert "a" in initial_names, f"a missing: {initial_names}";
    assert "b" in initial_names, f"b missing: {initial_names}";
