    has ordered_libs: list[str] = [];
    has ordered_paths: list[str] = [];
    has ordered_args: list[str] = [];
    has provenance: dict[str, str] = {};

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can descend with Package entry {
        visit [->:DependsOn:->];
    }

    can harvest with StaticLib entry {
        lib_label = "";
        for lib in here.libs {
