"""Tests for static-library link requirement propagation.

Verifies the behaviors the issue promises:
- ordered link plan is built in dependency-declaration order,
- duplicate requirements are merged once in semantics-preserving order,
- every library/arg requirement is annotated with its declaring wrapper,
- relative search paths are anchored to the wrapper that declared them,
- diagnostics name the wrapper whose (link ...) introduced a missing lib,
- walker targets Package/StaticLib entry abilities as declared.
"""

import io;
import from contextlib { redirect_stdout }

test "dependency-declaration order preserved" {
    sqlite_wrapper = StaticLib(
        name="sqlite-wrapper",
        libs=["sqlite3", "m"],
        search_paths=["vendor/sqlite/lib"],
        args=["-lpthread"]
    );

    raylib_wrapper = StaticLib(
        name="raylib-wrapper",
        libs=["raylib", "m"],
        search_paths=["vendor/raylib/lib"],
        args=["-ldl", "-lpthread"]
    );

    binary = Package(name="app-binary", kind="binary");

    root +>:DependsOn(declared_by="app-binary"):+> binary;
    binary +>:DependsOn(declared_by="app-binary"):+> sqlite_wrapper;
    binary +>:DependsOn(declared_by="app-binary"):+> raylib_wrapper;

    planner = LinkPlanner();
    root spawn planner;

    expected_libs = ["sqlite3", "m", "raylib"];
    expected_args = ["-lpthread", "-ldl"];
    expected_paths = ["vendor/sqlite/lib", "vendor/raylib/lib"];

    assert planner.ordered_libs == expected_libs, (
        f"libs not in declaration order: got {planner.ordered_libs}, "
        f"want {expected_libs}"
    );
    assert planner.ordered_args == expected_args, (
        f"args not in declaration order: got {planner.ordered_args}, "
        f"want {expected_args}"
    );
    assert planner.ordered_paths == expected_paths, (
        f"paths not in declaration order: got {planner.ordered_paths}, "
        f"want {expected_paths}"
    );
}

test "duplicate libs and args merged exactly once" {
    shared_lib_wrapper = StaticLib(
        name="shared-wrapper-a",
        libs=["m", "pthread"],
        search_paths=["vendor/common/lib"],
        args=["-lpthread"]
    );

    shared_lib_wrapper_b = StaticLib(
        name="shared-wrapper-b",
        libs=["m", "rt"],
        search_paths=["vendor/common/lib"],
        args=["-lpthread", "-ldl"]
    );

    binary = Package(name="app-binary", kind="binary");

    root +>:DependsOn(declared_by="app-binary"):+> binary;
    binary +>:DependsOn(declared_by="app-binary"):+> shared_lib_wrapper;
    binary +>:DependsOn(declared_by="app-binary"):+> shared_lib_wrapper_b;

    planner = LinkPlanner();
    root spawn planner;

    assert planner.ordered_libs == ["m", "pthread", "rt"], (
        f"duplicate libs not dedup'd in order: got {planner.ordered_libs}"
    );
    assert planner.ordered_args == ["-lpthread", "-ldl"], (
        f"duplicate args not dedup'd in order: got {planner.ordered_args}"
    );
    assert planner.ordered_paths == ["vendor/common/lib"], (
        f"duplicate path not dedup'd: got {planner.ordered_paths}"
    );

