        f"'m' should appear once, got {planner.ordered_libs.count('m')}"
    );
    assert planner.ordered_args.count("-lpthread") == 1, (
        f"'-lpthread' should appear once, got {planner.ordered_args.count('-lpthread')}"
    );
    assert planner.ordered_paths.count("vendor/common/lib") == 1, (
        f"shared path should appear once, got "
        f"{planner.ordered_paths.count('vendor/common/lib')}"
