"""Organization Settings, Categories & Document Types — taxonomy walker demo.

Models the PHASE 03 scenario natively: an Organization owns Settings and a
catalog of Category and DocumentType taxonomy nodes. A walker audits the
taxonomy, refuses duplicate names, detects references by documents, and
reports the safe-deactivation path (archive instead of delete) for any
taxonomy item still referenced by a Document node.
"""

node Organization {
    has name: str = "";
    has tenant_id: str = "";
}

node Settings {
    has allow_archive: bool = True;
    has max_categories: int = 50;
}

node Category {
    has title: str = "";
    has active: bool = True;
}

node DocumentType {
    has title: str = "";
    has active: bool = True;
}

node Document {
    has title: str = "";
    has archived: bool = False;
}

edge Owns {
    has created_on: str = "";
}

edge References {
    has since: str = "";
}

edge ClassifiedAs {
    has since: str = "";
}

walker TaxonomyAuditor {
    has report_lines: list[str] = [];
    has seen_names: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can land_at with Organization entry {
        self.report_lines = [];
        self.seen_names = [];
        self.report_lines.append(f"== Auditing tenant {here.tenant_id} ({here.name}) ==");
        visit [->:Owns:->];
    }

    can audit_settings with Settings entry {
        line = f"  settings: allow_archive={here.allow_archive}, max_categories={here.max_categories}";
        self.report_lines.append(line);
    }

    can audit_taxonomy with Category | DocumentType entry {
        is_cat = isinstance(here, Category);
        kind = "Category" if is_cat else "DocumentType";
        key = kind + ":" + here.title.lower();
        already_seen = False;
        for prior in self.seen_names {
            if prior == key {
                already_seen = True;
            }
        }
        if already_seen {
            dup_line = f"  DUPLICATE {kind} name '{here.title}' — would be rejected";
            self.report_lines.append(dup_line);
        } else {
            self.seen_names.append(key);
            active_label = "active" if here.active else "inactive";
            line = f"  {kind}: {here.title} [{active_label}]";
            self.report_lines.append(line);
        }
        visit [->:References:->];
    }

    can check_references with Document entry {
        if here.archived {
            ref_line = f"    ref-by Document '{here.title}' (archived) — taxonomy safe to deactivate";
        } else {
            ref_line = f"    ref-by Document '{here.title}' (LIVE) — taxonomy must be archived, not deleted";
        }
        self.report_lines.append(ref_line);
    }

    can finish with Organization exit {
        for ln in self.report_lines {
            print(ln);
        }
        disengage;
    }
}

