"""Test annex for the PHASE 03 taxonomy auditor demo."""

import io;
import from contextlib { redirect_stdout }

# ---------- Helper ----------
def _run_audit(org) {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = org spawn TaxonomyAuditor();
    }
    return buf.getvalue();
}

# ---------- Test 1: happy path — happy doc, settings echoed, no duplicates ----------
test "happy_path_settings_and_unique_taxonomy_listed" {
    acme = Organization(name="Acme Corp", tenant_id="T-HAPPY");
    settings = Settings(allow_archive=True, max_categories=25);
    acme +>:Owns(created_on="2024-01-01"):+> settings;

    cat_a = Category(title="Invoices", active=True);
    cat_b = Category(title="Contracts", active=True);
    acme +>:Owns(created_on="2024-01-02"):+> cat_a;
    acme +>:Owns(created_on="2024-01-02"):+> cat_b;

    dt_a = DocumentType(title="Tax Form", active=True);
    acme +>:Owns(created_on="2024-01-15"):+> dt_a;

    doc = Document(title="Q1-Tax-2024");
    cat_a +>:References(since="2024-03-01"):+> doc;

    root ++> acme;

    out = _run_audit(acme);

    assert "Auditing tenant T-HAPPY (Acme Corp)" in out, f"missing tenant header: {out}";
    assert "settings: allow_archive=True, max_categories=25" in out, f"missing settings line: {out}";
    assert "Category: Invoices [active]" in out, f"missing Invoices: {out}";
    assert "Category: Contracts [active]" in out, f"missing Contracts: {out}";
    assert "DocumentType: Tax Form [active]" in out, f"missing Tax Form: {out}";
    assert "DUPLICATE" not in out, f"unexpected duplicate marker in: {out}";
}

# ---------- Test 2: duplicate taxonomy name is flagged ----------
test "duplicate_taxonomy_name_flagged_case_insensitive" {
    acme = Organization(name="Acme", tenant_id="T-DUP");
    settings = Settings(allow_archive=True, max_categories=50);
    acme +>:Owns(created_on="2024-01-01"):+> settings;

    c1 = Category(title="Invoices", active=True);
    c2 = Category(title="invoices", active=True);  # case-insensitive duplicate
    c3 = Category(title="INVOICES", active=True);  # another case-insensitive duplicate
    acme +>:Owns(created_on="2024-01-02"):+> c1;
    acme +>:Owns(created_on="2024-01-03"):+> c2;
    acme +>:Owns(created_on="2024-01-04"):+> c3;

    dt1 = DocumentType(title="NDA", active=True);
    dt2 = DocumentType(title="nda", active=True);  # dup document type
    acme +>:Owns(created_on="2024-01-15"):+> dt1;
    acme +>:Owns(created_on="2024-01-16"):+> dt2;

    root ++> acme;

    out = _run_audit(acme);

    assert "DUPLICATE Category name 'invoices' — would be rejected" in out, f"missing Category dup: {out}";
    assert "DUPLICATE Category name 'INVOICES' — would be rejected" in out, f"missing INVOICES dup: {out}";
    assert "DUPLICATE DocumentType name 'nda' — would be rejected" in out, f"missing DocumentType dup: {out}";
    # The first occurrence of each must still be listed (not rejected).
    assert "Category: Invoices [active]" in out, f"first Invoices should appear: {out}";
    assert "DocumentType: NDA [active]" in out, f"first NDA should appear: {out}";
}

# ---------- Test 3: live vs archived references drive the safe-delete message ----------
test "live_reference_requires_archive_archived_is_safe" {
    acme = Organization(name="Acme", tenant_id="T-REF");
