    assert "ref-by Document 'Employee-Handbook' (LIVE) — taxonomy must be archived, not deleted" in out, f"missing live ref message: {out}";
    assert "ref-by Document 'Old-Policy-2010' (archived) — taxonomy safe to deactivate" in out, f"missing archived ref message: {out}";
