"""Knowledge graph of DSA concepts: nodes + prerequisite edges, walked by an auditor.

Models the VoxMentor backend knowledge graph in idiomatic Jac. Concept nodes
hold the curriculum metadata; typed ``Prereq`` edges carry the prerequisite
relationship. The ``PrerequisiteAuditor`` walker traverses the typed edges
to report reachability and counts the seeded population, replacing the
hand-rolled recursive CTE machinery from the original backend.
"""

node Concept {
    has name: str = "";
    has topic: str = "";
    has difficulty: int = 0;
    has tier: str = "";
}

edge Prereq {
    has weight: float = 1.0;
}

walker PrerequisiteAuditor {
    has target: str = "";
    has visited: list[str] = [];
    has path: list[str] = [];
    has hit: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can walk with Concept entry {
        # Cycle safety: walkers do not dedupe nodes on cyclic graphs.
        if here.name in self.visited {
            visit [-->];
        } else {
            self.visited.append(here.name);
            self.path.append(here.name);
            if here.name == self.target {
                self.hit = True;
                print(f"REACHED '{self.target}' via path: {self.path}");
                visit [-->];
            } else {
                # Report current node, then traverse only prerequisite edges.
                print(f"  visit {here.name} ({here.topic}, tier={here.tier})");
                visit [->:Prereq:->];
            }
        }
    }
}

walker ConceptCounter {
    has counts: int = 0;
    has difficulties: int = 0;
    has tier_filter: str = "";

    can start with Root entry {
        visit [-->];
    }

    can count with Concept entry {
        if self.tier_filter == "" or here.tier == self.tier_filter {
            self.counts += 1;
            self.difficulties += here.difficulty;
        }
        visit [-->];
    }
}

