"""Tree storage service: make depth configurable.

Models the core scenario from issue #186 — a recursive tree traversal
where the walker's recursion depth is bounded by a configurable limit.
The hand-rolled CTE/regex scaffolding is replaced with a typed-edge
walker that respects the configured max depth, accumulates rows, and
reports a single exit summary.
"""

# ----- node archetypes -----

node TreeNode {
    has id: int = 0;
    has label: str = "";
    has is_anchor: bool = False;
}

# ----- typed edges (relationship carries meaning) -----

edge ParentLink {
    has depth_step: int = 1;
}

# ----- walker: bounded-depth recursive descent over ParentLink edges -----

walker TreeFetcher {
    has max_depth: int = 3;
    has start_slug: str = "";
    has collected: list = [];
    has visited_ids: list = [];

    can begin with Root entry {
        # Find the anchor node whose label matches the slug and start from there.
        for n in [-->](?:TreeNode) {
            if n.label == self.start_slug {
                visit n;
                return;
            }
        }
        print(f"No node found with slug '{self.start_slug}'");
        disengage;
    }

    can descend with TreeNode entry {
        # Cycle policy: skip nodes we've already seen (walkers have no
        # built-in dedup in jac 0.36.x, so guard explicitly).
        if self.visited_ids.count(here.id) > 0 {
            visit [-->] else { disengage; }
            return;
        }
        self.visited_ids.append(here.id);
        self.collected.append({
            "id": here.id,
            "label": here.label,
            "depth": len(self.visited_ids),
        });
        print(f"visited id={here.id} label='{here.label}' depth={len(self.visited_ids)}");

        # Depth cap: if we've already consumed max_depth levels, stop
        # walking children. This is the configurable depth that issue
        # #186 complains about being hard-coded in the original SQL.
        if len(self.visited_ids) >= self.max_depth {
            print(f"reached max_depth={self.max_depth}; stopping descent");
            disengage;
        }

        visit [->:ParentLink:->] else { disengage; }
    }

    can summarize with Root entry {
        # Fallback entry on the way back up; only fires if we re-enter Root.
        print(f"summary: collected {len(self.collected)} nodes within depth {self.max_depth}");
        report {
            "max_depth": self.max_depth,
            "start_slug": self.start_slug,
            "rows": self.collected,
            "visited_ids": self.visited_ids,
        };
    }
}

# ----- demo wiring -----

with entry {
    # Build a small tree:
    #   root
    #    |-- root_node (anchor)
    #         |-- child_a
    #         |    |-- grandchild_a1
    #         |    |-- grandchild_a2
    #         |-- child_b
    #              |-- grandchild_b1
    #                      |-- great_grandchild_b1x
    root ++> TreeNode(id=1, label="root_node", is_anchor=True)
        +>:ParentLink:+> TreeNode(id=2, label="child_a")
        +>:ParentLink:+> TreeNode(id=3, label="child_b");
    TreeNode(id=2, label="child_a")
        +>:ParentLink:+> TreeNode(id=4, label="grandchild_a1")
        +>:ParentLink:+> TreeNode(id=5, label="grandchild_a2");
    TreeNode(id=3, label="child_b")
        +>:ParentLink:+> TreeNode(id=6, label="grandchild_b1");
    TreeNode(id=6, label="grandchild_b1")
        +>:ParentLink:+> TreeNode(id=7, label="great_grandchild_b1x");

    # Walk with a shallow depth cap (mirrors the "1 as depth" complaint).
    print("=== shallow fetch (max_depth=2) starting at 'root_node' ===");
    shallow = TreeFetcher(max_depth=2, start_slug="root_node");
    root spawn shallow;

    # Walk with a deeper cap to show the same walker is now configurable.
    print("=== deep fetch (max_depth=5) starting at 'root_node' ===");
    deep = TreeFetcher(max_depth=5, start_slug="root_node");
    root spawn deep;
}

