"""Tests for the wormneuroatlas demo: BFS shortest-hop vs buggy self-closure.

The issue is that a recursion that walks the *previous closure* rather than
the *original adjacency* over-counts reachable pairs. We verify the demo's
two walkers behave correctly on a small linear chain A-B-C-D-E.
"""

import io;
import from contextlib { redirect_stdout }

# ---------- Test 1: BFS reaches every node in true graph order ----------

test "shortest BFS reaches all five neurons exactly once" {
    a = Neuron(label="A");
    b = Neuron(label="B");
    c = Neuron(label="C");
    d = Neuron(label="D");
    e = Neuron(label="E");
    a +>:Synapse:+> b;
    b +>:Synapse:+> c;
    c +>:Synapse:+> d;
    d +>:Synapse:+> e;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root ++> a;
        res = root spawn ShortestHop();
    }
    out = buf.getvalue();

    # BFS in a linear chain visits each vertex once and prints each label once.
    n_a = out.count("[short] reached A");
    n_b = out.count("[short] reached B");
    n_c = out.count("[short] reached C");
    n_d = out.count("[short] reached D");
    n_e = out.count("[short] reached E");

    assert n_a == 1, f"A should appear exactly once in BFS, got {n_a}: {out}";
    assert n_b == 1, f"B should appear exactly once in BFS, got {n_b}: {out}";
    assert n_c == 1, f"C should appear exactly once in BFS, got {n_c}: {out}";
    assert n_d == 1, f"D should appear exactly once in BFS, got {n_d}: {out}";
    assert n_e == 1, f"E should appear exactly once in BFS, got {n_e}: {out}";
}

# ---------- Test 2: BFS visits appear in increasing hop order ----------

test "shortest BFS visits in true graph-distance order A,B,C,D,E" {
    a = Neuron(label="A");
    b = Neuron(label="B");
    c = Neuron(label="C");
    d = Neuron(label="D");
    e = Neuron(label="E");
    a +>:Synapse:+> b;
    b +>:Synapse:+> c;
    c +>:Synapse:+> d;
    d +>:Synapse:+> e;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root ++> a;
        root spawn ShortestHop();
    }
    out = buf.getvalue();

    pos_a = out.index("[short] reached A");
    pos_b = out.index("[short] reached B");
    pos_c = out.index("[short] reached C");
    pos_d = out.index("[short] reached D");
    pos_e = out.index("[short] reached E");

    assert pos_a < pos_b, f"A must precede B in BFS output: {out}";
    assert pos_b < pos_c, f"B must precede C in BFS output: {out}";
    assert pos_c < pos_d, f"C must precede D in BFS output: {out}";
    assert pos_d < pos_e, f"D must precede E in BFS output: {out}";
}

# ---------- Test 3: BFS marks exactly one neuron at each distance ----------

test "shortest BFS leaves visited_by_short True on every reachable neuron" {
    a = Neuron(label="A");
    b = Neuron(label="B");
    c = Neuron(label="C");
    d = Neuron(label="D");
    e = Neuron(label="E");
    a +>:Synapse:+> b;
    b +>:Synapse:+> c;
    c +>:Synapse:+> d;
    d +>:Synapse:+> e;

    root ++> a;
    root spawn ShortestHop();

    assert a.visited_by_short == True, "A should be marked visited";
    assert b.visited_by_short == True, "B should be marked visited";
    assert c.visited_by_short == True, "C should be marked visited";
    assert d.visited_by_short == True, "D should be marked visited";
    assert e.visited_by_short == True, "E should be marked visited";

    # No spurious extra visits: a 5-node chain has 5 visited nodes total.
    visited_count = 0;
    for n in [a, b, c, d, e] {
        if n.visited_by_short {
            visited_count += 1;
        }
    }
    assert visited_count == 5, f"expected 5 visited neurons, got {visited_count}";
}

# ---------- Test 4: buggy closure walker visits every neuron (still traverses) ----------

test "buggy closure walker also reaches all neurons on the chain" {
    a2 = Neuron(label="A");
    b2 = Neuron(label="B");
    c2 = Neuron(label="C");
    d2 = Neuron(label="D");
    e2 = Neuron(label="E");
    a2 +>:Synapse:+> b2;
    b2 +>:Synapse:+> c2;
    c2 +>:Synapse:+> d2;
    d2 +>:Synapse:+> e2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root ++> a2;
        root spawn BuggyClosure();
    }
    out = buf.getvalue();

    # Even the self-composing closure still visits every node in a finite chain;
    # the bug is not "missed nodes" but "over-counted pairs" in matrix terms.
    assert "[buggy] reached A" in out, f"buggy walker missed A: {out}";
    assert "[buggy] reached B" in out, f"buggy walker missed B: {out}";
    assert "[buggy] reached C" in out, f"buggy walker missed C: {out}";
    assert "[buggy] reached D" in out, f"buggy walker missed D: {out}";
    assert "[buggy] reached E" in out, f"buggy walker missed E: {out}";

    assert a2.visited_by_buggy == True, "A should be marked buggy-visited";
    assert b2.visited_by_buggy == True, "B should be marked buggy-visited";
    assert c2.visited_by_buggy == True, "C should be marked buggy-visited";
    assert d2.visited_by_buggy == True, "D should be marked buggy-visited";
    assert e2.visited_by_buggy == True, "E should be marked buggy-visited";
}

# ---------- Test 5: the two walkers use independent flags on the same graph ----------

test "running BFS does not corrupt buggy flags and vice versa" {
    a = Neuron(label="A");
    b = Neuron(label="B");
    c = Neuron(label="C");
    d = Neuron(label="D");
    e = Neuron(label="E");
    a +>:Synapse:+> b;
    b +>:Synapse:+> c;
    c +>:Synapse:+> d;
    d +>:Synapse:+> e;

    root ++> a;
    root spawn ShortestHop();

    # After BFS: short flags set, buggy flags untouched.
    assert a.visited_by_short == True, "short flag on A must be set after BFS";
    assert a.visited_by_buggy == False, "buggy flag on A must be untouched after BFS";
    assert e.visited_by_short == True, "short flag on E must be set after BFS";
    assert e.visited_by_buggy == False, "buggy flag on E must be untouched after BFS";
}

