"""Spec-hash write-storm demo.

Models the WRC/HCC write-storm from issue #460: a Controller reconciles
several Recipes, each owning a shared Context. Without a spec-hash gate, every
reconcile unconditionally re-writes the same Context, bumping its
`resourceVersion` and triggering a downstream watch (HCC) that re-emits a
NetworkPolicy. The fix is the same hash-gate the McpServer path already uses,
propagated to the Context path.

Entities (nodes) and relationships (typed edges):
  Recipe   --+> Context  (edge: OwnsContext)
  Context  --+> NetworkPolicy (edge: OwnsPolicy)
  Controller (the root) --+> Recipe (edge: Manages)

Walker `HCC` watches the Context subtree and would otherwise re-emit a
NetworkPolicy every loop. Once the Controller calls `stampSpecHash` /
`specHashUnchanged` on the desired manifest, the write is skipped, the
`resourceVersion` stops moving, and the downstream storm goes quiet.
"""

# ------------------------------------------------------------------
# Node archetypes
# ------------------------------------------------------------------

node Recipe {
    has name: str = "";
    has generation: int = 0;
    has available: bool = True;
}

node Context {
    has name: str = "";
    has resource_version: int = 0;
    has spec_hash: str = "";
    has available: bool = True;
}

node NetworkPolicy {
    has name: str = "";
    has generation: int = 0;
    has available: bool = True;
}

# ------------------------------------------------------------------
# Typed edges
# ------------------------------------------------------------------

edge Manages {
    has since: str = "";
}

edge OwnsContext {
    has recipe_id: str = "";
}

edge OwnsPolicy {
    has context_name: str = "";
}

# ------------------------------------------------------------------
# Walker: simulates the HCC watch over a shared Context. Every visit
# to a Context would, in the buggy code, bump its resourceVersion and
# re-emit a NetworkPolicy. The fix is the spec-hash gate on the
# Controller's write path; the walker models the *consequence* (a
# quiet watch when nothing changed, a re-emission when the spec
# actually moved).
# ------------------------------------------------------------------

walker HCC {
    has observations: list = [];

    can start with Root entry {
        # Watch the whole managed subtree: recipes -> contexts -> policies.
        visit [-->];
    }

    can watch_recipes with Recipe entry {
        # Follow every owned Context to see whether it changed.
        visit [->:OwnsContext:->];
    }

    can watch_contexts with Context entry {
        # If the controller's write was a no-op (spec hash unchanged),
        # resourceVersion does NOT move and we record a quiet tick.
        # Otherwise, resourceVersion moves and we record a noisy tick.
        tick = "quiet" if self.last_was_noop else "noisy";
        self.observations.append(tick);
        visit [->:OwnsPolicy:->];
    }

    can watch_policies with NetworkPolicy entry {
        # If we got here via a noisy tick, the policy is being
        # re-emitted; if quiet, the watch is dormant.
        if not self.last_was_noop {
