"""Fleet users: normal vs API-restricted access.

Models the core scenario from issue #51602: IT admins need a quick view
of which users have normal access versus users who are restricted to
specific API endpoints. The graph machinery walks users -> team
memberships -> API scopes and surfaces restricted users without forcing
admins to open each user record.
"""

node Team {
    has name: str = "";
    has description: str = "";
}

node APIEndpoint {
    has path: str = "";
    has method: str = "GET";
}

# A user restricted to specific endpoints gets Restricts -> typed edges
# pointing at the APIEndpoint nodes they may call. Normal users have no
# such edges, which is the discriminator the admin view needs.
node User {
    has email: str = "";
    has role: str = "viewer";
    has api_only: bool = False;
}

# A user may belong to many teams; the edge carries join context.
edge MemberOf {
    has joined: str = "2024-01-01";
}

# Restriction edges: only present on users with API-scoped access.
edge Restricts {
    has granted_by: str = "admin";
}

walker AccessAuditor {
    has restricted: list = [];
    has total_users: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can scan with User entry {
        self.total_users += 1;
        restrictions = [here->:Restricts:->];
        if len(restrictions) > 0 {
            self.restricted.append(
                {"email": here.email, "role": here.role, "api_only": here.api_only}
            );
        }
        visit [-->];
    }

    can continue with Team entry {
        visit [-->];
    }

    can finish with APIEndpoint entry {
        visit [-->];
    }

    can report with Root entry {
        normal = self.total_users - len(self.restricted);
        print(f"Audit complete: {normal} normal, {len(self.restricted)} restricted");
        for r in self.restricted {
            print(f"  RESTRICTED: {r['email']} (role={r['role']}, api_only={r['api_only']})");
        }
        disengage;
    }
}

