fixed.code:
"""Wayfinder demo: temporal recursive graph-complete with current pointers.

Models the essential scenario from issue #228 / #227:
  - A root `complete()` invocation owns a live `current` pointer.
  - `advance(layer)` publishes an immutable owned closure and moves the pointer.
  - Child `invoke` actions create scoped sub-completions, each with its own
    current pointer, and resolve to the child's final layer when it succeeds.
  - Asynchronous bottom-up progression: parent does NOT wait for child.
  - Temporal continuity: previously published work remains graph-natively
    accessible through breadcrumb edges.

The walker `Wayfinder` performs the traversal the issue complains about —
hand-rolled recursion over parent/child relationships, cascade invalidation
of child cursors on advance, and bottom-up synthesis ordering.
"""

node Interaction {
    has label: str = "";
    has kind: str = "user";  # "user" or "agent"
}

node Layer {
    has title: str = "";
    has published: bool = False;
    has synthesized: bool = False;
}

node Cursor {
    # A live current pointer belonging to one completion.
    has owner: str = "";
    has active: bool = True;
}

node Completion {
    # One `complete(inputGraph)` invocation: owns a cursor and a result.
    has name: str = "";
    has terminal: bool = False;
    has final_layer: str = "";
}

# Typed edges: breadcrumb back up the hierarchy, invoke from parent to
# child completion, and owned (closure) link from a completion to its
# published layer.
edge Breadcrumb { has label: str = "up"; }
edge Invoke { has action: str = "invoke"; }
edge Owns { has since: str = ""; }
edge CursorAt { has step: int = 0; }

walker Wayfinder {
    # Performs the temporal recursion the issue calls out: descends via
    # Invoke edges, advances cursors layer by layer, cascades cursor
    # invalidation on advance, then ascends via Breadcrumb edges for
    # bottom-up parent synthesis.

    has trace: list[str] = [];
    has depth_limit: int = 5;

    can start with Root entry {
        self.trace.append("root:enter");
        visit [-->];
    }

    can descend with Interaction entry {
        self.trace.append(f"interaction:{here.kind}:{here.label}");
        # Breadcrumbs keep temporal continuity: previously visited work
        # stays graph-natively reachable via the breadcrumb chain.
        visit [->:Invoke:->];
    }

    can ascend with Interaction entry {
        # Walk back up the hierarchy for bottom-up parent synthesis.
        visit [->:Breadcrumb:->];
    }

    can at_completion with Completion entry {
        self.trace.append(f"completion:{here.name}:terminal={here.terminal}");
        # Walk the owned cursor and published layers (the owned closure).
        visit [->:CursorAt:->];
        visit [->:Owns:->];
    }

    can at_cursor with Cursor entry {
        self.trace.append(f"cursor:{here.owner}:active={here.active}");
        visit [->:Owns:->];
    }

    can at_layer with Layer entry {
        self.trace.append(f"layer:{here.title}:pub={here.published}");
        # Layers do not fan out further; dead-end safe.
        visit [-->] else { disengage; }
    }
}

walker Advance {
    # Models `current.advance(layer)`: validate the target layer is
    # owned by this completion, atomically publish it, then move the
    # current pointer. Cascades invalidation of any live child cursors.

    has completion_name: str = "";
    has layer_title: str = "";
    has report: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can walk with Interaction entry {
        visit [->:Invoke:->];
    }

    can apply with Completion entry {
        if here.name != self.completion_name {
            visit [->:CursorAt:->];
            return;
        }
        # Cascade invalidation of child cursors before publishing.
        # (Bottom-up: child currents are not waited on, but their
        # presence is invalidated atomically with the advance.)
        for c in [->:CursorAt:->] {
            self.report.append(f"invalidating cursor of {here.name}");
            c.active = False;
        }
        here.final_layer = self.layer_title;
        here.terminal = True;
        self.report.append(f"advanced {here.name} -> {self.layer_title}");
    }
}

with entry {
    # Build the demo graph: one root completion with a child invoked
    # via an interaction node. Each completion owns a cursor and a
    # sequence of candidate layers.
    root_int = Interaction(label="root-prompt", kind="user");
    child_int = Interaction(label="child-prompt", kind="agent");

    root_layer = Layer(title="root-draft", published=False);
    final_layer = Layer(title="root-final", published=False);
    child_layer = Layer(title="child-result", published=False);

    root_cursor = Cursor(owner="root-cmp", active=True);
    child_cursor = Cursor(owner="child-cmp", active=True);

    root_cmp = Completion(name="root-cmp");
    child_cmp = Completion(name="child-cmp");

    # Wire the demo graph.
    root ++> root_int;
    root_int +>:Invoke(action="invoke"):+> child_int;
    child_int +>:Breadcrumb(label="up"):+> root_cmp;

    # Child completion owns its cursor and published layer.
    child_cmp +>:CursorAt(step=0):+> child_cursor;
    child_cmp +>:Owns(since="t0"):+> child_layer;

    # Root completion owns its cursor and candidate layers.
    root_cmp +>:CursorAt(step=0):+> root_cursor;
    root_cmp +>:Owns(since="t0"):+> root_layer;
    root_cmp +>:Owns(since="t1"):+> final_layer;

    # Spawn the wayfinder walker to demonstrate the traversal.
    wf = Wayfinder(depth_limit=5);
    root spawn wf;

    # Demonstrate the advance operation: publish the root final layer
    # and cascade-invalidate child cursors (bottom-up rule).
    adv = Advance(completion_name="root-cmp", layer_title="root-final");
    root spawn adv;

    print("=== wayfinder trace ===");
    for entry in wf.trace {
        print(entry);
    }
    print("=== advance report ===");
    for line in adv.report {
        print(line);
    }
    print(f"root terminal={root_cmp.terminal} final={root_cmp.final_layer}");
    print(f"child cursor still active={child_cursor.active}");
}

