    }

    can audit_safety with SafetyGate entry {
        remaining = here.payments_allowed;
        if here.armed and remaining > 0 {
            self.payment_count += 1;
            print(f"[SAFETY] gate '{here.gate_name}' armed, "
                  f"{remaining} intentional payment(s) permitted");
        } else {
            print(f"[SAFETY] gate '{here.gate_name}' DISARMED -> fail-closed");
            disengage;
        }
        visit [-->];
    }

    can audit_purchase with HostPurchase entry {
        label = "PAID" if here.paid else "UNPAID";
        print(f"[PURCHASE] order {here.order_id} item={here.item} buyer={here.buyer} -> {label}");
        visit [-->];
    }

    can audit_leg with DeliveryLeg entry {
        state = "DELIVERED" if here.delivered else "IN_TRANSIT";
        print(f"[DELIVERY] leg {here.leg_id} carrier={here.carrier} -> {state}");
        visit [-->];
    }
}

walker CycleGuard {
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can check with HostPurchase | DeliveryLeg | SafetyGate entry {
        key = str(here);
        already = False;
        for s in self.seen {
            if s == key {
                already = True;
            }
        }
        if already {
            print(f"[CYCLE] revisit detected at {key} -> disengage");
            disengage;
        }
        self.seen.append(key);
        print(f"[CYCLE] first visit to {key}");
        visit [-->];
    }
}

with entry {
    gate = SafetyGate(gate_name="one-shot-payment", armed=True, payments_allowed=1);
    purchase = HostPurchase(order_id="ORD-001", buyer="alice", paid=True, item="BUFF-token");
    leg_a = DeliveryLeg(leg_id="LEG-1", carrier="AutoOffer", delivered=True);
    leg_b = DeliveryLeg(leg_id="LEG-2", carrier="AutoOffer", delivered=False);

    root +>:GuardedBy:+> gate;
    gate +>:PaidBy(tx_ref="TX-7a"):+> purchase;
    purchase +>:FulfilledBy:+> leg_a;
    leg_a +>:FulfilledBy:+> leg_b;

    print("--- spawn CanaryAuditor ---");
    root spawn CanaryAuditor();

    print("--- spawn CycleGuard (safety net) ---");
    root spawn CycleGuard();
}

