    has name: str = "";            # e.g. "1D", "4H", "15m"
    has tier: str = "";            # "HTF" or "LTF"
    has frame: str = "";           # "Breath" or "Fibo"
    has bias: str = "neutral";     # primitive signal: bullish/bearish/neutral
    has strength: float = 0.0;     # primitive signal magnitude
    has freshness: str = "stale";  # fresh / recent / stale
    has replay_ready: bool = False;
}

node RegimeContext {
    has kind: str = "";            # "trending", "ranging", "volatile"
    has confidence: float = 0.0;
}

node PatternCandidate {
    has name: str = "";            # local pattern label
    has active: bool = False;
}

# ---------- Walker: matrix reporter ----------

walker MatrixReporter {
    has asset_count: int = 0;
    has timeframe_count: int = 0;
    has conflict_count: int = 0;
    has rows: list = [];

    can begin with Root entry {
        print("=== Signal Matrix Static Dashboard V1 ===");
        visit [-->];
    }

    can visit_asset with Asset entry {
        self.asset_count += 1;
        print(f"[ASSET] {here.symbol} ({here.family})");
        visit [->:FramesAsset:->];
    }

    can visit_timeframe with Timeframe entry {
        self.timeframe_count += 1;
        verdict = "ready" if here.replay_ready else "not-ready";
        row = {
            "tier": here.tier,
            "name": here.name,
            "frame": here.frame,
            "bias": here.bias,
            "strength": here.strength,
            "freshness": here.freshness,
            "replay": verdict
        };
        self.rows.append(row);
        print(
            f"  [{here.tier}/{here.frame}] {here.name} "
            f"bias={here.bias} strength={here.strength} "
            f"fresh={here.freshness} replay={verdict}"
        );
        visit [->:HasRegime:->];
        visit [->:HasTimeframe:->];
    }

    can visit_regime with RegimeContext entry {
        print(f"    regime={here.kind} conf={here.confidence}");
        visit [-->];
    }

    can visit_pattern with PatternCandidate entry {
        flag = "ON" if here.active else "off";
        print(f"    pattern[{flag}]: {here.name}");
        visit [-->];
    }

    can finish with Root entry {
        # Detect primitive conflicts across timeframes for the same asset.
        biases: dict = {};
        for r in self.rows {
            key = r["tier"] + ":" + r["name"];
            prev = biases.get(key);
            if prev is not None and prev != r["bias"] {
                self.conflict_count += 1;
                print(f"[CONFLICT] {key} saw {prev} then {r['bias']}");
            } else {
                biases[key] = r["bias"];
            }
        }
        print(
            f"--- summary: assets={self.asset_count} "
            f"timeframes={self.timeframe_count} "
            f"conflicts={self.conflict_count} ---"
        );
        print("No final-advice label produced (BUY_READY/AVOID/WATCH_ONLY).");
        disengage;
    }
}

