    has regime: str = "";
    has confidence: float = 0.0;
}

node CatalystContext {
    has source: str = "";
    has fresh: bool = True;
}

edge HasTimeframe { }
edge SignalsOn { }
edge HasRegime { }
edge HasCatalyst { }
edge ConflictsWith { }

walker MatrixAuditor {
    has visited_assets: list[str] = [];
    has conflict_count: int = 0;
    has stale_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can inspect_asset with Asset entry {
        if here.symbol not in self.visited_assets {
            self.visited_assets.append(here.symbol);
            print(f"[ASSET] {here.symbol} market={here.market}");
