"""Test annex for Signal Matrix Static Dashboard V1.

Verifies that MatrixAuditor walks the asset x timeframe matrix,
exposes primitive conflicts explicitly, surfaces stale primitives,
and keeps the asset/timeframe/regime/catalyst graph shape intact.
"""

import io;
import from contextlib { redirect_stdout }

test "MatrixAuditor visits both wired assets" {
    root ++> Asset(symbol="BTC-USD", market="crypto");
    root ++> Asset(symbol="ETH-USD", market="crypto");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn MatrixAuditor();
    }
    out = buf.getvalue();

    assert "[ASSET] BTC-USD" in out, f"missing BTC asset line: {out}";
    assert "[ASSET] ETH-USD" in out, f"missing ETH asset line: {out}";
    assert "BTC-USD" in res.visited_assets, f"BTC not recorded: {res.visited_assets}";
    assert "ETH-USD" in res.visited_assets, f"ETH not recorded: {res.visited_assets}";
}

test "Timeframes are traversed with correct minute values" {
    a = Asset(symbol="SOL-USD", market="crypto");
    tf_1h = Timeframe(label="1H", minutes=60);
    tf_4h = Timeframe(label="4H", minutes=240);
