"""Tests for the First Release Readiness audit walker (issue #103)."""

import io;
import from contextlib { redirect_stdout }

# ---------- Helpers ----------

def make_persona(name: str, role: str, signed: int, total: int) -> Persona {
    return Persona(name=name, role=role, scenarios_signed=signed, scenarios_total=total);
}

def make_checkpoint(label: str, kind: str, status: str, owner: str, evidence_current: bool) -> Checkpoint {
    return Checkpoint(label=label, kind=kind, status=status, owner=owner, evidence_current=evidence_current);
}

def make_signoff(reviewer: str, scope: str, severity: str, resolved: bool) -> SignOff {
    return SignOff(reviewer=reviewer, scope=scope, severity=severity, resolved=resolved);
}

def make_gate(label: str, blocked_by_id: int, authorizes_id: int) -> ReleaseGate {
    return ReleaseGate(label=label, blocked_by_id=blocked_by_id, authorizes_id=authorizes_id);
}

def run_auditor(rt) {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn ReadinessAuditor();
    }
    return (res, buf.getvalue());
}

# ---------- Tests ----------

test "happy path: all scenarios signed, evidence current, no unresolved P1/P2 yields GO" {
    rt = root;
    rt ++> make_persona("Alice", "PM", 4, 4);
    rt ++> make_persona("Bob", "QA", 5, 5);
    rt ++> make_checkpoint("UAT", "uat", "passed", "QA", True);
    rt ++> make_checkpoint("Security", "audit", "passed", "Sec", True);
    rt ++> make_signoff("QA Lead", "UAT", "", True);
    rt ++> make_signoff("Sec", "Sec", "P3", True);
    gate = make_gate("Release Gate", 102, 115);
    rt ++> gate;

    (res, out) = run_auditor(rt);

    assert res.current_gate is gate, f"auditor should set current_gate to the gate node, got {res.current_gate}";
    assert res.current_gate.decision == "GO", f"expected GO on happy path, got {res.current_gate.decision}";
    assert res.p1_total == 0, f"P1 total should be 0, got {res.p1_total}";
    assert res.p2_total == 0, f"P2 total should be 0, got {res.p2_total}";
    assert len(res.missing_evidence) == 0, f"no missing evidence expected, got {res.missing_evidence}";
    assert len(res.blocked_names) == 0, f"no blocked expected, got {res.blocked_names}";
    assert len(res.unfinished_personas) == 0, f"no unfinished personas expected, got {res.unfinished_personas}";
    assert "all persona scenarios signed" in out, f"GO message missing from output: {out}";
    assert "NO-GO" not in out, f"NO-GO should not appear on happy path: {out}";
}

test "unresolved P1 or P2 defect forces NO-GO and is tallied onto the gate" {
    rt = root;
    rt ++> make_persona("Alice", "PM", 4, 4);
    rt ++> make_checkpoint("UAT", "uat", "passed", "QA", True);
    rt ++> make_signoff("QA Lead", "UAT", "", True);
    # One resolved P1 must be ignored; one unresolved P2 must count.
    rt ++> make_signoff("R1", "A", "P1", True);
    rt ++> make_signoff("R2", "B", "P2", False);
    gate = make_gate("Defect Gate", 1, 2);
    rt ++> gate;

    (res, out) = run_auditor(rt);

    assert res.current_gate.decision == "NO-GO", f"unresolved P2 must force NO-GO, got {res.current_gate.decision}";
    assert res.p1_total == 0, f"resolved P1 must not be tallied, got p1={res.p1_total}";
    assert res.p2_total == 1, f"unresolved P2 must be tallied, got p2={res.p2_total}";
    assert res.current_gate.p1_count == 0, f"gate.p1_count should mirror p1_total, got {res.current_gate.p1_count}";
    assert res.current_gate.p2_count == 1, f"gate.p2_count should mirror p2_total, got {res.current_gate.p2_count}";
    assert "1 P2" in out, f"reason should mention 1 P2, got: {out}";
}

test "stale evidence and blocked checkpoint both contribute to NO-GO" {
    rt = root;
    rt ++> make_persona("Alice", "PM", 4, 4);
    cp_stale = make_checkpoint("Performance", "audit", "passed", "Ops", False);
    cp_block = make_checkpoint("Migration", "ops", "blocked", "Ops", True);
    cp_ok = make_checkpoint("Security", "audit", "passed", "Sec", True);
    rt ++> cp_stale;
    rt ++> cp_block;
    rt ++> cp_ok;
    rt ++> make_signoff("QA Lead", "UAT", "", True);
    gate = make_gate("Evidence Gate", 1, 2);
    rt ++> gate;

    (res, out) = run_auditor(rt);

    assert res.current_gate.decision == "NO-GO", f"stale evidence + blocked must force NO-GO, got {res.current_gate.decision}";
    assert "Performance" in res.missing_evidence, f"Performance should be in missing_evidence, got {res.missing_evidence}";
    assert "Migration" in res.blocked_names, f"Migration should be in blocked_names, got {res.blocked_names}";
    assert "stale evidence" in out, f"output should mention stale evidence: {out}";
    assert "blocked:" in out, f"output should mention blocked: {out}";
    assert "Security" not in res.missing_evidence, f"Security is current, must not appear: {res.missing_evidence}";
    assert "Security" not in res.blocked_names, f"Security is not blocked, must not appear: {res.blocked_names}";
}

test "persona with zero scenarios is skipped; incomplete personas block GO" {
    rt = root;
    # Zero-total persona must be ignored entirely.
    rt ++> make_persona("Empty", "None", 0, 0);
    # Signed == total is fine.
    rt ++> make_persona("Alice", "PM", 3, 3);
    # Signed < total blocks GO.
    rt ++> make_persona("Bob", "QA", 2, 5);
    rt ++> make_checkpoint("UAT", "uat", "passed", "QA", True);
    rt ++> make_signoff("QA Lead", "UAT", "", True);
    gate = make_gate("Persona Gate", 1, 2);
    rt ++> gate;

    (res, out) = run_auditor(rt);

    assert res.current_gate.decision == "NO-GO", f"incomplete persona must force NO-GO, got {res.current_gate.decision}";
    unfinished_str = ", ".join(res.unfinished_personas);
    assert "Bob (QA)" in unfinished_str, f"Bob (QA) should be in unfinished list, got {res.unfinished_personas}";
    assert "Empty" not in unfinished_str, f"zero-total persona must be skipped, got {res.unfinished_personas}";
    assert "Alice (PM)" not in unfinished_str, f"complete persona must not appear, got {res.unfinished_personas}";
    assert "unfinished:" in out, f"output should mention unfinished personas: {out}";
}

test "auditor writes its decision onto the reached gate and leaves other gates untouched" {
    rt = root;
    rt ++> make_persona("Alice", "PM", 4, 4);
    rt ++> make_checkpoint("UAT", "uat", "passed", "QA", True);
    rt ++> make_signoff("QA Lead", "UAT", "", True);
    # Force NO-GO via an unresolved P1 signoff reachable from root.
    rt ++> make_signoff("R1", "Critical", "P1", False);
    target = make_gate("Target Gate", 102, 115);
    rt ++> target;

    (res, _) = run_auditor(rt);

    assert res.current_gate is target, f"auditor must bind current_gate to the visited gate, got {res.current_gate}";
    assert target.decision == "NO-GO", f"target gate should be NO-GO, got {target.decision}";
    assert target.decision_owner == "Release Manager", f"decision_owner should be set, got {target.decision_owner}";
    assert target.p1_count == 1, f"target.p1_count should be 1, got {target.p1_count}";
    assert target.p2_count == 0, f"target.p2_count should be 0, got {target.p2_count}";
}

