"""Regression tests for the RoadWeaver road-snapping consistency demo.

Each test builds its own isolated graph, runs the walker(s) under test, and
asserts on observable behavior: edge creation, walker reports, and the
auditor's ``issues` list.
"""

import io;
import from contextlib { redirect_stdout }


test "snapper only modifies the target road and adds a TruncatedFrom edge to a new VirtualAnchor" {
    rt = Root();
    donor = Road(
        road_id=0,
        placements=[(666, 69, -669), (700, 70, -670), (740, 71, -671)],
        bridges=[],
        tunnels=[],
    );
    victim = Road(
        road_id=1,
        placements=[(699, 63, -689), (740, 64, -700), (780, 65, -710)],
        bridges=[],
        tunnels=[],
    );
    rt ++> donor;
    rt ++> victim;
    donor +>:Anchors(role="head"):+> VirtualAnchor(
        x=666, y=69, z=-669, donor_road_id=0
    );

    snapper = RoadSnapper(donor_anchor=(666, 69, -669), donor_id=0);
    rt spawn snapper;

    # Victim road must now have exactly one outgoing TruncatedFrom edge.
    truncated_edges = [victim ->:TruncatedFrom:->];
    assert len(truncated_edges) == 1, f"expected 1 TruncatedFrom edge, got {len(truncated_edges)}";

    anchor = truncated_edges[0];
    assert isinstance(anchor, VirtualAnchor), f"expected VirtualAnchor, got {type(anchor)}";
    assert anchor.donor_road_id == 0, f"donor_road_id should be 0, got {anchor.donor_road_id}";
    assert (anchor.x, anchor.y, anchor.z) == (666, 69, -669), f"anchor pos wrong: {(anchor.x, anchor.y, anchor.z)}";

    # Donor's original VirtualAnchor edge must be untouched.
    donor_anchors = [donor ->:Anchors:->];
    assert len(donor_anchors) == 1, f"donor should still have its Anchors edge: got {len(donor_anchors)}";
    assert isinstance(donor_anchors[0], VirtualAnchor), "donor anchor must remain a VirtualAnchor";

    # Donor road must NOT have gained a TruncatedFrom edge.
    donor_trunc = [donor ->:TruncatedFrom:->];
    assert len(donor_trunc) == 0, f"donor must not be truncated: got {len(donor_trunc)} edges";
}


test "auditor reports disconnect between virtual anchor and next placement" {
    rt = Root();
    donor = Road(
        road_id=0,
        placements=[(666, 69, -669), (700, 70, -670), (740, 71, -671)],
        bridges=[],
        tunnels=[],
    );
    victim = Road(
        road_id=1,
        placements=[(699, 63, -689), (740, 64, -700), (780, 65, -710)],
        bridges=[],
        tunnels=[],
    );
    rt ++> donor;
    rt ++> victim;

    snapper = RoadSnapper(donor_anchor=(666, 69, -669), donor_id=0);
    rt spawn snapper;

    auditor = ConsistencyAuditor();
    rt spawn auditor;

    disconnect_msgs = [m for m in auditor.issues if m.startswith("DISCONNECT")];
    assert len(disconnect_msgs) == 1, f"expected exactly 1 DISCONNECT, got {disconnect_msgs}";

    msg = disconnect_msgs[0];
    assert "DISCONNECT" in msg, f"missing DISCONNECT marker: {msg}";
    assert "666" in msg and "69" in msg and "-669" in msg, f"anchor coords missing: {msg}";
    assert "699" in msg and "63" in msg and "-689" in msg, f"first real placement missing: {msg}";
    assert "blocks" in msg, f"gap distance label missing: {msg}";

    # The reported gap must approximate 38.6 blocks (Euclidean distance between
    # (666,69,-669) and (699,63,-689)).
    import math;
    expected_gap = math.sqrt((699 - 666) ** 2 + (63 - 69) ** 2 + (-689 - (-669)) ** 2);
    assert 38.0 < expected_gap < 39.5, f"expected gap ~38.6, computed {expected_gap}";
}


test "stale bridge and tunnel spans are flagged as not recomputed against final geometry" {
    rt = Root();
    donor = Road(
        road_id=0,
        placements=[(666, 69, -669), (700, 70, -670), (740, 71, -671)],
        bridges=[],
        tunnels=[],
    );
    victim = Road(
        road_id=1,
        placements=[(699, 63, -689), (740, 64, -700), (780, 65, -710)],
        bridges=[(0, 2)],
        tunnels=[(1, 2)],
    );
    rt ++> donor;
    rt ++> victim;

    snapper = RoadSnapper(donor_anchor=(666, 69, -669), donor_id=0);
    rt spawn snapper;

    auditor = ConsistencyAuditor();
    rt spawn auditor;

    bridge_msgs = [m for m in auditor.issues if m.startswith("STALE_BRIDGE")];
    tunnel_msgs = [m for m in auditor.issues if m.startswith("STALE_TUNNEL")];
    assert len(bridge_msgs) == 1, f"expected 1 STALE_BRIDGE, got {bridge_msgs}";
    assert len(tunnel_msgs) == 1, f"expected 1 STALE_TUNNEL, got {tunnel_msgs}";

    assert "not recomputed against final geometry" in bridge_msgs[0], bridge_msgs[0];
    assert "not recomputed against final geometry" in tunnel_msgs[0], tunnel_msgs[0];
    assert "[0,2]" in bridge_msgs[0], bridge_msgs[0];
    assert "[1,2]" in tunnel_msgs[0], tunnel_msgs[0];
}


test "auditor flags out-of-range spans when placements list shrinks past span endpoints" {
    rt = Root();
    donor = Road(
        road_id=0,
        placements=[(666, 69, -669), (700, 70, -670), (740, 71, -671)],
        bridges=[],
        tunnels=[],
