"""Mandate authority: durable forward descendant query over signed spawned_by edges.

Authority derives only from parent-signed mandate receipts whose final child DID
and parent DID verify. Unsigned legacy edges remain restriction/attribution only.
The walker walks typed Parent edges and reports every descendant; caches are
verified projections only.
"""

node Agent {
    has did: str = "";
    has name: str = "";
}

# A parent-signed mandate receipt. Authority-bearing.
node Mandate {
    has parent_did: str = "";
    has child_did: str = "";
    has signed: bool = False;
    has verified: bool = False;
}

# An unsigned legacy edge. Restriction/attribution only — never confers authority.
node LegacyLink {
    has note: str = "";
}

edge Parent {
    has created_at: str = "";
}

edge Legacy {
    has reason: str = "";
}

walker DescendantAuthority {
    # Set of DIDs whose authority has been verified at the time of traversal.
    has authorized_dids: list[str] = [];

    can start with Root entry {
        visit [->:Parent:->];
    }

    can descend with Mandate entry {
        # A mandate confers authority only when signed AND verified.
        if here.signed and here.verified {
            if here.child_did not in self.authorized_dids {
                self.authorized_dids.append(here.child_did);
            }
            visit [here ->:Parent:->];
        }
        # Unsigned / unverified mandates carry no authority; stop descending
        # through this branch rather than projecting unverifiable DIDs.
    }
}

walker CollectDescendants {
    # Cycle-safe frontier of descendant DIDs.
    has seen: list[str] = [];
    has result: list[str] = [];

    can start with Root entry {
        visit [->:Parent:->];
    }

    can accumulate with Mandate entry {
        # Only include descendants whose authority is confirmed.
        if here.signed and here.verified {
            if here.child_did not in self.seen {
                self.seen.append(here.child_did);
                self.result.append(here.child_did);
            }
            visit [here ->:Parent:->];
        }
    }
}

with entry {
    # Agent identities referenced by mandates.
    alpha = Agent(did="did:alpha", name="Alpha");
    beta = Agent(did="did:beta", name="Beta");
    gamma = Agent(did="did:gamma", name="Gamma");
    delta = Agent(did="did:delta", name="Delta");
    rogue = Agent(did="did:rogue", name="Rogue");

    root ++> alpha;

    # Authority chain: alpha -> beta -> gamma (signed + verified).
    m1 = Mandate(parent_did="did:alpha", child_did="did:beta",
                 signed=True, verified=True);
    alpha +>:Parent(created_at="t0"):+> m1;

    m2 = Mandate(parent_did="did:beta", child_did="did:gamma",
                 signed=True, verified=True);
    m1 +>:Parent(created_at="t1"):+> m2;

    # Branch: beta -> delta (signed + verified).
    m3 = Mandate(parent_did="did:beta", child_did="did:delta",
                 signed=True, verified=True);
    m1 +>:Parent(created_at="t2"):+> m3;

    # Unsigned legacy edge: must NOT confer authority.
    legacy = LegacyLink(note="unsigned attribution only");
    rogue +>:Legacy(reason="legacy"):+> legacy;

    # Spawn the authority walker on the root.
    root spawn DescendantAuthority();

    # Now collect descendants whose authority has been recognized.
    collector = CollectDescendants();
    root spawn collector;

    print("Authorized descendant DIDs (forward, restart-surviving, signature-gated):");
    for did in collector.result {
        print(f"  - {did}");
    }

    # Terminate / delegate / cascade callers consume this authoritative list,
    # never the legacy attribution edges or hand-rolled _parent_children map.
    print(f"\nTotal authoritative descendants: {len(collector.result)}");
}

