"""Test annex for the signed-mandate authority descendant query."""

import io;
import from contextlib { redirect_stdout }

test "authority descends only through signed verified mandates" {
    root ++> Agent(did="did:alpha", name="Alpha");

    m1 = Mandate(parent_did="did:alpha", child_did="did:beta",
                 signed=True, verified=True);
    root +>:Parent(created_at="t0"):+> m1;

    m2 = Mandate(parent_did="did:beta", child_did="did:gamma",
                 signed=True, verified=True);
    m1 +>:Parent(created_at="t1"):+> m2;

    m3 = Mandate(parent_did="did:beta", child_did="did:delta",
                 signed=True, verified=True);
    m1 +>:Parent(created_at="t2"):+> m3;

    root spawn DescendantAuthority();

    collector = CollectDescendants();
    root spawn collector;

    assert "did:beta" in collector.result, f"missing beta: {collector.result}";
    assert "did:gamma" in collector.result, f"missing gamma: {collector.result}";
    assert "did:delta" in collector.result, f"missing delta: {collector.result}";
    assert len(collector.result) == 3, f"got {collector.result}";
}

test "unsigned legacy edges confer no authority" {
    rogue = Agent(did="did:rogue", name="Rogue");
    root ++> rogue;

    legacy = LegacyLink(note="unsigned attribution only");
    rogue +>:Legacy(reason="legacy"):+> legacy;

    # A Mandate linked only via a Legacy edge should still be considered:
    # it lacks signed/verified, so it must NOT contribute to authority.
    rogue_m = Mandate(parent_did="did:rogue", child_did="did:rogue_child",
                      signed=False, verified=False);
    rogue +>:Legacy(reason="attribution"):+> rogue_m;

    root spawn DescendantAuthority();

    collector = CollectDescendants();
    root spawn collector;

    assert "did:rogue_child" not in collector.result, f"legacy leaked authority: {collector.result}";
    assert len(collector.result) == 0, f"got {collector.result}";
}

test "unverified mandate blocks branch authority" {
    root ++> Agent(did="did:alpha", name="Alpha");

    # Branch A: signed AND verified — must appear.
    m_ok = Mandate(parent_did="did:alpha", child_did="did:ok",
                   signed=True, verified=True);
    root +>:Parent(created_at="t0"):+> m_ok;

    # Branch B: signed but NOT verified — must be excluded.
    m_unv = Mandate(parent_did="did:alpha", child_did="did:unv",
                    signed=True, verified=False);
    root +>:Parent(created_at="t1"):+> m_unv;

    # A child mandate descending from the unverified one is unreachable.
    m_under_unv = Mandate(parent_did="did:unv", child_did="did:under_unv",
                          signed=True, verified=True);
    m_unv +>:Parent(created_at="t2"):+> m_under_unv;

    root spawn DescendantAuthority();
    collector = CollectDescendants();
    root spawn collector;

    assert "did:ok" in collector.result, f"missing ok: {collector.result}";
    assert "did:unv" not in collector.result, f"unverified leaked: {collector.result}";
    assert "did:under_unv" not in collector.result, f"unverified subtree leaked: {collector.result}";
}

test "cycle in mandate graph does not loop or duplicate" {
    root ++> Agent(did="did:a", name="A");

    m1 = Mandate(parent_did="did:a", child_did="did:b",
                 signed=True, verified=True);
    root +>:Parent(created_at="t0"):+> m1;

    m2 = Mandate(parent_did="did:b", child_did="did:c",
                 signed=True, verified=True);
    m1 +>:Parent(created_at="t1"):+> m2;

    # Cycle edge: c -> a (revisits the root's child mandate).
    m_cycle = Mandate(parent_did="did:c", child_did="did:a",
                      signed=True, verified=True);
    m2 +>:Parent(created_at="t2"):+> m_cycle;

    root spawn DescendantAuthority();
    collector = CollectDescendants();
    root spawn collector;

    # Deterministic, cycle-safe: each DID listed at most once.
    assert len(collector.result) == len(collector.seen), f"dupes: {collector.result} vs {collector.seen}";
    assert collector.result.count("did:b") == 1, f"b duplicated: {collector.result}";
    assert collector.result.count("did:c") == 1, f"c duplicated: {collector.result}";
    assert collector.result.count("did:a") == 1, f"a duplicated: {collector.result}";
    assert "did:b" in collector.result, f"missing b: {collector.result}";
    assert "did:c" in collector.result, f"missing c: {collector.result}";
}

test "durable authoritative report survives fresh graph build" {
    # Cold-restart simulation: build a graph from scratch (as if reloaded from
    # persistent storage in arbitrary order) and confirm the authoritative
    # query is identical.
    root ++> Agent(did="did:alpha", name="Alpha");

    # Load order 1: deeper nodes first.
    m3 = Mandate(parent_did="did:beta", child_did="did:delta",
                 signed=True, verified=True);
    m2 = Mandate(parent_did="did:alpha", child_did="did:beta",
                 signed=True, verified=True);
    m1 = Mandate(parent_did="did:beta", child_did="did:gamma",
                 signed=True, verified=True);

    root +>:Parent(created_at="t0"):+> m2;
    m2 +>:Parent(created_at="t1"):+> m1;
    m2 +>:Parent(created_at="t2"):+> m3;

    root spawn DescendantAuthority();
    collector = CollectDescendants();
    root spawn collector;

    # Deterministic ordering (insertion order via seen/result lists).
    assert collector.result == ["did:beta", "did:gamma", "did:delta"], f"got {collector.result}";
    assert len(collector.result) == 3, f"got {collector.result}";

    # Tampered mandate: signed=True but verified=False must not appear.
    bad = Mandate(parent_did="did:alpha", child_did="did:bad",
                  signed=True, verified=False);
    root +>:Parent(created_at="t3"):+> bad;

    collector2 = CollectDescendants();
    root spawn collector2;
    assert "did:bad" not in collector2.result, f"tampered leaked: {collector2.result}";

    # Caller-side print: the program emits an authoritative list to stdout.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        collector3 = CollectDescendants();
        root spawn collector3;
        print("[OUT] authorized descendants:");
        for did in collector3.result {
            print(f"  - {did}");
        }
        print(f"[OUT] total = {len(collector3.result)}");
    }
    out = buf.getvalue();
    assert "[OUT]" in out, f"missing OUT marker: {out}";
    assert "did:beta" in out, f"missing beta in output: {out}";
    assert "did:bad" not in out, f"bad leaked to output: {out}";
}

