"""Regression tests for PedigreeCollapsePredictor.

Verifies the walker actually traverses, scores, and prints predictions;
asserts the cycle guard and depth cap from the program; and checks the
geographic/surname/temporal/record-density heuristics on representative
person nodes.
"""

import io;
import from contextlib { redirect_stdout }

test "walker prints one line per missing relation and marks as incomplete" {
    rural_a = Place(name="Dorf A", neighbors=["Dorf B"]);
    rural_b = Place(name="Dorf B", neighbors=["Dorf A"]);
    city = Place(name="Stadt X", neighbors=[]);

    p1 = Person(
        given="Anna", surname="Schmidt", birth_year=1820,
        occupation="farmer", citations=3, birth_place=rural_a,
        missing_relations=["mother", "spouse"]
    );
    p2 = Person(
        given="Hans", surname="Schmidt", birth_year=1818,
        occupation="farmer", citations=2, birth_place=rural_a,
        missing_relations=["father"]
    );

    root ++> p1;
    p1 +>:ParentLink:+> p2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn CollapsePredictor(tree_id=1, max_depth=6, limit=10);
    }
    out = buf.getvalue();

    # 2 missing relations on p1 + 1 missing on p2 = 3 prediction lines.
    n_incomplete = out.count("[incomplete]");
    assert n_incomplete == 3, f"expected 3 incomplete lines, got {n_incomplete}: {out}";

    # Each printed line should identify the person and report a composite score.
    assert "person=Anna Schmidt" in out, f"missing Anna line: {out}";
    assert "person=Hans Schmidt" in out, f"missing Hans line: {out}";
    assert "missing=mother" in out, f"missing 'missing=mother' marker: {out}";
    assert "missing=spouse" in out, f"missing 'missing=spouse' marker: {out}";
    assert "missing=father" in out, f"missing 'missing=father' marker: {out}";
}

test "score components sum to the composite written to stdout" {
    rural_a = Place(name="Dorf A", neighbors=["Dorf B"]);

    # Anna: 1820 (>= 1850? no -> 1750-1849 band -> +0.15),
    #       non-inferred place (+0.25), surname "Schmidt" (+0.2),
    #       occupation != "" (+0.05), citations>=2 (+0.05).
    #       composite = 0.25 + 0.20 + 0.15 + 0.10 = 0.70
    p1 = Person(
        given="Anna", surname="Schmidt", birth_year=1820,
        occupation="farmer", citations=3, birth_place=rural_a,
        missing_relations=["mother"]
    );
    root ++> p1;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn CollapsePredictor(tree_id=1, max_depth=6, limit=10);
    }
    out = buf.getvalue();

    assert "score=0.70" in out, f"expected composite 0.70 in output: {out}";
    assert "loc=0.25" in out, f"expected loc=0.25: {out}";
    assert "sur=0.20" in out, f"expected sur=0.20: {out}";
    assert "tmp=0.15" in out, f"expected tmp=0.15: {out}";
    assert "rec=0.10" in out, f"expected rec=0.10: {out}";
}

test "cycle guard prevents revisiting the same person by key" {
    rural_a = Place(name="Dorf A", neighbors=["Dorf B"]);

    # Two distinct Person nodes with identical given/surname/year ->
    # same dedupe key -> walker must visit at most one and only emit
    # one prediction line for that key.
    p1 = Person(
        given="Anna", surname="Schmidt", birth_year=1820,
        occupation="farmer", citations=3, birth_place=rural_a,
        missing_relations=["mother"]
    );
    p2 = Person(
        given="Anna", surname="Schmidt", birth_year=1820,
        occupation="farmer", citations=3, birth_place=rural_a,
        missing_relations=["father"]
    );

    root ++> p1;
    p1 +>:ParentLink:+> p2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn CollapsePredictor(tree_id=1, max_depth=6, limit=10);
    }
    out = buf.getvalue();

    # Only one of the duplicate-keyed persons should be processed.
    n_incomplete = out.count("[incomplete]");
    assert n_incomplete == 1, f"expected dedupe to 1 line, got {n_incomplete}: {out}";
}

test "inferred birth place contributes small location score" {
    rural_b = Place(name="Dorf B", neighbors=["Dorf A"]);

    # Klaus: birth_year 1775 (>= 1750 -> tmp +0.15),
    #        surname "Schmidt" (+0.2),
    #        occupation "miller" (+0.05), citations=1 (no +0.05),
    #        birth_place_inferred=True -> loc = 0.05.
    #        composite = 0.05 + 0.20 + 0.15 + 0.05 = 0.45
    p1 = Person(
        given="Klaus", surname="Schmidt", birth_year=1775,
        occupation="miller", citations=1, birth_place=rural_b,
        birth_place_inferred=True,
        missing_relations=["mother"]
