    root ++> p1;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn CollapsePredictor(tree_id=1, max_depth=6, limit=10);
    }
    out = buf.getvalue();

    assert "loc=0.05" in out, f"expected inferred loc=0.05: {out}";
    assert "score=0.45" in out, f"expected composite 0.45: {out}";
}

test "person with no birth place gets location score zero and no temporal bonus before 1750" {
    city = Place(name="Stadt X", neighbors=[]);

    # Eva: birth_year 1700 (< 1750 -> tmp 0.0),
    #      surname "Weber" (not in high-score set -> +0.1),
    #      no occupation, no citations -> rec 0.0,
    #      birth_place set to city BUT per the spec fallback, location_score
    #      returns 0.0 only when birth_place is None. With a Place object
    #      and not inferred, loc = 0.25. So composite = 0.25 + 0.10 + 0.0 + 0.0 = 0.35.
    p1 = Person(
        given="Eva", surname="Weber", birth_year=1700,
        occupation="", citations=0, birth_place=city,
        missing_relations=["parents"]
    );
    root ++> p1;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn CollapsePredictor(tree_id=1, max_depth=6, limit=10);
    }
    out = buf.getvalue();

    assert "tmp=0.00" in out, f"expected tmp=0.00 for pre-1750: {out}";
    assert "rec=0.00" in out, f"expected rec=0.00 with no occupation/citations: {out}";
    assert "score=0.35" in out, f"expected composite 0.35: {out}";
}

