"""DWDM blast-radius impact query.

Models the essential scenario from issue #70: when a device or module
fails, which wavelength paths (and the circuits that ride them) are
affected? Hand-rolled client-side iteration over every wavelength path
is replaced by a typed-edge walker that does the aggregation natively.

Graph shape
-----------
    WdmNode (device)
      +>:Hosts:+>
        WdmModule (line card)
          +>:Carries:+>
            WdmWavelengthPathChannel
              +>:BelongsTo:+>
                WdmWavelengthPath
                  +>:CarriesCircuit:+>
                    WdmCircuit
"""

node WdmNode {
    has name: str = "";
    has site: str = "";
}

node WdmModule {
    has name: str = "";
    has slot: int = 0;
}

node WdmWavelengthPathChannel {
    has channel_id: str = "";
    has frequency_thz: float = 0.0;
}

node WdmWavelengthPath {
    has path_id: str = "";
    has a_end: str = "";
    has z_end: str = "";
}

node WdmCircuit {
    has circuit_id: str = "";
    has customer: str = "";
}

edge Hosts {
    has installed_on: str = "";
}

edge Carries {
    has since: str = "";
}

edge BelongsTo {
    has order: int = 0;
}

edge CarriesCircuit {
    has role: str = "primary";
}

walker ImpactQuery {
    has failed_target: str = "";
    has report: list = [];
    has visited: set = {};

    can start with Root entry {
        visit [-->];
    }

    can inspect_device with WdmNode entry {
        if here.name == self.failed_target {
            print(f"[FAIL] device {here.name} at {here.site} is down");
            self.report.append(("DEVICE", here.name));
            visit [->:Hosts:->];
        } else {
            visit [-->];
        }
    }

    can inspect_module with WdmModule entry {
        if here.name == self.failed_target {
            print(f"[FAIL] module {here.name} (slot {here.slot}) is down");
            self.report.append(("MODULE", here.name));
            visit [->:Carries:->];
        } else {
            visit [-->];
        }
    }

    can collect_channel with WdmWavelengthPathChannel entry {
        if self.failed_target in self.visited {
            disengage;
        }
        self.visited.add(self.failed_target);
        print(f"  -> channel {here.channel_id} @ {here.frequency_thz} THz");
        self.report.append(("CHANNEL", here.channel_id));
        visit [->:BelongsTo:->];
    }

    can collect_path with WdmWavelengthPath entry {
        print(f"  -> wavelength path {here.path_id} ({here.a_end} -> {here.z_end})");
        self.report.append(("PATH", here.path_id));
        visit [->:CarriesCircuit:->];
    }

    can collect_circuit with WdmCircuit entry {
        print(f"  -> circuit {here.circuit_id} for {here.customer}");
        self.report.append(("CIRCUIT", here.circuit_id));
    }

    can ignore_other with WdmWavelengthPathChannel | WdmWavelengthPath | WdmCircuit entry {
        # Fallback for nodes reachable via plain --> walks that we don't
        # care about; just keep moving.
        visit [-->];
    }
}

