"""DWDM blast-radius impact: which wavelength paths and circuits ride
through a failed device or module? Models the aggregation query the
issue requests as a typed-edge walker over the WdmWavelengthPathChannel
relationships."""

node WdmNode {
    has name: str = "";
    has site: str = "";
}

node WdmModule {
    has name: str = "";
    has slot: int = 0;
}

node WdmWavelengthPath {
    has label: str = "";
    has frequency: float = 0.0;
}

node WdmCircuit {
    has circuit_id: str = "";
    has customer: str = "";
}

edge Hosts {
    has since: str = "";
}

edge CarriesPath {
    has direction: str = "tx";
}

edge RealizesCircuit {
    has order: int = 0;
}

walker ImpactAnalyzer {
    has paths: list = [];
    has circuits: list = [];

    can start with Root entry {
        visit [-->];
    }

    can on_node with WdmNode entry {
        print(f"== Impact analysis for node '{here.name}' ({here.site}) ==");
        # Walk: node -> hosted modules -> wavelength paths -> circuits.
        visit [->:Hosts:->];
    }

    can on_module with WdmModule entry {
        print(f"== Impact analysis for module '{here.name}' slot {here.slot} ==");
        # From a module, hop straight to the wavelength paths it carries.
        visit [->:CarriesPath:->];
    }

    can collect_path with WdmWavelengthPath entry {
        if here not in self.paths {
            self.paths.append(here);
        }
        visit [->:RealizesCircuit:->];
    }

    can collect_circuit with WdmCircuit entry {
        if here not in self.circuits {
            self.circuits.append(here);
        }
    }
}

