test "node impact aggregates paths and circuits" {
    device = WdmNode(name="core-east", site="NYC1");
    root ++> device;

    module = WdmModule(name="linecard-1", slot=3);
    device +>:Hosts(since="2024-Q1"):+> module;

    path1 = WdmWavelengthPath(label="lambda1", frequency=193.0);
    path2 = WdmWavelengthPath(label="lambda2", frequency=193.1);
    module +>:CarriesPath(direction="tx"):+> path1;
    module +>:CarriesPath(direction="rx"):+> path2;

    circuit1 = WdmCircuit(circuit_id="CKT-1", customer="ACME");
    circuit2 = WdmCircuit(circuit_id="CKT-2", customer="Globex");
    path1 +>:RealizesCircuit(order=1):+> circuit1;
    path2 +>:RealizesCircuit(order=1):+> circuit2;

    res = device spawn ImpactAnalyzer();

    assert len(res.paths) == 2, f"got {len(res.paths)} paths";
    assert path1 in res.paths, f"missing {path1.label}";
    assert path2 in res.paths, f"missing {path2.label}";
    assert len(res.circuits) == 2, f"got {len(res.circuits)} circuits";
    assert circuit1 in res.circuits, f"missing {circuit1.circuit_id}";
    assert circuit2 in res.circuits, f"missing {circuit2.circuit_id}";
}

test "module impact returns only carried paths and their circuits" {
    device = WdmNode(name="core-west", site="CHI1");
    root ++> device;

    target = WdmModule(name="linecard-A", slot=1);
    sibling = WdmModule(name="linecard-B", slot=2);
    device +>:Hosts(since="2024-Q2"):+> target;
    device +>:Hosts(since="2024-Q2"):+> sibling;

    target_path = WdmWavelengthPath(label="target", frequency=193.2);
    sibling_path = WdmWavelengthPath(label="sibling", frequency=193.3);
    target +>:CarriesPath(direction="tx"):+> target_path;
    sibling +>:CarriesPath(direction="tx"):+> sibling_path;

    target_circuit = WdmCircuit(circuit_id="CKT-T", customer="ACME");
    sibling_circuit = WdmCircuit(circuit_id="CKT-S", customer="Globex");
    target_path +>:RealizesCircuit(order=1):+> target_circuit;
    sibling_path +>:RealizesCircuit(order=1):+> sibling_circuit;

    res = target spawn ImpactAnalyzer();

    assert len(res.paths) == 1, f"got {len(res.paths)} paths";
    assert target_path in res.paths, f"missing {target_path.label}";
    assert sibling_path not in res.paths, f"unexpected {sibling_path.label}";
    assert len(res.circuits) == 1, f"got {len(res.circuits)} circuits";
    assert target_circuit in res.circuits, f"missing {target_circuit.circuit_id}";
    assert sibling_circuit not in res.circuits, f"unexpected {sibling_circuit.circuit_id}";
}

test "node impact deduplicates shared paths and circuits" {
    device = WdmNode(name="shared-node", site="NYC1");
    root ++> device;

    module1 = WdmModule(name="linecard-1", slot=1);
    module2 = WdmModule(name="linecard-2", slot=2);
    device +>:Hosts(since="2024-Q1"):+> module1;
    device +>:Hosts(since="2024-Q1"):+> module2;

    shared_path = WdmWavelengthPath(label="shared", frequency=193.5);
    module1 +>:CarriesPath(direction="tx"):+> shared_path;
    module2 +>:CarriesPath(direction="rx"):+> shared_path;

    shared_circuit = WdmCircuit(circuit_id="CKT-SHARED", customer="Initech");
    shared_path +>:RealizesCircuit(order=1):+> shared_circuit;

    res = device spawn ImpactAnalyzer();

    assert len(res.paths) == 1, f"got {len(res.paths)} paths";
    assert res.paths[0] == shared_path, f"got unexpected path";
    assert len(res.circuits) == 1, f"got {len(res.circuits)} circuits";
    assert res.circuits[0] == shared_circuit, f"got unexpected circuit";
}

