"""S3-style bucket listing: model the recursive file traversal that
balloons memory when the whole listing is materialized before being written
out. A walker streams bucket -> prefix -> key nodes one at a time so
nothing is buffered into a giant in-memory list."""

node Bucket {
    has name: str = "";
    has region: str = "";
}

node Prefix {
    has name: str = "";
    has depth: int = 0;
}

node Key {
    has key_name: str = "";
    has size_bytes: int = 0;
    has available: bool = True;
}

edge ContainsPrefix {
    has recursive: bool = True;
}

edge ContainsKey {
    has recursive: bool = True;
}

walker LsStreamer {
    has streamed_count: int = 0;
    has total_bytes: int = 0;
    has max_in_flight: int = 1;

    can start with Root entry {
        print(f"s3cmd ls --recursive starting under root");
        visit [-->];
    }

    can enter_bucket with Bucket entry {
        print(f"[BUCKET] s3://{here.name}  region={here.region}");
        # Stream prefixes and keys one node at a time; never buffer the
        # whole tree. The walker carries state on self.* so each visit
        # is O(1) memory regardless of fan-out.
        visit [->:ContainsPrefix:->];
        visit [->:ContainsKey:->];
    }

    can descend with Prefix entry {
        prefix_path = f"{here.name}/";
        print(f"[PREFIX d={here.depth}] {prefix_path}");
        visit [->:ContainsPrefix:->];
        visit [->:ContainsKey:->];
    }

    can emit_key with Key entry {
        # This is the "write to stdout after each API request" path:
        # each key is emitted immediately on visit, not accumulated.
        self.streamed_count += 1;
        self.total_bytes += here.size_bytes;
        marker = "" if here.available else " (DELETED)";
        print(f"  -> {here.key_name}  size={here.size_bytes}{marker}");
    }
}

with entry {
    # Wire a small bucket/prefix/key graph. The ContainsPrefix /
    # ContainsKey typed edges carry the recursion flag so the walker
    # traverses the *same* shape s3cmd uses for --recursive.
    data_lake = Bucket(name="data-lake", region="us-east-1");
    archive = Bucket(name="archive", region="eu-west-1");
    raw = Prefix(name="raw", depth=1);
    cleaned = Prefix(name="cleaned", depth=1);
    events = Prefix(name="events", depth=2);
    k1 = Key(key_name="raw/2024-01.parquet", size_bytes=4096);
    k2 = Key(key_name="raw/2024-02.parquet", size_bytes=8192);
    k3 = Key(key_name="cleaned/jan.parquet", size_bytes=2048);
    k4 = Key(key_name="cleaned/events/click.parquet",
             size_bytes=512, available=False);

    root ++> data_lake;
    data_lake +>:ContainsPrefix(recursive=True):+> raw;
    data_lake +>:ContainsPrefix(recursive=True):+> cleaned;
    raw +>:ContainsKey(recursive=True):+> k1;
    raw +>:ContainsKey(recursive=True):+> k2;
    cleaned +>:ContainsKey(recursive=True):+> k3;
    cleaned +>:ContainsPrefix(recursive=True):+> events;
    events +>:ContainsKey(recursive=True):+> k4;

    root ++> archive;

    streamer = LsStreamer(max_in_flight=1);
    root spawn streamer;

    print(f"--- streamed {streamer.streamed_count} keys, "
          f"{streamer.total_bytes} bytes total ---");
    print("(in the original bug all of these would be held in memory "
          "before the first stdout write; the walker emits per-visit)");
}

