"""Test annex for s3cmd recursive ls streaming walker."""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
test "streams every key from one bucket exactly once" {
    # Single bucket with two prefixes, two leaves each -> 4 keys emitted.
    b = Bucket(name="b1", region="us-east-1");
    p1 = Prefix(name="raw", depth=1);
    p2 = Prefix(name="cleaned", depth=1);
    k1 = Key(key_name="raw/a.parquet", size_bytes=10);
    k2 = Key(key_name="raw/b.parquet", size_bytes=20);
    k3 = Key(key_name="cleaned/c.parquet", size_bytes=30);
    k4 = Key(key_name="cleaned/d.parquet", size_bytes=40);

    root ++> b;
    b +>:ContainsPrefix(recursive=True):+> p1;
    b +>:ContainsPrefix(recursive=True):+> p2;
    p1 +>:ContainsKey(recursive=True):+> k1;
    p1 +>:ContainsKey(recursive=True):+> k2;
    p2 +>:ContainsKey(recursive=True):+> k3;
    p2 +>:ContainsKey(recursive=True):+> k4;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LsStreamer();
    }
    out = buf.getvalue();

    assert res.streamed_count == 4,
        f"expected 4 streamed keys, got {res.streamed_count}";
    assert res.total_bytes == 100,
        f"expected 100 total bytes, got {res.total_bytes}";
    for kn in ["raw/a.parquet", "raw/b.parquet",
               "cleaned/c.parquet", "cleaned/d.parquet"] {
        assert kn in out, f"key '{kn}' missing from output: {out}";
    }
    assert "[BUCKET] s3://b1  region=us-east-1" in out,
        f"bucket header missing: {out}";
}

# ---------------------------------------------------------------------------
test "handles two buckets and aggregates across them" {
    b1 = Bucket(name="b1", region="us-east-1");
    b2 = Bucket(name="b2", region="eu-west-1");
    k1 = Key(key_name="x.parquet", size_bytes=5);
    k2 = Key(key_name="y.parquet", size_bytes=25);

    root ++> b1;
    root ++> b2;
    b1 +>:ContainsKey(recursive=True):+> k1;
    b2 +>:ContainsKey(recursive=True):+> k2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LsStreamer();
    }
    out = buf.getvalue();

    assert res.streamed_count == 2,
        f"expected 2 keys across buckets, got {res.streamed_count}";
    assert res.total_bytes == 30,
        f"bytes from both keys, got {res.total_bytes}";
    assert ("s3://b1" in out and "s3://b2" in out),
        f"both bucket headers expected: {out}";
}

# ---------------------------------------------------------------------------
test "empty bucket emits header but zero keys and zero bytes" {
    e = Bucket(name="empty", region="ap-south-1");
    root ++> e;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LsStreamer();
    }
    out = buf.getvalue();

    assert "[BUCKET] s3://empty  region=ap-south-1" in out,
        f"empty bucket header missing: {out}";
    assert res.streamed_count == 0,
        f"no keys to stream, got {res.streamed_count}";
    assert res.total_bytes == 0,
