    assert "raw/gone.parquet" in out, f"deleted key missing: {out}";
    assert "(DELETED)" in out, f"deleted marker missing: {out}";
    # The live key line must NOT carry the deleted marker.
    assert not "raw/live.parquet  size=100 (DELETED)" in out,
        f"live key incorrectly flagged DELETED: {out}";
