# ---------------------------------------------------------------------------
test "recurses through nested prefixes to find deep keys" {
    b = Bucket(name="lake", region="us-west-2");
    p1 = Prefix(name="year", depth=1);
    p2 = Prefix(name="month", depth=2);
    p3 = Prefix(name="day", depth=3);
