    root ++> b;
    b +>:ContainsPrefix(recursive=True):+> p1;
    p1 +>:ContainsPrefix(recursive=True):+> p2;
    p2 +>:ContainsPrefix(recursive=True):+> p3;
    p3 +>:ContainsKey(recursive=True):+> deep;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LsStreamer();
    }
    out = buf.getvalue();

    assert res.streamed_count == 1,
        f"deep key reached, got {res.streamed_count}";
    assert res.total_bytes == 7,
        f"deep key bytes, got {res.total_bytes}";
    assert "year/month/day/x.parquet" in out,
        f"deep key output missing: {out}";
    # All three prefix depths reported.
    assert "[PREFIX d=1]" in out and "[PREFIX d=2]" in out and "[PREFIX d=3]" in out,
        f"all prefix headers expected: {out}";
}

