# ---------- Entities ----------

node GraphNode {
    has label: str = "";
}

node VisualizationFrame {
    has step: int = 0;
    has visited: list[str] = [];
    has frontier: list[str] = [];
    has current: str = "";
    has edge_taken: str = "";
}

# ---------- Relationships ----------

edge Adjacent { }

# ---------- Walkers ----------

walker GraphVisualizer {
    has mode: str = "BFS";
    has frames: list[VisualizationFrame] = [];
    has frontier: list[str] = [];
    has visited: list[str] = [];
    has last_edge: str = "";
    has last_dst: str = "";

    can start with Root entry {
        print(f"GraphVisualizer starting in {self.mode} mode");
        # Seed the walk at the spawned graph root's first neighbor.
        visit [->:Adjacent:->];
    }

    can snapshot with GraphNode entry {
        # Record the current node as a new frame and update walker state.
        self.last_dst = here.label;
        if here.label not in self.visited {
            self.visited.append(here.label);
        }
        if self.mode == "BFS" {
            if here.label not in self.frontier {
                self.frontier.append(here.label);
            }
        } else {
            if here.label not in self.frontier {
                self.frontier = [here.label] + self.frontier;
            }
        }
        self.frames.append(
            VisualizationFrame(
                step=len(self.frames),
                current=here.label,
                visited=list(self.visited),
                frontier=list(self.frontier),
                edge_taken=self.last_edge
