# --- Subject node archetypes ---------------------------------------------------

node File {
    has path: str = "";
    has revision: str = "";
}

node Module {
    has name: str = "";
    has file_path: str = "";
}

node Package {
    has name: str = "";
    has version: str = "";
}

node ExternalBoundary {
    # "unknown / unavailable target" — represents dynamic imports, missing
    # symbols, etc. as a first-class subject rather than a dangling string.
    has reason: str = "";
}

# --- Typed semantic edge archetypes -------------------------------------------

edge DependsOn {
    # Generic dependency: file -> module/package/external.
    has kind: str = "use";          # "use" | "require" | "import"
    has ordinal: int = 0;           # source order matters for some
    has confidence: float = 1.0;
    has producer: str = "scanner";
}

edge InheritsFrom {
    has kind: str = "static";       # "static" | "dynamic"
    has ordinal: int = 0;
    has confidence: float = 1.0;
    has producer: str = "scanner";
}

edge TestsTarget {
    has ordinal: int = 0;
    has confidence: float = 1.0;
    has producer: str = "scanner";
}

# --- Traversal walker ---------------------------------------------------------

walker DependencyAuditor {
    has visited: list[str] = [];    # explicit cycle guard (no built-in dedupe)
    has invalidation: list[str] = [];  # accumulated for the single exit report
    has depth_limit: int = 8;

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can audit with File | Module | Package | ExternalBoundary entry {
        nid = here.__class__.__name__ + ":" + (
            here.path if isinstance(here, File) else (
                here.file_path if isinstance(here, Module) else (
                    here.name if isinstance(here, Package) else here.reason
                )
            )
        );
        if nid in self.visited {
            # Cycle policy: surface it, don't loop forever.
            print(f"[cycle] revisit {nid}");
            self.invalidation.append(f"cycle:{nid}");
            disengage;
        }
        if self.depth_limit <= 0 {
            print(f"[depth-cap] stopping at {nid}");
            self.invalidation.append(f"depth-cap:{nid}");
            disengage;
        }
        self.visited.append(nid);
        self.invalidation.append(nid);
        next_limit = self.depth_limit - 1;
        self.depth_limit = next_limit;
        visit [->:DependsOn:->] else {
            # Dead end — external boundary or leaf. Record it as a
            # boundary marker so callers can see what terminates a chain.
            print(f"[boundary] {nid}");
            disengage;
        }
    }

    can summarize with Root entry {
        print(f"[report] visited={len(self.visited)} "
              f"invalidations={self.invalidation}");
    }
}

walker InheritanceWalker {
    can start with Root entry {
        visit [->:InheritsFrom:->];
    }

    can trace with Module | Package entry {
        kind_label = here.__class__.__name__ + ":" + here.name;
        print(f"[inherit] {kind_label} (origin={self.cur_inherit_kind})");
        visit [->:InheritsFrom:->];
    }

