"""Tests for the modernization-gap claim/evidence auditor."""

import io;
import from contextlib { redirect_stdout }

# Helper: build a fresh graph and run the auditor, capturing stdout.
def run_auditor {
    buf = io.StringIO();
    auditor = ClaimAuditor();
    with redirect_stdout(buf) {
        root spawn auditor;
    }
    return (auditor, buf.getvalue());
}

test "claims lacking any evidence are flagged unsupported" {
    root ++> Claim(title="no-evidence claim A", lane="x", claim_id="#1");
    root ++> Claim(title="no-evidence claim B", lane="y", claim_id="#2");
    (auditor, _) = run_auditor();
    assert len(auditor.unsupported) == 2, f"both no-evidence claims should be unsupported: {auditor.unsupported}";
    assert "no-evidence claim A" in auditor.unsupported, f"missing A: {auditor.unsupported}";
    assert "no-evidence claim B" in auditor.unsupported, f"missing B: {auditor.unsupported}";
    assert len(auditor.proven) == 0, f"nothing should be proven: {auditor.proven}";
    assert len(auditor.stale_claims) == 0, f"nothing should be stale: {auditor.stale_claims}";
}

test "claim with deterministic evidence is proven and not flagged stale" {
    c = Claim(title="deterministic claim", lane="dep", claim_id="#10");
    root ++> c;
    ev = Evidence(title="base-head receipt", source="lockfile.diff", deterministic=True);
    c +>:BackedBy(observed_at="2024-W14", stale=False):+> ev;
    (auditor, _) = run_auditor();
    assert "deterministic claim" in auditor.proven, f"should be proven: {auditor.proven}";
    assert "deterministic claim" not in auditor.unsupported, f"should not be unsupported: {auditor.unsupported}";
    assert "deterministic claim" not in auditor.stale_claims, f"should not be stale: {auditor.stale_claims}";
}

test "claim backed only by stale evidence is classified stale not unsupported" {
    c = Claim(title="stale-backed claim", lane="ci", claim_id="#20");
    root ++> c;
    ev = Evidence(title="moving toolchain row", source="ci/stable", deterministic=False);
    c +>:BackedBy(observed_at="2024-W10", stale=True):+> ev;
    (auditor, _) = run_auditor();
    assert "stale-backed claim" in auditor.stale_claims, f"stale evidence must mark the claim stale: {auditor.stale_claims}";
    assert "stale-backed claim" not in auditor.proven, f"stale claim must not also be proven: {auditor.proven}";
    assert "stale-backed claim" not in auditor.unsupported, f"stale-backed claim must not be re-flagged unsupported: {auditor.unsupported}";
}

test "policy adjacency reflects governed-by edge presence" {
    gov_claim = Claim(title="governed claim", lane="api", claim_id="#30");
    ungoverned = Claim(title="ungoverned claim", lane="api", claim_id="#31");
    root ++> gov_claim;
    root ++> ungoverned;
    pol = Policy(title="API support tiers", strict=True);
    gov_claim +>:GovernedBy:+> pol;
    (auditor, _) = run_auditor();
    assert "governed claim" in auditor.policy_adjacent, f"governed claim should be policy-adjacent: {auditor.policy_adjacent}";
    assert "ungoverned claim" not in auditor.policy_adjacent, f"ungoverned claim must not be policy-adjacent: {auditor.policy_adjacent}";
    assert len(auditor.policy_adjacent) == 1, f"exactly one policy-adjacent claim: {auditor.policy_adjacent}";
}

test "review notes are printed to stdout for each annotated claim" {
    a = Claim(title="annotated A", lane="x", claim_id="#40");
    b = Claim(title="annotated B", lane="y", claim_id="#41");
    c = Claim(title="unannotated", lane="z", claim_id="#42");
    root ++> a;
    root ++> b;
    root ++> c;
    n1 = ReviewNote(message="first annotation");
    n2 = ReviewNote(message="second annotation");
    a +>:AnnotatedBy:+> n1;
    b +>:AnnotatedBy:+> n2;
    (auditor, out) = run_auditor();
    assert "note: first annotation" in out, f"missing first annotation in stdout: {out}";
    assert "note: second annotation" in out, f"missing second annotation in stdout: {out}";
    assert out.count("note:") == 2, f"exactly two notes expected: {out}";
}

