node Namespace {
    has name: str = "";
    has owner: str = "";
    has members: list[str] = [];
    has groups: list[str] = [];
}

node Group {
    has name: str = "";
    has owner: str = "";
    has members: list[str] = [];
    has subgroups: list[str] = [];
}

