    has leaver: str = "";
    has visited: list[str] = [];
    has target_scopes: list[NodeArchitecture] = [];
    has failures: list[str] = [];
    has removals: list[str] = [];

    def already_seen(scope_name: str) -> bool {
        for v in self.visited {
            if v == scope_name {
                return True;
            }
        }
        return False;
    }

    def record_visit(scope_name: str) -> None {
        if not self.already_seen(scope_name) {
            self.visited.append(scope_name);
        }
    }

