    can gather with Namespace entry {
        # Phase 1: collect every scope where the leaver holds a direct row.
        self.record_visit(here.name);
        for g_name in here.groups {
            for g in [-->](?:Group) {
                if g.name == g_name and self.leaver in g.members {
                    self.target_scopes.append(g);
                }
            }
