        }
        self.record_visit(here.name);
        if self.leaver in here.members {
            entry = NodeArchitecture(name=here.name, kind="Group");
            self.target_scopes.append(entry);
        }
        for sg_name in here.subgroups {
            for sg in [-->](?:Subgroup) {
