def normalize(raw: str) -> str {
    segments = raw.split("/");
    cleaned: list[str] = [];
    for seg in segments {
        s = seg.strip();
        s = s.replace("  ", " ");
        s = s.replace("  ", " ");
        cleaned.append(s);
    }
    return "/".join(cleaned);
}

def build_path(parent: str, child: str) -> str {
    if parent == "" {
        return child;
    }
    return parent + "/" + child;
}

