"""SVG paint pipeline: walk the DOM directly to emit paint commands.

Models the architectural shift in DioxusLabs/blitz issue #701 — replace the
"serialize to usvg and re-parse" hand-rolled machinery with a walker that
traverses the live SVG DOM and emits per-node paint commands. The walker
demonstrates:

  * typed-edge traversal over the parent/child SVG tree
  * presentation-hint inheritance (attr -> cascade -> style override)
  * cycle-safe DFS using an explicit visited-set (jac 0.36.1 walkers have
    no built-in once-per-node)
  * an "invalidation" pass that mirrors the cascade-damage region the
    Rust code computes when a node mutates
"""

# --- Entity archetypes ---------------------------------------------------

node SvgRoot {
    has view_box: str = "0 0 100 100";
    has width: float = 100.0;
    has height: float = 100.0;
}

node SvgElement {
    has tag: str = "";
    has fill_attr: str = "";       # presentational hint (author attr)
    has style_fill: str = "";      # cascade / stylesheet value (overrides attr)
    has stroke_attr: str = "";
    has style_stroke: str = "";
    has geometry: str = "";        # d="..." / cx="50" / points="..." etc.
    has cached_path: str = "";     # flattened kurbo::BezPath equivalent
    has valid: bool = True;        # False = needs repaint (damage)
}

node PaintCommand {
    has cmd: str = "";
    has target_tag: str = "";
}

# --- Edge archetypes -----------------------------------------------------

edge ChildOf {
    has order: int = 0;
}

edge Emits {
    has seq: int = 0;
}

# --- Walker: PaintSvg ----------------------------------------------------

walker PaintSvg {
    has visited: list = [];
    has order: int = 0;

    can start with Root entry {
        print(f"[paint] begin SVG traversal, viewBox={here.view_box}");
        self.visited = [];
        self.order = 0;
        visit [->:ChildOf:->];
    }

    can paint_node with SvgElement entry {
        tag = here.tag;
        # Cycle guard: jac 0.36.1 has no built-in dedupe on visit.
        if tag in self.visited {
            print(f"[paint]   skip cycle: <{tag}> already visited");
            disengage;
        }
        self.visited.append(tag);

        # Domain logic that must survive the lift: presentational hint
        # inheritance. style overrides attr (cascade order).
        attr_fill = here.fill_attr;
        css_fill = here.style_fill;
        effective_fill = css_fill if css_fill != "" else attr_fill;

        attr_stroke = here.stroke_attr;
        css_stroke = here.style_stroke;
        effective_stroke = css_stroke if css_stroke != "" else attr_stroke;

        # Damage region: only invalid subtrees emit paint commands.
        if not here.valid {
            self.order += 1;
            cmd = (
                f"fill({effective_fill}) stroke({effective_stroke}) "
                f"path={here.cached_path}"
            );
            root +>:Emits(seq=self.order):+> PaintCommand(
                cmd=cmd,
                target_tag=here.tag,
            );
            print(f"[paint]   <{tag}> fill={effective_fill} stroke={effective_stroke} (re-emitting)");
        } else {
            print(f"[paint]   <{tag}> fill={effective_fill} stroke={effective_stroke} (clean)");
        }
        visit [->:ChildOf:->];
    }

    can descend with SvgRoot entry {
        if here.view_box == "" {
            print("[paint] no viewBox on <svg> root; cannot layout");
            disengage;
        }
        print(f"[paint] <svg> viewBox='{here.view_box}' {here.width}x{here.height}");
        self.visited = [];
        visit [->:ChildOf:->];
    }
}

# --- Walker: InvalidateSubtree -------------------------------------------

walker InvalidateSubtree {
    # Mirrors DocumentMutator damage propagation: a mutated node marks
    # itself and all descendants invalid so the next paint pass re-emits.

    can start with Root entry {
        print("[invalidate] starting damage walk");
        visit [->:ChildOf:->];
    }

    can damage with SvgElement entry {
        here.valid = False;
        print(f"[invalidate]   damaged <{here.tag}>");
        visit [->:ChildOf:->];
    }

    can damage_root with SvgRoot entry {
        print(f"[invalidate] <svg> root retained (replaced-element sizing)");
        visit [->:ChildOf:->];
    }
}

# --- Demo wiring ---------------------------------------------------------

with entry {
