"""Regression tests for the blitz SVG pipeline demo.

Exercises the two-phase pipeline (Cascade, then Paint) over a small SVG
subtree attached as ordinary DOM nodes, and verifies that:

- Every SVG node gets one StyleCascade attached (one cascade node per
  SVG node, populated by the Cascade walker).
- Every SVG node gets one PaintCommand attached (one paint emission per
  visible node, including the SvgRoot viewport command).
- Presentation attrs on SVG nodes are promoted into the cascade
  (fill='tomato' must surface as resolved_fill='tomato' on the cascade
  node; defaulting kicks in when an attr is absent: currentColor / none).
- The cycle guard actually fires: a node that is its own ChildOf target
  must not produce more than one cascade / paint emission, i.e. the
  walker disengages on the second visit instead of looping forever.
- A separate Cascade-then-Paint run over a fresh graph yields the
  expected paint command count for a four-node subtree.
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Test 1: every SVG node gets exactly one StyleCascade, fill is promoted.
# ---------------------------------------------------------------------------
test "cascade attaches one StyleCascade per node and promotes fill" {
    root_svg = SvgRoot(view_box="0 0 100 100");
    rect = SvgNode(tag="rect", fill="tomato", geometry="M0,0 h10 v10 h-10 z");
    circ = SvgNode(tag="circle", fill="steelblue", geometry="M50,50 a10,10 0 1,0 0.001,0");
    root_svg +>:ChildOf:+> rect;
    root_svg +>:ChildOf:+> circ;
    root ++> root_svg;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Cascade();
    }

    cascades_for_rect = [rect ->:CascadedBy:->];
    cascades_for_circ = [circ ->:CascadedBy:->];
    assert len(cascades_for_rect) == 1, f"rect must have exactly one cascade, got {len(cascades_for_rect)}";
    assert len(cascades_for_circ) == 1, f"circle must have exactly one cascade, got {len(cascades_for_circ)}";

    rect_cascade = cascades_for_rect[0];
    circ_cascade = cascades_for_circ[0];
    assert rect_cascade.resolved_fill == "tomato", f"rect fill must be promoted, got {rect_cascade.resolved_fill}";
    assert rect_cascade.resolved_stroke == "none", f"absent stroke defaults to none, got {rect_cascade.resolved_stroke}";
    assert circ_cascade.resolved_fill == "steelblue", f"circle fill must be promoted, got {circ_cascade.resolved_fill}";
}

# ---------------------------------------------------------------------------
# Test 2: defaulting when attrs are absent (currentColor / none).
# ---------------------------------------------------------------------------
test "cascade defaults absent fill to currentColor and stroke to none" {
    root_svg = SvgRoot(view_box="0 0 50 50");
    bare = SvgNode(tag="g", geometry="");
    root_svg +>:ChildOf:+> bare;
    root ++> root_svg;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Cascade();
    }

    cascades = [bare ->:CascadedBy:->];
    assert len(cascades) == 1, f"expected one cascade on bare node, got {len(cascades)}";
    assert cascades[0].resolved_fill == "currentColor", f"absent fill must default to currentColor, got {cascades[0].resolved_fill}";
    assert cascades[0].resolved_stroke == "none", f"absent stroke must default to none, got {cascades[0].resolved_stroke}";
}

# ---------------------------------------------------------------------------
# Test 3: paint walker emits one command per node plus a viewport for root.
# ---------------------------------------------------------------------------
test "paint emits one viewport command for SvgRoot and one per SvgNode" {
    root_svg = SvgRoot(view_box="0 0 200 200", intrinsic_w=200.0, intrinsic_h=200.0);
    rect = SvgNode(tag="rect", fill="tomato", geometry="M10,10 h80 v80 h-80 z");
    circ = SvgNode(tag="circle", fill="steelblue", geometry="M150,50 a40,40 0 1,0 0.001,0");
    text_node = SvgNode(tag="text", fill="black", geometry="M20,180");
    line = SvgNode(tag="line", stroke="black", stroke_width=2.0, geometry="M0,100 L200,100");
    root_svg +>:ChildOf:+> rect;
    root_svg +>:ChildOf:+> circ;
    root_svg +>:ChildOf:+> text_node;
    root_svg +>:ChildOf:+> line;
    root ++> root_svg;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Paint();
    }

    assert res.command_count == 5, f"expected 5 paint commands (1 viewport + 4 nodes), got {res.command_count}";

    root_cmds = [root_svg ->:PaintedAs:->];
    rect_cmds = [rect ->:PaintedAs:->];
    line_cmds = [line ->:PaintedAs:->];
    assert len(root_cmds) == 1, f"SvgRoot must have exactly one paint command, got {len(root_cmds)}";
