"""Synthetic-world test platform: model plugins, scenarios, and fixtures as a graph.

Models the elizaOS issue's core complaint: a fragmented test foundation where
plugins, scenarios, and mock-model fixtures are not unified into one resettable
synthetic world. Walkers traverse the graph to audit coverage gaps, simulate
the two model modes (strict mock vs. real-model 3/3 stability), and surface
uncovered runtime surfaces.
"""

node Plugin {
    has name: str = "";
    has surfaces: list[str] = [];
    has in_scenario: bool = False;
    has mock_fixture_count: int = 0;
}

node Scenario {
    has name: str = "";
    has model_mode: str = "strict_mock";
    has first_pass: bool = False;
    has stable_3_of_3: bool = False;
}

node Fixture {
    has provider: str = "";
    has registered: int = 0;
    has used: int = 0;
    has unmatched: int = 0;
}

edge HasSurface {
    has kind: str = "";
}

edge CoveredBy;

edge RegisteredFor;

walker CoverageAuditor {
    has uncovered: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Plugin entry {
        report_label = "COVERED" if here.in_scenario else "UNCOVERED";
        print(f"[{report_label}] plugin {here.name} surfaces={here.surfaces}");
        if not here.in_scenario {
            self.uncovered.append(here.name);
        }
        visit [->:CoveredBy:->];
