fixed.jac_tests:
"""Tests for DeepCopy cycle-safety demo.

The issue promises that a `CopyWalker` threads a visited map through the
traversal so a node reached twice returns its existing copy rather than
recursing. These tests build small cyclic graphs and assert that:

1. The traversal terminates (the visitor does not blow the stack).
2. Each distinct source node is copied at most once.
3. The same source node, reached again through a cycle, yields no
   second copy and the count of distinct copies equals the count of
   distinct source nodes.
4. The rewalker walker, which mirrors the rewriter's visited-set
   semantics, also terminates and stops on back-edges.
"""

import io;
import from contextlib { redirect_stdout }

def _run_on(roots: list) -> str {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        for r in roots {
            copier = CopyWalker();
            r spawn copier;
        }
    }
    return buf.getvalue();
}

def _run_rewriter_on(roots: list) -> str {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        for r in roots {
            rewriter = RewriterWalker();
            r spawn rewriter;
        }
    }
    return buf.getvalue();
}

test "self-referential schema copy terminates and reuses copy" {
    # Schema that points to itself via a SchemaChild edge.
    s = Schema(name="RootSchema");
    s +>:SchemaChild:+> s;

    out = _run_on([s]);

    # The first visit must copy, the back-edge must report the cycle hit.
    assert "copying schema RootSchema" in out, f"first visit did not copy: {out}";
    assert "cycle hit on schema RootSchema -> reusing copy" in out,
        f"back-edge not short-circuited: {out}";
    # Exactly one copy + one cycle-hit message; no recursion storm.
    assert out.count("copying schema RootSchema") == 1,
        f"expected exactly 1 copy, got {out.count('copying schema RootSchema')}";
    assert out.count("cycle hit on schema RootSchema -> reusing copy") == 1,
        f"expected exactly 1 cycle hit, got {out.count('cycle hit on schema RootSchema -> reusing copy')}";
}

test "self-referential encoding copy terminates and reuses copy" {
    e = Encoding(name="RootEncoding");
    e +>:EncodingChild:+> e;

    out = _run_on([e]);

    assert "copying encoding RootEncoding" in out, f"first visit did not copy: {out}";
    assert "cycle hit on encoding RootEncoding -> reusing copy" in out,
        f"back-edge not short-circuited: {out}";
    assert out.count("copying encoding RootEncoding") == 1,
        f"expected exactly 1 encoding copy: {out}";
    assert out.count("cycle hit on encoding RootEncoding -> reusing copy") == 1,
        f"expected exactly 1 cycle hit on encoding: {out}";
}

test "media type reaching cyclic encoding copies each node once" {
    # mt -> e (MediaEncoding) -> e (EncodingChild): the encoding is reached
    # both directly from mt and from itself. Distinct node count = 2.
    e = Encoding(name="RootEncoding");
    e +>:EncodingChild:+> e;
    mt = MediaType(name="RootMediaType");
    mt +>:MediaEncoding:+> e;

    out = _run_on([mt]);

    assert "copying media type RootMediaType" in out,
        f"media type not copied: {out}";
    assert "copying encoding RootEncoding" in out,
        f"cyclic encoding not copied on first reach: {out}";
    # The second reach (through the cycle) must be a hit, not a recopy.
    assert "cycle hit on encoding RootEncoding -> reusing copy" in out,
        f"second reach did not short-circuit: {out}";
    # The media type's direct edge to e counts as the encoding's first
    # reach, so exactly one copy of each distinct node.
    assert out.count("copying encoding RootEncoding") == 1,
        f"encoding copied more than once: {out}";
    assert out.count("copying media type RootMediaType") == 1,
        f"media type copied more than once: {out}";
    # No rewriter messages leaked into the copier run.
    assert "rewriter cycle-safe" not in out, f"unexpected rewriter output: {out}";
}

test "rewriter walker also short-circuits on cycles" {
    # The issue calls out that the rewriter's visited-set is the
    # reference behavior; the copier's visited map is supposed to match it.
    s = Schema(name="RootSchema");
    s +>:SchemaChild:+> s;
    e = Encoding(name="RootEncoding");
    e +>:EncodingChild:+> e;

    out = _run_rewriter_on([s, e]);

    assert "rewriting schema RootSchema" in out, f"schema not rewritten: {out}";
    assert "rewriter cycle-safe on schema RootSchema" in out,
        f"schema cycle not handled: {out}";
    assert "rewriting encoding RootEncoding" in out, f"encoding not rewritten: {out}";
    assert "rewriter cycle-safe on encoding RootEncoding" in out,
        f"encoding cycle not handled: {out}";
    # Each distinct source node is rewritten exactly once.
    assert out.count("rewriting schema RootSchema") == 1,
        f"schema rewritten more than once: {out}";
    assert out.count("rewriting encoding RootEncoding") == 1,
        f"encoding rewritten more than once: {out}";
}

test "non-cyclic multi-node schema copies each child once" {
    # No cycles: a -> b -> c chain. Each node must be copied exactly once
    # and no cycle-hit messages should appear.
    a = Schema(name="a");
    b = Schema(name="b");
    c = Schema(name="c");
    a +>:SchemaChild:+> b;
    b +>:SchemaChild:+> c;

    out = _run_on([a]);

    assert "copying schema a" in out, f"a not copied: {out}";
    assert "copying schema b" in out, f"b not copied: {out}";
    assert "copying schema c" in out, f"c not copied: {out}";
    assert "cycle hit" not in out, f"unexpected cycle hit in acyclic graph: {out}";
    assert out.count("copying schema a") == 1, f"a copied multiple times: {out}";
    assert out.count("copying schema b") == 1, f"b copied multiple times: {out}";
    assert out.count("copying schema c") == 1, f"c copied multiple times: {out}";
}

