"""Character-check validation graph: cycle-aware input validation with depth/size caps.

Models the essential scenario from INPUT-001: characters are nodes, their
character-builder containers form a tree of typed edges, and a validation
walker walks the structure once with explicit visited-set + depth/size
limits (no recursion plumbing, no N+1 loops). It also handles the
"first-digit path mistaken for character ID" trap by treating a bare digit
string as an explicit ID type rather than a path, and rejects anything else.
"""

# ---------- Entity archetypes ----------

node Character {
    has title: str = "";
    has level: int = 1;
    has valid: bool = True;
}

node Container {
    has name: str = "";
    has depth: int = 0;
}

# Container may legally point back to a character (cycle attempts).
# Cycle detection is a domain invariant — the walker must enforce it,
# because in jac 0.36.1 walkers have no built-in once-per-node visit.

edge Holds {
    has weight: int = 1;
}

# ---------- Walker: cycle-aware validator ----------

walker Validate {
    has max_depth: int = 8;
    has max_nodes: int = 64;
    has visited: list[str] = [];
    has cycles: int = 0;
    has checked: int = 0;
    has errors: list[str] = [];

    can start with Root entry {
        # Parse the input kind explicitly. A bare digit string is a Character ID;
        # anything else is either a Container path or invalid — never both.
        raw_input = "char-7";
        kind = self.classify(raw_input);
        if kind == "invalid" {
            self.errors.append("input could not be parsed as id or path");
            report self;
            disengage;
        }
        print(f"input kind: {kind}");
        visit [-->];
    }

    can descend with Container entry {
        # Depth cap: explicit domain invariant, not scaffolding.
        if here.depth > self.max_depth {
            self.errors.append(f"depth cap exceeded at {here.name}");
            disengage;
        }
        # Node cap: bounded walk.
        if self.checked >= self.max_nodes {
            self.errors.append("node cap exceeded");
            disengage;
        }
        # Cycle guard: domain invariant preserved explicitly because
        # the language does not dedupe walker visits on cyclic graphs.
        if here.name in self.visited {
            self.cycles += 1;
            print(f"[CYCLE] revisited {here.name}");
            disengage;
        }
        self.visited.append(here.name);
        self.checked += 1;
        print(f"[CONTAINER] {here.name} (depth {here.depth})");
        visit [->:Holds:->];
    }

    can inspect with Character entry {
        if not here.valid {
            self.errors.append(f"invalid character: {here.title}");
        }
        print(f"[CHARACTER] {here.title} lvl {here.level}");
    }

    """Classify input as explicit ID, container path, or invalid.

    A bare numeric string is treated as a Character ID (never a path);
    a slash-bearing string is a container path. Anything else is invalid
    so a missing/invalid path is never reinterpreted as a character ID.
    """
    def classify(raw: str) -> str {
        if raw == "" {
            return "invalid";
        }
        is_digits = True;
        for ch in raw {
            if ch not in "0123456789" {
                is_digits = False;
                break;
            }
        }
        if is_digits {
            return "id";
        }
        has_slash = False;
        for ch in raw {
            if ch == "/" {
                has_slash = True;
                break;
            }
        }
        if has_slash {
            return "path";
        }
        return "invalid";
    }
