"""CharacterCheck: bounded intake + cycle-safe container traversal.

Models the essential scenario from issue #13 INPUT-001:
  * Explicit input envelopes (id / URL / local path / snapshot).
  * Schema/version fingerprint on the parsed payload.
  * Bounded traversal of nested character containers with cycle
    detection (visited set + depth cap + child cap).
  * Typed exceptions surfaced by a validator walker so the CLI layer
    can translate kind/action without losing information.
"""

# ----------------------------------------------------------------------
# Edge archetypes
# ----------------------------------------------------------------------

edge Contains {
    has kind: str = "container";
}

# ----------------------------------------------------------------------
# Node archetypes
# ----------------------------------------------------------------------

node Envelope {
    has schema_id: str = "";
    has schema_version: int = 0;
    has fingerprint: str = "";
}

node Character {
    has name: str = "";
    has level: int = 1;
}

node Container {
    has label: str = "";
    has depth: int = 0;
    has child_count: int = 0;
}

# ----------------------------------------------------------------------
# Walker: bounded, cycle-safe traversal with typed-error reporting
# ----------------------------------------------------------------------

walker Validator {
    has max_depth: int = 8;
    has max_children: int = 64;
    has max_nodes: int = 256;
    has visited: list[str] = [];
    has nodes_seen: int = 0;
    has fingerprint: str = "";
    has error_kind: str = "";
    has error_action: str = "";
    has cycles_blocked: int = 0;
    has depth_capped: int = 0;
    has child_capped: int = 0;

    can start with Root entry {
        # Schema fingerprint must be present and match a known shape.
        env = [-->](?:Envelope);
        if not env {
            self.error_kind = "schema_error";
            self.error_action = "verify_envelope";
            report self;
            disengage;
        }
        first = env[0];
        if first.schema_id == "" or first.schema_version <= 0 {
            self.error_kind = "schema_error";
            self.error_action = "verify_envelope";
            report self;
            disengage;
        }
        self.fingerprint = f"{first.schema_id}@{first.schema_version}";
        visit [-->];
    }

    can inspect_envelope with Envelope entry {
        visit [-->];
    }

    can inspect_character with Character entry {
        if here.name == "" {
            self.error_kind = "shape_error";
            self.error_action = "fix_character_name";
            report self;
            disengage;
        }
        self.nodes_seen += 1;
        if self.nodes_seen > self.max_nodes {
            self.error_kind = "limit_error";
            self.error_action = "reduce_graph";
            report self;
            disengage;
        }
        visit [-->];
    }

    can inspect_container with Container entry {
        # Cycle guard: a label we have already entered is a back-edge.
        already = False;
        for tag in self.visited {
            if tag == here.label {
                already = True;
                break;
            }
        }
        if already {
            self.cycles_blocked += 1;
            self.error_kind = "cycle_error";
            self.error_action = "break_cycle";
            report self;
            disengage;
        }
        self.visited.append(here.label);
        self.nodes_seen += 1;

        if here.depth > self.max_depth {
            self.depth_capped += 1;
            self.error_kind = "limit_error";
            self.error_action = "reduce_depth";
            report self;
            disengage;
        }
        if here.child_count > self.max_children {
            self.child_capped += 1;
            self.error_kind = "limit_error";
            self.error_action = "reduce_children";
            report self;
            disengage;
        }

        kids = [here ->:Contains:->];
        for (i, kid) in enumerate(kids) {
            if i >= self.max_children {
                self.child_capped += 1;
                self.error_kind = "limit_error";
                self.error_action = "reduce_children";
                report self;
                disengage;
            }
            visit kid;
        }
    }
}

# ----------------------------------------------------------------------
# Demo wiring
# ----------------------------------------------------------------------

with entry {
    env = Envelope(schema_id="charactercheck.v1", schema_version=1,
                   fingerprint="cc-v1-sha256:abcd");
    root ++> env;

    # A normal, acyclic container tree.
    party = Container(label="party", depth=1, child_count=2);
    spellbook = Container(label="spellbook", depth=2, child_count=2);
    inventory = Container(label="inventory", depth=2, child_count=1);
    party +>:Contains:+> spellbook;
    party +>:Contains:+> inventory;

    fighter = Character(name="Aldric", level=5);
    wizard = Character(name="Vexa", level=7);
    rogue = Character(name="Sable", level=4);
    spellbook +>:Contains:+> fighter;
    spellbook +>:Contains:+> wizard;
    inventory +>:Contains:+> rogue;

    root +>:Contains:+> party;

    # An invalid container: missing label triggers a shape_error.
    bad = Container(label="", depth=1, child_count=0);
    root +>:Contains:+> bad;

    # A cyclic reference: spellbook already points to party — add a
    # back-edge so the visited-set guard can block the loop.
    party +>:Contains:+> party;

    print("=== first run: bound depth and children ===");
    v1 = Validator(max_depth=8, max_children=64, max_nodes=256);
    root spawn v1;
    print(f"fingerprint={v1.fingerprint} "
          f"nodes_seen={v1.nodes_seen} "
          f"kind={v1.error_kind} action={v1.error_action} "
          f"cycles={v1.cycles_blocked} depth_capped={v1.depth_capped} "
          f"child_capped={v1.child_capped}");

    print("=== second run: tighter child cap trips first ===");
    v2 = Validator(max_depth=8, max_children=1, max_nodes=256);
    root spawn v2;
