import io;
import from contextlib { redirect_stdout }

test "validated expansion walks a clean subgraph" {
    intake = Task(title="intake", done=True);
    execute = Task(title="execute");
    sub = PlanGraph(label="clean", task_count=2, validated=True);

    sub +>:Contains:+> intake;
    sub +>:Contains:+> execute;
    intake +>:DependsOn:+> execute;
    root ++> sub;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ValidatedExpansion(reason="recursive expansion");
    }
    out = buf.getvalue();

    assert res.visited_count > 0, f"got {res.visited_count}: {out}";
    assert "[validated] expanding" in out, f"missing expansion output: {out}";
    assert "intake" in out, f"missing intake traversal: {out}";
}

test "validated expansion detects a cyclic subgraph" {
    first = Task(title="first");
    second = Task(title="second");
    sub = PlanGraph(label="cyclic", task_count=2, validated=True);

    sub +>:Contains:+> first;
    sub +>:Contains:+> second;
    first +>:DependsOn:+> second;
    second +>:DependsOn:+> first;
    root ++> sub;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ValidatedExpansion(reason="recursive expansion");
    }
    out = buf.getvalue();

    assert res.visited_count > 0, f"got {res.visited_count}: {out}";
    assert res.visited_count <= 2, f"cycle was not bounded: {res.visited_count}";
    assert "CyclicDependencyError" in out, f"missing cycle report: {out}";
}

test "validated expansion rejects an unvalidated subgraph" {
    only_task = Task(title="unvalidated-task");
    sub = PlanGraph(label="unchecked", task_count=1, validated=False);
    sub +>:Contains:+> only_task;
    root ++> sub;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ValidatedExpansion(reason="recursive expansion");
    }
    out = buf.getvalue();

    assert res.visited_count == 0, f"walked unchecked graph: {res.visited_count}";
    assert "rejecting sub-graph" in out, f"missing rejection output: {out}";
}

test "raw expansion reaches its safety cap on a cycle" {
    looping = Task(title="looping");
    sub = PlanGraph(label="raw-cycle", task_count=1, validated=True);

    sub +>:Contains:+> looping;
    looping +>:DependsOn:+> looping;
