fixed.code:
"""Subagent scope enforcement: modeling the PowerShell $home collision incident.

The bug: a read-only subagent recursively deletes %USERPROFILE% because a
cleanup command collides PowerShell's read-only automatic $HOME variable
with a local $home assignment, leaving $home resolved to the real user
profile. The destructive recursion is not interrupted by the language-level
non-terminating error.

This program models the essential scenario natively in Jac:

  - A delegation hierarchy (Project -> Subagent -> Command -> Path) connected
    by typed edges (DelegatesTo, Issues, Targets).
  - A SubagentRole node carrying the scope/permission fields the issue
    describes (read_only, approval_policy, action_preference).
  - A Path node with a sensitive flag and a canonical-resolved payload,
    representing the directory tree that gets walked and pruned.
  - A ScopeAuditor walker that descends the delegation chain, classifies
    commands as in-scope or out-of-scope, and a CascadePurge walker that
    performs the recursive prune -- but is blocked at the read-only root
    because the read-only flag is honored before any child is visited.

The whole point: cascade-deletion machinery must respect the scope that
spawned it, not just rely on a downstream command's variable hygiene.
"""

node SubagentRole {
    has role_name: str = "";
    has read_only: bool = True;
    has approval_policy: str = "Never";
    has action_preference: str = "Continue";  # PowerShell $ErrorActionPreference
}

node Command {
    has label: str = "";
    has uses_unsafe_variable: bool = False;   # the $home collision
    has has_terminating_errors: bool = False; # $ErrorActionPreference = 'Stop'
    has is_destructive: bool = False;          # Remove-Item -Recurse -Force
}

node Path {
    has pname: str = "";
    has is_sensitive_root: bool = False;      # the %USERPROFILE% boundary
    has canonical_resolved: bool = False;     # canonical-path guard
}

edge DelegatesTo {
    has granted_at: str = "";
}

edge Issues {
    has seq: int = 0;
}

edge Targets {
    has depth: int = 0;
}

walker ScopeAuditor {
    has violations: list[str] = [];
    has visited: list[str] = [];   # explicit cycle / re-entry guard

    can start with Root entry {
        visit [->:DelegatesTo:->];
    }

    can descend with SubagentRole entry {
        self.visited.append(here.role_name);
        print(f"[audit] role={here.role_name} read_only={here.read_only} "
              f"approval={here.approval_policy} err_pref={here.action_preference}");
        visit [->:Issues:->];
    }

    can inspect_cmd with Command entry {
        # The original PowerShell $home collision signature: local $home
        # collides with read-only automatic $HOME, leaving $home resolved
        # to the real user profile while still permitting execution.
        if here.uses_unsafe_variable and not here.has_terminating_errors {
            note = f"variable-collision risk on cmd '{here.label}'";
            self.violations.append(note);
            print(f"  [violation] {note}");
        } else {
            print(f"  [ok] cmd '{here.label}'");
        }
        visit [->:Targets:->];
    }

    can mark_path with Path entry {
        if here.is_sensitive_root and not here.canonical_resolved {
            note = f"sensitive root '{here.pname}' hit without canonical guard";
            self.violations.append(note);
            print(f"  [violation] {note}");
        } else {
            print(f"  [ok] path '{here.pname}'");
        }
        visit [->:Targets:->];
    }
}

walker CascadePurge {
    has pruned: list[str] = [];
    has blocked: bool = False;

    can start with Root entry {
        visit [->:DelegatesTo:->];
    }

    can enter_role with SubagentRole entry {
        # The domain invariant the issue is really about: a read-only
        # subagent must not cascade-delete anything, regardless of what
        # downstream commands try to do. This is the cycle/scope guard.
        if here.read_only {
            self.blocked = True;
            print(f"[purge] BLOCKED at role={here.role_name} (read_only)");
            disengage;
        }
        print(f"[purge] entering role={here.role_name}");
        visit [->:Issues:->];
    }

    can enter_cmd with Command entry {
        if here.is_destructive {
            self.pruned.append(here.label);
            print(f"[purge] pruning via cmd='{here.label}'");
        }
        visit [->:Targets:->];
    }

    can enter_path with Path entry {
        # Even if a destructive command slipped through, the sensitive
        # root boundary is a hard stop -- mirroring the canonical-path
        # guard the issue says was missing.
        if here.is_sensitive_root and not here.canonical_resolved {
            print(f"[purge] BLOCKED at sensitive path '{here.pname}'");
            disengage;
        }
        self.pruned.append(here.pname);
        print(f"[purge] removed {here.pname}");
        visit [->:Targets:->];
    }
}

with entry {
    # --- Graph wiring ---
    read_only_role = SubagentRole(
        role_name="audit-subagent",
        read_only=True,
        approval_policy="Never",
        action_preference="Continue"
    );

    # The offending compound command: local $home collides with read-only
    # $HOME, no terminating error preference, recursive destructive prune.
    bad_cmd = Command(
        label="cleanup-temp",
        uses_unsafe_variable=True,
        has_terminating_errors=False,
        is_destructive=True
    );

    # Sensitive paths under %USERPROFILE% the recursion would walk into.
    user_profile = Path(pname="%USERPROFILE%", is_sensitive_root=True, canonical_resolved=False);
    codex_dir    = Path(pname=".codex",        is_sensitive_root=False);
    appdata      = Path(pname="AppData",       is_sensitive_root=False);
    documents    = Path(pname="Documents",     is_sensitive_root=False);

    # Delegation: Root -> read_only subagent -> compound command -> paths.
    root +>:DelegatesTo(granted_at="2026-07-13"):+> read_only_role;
    read_only_role +>:Issues(seq=1):+> bad_cmd;
    bad_cmd +>:Targets(depth=0):+> user_profile;
    user_profile +>:Targets(depth=1):+> codex_dir;
    codex_dir    +>:Targets(depth=2):+> appdata;
    appdata      +>:Targets(depth=3):+> documents;

    # --- Demo 1: scope audit ---
    auditor = ScopeAuditor();
    root spawn auditor;
    print(f"[audit] total violations recorded: {len(auditor.violations)}");
    for v in auditor.violations {
        print(f"  - {v}");
    }

    # --- Demo 2: cascade purge that must be blocked by scope ---
    purger = CascadePurge();
    root spawn purger;
    print(f"[purge] blocked={purger.blocked} pruned={purger.pruned}");
}

fixed.jac_tests:
"""Regression tests for the subagent-scope-enforcement Jac demo.

The incident: a read-only subagent should not be allowed to cascade-delete
paths rooted at %USERPROFILE%. These tests verify (a) the scope auditor
flags the exact PowerShell $home collision signature and (b) the cascade
purge walker honors the read_only invariant and the sensitive-root guard.
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Test 1: scope auditor detects the $home collision signature
# ---------------------------------------------------------------------------
test "scope auditor flags variable-collision risk on read-only subagent" {
    role = SubagentRole(
        role_name="audit-subagent",
        read_only=True,
        approval_policy="Never",
        action_preference="Continue"
    );
    bad_cmd = Command(
        label="cleanup-temp",
        uses_unsafe_variable=True,
        has_terminating_errors=False,
        is_destructive=True
    );
    user_profile = Path(pname="%USERPROFILE%", is_sensitive_root=True, canonical_resolved=False);
    codex_dir    = Path(pname=".codex", is_sensitive_root=False);
    appdata      = Path(pname="AppData", is_sensitive_root=False);
    documents    = Path(pname="Documents", is_sensitive_root=False);

    root +>:DelegatesTo(granted_at="2026-07-13"):+> role;
    role +>:Issues(seq=1):+> bad_cmd;
    bad_cmd +>:Targets(depth=0):+> user_profile;
    user_profile +>:Targets(depth=1):+> codex_dir;
    codex_dir    +>:Targets(depth=2):+> appdata;
    appdata      +>:Targets(depth=3):+> documents;

    auditor = ScopeAuditor();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn auditor;
    }
    # The auditor must record exactly the variable-collision violation
    # for the cleanup-temp command (uses_unsafe_variable=True with no
    # terminating-error preference).
    joined = "\n".join(res.violations);
    assert "variable-collision" in joined, f"expected variable-collision violation, got {res.violations}";
    assert "cleanup-temp" in joined, f"expected cleanup-temp cmd in violation, got {res.violations}";
    assert "[violation]" in buf.getvalue(), f"expected violation print, got {buf.getvalue()}";
}

# ---------------------------------------------------------------------------
# Test 2: same command WITHOUT terminating-errors guard produces NO violation
#         when terminating errors are enabled (fail-closed semantics).
# ---------------------------------------------------------------------------
test "scope auditor passes when terminating errors are enabled" {
    role = SubagentRole(
        role_name="audit-subagent",
        read_only=True,
        approval_policy="Never",
        action_preference="Stop"
    );
    safe_cmd = Command(
        label="cleanup-temp",
        uses_unsafe_variable=True,
        has_terminating_errors=True,   # $ErrorActionPreference = 'Stop'
        is_destructive=False
    );
    safe_path = Path(pname="%USERPROFILE%", is_sensitive_root=True, canonical_resolved=True);

    root +>:DelegatesTo(granted_at="2026-07-13"):+> role;
    role +>:Issues(seq=1):+> safe_cmd;
    safe_cmd +>:Targets(depth=0):+> safe_path;

    auditor = ScopeAuditor();
    res = root spawn auditor;
    assert len(res.violations) == 0, f"expected zero violations, got {res.violations}";
}

# ---------------------------------------------------------------------------
# Test 3: cascade purge is BLOCKED at the read_only subagent (the headline
#         invariant: scope > downstream variable hygiene).
# ---------------------------------------------------------------------------
test "cascade purge is blocked at read-only subagent" {
    role = SubagentRole(
        role_name="audit-subagent",
        read_only=True,
        approval_policy="Never",
        action_preference="Continue"
    );
    bad_cmd = Command(label="cleanup-temp", uses_unsafe_variable=True, has_terminating_errors=False, is_destructive=True);
    user_profile = Path(pname="%USERPROFILE%", is_sensitive_root=True, canonical_resolved=False);
    codex_dir    = Path(pname=".codex", is_sensitive_root=False);

    root +>:DelegatesTo(granted_at="2026-07-13"):+> role;
    role +>:Issues(seq=1):+> bad_cmd;
    bad_cmd +>:Targets(depth=0):+> user_profile;
    user_profile +>:Targets(depth=1):+> codex_dir;

    purger = CascadePurge();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn purger;
    }
    out = buf.getvalue();
    assert res.blocked is True, f"expected purger.blocked=True, got {res.blocked}";
    assert "BLOCKED" in out, f"expected BLOCKED marker in output, got {out}";
    # Nothing must have been pruned: a read-only subagent cannot delete anything.
    assert len(res.pruned) == 0, f"expected zero pruned nodes, got {res.pruned}";
}

# ---------------------------------------------------------------------------
# Test 4: cascade purge with a NON-read-only role is blocked only at the
#         sensitive-root boundary (canonical-path guard is the second line
#         of defense the issue says was missing).
# ---------------------------------------------------------------------------
test "cascade purge stops at sensitive root without canonical resolution" {
    role = SubagentRole(
        role_name="mutable-worker",
        read_only=False,
        approval_policy="OnRequest",
        action_preference="Continue"
    );
    bad_cmd = Command(label="cleanup-temp", uses_unsafe_variable=True, has_terminating_errors=False, is_destructive=True);
    user_profile = Path(pname="%USERPROFILE%", is_sensitive_root=True, canonical_resolved=False);

    root +>:DelegatesTo(granted_at="2026-07-13"):+> role;
    role +>:Issues(seq=1):+> bad_cmd;
    bad_cmd +>:Targets(depth=0):+> user_profile;

    purger = CascadePurge();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn purger;
    }
    out = buf.getvalue();
    assert res.blocked is False, f"expected not blocked at role, got {res.blocked}";
    assert "BLOCKED at sensitive path" in out, f"expected sensitive-root block, got {out}";
    # The command itself is destructive so it gets pruned, but the
    # sensitive path itself must NOT appear in the pruned list.
    assert "cleanup-temp" in res.pruned, f"expected cleanup-temp pruned, got {res.pruned}";
    assert "%USERPROFILE%" not in res.pruned, f"sensitive root must not be pruned, got {res.pruned}";
}

# ---------------------------------------------------------------------------
# Test 5: graph shape -- the delegation chain matches the issue's wiring.
# ---------------------------------------------------------------------------
test "delegation chain connects root to subagent to command to paths" {
    role = SubagentRole(role_name="audit-subagent", read_only=True);
    bad_cmd = Command(label="cleanup-temp", uses_unsafe_variable=True, has_terminating_errors=False, is_destructive=True);
    user_profile = Path(pname="%USERPROFILE%", is_sensitive_root=True);
    codex_dir    = Path(pname=".codex");

    root +>:DelegatesTo(granted_at="2026-07-13"):+> role;
    role +>:Issues(seq=1):+> bad_cmd;
    bad_cmd +>:Targets(depth=0):+> user_profile;
    user_profile +>:Targets(depth=1):+> codex_dir;

    assert len([root -->]) == 1, f"root should have 1 delegate, got {len([root -->])}";
    delegated = [root ->:DelegatesTo:->];
    assert role in delegated, f"role missing from DelegatesTo edges: {delegated}";
    issued = [role ->:Issues:->];
    assert bad_cmd in issued, f"bad_cmd missing from Issues edges: {issued}";
    targeted = [bad_cmd ->:Targets:->];
    assert user_profile in targeted, f"user_profile missing from Targets edges: {targeted}";
    # Path children chain follows the recursion the issue describes.
    children = [user_profile ->:Targets:->];
    assert codex_dir in children, f"codex_dir missing from path chain: {children}";
