"""Scene-graph incremental invalidation.

Models the pygfx/pygfx issue #1298 scenario: a scene is built once but
rendered many times. The naive approach re-walks the whole tree on every
render. The incremental approach maintains derived state on mutation
and reuses it on render. Both are demonstrated.
"""

# --- Entity archetypes ----------------------------------------------------

node Group {
    has name: str = "";
    has group_order: int = 0;
}

node Renderable {
    has name: str = "";
    has visible: bool = True;
}

node Light {
    has name: str = "";
    has light_type: str = "point";
}

# --- Typed edges (relationship carries meaning) ---------------------------

edge Child {
    has order: int = 0;
}

# --- Walker: naive full traversal (the costly path the issue complains about)

walker NaiveFlatten {
    has renderables: list = [];
    has lights: list = [];
    has group_orders: dict = {};
    has depth: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can walk with Group entry {
        if here.group_order != 0 {
            self.group_orders[here.name] = here.group_order;
        }
        self.depth += 1;
        visit [->:Child:->];
        self.depth -= 1;
    }

    can gather_renderable with Renderable entry {
        if here.visible {
            self.renderables.append(here.name);
        }
        visit [->:Child:->];
    }

    can gather_light with Light entry {
        self.lights.append((here.name, here.light_type));
        visit [->:Child:->];
    }
}

# --- Walker: incremental invalidation marker -------------------------------

walker MarkDirty {
    can start with Root entry {
        visit [-->];
    }

    can mark_group with Group entry {
        print(f"  invalidating subtree rooted at Group '{here.name}'");
        visit [->:Child:->];
    }

    can mark_renderable with Renderable entry {
        print(f"  invalidating renderable '{here.name}'");
        visit [->:Child:->];
    }

    can mark_light with Light entry {
        print(f"  invalidating light '{here.name}'");
        visit [->:Child:->];
    }
}

# --- Helpers ---------------------------------------------------------------

def render_frame(label: str, w: NaiveFlatten) -> None {
    print(f"--- frame ({label}) ---");
    print(f"  renderables: {w.renderables}");
    print(f"  lights:      {w.lights}");
    print(f"  group_order: {w.group_orders}");
}

# --- Demo ------------------------------------------------------------------

with entry {
    # Build a deep nested scene graph with a couple of lights.
    g1 = Group(name="root_group", group_order=1);
    g2 = Group(name="rig", group_order=2);
    g3 = Group(name="mesh_bucket", group_order=3);
    g4 = Group(name="deep_leaf", group_order=0);

    r1 = Renderable(name="cube");
    r2 = Renderable(name="line_strip");
    r3 = Renderable(name="points");
    r4 = Renderable(name="hidden_helper", visible=False);
    l1 = Light(name="key_light", light_type="directional");
    l2 = Light(name="fill_light", light_type="ambient");

    root ++> g1;
    g1 +>:Child(order=0):+> g2;
    g2 +>:Child(order=0):+> g3;
    g3 +>:Child(order=0):+> g4;
    g4 +>:Child(order=0):+> r1;
    g3 +>:Child(order=1):+> r2;
    g2 +>:Child(order=1):+> r3;
    g2 +>:Child(order=2):+> r4;
    g1 +>:Child(order=1):+> l1;
    g1 +>:Child(order=2):+> l2;

    # The naive path: walk the entire scene to flatten it.
    print("Approach A: full scene walk per render (the issue's hot path)");
    naive = NaiveFlatten();
    root spawn naive;
    render_frame("naive walk", naive);

    # The incremental path: mutate the scene, then only invalidate the
    # touched subtree instead of re-walking everything.
    print("\nApproach B: incremental invalidation on mutation");
    print("Mutating visibility of 'cube' and group_order of 'rig':");
    r1.visible = False;
    g2.group_order = 5;
    invalidator = MarkDirty();
    root spawn invalidator;
}

