"""Test annex for the scene-graph incremental invalidation demo."""

import io;
import from contextlib { redirect_stdout }

# --- Test 1: Naive walker visits every node in the scene graph ------------

test "naive walker visits every Group, Renderable, and Light" {
    root ++> Group(name="g_a", group_order=1);
    ga = [root -->][0];
    gb = Group(name="g_b", group_order=2);
    gc = Group(name="g_c", group_order=0);
    r1 = Renderable(name="r1");
    r2 = Renderable(name="r2");
    l1 = Light(name="l1", light_type="point");

    ga +>:Child(order=0):+> gb;
    ga +>:Child(order=1):+> r1;
    gb +>:Child(order=0):+> gc;
    gb +>:Child(order=1):+> r2;
    ga +>:Child(order=2):+> l1;

    w = NaiveFlatten();
    root spawn w;

    assert "r1" in w.renderables, f"missing r1: {w.renderables}";
    assert "r2" in w.renderables, f"missing r2: {w.renderables}";
    assert w.renderables == ["r1", "r2"], f"order/contents: {w.renderables}";
    assert ("l1", "point") in w.lights, f"missing light: {w.lights}";
    assert w.lights == [("l1", "point")], f"lights list: {w.lights}";
    assert w.group_orders == {"g_a": 1, "g_b": 2}, f"group_orders: {w.group_orders}";
    assert w.depth == 0, f"depth not reset: {w.depth}";
}

# --- Test 2: Naive walker respects visible=False and excludes group_order=0

test "naive walker skips invisible renderables and zero-order groups" {
    root ++> Group(name="g_top", group_order=4);
    g = [root -->][0];
    visible_r = Renderable(name="show_me");
    hidden_r = Renderable(name="hide_me", visible=False);
    another_hidden = Renderable(name="also_hidden", visible=False);
    g +>:Child(order=0):+> visible_r;
    g +>:Child(order=1):+> hidden_r;
    g +>:Child(order=2):+> another_hidden;

    w = NaiveFlatten();
    root spawn w;

    assert w.renderables == ["show_me"], f"got {w.renderables}";
    assert "hide_me" not in w.renderables, "hide_me leaked through";
    assert "also_hidden" not in w.renderables, "also_hidden leaked through";
    assert w.group_orders == {"g_top": 4}, f"got {w.group_orders}";
    assert len(w.group_orders) == 1, f"expected only g_top, got {w.group_orders}";
}

# --- Test 3: MarkDirty prints an invalidation line per node ---------------

test "MarkDirty prints invalidation for every Group, Renderable, and Light" {
    root ++> Group(name="grp");
    g = [root -->][0];
    r = Renderable(name="rend");
    l = Light(name="lt", light_type="directional");
    g +>:Child(order=0):+> r;
    g +>:Child(order=1):+> l;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        w = MarkDirty();
        root spawn w;
    }
    out = buf.getvalue();

    assert "Group 'grp'" in out, f"missing group invalidation: {out}";
    assert "renderable 'rend'" in out, f"missing renderable invalidation: {out}";
    assert "light 'lt'" in out, f"missing light invalidation: {out}";
    # Three lines total, one per node.
    lines = [ln for ln in out.splitlines() if ln.strip().startswith("invalidating")];
    assert len(lines) == 3, f"expected 3 invalidation lines, got {len(lines)}: {out}";
}

# --- Test 4: Mixed scene shape captures everything correctly --------------

test "naive walker captures mixed scene: 2 renderables + 1 light + 2 group_orders" {
    root ++> Group(name="g1", group_order=1);
    g1 = [root -->][0];
    g2 = Group(name="g2", group_order=7);
    r1 = Renderable(name="alpha");
    r2 = Renderable(name="beta");
    l1 = Light(name="key", light_type="directional");
    g1 +>:Child(order=0):+> g2;
    g2 +>:Child(order=0):+> r1;
    g1 +>:Child(order=1):+> r2;
    g1 +>:Child(order=2):+> l1;

    w = NaiveFlatten();
    root spawn w;

    assert len(w.renderables) == 2, f"renderables count: {w.renderables}";
    assert "alpha" in w.renderables and "beta" in w.renderables, f"got {w.renderables}";
    assert len(w.lights) == 1, f"lights count: {w.lights}";
    assert w.lights[0] == ("key", "directional"), f"light tuple: {w.lights}";
    assert w.group_orders == {"g1": 1, "g2": 7}, f"group_orders: {w.group_orders}";
    # Graph shape sanity: 4 typed children off g1 (g2 + r2 + l1 via Child edges).
    typed = [g1 ->:Child:->];
    assert len(typed) == 3, f"g1 Child edges: {len(typed)}";
}

