"""Application dependency resolver.

Models the HARP scenario from msqd/harp issue #803: an ApplicationsRegistry
holds apps with explicit dependencies, and we walk the dependency graph to
produce a topologically ordered resolution. The walker that performs the
walk uses Kahn's algorithm over typed DependsOn edges, emitting nodes in
resolution order.
"""

# Edge carrying the meaning "this app depends on that app".
edge DependsOn { }

node App {
    has name: str = "";
    has in_degree: int = 0;
    has resolved: bool = False;
}

walker Resolver {
    has queue: list[str] = [];
    has order: list[str] = [];

    can start with Root entry {
        # Seed the queue with every app that has no dependencies.
        for app in [-->](?:App) {
            if app.in_degree == 0 {
                self.queue.append(app.name);
            }
        }
        visit [-->](?:App);
    }

    can resolve with App entry {
        if here.resolved {
            # Kahn's algorithm visits each node exactly once; this guard
            # is defensive against the unspecified traversal order.
            visit [-->](?:App);
            disengage;
        }
        here.resolved = True;
        self.order.append(here.name);
        print(f"resolved {here.name} (in_degree was {here.in_degree})");

        # O(E) decrement mirroring the issue's "find dependents" loop.
        # Edges go dependent -> dependency, so for each sibling we
        # inspect its outgoing DependsOn edges and decrement in_degree
        # if it lists this node as a dependency.
        for sibling in [-->](?:App) {
            depends_on_us = False;
            for e in [sibling->:DependsOn:->] {
                if e.name == here.name {
                    depends_on_us = True;
                    break;
                }
            }
            if depends_on_us {
                sibling.in_degree -= 1;
                if sibling.in_degree == 0 {
                    self.queue.append(sibling.name);
                }
            }
        }

        # Drain anything that became ready.
        while self.queue {
            nxt = self.queue.pop(0);
            print(f"queue ready: {nxt}");
        }

        visit [-->](?:App) else { disengage; }
    }
}

with entry {
    # Build the demo dependency graph:
    #   web  -> db, cache
    #   db   -> cache
    #   cache -> (nothing)
    #   worker -> db
    web = App(name="web", in_degree=2);
    db = App(name="db", in_degree=2);
    cache = App(name="cache", in_degree=0);
    worker = App(name="worker", in_degree=1);

    root ++> web ++> db ++> cache ++> worker;

    web +>:DependsOn:+> db;
    web +>:DependsOn:+> cache;
    db +>:DependsOn:+> cache;
    worker +>:DependsOn:+> db;

    resolver = Resolver();
    root spawn resolver;

    print("final resolution order: " + ", ".join(resolver.order));
}

