"""Content-addressed nominal type identity model.

Two independently declared copies of the same struct share an identity
when their canonical declaration digests match. The walker walks the
type dependency graph, detects recursive groups (SCCs), canonically
encodes each component, and invalidates dependents when a declaration
changes.
"""

node TypeDecl {
    has kind: str = "struct";
    has name: str = "";
    has fields: list[str] = [];
    has methods: list[str] = [];
    has impl_digest: str = "";
    has declared_digest: str = "";
    has resolved_digest: str = "";

    def shape_digest() -> str {
        field_part = ",".join(self.fields);
        method_part = ",".join(self.methods);
        return f"{self.kind}:{self.name}<{field_part}>/[{method_part}]@{self.impl_digest}";
    }
}

edge DependsOn {
    has kind: str = "field";
}

walker DigestBuilder {
    has order: list[str] = [];
    has on_stack: dict[str, bool] = {};

    can start with Root entry {
        visit [-->];
    }

    can descend with TypeDecl entry {
        key = here.name;
        if self.on_stack.get(key, False) {
            here.resolved_digest = "CYCLE";
            return;
        }
        self.on_stack[key] = True;
        here.declared_digest = here.shape_digest();
        dep_list = [->:DependsOn:->];
        dep_hashes = [d.resolved_digest for d in dep_list];
        dep_part = "|".join(dep_hashes);
        here.resolved_digest = f"{here.declared_digest}::[{dep_part}]";
        if here.name not in self.order {
            self.order.append(here.name);
        }
        visit dep_list;
        self.on_stack[key] = False;
    }
}

walker InvalidationWalker {
    has changed: str = "";
    has visited: dict[str, bool] = {};
    has invalidated: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can pick with TypeDecl entry {
        if here.name == self.changed {
            self.invalidated.append(here.name);
            self.visited[here.name] = True;
            visit [->:DependsOn:->];
        }
    }

    can propagate with TypeDecl entry {
        if self.visited.get(here.name, False) {
            return;
        }
        self.invalidated.append(here.name);
        self.visited[here.name] = True;
        print(f"invalidating {here.name} because its dependency changed");
        visit [->:DependsOn:->];
    }
}

with entry {
