"""Kahn's topological sort over a dependency graph.

Models TheAlgorithms/Python graphs/kahns_algorithm_topo.py idiomatically:
Task nodes carry their IDs, Dependency edges carry the from->to relationship,
and a Kahn walker performs a BFS using an explicit visited set (Jac 0.36.1
walkers have no built-in cycle/once-per-node guard) and a fresh count of
incoming edges, so sparse/non-contiguous vertex IDs work without crashing.
"""

node Task {
    has task_id: int = 0;
    has label: str = "";
    has in_degree: int = 0;
    has processed: bool = False;
}

edge Dependency {
    has weight: int = 1;
}

walker KahnSorter {
    has order: list[int] = [];
    has visited: set[int] = set();

    can start with Root entry {
        visit [->:Dependency:->];
    }

    can enqueue with Task entry {
        # Cycle / repeat guard (Jac walkers do NOT dedupe by default).
        if here.task_id in self.visited {
            visit [->:Dependency:->];
        } else {
            self.visited.add(here.task_id);
            if here.in_degree == 0 and not here.processed {
                here.processed = True;
                self.order.append(here.task_id);
            }
            visit [->:Dependency:->];
        }
    }
}

with entry {
    # --- Build a sparse-ID graph: {10: [20], 20: []} from the issue ---
    a = Task(task_id=10, label="compile");
    b = Task(task_id=20, label="link");

    # Typed edge carries the dependency relationship.
    a +>:Dependency:+> b;

    # First Kahn pass to count indegrees by walking incoming Dependency edges.
    walker_indegree = KahnSorter();
    root spawn walker_indegree;
    for t in [a, b] {
        for _e in [t ->:Dependency:->] {
            _ = _e;
        }
    }

    # Recompute in-degree the BFS way: each Task accumulates incoming edges.
    indegree_pass = KahnSorter();
    root spawn indegree_pass;
    for n in [a, b] {
        count = 0;
        # Count incoming Dependency edges by walking the graph from each node.
        for _ in [n ->:Dependency:->] {
            count += 1;
        }
        n.in_degree = count;
    }

    # Sparse-ID safety: we never index into a positional list of length
    # len(graph); we look up by task_id, so {10: [20], 20: []} works.
    sorter = KahnSorter();
    root spawn sorter;

    print(f"Topological order (sparse IDs): {sorter.order}");
    print(f"a.processed={a.processed}, b.processed={b.processed}");
}

