"""Package composition with deterministic dependency closure and verification.

Models the essential scenario from the composition extraction issue:
packages declare typed dependencies on other packages, a walker resolves
the dependency closure in deterministic order, detects cycles, and
verifies that every dependency resolves to a real package identity.
"""

# ----- Entities ---------------------------------------------------------

node Package {
    has name: str = "";
    has version: str = "";
    has available: bool = True;
    has depth: int = 0;
}

node PackageIdentity {
    has name: str = "";
    has version: str = "";
    has content_hash: str = "";
}

# ----- Typed edges -------------------------------------------------------

edge Dependency {
    has scope: str = "compile";
    has optional: bool = False;
}

edge IdentityOf { }

# ----- Composer walker: closes the dependency graph and detects cycles ---

walker Composer {
    has closure_order: list[str] = [];
    has failures: list[str] = [];
    has visited: list[str] = [];
    has max_depth: int = 32;

    can start with Root entry {
        # begin by walking every Package hanging off root
        visit [-->];
    }

    can compose with Package entry {
        # depth-first traversal with explicit cycle guard
        if here.depth > self.max_depth {
            self.failures.append(f"depth-exceeded at {here.name}");
            disengage;
        }
        already_seen = here.name in self.visited;
        if already_seen {
            self.failures.append(f"duplicate/cycle via {here.name}");
            disengage;
        }
        self.visited.append(here.name);
        self.closure_order.append(f"{here.name}@{here.version}");
        here.depth = here.depth + 1;
        visit [->:Dependency:->];
    }

    can finish with Root entry {
        print("CLOSURE_ORDER=" + ",".join(self.closure_order));
        print("FAILURES=" + ",".join(self.failures));
    }
}

# ----- Resolver walker: visits packages and verifies their identities ---

walker Resolver {
    has report_lines: list[str] = [];
    has seen_packages: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can resolve with Package entry {
        if here.name in self.seen_packages {
            disengage;
        }
        self.seen_packages.append(here.name);
        self.report_lines.append(f"resolve {here.name}@{here.version}");
        visit [->:IdentityOf:->];
        visit [->:Dependency:->];
    }

    can verify with PackageIdentity entry {
        self.report_lines.append(
            f"verify id {here.name}@{here.version} sha={here.content_hash}"
        );
    }

    can finish with Root entry {
        print("\n".join(self.report_lines));
    }
}

# ----- Demo --------------------------------------------------------------

with entry {
    # build three packages with explicit dependencies
    pkg_a = Package(name="core", version="1.0.0");
    pkg_b = Package(name="io",   version="1.2.0");
    pkg_c = Package(name="util", version="0.9.0");

    # identities that must resolve from the catalog
    id_core = PackageIdentity(name="core", version="1.0.0", content_hash="sha-core");
    id_io   = PackageIdentity(name="io",   version="1.2.0", content_hash="sha-io");
    id_util = PackageIdentity(name="util", version="0.9.0", content_hash="sha-util");

    # wire packages under root, attach identities, declare dependencies
    root ++> pkg_a;
    root ++> pkg_b;
    root ++> pkg_c;

    pkg_a +>:Dependency(scope="compile"):+> pkg_b;
    pkg_b +>:Dependency(scope="compile"):+> pkg_c;
    pkg_c +>:Dependency(scope="compile"):+> pkg_a;   # forms a cycle on purpose

    pkg_a +>:IdentityOf:+> id_core;
