"""Review lifecycle atomic-compact-v2 demo.

Models the live review lifecycle from issue #2423:
    candidate consent -> freeze -> admitted lenses
    -> at most one bounded correction
    -> targeted validation -> approval and burn.

Orphaned review surfaces (legacy versions, receipts, lineage,
tombstones, recovery shells) are absent; only the atomic compact-v2
lifecycle remains. A walker traverses the lifecycle stages, guards
against cycles (walker semantics in jac 0.36.1 do not auto-dedupe),
enforces the bounded correction, and burns any approval without
leaving a terminal receipt.
"""

node Candidate {
    has title: str = "";
    has consent_granted: bool = False;
}

node Freeze {
    has freeze_id: str = "";
}

node Lens {
    has reviewer: str = "";
    has admitted: bool = False;
}

node Correction {
    has bounded: bool = True;
    has count: int = 0;
}

node Validation {
    has evidence: str = "";
    has targeted: bool = False;
}

node Approval {
    has final: bool = False;
}

# Typed edges for the live lifecycle steps.
edge ConsentsTo { }
edge FreezesInto { }
edge AdmitsLens { }
edge AllowsCorrection { }
edge TargetsValidation { }
edge ApprovesAndBurns { }

walker LifecycleAuditor {
    # Track visited nodes to enforce no-revisit (jac 0.36.1 walkers
    # do NOT auto-dedupe on cycles, so the policy is explicit).
    has seen: list = [];

    can start with Root entry {
        print("Atomic compact-v2 lifecycle audit starting");
        visit [-->];
    }

    can audit_consent with Candidate entry {
        if here.title in self.seen {
            disengage;
        }
        self.seen.append(here.title);
        status = "consent" if here.consent_granted else "no-consent";
        print(f"[{status}] candidate: {here.title}");
        visit [-->];
    }

    can audit_freeze with Freeze entry {
        print(f"[freeze] freeze_id={here.freeze_id}");
        visit [-->];
    }

    can audit_lenses with Lens entry {
        if not here.admitted {
            print(f"[skip] lens from {here.reviewer} not admitted");
            disengage;
        }
        print(f"[lens] admitted reviewer={here.reviewer}");
        visit [-->];
    }

    can audit_correction with Correction entry {
        # Bounded correction policy: at most one correction per
        # candidate; further attempts terminate the walk.
        if not here.bounded or here.count > 1 {
            print("[refuse] correction not bounded");
            disengage;
        }
        print(f"[correction] bounded, count={here.count}");
        visit [-->];
    }

    can audit_validation with Validation entry {
        if not here.targeted {
            print("[refuse] validation not targeted");
            disengage;
        }
        print(f"[validation] evidence={here.evidence}");
        visit [-->];
    }

    can audit_approval with Approval entry {
        if not here.final {
            print("[refuse] approval not final");
            disengage;
        }
        # Approval leaves no terminal receipt, lineage, witness,
        # or tombstone: just burn and disengage.
        print("[burn] approval final; no receipt retained");
        disengage;
    }
}

with entry {
    cand = Candidate(title="RFC-7", consent_granted=True);
    frz = Freeze(freeze_id="F-001");
    lens_a = Lens(reviewer="alice", admitted=True);
    lens_b = Lens(reviewer="bob", admitted=True);
    corr = Correction(bounded=True, count=1);
    vald = Validation(evidence="tests pass", targeted=True);
    appr = Approval(final=True);

    root +>:ConsentsTo:+> cand;
    cand +>:FreezesInto:+> frz;
    frz +>:AdmitsLens:+> lens_a;
    frz +>:AdmitsLens:+> lens_b;
    lens_a +>:AllowsCorrection:+> corr;
    corr +>:TargetsValidation:+> vald;
    vald +>:ApprovesAndBurns:+> appr;

    root spawn LifecycleAuditor();
}

fixed.jac_tests:
"""Test annex for the review lifecycle atomic-compact-v2 demo.

Covers the behavior the issue specifies:
  - consent-gated traversal starts from Root,
  - lenses that are not admitted are skipped (not burned),
  - bounded correction: count > 1 refuses and stops the walk,
  - non-targeted validation refuses and stops the walk,
  - final approval burns without producing any further output,
  - candidate revisit is deduped via the auditor's `seen` list
    (walker semantics in jac 0.36.1 do not auto-dedupe on cycles).
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# 1. Happy path: full lifecycle runs consent -> freeze -> lens -> correction
#    -> validation -> approval/burn, in that order, with one consent line.
# ---------------------------------------------------------------------------
test "happy path runs the full atomic lifecycle" {
    root ++> Candidate(title="RFC-7", consent_granted=True);
    cand = [root -->][?:Candidate];
    cand[0] +>:FreezesInto:+> Freeze(freeze_id="F-001");
    frz = [cand[0] ->:FreezesInto:->][?:Freeze][0];
    frz +>:AdmitsLens:+> Lens(reviewer="alice", admitted=True);
    frz +>:AdmitsLens:+> Lens(reviewer="bob", admitted=True);
    lens_a = [frz ->:AdmitsLens:->][?:Lens][0];
    lens_a +>:AllowsCorrection:+> Correction(bounded=True, count=1);
    corr = [lens_a ->:AllowsCorrection:->][?:Correction][0];
    corr +>:TargetsValidation:+> Validation(evidence="tests pass", targeted=True);
    vald = [corr ->:TargetsValidation:->][?:Validation][0];
    vald +>:ApprovesAndBurns:+> Approval(final=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LifecycleAuditor();
    }
    out = buf.getvalue();

    assert "Atomic compact-v2 lifecycle audit starting" in out, f"missing startup line: {out}";
    assert "[consent] candidate: RFC-7" in out, f"missing consent line: {out}";
    assert "[freeze] freeze_id=F-001" in out, f"missing freeze line: {out}";
    assert "[lens] admitted reviewer=alice" in out, f"missing alice lens line: {out}";
    assert "[lens] admitted reviewer=bob" in out, f"missing bob lens line: {out}";
    assert "[correction] bounded, count=1" in out, f"missing correction line: {out}";
    assert "[validation] evidence=tests pass" in out, f"missing validation line: {out}";
    assert "[burn] approval final; no receipt retained" in out, f"missing burn line: {out}";
    # Exactly one consent line even with two lenses after it.
    assert out.count("[consent]") == 1, f"expected exactly one consent line, got: {out}";
    # Burn is terminal: nothing follows it.
    burn_idx = out.index("[burn]");
    assert burn_idx == len(out) - len("[burn] approval final; no receipt retained\n"), f"burn not terminal: {out}";
}

# ---------------------------------------------------------------------------
# 2. No-consent candidate is reported and the walk advances (does not
#    refuse the whole audit; consent is informational on the candidate).
# ---------------------------------------------------------------------------
test "candidate without consent is reported but traversal continues" {
    cand = Candidate(title="RFC-no", consent_granted=False);
    root +>:ConsentsTo:+> cand;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LifecycleAuditor();
    }
    out = buf.getvalue();

    assert "[no-consent] candidate: RFC-no" in out, f"missing no-consent line: {out}";
    assert "[consent]" not in out, f"consent line should not appear: {out}";
}

# ---------------------------------------------------------------------------
# 3. Non-admitted lens is skipped (NOT burned) and the walk halts there
#    because the auditor disengages on the unadmitted lens.
# ---------------------------------------------------------------------------
test "non-admitted lens is skipped and walk halts there" {
    cand = Candidate(title="RFC-L", consent_granted=True);
    root +>:ConsentsTo:+> cand;
    cand +>:FreezesInto:+> Freeze(freeze_id="F-L");
    frz = [cand ->:FreezesInto:->][?:Freeze][0];
    frz +>:AdmitsLens:+> Lens(reviewer="carol", admitted=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LifecycleAuditor();
    }
    out = buf.getvalue();

    assert "[skip] lens from carol not admitted" in out, f"missing skip line: {out}";
    assert "[lens]" not in out, f"no admitted-lens line expected: {out}";
    assert "[burn]" not in out, f"burn must not fire when lens is skipped: {out}";
}

# ---------------------------------------------------------------------------
# 4. Bounded correction policy: count > 1 is refused and the walk halts
#    before validation/burn.
# ---------------------------------------------------------------------------
test "unbounded correction (count > 1) refuses and stops walk" {
    cand = Candidate(title="RFC-C", consent_granted=True);
    root +>:ConsentsTo:+> cand;
    cand +>:FreezesInto:+> Freeze(freeze_id="F-C");
    frz = [cand ->:FreezesInto:->][?:Freeze][0];
    lens = Lens(reviewer="alice", admitted=True);
    frz +>:AdmitsLens:+> lens;
    lens +>:AllowsCorrection:+> Correction(bounded=True, count=2);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LifecycleAuditor();
    }
    out = buf.getvalue();

    assert "[refuse] correction not bounded" in out, f"missing refusal line: {out}";
    assert "[validation]" not in out, f"validation must not run after refused correction: {out}";
    assert "[burn]" not in out, f"burn must not run after refused correction: {out}";
}

# ---------------------------------------------------------------------------
# 5. Non-targeted validation refuses and stops the walk before burn.
# ---------------------------------------------------------------------------
test "non-targeted validation refuses and stops walk" {
    cand = Candidate(title="RFC-V", consent_granted=True);
    root +>:ConsentsTo:+> cand;
    cand +>:FreezesInto:+> Freeze(freeze_id="F-V");
    frz = [cand ->:FreezesInto:->][?:Freeze][0];
    lens = Lens(reviewer="alice", admitted=True);
    frz +>:AdmitsLens:+> lens;
    lens +>:AllowsCorrection:+> Correction(bounded=True, count=1);
    corr = [lens ->:AllowsCorrection:->][?:Correction][0];
    corr +>:TargetsValidation:+> Validation(evidence="weak", targeted=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LifecycleAuditor();
    }
    out = buf.getvalue();

    assert "[refuse] validation not targeted" in out, f"missing refusal line: {out}";
    assert "[burn]" not in out, f"burn must not run after refused validation: {out}";
}

# ---------------------------------------------------------------------------
# 6. Cycle handling: a Candidate reachable twice with the same title is
#    deduped by the auditor's `seen` list. Walker semantics in jac 0.36.1
#    do NOT auto-dedupe, so the policy is explicit in the program. We
#    confirm by counting consent lines on a graph that revisits the same
#    title via a Freeze -> Candidate (different node, same title) edge.
# ---------------------------------------------------------------------------
test "candidate revisit is deduped via seen list" {
    cand1 = Candidate(title="SHARED", consent_granted=True);
    root +>:ConsentsTo:+> cand1;
    cand1 +>:FreezesInto:+> Freeze(freeze_id="F-shared");
    frz = [cand1 ->:FreezesInto:->][?:Freeze][0];
    # Second candidate with the same title reached from the freeze.
    # Without dedupe, audit_consent would fire twice for SHARED.
    cand2 = Candidate(title="SHARED", consent_granted=True);
    frz +>:FreezesInto:+> cand2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LifecycleAuditor();
    }
    out = buf.getvalue();

    # seen list dedupes by title, so SHARED appears once.
    assert out.count("[consent] candidate: SHARED") == 1, f"expected one consent for shared title, got: {out}";
    # Freeze for the shared cycle is still reported.
    assert "[freeze] freeze_id=F-shared" in out, f"missing freeze line: {out}";
}

