        b +>:ReplacedBy(replacement="alpha-cycle"):+> a;
        res = root spawn Auditor(depth_limit=20);
    }
    out = buf.getvalue();
    assert "[CYCLE] revisit of" in out, f"missing CYCLE marker: {out}";
    assert res.has_cycle == True, f"has_cycle flag must be True, got {res.has_cycle}";
    # The cycle guard should disengage before revisiting — count OK/CYCLE occurrences bounded.
    assert out.count("[OK]") + out.count("[CYCLE]") <= 3, f"too many visits in cyclic graph: {out}";
}

