"""Access-only post-consolidate recompute demo.

Models the essential scenario from issue #205: WSGs (Watershed Segments)
hold accessibility state that depends on a barrier set that may be
incomplete on a single host. We represent WSGs and barriers as nodes,
link a WSG to its downstream WSG via a FlowsInto typed edge, and link
WSGs to the barriers that gate them via a GatedBy typed edge. A
Consolidator walker merges barrier sets across WSGs (provincial
accumulation) and then recomputes each WSG's mapping_code using only
access inputs — never re-deriving streams/habitat. A Recompute walker
then walks the consolidated graph and visits every WSG once (cycle-safe
via an explicit guard set, since jac 0.36.1 walkers have no built-in
dedupe). Each ability ends with `visit ... else { disengage; }` for
dead-end handling.
"""

# --- Entity archetypes ----------------------------------------------------

node Barrier {
    has barrier_id: str = "";
    has blocked: bool = True;
}

node WSG {
    # mapping_code tokens: token1 = "ACCESS" / "NOACCESS",
    # token2 = provincial rollup percentage label.
    has segment_id: str = "";
    has token1: str = "NOACCESS";
    has token2: str = "0%";
    has local_barriers: list[str] = [];
    has visited: bool = False;
}

# --- Typed edges (relationship carries meaning) ---------------------------

edge FlowsInto {
    # WSG -> WSG: downstream flow relationship.
    has weight: float = 1.0;
}

edge GatedBy {
    # WSG -> Barrier: this barrier gates the WSG's accessibility.
}

edge CarriesBarriers {
    # WSG -> Barrier: barriers observed on this segment (provincial feed).
}

# --- Walkers --------------------------------------------------------------

# Consolidator: merge barrier sets across WSGs (provincial accumulation).
# In the issue this is the "consolidate" step that produces the *complete*
# barrier set a downstream WSG may need.
walker Consolidator {
    can start with Root entry {
        visit [-->];
    }

    can gather with WSG entry {
        # Every barrier this WSG carries is promoted to "gating" — i.e.
        # once barriers are consolidated into the provincial feed, every
        # WSG becomes aware of them. This is the post-consolidate state.
        for b in [-->](?:Barrier) {
            here +>:GatedBy:+> b;
        }
        visit [-->];
    }

    can collect with Barrier entry {
        visit [-->];
    }
}

# Recompute: walk every WSG once (cycle-safe via visited flag) and
# recompute mapping_code token1 from the *current* consolidated barrier
# set. token2 is a cheap rollup label — no re-derivation of streams.
walker Recompute {
    has total_wsg: int = 0;
    has recomputed: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can scan with WSG entry {
        if here.visited {
            # Cycle / repeated-visit guard: jac 0.36.1 has no built-in
            # dedupe, so this is the explicit cycle policy required by
            # the issue's "access depends on downstream" semantics.
            disengage;
        }
        here.visited = True;
        self.total_wsg += 1;

        # Access-only recompute: read gating barriers from the
        # consolidated graph, do NOT touch streams/habitat.
        gate_count = 0;
        for g in [here->:GatedBy:->] {
            if g.blocked {
                gate_count += 1;
            }
        }

        new_token1 = "NOACCESS" if gate_count > 0 else "ACCESS";
        new_token2 = f"{100 - gate_count * 10}%";
        here.token1 = new_token1;
        here.token2 = new_token2;
        self.recomputed += 1;
        print(f"recompute {here.segment_id}: token1={here.token1} "
              f"token2={here.token2} (gates={gate_count})");

        visit [-->];
    }

    can skip with Barrier entry {
        visit [-->];
    }
}

# --- Demo wiring ----------------------------------------------------------

with entry {
    # Build a small WSG chain: head -> mid -> tail. tail is gated by a
    # barrier that originates "upstream" on a different bucket in the
    # un-consolidated view — the post-consolidate recompute reveals it.
    head = WSG(segment_id="HEAD", local_barriers=["B1"]);
    mid = WSG(segment_id="MID", local_barriers=[]);
    tail = WSG(segment_id="TAIL", local_barriers=[]);

    b1 = Barrier(barrier_id="B1", blocked=True);
    b2 = Barrier(barrier_id="B2", blocked=True);

    root ++> head ++> mid ++> tail;

    # Each WSG carries its own observed barriers (the per-bucket feed).
    head +>:CarriesBarriers:+> b1;
    mid +>:CarriesBarriers:+> b2;

    # Step 1: consolidate barrier sets so every WSG knows about every
    # barrier — this is the "post-consolidate" state the issue wants.
    root spawn Consolidator();

    # Step 2: cheap access-only recompute over the consolidated graph.
    rec = Recompute();
    root spawn rec;
    print(f"recompute complete: visited={rec.total_wsg} "
          f"recomputed={rec.recomputed}");
}

