import io;
import from contextlib { redirect_stdout }

test "consolidate promotes carried barriers to gated edges" {
    w = WSG(segment_id="S1");
    b = Barrier(barrier_id="B1", blocked=True);
    root ++> w;
    w +>:CarriesBarriers:+> b;
    root spawn Consolidator();
    gates = [w->:GatedBy:->];
    assert b in gates, f"expected GatedBy to B1, got {gates}";
    assert len(gates) == 1, f"expected exactly one gate, got {len(gates)}";
}

test "recompute ignores carried barriers before consolidate" {
    w = WSG(segment_id="W0");
    b = Barrier(barrier_id="B0", blocked=True);
    root ++> w;
    w +>:CarriesBarriers:+> b;
    rec = Recompute();
    root spawn rec;
    assert w.token1 == "ACCESS", f"carried-only barrier must not gate: {w.token1}";
    assert w.token2 == "100%", f"expected 100% rollup, got {w.token2}";
    assert rec.recomputed == 1, f"expected one recompute, got {rec.recomputed}";
}

test "post-consolidate recompute applies blocked gates per segment" {
    head = WSG(segment_id="HEAD");
    mid = WSG(segment_id="MID");
    tail = WSG(segment_id="TAIL");
    b1 = Barrier(barrier_id="B1", blocked=True);
    b2 = Barrier(barrier_id="B2", blocked=True);
    root ++> head ++> mid ++> tail;
    head +>:CarriesBarriers:+> b1;
    mid +>:CarriesBarriers:+> b2;
    root spawn Consolidator();
    rec = Recompute();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn rec;
    }
    out = buf.getvalue();
    assert head.token1 == "NOACCESS", f"HEAD should be gated: {head.token1}";
    assert head.token2 == "90%", f"HEAD token2 wrong: {head.token2}";
    assert mid.token1 == "NOACCESS", f"MID should be gated: {mid.token1}";
    assert mid.token2 == "90%", f"MID token2 wrong: {mid.token2}";
    assert tail.token1 == "ACCESS", f"TAIL has no gates downstream: {tail.token1}";
    assert tail.token2 == "100%", f"TAIL token2 wrong: {tail.token2}";
    assert rec.total_wsg == 3, f"expected 3 WSG visits, got {rec.total_wsg}";
    assert rec.recomputed == 3, f"expected 3 recomputes, got {rec.recomputed}";
    assert "recompute TAIL" in out, f"missing TAIL recompute line: {out}";
}

test "unblocked gate does not deny access" {
    w = WSG(segment_id="OPEN");
    b = Barrier(barrier_id="B_OPEN", blocked=False);
    root ++> w;
    w +>:CarriesBarriers:+> b;
    root spawn Consolidator();
    rec = Recompute();
    root spawn rec;
    assert w.token1 == "ACCESS", f"unblocked gate must allow access: {w.token1}";
    assert w.token2 == "100%", f"expected 100% with zero blocked gates: {w.token2}";
}

test "recompute visits each wsg once on cyclic flow" {
    a = WSG(segment_id="A");
    b = WSG(segment_id="B");
    root ++> a;
    a ++> b;
    b ++> a;
    rec = Recompute();
    root spawn rec;
    assert rec.total_wsg == 2, f"cycle guard should cap visits at 2, got {rec.total_wsg}";
    assert rec.recomputed == 2, f"expected 2 recomputes, got {rec.recomputed}";
    assert a.visited, f"A should be marked visited";
    assert b.visited, f"B should be marked visited";
}

