"""Recursive macro expansion model: tracked enum chain with depth-limited traversal.

Models the gccrs issue where deeply recursive macro expansion degrades compiler
performance. Each FooN enum depends on the previous one (FooN depends on FooN-1)
through a typed DependsOn edge. An Expander walker walks the dependency chain
forward (deepest first) and enforces a depth limit to mimic the compiler's
recursive bound, reporting the deepest reachable depth and any chain that
exceeds the limit.
"""

node MacroDef {
    has name: str = "";
    has depth: int = 0;
    has payload: str = "";
}

edge DependsOn {
    has weight: int = 1;
}

walker Expander {
    has max_depth: int = 10;
    has visited: list[str] = [];
    has deepest: int = 0;
    has over_limit: bool = False;
    has over_limit_name: str = "";

    can start with Root entry {
        visit [-->];
    }

    can expand with MacroDef entry {
        if here.name in self.visited {
            disengage;
        }
        self.visited.append(here.name);
        if here.depth > self.deepest {
            self.deepest = here.depth;
        }
        if here.depth > self.max_depth {
            self.over_limit = True;
            self.over_limit_name = here.name;
            print(f"DEPTH EXCEEDED at {here.name} (depth={here.depth}, limit={self.max_depth})");
            disengage;
        }
        print(f"expanding {here.name} at depth {here.depth}");
        visit [->:DependsOn:->];
    }

    def report() -> dict {
        return {
            "max_depth_seen": self.deepest,
            "over_limit": self.over_limit,
            "offender": self.over_limit_name,
            "expanded_count": len(self.visited),
        };
    }
}

