}

# ---------------------------------------------------------------------------
# Typed edges (the relationships carry meaning, so each is an archetype)
# ---------------------------------------------------------------------------

edge Grants {
    has granted_at: str = "";
}

edge Inherits {
    # A role Inherits from another (more senior) role.
