# Walker 1: PermissionAuditor
#   Walks the inheritance chain from a user's roles, collects grants and
#   denials, and resolves the effective permission list. Includes an
#   explicit visited-set (jac 0.36.1 walkers do not dedupe on cycles).
# ---------------------------------------------------------------------------

walker PermissionAuditor {
    has username: str = "";
    has collected_grants: list[str] = [];
    has collected_denials: list[str] = [];
    has seen_roles: list[str] = [];

    can start with Root entry {
        # Find the target user and start auditing from their role assignments.
        for u in [-->](?:User) {
            if u.username == self.username {
                visit [->:Assigned:->];
            }
        }
    }

    can audit_user with User entry {
        # Already on the user — fall through to roles.
        visit [->:Assigned:->];
    }

    can audit_role with Role entry {
        if here.name in self.seen_roles {
            # Cycle guard: stop walking this branch.
            disengage;
        }
        self.seen_roles.append(here.name);

        # Direct grants from this role.
        for g in [->:Grants:->] {
            if g.name not in self.collected_grants {
                self.collected_grants.append(g.name);
            }
        }

        # Direct denials from this role.
        for d in [->:Denies:->] {
            if d.name not in self.collected_denials {
                self.collected_denials.append(d.name);
            }
        }

        # Walk inheritance upward — but a denial from any ancestor sticks.
        visit [->:Inherits:->];
    }

    can finish with Root entry {
        effective = [];
        for p in self.collected_grants {
            if p not in self.collected_denials and p not in effective {
                effective.append(p);
            }
        }
        report {
            "user": self.username,
            "roles_visited": self.seen_roles,
            "grants": self.collected_grants,
            "denials": self.collected_denials,
            "effective_permissions": effective,
        };
    }
}

# ---------------------------------------------------------------------------
# Walker 2: RoleHierarchyOrder
#   Performs a topological walk over Inherits edges so that each role is
#   processed after the roles it inherits from. Implements Kahn-style
#   ordering: find roots (no incoming Inherits), emit, drop their outgoing
#   edges, repeat — purely with walkers and edge deletes.
# ---------------------------------------------------------------------------

walker FindRoots {
    can start with Root entry {
        # Pick roles that have NO incoming Inherits edge as roots.
        candidates = [];
        for r in [-->](?:Role) {
            has_incoming = false;
            for other in [-->](?:Role) {
                if other ->:Inherits:-> r {
                    has_incoming = true;
                }
            }
            if not has_incoming {
                candidates.append(r);
            }
        }
        report {"roots": candidates};
    }
}

walker EmitRole {
    has order: list[str] = [];
    can start with Root entry {
        for r in [-->](?:Role) {
            if r.name not in self.order {
                self.order.append(r.name);
