"""Compose Preview DEX pipeline: model the dependency → DEX → preview walk.

The issue hand-rolls a pipeline that takes a user project's resolved
Compose artifacts, caches a fingerprint, converts classes.jar to DEX,
and rebuilds the cache when the dependency set changes. The same
pipeline is lifted here to native graph form:

    Project -- resolves to --> ComposeArtifacts
    ComposeArtifacts -- packs --> DexArtifact (typed: PackedFrom)
    DexArtifact -- invalidated by fingerprint --> DexArtifact

A ``D8Pipeline`` walker descends the artifact tree from the project,
fingerprint-checks the cached DEX, and (if the fingerprint mismatches)
walks every dependent artifact via ``PackedFrom`` so the cache can be
fully rebuilt. Cycle policy is explicit (guard set) because Jac 0.36.1
walkers do not dedupe traversal.
"""

# ---------- entities ----------

node Project {
    has name: str = "";
    has kotlin_version: str = "";
    has compose_compiler_version: str = "";
}

node ComposeArtifact {
    has group: str = "";
    has name: str = "";
    has version: str = "";
    has aar: bool = False;

    def fingerprint() -> str {
        return f"{self.group}:{self.name}:{self.version}";
    }
}

node DexArtifact {
    has cache_key: str = "";
    has fingerprint_in_use: str = "";
}

# ---------- relationships ----------

# A project resolves to many compose artifacts (e.g. runtime, ui, material3).
edge Resolves {
    has variant: str = "debug";
}

# A DEX file is packed from exactly one compose artifact (classes.jar → D8).
edge PackedFrom { }

# Dependency ordering between artifacts (foundation → material3).
edge DependsOn { }

# ---------- walker ----------

walker D8Pipeline {
    has current_fingerprint: str = "";
    has cache_hits: int = 0;
    has cache_misses: int = 0;
    has rebuilt: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can open_project with Project entry {
        print(f"Project: {here.name} (Kotlin {here.kotlin_version})");
        # Descend into the project's resolved artifacts via Resolves.
        visit [->:Resolves:->];
    }

    # The resolve step: for each compose artifact, look up (or miss) its
    # cached DEX. If the cached DEX exists and the fingerprint matches the
    # one derived from the resolved artifact, the cache hits; otherwise
    # we walk its descendants via PackedFrom to mark the cache stale.
    can resolve_artifact with ComposeArtifact entry {
        fp = here.fingerprint();
        match_dex = DexArtifact(cache_key=fp, fingerprint_in_use=fp);
        here +>:PackedFrom:+> match_dex;
        if fp == self.current_fingerprint {
            self.cache_hits += 1;
            print(f"  [HIT ] {fp} (aar={here.aar})");
        } else {
            self.cache_misses += 1;
            print(f"  [MISS] {fp} (aar={here.aar})");
            self.rebuilt.append(fp);
            # Cascade-invalidate: walk the packed DEX so callers downstream
            # of the stale DEX see that the cache must be rebuilt. This is
            # the "rebuild when the fingerprint changes" branch of the issue.
            visit [here ->:PackedFrom:->];
        }
    }

    # The cascade path: a stale DEX must be rebuilt. Walk every dependent
    # artifact so the full downstream subtree is invalidated together.
    can rebuild_dex with DexArtifact entry {
        print(f"  [REBUILD] dex({here.cache_key}) stale → regenerating");
        visit [-->];
    }
}

# ---------- demo wiring ----------

with entry {
    # 1. Project.
    app = Project(
        name="CodeOnTheGo",
        kotlin_version="2.3.21",
        compose_compiler_version="2.3.21"
    );

    # 2. Resolved Compose artifacts (runtime, ui, foundation, material3).
    runtime    = ComposeArtifact(group="androidx.compose.runtime",    name="runtime",    version="1.6.0", aar=True);
