node AccessScope {
    has scope_id: int = 0;
    has kind: str = "PROJECT";
    has root_folder_id: int = 0;
}

node Principal {
    has principal_id: int = 0;
    has principal_type: str = "USER";
}

node User(Principal) {
    has user_id: int = 0;
}

node ProjectPrincipal(Principal) {
    has project_id: int = 0;
}

# ----- Edges -----
edge ParentLink {}    # filesystem parent -> child
edge Owns {}          # project -> its items
edge Grants {}        # access scope -> grant node
edge MemberOf {}      # user -> project membership

# ----- Legacy walker: the slow recursive walk the issue complains about -----
walker LegacyAccessWalker {
    has user_id: int = 0;
    has target_id: int = 0;
    has allowed: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can climb with Folder entry {
        # Hand-rolled recursion: walk parent chain to find owning project.
        if here.folder_id == self.target_id {
            self.allowed = True;
            disengage;
        }
        visit [->:ParentLink:->];
    }

    can climb with File entry {
        if here.file_id == self.target_id {
            self.allowed = True;
            disengage;
        }
        visit [->:ParentLink:->];
    }
}

# ----- Modern walker: indexed scope lookup, no recursion needed -----
walker ScopeAccessWalker {
    has principal_type: str = "USER";
    has principal_id: int = 0;
    has target_item_title: str = "";
    has allowed: bool = False;
    has reason: str = "";

    can start with Root entry {
        # Step 1: locate the target item by title (cheap map-style lookup).
        target = [i for i in [-->] if i.title == self.target_item_title];
        if not target {
            self.reason = "item not found";
            disengage;
        }
        item = target[0];

        # Step 2: project-level permission check (no walking).
        if self._check_project(item.owner_project_id) {
            self.allowed = True;
            self.reason = f"project grant on project {item.owner_project_id}";
            disengage;
        }

        # Step 3: scope-level permission check (no walking).
        if self._check_scope(item.access_scope_id) {
            self.allowed = True;
            self.reason = f"scope grant on scope {item.access_scope_id}";
            disengage;
        }

        self.reason = "no matching grant";
        disengage;
    }

    def _check_project(project_id: int) -> bool {
        for proj in [-->] {
            if not isinstance(proj, Project) {
                continue;
            }
            if proj.project_id != project_id {
                continue;
            }
            # Walk MemberOf edges to see if principal is a project member.
            for member in [proj->:MemberOf:->] {
                if member.principal_type == self.principal_type
                        and member.principal_id == self.principal_id {
                    return True;
                }
            }
            # Or if the principal is itself the project (project-to-project).
            if self.principal_type == "PROJECT"
                    and self.principal_id == project_id {
                return True;
            }
        }
        return False;
    }

    def _check_scope(scope_id: int) -> bool {
        for scope in [-->] {
            if not isinstance(scope, AccessScope) {
                continue;
            }
            if scope.scope_id != scope_id {
                continue;
            }
            for grant in [scope->:Grants:->] {
                if grant.principal_type == self.principal_type
                        and grant.principal_id == self.principal_id {
                    return True;
                }
            }
        }
        return False;
    }
}

