        for up in upstreams {
            if up.status != "GO" {
                ready = False;
            }
        }

        if ready {
            here.status = "GO";
            self.go_count += 1;
            print(f"[GO]   {here.ticket:>4} {here.title}  ({here.category})");
        } else {
            here.status = "BLOCKED";
            self.blocked.append(here.ticket);
            self.blocked_count += 1;
            print(f"[WAIT] {here.ticket:>4} {here.title}  ({here.category})  waiting on upstreams");
        }

        # Release gate special handling.
        if here.ticket == "#453" and here.status == "GO" {
            self.release_unlocked = True;
        }

        # Forward traverse dependents; dead-end handling prevents hang.
        visit [->:DependsOn:->] else {
            disengage;
        }
    }
}

