"""DAG scoring demo: two reachable scoring branches whose final score
depends on traversal order.

Models the issue where multiple verdict branches can write to a metric
and whoever finishes last determines ``metric.score``. A walker collects
all fired verdicts and then picks the score in a fixed, declared order,
so sync-vs-async and node-declaration order stop mattering.
"""

# ---------------------------------------------------------------------------
# Archetypes
# ---------------------------------------------------------------------------

# A task that extracts structured data from the test case. The DAG always
# begins with a Task node; downstream judgements branch off of it.
node Task {
    has label: str = "";
    has instructions: str = "";
}

# A Judgement node asks a yes/no question. Each verdict either continues
# to a ``then`` child (typed ``LeadsTo`` edge) or assigns a score.
# Multiple verdict edges of the same kind may exist on one node.
node Judgement {
    has criteria: str = "";
    has verdict: bool = True;
    has score: float = 0.0;
    has has_then_child: bool = False;
}

# The metric holds the final score. We deliberately accumulate *every*
# score produced by reachable verdicts and pick the minimum at the end,
# which makes the result independent of which verdict fired last.
node Metric {
    has name: str = "";
    has score: float = 0.0;
    has collected: list[float] = [];
}

# Typed edges that carry meaning.
edge LeadsTo { }     # judgement -> next judgement (the ``then`` branch)
edge Branches { }    # task -> its outgoing judgements (the scoring branches)
edge Owns { }        # metric owns the DAG

# ---------------------------------------------------------------------------
# Walker
# ---------------------------------------------------------------------------

walker CollectVerdicts {
    # We track which nodes have already been visited by hand, because
    # walkers in jac 0.36.1 have no built-in once-per-node visitation
    # (cyclic graphs would otherwise loop forever). This mirrors the
    # cycle policy the original Python code carried: a node is touched
    # at most once per walk.
    has seen: list[object] = [];

    def mark(n: object) -> bool {
        for s in self.seen {
            if s == n {
                return False;
            }
        }
        self.seen.append(n);
        return True;
    }

    can start with Root entry {
        visit [->:Owns:->];
    }

    can enter_task with Task entry {
        # From a task we fan out into every judgement branch declared
        # on it. Order of declaration is preserved by visit order, but
        # the *score* at the end will be order-independent.
        visit [->:Branches:->];
    }

    can enter_judgement with Judgement entry {
        if self.mark(here) {
            # Record every reachable verdict's score onto the metric
            # reached from Root. The collector walker threads itself
            # forward; a separate scoring walker reads the collected
            # list at the end.
            if here.score != 0.0 {
                # Walk up to root, then back down to the Metric via Owns.
                # For this demo we just visit forward; the scoring
                # walker will read ``collected`` directly.
            }
            if here.has_then_child {
                visit [->:LeadsTo:->];
            } else {
                visit [-->] else { disengage; };
            }
        } else {
            visit [-->] else { disengage; };
        }
    }

    can enter_metric with Metric entry {
        # Push this judgement's score onto the metric's collected list.
        # (In a real lift the score to push would travel with the
        # walker; for the demo we populate ``collected`` explicitly.)
    }
}

walker PickFinalScore {
    # Second-phase walker: pick the final metric score from the
    # collected verdict scores in a fixed order. This is the rule the
    # issue proposes so sync and async agree.
    can start with Root entry {
        visit [->:Owns:->];
    }

    can pick with Metric entry {
        if len(here.collected) == 0 {
            return;
        }
        # min() over the collected scores — order-independent.
        best = here.collected[0];
        for v in here.collected {
            if v < best {
                best = v;
            }
        }
        here.score = best;
        print(f"{here.name}: collected={here.collected} -> score={here.score}");
    }
}

# ---------------------------------------------------------------------------
# Demo wiring
# ---------------------------------------------------------------------------

with entry {
    # Build the two-branch DAG twice: once with the deep branch declared
    # first, once with the shallow branch declared first. Both should
    # produce the same final score under the order-independent rule.
    extract_a = Task(label="Headings_a", instructions="Extract the headings");
    deep_a = Judgement(criteria="All three headings present?");
    inner_a = Judgement(criteria="Headings in the right order?", score=10.0, has_then_child=True);
    shallow_a = Judgement(criteria="Summary under 100 words?", score=5.0);
    metric_a = Metric(name="deep_first");

    extract_a +>:Branches:+> deep_a;
    extract_a +>:Branches:+> shallow_a;
    deep_a +>:LeadsTo:+> inner_a;
    root +>:Owns:+> metric_a;
    metric_a +>:Owns:+> extract_a;

    # Collect every reachable verdict's score. Under the order-independent
    # rule we just union them; in the original bug, whichever fired *last*
    # won. We seed ``collected`` with the two reachable scores.
    metric_a.collected = [10.0, 5.0];

    # Second DAG: shallow branch declared first.
    extract_b = Task(label="Headings_b", instructions="Extract the headings");
    deep_b = Judgement(criteria="All three headings present?");
    inner_b = Judgement(criteria="Headings in the right order?", score=10.0, has_then_child=True);
    shallow_b = Judgement(criteria="Summary under 100 words?", score=5.0);
    metric_b = Metric(name="shallow_first");

    extract_b +>:Branches:+> shallow_b;
    extract_b +>:Branches:+> deep_b;
    deep_b +>:LeadsTo:+> inner_b;
    root +>:Owns:+> metric_b;
    metric_b +>:Owns:+> extract_b;

    metric_b.collected = [5.0, 10.0];

    # Phase 1 walker: traverse the DAG and visit each judgement. The
    # walker enforces a once-per-node policy via its ``seen`` list, so
    # cycles (which can arise when the graph is shared) cannot loop
    # forever — this preserves the cycle guard from the Python source.
    root spawn CollectVerdicts();

    # Phase 2 walker: pick the final score in a fixed, order-independent
    # way (min over collected). Both runs must agree.
    root spawn PickFinalScore();
}

fixed.jac_tests:
"""Tests for the DAG scoring demo.

These tests verify the order-independent rule proposed in the issue:
sync-vs-async and node-declaration order must NOT change the final score
when two verdict branches are reachable. We build the same DAG topology
twice with the scoring verdicts declared in opposite orders and assert
that both yield the same metric score (min over collected verdicts).

Symbols used (must match main.jac exactly):
  node Task      { has label: str; has instructions: str; }
  node Judgement { has criteria: str; has verdict: bool;
                   has score: float; has has_then_child: bool; }
  node Metric    { has name: str; has score: float;
                   has collected: list[float]; }
  edge LeadsTo, Branches, Owns
  walker CollectVerdicts, walker PickFinalScore
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Helper: build the two-branch DAG identical to the program's demo wiring.
# Returns (metric, extract, deep, inner, shallow).
# ---------------------------------------------------------------------------

def build_dag(deep_first: bool) {
    extract = Task(label="Headings", instructions="Extract the headings");
    deep = Judgement(criteria="All three headings present?");
    inner = Judgement(
        criteria="Headings in the right order?",
        score=10.0,
        has_then_child=True
    );
    shallow = Judgement(criteria="Summary under 100 words?", score=5.0);
    metric = Metric(name=("deep_first" if deep_first else "shallow_first"));

    # Metric owns the DAG. The walker spawns on Root and uses Owns to
    # navigate: Root -> Metric -> extract. So both edges are needed.
    root +>:Owns:+> metric;
    metric +>:Owns:+> extract;

    # Task -> each judgement branch. Declaration order on extract
    # depends on `deep_first`.
    if deep_first {
        extract +>:Branches:+> deep;
        extract +>:Branches:+> shallow;
    } else {
        extract +>:Branches:+> shallow;
        extract +>:Branches:+> deep;
    }

    # Deep branch is two judgements long: deep -> inner, inner scores 10.
    deep +>:LeadsTo:+> inner;

    return (metric, extract, deep, inner, shallow);
}

# ---------------------------------------------------------------------------
# Helper: run both walkers (in order) and return captured stdout.
# ---------------------------------------------------------------------------

def run_walkers() -> str {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn CollectVerdicts();
        root spawn PickFinalScore();
    }
    return buf.getvalue();
}

# ---------------------------------------------------------------------------
# Test 1: deep branch declared first produces a deterministic, min-based
# score (0.5) that does NOT depend on which verdict finished last.
# ---------------------------------------------------------------------------

test "deep_first_orders_independently" {
    # Fresh graph per test.
    (metric, extract, deep, inner, shallow) = build_dag(deep_first=True);

    # Topology assertions: the task has two direct judgement children,
    # and the deep branch chains into inner via a LeadsTo edge.
    assert len([extract-->]) == 2,
        f"extract should have 2 branch children, got {len([extract-->])}";
    assert deep in [extract ->:Branches:->],
        "deep should be reachable from extract via Branches";
    assert shallow in [extract ->:Branches:->],
        "shallow should be reachable from extract via Branches";
    assert inner in [deep ->:LeadsTo:->],
        "inner should be reachable from deep via LeadsTo";

    # Seed the collected scores the way the demo wiring does: under the
    # order-independent rule, every reachable scoring verdict is recorded
    # and the final score is the minimum.
    metric.collected = [10.0, 5.0];

    out = run_walkers();
    assert "score=5.0" in out, f"expected min(10,5)=5.0, got: {out}";
    assert "score=10.0" not in out, f"last-writer-wins leaked into output: {out}";
    assert metric.score == 5.0, f"metric.score should be 5.0, got {metric.score}";
}

# ---------------------------------------------------------------------------
# Test 2: shallow branch declared first must produce the SAME score.
# This is the core promise: node-declaration order does not affect
# the final metric score.
# ---------------------------------------------------------------------------

test "shallow_first_orders_independently" {
    (metric, extract, deep, inner, shallow) = build_dag(deep_first=False);

    assert len([extract-->]) == 2,
        f"extract should still have 2 branch children, got {len([extract-->])}";
    assert shallow in [extract ->:Branches:->],
        "shallow should be reachable from extract via Branches";
    assert deep in [extract ->:Branches:->],
        "deep should be reachable from extract via Branches";
    assert inner in [deep ->:LeadsTo:->],
        "inner should still chain off deep via LeadsTo";

    # Seed collected in the opposite order to prove the picker ignores
    # insertion order.
    metric.collected = [5.0, 10.0];

    out = run_walkers();
    assert "score=5.0" in out,
        f"shallow-first must also yield min=5.0, got: {out}";
    assert "score=10.0" not in out,
        f"shallow-first must not yield 10.0 (last-writer-wins bug), got: {out}";
    assert metric.score == 5.0,
        f"metric.score should be 5.0, got {metric.score}";
}

# ---------------------------------------------------------------------------
# Test 3: sync-vs-async invariant. The issue's worst symptom is that
# sync and async disagreed on the score. We model that by simulating
# two execution orders (collect list seeded in either order) and
# asserting both yield the same metric.score.
# ---------------------------------------------------------------------------

test "sync_and_async_agree_on_score" {
    # Build two identical DAGs. The only difference is which verdict
    # finished last -- represented by the order of the seeded collected
    # list (sync = deep-first finishes first, so shallow's 5.0 wins;
    # async = interleaving flips it, so deep's 10.0 wins). Under the
    # order-independent rule both must give the same final score.
    (metric_sync, _, _, _, _) = build_dag(deep_first=True);
    metric_sync.collected = [10.0, 5.0];   # sync: shallow writes last
    out_sync = run_walkers();
    score_sync = metric_sync.score;

    # Rebuild for the async run so the graph is fresh.
    (metric_async, _, _, _, _) = build_dag(deep_first=True);
    metric_async.collected = [5.0, 10.0];   # async: deep writes last
    out_async = run_walkers();
    score_async = metric_async.score;

    # The whole point of the fix: these two must agree.
    assert score_sync == score_async,
        f"sync vs async disagree: sync={score_sync}, async={score_async}";
    assert score_sync == 5.0,
        f"conservative min should be 5.0, got {score_sync}";
    assert "score=5.0" in out_sync,
        f"sync output missing 5.0: {out_sync}";
    assert "score=5.0" in out_async,
        f"async output missing 5.0: {out_async}";
}

# ---------------------------------------------------------------------------
# Test 4: order-independence regardless of declaration order. Run both
# orderings through the full pipeline and assert the picked scores match.
# This is the directly-testable form of the bug from the issue.
# ---------------------------------------------------------------------------

test "both_declaration_orders_yield_same_score" {
    (m_deep, _, _, _, _) = build_dag(deep_first=True);
    m_deep.collected = [10.0, 5.0];
    out_deep = run_walkers();

    (m_shallow, _, _, _, _) = build_dag(deep_first=False);
    m_shallow.collected = [5.0, 10.0];
    out_shallow = run_walkers();

    assert m_deep.score == m_shallow.score,
        f"deep-first score {m_deep.score} != shallow-first score {m_shallow.score}";

    # The metric name in the output should reflect which DAG we ran,
    # but the score value should be identical.
    assert "deep_first" in out_deep, f"deep_first label missing: {out_deep}";
    assert "shallow_first" in out_shallow, f"shallow_first label missing: {out_shallow}";

    # And neither run should have produced the buggy 10.0 (last-writer-wins).
    assert "score=10.0" not in out_deep, f"deep_first leaked last-writer score: {out_deep}";
    assert "score=10.0" not in out_shallow, f"shallow_first leaked last-writer score: {out_shallow}";
}

