fixed.code:
"""Dynamic child-region supervision and recovery on a factory floor.

Models the essential scenario from issue #38: a parent region supervises
dynamically created child regions, each with explicit completion, timeout,
cancellation, restart-recovery, and failure-propagation semantics. A
``Supervisor`` walker recursively propagates cancellation across descendants,
fences stale work, and prunes abandoned retries; an ``Inspector`` walker
collects the supervisor's authoritative state and projections."""

node WorkRegion {
    has name: str = "";
    has epoch: int = 0;
    has cancelled: bool = False;
    has blocked_reason: str = "";
    has terminal_outcome: str = "pending";  # pending | success | failed | timeout | cancelled
}

edge Supervises {
    has budget_ms: int = 1000;
    has attempt: int = 0;
    has abandoned: bool = False;
}

walker Supervisor {
    has trace_log: list[str] = [];

    can begin with Root entry {
        visit [-->];
    }

    can supervise with WorkRegion entry {
        self.trace_log.append(f"supervise:{here.name}:epoch={here.epoch}:outcome={here.terminal_outcome}");
        if here.cancelled {
            self.trace_log.append(f"fence-stale:{here.name}");
            visit [-->] else { disengage; }
            return;
        }
        # Propagate cancellation to descendants, advance epoch, fence stale work.
        here.cancelled = True;
        here.epoch += 1;
        here.terminal_outcome = "cancelled";
        self.trace_log.append(f"propagate-cancel:{here.name}");
        visit [->:Supervises:->];
    }

    can prune with WorkRegion entry {
        # Abandoned retries: keep history but no longer a live successor.
        here.terminal_outcome = "abandoned";
        self.trace_log.append(f"prune-abandoned:{here.name}");
    }
}

walker Inspector {
    has report_lines: list[str] = [];

    can begin with Root entry {
        visit [-->];
    }

    can inspect with WorkRegion entry {
        blocked = "none" if here.blocked_reason == "" else here.blocked_reason;
        line = f"region={here.name} epoch={here.epoch} outcome={here.terminal_outcome} blocked={blocked}";
        self.report_lines.append(line);
        visit [-->];
    }
}

with entry {
    parent = WorkRegion(name="parent-line");
    child_a = WorkRegion(name="child-A", terminal_outcome="success");
    child_b = WorkRegion(name="child-B", terminal_outcome="failed");
    child_c = WorkRegion(name="child-C", terminal_outcome="timeout", blocked_reason="deadline");
    # Abandoned retry of child-B: history preserved, not a live successor.
    child_b_retry = WorkRegion(name="child-B#retry1", terminal_outcome="abandoned");
    grandchild = WorkRegion(name="grandchild-A1");

    root ++> parent;
    parent +>:Supervises(budget_ms=500, attempt=1):+> child_a;
    parent +>:Supervises(budget_ms=500, attempt=1):+> child_b;
    parent +>:Supervises(budget_ms=250, attempt=1):+> child_c;
    parent +>:Supervises(budget_ms=500, attempt=2, abandoned=True):+> child_b_retry;
    child_a +>:Supervises(budget_ms=200, attempt=1):+> grandchild;

    supervisor = Supervisor();
    root spawn supervisor;
    print("supervision trace:");
    for entry in supervisor.trace_log {
        print(f"  {entry}");
    }

    inspector = Inspector();
    root spawn inspector;
    print("inspection report:");
    for line in inspector.report_lines {
        print(f"  {line}");
    }
}

fixed.jac_tests:
test "cancellation advances epochs through descendants" {
    parent = WorkRegion(name="parent");
    child = WorkRegion(name="child");
    grandchild = WorkRegion(name="grandchild");
    root ++> parent;
    parent +>:Supervises:+> child;
    child +>:Supervises:+> grandchild;

    supervisor = Supervisor();
    result = root spawn supervisor;

    assert parent.cancelled == True, f"parent cancelled={parent.cancelled}";
    assert child.cancelled == True, f"child cancelled={child.cancelled}";
    assert grandchild.cancelled == True, f"grandchild cancelled={grandchild.cancelled}";
    assert parent.epoch == 1, f"parent epoch={parent.epoch}";
    assert child.epoch == 1, f"child epoch={child.epoch}";
    assert grandchild.epoch == 1, f"grandchild epoch={grandchild.epoch}";
}

test "repeated recovery does not advance a settled epoch" {
    parent = WorkRegion(name="parent");
    child = WorkRegion(name="child");
    root ++> parent;
    parent +>:Supervises:+> child;

    first = Supervisor();
    root spawn first;
    second = Supervisor();
    root spawn second;

    assert parent.epoch == 1, f"parent epoch after retry={parent.epoch}";
    assert child.epoch == 1, f"child epoch after retry={child.epoch}";
    assert parent.cancelled == True, f"parent cancelled after retry={parent.cancelled}";
    assert child.cancelled == True, f"child cancelled after retry={child.cancelled}";
    assert len([parent-->]) == 1, f"parent child count={len([parent-->])}";
}

test "typed retry history retains terminal states" {
    parent = WorkRegion(name="parent");
    failed_attempt = WorkRegion(name="child-B", terminal_outcome="failed");
    abandoned_retry = WorkRegion(name="child-B#retry1", terminal_outcome="abandoned");
    cancelled_attempt = WorkRegion(
        name="child-B#cancelled",
        terminal_outcome="cancelled",
        cancelled=True,
        epoch=3
    );
    root ++> parent;
    parent +>:Supervises(budget_ms=500, attempt=1):+> failed_attempt;
    parent +>:Supervises(budget_ms=500, attempt=2, abandoned=True):+> abandoned_retry;
    parent +>:Supervises(budget_ms=500, attempt=3):+> cancelled_attempt;

    typed_count = len([parent ->:Supervises:->]);
    assert typed_count == 3, f"typed children={typed_count}";
    assert failed_attempt in [parent ->:Supervises:->], f"failed attempt missing";
    assert abandoned_retry in [parent ->:Supervises:->], f"abandoned retry missing";
    assert cancelled_attempt in [parent ->:Supervises:->], f"cancelled attempt missing";
    assert failed_attempt.terminal_outcome == "failed", f"failed outcome={failed_attempt.terminal_outcome}";
    assert abandoned_retry.terminal_outcome == "abandoned", f"retry outcome={abandoned_retry.terminal_outcome}";
    assert cancelled_attempt.terminal_outcome == "cancelled", f"cancelled outcome={cancelled_attempt.terminal_outcome}";
    assert cancelled_attempt.epoch == 3, f"cancelled epoch={cancelled_attempt.epoch}";
    all_count = len([parent-->]);
    assert all_count == 3, f"all child history count={all_count}";
}

test "inspection exposes terminal and blocking projections" {
    parent = WorkRegion(name="parent");
    success = WorkRegion(name="child-A", terminal_outcome="success");
    timed_out = WorkRegion(
        name="child-C",
        terminal_outcome="timeout",
        blocked_reason="deadline"
    );
    root ++> parent;
    parent +>:Supervises:+> success;
    parent +>:Supervises:+> timed_out;

    inspector = Inspector();
    result = root spawn inspector;

    assert len(inspector.report_lines) == 3, f"report count={len(inspector.report_lines)}";
    assert inspector.report_lines[1] == "region=child-A epoch=0 outcome=success blocked=none", f"success report={inspector.report_lines[1]}";
    assert inspector.report_lines[2] == "region=child-C epoch=0 outcome=timeout blocked=deadline", f"timeout report={inspector.report_lines[2]}";
}

