"""Tests for the VTX2.3 Substrait -> SQLGlot -> governed PostgreSQL projection."""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Test 1: the mapper walker emits From + each projection expression in the
# correct bottom-up dependency order for the #2598 fixture.
# ---------------------------------------------------------------------------
test "mapper emits from clause and projections in order" {
    rt = Root();
    read = ReadRel(table_name="customers");
    f_name = FieldRef(field_name="name");
    f_email = FieldRef(field_name="email");
    f_country = FieldRef(field_name="country");
    p_name = ProjectRel(output_name="customer_name", expression="upper(trim(name))");
    p_email = ProjectRel(output_name="email", expression="email");
    p_country = ProjectRel(output_name="country", expression="country");

    rt ++> read;
    read +>:HasRel:+> p_name;
    read +>:HasRel:+> p_email;
    read +>:HasRel:+> p_country;
    p_name +>:DependsOn(field_name="name"):+> f_name;
    p_email +>:DependsOn(field_name="email"):+> f_email;
    p_country +>:DependsOn(field_name="country"):+> f_country;

    mapper = SubstraitToSqlGlot();
    read spawn mapper;

    rendered = mapper.rendered;
    assert "FROM customers" in rendered, f"missing FROM clause: {rendered}";
    name_idx = rendered.index("FROM customers");
    expr_indices = [
        rendered.index("customer_name := upper(trim(name))"),
        rendered.index("email := email"),
        rendered.index("country := country"),
    ];
    for idx in expr_indices {
        assert idx > name_idx, f"projection rendered before FROM: {rendered}";
    }
    assert len(mapper.diagnostics) == 0, f"unexpected diagnostics: {mapper.diagnostics}";
}

# ---------------------------------------------------------------------------
# Test 2: an unadmitted ReadRel is short-circuited and flagged.
# ---------------------------------------------------------------------------
test "unadmitted ReadRel short-circuits and emits diagnostic" {
    rt = Root();
