# ---------------------------------------------------------------------------
test "unadmitted ProjectRel is flagged with placeholder" {
    rt = Root();
    read = ReadRel(table_name="customers");
    f_secret = FieldRef(field_name="secret");
    p_name = ProjectRel(output_name="customer_name", expression="upper(trim(name))");
    p_bad = ProjectRel(output_name="secret_col", expression="vault()", admitted=False);

    rt ++> read;
    read +>:HasRel:+> p_name;
    read +>:HasRel:+> p_bad;
    p_name +>:DependsOn(field_name="name"):+> FieldRef(field_name="name");
    p_bad +>:DependsOn(field_name="secret"):+> f_secret;

    mapper = SubstraitToSqlGlot();
    read spawn mapper;

    rendered = mapper.rendered;
    assert any("unadmitted projection secret_col" in line for line in rendered), f"missing placeholder: {rendered}";
    assert any(d == "unadmitted projection secret_col" for d in mapper.diagnostics), f"diagnostics: {mapper.diagnostics}";
    assert "customer_name := upper(trim(name))" in rendered, f"good projection missing: {rendered}";
