# ---------------------------------------------------------------------------
test "renderer emits governed PostgreSQL in source order" {
    rt = Root();
    sql_select = SqlGlotExpr(sql_kind="SELECT_STMT", sql_text="SELECT");
    sql_proj1 = SqlGlotExpr(sql_kind="PROJECTION", sql_text="upper(trim(name)) AS customer_name,");
    sql_proj2 = SqlGlotExpr(sql_kind="PROJECTION", sql_text="email AS email,");
    sql_proj3 = SqlGlotExpr(sql_kind="PROJECTION", sql_text="country AS country");
    sql_from = SqlGlotExpr(sql_kind="FROM_CLAUSE", sql_text="FROM customers");
    sql_noise = SqlGlotExpr(sql_kind="IGNORED", sql_text="should not appear");

    rt +>:HasExpr:+> sql_select;
    sql_select +>:HasExpr:+> sql_proj1;
    sql_select +>:HasExpr:+> sql_proj2;
    sql_select +>:HasExpr:+> sql_proj3;
