"""Structured object search with boolean related predicates.

Models the hubuum-style "POST search" workflow as native Jac graph
machinery: classes own typed object instances, objects carry a
field-typed value bag, and ``Related`` edges represent the cross-class
relations the boolean expression tree walks. A search walker descends a
nested ``and`` / ``or`` / ``not`` tree, evaluates direct field predicates
on candidate objects, and explores ``related`` predicates by traversing
``Related`` edges with an explicit visited-set cycle policy. Stable
cursor pagination is simulated by walking past a deterministic offset
before emitting results.
"""

# ---------------------------------------------------------------------------
# Core entity archetypes
# ---------------------------------------------------------------------------

node Object {
    has name: str = "";
    has class_name: str = "";
    has value: str = "";

    def field_equals(field: str, operand: str) -> bool {
        if field == "name" {
            return self.name == operand;
        }
        if field == "value" {
            return self.value == operand;
        }
        return False;
    }
}

node HostClass {
    has class_id: int = 0;
    has class_name: str = "";
}

node Room {
    has room_id: int = 0;
    has label: str = "";
}

node Person {
    has person_id: int = 0;
    has handle: str = "";
}

# ---------------------------------------------------------------------------
# Relationship edges
# ---------------------------------------------------------------------------

edge Hosts {
    has since: str = "";
}

edge Related {
    has kind: str = "";
}

# ---------------------------------------------------------------------------
# Boolean expression tree (versionable, deliberately small).
# ---------------------------------------------------------------------------

node Expr {
    has op: str = "";
}

node FieldExpr(Expr) {
    has field: str = "";
    has operand: str = "";
}

node NotExpr(Expr) {
    has child: Expr = None;
}

node RelatedExpr(Expr) {
    has direction: str = "out";
    has target_class: str = "";
    has child: Expr = None;
    has max_depth: int = 2;
}

node AndExpr(Expr) {
    has left: Expr = None;
    has right: Expr = None;
}

node OrExpr(Expr) {
    has left: Expr = None;
    has right: Expr = None;
}

# ---------------------------------------------------------------------------
# Search walker: walks the expression tree and the Related-edge graph,
# enforcing an explicit visited set as the cycle policy.
# ---------------------------------------------------------------------------

walker Search {
    has query_fingerprint: str = "";
    has cursor_offset: int = 0;
    has page_size: int = 0;
    has emitted: int = 0;
    has include_total: bool = True;
    has total_matches: int = 0;
    has candidates: list = [];
    has visited_edges: set = {};

    can start with HostClass entry {
        print(f"Search on class '{here.class_name}' "
              f"(fingerprint={self.query_fingerprint}, "
              f"cursor={self.cursor_offset}, page={self.page_size})");
        for (i, obj) in enumerate(self.candidates) {
            verdict = self.evaluate_object(obj);
            if verdict {
                self.total_matches += 1;
                if i >= self.cursor_offset and self.emitted < self.page_size {
                    self.emit(obj);
                }
            }
        }
        if self.include_total {
            print(f"total_matches={self.total_matches}");
        } else {
            print("include_total=false: total-count work skipped");
        }
    }

    def emit(obj: Object) -> None {
        self.emitted += 1;
        status = "MATCH";
        print(f"[{status}] {here.class_name}:{obj.name} = {obj.value}");
    }

    def evaluate_object(obj: Object) -> bool {
        # Use the class node attached to ``here`` as the rule source.
        return self.evaluate(self.candidates_expr, obj);
    }

    def evaluate(expr: Expr, obj: Object) -> bool {
        if isinstance(expr, FieldExpr) {
            return obj.field_equals(expr.field, expr.operand);
        }
        if isinstance(expr, NotExpr) {
            return not self.evaluate(expr.child, obj);
        }
        if isinstance(expr, AndExpr) {
            return self.evaluate(expr.left, obj)
                and self.evaluate(expr.right, obj);
        }
        if isinstance(expr, OrExpr) {
            return self.evaluate(expr.left, obj)
                or self.evaluate(expr.right, obj);
        }
        if isinstance(expr, RelatedExpr) {
            return self.evaluate_related(expr, obj);
        }
        return False;
    }

    def evaluate_related(expr: RelatedExpr, obj: Object) -> bool {
        # Walk Related edges breadth-first up to expr.max_depth, recording
        # every edge we cross so cycles cannot loop forever.
        frontier = [obj];
        seen: set = {obj};
        depth = 0;
        while frontier and depth < expr.max_depth {
            depth += 1;
            next_frontier = [];
            for node in frontier {
                if expr.direction == "out" {
                    neighbors = [t for (e, t) in [ne
                        for ne in --node->:Related:->]] ;
                } else {
                    neighbors = [s for (s, e) in [ne
                        for ne in node<-:Related:--]] ;
                }
                for nb in neighbors {
                    if nb in seen {
                        continue;
                    }
                    seen.add(nb);
                    if self.evaluate(expr.child, nb) {
                        return True;
                    }
                    next_frontier.append(nb);
                }
            }
            frontier = next_frontier;
        }
        return False;
    }
}

# ---------------------------------------------------------------------------
# Demo wiring: a class with objects, related Rooms and Persons, and a
# boolean expression tree that mirrors the issue's example
# (related Room named 'foo' AND related Person named 'bar' OR 'zoot').
# ---------------------------------------------------------------------------

with entry {
    cls = HostClass(class_id=1, class_name="Booking");

    room_foo = Room(room_id=10, label="foo");
    room_basement = Room(room_id=11, label="basement");

    person_bar = Person(person_id=20, handle="bar");
    person_zoot = Person(person_id=21, handle="zoot");
    person_qux = Person(person_id=22, handle="qux");

    root +>:Hosts:+> cls;

    obj_a = Object(name="bk-001", class_name="Booking", value="A");
    obj_b = Object(name="bk-002", class_name="Booking", value="B");
    obj_c = Object(name="bk-003", class_name="Booking", value="C");
    obj_d = Object(name="bk-004", class_name="Booking", value="D");

    root ++> obj_a;
    root ++> obj_b;
    root ++> obj_c;
    root ++> obj_d;

    # obj_a is related to foo and bar
    obj_a +>:Related(kind="uses"):+> room_foo;
    obj_a +>:Related(kind="owner"):+> person_bar;

    # obj_b is related to foo and zoot
    obj_b +>:Related(kind="uses"):+> room_foo;
    obj_b +>:Related(kind="owner"):+> person_zoot;

    # obj_c is related to basement and qux (no matching related Room)
    obj_c +>:Related(kind="uses"):+> room_basement;
    obj_c +>:Related(kind="owner"):+> person_qux;

    # obj_d is related only to basement
    obj_d +>:Related(kind="uses"):+> room_basement;

    # Expression tree:
    #   related(Room,name='foo') AND (related(Person,name='bar') OR related(Person,name='zoot'))
    person_is_bar = FieldExpr(op="field", field="name", operand="bar");
    person_is_zoot = FieldExpr(op="field", field="name", operand="zoot");
    person_match = OrExpr(op="or", left=person_is_bar, right=person_is_zoot);

    room_is_foo = FieldExpr(op="field", field="name", operand="foo");
    room_match = RelatedExpr(
        op="related",
        direction="out",
        target_class="Room",
        child=room_is_foo,
        max_depth=2
    );
    person_match_related = RelatedExpr(
        op="related",
        direction="out",
        target_class="Person",
        child=person_match,
        max_depth=2
    );
    full_expr = AndExpr(op="and", left=room_match, right=person_match_related);

    # Build a deterministic candidate list (could be a class-scoped query).
    candidates = [obj_a, obj_b, obj_c, obj_d];

    # Fingerprint would be derived from a canonical serialization of the
    # expression + sort + auth context in a real implementation.
    walker_instance = Search(
        query_fingerprint="sha256:deadbeef",
        cursor_offset=0,
        page_size=10,
        candidates=candidates,
        include_total=True
    );
    walker_instance.candidates_expr = full_expr;

    cls spawn walker_instance;
}

