"""Blast-radius review over a connected-type architecture graph.

Models the essential scenario from ggcdevs/pente3D.ai issue #25:
given a type X whose exported contract changed, find the downstream
modules Y/Z that reference it, classify them as pure or glue, and
report which consumers were left untested by the changeset.

The hand-rolled machinery the issue complains about (recursive parent
walks, manual cascade invalidation, per-consumer query loops) is
replaced by a walker over typed edges.
"""

node Module {
    has name: str = "";
    has kind: str = "pure";
    # Pure modules are covered by co-located Y.test.ts; glue modules
    # (render, net, ui) are covered only by Playwright e2e tests.
    has in_changeset: bool = False;
    has tests_touched: bool = False;
}

node Type {
    has name: str = "";
    has contract: str = "";
    # Snapshot of the type's exported signature/fields/methods/exports
    # BEFORE the commit. Diffed against post-commit to decide whether
    # the contract actually changed (the staleness filter from §Design).
    has contract_changed: bool = False;
}

edge References {
    has relation: str = "uses";
    # Creates / param / returns / field / extends / uses.
}

walker BlastRadius {
    has origin: str = "";
    has visited: list[str] = [];
    has pure_uncovered: list[str] = [];
    has glue_uncovered: list[str] = [];

    can start with Type entry {
        # Seed: remember the type whose contract changed.
        self.origin = here.name;
        self.visited = self.visited + [here.name];
        visit [->:References:->];
    }

    can audit with Module entry {
        # The change is "blasting" a module if neither the module nor
        # its tests appear in the changeset. This is the test-delta
        # cross-reference the issue describes.
        covered = here.in_changeset or here.tests_touched;
        if not covered {
            if here.kind == "pure" {
                self.pure_uncovered = self.pure_uncovered + [here.name];
            } else {
                self.glue_uncovered = self.glue_uncovered + [here.name];
            }
        }
        visit [-->];
    }

    can summarize with Root entry {
        # The single exit report: a question the agent must answer,
        # not an assertion the tool can't back up.
        print(
            f"Type {self.origin}'s contract changed; "
            f"consumers with no test delta in this change:"
        );
        has_pure = len(self.pure_uncovered) > 0;
        has_glue = len(self.glue_uncovered) > 0;
        pure_label = "(pure)" if has_pure else "(none)";
        glue_label = "(glue)" if has_glue else "(none)";
        pure_list = ", ".join(self.pure_uncovered) if has_pure else "—";
        glue_list = ", ".join(self.glue_uncovered) if has_glue else "—";
        print(f"  pure: {pure_list} {pure_label}");
        print(f"  glue: {glue_list} {glue_label}");
        if has_pure {
            print(
                "  Confirm each pure consumer is unaffected or covered "
                "by a co-located Y.test.ts delta."
            );
        }
        if has_glue {
            print(
                "  Glue consumers are Playwright-verified, not unit-"
                "tested: confirm an e2e still covers this path."
            );
        }
        disengage;
    }
}

with entry {
    # Architecture: a single type whose contract changed, with
    # downstream pure and glue consumers. Some consumers were also
    # touched in the changeset (so they are NOT flagged).
    scene_sync = Type(name="SceneSync", contract="engine:Scene", contract_changed=True);

    sync_engine = Module(name="SyncEngine", kind="pure", in_changeset=True, tests_touched=True);
    scene_view = Module(name="SceneView", kind="pure");
    render_loop = Module(name="RenderLoop", kind="glue");
    net_io = Module(name="NetIO", kind="glue", in_changeset=True, tests_touched=False);
    ui_panel = Module(name="UIPanel", kind="glue");

    scene_sync +>:References(relation="creates"):+> sync_engine;
    scene_sync +>:References(relation="field"):+> scene_view;
    scene_sync +>:References(relation="param"):+> render_loop;
    scene_sync +>:References(relation="returns"):+> net_io;
    scene_sync +>:References(relation="uses"):+> ui_panel;
    root ++> scene_sync;

    b = BlastRadius();
    scene_sync spawn b;
    root spawn b;
}

