"""Test impact analysis via graph reachability.

Models the core scenario from issue #137: a maintainer wants to know which
tests need to re-run when code changes. We keep two layers of graph state
(structural dependencies and behavioral call edges), then walk reachable
components from each test entry point to determine the impact set.
"""

node Component {
    has name: str = "";
    has file: str = "";
}

node TestCase {
    has name: str = "";
}

node Change {
    has file: str = "";
}

edge DependsOn {
    has kind: str = "structural";
}

edge Calls {
    has callsite: str = "";
}

edge AffectedBy {
    has reason: str = "";
}

walker ImpactAnalyzer {
    has affected: dict[str, list[str]] = {};

    can start with Root entry {
        visit [-->];
    }

    can collect_changes with Change entry {
        reason = f"changed:{here.file}";
        here +>:AffectedBy(reason=reason):+> Component(name="", file=here.file);
        visit [-->];
    }

    can seed_tests with TestCase entry {
        visit [->:Calls:->];
    }

    can walk_calls with Component entry {
        key = here.file;
        if key not in self.affected {
            self.affected[key] = [];
        }
        if here.name != "" and here.name not in self.affected[key] {
            self.affected[key].append(here.name);
        }
        visit [->:DependsOn:->];
    }

    can reach_components with Component entry {
        key = here.file;
        if key not in self.affected {
            self.affected[key] = [];
        }
        if here.name != "" and here.name not in self.affected[key] {
            self.affected[key].append(here.name);
        }
        visit [->:DependsOn:->];
    }

    can report with Root entry {
        total = 0;
        for k in self.affected.keys() {
            total += len(self.affected[k]);
        }
        print(f"Impact coverage: {total} component refs across {len(self.affected.keys())} files");
        for file in self.affected.keys() {
            names = self.affected[file];
            joined = ", ".join(names);
            print(f"  {file} -> [{joined}]");
        }
        disengage;
    }
}

