    has title: str = "";
    has body_read: bool = False;            # word/document.xml only?
    has footnotes_read: bool = False;       # footnotes.xml relationship traversed?
    has endnotes_read: bool = False;        # endnotes.xml relationship traversed?
    has encrypted: bool = False;            # explicit diagnostic for unsupported packages
}

# ---------- Typed edges: how spans attach to their host document ----------

edge PartOf {
    has story_part: str = "";   # word/document.xml | word/footnotes.xml | ...
}

# ---------- Walker: walks every reachable span, classifies, reports ----------

walker Reconcile {
    has target_format: str = "";
