# Entities
# ----------------------------------------------------------------------

node Turn {
    has role: str = "";
    has payload: str = "";
    has token_count: int = 0;
    has anchor: bool = False;
}

node Conversation {
    has name: str = "";
    has template: str = "";
    has reanchors_on_user: bool = False;
}

# ----------------------------------------------------------------------
# Typed edges
# ----------------------------------------------------------------------

# A turn follows another turn in the same conversation.
edge NextTurn { has order: int = 0; }

# A conversation contains its turns (typed, payload-free relationship).
edge HoldsTurn { }

# A template re-anchors the last user query (semantic edge).
edge Anchors { }

