# Walker: RangeRecomputer — performs the per-turn probe traversal the
# issue describes. In the real code each per-message probe re-renders the
# full conversation; here we model that as one full-render step per turn
# visited, with an explicit visited set so cycles cannot hang the walker.
# ----------------------------------------------------------------------

walker RangeRecomputer {
    has visits: int = 0;
    has tokens_seen: int = 0;
    has full_recompute: bool = True;

    can start with Root entry {
        # Walk into every conversation anchored at root.
        visit [-->];
    }

    can enter_conversation with Conversation entry {
        print(f"[conv] {here.name} template={here.template} "
              f"reanchors_on_user={here.reanchors_on_user}");
