        visit [->:HoldsTurn:->];
    }

    can probe_turn with Turn entry {
        # Each turn probe = one full render of the whole conversation.
        self.visits += 1;
        self.tokens_seen += here.token_count;
        here.anchor = True;
        visit [->:NextTurn:->];
    }
}

