# Walker: IncrementalWalker — models the cheap path: walk once from the
# new tail anchor and only probe downstream turns whose offsets moved.
# ----------------------------------------------------------------------

walker IncrementalWalker {
    has visits: int = 0;

    can start with Root entry {
        visit [-->];
