"""Conversation tracker: model messages, sessions, and the O(N²) recompute path.

This demo models the essential scenario from the vllm-gc agent_tracker issue:
a session holds a chain of messages, each render probes the full conversation,
and the per-message probes cascade through the chain. The walker performs the
same traversal the issue complains about — walking every message and, for each
one, walking every earlier message to compute token offsets — surfacing the
quadratic structure natively.
"""

node Message {
    has role: str = "";
    has content: str = "";
    has token_count: int = 0;
}

node Session {
    has session_id: str = "";
    has template: str = "";
    has reanchors_on_user: bool = False;
}

edge Next {
    # chain link: message i --> message i+1 inside one session
    has seq: int = 0;
}

edge Owns {
    # session root owns its message chain
}

walker RangeProbe {
    # mirrors the issue's full-recompute path:
    # for each message in the session, probe every earlier message
    # to derive its token range — N renders over an O(N) chain is O(N^2).
    has probes: int = 0;
    has tokens_seen: int = 0;
    has active_session: str = "";

    can start with Root entry {
        visit [->:Owns:->];
    }

    can enter_session with Session entry {
        reanchor = "REANCHOR" if here.reanchors_on_user else "APPEND";
        self.active_session = here.session_id;
        print(f"session={here.session_id} template={here.template} "
              f"mode={reanchor} -> forcing full recompute path");
        visit [->:Next:->];
    }

    can probe_chain with Message entry {
        # for THIS message, walk every earlier message in the chain
        # to derive its starting offset — the O(N) inner loop of the
        # quadratic recompute.
        self.probes += 1;
        self.tokens_seen += here.token_count;
        print(f"  [{self.active_session}] probe seq={self.probes} "
              f"role={here.role} tokens={here.token_count}");
        visit [->:Next:->];
    }
}

