"""Symmetric-aggregate fan-out demo: model a Malloy-style parent source with two
join_many legs and traverse it with walkers that mirror the slow plan shape
(traversing every fan-out row) and the fast pre-aggregated plan shape
(collapsing each leg before merging)."""

# ---------------------------------------------------------------------------
# Entity archetypes
# ---------------------------------------------------------------------------

node LegRow {
    has leg_id: int = 0;
    has parent_id: int = 0;
    has amount: float = 0.0;
}

# A leg holds the raw fan-out rows that the slow symmetric-aggregate plan must
# traverse one-by-one. Modeling the rows as real graph nodes is what lets the
# "slow" walker prove out the fanned traversal cost analog.
node LegA {
    has label: str = "leg_a";
}

node LegB {
    has label: str = "leg_b";
}

# A parent is the root of the graph. It owns both legs and exposes measures
# computed either by walking every fan-out row (slow path) or by visiting a
# pre-aggregated child that already holds the per-parent sum (fast path).
node Parent {
    has pid: int = 0;
}

# ---------------------------------------------------------------------------
# Edge archetypes
# ---------------------------------------------------------------------------

# A parent owns its raw fan-out rows via one edge type per leg so walkers can
# pick a leg by edge type without scanning the wrong rows.
edge HasLegARow {
    has row_id: int = 0;
}

edge HasLegBRow {
    has row_id: int = 0;
}

# The pre-aggregated leg-a helper: instead of holding every raw row, this
# holds a single aggregate node per parent, which is exactly the rewrite the
# issue recommends.
edge HasLegAAggregate {
    has amount_total: float = 0.0;
}

edge HasLegBAggregate {
    has amount_total: float = 0.0;
}

# A row belongs to a parent. We separate "row-to-parent" so a walker that
# arrives at a row knows where to report back to.
edge BelongsToParent {
    has pid: int = 0;
}

# A pre-aggregated leaf node — a placeholder representing the per-parent total
# computed ahead of time. Visiting it is O(1) per parent rather than O(rows).
node LegAAggregate {
    has pid: int = 0;
    has amount_total: float = 0.0;
}

node LegBAggregate {
    has pid: int = 0;
    has amount_total: float = 0.0;
}

# ---------------------------------------------------------------------------
# Walkers
# ---------------------------------------------------------------------------

# SlowPlanWalker mirrors the fanned symmetric-aggregate plan: it walks every
# raw row of both legs through typed edges and sums the amounts itself.
# This is the O(rows_in_leg_a + rows_in_leg_b) traversal the issue calls out.
walker SlowPlanWalker {
    has a_total: float = 0.0;
    has b_total: float = 0.0;

    can start with Parent entry {
        # Walk every raw row of leg_a then leg_b. Typed edges keep the two
        # legs separate so the sums never bleed into each other.
        visit [->:HasLegARow:->];
        visit [->:HasLegBRow:->];
    }

    can collect_a with LegRow entry {
        # Only fire on leg-a rows. The leg identity is encoded by which typed
        # edge delivered us here, so we just sum unconditionally.
        self.a_total = self.a_total + here.amount;
        visit [-->];
    }

    can collect_b with LegRow entry {
        self.b_total = self.b_total + here.amount;
        visit [-->];
    }

    def report() -> dict {
        return {"a_total": self.a_total, "b_total": self.b_total};
    }
}

# FastPlanWalker mirrors the pre-aggregated rewrite: it visits only the
# per-parent aggregate nodes, never the raw fan-out rows.
walker FastPlanWalker {
    has a_total: float = 0.0;
    has b_total: float = 0.0;

    can start with Parent entry {
        visit [->:HasLegAAggregate:->];
        visit [->:HasLegBAggregate:->];
    }

    can collect_a_agg with LegAAggregate entry {
        self.a_total = self.a_total + here.amount_total;
        visit [-->];
    }

    can collect_b_agg with LegBAggregate entry {
        self.b_total = self.b_total + here.amount_total;
        visit [-->];
    }

    def report() -> dict {
        return {"a_total": self.a_total, "b_total": self.b_total};
    }
}

# ReachabilityChecker walks the parent -> aggregate edges only. It exists to
# show the typed-edge view of the graph: a parent is reachable through the
# pre-aggregated helper in one hop, exactly as the issue's recommended
# `join_one` rewrite does at the SQL level.
walker ReachabilityChecker {
    has reachable_via_a: bool = False;
    has reachable_via_b: bool = False;

    can start with Parent entry {
        visit [->:HasLegAAggregate:->] else { disengage; }
    }

    can note_a with LegAAggregate entry {
        self.reachable_via_a = True;
        visit [->:HasLegBAggregate:->] else { disengage; }
    }

    can note_b with LegBAggregate entry {
        self.reachable_via_b = True;
        visit [-->];
    }
}

# ---------------------------------------------------------------------------
# Demo wiring
# ---------------------------------------------------------------------------

with entry {
    # Build a small but representative fan-out: 4 parents, each with 3 raw
    # rows per leg. The slow walker must visit 4*3*2 = 24 rows; the fast
    # walker visits only 4*2 = 8 aggregate nodes.
    parent_count = 4;
    rows_per_leg = 3;

    expected_a_total = 0.0;
    expected_b_total = 0.0;

    for p in range(1, parent_count + 1) {
        parent = Parent(pid=p);

        # Pre-compute the per-parent totals that the fast path will read.
        a_total_for_p = 0.0;
        b_total_for_p = 0.0;

        for j in range(1, rows_per_leg + 1) {
            a_amount = j * 1.0;
            b_amount = j * 1.0;

            a_row = LegRow(leg_id=(p - 1) * rows_per_leg + j,
                           parent_id=p,
                           amount=a_amount);
            b_row = LegRow(leg_id=(p - 1) * rows_per_leg + j,
                           parent_id=p,
                           amount=b_amount);

            parent +>:HasLegARow(row_id=(p - 1) * rows_per_leg + j):+> a_row;
            parent +>:HasLegBRow(row_id=(p - 1) * rows_per_leg + j):+> b_row;

            a_total_for_p = a_total_for_p + a_amount;
            b_total_for_p = b_total_for_p + b_amount;
        }

        expected_a_total = expected_a_total + a_total_for_p;
        expected_b_total = expected_b_total + b_total_for_p;

        a_agg = LegAAggregate(pid=p, amount_total=a_total_for_p);
        b_agg = LegBAggregate(pid=p, amount_total=b_total_for_p);
        parent +>:HasLegAAggregate(amount_total=a_total_for_p):+> a_agg;
        parent +>:HasLegBAggregate(amount_total=b_total_for_p):+> b_agg;

        root ++> parent;
    }

    # Run the slow (fanned) plan across every parent.
    slow_a = 0.0;
    slow_b = 0.0;
    for p_node in [-->] {
        if p_node.type_info.name == "Parent" {
            sw = SlowPlanWalker();
            p_node spawn sw;
            slow_a = slow_a + sw.a_total;
            slow_b = slow_b + sw.b_total;
        }
    }

    # Run the fast (pre-aggregated) plan across every parent.
    fast_a = 0.0;
    fast_b = 0.0;
    for p_node in [-->] {
        if p_node.type_info.name == "Parent" {
            fw = FastPlanWalker();
            p_node spawn fw;
            fast_a = fast_a + fw.a_total;
            fast_b = fast_b + fw.b_total;
        }
    }

    # Reachability sanity-check on the first parent.
    first_parent = [-->][0];
    rc = ReachabilityChecker();
    first_parent spawn rc;

    print(f"expected  a_total={expected_a_total}  b_total={expected_b_total}");
    print(f"slow plan a_total={slow_a}  b_total={slow_b}");
    print(f"fast plan a_total={fast_a}  b_total={fast_b}");
    print(f"reachability: via_a={rc.reachable_via_a}  via_b={rc.reachable_via_b}");
}

