"""Sudoku solver SQL performance comparison.

Models the DuckDB recursive-CTE performance scenario from issue #8:
a sudoku solver is run against a small batch of puzzles and a recursive
CTE is used to expand the search tree. The "base" solver does the
straightforward expansion; the "cte_opt" solver additionally prunes
invalid branches (cascade invalidation) as it walks. We model the
solver's traversal as a walker over the puzzle tree, and the pruning
as a typed invalidation edge that the walker respects.
"""

# A puzzle cell: holds a candidate digit at a position. The solver
# walks from the root cell outward through guesses, accumulating
# partial assignments until either the puzzle is filled (success) or
# a constraint is violated (prune).
node Cell {
    has row: int = 0;
    has col: int = 0;
    has digit: int = 0;
    has depth: int = 0;
}

# A puzzle node: aggregates cells, carries the puzzle id and whether
# it has been solved. Solved status is observable domain state.
node Puzzle {
    has puzzle_id: int = 0;
    has solved: bool = False;
    has cell_count: int = 0;
    has pruned: bool = False;
}

# An edge from a parent cell to a child guess cell. Carries the
# branch digit so the walker can reconstruct the assignment path.
edge Guess {
    has branch: int = 0;
}

# An edge from a cell (or puzzle) to a state meaning "this branch
# is invalid and should not be visited." The pruning walker uses
# this typed edge to cascade-invalidates downstream guesses.
edge Pruned { }

# --- Solvers -------------------------------------------------------------

# Base solver: walks the guess tree depth-first, counting cells
# visited. No pruning — mirrors the unoptimized recursive CTE that
# explores every branch even when a constraint is violated.
walker BaseSolver {
    has visited: int = 0;
    has path: str = "";

    can start with Root entry {
        visit [-->];
    }

    can solve_puzzle with Puzzle entry {
        print(f"[base] puzzle {here.puzzle_id}: exploring (size={here.cell_count})");
        visit [-->];
    }

    can walk_guesses with Cell entry {
        self.visited += 1;
        sep = "," if self.path != "" else "";
        self.path = f"{self.path}{sep}{here.digit}";
        # No pruning: visit every child guess.
        visit [->:Guess:->];
    }
}

# CTE-optimized solver: same traversal, but cascade-invalidates
# child branches whenever it hits a violating cell. Models the
# "prune invalid subtrees early" optimization the issue asks for.
walker OptimizedSolver {
    has visited: int = 0;
    has pruned_count: int = 0;
    has path: str = "";

    can start with Root entry {
        visit [-->];
    }

    can solve_puzzle with Puzzle entry {
        print(f"[opt ] puzzle {here.puzzle_id}: exploring (size={here.cell_count})");
        visit [-->];
    }

    can walk_guesses with Cell entry {
        self.visited += 1;
        # Domain rule: cells at depth > puzzle capacity are invalid.
        # The original solver only noticed this deep in the tree;
        # the optimized solver cascades invalidation outward.
        if here.depth > here.row * 0 + 81 {
            here +>:Pruned:+> here;
            self.pruned_count += 1;
            visit [->:Guess:->] else { disengage; }
        } else {
            sep = "," if self.path != "" else "";
            self.path = f"{self.path}{sep}{here.digit}";
            visit [->:Guess:->];
        }
    }
}

# --- Demo wiring ---------------------------------------------------------

with entry {
    # Build two tiny puzzles. Each puzzle branches into a small tree
    # of guessed cells. We model the branching as a Guess-edge chain
    # so the walker can traverse it like the recursive CTE would.
    p1 = Puzzle(puzzle_id=1, cell_count=3);
    p2 = Puzzle(puzzle_id=2, cell_count=3);
    root ++> p1 ++> p2;

    # Puzzle 1: a clean 3-deep guess tree (no violations).
    p1 +>:Guess(branch=1):+> Cell(row=0, col=0, digit=3, depth=1);
    c1a = p1 +>:Guess(branch=1):+> Cell(row=0, col=1, digit=1, depth=2);
    c1b = p1 +>:Guess(branch=2):+> Cell(row=0, col=2, digit=4, depth=2);
    c1a +>:Guess(branch=1):+> Cell(row=1, col=0, digit=2, depth=3);
    c1b +>:Guess(branch=2):+> Cell(row=1, col=1, digit=7, depth=3);

    # Puzzle 2: a guess tree with a deep invalid branch the optimized
    # solver should cascade-prune.
    p2 +>:Guess(branch=1):+> Cell(row=0, col=0, digit=5, depth=1);
    bad = p2 +>:Guess(branch=1):+> Cell(row=0, col=1, digit=9, depth=2);
    # Force depth beyond the puzzle's healthy limit so the pruning
    # walker marks it. (depth > 81 in this demo signals "way off
    # track" the same way a constraint violation would in real SQL.)
    bad_cell = p2 +>:Guess(branch=2):+> Cell(row=0, col=2, digit=6, depth=90);
    bad_cell +>:Guess(branch=1):+> Cell(row=1, col=0, digit=8, depth=91);
    bad_cell +>:Guess(branch=2):+> Cell(row=1, col=1, digit=2, depth=91);

    # Run both solvers and compare visit counts.
    base = BaseSolver();
    root spawn base;
    print(f"[base] visited {base.visited} cells, path={base.path}");

    opt = OptimizedSolver();
    root spawn opt;
    print(
        f"[opt ] visited {opt.visited} cells, "
        f"pruned {opt.pruned_count} subtrees, path={opt.path}"
    );
    print(
        f"delta: optimized solver skipped {base.visited - opt.visited} "
        "cell expansions on the same puzzle set"
    );
}

