"""Regression tests for the sudoku cascade walker.

The program models a sudoku constraint graph (Board / Row / Column / Box
nodes, Cell nodes joined by InRow/InCol/InBox membership edges and Peers
relationships, plus Digit nodes linked by Holds edges). The Cascade
walker walks the graph, printing the Board name and chasing the
membership / peer edges.

These tests exercise the *structure* the walker depends on: the typed
edges that define rows, columns, boxes, peer relationships, and the
digit holds, plus the cascade walker's traversal behavior on a minimal
graph. Each test builds its own graph so they are order-independent.
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Test 1: The demo Board, Row, Column, Box chain is wired up under root.
#         The walker needs this base graph to even reach a Board.
# ---------------------------------------------------------------------------
test "demo graph wires board under root" {
    root ++> Board(name="Sudoku #1");
    boards = [root -->][?:Board];
    assert len(boards) == 1, f"expected 1 board under root, got {len(boards)}";
    assert boards[0].name == "Sudoku #1", f"unexpected name: {boards[0].name}";
}

# ---------------------------------------------------------------------------
# Test 2: InRow / InCol / InBox membership edges carry the slot index and
#         connect the right unit to the right Cell.
# ---------------------------------------------------------------------------
test "membership edges carry slot index" {
    r = Row(index=0);
    c0 = Column(index=0);
    bx = Box(index=0);
    root ++> r ++> c0 ++> bx;

    cell00 = Cell(row=0, col=0, candidates=9);
    cell01 = Cell(row=0, col=1, candidates=9);
    r +>:InRow(slot=0):+> cell00;
    r +>:InRow(slot=1):+> cell01;
    c0 +>:InCol(slot=0):+> cell00;
    bx +>:InBox(slot=0):+> cell00;
    bx +>:InBox(slot=1):+> cell01;

    row_targets = [r ->:InRow:->];
    assert len(row_targets) == 2, f"row should hold 2 cells, got {len(row_targets)}";
    assert cell00 in row_targets, "cell00 missing from row";
    assert cell01 in row_targets, "cell01 missing from row";

    col_targets = [c0 ->:InCol:->];
    assert len(col_targets) == 1, f"col should hold 1 cell, got {len(col_targets)}";
    assert col_targets[0] is cell00, "col target is not cell00";

    box_targets = [bx ->:InBox:->];
    assert len(box_targets) == 2, f"box should hold 2 cells, got {len(box_targets)}";
    assert cell00 in box_targets, "cell00 missing from box";
    assert cell01 in box_targets, "cell01 missing from box";
}

# ---------------------------------------------------------------------------
# Test 3: The Peers edges are bidirectional between cells of the same unit.
#         The Cascade walker relies on `->:Peers:->` to fan out across the
#         constraint graph; both directions must exist.
# ---------------------------------------------------------------------------
test "peer edges are bidirectional between cells" {
    a = Cell(row=0, col=0, candidates=9);
    b = Cell(row=0, col=1, candidates=9);
    c = Cell(row=1, col=0, candidates=9);
    root ++> a ++> b ++> c;

    a +>:Peers:+> b;
    b +>:Peers:+> a;
    a +>:Peers:+> c;
    c +>:Peers:+> a;

    a_peers = [a ->:Peers:->];
    assert len(a_peers) == 2, f"a should have 2 peers, got {len(a_peers)}";
    assert b in a_peers, "b missing from a's peers";
    assert c in a_peers, "c missing from a's peers";

    b_peers = [b ->:Peers:->];
    assert len(b_peers) == 1, f"b should have 1 peer, got {len(b_peers)}";
    assert b_peers[0] is a, "b's only peer should be a";

    c_peers = [c ->:Peers:->];
    assert len(c_peers) == 1, f"c should have 1 peer, got {len(c_peers)}";
    assert c_peers[0] is a, "c's only peer should be a";
}

# ---------------------------------------------------------------------------
# Test 4: Holds edges carry the placed digit from a Cell to a Digit node,
#         and there is exactly one Holds edge per placed cell.
# ---------------------------------------------------------------------------
test "holds edges carry digit value" {
    cell = Cell(row=0, col=0, candidates=1, solved=True);
    d = Digit(value=7);
    root ++> cell ++> d;
    cell +>:Holds(digit=7):+> d;

    held = [cell ->:Holds:->];
    assert len(held) == 1, f"cell should hold exactly 1 digit, got {len(held)}";
    assert held[0] is d, "holds target is not the digit node";
    assert held[0].value == 7, f"digit value should be 7, got {held[0].value}";

    place_edges = [cell ->:Holds:->];
    edge_objs = [cell ->:Holds:->];
    assert len(edge_objs) == 1, "expected exactly one Holds edge";
}

# ---------------------------------------------------------------------------
# Test 5: Spawning Cascade on a Board subgraph prints the board name and
#         reaches the Holds-linked digits (the begin_board -> visit [->:Holds:->]
#         -> drop_digit path). This is the cascade the issue describes: the
#         walker must traverse Board -> Holds -> Digit, then walk Peers from
#         each Digit back out across the constraint graph.
# ---------------------------------------------------------------------------
test "cascade walker prints board name and traverses holds" {
    bx = Box(index=0);
    cell = Cell(row=0, col=0, candidates=1, solved=True);
    d = Digit(value=4);

    board = Board(name="Mini");
    root ++> board ++> bx;
    bx +>:InBox(slot=0):+> cell;
    cell +>:Holds(digit=4):+> d;
    cell +>:Peers:+> bx;
    bx +>:Peers:+> cell;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = board spawn Cascade(placed=0, depth_limit=5);
    }
    out = buf.getvalue();
    assert "Board: Mini" in out, f"missing Board header in output: {out!r}";
    # The walker has 'placed' as a has field; after running it should still
    # be an int (the walker itself doesn't mutate placed in this minimal graph,
    # but the field must exist and be readable).
    assert isinstance(res.placed, int), f"placed should be int, got {type(res.placed)}";
    assert res.depth_limit == 5, f"depth_limit should be 5, got {res.depth_limit}";
}

