        for layer_idx in range(self.target_layers) {
            if layer_idx % 2 == 0 {
                # Non-empty layer: monotonic offsets + neighbor values.
                offs = [0, 2, 5, 9];
                vals = [11, 22, 33, 44, 55, 66, 77, 88, 99];
                pad = 0;
            } else {
                # Empty layer: equal adjacent offsets, no values.
                offs = [0, 0, 0, 0];
                vals = [];
                pad = 4;
            }
            offsets_per_layer.append(offs);
            values_per_layer.append(vals);
            offsets_bytes.append(len(offs) * 4);
            values_bytes.append(len(vals) * 4);
            padding_bytes.append(pad);
        }

        col = LayeredColumn(
            column_name=f"col_{here.node_id}",
            layer_count=self.target_layers,
            total_rows=total_rows,
            layer_offsets=offsets_per_layer,
            layer_values=values_per_layer,
            offsets_bytes=offsets_bytes,
            values_bytes=values_bytes,
            padding_bytes=padding_bytes,
            certified=True
        );
        here +>:AdjacencyRef:+> col;
        visit [-->];
    }
}

