walker Auditor {
    can start with Root entry {
        visit [-->];
    }

    can audit with LayeredColumn entry {
        layer_total = len(here.layer_offsets);
        if layer_total != here.layer_count {
            print(f"[Auditor] FAIL {here.column_name}: layer_count="
                  f"{here.layer_count} vs arrays={layer_total}");
            here.certified = False;
            return;
        }
        for layer_idx in range(layer_total) {
            offs = here.layer_offsets[layer_idx];
            # Empty-layer encoding: all offsets equal.
            if len(offs) >= 2 and offs[0] == offs[1] {
                print(f"[Auditor] layer {layer_idx}: EMPTY (equal offsets)");
                continue;
            }
            monotonic_ok = True;
            for i in range(1, len(offs)) {
                if offs[i] < offs[i - 1] {
                    monotonic_ok = False;
                }
            }
            label = "OK" if monotonic_ok else "FAIL";
            print(f"[Auditor] layer {layer_idx}: {label} offsets={offs}");
            if not monotonic_ok {
                here.certified = False;
            }
        }
        visit [-->];
    }
}

# ---------------------- Upper-layer greedy consumer ------------------------

walker Consumer {
    has start_node: str = "";

    can start with Root entry {
        print(f"[Consumer] start={self.start_node}");
        visit [-->];
    }

    can pick_start with GraphNode entry {
        if self.start_node == "" or here.node_id == self.start_node {
            visit [->:AdjacencyRef:->];
        } else {
            visit [-->];
