    }

    can traverse with LayeredColumn entry {
        if not here.certified {
            print(f"[Consumer] fallback to row-asset decode for {here.column_name}");
            visit [<--];
        }
        # Greedy traversal: walk upper layers first, stop at max layer.
        max_layer = here.layer_count - 1;
        for layer_idx in range(max_layer, -1, -1) {
            offs = here.layer_offsets[layer_idx];
            if len(offs) >= 2 and offs[0] == offs[1] {
                # Empty layer — skip, do not decode.
                continue;
            }
            vals = here.layer_values[layer_idx];
            sample_count = min(3, len(vals));
            sample = vals[0:sample_count];
            print(f"[Consumer] layer {layer_idx}: "
                  f"neighbors(first {sample_count})={sample}");
        }
        visit [<--];
    }
}

