    g0 = GraphNode(node_id="shard-A", hnsw_level=3, layer_count=3);
    g1 = GraphNode(node_id="shard-B", hnsw_level=2, layer_count=3);
    g2 = GraphNode(node_id="shard-C", hnsw_level=1, layer_count=3);
    root ++> g0 ++> g1 ++> g2;

    # Writer emits certified offsets-list sources for every graph node.
    root spawn Writer(target_layers=3);

    # Auditor validates layer_count, monotonic offsets, empty-layer encoding.
    root spawn Auditor();

    # Consumer performs upper-layer greedy traversal w/ row-asset fallback.
    root spawn Consumer(start_node="shard-B");
}

