"""Tests for layered adjacency graph auditor and cascade.

Covers the issue #1920 promises:
  * empty layers are accepted via equal offsets (single [0])
  * multi-layer graphs report every layer exactly once
  * corrupt layers are flagged BAD with detail
  * cascade deletes every layer under a graph
  * auditor surfaces declared layer count and graph name
"""

import io;
import from contextlib { redirect_stdout }

test "empty layer is OK via equal offsets" {
    root ++> Graph(name="g_empty", layer_count=1);
    g = [root -->][0];
    l0 = Layer(
        layer_index=0,
        row_count=0,
        offsets=[0],
        values=[],
    );
    g +>:Adjacency(label="layer_0"):+> l0;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
    out = buf.getvalue();

    assert "auditing graph 'g_empty'" in out, f"missing audit header: {out}";
    assert "[OK] layer=0" in out, f"empty layer should be OK: {out}";
    assert res.seen_layers == 1, f"expected 1 layer seen, got {res.seen_layers}";
    assert len(res.bad_layers) == 0, f"empty layer must not be bad: {res.bad_layers}";
}

test "multi-layer graph reports every layer" {
    root ++> Graph(name="g_multi", layer_count=3);
    g = [root -->][0];

    l0 = Layer(layer_index=0, row_count=3, offsets=[0, 1, 2, 3], values=[10, 20, 30]);
    l1 = Layer(layer_index=1, row_count=0, offsets=[0], values=[]);
    l2 = Layer(layer_index=2, row_count=2, offsets=[0, 2, 2], values=[5, 9], checksum_ok=True);

    g +>:Adjacency(label="layer_0"):+> l0;
    g +>:Adjacency(label="layer_1"):+> l1;
    g +>:Adjacency(label="layer_2"):+> l2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
    out = buf.getvalue();

    assert res.graph_name == "g_multi", f"graph name not captured: {res.graph_name}";
    assert res.declared_layers == 3, f"declared layer count not 3: {res.declared_layers}";
    assert res.seen_layers == 3, f"expected 3 layers audited, got {res.seen_layers}";
    assert "[OK] layer=0" in out, f"layer 0 status missing: {out}";
    assert "[OK] layer=1" in out, f"layer 1 status missing: {out}";
    assert "[OK] layer=2" in out, f"layer 2 status missing: {out}";
    assert len(res.bad_layers) == 0, f"healthy graph should have no bad layers: {res.bad_layers}";
}

test "corrupt layer is reported as BAD with detail" {
    root ++> Graph(name="g_corrupt", layer_count=1);
    g = [root -->][0];
    l0 = Layer(
        layer_index=0,
        row_count=2,
        offsets=[0, 2, 1],
        values=[7, 7],
        checksum_ok=False,
    );
    g +>:Adjacency(label="layer_0"):+> l0;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
    out = buf.getvalue();

    assert "[BAD] layer=0" in out, f"corruption must be flagged BAD: {out}";
    assert res.seen_layers == 1, f"expected 1 layer visited, got {res.seen_layers}";
    assert len(res.bad_layers) == 1, f"expected exactly 1 bad layer, got {res.bad_layers}";
    bad = res.bad_layers[0];
    assert "layer 0" in bad, f"bad-layer detail missing index: {bad}";
    assert "monotonic=False" in bad, f"bad-layer detail should report non-monotonic: {bad}";
}

test "cascade deletes every layer under the graph" {
    root ++> Graph(name="g_cascade", layer_count=2);
    g = [root -->][0];

    l0 = Layer(layer_index=0, row_count=2, offsets=[0, 1, 2], values=[1, 2]);
    l1 = Layer(layer_index=1, row_count=0, offsets=[0], values=[]);

    g +>:Adjacency(label="layer_0"):+> l0;
    g +>:Adjacency(label="layer_1"):+> l1;

    assert len([g ->:Adjacency:->]) == 2, "graph should start with 2 layers";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Cascade();
    }
    out = buf.getvalue();

    assert "cascade: invalidating graph g_cascade" in out, f"missing cascade start: {out}";
    assert res.dropped == 2, f"cascade should drop 2 layers, got {res.dropped}";
    remaining = [g ->:Adjacency:->];
    assert len(remaining) == 0, f"all layers should be gone, left: {remaining}";
}

test "auditor reports declared layer count and graph name" {
    root ++> Graph(name="g_meta", layer_count=4);
    g = [root -->][0];
    # Only 2 layers actually present; declared count is 4.
    l0 = Layer(layer_index=0, row_count=1, offsets=[0, 1], values=[42]);
    l1 = Layer(layer_index=1, row_count=0, offsets=[0], values=[]);
    g +>:Adjacency(label="layer_0"):+> l0;
    g +>:Adjacency(label="layer_1"):+> l1;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
    out = buf.getvalue();

    assert "auditing graph 'g_meta'" in out, f"missing graph name in header: {out}";
    assert "declared layers=4" in out, f"missing declared layer count: {out}";
    assert res.graph_name == "g_meta", f"walker graph_name wrong: {res.graph_name}";
    assert res.declared_layers == 4, f"walker declared_layers wrong: {res.declared_layers}";
    assert res.seen_layers == 2, f"seen should equal actual layers (2), got {res.seen_layers}";
}

