# ----- Node archetypes -----------------------------------------------------

node Module {
    has name: str = "";
    has artifact_id: str = "";
    has local_ok: bool = False;
    has remote_ok: bool = False;

    def is_resolved() -> bool {
        return self.local_ok or self.remote_ok;
