walker RecursionTracer {
    has max_depth: int = 10;
    has visited: list[int] = [];

    can start with Root entry {
        print("Call tree:");
        print("factorial(4)");
        visit [-->];
    }

    # Walk the call hierarchy through Invokes edges, recording frame state.
    can trace with Call entry {
        if here.call_id in self.visited {
            visit [-->];
            return;
        }
        self.visited.append(here.call_id);

        # Depth-limit guard — collapsed frames stay readable.
        if here.depth >= self.max_depth {
            indent = "   " * here.depth;
            print(f"{indent}└─ ... [depth limit reached]");
            disengage;
        }

        indent = "   " * here.depth;
        suffix = f" -> {here.return_value}" if here.status == "returned" else "";
        print(f"{indent}└─ {here.func_name}({here.args}){suffix}");

        # Capture the active stack frame at this point in the traversal.
        self._show_stack_frame(here);
        visit [->:Invokes:->];
    }

    def _show_stack_frame(frame: Call) -> None {
        prefix = "   " * (frame.depth + 1);
        marker = "[ACTIVE]" if frame.active else "       ";
        print(f"{prefix}{marker} depth={frame.depth} "
              f"call={frame.func_name}({frame.args}) "
              f"locals={frame.locals}");
    }
}

# A second walker replays the trace in reverse to demonstrate
# backward step restoration of stack state.
walker BackwardReplay {
    has visited: list[int] = [];

    can start with Root entry {
        print("Backward replay (unwinding the stack):");
        # Walk back over StackFrame edges from leaf to root.
        visit [<--:StackFrame:<--];
    }

    can rewind with Call entry {
        if here.call_id in self.visited {
            visit [<--];
            return;
        }
        self.visited.append(here.call_id);

        indent = "   " * here.depth;
        returned = f" <- returned {here.return_value}" if here.return_value else "";
        print(f"{indent}<- {here.func_name}({here.args}) popped{returned}");
        visit [<--:StackFrame:<--];
    }
}

with entry {
    # Build the factorial(4) call tree:
    #   f4 -> f3 -> f2 -> f1(returns 1)
    #              f2 returns 2
    #         f3 returns 6
    #   f4 returns 24
    f1 = Call(call_id=1, func_name="factorial", depth=3, args="n=1",
              locals="", return_value="1", status="returned");
    f2 = Call(call_id=2, func_name="factorial", depth=2, args="n=2",
              locals="", return_value="2", status="returned");
    f3 = Call(call_id=3, func_name="factorial", depth=1, args="n=3",
              locals="", return_value="6", status="returned");
    f4 = Call(call_id=4, func_name="factorial", depth=0, args="n=4",
              locals="", return_value="24", status="returned", active=True);

    # Wire the call hierarchy via Invokes edges (parent -> child).
    f4 +>:Invokes:+> f3 +>:Invokes:+> f2 +>:Invokes:+> f1;

    # Wire the active stack: f4 is on top, f1 at the bottom.
    # StackFrame edges go from a frame to the frame BELOW it on the stack.
    f4 +>:StackFrame:+> f3 +>:StackFrame:+> f2 +>:StackFrame:+> f1;

    # Wire WaitsFor edges — a caller waits for its callee's return.
    f4 +>:WaitsFor:+> f3;
    f3 +>:WaitsFor:+> f2;
    f2 +>:WaitsFor:+> f1;

    # Attach the whole tree to root so the walker can spawn on it.
    root ++> f4;

    print("=== Forward recursion trace ===");
    root spawn RecursionTracer(max_depth=8);

    print("");
    print("=== Backward replay (stack unwind) ===");
    # Spawn on the leaf to demonstrate walking back up via StackFrame edges.
    f1 spawn BackwardReplay();
}

