            print(f"[DIST]  depth {self.depth}: skip dup {here.name}");
        } else {
            self.seen.append(here.name);
            self.pulled.append(here.name);
            print(f"[DIST]  depth {self.depth}: pulled {here.name}");
        }
        if self.depth < self.max_depth {
            self.depth += 1;
            visit [->:ReportsTo:->] else { disengage; }
        } else {
            disengage;
        }
    }
}

