"""Recursive CTE semantics modeled in Jac.

Demonstrates the gap described in vitess #20903: a recursive CTE declared
UNION DISTINCT but left unmerged (no single-route pushdown) has no
deduplication primitive in the plan, so the engine re-enqueues every
emitted row. On duplicate-free data this is harmless; on data that
reproduces rows it yields wrong multiplicity, and on cyclic data it loops
until a depth limit fires where MySQL would have terminated.

The graph below is a manager chain seeded from an unmerged root and
unfolded by a recursive walker. A distinct walker reports each name once;
an all walker reports every emitted row and re-enqueues every one of
them, mirroring UNION DISTINCT vs UNION ALL semantics.
"""

node Employee {
    has name: str = "";
}

edge ReportsTo {
    has label: str = "reports-to";
}

walker RecurseDistinct {
    """UNION DISTINCT semantics: each row emitted at most once.

    Tracks a guard set of visited node ids to mirror MySQL's
    deduplication of the working table.
    """
    has guard: list[str] = [];
    has max_depth: int = 6;

    can start with Root entry {
        visit [->:ReportsTo:->];
    }

    can step with Employee entry {
        if self.max_depth <= 0 {
            print("DISTINCT  stop (max depth)");
            disengage;
        }
        if here.name not in self.guard {
            self.guard.append(here.name);
            print(f"DISTINCT  emit {here.name}");
            self.max_depth -= 1;
            visit [->:ReportsTo:->];
        } else {
            print(f"DISTINCT  skip {here.name} (already seen)");
        }
    }
}

walker RecurseAll {
    """UNION ALL semantics: every emitted row is appended and re-enqueued.

    No guard set, so a cyclic subtree re-emits the same row forever; the
    walker enforces a depth cap to mirror the VT09030 recursion-limit
    guard the engine uses.
    """
    has max_depth: int = 6;

    can start with Root entry {
        visit [->:ReportsTo:->];
    }

    can step with Employee entry {
        if self.max_depth <= 0 {
            print("ALL       stop (max depth)");
            disengage;
        }
        print(f"ALL       emit {here.name}");
        self.max_depth -= 1;
        visit [->:ReportsTo:->];
    }
}

with entry {
    # Manager chain: alice -> bob -> carol -> dave (a strict hierarchy,
    # duplicate-free) with an extra edge from carol back to alice to
    # create a cycle that MySQL would terminate via DISTINCT.
    alice = Employee(name="alice");
    bob = Employee(name="bob");
    carol = Employee(name="carol");
    dave = Employee(name="dave");

    root +>:ReportsTo:+> alice;
    alice +>:ReportsTo:+> bob;
    bob +>:ReportsTo:+> carol;
    carol +>:ReportsTo:+> dave;
    carol +>:ReportsTo:+> alice;

    print("=== DISTINCT walk (mirrors UNION DISTINCT) ===");
    root spawn RecurseDistinct(max_depth=6);

    print("=== ALL walk (mirrors unmerged UNION DISTINCT bug) ===");
    root spawn RecurseAll(max_depth=6);
}

fixed.jac_tests:
"""Tests for the recursive CTE UNION DISTINCT vs UNION ALL semantics.

The issue (#20903) describes a planner bug where an unmerged recursive
CTE declared UNION DISTINCT executes with UNION ALL semantics, so on
data that re-produces rows you get duplicates, and on cyclic data you
hit the recursion-limit error (VT09030) where MySQL would have
terminated via DISTINCT.

The Jac program models this with two walkers on a manager graph that
contains a cycle (carol -> alice). The DISTINCT walker guards against
re-emitting a name; the ALL walker does not.
"""

import io;
import from contextlib { redirect_stdout }

test "distinct walker emits each name at most once on a cycle" {
    # Cycle: alice -> bob -> carol -> alice. With DISTINCT semantics,
    # alice is emitted once, then bob, then carol, then revisiting alice
    # (via the carol -> alice edge) is skipped. Total three emits.
    alice = Employee(name="alice");
    bob = Employee(name="bob");
    carol = Employee(name="carol");
    root +>:ReportsTo:+> alice;
    alice +>:ReportsTo:+> bob;
    bob +>:ReportsTo:+> carol;
    carol +>:ReportsTo:+> alice;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn RecurseDistinct(max_depth=10);
    }
    out = buf.getvalue();

    emit_lines = [
        line
        for line in out.splitlines()
        if "emit" in line
    ];
    assert len(emit_lines) == 3, f"expected 3 emits, got {len(emit_lines)}: {out}";
    assert "emit alice" in out, f"alice should be emitted: {out}";
    assert "emit bob" in out, f"bob should be emitted: {out}";
    assert "emit carol" in out, f"carol should be emitted: {out}";
    assert "skip alice" in out, f"alice should be skipped on revisit (cycle): {out}";
}

test "all walker re-enqueues cycle rows until depth cap" {
    # Same cyclic graph as above but with UNION ALL semantics: the
    # back-edge carol -> alice re-emits alice, which re-emits bob, which
    # re-emits carol, ... until the max_depth cap fires (mirroring the
    # VT09030 recursion-limit error in the engine).
    alice = Employee(name="alice");
    bob = Employee(name="bob");
    carol = Employee(name="carol");
    root +>:ReportsTo:+> alice;
    alice +>:ReportsTo:+> bob;
    bob +>:ReportsTo:+> carol;
    carol +>:ReportsTo:+> alice;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn RecurseAll(max_depth=4);
    }
    out = buf.getvalue();

    assert "stop (max depth)" in out, f"ALL walker must hit the depth cap: {out}";
    # Each of alice/bob/carol should appear in emit lines at least
    # twice: once from the seed pass, then again after the cycle wraps
    # around. That is the bug: re-enqueueing every emitted row.
    emit_lines = [
        line
        for line in out.splitlines()
        if "emit" in line
    ];
    assert len(emit_lines) > 3, (
        f"ALL walker should re-emit cyclic rows (got {len(emit_lines)} emits): {out}"
    );
}

test "distinct walker terminates cleanly on a long chain without a cycle" {
    # Duplicate-free strict hierarchy: alice -> bob -> carol -> dave.
    # DISTINCT must visit each exactly once and then stop (no more
    # outgoing edges).
    alice = Employee(name="alice");
    bob = Employee(name="bob");
    carol = Employee(name="carol");
    dave = Employee(name="dave");
    root +>:ReportsTo:+> alice;
    alice +>:ReportsTo:+> bob;
    bob +>:ReportsTo:+> carol;
    carol +>:ReportsTo:+> dave;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn RecurseDistinct(max_depth=10);
    }
    out = buf.getvalue();

    emit_lines = [
        line
        for line in out.splitlines()
        if "emit" in line
    ];
    assert len(emit_lines) == 4, f"expected 4 emits, got {len(emit_lines)}: {out}";
    # The guard set on the walker instance is mutated during traversal;
    # verify it contains every name exactly once.
    names_in_guard = res.guard;
    assert sorted(names_in_guard) == ["alice", "bob", "carol", "dave"], (
        f"guard should hold all four names once: {names_in_guard}"
    );
}

test "all walker emits each row only once on a duplicate-free chain" {
    # Same strict hierarchy, no cycle. UNION ALL is harmless here: each
    # row is emitted exactly once. This guards the test set so a fix that
    # overcorrects (e.g. always terminating after one emit) would still
    # pass the cyclic tests above but break this one.
    alice = Employee(name="alice");
    bob = Employee(name="bob");
    carol = Employee(name="carol");
    dave = Employee(name="dave");
    root +>:ReportsTo:+> alice;
    alice +>:ReportsTo:+> bob;
    bob +>:ReportsTo:+> carol;
    carol +>:ReportsTo:+> dave;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn RecurseAll(max_depth=10);
    }
    out = buf.getvalue();

    emit_lines = [
        line
        for line in out.splitlines()
        if "emit" in line
    ];
    assert len(emit_lines) == 4, f"expected 4 emits on a cycle-free chain, got {len(emit_lines)}: {out}";
    assert "stop (max depth)" not in out, (
        f"ALL walker must not hit the depth cap on a finite chain: {out}"
    );
}

test "distinct and all diverge specifically on the cycle" {
    # Same cyclic graph, both walkers. The DISTINCT walk produces
    # strictly fewer emits than the ALL walk -- that gap is the bug
    # described in #20903.
    alice = Employee(name="alice");
    bob = Employee(name="bob");
    carol = Employee(name="carol");
    root +>:ReportsTo:+> alice;
    alice +>:ReportsTo:+> bob;
    bob +>:ReportsTo:+> carol;
    carol +>:ReportsTo:+> alice;

    buf_d = io.StringIO();
    with redirect_stdout(buf_d) {
        root spawn RecurseDistinct(max_depth=10);
    }
    out_d = buf_d.getvalue();
    distinct_emits = sum(1 for line in out_d.splitlines() if "emit" in line);

    buf_a = io.StringIO();
    with redirect_stdout(buf_a) {
        root spawn RecurseAll(max_depth=4);
    }
    out_a = buf_a.getvalue();
    all_emits = sum(1 for line in out_a.splitlines() if "emit" in line);

    assert distinct_emits == 3, f"DISTINCT should emit 3 on the cycle, got {distinct_emits}: {out_d}";
    assert all_emits > distinct_emits, (
        f"ALL emits ({all_emits}) must exceed DISTINCT emits ({distinct_emits}) on the cycle -- "
        f"that gap is the #20903 bug"
    );
    assert "stop (max depth)" in out_a, (
        f"ALL walker must hit depth cap (VT09030 analogue) on cycle: {out_a}"
    );
}

