"""Auto-mutation evaluation coordinator.

Models the core scenario from issue #425: a coordinator that walks
approved candidates through analysis, mutation, tiered evaluation,
publication, rollback, and evidence-driven replanning. The graph
relationships (Candidates belong to Plans, Candidates carry Mutation
records, Evaluations and Rollback events form a lineage trail) are
expressed as typed edges, and walker traversal replaces the hand-rolled
recursion/queue machinery of the original.
"""

# ---------- Entity archetypes ----------

node Plan {
    has title: str = "";
    has budget: int = 100;
}

node Candidate {
    has name: str = "";
    has status: str = "pending";   # pending | analyzed | mutated | evaluated | promoted | rolled_back
    has approved: bool = False;
}

node Mutation {
    has kind: str = "";
    has reversible: bool = True;
}

node Evaluation {
    has tier: str = "";            # cheap | standard | full
    has score: float = 0.0;
    has passes_hard: bool = False;
}

node Rollback {
    has reason: str = "";
}

node Artifact {
    has label: str = "";
    has published: bool = False;
}

# ---------- Relationship archetypes ----------

edge Owns { }
edge Carries { }
edge EvaluatedBy { }
edge RollbackOf { }
edge Publishes { }

# ---------- Walker: Coordinator ----------

walker Coordinator {
    has report: list[str] = [];
    has visited: list[str] = [];

    can begin with Root entry {
        # Step into the plan frontier.
        visit [-->];
    }

    can drive with Plan entry {
        if here.title not in self.visited {
            self.visited.append(here.title);
            self.report.append(f"plan:{here.title} budget={here.budget}");
        }
        # Walk owned candidates, mutations, evaluations, rollbacks, artifacts.
        visit [->:Owns:->];
    }

    can audit with Candidate entry {
        if here.name not in self.visited {
            self.visited.append(here.name);
            self.report.append(f"candidate:{here.name} status={here.status} approved={here.approved}");
        }
        visit [->:Carries:->];
        visit [->:EvaluatedBy:->];
        visit [->:RollbackOf:->];
    }

    can log_mutation with Mutation entry {
        self.report.append(f"  mutation kind={here.kind} reversible={here.reversible}");
        visit [-->];
    }

    can log_eval with Evaluation entry {
        outcome = "PASS" if here.passes_hard else "FAIL";
        self.report.append(f"  eval tier={here.tier} score={here.score} -> {outcome}");
        visit [-->];
    }

    can log_rollback with Rollback entry {
        self.report.append(f"  rollback reason={here.reason}");
        visit [-->];
    }

    can log_artifact with Artifact entry {
        pub = "PUBLISHED" if here.published else "DRAFT";
        self.report.append(f"  artifact {here.label} -> {pub}");
        visit [-->];
    }
}

# ---------- Walker: Promotion gate ----------
# Walks Plan -> Candidate via Owns, asserts the hard-constraint passes,
# then publishes the artifact. Demonstrates cycle-safe traversal with a
# visited-set guard (Jac 0.36.1 walkers have no built-in dedupe).

walker Promoter {
    has blocked: list[str] = [];
    has promoted: list[str] = [];

    can begin with Root entry {
        visit [-->];
    }

    can inspect with Plan entry {
        visit [->:Owns:->];
    }

    can decide with Candidate entry {
        if here.approved and here.status == "evaluated" {
            # Read its evaluation via the typed edge; promote only on pass.
            for ev in [->:EvaluatedBy:->] {
                if ev.passes_hard {
                    here.status = "promoted";
                    self.promoted.append(here.name);
                } else {
                    here.status = "rolled_back";
                    self.blocked.append(here.name);
                }
            }
        } else {
            here.status = "rolled_back";
            self.blocked.append(here.name);
        }
        visit [-->];
    }
}

