node ApprovedField {
    has semantic_id: str = "";
    has label: str = "";
    has available: bool = True;
}

node Donor {
    has name: str = "";

    def summary() -> str {
        return self.name;
    }
}

node Gift {
    has amount: float = 0.0;

    def summary() -> str {
        return f"${self.amount}";
    }
}

edge NamedRole {
    has role: str = "";
    has cardinality: str = "exactly_one";
}

edge GiftLine {
    has order_idx: int = 0;
}

walker FactsBuilder {
    has visited: list = [];

    can start with Root entry {
        visit [-->];
    }

    can build with Donor entry {
        if here in self.visited {
            disengage;
        }
        self.visited.append(here);
        print(f"Facts root subject: donor {here.name}");
        visit [->:NamedRole:->];
    }

    can collect_role with ApprovedField entry {
        if not here.available {
            disengage;
        }
        print(f"  field {here.semantic_id} ({here.label}) available");
    }
}

