"""Performance CI workflow model: Monte Carlo timing harness over perf-marked tests.

Models the spec-kitty issue's core scenario: a dedicated, out-of-band
performance-test workflow that runs perf-marked tests N times and aggregates
execution time with a weighted-average / percentile signal, alerting against
regression rather than a single-shot budget. The two perf-marked tests
(`test_shipped_profile_load_time`, `test_doctor_doctrine_json_completes_under_two_seconds`)
are modeled as ``PerfTest`` nodes, the CI workflow is a walker that traverses
``Targets`` and ``Runs`` edges, and the regression policy is explicit domain
logic (not scaffolding).
"""

node PerfTest {
    has name: str = "";
    has hard_budget_s: float = 0.0;
    has warm_samples: list[float] = [];
}

node ProfileLoad {
    has name: str = "";
    has warm_samples: list[float] = [];

    def avg() -> float {
        total = 0.0;
        for s in self.warm_samples { total += s; }
        return total / len(self.warm_samples) if len(self.warm_samples) > 0 else 0.0;
    }
}

node DoctorDoctrineJson {
    has name: str = "";
    has warm_samples: list[float] = [];

    def avg() -> float {
        total = 0.0;
        for s in self.warm_samples { total += s; }
        return total / len(self.warm_samples) if len(self.warm_samples) > 0 else 0.0;
    }
}

edge Targets {
    has priority: int = 0;
}

edge Runs {
    has n_trials: int = 0;
    has weighted_avg_s: float = 0.0;
    has p95_s: float = 0.0;
    has alert: bool = False;
}

node PerfBaseline {
    has name: str = "";
    has baseline_avg_s: float = 0.0;
    has regression_pct: float = 50.0;
}

walker PerfRunner {
    has measured: dict[str, float] = {};
    has n_trials: int = 5;
    has visited: list[str] = [];

    can start with Root entry {
        visit [->:Targets:->];
    }

    can collect with ProfileLoad | DoctorDoctrineJson entry {
        kind = "profile_load" if isinstance(here, ProfileLoad) else "doctor_json";
        if kind in self.visited { disengage; }
        self.visited.append(kind);

        samples = here.warm_samples;
        n = self.n_trials;
        trials: list[float] = [];
        i = 0;
        while i < n {
            idx = i % len(samples);
            trials.append(samples[idx]);
            i += 1;
        }

        total = 0.0;
        for t in trials { total += t; }
        weighted_avg = total / len(trials) if len(trials) > 0 else 0.0;

        sorted_t = sorted(trials);
        p95_idx = int(len(sorted_t) * 0.95) - 1;
        if p95_idx < 0 { p95_idx = 0; }
        if p95_idx >= len(sorted_t) { p95_idx = len(sorted_t) - 1; }
        p95 = sorted_t[p95_idx];

        here +>:Runs(n_trials=n, weighted_avg_s=weighted_avg, p95_s=p95):+> PerfBaseline(
            name=here.name,
            baseline_avg_s=weighted_avg,
            regression_pct=50.0
        );

        self.measured[here.name] = weighted_avg;

        visit [->:Runs:->];
    }

    can report with PerfBaseline entry {
        verdict = "OK";
        if here.baseline_avg_s >= 2.0 {
            verdict = "REGRESSION";
        }
        print(
            f"[{verdict}] {here.name}: weighted_avg={here.baseline_avg_s:.3f}s"
        );
        visit [-->] else { disengage; };
    }
}

walker PerfAuditor {
    can start with Root entry {
        print("=== Out-of-band performance CI workflow (Monte Carlo) ===");
        print(f"SPEC_KITTY_RUN_PERFORMANCE=1, trials=5, policy=weighted_avg+p95");
        visit [->:Targets:->];
