    has title: str = "";
    has bytes: str = "";
}

node ReferenceDef {
    has label: str = "";
    has url: str = "";
    has title: str = "";
}

node Heading {
    has text: str = "";
    has level: int = 0;
    has slug: str = "";
}

node InlineSpan {
    has kind: str = "";
    has run: str = "";
    has repeats: int = 0;
}

node ParsedBlock {
    has kind: str = "";
    has ordinal: int = 0;
}

edge Contains { has order: int = 0; }

walker MarkdownAuditor {
    has seen_labels: list[str] = [];
    has seen_slugs: list[str] = [];
    has failures: int = 0;

    can start with Root entry {
        print("Auditing Markdown graph from root");
        visit [-->];
