    can audit_doc with MarkdownDocument entry {
        print(f"document: '{here.title}' ({len(here.bytes)} bytes)");
        visit [->:Contains:->];
    }

    can audit_block with ParsedBlock entry {
        print(f"  block[{here.ordinal}] kind={here.kind}");
        visit [->:Contains:->];
    }

    can audit_refs with ReferenceDef entry {
        already = False;
        for lbl in self.seen_labels {
            if lbl == here.label {
                already = True;
            }
        }
        if already {
            print(f"  DUPLICATE reference: {here.label}");
            self.failures = self.failures + 1;
        } else {
            self.seen_labels.append(here.label);
            print(f"  ref[{here.label}] -> {here.url}");
        }
    }

    can audit_heading with Heading entry {
        slug = here.text.lower().replace(" ", "-");
        collide = False;
        for s in self.seen_slugs {
            if s == slug {
                collide = True;
            }
        }
        if collide {
            print(f"  COLLIDING slug: {slug}");
            self.failures = self.failures + 1;
        } else {
            self.seen_slugs.append(slug);
            print(f"  heading h{here.level}: {here.text} -> #{slug}");
        }
    }

    can audit_inline with InlineSpan entry {
        if here.repeats > 32 {
            print(f"  QUADRATIC inline: {here.kind} x{here.repeats}");
            self.failures = self.failures + 1;
        } else {
