"""Schema-prefixed ancestors/descendants traversal demo.

Models the arbor issue: a tree of structs in different schemas (prefixes),
where ancestors and descendants must be looked up within the *same* schema
as the seed struct. The walker filters by prefix on each Struct entry so it
stays inside one schema's tree, and enforces a depth cap (the original
Elixir defaulted to depth = 2_147_483_647).
"""

# ---------- Node archetypes ----------

node Struct {
    has name: str = "";
    has prefix: str = "public";
    has primary_key: int = 0;
    has depth_from_root: int = 0;
    has alive: bool = True;

    def id() -> int {
        return self.primary_key;
    }

    def schema() -> str {
        return self.prefix;
    }
}

node Config {
    has max_depth: int = 3;
}

# ---------- Edge archetypes ----------

edge ParentLink {
    has via_fk: int = 0;
}

edge ChildLink {
    has via_fk: int = 0;
}

edge CrossSchema {
    has reason: str = "different prefix";
}

# ---------- Walkers ----------

walker AncestorFinder {
    has target_id: int = 0;
    has schema_name: str = "public";
    has max_depth: int = 8;
    has seen: list[int] = [];
    has ancestors: list[tuple[int, str]] = [];

    can start with Root entry {
        visit [-->];
    }

    can ascend with Struct entry {
        my_id = here.id();
        my_schema = here.schema();
        if my_schema != self.schema_name {
            return;
        }
        if here.depth_from_root >= self.max_depth {
            return;
        }
        if my_id in self.seen {
            disengage;
        }
        self.seen.append(my_id);
        self.ancestors.append((my_id, here.name));
        visit [->:ParentLink:->];
    }
}

walker DescendantFinder {
    has seed_id: int = 0;
    has schema_name: str = "public";
    has max_depth: int = 8;
    has seen: list[int] = [];
    has descendants: list[tuple[int, str]] = [];

    can start with Root entry {
        visit [-->];
    }

    can descend with Struct entry {
        my_id = here.id();
        my_schema = here.schema();
        if my_schema != self.schema_name {
            return;
        }
        if here.depth_from_root > self.max_depth {
            return;
        }
        if my_id in self.seen {
            disengage;
        }
        self.seen.append(my_id);
        self.descendants.append((my_id, here.name));
        visit [->:ChildLink:->];
    }
}

walker CascadeInvalidator {
    has schema_name: str = "public";
    has invalidated: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can mark_phase with Struct entry {
        if here.schema() != self.schema_name {
            return;
        }
        if not here.alive {
            return;
        }
        here.alive = False;
        self.invalidated.append(here.name);
        visit [->:ChildLink:->];
    }
}

# ---------- Demo wiring ----------

with entry {
    cfg = Config(max_depth=3);

    # Public schema tree: p_root -> p_mid -> p_leaf
    p_root = Struct(name="public_root", prefix="public", primary_key=1, depth_from_root=0);
    p_mid = Struct(name="public_mid", prefix="public", primary_key=2, depth_from_root=1);
    p_leaf = Struct(name="public_leaf", prefix="public", primary_key=3, depth_from_root=2);

    # Audit schema tree: a_root -> a_mid -> a_leaf
    a_root = Struct(name="audit_root", prefix="audit", primary_key=10, depth_from_root=0);
    a_mid = Struct(name="audit_mid", prefix="audit", primary_key=11, depth_from_root=1);
    a_leaf = Struct(name="audit_leaf", prefix="audit", primary_key=12, depth_from_root=2);

    # Introduce a cycle on the public side and a cross-schema lure
    # that the prefix-bound walker must NOT follow.
    cfg ++> p_root;
    cfg +>:ParentLink:+> p_mid;
    cfg +>:ParentLink:+> p_leaf;
    p_root +>:ChildLink:+> p_mid;
    p_mid +>:ChildLink:+> p_leaf;
    p_mid +>:ChildLink:+> p_root;
    p_leaf +>:CrossSchema:+> a_root;

    cfg ++> a_root;
    a_root +>:ChildLink:+> a_mid;
    a_mid +>:ChildLink:+> a_leaf;

    af_pub = AncestorFinder(target_id=3, schema_name="public", max_depth=cfg.max_depth);
    print("=== ancestors of public_leaf (schema=public) ===");
    root spawn af_pub;
    print(f"  collected: {af_pub.ancestors}");

    af_aud = AncestorFinder(target_id=12, schema_name="audit", max_depth=cfg.max_depth);
    print("=== ancestors of audit_leaf (schema=audit) ===");
    root spawn af_aud;
    print(f"  collected: {af_aud.ancestors}");

    df_pub = DescendantFinder(seed_id=1, schema_name="public", max_depth=cfg.max_depth);
    print("=== descendants of public_root (schema=public, cycle present) ===");
    root spawn df_pub;
    print(f"  collected: {df_pub.descendants}");

    df_aud = DescendantFinder(seed_id=10, schema_name="audit", max_depth=cfg.max_depth);
    print("=== descendants of audit_root (schema=audit) ===");
    root spawn df_aud;
    print(f"  collected: {df_aud.descendants}");

    inv = CascadeInvalidator(schema_name="public");
    print("=== cascade invalidation (schema=public) ===");
    root spawn inv;
    print(f"  invalidated: {inv.invalidated}");
}

