"""Nika Core Product Factory: model ProductProjects and their dependency
graph, then audit them with a walker that classifies PR/pipeline state and
detects cycles in the PF dependency wave."""

# ----------------------------------------------------------------------
# Node archetypes: the durable entities on the dashboard.
# ----------------------------------------------------------------------

node ProductProject {
    has title: str = "";
    has head_sha: str = "";
    has gate_status: str = "PENDING";  # RED / GREEN-BUT-STALE / MERGE-READY / BLOCKED
    has core_evidence: bool = False;
    has m12_evidence: bool = False;
    has integrated: bool = False;
}

node ScheduledSlot {
    has task_id: str = "";
    has minute_of_hour: int = 0;
}

edge DependsOn {
    has wave: str = "PF";  # which dependency wave this edge belongs to
}

# ----------------------------------------------------------------------
# Walker: classify the PF wave and detect cycles via an explicit guard set
# (jac 0.36.1 walkers have no built-in dedupe on cyclic graphs). Each
# invocation is depth-bounded so the cyclic graph cannot run forever.
# ----------------------------------------------------------------------

walker PFAuditor {
    has max_steps: int = 12;
    has steps: int = 0;

    can start with Root entry {
        print("PF WAVE AUDIT — classifying dependency wave ...");
        visit [-->];
    }

    can classify with ProductProject entry {
        self.steps += 1;
        if self.steps > self.max_steps {
            print("  [HALT] step budget exhausted (cycle-safe)");
            disengage;
        }
        if here.integrated {
            status = "INTEGRATED";
        } elif here.core_evidence and here.m12_evidence {
            status = "MERGE-READY";
        } else {
            status = here.gate_status;
        }
        head_short = here.head_sha[:8] if here.head_sha else "--------";
        print(f"  [PP] {here.title} @ {head_short} -> {status}");
        visit [->:DependsOn:->] else {
            disengage;
        }
    }

    can classify_slot with ScheduledSlot entry {
        print(f"  [SLOT] {here.task_id} scheduled at minute :{here.minute_of_hour:02d}");
        visit [-->];
    }
}

# ----------------------------------------------------------------------
# Demo wiring.
# ----------------------------------------------------------------------

with entry {
    # Five durable ProductProjects in the dependency wave.
    pf1 = ProductProject(
        title="PF1-ProductProject",
        head_sha="a973b82e096f642f",
        gate_status="GREEN-BUT-STALE",
        core_evidence=True,
        m12_evidence=True,
    );
    pf2 = ProductProject(
        title="PF2-DynamicTeamComposer",
        head_sha="5f84e4c3380b0834",
        gate_status="MERGE-READY",
        core_evidence=True,
        m12_evidence=True,
        integrated=True,
    );
    pf3 = ProductProject(
        title="PF3-ExecutionNode",
        head_sha="0000000000000000",
        gate_status="RED",
        core_evidence=False,
        m12_evidence=False,
    );
    pf4 = ProductProject(
        title="PF4-IntegrationGatekeeper",
        head_sha="1111111111111111",
        gate_status="BLOCKED",
    );
    pf5 = ProductProject(
        title="PF5-CommandPresentation",
        head_sha="2222222222222222",
        gate_status="MERGE-READY",
        core_evidence=True,
        m12_evidence=True,
    );

    # Dependency wave (PF1 -> PF2 -> PF3 -> PF4 -> PF5). PF5 also depends
    # back on PF1 so the cycle guard has real work to do.
    pf1 +>:DependsOn(wave="PF"):+> pf2;
    pf2 +>:DependsOn(wave="PF"):+> pf3;
    pf3 +>:DependsOn(wave="PF"):+> pf4;
    pf4 +>:DependsOn(wave="PF"):+> pf5;
    pf5 +>:DependsOn(wave="PF"):+> pf1;

    # Scheduled slots with the staggered minute-of-hour values from the issue.
    slot1 = ScheduledSlot(task_id="PF1", minute_of_hour=5);
    slot2 = ScheduledSlot(task_id="PF2", minute_of_hour=17);
    slot3 = ScheduledSlot(task_id="PF3", minute_of_hour=29);
    slot4 = ScheduledSlot(task_id="PF4", minute_of_hour=41);
    slot5 = ScheduledSlot(task_id="PF5", minute_of_hour=53);

    # Mount the wave and the schedule under root.
    root ++> pf1 ++> slot1;
    root ++> pf2 ++> slot2;
    root ++> pf3 ++> slot3;
    root ++> pf4 ++> slot4;
    root ++> pf5 ++> slot5;

    # Run the auditor.
    root spawn PFAuditor();
}

