"""Fork lineage: immutable inherited prefix after fork creation.

Models the essential scenario from issue #27: a parent transcript can be
forked at an offset to create a child. After fork creation, mutations to the
parent prefix (edit, delete, reorder, compaction, exclusion change) must not
alter the child's inherited snapshot. The walker enforces the invariant by
snapshotting the inherited prefix at fork time and only re-reading the
child-owned continuation thereafter.
"""

node Message {
    has content: str = "";
    has edited: bool = False;
    has deleted: bool = False;
    has excluded: bool = False;
}

# A Fork edge records the offset at which a child transcript was forked from
# its parent. The child carries an inherited prefix snapshot that becomes
# immutable once the fork edge is created.
edge Fork {
    has offset: int = 0;
    has inherited_snapshot: list[str] = [];
    has sealed: bool = True;
}

# An Append edge links one message to the next in transcript order.
edge Append {
    has order: int = 0;
}

walker TranscriptAuditor {
    has report: list[str] = [];
    has visited: list[Message] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Message entry {
        if here in self.visited {
            disengage;
        }
        self.visited.append(here);
        # Walk the message chain via Append edges in declared order.
        visit [->:Append:->];
    }

    # At a forked child, the inherited prefix is the snapshot, NOT a fresh
    # re-read of the parent's mutable prefix. Only the child-owned
    # continuation (reached via Append from this point) is re-rendered.
    can render with Fork entry {
        if not here.sealed {
            disengage;
        }
        for (i, line) in enumerate(here.inherited_snapshot) {
            self.report.append(f"inherited[{i}]: {line}");
        }
        # Follow the child-owned continuation only.
        visit [->:Append:->];
    }
}

with entry {
    # Parent transcript: a chain of five messages.
    m1 = Message(content="hello");
    m2 = Message(content="world");
    m3 = Message(content="foo");
    m4 = Message(content="bar");
    m5 = Message(content="baz");

    # Connect them in order with typed Append edges.
    m1 +>:Append(order=0):+> m2;
    m2 +>:Append(order=1):+> m3;
    m3 +>:Append(order=2):+> m4;
    m4 +>:Append(order=3):+> m5;

    # Fork a child at offset 2 (inherits m1, m2; child-owned continuation
    # starts at m3 and continues to m4, m5).
    fork_edge = Fork(
        offset=2,
        inherited_snapshot=["hello", "world"],
        sealed=True
    );
    m2 +>:fork_edge:+> m3;

    # ---- Demonstrate the invariant ----
    auditor = TranscriptAuditor();
    root spawn auditor;
    auditor spawn m2;

    print("=== Initial child transcript (after fork) ===");
    for line in auditor.report {
        print(line);
    }
    snapshot_count = len(auditor.report);

    # Now mutate the parent prefix: edit and delete m1.
    m1.edited = True;
    m1.content = "HELLO-MUTATED";
    m1.deleted = True;

    # Also exclude m2 from the parent and reorder by touching the chain.
    m2.excluded = True;

    # Re-spawn a fresh auditor to re-render the child transcript.
    auditor2 = TranscriptAuditor();
    root spawn auditor2;
    auditor2 spawn m2;

    print("=== Child transcript AFTER parent prefix mutations ===");
    for line in auditor2.report {
        print(line);
    }

    if len(auditor2.report) == snapshot_count {
        print("INVARIANT HELD: child inherited prefix is immutable.");
    } else {
        print("INVARIANT VIOLATED: child inherited prefix changed!");
    }
}

