    assert auditor.dependency_order[0] == "a.example", f"wrong first domain: {auditor.dependency_order}";
    assert auditor.dependency_order[1] == "b.example", f"wrong second domain: {auditor.dependency_order}";
    assert auditor.dependency_order[2] == "c.example", f"wrong third domain: {auditor.dependency_order}";
    assert auditor.cycles_found == 0, f"unexpected cycles: {auditor.cycles_found}";
}

test "cycle in include chain is detected and traversal halts" {
    root ++> Domain(name="alpha.test", spf_record="v=spf1 include:beta.test -all");
    a = [root -->][0];
    b = Domain(name="beta.test", spf_record="v=spf1 include:gamma.test -all");
    c = Domain(name="gamma.test", spf_record="v=spf1 include:alpha.test -all");
    a +>:Ref(mechanism="include"):+> b;
    b +>:Ref(mechanism="include"):+> c;
    c +>:Ref(mechanism="include"):+> a;

    buf = io.StringIO();
    with redirect_stdout(buf) {
