    }

    out = buf.getvalue();
    assert auditor.cycles_found >= 1, f"expected at least 1 cycle, got {auditor.cycles_found}";
    assert "[CYCLE] already visited alpha.test" in out, f"missing cycle marker: {out}";
    assert auditor.failures == 0, f"cycle should not be a failure, got {auditor.failures}";
