"""Regression tests for the worktree-adoption parent-removal guard.

Each test builds a fresh graph and runs the Archiver walker the way
ArchiveService would. We assert:

  * archiving an *adopted* worktree refuses to touch the parent, walks
    every SharesParent neighbor, and surfaces the would-be collateral;
  * archiving an *internal* worktree is allowed and removes nothing
    outside the worktree itself;
  * a target_task that does not match any worktree does not mutate the
    walker's blocked/collateral state;
  * cyclic SharesParent edges do not send the audit into an infinite
    loop (visited-guard works).
"""

import io;
import from contextlib { redirect_stdout }

# ---- 1. adopted worktree: parent removal must be blocked and the
#         collateral list must enumerate every node sharing the parent.

test "adopted worktree archive is refused and reports collateral" {
    parent = "/tmp/dp-adopted";
    repo = Repo(name="repo", parent_dir=parent);
    adopted = Worktree(
        branch="feature",
        path=f"{parent}/repo.feature",
        adopted=True,
        task_id="task-A"
