    repo_label = f"repo:repo at {parent}/repo";
    wt_label = "worktree[adopted]:" + f"{parent}/repo.feature";
    sent_label = f"sibling:{parent}/unrelated-sentinel";

    assert repo_label in res.collateral, f"main repo not listed: {res.collateral}";
    assert wt_label in res.collateral, f"adopted worktree not listed: {res.collateral}";
    assert sent_label in res.collateral, f"unrelated sentinel not listed: {res.collateral}";

    # The guard's refusal marker must be on stdout so the caller can act.
    assert "[blocked]" in out, f"missing [blocked] marker: {out}";
    assert "refusing to remove parent" in out, f"missing refusal message: {out}";

    # The shared-parent directory itself is never added as collateral --
    # only the entries that would have been destroyed are listed.
    assert parent not in res.collateral, (
        f"parent dir {parent} leaked into collateral: {res.collateral}"
    );
