}

node Agent {
    has name: str = "";            # Claude, Codex, OpenCode, ...
    has supported: bool = True;
}

# -----------------------------------------------------------------------------
# Typed edges
# -----------------------------------------------------------------------------

# A milestone contains one or more modules (Milestone -contains-> Module).
edge Contains { }

# A module may list one or more integrations / runtime dependencies
# (Module -depends_on-> Module or Module -depends_on-> Agent).
edge DependsOn { has note: str = ""; }

# A module may apply specifically to one agent (Module -targets-> Agent).
edge Targets { }

# -----------------------------------------------------------------------------
# Walker: report which modules survive the rewrite, which are deferred, and
# which are intentionally removed. Visits every milestone via Contains and
# then each module under it.
# -----------------------------------------------------------------------------

walker ScopeAuditor {
    has in_mvp: int = 0;
    has deferred: int = 0;
    has removed: int = 0;
    has processed: int = 0;

    can start with Root entry {
        print("Scope audit: walking milestone -> module tree");
        visit [-->];
