    can pick_milestone with Milestone entry {
        print(f"  -> milestone: {here.name} [{here.status}]");
        visit [->:Contains:->];
    }

    can audit_module with Module entry {
        self.processed += 1;
        bucket = here.mvp_status;
        if bucket == "InMVP" {
            self.in_mvp += 1;
        } elif bucket == "Deferred" {
            self.deferred += 1;
        } else {
            self.removed += 1;
        }
        tag = "IN " if here.mvp_status == "InMVP" else ("DEF" if here.mvp_status == "Deferred" else "OUT");
        print(f"     [{tag}] {here.name} -- {here.decision}");
