            disengage;
        }
        self.visited.append(here.pagenum);
        print(f"visiting page pagenum={here.pagenum} label={here.label} "
              f"oldestleaf={here.oldestleaf} is_leaf={here.is_leaf}");

        # Track the minimum oldestleaf the tree claims -- this is what
        # callback_gc() trusts to decide what to FREE.
        if here.oldestleaf < self.min_oldestleaf {
            self.min_oldestleaf = here.oldestleaf;
        }

        if not here.is_leaf {
            # Continue down the tree via forged parent links.
            visit [->:ParentLink:->];
        } else {
            # Leaves record which live block they actually live in.
            visit [->:StoredAt:->];
        }
    }

    can collect_block with Block entry {
        # Remember which blocks the tree actually touches -- these are
        # the "live" blocks that should NOT be freed.
        self.live_blocks_seen.append(here.blkno);
        print(f"  leaf lives in block blkno={here.blkno} ({here.label})");
    }
}

walker GarbageCollect {
    has min_oldestleaf: int = 0;
    has freed: list[int] = [];
    has preserved: list[int] = [];

    can start with Root entry {
        print(f"\n[GC] FREE request: oldestleaf={self.min_oldestleaf}");
        # Sweep every block; lbs honors FREE unconditionally.
        visit [-->];
    }

    can sweep with Block entry {
        if here.blkno < self.min_oldestleaf {
            here.live = False;
            self.freed.append(here.blkno);
            print(f"  [FREE] block blkno={here.blkno} ({here.label}) -- lbs deletes it");
        } else {
            self.preserved.append(here.blkno);
            print(f"  [KEEP] block blkno={here.blkno} ({here.label})");
        }
        visit [-->];
    }
}

with entry {
    # Build the B+Tree-shaped graph. Page A is the root; B, C, D are
    # its child pages (also leaves for brevity). Each leaf points at
    # the block where its contents physically live.
    root_pg = Page(pagenum=1, label="root", oldestleaf=2, is_root=True, is_leaf=False);
    b_pg = Page(pagenum=2, label="B", oldestleaf=2, is_leaf=True);
    c_pg = Page(pagenum=3, label="C", oldestleaf=10, is_leaf=True);
    d_pg = Page(pagenum=4, label="D", oldestleaf=4, is_leaf=True);

    b_blk = Block(blkno=100, label="B-data");
    c_blk = Block(blkno=101, label="C-data");
    d_blk = Block(blkno=102, label="D-data");
    # Two extra blocks that the forged oldestleaf will cause kvlds to
    # instruct lbs to FREE -- these are the live-but-victim blocks.
    extra1 = Block(blkno=5, label="victim-block-5");
    extra2 = Block(blkno=8, label="victim-block-8");

    # Wire the tree. The attacker forged child D's oldestleaf to a very
    # small value (4) -- when the root computes min(oldestleaf) across
    # its children, that forged value is what wins.
    root_pg +>:ParentLink(claimed_pagenum=2, claimed_oldestleaf=2):+> b_pg;
    root_pg +>:ParentLink(claimed_pagenum=3, claimed_oldestleaf=10):+> c_pg;
    root_pg +>:ParentLink(claimed_pagenum=4, claimed_oldestleaf=4):+> d_pg;

    b_pg +>:StoredAt:+> b_blk;
    c_pg +>:StoredAt:+> c_blk;
    d_pg +>:StoredAt:+> d_blk;

    root ++> root_pg;
    root ++> extra1;
    root ++> extra2;

    # 1. Descend the tree, trust every field, accumulate the minimum
    #    oldestleaf the attacker forged.
    descend = AttackerDescend();
    root spawn descend;

    print(f"\nattacker-controlled min oldestleaf = {descend.min_oldestleaf}");
    print(f"live blocks the tree actually used   = {descend.live_blocks_seen}");

    # 2. callback_gc() fires: FREE everything below the forged oldestleaf.
    #    lbs honors it unconditionally -- confused deputy destroys live data.
    gc = GarbageCollect(min_oldestleaf=descend.min_oldestleaf);
    root spawn gc;

    print(f"\nfreed (by lbs due to forged oldestleaf): {gc.freed}");
    print(f"preserved: {gc.preserved}");
    print("note: every freed block was a live block the B+Tree never");
    print("actually invalidated -- kvlds trusted the child record's field.");
}

fixed.code:
"""Kivaloo Bug Bounty #720 — modeled as a typed B+Tree of pages on blocks.

Bug 2 (data destruction via forged `oldestleaf`): the kvlds daemon trusts a
child page's `oldestleaf` field, computes the root's `oldestleaf` as the
minimum of its children's claims, and instructs the backing store (LBS) to
free every block up to that point — no validation against the tree's real
extent. We model the page tree with typed edges and walk it with an auditor
walker that, just like the real daemon, follows child pointers and computes
`oldestleaf` as the min of its children's claims, then issues FREE requests
against every block the trust-violating value touches.

The demo wires one honest page tree plus one attacker-forged child whose
`oldestleaf` lies far below the real tree's lowest block — showing how the
honest walker, by the issue's exact mechanism, orders destruction of live
blocks it never visited.
"""

node Block {
    has blkno: int = 0;
    has label: str = "";
}

node Page {
    has pagenum: int = 0;
    has claimed_oldestleaf: int = 0;
    has pagesize: int = 0;
    has key: str = "";
    has forged: bool = False;
}

edge ParentChild {
}

edge LivesOn {
}

walker BTreeGC {
    has freed: list[int] = [];
    has visited: set[int] = set();
    has trusted_min: int = 0;
    has observed_min: int = 999999;

    can start with Root entry {
        print("[GC] starting from root, descending into page tree");
        visit [->:ParentChild:->];
    }

    can descend with Page entry {
        if here.pagenum in self.visited {
            disengage;
        }
        self.visited.add(here.pagenum);

        if here.claimed_oldestleaf < self.observed_min {
            self.observed_min = here.claimed_oldestleaf;
        }

        if here.forged {
            print(f"[GC] WARNING: forged page {here.pagenum} claims oldestleaf={here.claimed_oldestleaf}");
        } else {
            print(f"[GC] visited page {here.pagenum} (claims oldestleaf={here.claimed_oldestleaf})");
        }

        visit [->:ParentChild:->];
    }

    can collect_free with Block entry {
        min_used = self.observed_min;
        if here.blkno < min_used {
            self.freed.append(here.blkno);
            print(f"[GC] FREE block {here.blkno} ({here.label})");
        } else {
            print(f"[GC] keep block {here.blkno} ({here.label})");
        }
    }
}

with entry {
    root_page = Page(pagenum=100, claimed_oldestleaf=200, pagesize=4096, key="root");
    honest_leaf_a = Page(pagenum=101, claimed_oldestleaf=200, pagesize=4096, key="alpha");
    honest_leaf_b = Page(pagenum=102, claimed_oldestleaf=200, pagesize=4096, key="beta");
    forged_child = Page(pagenum=103, claimed_oldestleaf=1, pagesize=4096, key="zeta", forged=True);

    root +>:ParentChild:+> root_page;
    root_page +>:ParentChild:+> honest_leaf_a;
    root_page +>:ParentChild:+> honest_leaf_b;
    root_page +>:ParentChild:+> forged_child;

    block_anchor = Block(blkno=1, label="blk#1 (anchor)");
    block_root = Block(blkno=100, label="blk#100 -> root_page");
    block_alpha = Block(blkno=101, label="blk#101 -> leaf alpha");
    block_beta = Block(blkno=102, label="blk#102 -> leaf beta");
    block_forged = Block(blkno=103, label="blk#103 -> forged child");

    root_page +>:LivesOn:+> block_anchor;
    honest_leaf_a +>:LivesOn:+> block_root;
