    print(f"\n[summary] forged oldestleaf observed_min={gc_walker.observed_min}");
    print(f"[summary] freed {len(gc_walker.freed)} blocks: {gc_walker.freed}");
    print("[summary] BUG 2 reproduced: forged oldestleaf caused the GC to FREE live blocks the walker never visited honestly.");
