    def init(env_map: dict[str, str], max_depth: int) {
        self.env = env_map;
        self.max_depth = max_depth;
    }

    can start with Root entry {
        visit [-->];
    }

    can resolve with EnvVar entry {
        path: list[str] = [];
        result = self._resolve(here.name, path, 0);
        print(f"{here.name} -> {result}");
        if result != "" {
            here.resolved = result;
        }
        visit [-->];
    }

    def _resolve(var_name: str, path: list[str], depth: int) -> str {
        if depth > self.max_depth {
            self._fail(path + [var_name]);
            return "";
        }
        if var_name in path {
            self._fail(path + [var_name]);
            return "";
        }
        raw = self.env.get(var_name, "");
        if not raw.startswith("${") {
            return raw;
        }
        ref_name = raw[2:-1];
        next_path = path + [var_name];
        return self._resolve(ref_name, next_path, depth + 1);
    }

    def _fail(path: list[str]) -> None {
        arrow_path = " -> ".join(path);
        print(f"CircularReferenceError: Circular reference detected: {arrow_path}");
        disengage;
    }
}

