"""Docker build pipeline: model a heavy Rust/native build graph and walk it.

The pipeline models the developer complaint: small backend source edits should
rebuild mostly the application crate, not force repeated compilation of heavy
native dependencies (e.g. DuckDB C++ sources). A walker traverses the build
dependency graph, classifies which artifacts are heavy (must be cached) versus
light (safe to recompile), and reports whether the small edit triggered any
expensive recompilation. A second walker walks the cache-miss chain so we can
see which dependencies would have to be rebuilt from scratch.
"""

# ---- Edge archetypes -------------------------------------------------------

# A build-time dependency: "b depends on a at build time". Carries the
# observed compile cost in seconds so the walker can classify the edge.
edge BuildDep {
    has cost_seconds: int = 0;
    has native: bool = False;
}

# A cache-miss link: "a cached artifact was invalidated by b". Used by the
# invalidation walker to cascade a small source change through the graph.
edge CacheMiss {
    has reason: str = "";
}

# ---- Node archetypes -------------------------------------------------------

node BuildStage {
    has name: str = "";
    has language: str = "";   # "rust", "cpp", "js", ...
    has heavy: bool = False;
}

node SourceFile {
    has path: str = "";
    has lines: int = 0;
}

node CachedArtifact {
    has key: str = "";
    has size_mb: int = 0;
    has pinned: bool = False;
}

# ---- Walker: classify what the build actually did ---------------------------

walker BuildAuditor {
    has edited: str = "";        # path the developer touched
    has heavy_rebuilds: int = 0;  # how many heavy artifacts were invalidated
    has light_rebuilds: int = 0;  # how many light artifacts were invalidated
    has report: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    # A single ability handles every node archetype in the build graph
    # because they all expose `name`. The classification depends on the
    # concrete node fields, so we read them via type-specific branches.
    can classify with BuildStage | SourceFile | CachedArtifact entry {
        label = here.name if here.name else "?";

        # Heavy native stages (Rust + C++ for DuckDB) must be cached.
        if here isa BuildStage {
            if here.heavy {
                self.heavy_rebuilds += 1;
                self.report.append(f"HEAVY  stage  {label} ({here.language})");
            } else {
                self.light_rebuilds += 1;
                self.report.append(f"light  stage  {label} ({here.language})");
            }
            visit [->:BuildDep:->];
        } else {
            visit [-->];
        }
    }

    can summarize with Root exit {
        total = self.heavy_rebuilds + self.light_rebuilds;
        verdict = "OK" if self.heavy_rebuilds == 0 else "WASTEFUL";
        print(f"build audit verdict: {verdict}  "
              f"(heavy={self.heavy_rebuilds}, light={self.light_rebuilds}, "
