"""Task dependency graph with memoization and cycle detection.

Models pyinvoke/invoke issue #461: tasks depend on other tasks, each task
memoizes its work so re-entry short-circuits, and the dependency walk must
detect cycles and execute prerequisites before their dependents.

Entities:
  Task     — a unit of work with memoized output.
  Config   — a cached configuration value that some tasks populate.
  Step     — a sub-step a task performs (build, fetch, validate, ...).
Edges:
  Requires   — task -> task (this task needs that task to run first).
  Produces   — task -> config / step (this task generates that artifact).
"""

node Config {
    has key: str = "";
    has value: str = "";
    has filled: bool = False;
}

node Step {
    has label: str = "";
    has done: bool = False;
}

node Task {
    has name: str = "";
    has memo: str = "";
    has ran: bool = False;
}

edge Requires { }
edge Produces { }

walker Executor {
    has visited: list = [];
    has log: list = [];

    can start with Root entry {
        visit [-->];
    }

    # Union trigger: a Task enters its prerequisite list through typed
    # Requires edges; a Config or Step entry is also valid because the
    # walker may step onto produced artifacts between tasks.
    can run with Task | Config | Step entry {
        if here in self.visited {
            # Cycle guard: the visited set is explicit because jac 0.36.1
            # walkers do not dedupe revisits on cyclic graphs.
            self.log.append(f"CYCLE detected at {here}");
            disengage;
        }
        self.visited.append(here);

        if here <: Task {
            t: Task = here;
            if t.ran {
                self.log.append(f"  memo hit: {t.name} -> {t.memo}");
                visit [-->];
            } else {
                # First: satisfy prerequisites (Requires edges).
                # We must walk the typed Requires edges out of this task
                # BEFORE running it, so dependents only run after deps.
                for (i, n) in enumerate([->:Requires:->]) {
                    # Recursive descent via spawn: the child walker walks
                    # its own prereqs, memoizes, then returns. This is
                    # the "BFS over requires" the issue describes, lifted
                    # into a walker instead of a hand-rolled queue.
                    child = Executor(visited=self.visited, log=self.log);
                    child spawn n;
                    self.visited = child.visited;
                    self.log = child.log;
                }
                # After deps, execute this task and memoize.
                t.memo = f"work({t.name})";
                t.ran = True;
                self.log.append(f"  ran: {t.name}");
                visit [-->];
            }
        } else {
            # Artifact nodes: just walk onward.
            visit [-->];
        }
    }
}

walker Auditor {
    can start with Root entry {
        self.audit();
    }

    def audit() -> None {
        # Reachability / dependency-ordering probe: walk every reachable
        # task via typed Requires edges and report visited order. Used
        # to confirm the topo-like order Executor produced.
        seen: list = [];
        stack: list = [->:Requires:->];
        while stack {
            n = stack.pop();
            if n in seen {
                continue;
            }
            seen.append(n);
            if n <: Task {
                t: Task = n;
                print(f"reachable task: {t.name} ran={t.ran} memo={t.memo}");
            }
            for (i, nx) in enumerate([n->:Requires:->]) {
                stack.append(nx);
            }
        }
    }
