"""Task dependency graph with memoization-style short-circuit traversal.

Models the pyinvoke/invoke #461 "advanced task dependencies / caching" use case:
a tree of tasks (some heavy, some cheap) connected by typed `Requires` edges.
A walker descends the dependency graph, but each task remembers whether its
result has already been "produced" — re-entering an already-completed task
short-circuits instead of re-running its body. This is the make-like behavior
the issue asks for: tasks declare what they need, run only as many times as
required, and skip work that has already been done.
"""

node Task {
    has title: str = "";
    has heavy: bool = False;
    has done: bool = False;
    has runs: int = 0;
}

edge Requires {
    has via: str = "pre";
}

walker Executor {
    can start with Root entry {
        visit [->:Requires:->];
    }

    can run_task with Task entry {
        if here.done {
            print(f"  [skip ] {here.title} (already done, runs={here.runs})");
            visit [->:Requires:->];
            return;
        }
        if here.heavy {
            print(f"  [heavy] {here.title} -- doing real work");
            here.runs = here.runs + 1;
        } else {
            print(f"  [light] {here.title} -- quick step");
            here.runs = here.runs + 1;
        }
        here.done = True;
        visit [->:Requires:->];
    }
}

with entry {
    # Build a small dependency tree. `deploy` requires `build_artifact`
    # requires `compile` and `fetch_secrets`. `compile` itself requires
    # `fetch_secrets` (shared subtree).
    fetch_secrets = Task(title="fetch_secrets", heavy=True);
    compile_t = Task(title="compile", heavy=True);
    build_artifact = Task(title="build_artifact", heavy=True);
    provision_db = Task(title="provision_db", heavy=True);
    deploy = Task(title="deploy", heavy=True);

    root +>:Requires(via="pre"):+> deploy;
    deploy +>:Requires:+> build_artifact;
    deploy +>:Requires:+> provision_db;
    build_artifact +>:Requires:+> compile_t;
    build_artifact +>:Requires:+> fetch_secrets;
    compile_t +>:Requires:+> fetch_secrets;
    provision_db +>:Requires:+> fetch_secrets;

    print("=== first execution pass ===");
    Executor() spawn deploy;

    print("=== second execution pass (everything should be skipped) ===");
    Executor() spawn deploy;

    print(f"final runs: "
          f"fetch_secrets={fetch_secrets.runs}, "
          f"compile={compile_t.runs}, "
          f"build_artifact={build_artifact.runs}, "
          f"provision_db={provision_db.runs}, "
          f"deploy={deploy.runs}");
