    def _seen(self, key: str) -> bool {
        for k in self.visited {
            if k == key {
                return True;
            }
        }
        return False;
    }

    def _mark(self, key: str) -> None {
        if not self._seen(key) {
            self.visited.append(key);
        }
    }

    def _classify(self, old_h: str, new_h: str) -> str {
        if old_h == "" {
            return "new";
        }
        if old_h == new_h {
            return "unchanged";
        }
        return "changed";
