    has trail: list[str] = [];
    has cycle_found: bool = False;
    has seen: list[str] = [];

    can start with Root entry {
        print(f"Auditor engaged: trail={self.trail}");
        visit [-->];
    }

    can descend with EvidenceBundle entry {
        if here.visited {
            self.cycle_found = True;
            print(f"[CYCLE] re-entered bundle {here.bundle_id}");
            disengage;
        }
        here.visited = True;
        self.seen.append(here.bundle_id);
        self.trail.append(here.bundle_id);
        print(f"entering bundle {here.bundle_id} (sig={here.signature})");
        if here.signature == "invalid" {
            print(f"  signature FAILED on {here.bundle_id}");
        }
        visit [-->];
    }

    can record_config with Config entry {
        verdict = "REVOKED" if here.revoked else "OK";
        self.trail.append(f"cfg:{here.title}:{verdict}");
        print(f"  config [{verdict}] {here.title} ck={here.checksum}");
    }

    can record_metric with Metric entry {
        self.trail.append(f"m:{here.name}={here.value}");
        print(f"  metric {here.name}={here.value}");
    }

    can record_artifact with Artifact entry {
        self.trail.append(f"art:{here.path}/{here.size_kb}kb");
        print(f"  artifact {here.path} ({here.size_kb}kb)");
    }
}

walker CascadeInvalidator {
    has purged: list[str] = [];
    has depth: int = 0;

    can start with Root entry {
        print("Cascade invalidator sweeping dependents");
        visit [-->];
    }

    can sweep with EvidenceBundle entry {
        if self.depth > 4 {
            print(f"  depth cap hit at {here.bundle_id}, disengaging");
            disengage;
        }
        if here.published {
            here.published = False;
            self.purged.append(here.bundle_id);
            print(f"  invalidated bundle {here.bundle_id}");
        }
        self.depth += 1;
        visit [<--];
    }
}

