        # pass, skip it. Without this a DependsOn loop would hang forever.
        already_done = False;
        for prior in self.modules_seen {
            if prior == here.name {
                already_done = True;
            }
        }
        if already_done {
            print(f"[stage:{self.stage_name}] skip already-seen {here.name}");
            disengage;
        }
        self.modules_seen.append(here.name);

        # Per-iteration budget check: long-running loops in the real
        # compiler check cancellation each step; we mirror that here.
        if self.budget_ref.remaining <= 0 {
            self.budget_ref.canceled = True;
            print(f"[stage:{self.stage_name}] budget exhausted at {here.name}");
            disengage;
        }
        self.budget_ref.remaining = self.budget_ref.remaining - 1;

        print(
            f"[stage:{self.stage_name}] processing {here.name} "
            f"(budget left: {self.budget_ref.remaining})"
        );

        # Recurse into this module's dependencies. The typed edge
        # ``DependsOn`` is the relationship; we don't read a rules
        # list, we follow edges.
        visit [here->:DependsOn:->];
    }
}

# ----------------------------------------------------------------------
# Demo wiring
# ----------------------------------------------------------------------

with entry {
    # Three modules that form a dependency graph. main pulls in helpers
    # and util; helpers pulls in util; util is a leaf. No cycles here.
    main = Module(name="main.rego", rules=["helpers", "util"]);
    helpers = Module(name="helpers.rego", rules=["util"]);
    util = Module(name="util.rego", rules=[]);

    # Connect via the typed DependsOn edge so the walker traverses by
    # relationship, not by reading an adjacency list off the node.
    main +>:DependsOn:+> helpers;
    helpers +>:DependsOn:+> util;
    root +>:DependsOn:+> main;

    # A shared budget. Make it small so the third stage demonstrates the
    # "long compile gets cut off" behaviour from the issue.
    shared_budget = Budget(remaining=3, canceled=False);

    # Stage 1: parse -- plenty of budget, should complete.
    c1 = Compiler(
        budget_ref=shared_budget,
        stage_name="parse",
        modules_seen=[]
    );
    root spawn c1;
    print(f"after parse: budget={shared_budget.remaining} canceled={shared_budget.canceled}");
    print("---");

    # Reset for the next stage so we can demonstrate cancellation cleanly.
    shared_budget.remaining = 3;
    shared_budget.canceled = False;

    # Stage 2: type-check -- walks again, uses the same three modules.
    c2 = Compiler(
        budget_ref=shared_budget,
        stage_name="typecheck",
        modules_seen=[]
    );
    root spawn c2;
    print(f"after typecheck: budget={shared_budget.remaining} canceled={shared_budget.canceled}");
    print("---");

    # Stage 3: a tiny budget that runs out mid-walk, proving the
    # per-iteration check kicks in instead of hanging the request.
    tight_budget = Budget(remaining=1, canceled=False);
    c3 = Compiler(
        budget_ref=tight_budget,
        stage_name="eval",
        modules_seen=[]
    );
    root spawn c3;
    print(f"after eval: budget={tight_budget.remaining} canceled={tight_budget.canceled}");
}

