"""Analyzed code graph: list packages, get stats, export, and cascade delete.

Models the CLI commands requested in the issue as walkers over typed edges
that carry the relationship meaning (DEFINES, CONTAINS, CALLS, IMPORTS,
INHERITS, BELONGS_TO). Each entity node carries an explicit ``kind`` so a
union ability can label it without sniffing class identity.
"""

# ---- Edge archetypes: each carries a typed relationship ----
edge Defines { }
edge Contains { }
edge Calls { }
edge Imports { }
edge Inherits { }
edge BelongsTo { }    # module/class/function -> package

# ---- Base node so every entity shares a kind label + fqn ----
node CodeNode {
    has kind: str = "";
    has name: str = "";
    has fqn: str = "";
    has package_name: str = "";
}

# ---- Concrete archetypes inherit the shared fields ----
node Module(CodeNode) {
    has kind: str = "Module";
}

node Cls(CodeNode) {
    has kind: str = "Class";
}

node Func(CodeNode) {
    has kind: str = "Function";
}

node Package {
    has name: str = "";
    has analyzed_at: str = "";
    has node_count: int = 0;
}

# ---- Walker: list all analyzed packages with summary counts ----
walker PackageLister {
    has detailed: bool = False;
    has lines: list[str] = [];

    can start with Root entry {
        self.lines = [];
        visit [-->];
    }

    can gather with Package entry {
        summary = f"{here.name}  nodes={here.node_count}";
        self.lines.append(summary);
        if self.detailed {
            self.lines.append(f"  analyzed_at={here.analyzed_at}");
        }
    }

    can drain with Root exit {
        print("Analyzed Packages:");
        for line in self.lines {
            print(f"  {line}");
        }
        report self.lines;
    }
}

# ---- Walker: get detailed stats for one package ----
walker PackageStats {
    has package_name: str = "";
    has depth: int = 3;
    has stats_only: bool = False;
    has by_type: dict[str, int] = {};
    has by_rel: dict[str, int] = {};
    has most_connected: list[str] = [];
    has incoming: dict[str, int] = {};

    can start with Root entry {
        visit [-->];
    }

    can hit with Package entry {
        if here.name == self.package_name {
            self.by_type["Package"] = 1;
            visit [-->] else { disengage; }
        }
    }

    can count_node with Module | Cls | Func entry {
        if self.stats_only {
            return;
        }
        self.incoming[here.fqn] = self.incoming.get(here.fqn, 0);
        for n in [-->] {
            self.incoming[here.fqn] = self.incoming.get(here.fqn, 0);
        }
        visit [-->];
    }

    can summarize with Package exit {
        print(f"Package: {self.package_name}");
        print(f"Analyzed: {here.analyzed_at}");
        print("Nodes:");
        for (k, v) in self.by_type.items() {
            print(f"  {k}: {v}");
        }
        print("Relationships:");
        for (k, v) in self.by_rel.items() {
            print(f"  {k}: {v}");
        }
        if self.most_connected {
            print("Most Connected:");
            for entry in self.most_connected {
                print(f"  {entry}");
            }
        }
        report {
            "package": self.package_name,
            "by_type": self.by_type,
            "by_rel": self.by_rel,
        };
    }
}

# ---- Walker: cascade delete a package (DETACH DELETE equivalent) ----
walker PackageDeleter {
    has package_name: str = "";
    has force: bool = False;
    has dry_run: bool = False;
    has deleted_nodes: int = 0;
    has deleted_edges: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can hit with Package entry {
        if here.name != self.package_name {
            disengage;
        }
        # Detach delete: remove all edges first, then the node.
        old_edges = [-->];
        for e in old_edges {
            here del --> e;
            self.deleted_edges += 1;
        }
        if not self.dry_run {
            del here;
            self.deleted_nodes += 1;
        } else {
