"""Regression tests for HIER benchmark model (issue #353).

Tests:
  1. HierarchyInspector post-order traversal via Parent edges
  2. ReachabilityChecker path discovery
  3. CascadeInvalidator subtree invalidation
  4. Cycle detection on a graph with a back-edge
  5. Two-hop index fanout counting
"""

import io;
import from contextlib { redirect_stdout }

# ---------- Test 1: HierarchyInspector traversal over narrow deep tree ----------
test "HierarchyInspector traverses a deep Parent chain" {
    a = OntologyClass(name="a");
    b = OntologyClass(name="b");
    d = OntologyClass(name="d");
    e = OntologyClass(name="e");
    root ++> a +>:Parent:+> b +>:Parent:+> d +>:Parent:+> e;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn HierarchyInspector();
    }
    out = buf.getvalue();

    assert "[CYCLE]" not in out, f"unexpected cycle: {out}";
    assert res.cycle_detected is False, f"cycle_detected should be False: {out}";
    assert res.visited == ["a", "b", "d", "e"], (
        f"expected order [a,b,d,e], got {res.visited}"
    );
    assert res.order == ["a", "b", "d", "e"], (
        f"expected order list [a,b,d,e], got {res.order}"
    );
    assert "visit a (depth 0" in out, f"missing a visit line: {out}";
    assert "visit e (depth 3" in out, f"missing e visit line: {out}";
}

# ---------- Test 2: ReachabilityChecker finds target via Parent walk ----------
test "ReachabilityChecker reaches target through Parent chain" {
    p1 = OntologyClass(name="P1");
    p2 = OntologyClass(name="P2");
    p3 = OntologyClass(name="P3");
    p4 = OntologyClass(name="P4");
    root ++> p1 +>:Parent:+> p2 +>:Parent:+> p3 +>:Parent:+> p4;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ReachabilityChecker(target="P4");
    }
    out = buf.getvalue();

    assert res.reached is True, f"P4 should be reachable, got {res.reached}";
    assert "P4" in res.path, f"path missing P4: {res.path}";
    assert res.path[0] == "P1", f"path should start at P1: {res.path}";
    assert res.path[-1] == "P4", f"path should end at P4: {res.path}";
    assert "REACHED P4" in out, f"missing REACHED line: {out}";
}

test "ReachabilityChecker misses unreachable target" {
    u1 = OntologyClass(name="U1");
    u2 = OntologyClass(name="U2");
    root ++> u1 +>:Parent:+> u2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ReachabilityChecker(target="Nonexistent");
    }
    out = buf.getvalue();

    assert res.reached is False, f"should not reach Nonexistent: {res.reached}";
    assert "REACHED" not in out, f"should not print REACHED: {out}";
    assert res.path == ["U1", "U2"], f"path should be [U1,U2]: {res.path}";
}

# ---------- Test 3: CascadeInvalidator flags subtree root only ----------
test "CascadeInvalidator flags target and walks its children" {
    # Build a subtree: X is target with two children, plus an unrelated branch Y.
    x = OntologyClass(name="X_target");
    xc1 = OntologyClass(name="X_child1");
    xc2 = OntologyClass(name="X_child2");
    y = OntologyClass(name="Y_unrelated");
    yc = OntologyClass(name="Y_child");
    root ++> x +>:Parent:+> xc1;
    x +>:Parent:+> xc2;
    root ++> y +>:Parent:+> yc;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CascadeInvalidator(invalid_name="X_target");
    }
    out = buf.getvalue();

    # The walker only flags the literal target node (it cascades by visiting
    # children, not by flipping their invalidated flag).
    assert x.invalidated is True, f"X_target must be invalidated: {x.invalidated}";
    assert xc1.invalidated is False, (
        f"X_child1 should not be flagged by walker: {xc1.invalidated}"
    );
    assert xc2.invalidated is False, (
        f"X_child2 should not be flagged by walker: {xc2.invalidated}"
    );
    assert y.invalidated is False, f"Y_unrelated untouched: {y.invalidated}";
    assert yc.invalidated is False, f"Y_child untouched: {yc.invalidated}";
    assert res.purged == ["X_target"], (
        f"purged should be ['X_target'], got {res.purged}"
    );
    assert "invalidated X_target" in out, f"missing invalidate line: {out}";
}

# ---------- Test 4: Cycle detection on a back-edge graph ----------
test "HierarchyInspector detects a cycle via back-edge" {
    cy = OntologyClass(name="Cy");
    cy2 = OntologyClass(name="Cy2");
    root ++> cy +>:Parent:+> cy2;
    # Back-edge creating a cycle
    cy2 +>:Parent:+> cy;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn HierarchyInspector();
    }
    out = buf.getvalue();

    assert res.cycle_detected is True, (
        f"cycle_detected should be True, got {res.cycle_detected}"
    );
    assert "Cy" in res.visited, f"Cy must be in visited: {res.visited}";
    assert "Cy2" in res.visited, f"Cy2 must be in visited: {res.visited}";
    assert "[CYCLE]" in out, f"missing CYCLE marker: {out}";
}

# ---------- Test 5: Two-hop index fanout via IndexEntry ----------
test "HierarchyInspector counts TwoHopLink fanout on IndexEntry" {
    h1 = OntologyClass(name="Hop1");
    h2 = OntologyClass(name="Hop2");
    h3 = OntologyClass(name="Hop3");
    h4 = OntologyClass(name="Hop4");
    root ++> h1 +>:Parent:+> h2 +>:Parent:+> h3 +>:Parent:+> h4;
    idx = IndexEntry();
    root ++> idx;
    idx +>:TwoHopLink:+> h1;
    idx +>:TwoHopLink:+> h2;
    idx +>:TwoHopLink:+> h3;
    idx +>:TwoHopLink:+> h4;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        inspector = HierarchyInspector();
        idx spawn inspector;
    }
    out = buf.getvalue();

    assert inspector.two_hop_fanout == 4, (
        f"two_hop_fanout should be 4, got {inspector.two_hop_fanout}"
    );
    assert "2-hop fanout at index entry: 4" in out, (
        f"missing fanout line: {out}"
    );
}

