"""Tests for per-TS top-up walker behavior on the JobNode chain."""

import io;
import from contextlib { redirect_stdout }

test "top-up recovers a TS that was emitted as failed" {
    # Build a chain where alignment emitted Position_1_3 in `failed`
    # (the ts_alignment.py policy: partial success is normal).
    alignment = JobNode(
        job_type="tsAlignment",
        exit_status="SUCCESS",
        ok=["Position_1_1", "Position_1_2", "Position_1_4"],
        failed=["Position_1_3"],
        missing=[]
    );
    ctf = JobNode(
        job_type="tsCtf",
        exit_status="SUCCESS",
        ok=["Position_1_1", "Position_1_2", "Position_1_4"],
        failed=[],
        missing=[]
    );
    root +>:RunsOn(order=1):+> alignment;
    alignment +>:RunsOn(order=2):+> ctf;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn TopUp(target_ts="Position_1_3");
    }
    out = buf.getvalue();

    assert res.recovered, f"top-up should recover Position_1_3, got {res.recovered}";
    assert "Position_1_3" not in alignment.failed, (
        f"Position_1_3 must move out of failed, got {alignment.failed}"
    );
    assert "Position_1_3" in alignment.ok, (
        f"Position_1_3 must be re-emitted in ok, got {alignment.ok}"
    );
    assert "[TOP-UP]" in out, f"missing TOP-UP marker: {out}";
    assert "tsAlignment" in res.visited_jobs, (
        f"walker must visit alignment job, visited={res.visited_jobs}"
    );
}

test "top-up cannot recover a TS that was silently dropped (missing)" {
    # In the deadcode_test failure: Position_1_3 was NOT in alignment's
    # `failed` list — it was absent from the manifest entirely. The
    # walker must NOT report success when the TS isn't recorded as
    # failed at the first job it visits.
    alignment = JobNode(
        job_type="tsAlignment",
        exit_status="SUCCESS",
        ok=["Position_1_1", "Position_1_2", "Position_1_4"],
        failed=[],   # silently dropped, not recorded as failed
        missing=["Position_1_3"]
    );
    ctf = JobNode(
        job_type="tsCtf",
        exit_status="SUCCESS",
        ok=["Position_1_1", "Position_1_2", "Position_1_4"],
        failed=[],
        missing=[]
    );
    root +>:RunsOn(order=1):+> alignment;
    alignment +>:RunsOn(order=2):+> ctf;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn TopUp(target_ts="Position_1_3");
    }

    assert not res.recovered, (
        f"top-up must fail when TS is not in any job's failed list, "
        f"got recovered={res.recovered}"
    );
    assert alignment.ok == ["Position_1_1", "Position_1_2", "Position_1_4"], (
        f"alignment.ok must be unchanged, got {alignment.ok}"
    );
}

test "top-up is aborted on total wipeout (fatal policy preserved)" {
    # From drivers/ts_alignment.py: only a total wipeout (nothing
    # aligned) is fatal. The walker must disengage without recovering.
    alignment = JobNode(
        job_type="tsAlignment",
        exit_status="SUCCESS",
        ok=[],
        failed=["Position_1_1", "Position_1_2"],
        missing=[]
    );
    root +>:RunsOn(order=1):+> alignment;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn TopUp(target_ts="Position_1_1");
    }
    out = buf.getvalue();

    assert not res.recovered, (
        f"total wipeout must abort recovery, got recovered={res.recovered}"
    );
    assert "FATAL" in out, f"missing FATAL marker on wipeout: {out}";
    assert "Position_1_1" in alignment.failed, (
        f"failed list must be unchanged on fatal abort, got {alignment.failed}"
    );
}

test "audit manifest reveals which TSs each job emits" {
    # AuditManifest should collect exactly the union of every JobNode's
    # `ok` list — i.e. the downstream-visible manifest.
    alignment = JobNode(
        job_type="tsAlignment",
        exit_status="SUCCESS",
        ok=["Position_1_1", "Position_1_2", "Position_1_4"],
        failed=["Position_1_3"],
        missing=[]
    );
    ctf = JobNode(
        job_type="tsCtf",
        exit_status="SUCCESS",
        ok=["Position_1_1", "Position_1_2", "Position_1_4"],
        failed=[],
        missing=[]
    );
    root +>:RunsOn(order=1):+> alignment;
    alignment +>:RunsOn(order=2):+> ctf;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn AuditManifest();
    }
    out = buf.getvalue();

    assert "Position_1_3" not in res.seen_ts, (
        f"Position_1_3 must not appear in any emitted manifest, "
        f"got seen={res.seen_ts}"
    );
    assert "Position_1_1" in res.seen_ts, (
        f"Position_1_1 must appear in audit, got seen={res.seen_ts}"
    );
    assert "emits:" in out, f"missing emits marker: {out}";
    assert "tsAlignment" in out and "tsCtf" in out, (
        f"audit must print both job types: {out}"
    );
}

test "top-up moves TS from failed to ok without disturbing siblings" {
    # Sibling TSs already in `ok` must be untouched by the top-up.
    alignment = JobNode(
        job_type="tsAlignment",
        exit_status="SUCCESS",
        ok=["Position_1_1", "Position_1_2", "Position_1_4", "Position_1_5"],
        failed=["Position_1_3"],
        missing=[]
    );
    root +>:RunsOn(order=1):+> alignment;

    ok_before = sorted(alignment.ok);
    res = root spawn TopUp(target_ts="Position_1_3");

    assert res.recovered, f"recovery should succeed, got {res.recovered}";
    assert alignment.failed == [], (
        f"failed list must be empty after top-up, got {alignment.failed}"
    );
    assert sorted(alignment.ok) == sorted(
        ok_before + ["Position_1_3"]
    ), f"ok list must gain exactly Position_1_3, got {alignment.ok}";
    assert len(alignment.ok) == len(ok_before) + 1, (
        f"ok list must grow by exactly 1, got {len(alignment.ok)}"
    );
}

