"""Generic-style parameter and constraint resolution modeled with typed edges.

Models the essential scenario from issue #34: a graph of type-like nodes
(``Param``, ``Constraint``, ``ConcreteType``) with ``Constrains`` and
``Applies`` relationships. A walker performs inference-first resolution
with deferred substitution, depth limiting, cycle detection, and
constraint evaluation — the same shape as a generics type checker.
"""

node Param {
    has name: str = "";
    has kind: str = "type";
    has resolved: bool = False;
}

node Constraint {
    has expr: str = "";
    has valid: bool = True;
    has reason: str = "";
}

node ConcreteType {
    has name: str = "";
    has base: str = "";
}

edge Constrains {
    has weight: int = 0;
}

edge Applies {
    has site: str = "";
}

edge Depends {
}

walker Resolver {
    has max_depth: int = 8;
    has guard: list[str] = [];
    has depth: int = 0;
    has log: list[str] = [];
    has deferred: list[str] = [];

    can start with Root entry {
        self.depth = 0;
        visit [-->];
    }

    can resolve_param with Param entry {
        if here.resolved {
            self.log.append(f"already resolved: {here.name}");
            disengage;
        }
        self.depth += 1;
        if self.depth > self.max_depth {
            self.log.append(f"depth limit hit at {here.name}");
            self.deferred.append(here.name);
            disengage;
        }
        if here.name in self.guard {
            self.log.append(f"cycle detected at {here.name}");
            self.deferred.append(here.name);
            disengage;
        }
        self.guard.append(here.name);
        self.log.append(f"resolving param {here.name} ({here.kind})");
        visit [->:Constrains:->];
    }

    can check_constraints with Constraint entry {
        passed = here.valid;
        verdict = "valid" if passed else "invalid";
        line = f"constraint '{here.expr}' -> {verdict}";
        if not passed {
            line = f"{line}: {here.reason}";
        }
        self.log.append(line);
        visit [->:Depends:->];
    }

    can record_concrete with ConcreteType entry {
        self.log.append(f"concrete type resolved: {here.name} (base={here.base})");
        visit [-->];
    }
}

