    T = Param(name="T", kind="type");
    U = Param(name="U", kind="type");
    V = Param(name="V", kind="type");
    W = Param(name="W", kind="type");

    same_kind = Constraint(expr="T == U", valid=True);
    numeric = Constraint(expr="is_numeric(T)", valid=False, reason="T is unbound");
