    c2 = Constraint(expr="P2 == P1", valid=True);

    root ++> p1;
    p1 +>:Constrains:+> c1;
    c1 +>:Depends:+> p2;
    p2 +>:Constrains:+> c2;
    c2 +>:Depends:+> p1;

    resolver = Resolver(max_depth=8);
    root spawn resolver;

    assert "cycle detected at P1" in resolver.log, f"got {resolver.log}";
    assert len(resolver.deferred) == 1, f"got {resolver.deferred}";
    assert "P1" in resolver.deferred, f"got {resolver.deferred}";
}

test "records invalid constraint diagnostics" {
    param_u = Param(name="U");
    invalid = Constraint(
        expr="is_numeric(U)",
        valid=False,
        reason="U is unbound"
    );

    root ++> param_u;
    param_u +>:Constrains(weight=2):+> invalid;

    resolver = Resolver();
    root spawn resolver;

    assert len(resolver.log) == 2, f"got {resolver.log}";
    assert "resolving param U (type)" in resolver.log, f"got {resolver.log}";
    assert "constraint 'is_numeric(U)' -> invalid: U is unbound" in resolver.log, f"got {resolver.log}";
    assert len(resolver.deferred) == 0, f"got {resolver.deferred}";
}

