"""PeakATail Stage 1d: IP-filter window, strand asymmetry, and per-site bookkeeping.

Models the essential scenario from issue #95: cleavage sites on plus/minus strands,
internal-priming windows that are strand-asymmetric, a pas catalog that drops zero-count
gene-assigned sites, and a unified-bed column-5 bug where the first merged member's count
is emitted instead of cohort-level support. A walker audits a small dataset and reports
each defect class.
"""

node CleavageSite {
    has chrom: str = "";
    has pos: int = 0;           # 1-based cleavage coordinate
    has strand: str = "";       # "+" or "-"
    has a_run_len: int = 0;     # observed A-run length in the IP window
    has is_novel: bool = False; # atlas-novel vs atlas-known
    has clip_umis: int = 0;     # tier-1 clip molecule count
}

node PASRecord {
    has pas_id: str = "";
    has gene: str = "";
    has clip_umis: int = 0;     # post-CB-filter count
    has in_annotatedpas: bool = True;
}

node UnifiedPAS {
    has unified_id: str = "";
    has first_member_umis: int = 0;    # bug: bedtools merge -o first emits this
    has cohort_clip_umis_sum: int = 0; # correct: sum across merged members
    has any_tier1: bool = False;
}

edge OnStrand {
    has label: str = "";
}

edge MergedInto {
    has order: int = 0;
}

walker IPAuditor {
    has wrong_window_count: int = 0;
    has zero_count_dropped: int = 0;
    has wrong_col5_count: int = 0;
    has audited: list[str] = [];

    can start with Root entry {
        print("Stage 1d audit: strand-asymmetric IP window, zero-count drops, unified col5");
        visit [-->];
    }

    can audit_site with CleavageSite entry {
        # Section 1 of the issue: legacy window [-10, +30) genomic is applied to both
        # strands. On the minus strand the A-stretch that primes oligo-dT is
        # transcript-upstream, so the window tests the wrong side. A strand-aware
        # window would flip to [-30, +10) genomic and scan the reverse complement.
        window_ok = (here.strand == "+" and here.a_run_len <= 30)
            or (here.strand == "-" and here.a_run_len <= 10);
        if not window_ok {
            self.wrong_window_count += 1;
            self.audited.append(
                f"[IP-WINDOW] {here.chrom}:{here.pos}{here.strand} "
                f"a_run={here.a_run_len} tested wrong side"
            );
        }
        # Section 4 addendum: atlas-novel + IP-passing sites are 24.5% decoys on
        # Kinnex. The legacy loose rule (>=6 A or >=70% A) misses the tighter
        # downstream +1..+18 class. Flag them so the re-benchmark can find them.
        if here.is_novel and here.a_run_len >= 6 {
            self.audited.append(
                f"[KINNEX-DECOY?] {here.chrom}:{here.pos}{here.strand} "
                f"novel + a_run={here.a_run_len}"
            );
        }
        visit [-->];
    }

    can audit_pas with PASRecord entry {
        # Section 3.2: pasbed.bed silently drops gene-assigned PAS with zero counts
        # after the CB filter. We model the drop as "in_annotatedpas=True but
        # clip_umis=0", which a correct sink would still emit.
        if here.in_annotatedpas and here.clip_umis == 0 {
            self.zero_count_dropped += 1;
            self.audited.append(
                f"[ZERO-DROP] {here.pas_id} gene={here.gene} dropped from pasbed"
            );
        }
        visit [-->];
    }

    can audit_unified with UnifiedPAS entry {
        # Section 3.4: unified/multi_sample_merged.bed col 5 is the FIRST merged
        # member's clip-molecule count, not cohort support. The correct column 5
        # is the cohort sum; a tier-1 + tier-2 merge should still carry any_tier1.
        if here.first_member_umis != here.cohort_clip_umis_sum {
            self.wrong_col5_count += 1;
            self.audited.append(
                f"[COL5-BUG] {here.unified_id} first={here.first_member_umis} "
                f"cohort_sum={here.cohort_clip_umis_sum} any_tier1={here.any_tier1}"
            );
        }
        visit [-->];
    }
}

with entry {
    # A small mixed-strand catalog: two plus sites (one known, one novel with a
    # suspicious A-run), one minus site that would be mis-tested by the legacy
    # window, and the bookkeeping artifacts the issue flags.
    plus_known = CleavageSite(
        chrom="chr1", pos=1000, strand="+",
        a_run_len=4, is_novel=False, clip_umis=120
    );
    plus_novel = CleavageSite(
        chrom="chr1", pos=2500, strand="+",
        a_run_len=8, is_novel=True, clip_umis=42
    );
    minus_suspicious = CleavageSite(
        chrom="chr2", pos=750, strand="-",
        a_run_len=25, is_novel=True, clip_umis=17
    );

    # pasbed drop: gene-assigned, in annotatedpas, but zero clip UMIs after CB filter.
    dropped_zero = PASRecord(
        pas_id="pas:chr1:3000:+", gene="GENE_X",
        clip_umis=0, in_annotatedpas=True
    );
    kept_nonzero = PASRecord(
        pas_id="pas:chr1:3050:+", gene="GENE_X",
        clip_umis=9, in_annotatedpas=True
    );

    # Unified PAS where first-member count != cohort sum: classic col-5 defect.
    unified_bad = UnifiedPAS(
        unified_id="u:chr3:4000:+",
        first_member_umis=5,           # what bedtools merge -o first emits
        cohort_clip_umis_sum=137,       # what column 5 SHOULD carry
        any_tier1=True
    );

    root +>:OnStrand(label="catalog"):+> plus_known
        +>:OnStrand:+> plus_novel
        +>:OnStrand:+> minus_suspicious;
    root +>:OnStrand(label="pasbed"):+> dropped_zero
        +>:OnStrand:+> kept_nonzero;
    root +>:MergedInto(order=0):+> unified_bad;

    auditor = IPAuditor();
    root spawn auditor;

    print(f"\n--- Stage 1d audit summary ---");
    print(f"wrong-window sites flagged: {auditor.wrong_window_count}");
    print(f"zero-count PAS dropped:     {auditor.zero_count_dropped}");
    print(f"unified-bed col5 wrong:     {auditor.wrong_col5_count}");
    print(f"total findings:             {len(auditor.audited)}");
    for note in auditor.audited {
        print(f"  {note}");
    }
}

