import io;
import from contextlib { redirect_stdout }

test "dependency stages complete after prerequisites" {
    intake = Stage(name="intake+intelligence", duration=10);
    review = Stage(name="review+security-audit", duration=15);
    checks = Stage(name="test+docs", duration=12);
    deploy = Stage(name="deploy", duration=8);

    review +>:Depends(reason="intake before review"):+> intake;
    checks +>:Depends(reason="review before test"):+> review;
    deploy +>:Depends(reason="all green before ship"):+> checks;

    root ++> intake;
    root ++> review;
    root ++> checks;
    root ++> deploy;

    res = root spawn Scheduler();

    assert len([root-->]) == 4, f"got {len([root-->])} root stages";
    assert intake in [review ->:Depends:->], f"missing intake dependency";
    assert review in [checks ->:Depends:->], f"missing review dependency";
    assert checks in [deploy ->:Depends:->], f"missing test dependency";
    assert intake.status == "done", f"intake status={intake.status}";
    assert review.status == "done", f"review status={review.status}";
    assert checks.status == "done", f"test status={checks.status}";
    assert deploy.status == "done", f"deploy status={deploy.status}";
    assert res.wave_count == 4, f"got {res.wave_count} completed stages";
}

test "independent stages are all released" {
    intake = Stage(name="intake+intelligence", duration=10);
    audit = Stage(name="security-audit", duration=15);
    docs = Stage(name="docs", duration=12);

    root ++> intake;
    root ++> audit;
    root ++> docs;

    res = root spawn Scheduler();

    assert len([root-->]) == 3, f"got {len([root-->])} direct stages";
    assert intake.status == "done", f"intake status={intake.status}";
    assert audit.status == "done", f"audit status={audit.status}";
    assert docs.status == "done", f"docs status={docs.status}";
    assert res.wave_count == 3, f"got {res.wave_count} completed stages";
}

test "dependency cycle is detected" {
    first = Stage(name="first");
    second = Stage(name="second");

    first +>:Depends(reason="first waits for second"):+> second;
    second +>:Depends(reason="second waits for first"):+> first;
    root ++> first;

    res = root spawn CycleCheck();

    assert first in [second ->:Depends:->], f"missing reverse dependency";
    assert second in [first ->:Depends:->], f"missing forward dependency";
    assert res.found_cycle == True, f"found_cycle={res.found_cycle}";
}

test "parallel failures appear in unified report" {
    lint = Stage(name="lint", status="failed", error="lint failed");
    security = Stage(name="security", status="failed", error="audit failed");

