    root ++> security;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Aggregate();
    }
    out = buf.getvalue();

    assert "[report] lint status=failed err=lint failed" in out, f"report={out}";
    assert "[report] security status=failed err=audit failed" in out, f"report={out}";
}

