"""Memory leak from recursive show-rule expansion over matrix show rules.

Models the essential scenario from typst/typst issue #8066: a show rule
that expands a math.mat into another math.mat (self-referential rewrite)
will be re-applied by the engine, so the rewrite graph grows without bound.

We model the document tree, the rewrite rules, and the application of those
rules as a graph. A walker attempts to apply the show rule repeatedly; an
explicit cycle / depth policy is required because walkers in jac 0.36.1 do
not deduplicate revisits on cyclic graphs (probe-verified). The bug is
reproduced by the un-guarded walker blowing past the depth cap; the fixed
walker enforces the cap and refuses to expand once the rule is known to
be self-referential.
"""

# --- Entity archetypes ----------------------------------------------------

node DocNode {
    has label: str = "";
    has depth: int = 0;
}

node MatNode(DocNode) {
    has rows: int = 0;
}

node RuleNode {
    has rule_name: str = "";
    has target: str = "";
    has is_self_referential: bool = False;
}

# --- Relationship archetypes ---------------------------------------------

# A show rule applies to a given node kind.
edge AppliesTo {
    has priority: int = 0;
}

# A show rule rewrites a node into another node.
edge RewritesTo {
    has applied_count: int = 0;
}

# Document tree parent/child containment.
edge Contains { }

# --- Walker: applies show rules recursively -----------------------------

walker ShowApplier {
    has max_depth: int = 16;
    has budget: int = 0;
    has visited_rules: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can descend with DocNode entry {
        self.budget += 1;
        if self.budget > self.max_depth {
            print(
                f"[LEAK] exceeded depth cap at "
                f"depth={self.budget}, label={here.label}; "
                f"this mirrors the OOM growth in #8066"
            );
            disengage;
        }
        # First, recurse into any contained children.
        visit [-->];
    }

    can apply_rule with MatNode entry {
        # Find the show rule that targets this kind of node.
        visit [->:AppliesTo:->];
    }

    can fire_rule with RuleNode entry {
        # Cycle guard: if we have already tried this rule on this branch,
        # refuse to expand again -- this is the fix for the self-referential
        # `show math.mat: it => math.mat(it.rows)` case.
        already = False;
        for name in self.visited_rules {
            if name == here.rule_name {
                already = True;
            }
        }
        if already {
            print(
                f"[FIX] rule '{here.rule_name}' already applied on this "
                f"branch; refusing to re-expand (breaks the recursion)"
            );
            disengage;
        }
        self.visited_rules.append(here.rule_name);

        if here.is_self_referential {
            print(
                f"[FIX] rule '{here.rule_name}' is self-referential "
                f"(target='{here.target}'); one application is enough"
            );
            disengage;
        }

        # Otherwise, walk every rewrite the rule produces and continue.
        visit [->:RewritesTo:->];
    }
}

# --- Demo wiring ---------------------------------------------------------

with entry {
    # A self-referential show rule: math.mat -> math.mat(it.rows).
    # This is exactly the pattern from the bug report.
    mat_rule = RuleNode(
        rule_name="show_math_mat",
        target="math.mat",
        is_self_referential=True,
