# The unmitigated walker mirrors the reported OOM: it grows
# rendered_bytes by ~1 MiB per step and disengages only when the
# explicit cap is hit.
# ---------------------------------------------------------------------------

test "unguarded walker grows rendered_bytes until cap" {
    m = Matrix(name="leaky", rows=1);
