    has order: list[str] = [];
    has indegree: dict[str, int] = {};
    has dependents: dict[str, list[str]] = {};
    has remaining: int = 0;

    can plan with Root entry {
        # Collect all milestones reachable from root via the typed
        # SequenceLink edges. This replaces the hand-rolled glob + sort
        # over NN-* prefixes: we walk the declared graph instead.
        self._collect(here);
        self._topo_sort();
        print(f"Execution order: {self.order}");
        if self.remaining != 0 {
