        here.completed = True;
        print(f"[run] {here.name} :: hint={here.hint!r}");
        visit [->:SequenceLink:->];
    }

    def _collect(root_node: Milestone | Root) -> None {
        for m in [->:SequenceLink:->] {
            self.remaining += 1;
            self.indegree[m.name] = self.indegree.get(m.name, 0);
            self.dependents[m.name] = [];
        }
        for m in [->:SequenceLink:->] {
            for dep in [->:DependsOn:->] {
                self.indegree[m.name] = self.indegree.get(m.name, 0) + 1;
                deps = self.dependants_get(dep.name);
                deps.append(m.name);
            }
        }
    }

    def dependants_get(name: str) -> list[str] {
        existing = self.dependents.get(name);
        if existing is None {
            self.dependents[name] = [];
            return self.dependents[name];
        }
        return existing;
    }

    def _topo_sort() -> None {
        ready: list[str] = [];
        for (name, deg) in self.indegree.items() {
            if deg == 0 {
                ready.append(name);
            }
        }
        idx = 0;
        while idx < len(ready) {
            current = ready[idx];
            idx += 1;
            self.order.append(current);
            outs = self.dependents.get(current);
            if outs is None {
                continue;
            }
            for nxt in outs {
                new_deg = self.indegree[nxt] - 1;
                self.indegree[nxt] = new_deg;
                if new_deg == 0 {
                    ready.append(nxt);
                }
            }
        }
        self.remaining = len(self.indegree) - len(self.order);
    }
}

