    has name: str = "";
    has prompt: str = "";
    has verify: str = "";
    has generate: str = "";
    has hint: str = "";
    has completed: bool = False;
}

node Manifest {
    has sequence: list[str] = [];
    has completed_set: list[str] = [];
}

