    has visited: list[str] = [];

    can begin with Root entry {
        visit [->:Sequence:->];
    }

    can prepare with Manifest entry {
        print(f"--- setup hook: reading manifest with {len(here.sequence)} entries ---");
        visit [->:Sequence:->];
    }

    can precheck with Milestone entry {
        self.visited.append(here.name);
        status = "DONE" if here.completed else "PENDING";
        print(f"  setup: {here.name} -> {status}");
        visit [->:DependsOn:->];
    }
}

walker Runner {
    has order: list[str] = [];
    has log: list[str] = [];

    can begin with Root entry {
        visit [->:Sequence:->];
    }

    can dispatch with Manifest entry {
        print(f"--- runner: dispatching in declared order ---");
        visit [->:Sequence:->];
    }

    can run with Milestone entry {
        # dependency check: ensure any DependsOn targets are already done
        deps = [here];
        visit [->:DependsOn:->];
        for d in deps {
            if d.completed {
                self.log.append(f"dep {d.name} ok");
            } else {
                self.log.append(f"BLOCKED by {d.name}");
                return;
            }
        }
        self.order.append(here.name);
        print(f"  run: {here.name} (verify={here.verify})");
        here.completed = True;
        visit [->:RunsBefore:->];
    }

    can propagate with Milestone entry {
        # an Invalidates edge means: when this milestone completed, any
        # successor linked by Invalidates must drop its completed flag.
        here.completed = False;
        self.log.append(f"INVALIDATED {here.name}");
    }

