"""Regression tests for the roadmap walker demo.

The program models a versioned roadmap with typed edges
(DependsOn, Blocks, MigratesTo). Two walkers exercise it:

- RoadmapAuditor: cascade-invalidation starting from a deprecation target,
  with an explicit cycle guard.
- DependencySweeper: topological-style ranking via typed-edge traversal,
  with explicit dedupe.

These tests exercise the BEHAVIOR the issue describes — typed graph
traversal, cascade invalidation along typed edges, dedupe, and ordering —
not incidental printing details.
"""

import io;
import from contextlib { redirect_stdout }

# Shared fixtures ---------------------------------------------------

def build_roadmap {
    # Construct an isolated root so each test owns its graph.
    rt = root;

    cost_routing = Feature(
        title="Cost-Aware Routing",
        version="v0.8.0",
        status="completed",
        notes="tier-based embedding provider selection",
    );
    kg_layer = Feature(
        title="Knowledge Graph Layer",
        version="v0.7.0",
        status="completed",
        notes="entity extraction, typed relationships, graph traversal",
    );
    session_pipe = Feature(
        title="Session->Memory Pipeline",
        version="v0.6.0",
        status="completed",
        notes="native fact extraction in on_session_end",
    );
    supersession = Feature(
        title="Auto-Supersession",
        version="v0.5.1",
        status="completed",
        notes="similarity > 0.90",
    );
    guardrails = Feature(
        title="Active Guardrails",
        version="v0.5.0",
        status="completed",
        notes="memory-driven prevention of destructive actions",
    );
    sica = Feature(
        title="SICA Self-Improvement",
        version="v0.9.0",
        status="open",
        notes="LLM-assisted memory consolidation",
    );
    neo4j = Feature(
        title="Neo4j Backend",
        version="v1.0.0",
        status="future",
        notes="migrate graph layer at ~100K entities",
    );

    rt ++> cost_routing
        ++> kg_layer
        ++> session_pipe
        ++> supersession
        ++> guardrails;
    rt ++> sica;
    rt ++> neo4j;

    sica +>:DependsOn(strength="hard"):+> kg_layer;
    sica +>:DependsOn(strength="hard"):+> guardrails;
    kg_layer +>:Blocks(reason="Qdrant under threshold"):+> neo4j;
    sica +>:Blocks(reason="uses current graph API"):+> neo4j;
    neo4j +>:MigratesTo(threshold="100K entities"):+> kg_layer;

    return (
        rt, cost_routing, kg_layer, session_pipe, supersession,
        guardrails, sica, neo4j,
    );
}

# -------------------------------------------------------------------

test "auditor marks the named deprecation target as deprecated" {
    (rt, _cr, _kg, _sp, _su, _gr, _si, neo4j) = build_roadmap();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = RoadmapAuditor(deprecation_target="Neo4j Backend");
        rt spawn auditor;
    }

    assert neo4j.deprecated == True,
        f"Neo4j Backend should be flagged deprecated, got {neo4j.deprecated}";
    assert "DEPRECATED: Neo4j Backend" in buf.getvalue(),
        f"missing DEPRECATED marker in auditor output: {buf.getvalue()}";
}

test "auditor does not deprecate features that are not the target" {
    (rt, _cr, kg_layer, _sp, _su, _gr, sica, _neo) = build_roadmap();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = RoadmapAuditor(deprecation_target="Neo4j Backend");
        rt spawn auditor;
    }

    assert kg_layer.deprecated == False,
        f"KG Layer should remain non-deprecated, got {kg_layer.deprecated}";
    assert sica.deprecated == False,
        f"SICA should remain non-deprecated, got {sica.deprecated}";
}

test "typed edges are present in the expected directions" {
    (rt, _cr, kg_layer, _sp, _su, _gr, sica, neo4j) = build_roadmap();

    # SICA depends on KG Layer (hard)
    deps_from_sica = [sica ->:DependsOn:->];
    assert kg_layer in deps_from_sica,
        f"KG Layer should be a DependsOn target of SICA, got {deps_from_sica}";

    # KG Layer blocks Neo4j migration
    blocks_from_kg = [kg_layer ->:Blocks:->];
    assert neo4j in blocks_from_kg,
        f"Neo4j should be a Blocks target of KG Layer, got {blocks_from_kg}";

    # SICA also blocks Neo4j
    blocks_from_sica = [sica ->:Blocks:->];
    assert neo4j in blocks_from_sica,
        f"Neo4j should be a Blocks target of SICA, got {blocks_from_sica}";

    # Neo4j migrates to KG Layer
    migrates_from_neo = [neo4j ->:MigratesTo:->];
    assert kg_layer in migrates_from_neo,
        f"KG Layer should be a MigratesTo target of Neo4j, got {migrates_from_neo}";

    # Reverse edges must NOT exist.
    assert kg_layer not in [sica ->:Blocks:->],
        "KG Layer must NOT have a Blocks edge back to SICA";
    assert kg_layer not in [neo4j ->:Blocks:->],
        "KG Layer must NOT have an incoming Blocks edge from Neo4j";
}

test "dependency sweeper ranks features without duplicates" {
    (rt, _cr, kg_layer, _sp, _su, _gr, sica, neo4j) = build_roadmap();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        sweeper = DependencySweeper();
        rt spawn sweeper;
    }

    # No duplicate ranks in walker output.
    order = sweeper.order;
    assert len(order) == len(set(order)),
        f"sweeper order contains duplicates: {order}";

    # Every roadmap feature is reachable from Root via typed edges.
    titles = {f.title for f in [
        _cr, kg_layer, _sp, _su, _gr, sica, neo4j,
    ]};
    reached = set(order);
    assert titles <= reached,
        f"missing features in sweep order: {titles - reached}";

    # SICA must precede KG Layer because SICA DependsOn KG Layer,
    # and the walker visits DependsOn targets first.
    assert order.index("SICA Self-Improvement") < order.index(
        "Knowledge Graph Layer"
    ), f"SICA must come before KG Layer in dependency order, got {order}";
}

test "cascade reaches downstream blockers along typed Blocks edges" {
    (rt, _cr, kg_layer, _sp, _su, _gr, sica, neo4j) = build_roadmap();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = RoadmapAuditor(deprecation_target="Neo4j Backend");
        rt spawn auditor;
    }
    out = buf.getvalue();

    # Cascade must visit at least SICA (which Blocks Neo4j) and KG Layer
    # (which also Blocks Neo4j). The walker's fan_out prints "[OPEN]" or
    # "[COMPLETED]" status lines for non-target features.
    assert "SICA Self-Improvement" in out,
        f"SICA should be visited during cascade, got: {out}";
    assert "Knowledge Graph Layer" in out,
        f"KG Layer should be visited during cascade, got: {out}";

    # Explicit cycle guard must fire: Neo4j ->MigratesTo-> KG Layer, and
    # KG Layer ->Blocks-> Neo4j would form a loop if not guarded. The
    # walker logs "cycle skip" when re-entering a guarded node.
    assert "cycle skip" in out,
        f"expected explicit cycle-skip log, got: {out}";
}

