"""PWA metadata fetcher: model HTML/manifest/favicon sources as nodes and
walk them with a fetcher walker that gracefully handles partial failures.

The issue complained about hand-rolled dependency chains over fetched
metadata sources. Here the relationships become typed edges and a walker
traverses them, returning a typed Result that records partial success."""

# --- Result type ---------------------------------------------------------

obj FetchResult {
    has title: str = "";
    has manifest_url: str = "";
    has icon_url: str = "";
    has failures: list[str] = [];

    def is_complete() -> bool {
        return self.title != "" and self.manifest_url != "" and self.icon_url != "";
    }
}

# --- Source archetypes ---------------------------------------------------

node Page {
    has url: str = "";
    has title: str = "";
    has manifest_href: str = "";
    has favicon_href: str = "";
    has reachable: bool = True;
}

node Manifest {
    has url: str = "";
    has icon_candidates: list[str] = [];
    has reachable: bool = True;
}

node Icon {
    has url: str = "";
    has reachable: bool = True;
}

# --- Typed edges ---------------------------------------------------------

edge LinksTo { }
edge Declares { }

# --- Helpers -------------------------------------------------------------

def resolve_url(base: str, ref: str) -> str {
    if ref == "" {
        return "";
    }
    if ref.startswith("http://") or ref.startswith("https://") {
        return ref;
    }
    slash = base.rfind("/");
    root_dir = base if slash < 0 else base[:slash];
    if ref.startswith("/") {
        return root_dir + ref;
    }
    return root_dir + "/" + ref;
}

# --- Walker --------------------------------------------------------------

walker MetadataFetcher {
    has result: FetchResult = FetchResult();
    has base: str = "";

    can start with Root entry {
        visit [-->];
    }

    can fetch_page with Page entry {
        if not here.reachable {
            self.result.failures.append(f"page unreachable: {here.url}");
        } else {
            self.result.title = here.title;
            self.result.manifest_url = resolve_url(here.url, here.manifest_href);
            self.result.icon_url = resolve_url(here.url, here.favicon_href);
        }
        visit [->:LinksTo:->];
    }

    can fetch_manifest with Manifest entry {
        if not here.reachable {
            self.result.failures.append(f"manifest unreachable: {here.url}");
        } else {
            best = "";
            for candidate in here.icon_candidates {
                best = resolve_url(here.url, candidate);
            }
            if best != "" {
                self.result.icon_url = best;
            }
        }
        visit [->:Declares:->];
    }

    can fetch_icon with Icon entry {
        if here.reachable {
            self.result.icon_url = here.url;
        } else {
            self.result.failures.append(f"icon unreachable: {here.url}");
        }
    }
}

# --- Demo wiring ---------------------------------------------------------

with entry {
    page_node = Page(
        url="https://example.com/index.html",
        title="Example App",
        manifest_href="/manifest.json",
        favicon_href="/favicon.ico",
        reachable=True
    );

    manifest_node = Manifest(
        url="https://example.com/manifest.json",
        icon_candidates=["icons/icon-192.png", "icons/icon-512.png"],
        reachable=True
    );

    icon_192 = Icon(url="https://example.com/icons/icon-192.png", reachable=True);
    icon_512 = Icon(url="https://example.com/icons/icon-512.png", reachable=False);

    page_node +>:LinksTo:+> manifest_node;
    manifest_node +>:Declares:+> icon_192;
    manifest_node +>:Declares:+> icon_512;

    fetcher = MetadataFetcher(base=page_node.url);
    page_node spawn fetcher;

    r = fetcher.result;
    summary = "complete" if r.is_complete() else "partial";
    print(f"[{summary}] title='{r.title}' manifest='{r.manifest_url}' icon='{r.icon_url}'");
    if r.failures {
        print(f"failures: {r.failures}");
    }
}

