}

walker DependencyCascade {
    has visited: list[str] = [];
    has depth_limit: int = 4;
    has current_depth: int = 0;

    can start with Root entry {
        print("Cascading dependency invalidation (depth-limited, cycle-safe)");
        visit [-->];
    }

    can cascade with Package entry {
        seen = False;
        for v in self.visited {
            if v == here.name {
                seen = True;
                break;
            }
