"""Test annex for the LicenseAuditor walker demo.

Covers the three behaviors the issue cares about:
  1. Non-compliant transitive licenses are flagged.
  2. Compliant licenses pass silently.
  3. Cycles in the dependency graph don't loop forever / double-flag.
"""

import io;
import from contextlib { redirect_stdout }

test "flags non-compliant transitive licenses" {
    # Minimal graph with one MIT root, one MIT child, and one
    # GPL transitive grandchild.  Both the GPL node and any other
    # non-allowlisted dep must show up in flagged.
    root ++> Package(name="DateExt", version="1.0.0", license="MIT");
    gpl_dep = Package(name="GplThing", version="1.0.0", license="GPL-3.0");
    dateext_node = [root -->][?:Package][0];
    dateext_node +>:DependsOn:+> Package(name="OkDep", version="1.0.0", license="MIT");
    dateext_node +>:DependsOn:+> gpl_dep;
    gpl_dep +>:DependsOn:+> Package(name="AgplHelper", version="0.1.0", license="AGPL-3.0");

    auditor = LicenseAuditor();
    root spawn auditor;

    assert len(auditor.flagged) == 2, f"expected 2 flags, got {auditor.flagged}";
    flagged_names = [t[1] for t in auditor.flagged];
    assert "GplThing" in flagged_names, f"GplThing missing from flags: {flagged_names}";
    assert "AgplHelper" in flagged_names, f"AgplHelper missing from flags: {flagged_names}";

    # Every finding is attributed to the project being shipped.
    for triple in auditor.flagged {
        assert triple[0] == "DateExt", f"wrong root attribution: {triple}";
        assert triple[2] not in auditor.allowed, f"flagged an allowed license: {triple}";
    }
}

test "compliant deps are not flagged" {
    # A graph made entirely of allowlisted licenses.  Nothing should
    # land in `flagged`, and every package should appear in `visited`.
    root ++> Package(name="DateExt", version="1.0.0", license="MIT");
    rt = [root -->][?:Package][0];
    rt +>:DependsOn:+> Package(name="Tz", version="2.0.0", license="Apache-2.0");
    rt +>:DependsOn:+> Package(name="Cal", version="1.0.0", license="BSD-3-Clause");
    [rt ->:DependsOn:->][0] +>:DependsOn:+> Package(name="CalCore", version="0.5.0", license="MIT");

    auditor = LicenseAuditor();
    root spawn auditor;

    assert auditor.flagged == [], f"compliant graph produced flags: {auditor.flagged}";
    assert len(auditor.visited) == 4, f"expected 4 visited, got {auditor.visited}";
    assert "DateExt" in auditor.visited, "root not visited";
    assert "Tz" in auditor.visited, "Tz not visited";
    assert "Cal" in auditor.visited, "Cal not visited";
    assert "CalCore" in auditor.visited, "transitive CalCore not visited";
}

test "custom allowlist is honored" {
    # The walker carries its own allowlist.  A narrower allowlist
    # that excludes BSD-3-Clause should flag a BSD-3 node but still
    # pass MIT.
    root ++> Package(name="DateExt", version="1.0.0", license="MIT");
    rt = [root -->][?:Package][0];
    rt +>:DependsOn:+> Package(name="MitDep", version="1.0.0", license="MIT");
    rt +>:DependsOn:+> Package(name="BsdDep", version="1.0.0", license="BSD-3-Clause");

    auditor = LicenseAuditor(allowed=["MIT"]);
    root spawn auditor;

    assert len(auditor.flagged) == 1, f"expected exactly 1 flag, got {auditor.flagged}";
    assert auditor.flagged[0][1] == "BsdDep", f"wrong dep flagged: {auditor.flagged}";
    assert auditor.flagged[0][2] == "BSD-3-Clause", f"wrong license reported: {auditor.flagged}";
}

test "cycles do not loop or double-flag" {
    # A -> B -> A.  Without the visited guard this would be infinite.
    # With it, each node is audited at most once and each non-compliant
    # node is flagged at most once.
    root ++> Package(name="DateExt", version="1.0.0", license="MIT");
    rt = [root -->][?:Package][0];
    a = Package(name="A", version="1.0.0", license="GPL-3.0");
    b = Package(name="B", version="1.0.0", license="AGPL-3.0");
    rt +>:DependsOn:+> a;
    a +>:DependsOn:+> b;
    b +>:DependsOn:+> a;

    buf = io.StringIO();
    auditor = LicenseAuditor();
    with redirect_stdout(buf) {
        root spawn auditor;
    }
    out = buf.getvalue();

    # Each non-compliant node audited exactly once -> exactly two flags.
    assert len(auditor.flagged) == 2, f"cycle caused wrong flag count: {auditor.flagged}";
    flagged_names = [t[1] for t in auditor.flagged];
    assert flagged_names.count("A") == 1, f"A flagged more than once: {flagged_names}";
    assert flagged_names.count("B") == 1, f"B flagged more than once: {flagged_names}";

    # The verdict lines for A and B each appear exactly once in stdout.
    a_lines = [ln for ln in out.splitlines() if "[FLAG] A@1.0.0" in ln];
    b_lines = [ln for ln in out.splitlines() if "[FLAG] B@1.0.0" in ln];
    assert len(a_lines) == 1, f"A audited {len(a_lines)} times, output:\n{out}";
    assert len(b_lines) == 1, f"B audited {len(b_lines)} times, output:\n{out}";

    # visited has no duplicates -- every package audited at most once.
    assert len(auditor.visited) == len(set(auditor.visited)), (
        f"visited contains duplicates: {auditor.visited}"
    );
}

