"""License audit on transitive dependencies.

Models the essential scenario from issue #84: a project's package manifest
pulls in transitive dependencies, each of which declares a license. A
walker crawls the dependency graph, classifies each package's license
against an allowlist, and reports findings.
"""

node Package {
    has name: str = "";
    has version: str = "";
    has license: str = "";
    has approved: bool = False;
    has audited: bool = False;
    has blocked: bool = False;
    has reason: str = "";
}

node AuditReport {
    has total: int = 0;
    has compatible: int = 0;
    has incompatible: int = 0;
    has unknown: int = 0;
}

edge DependsOn { }
edge Reports { }

walker LicenseAuditor {
    has allowlist: list[str] = [];
    has visited: list[str] = [];
    has report_node: AuditReport = AuditReport();

    def classify(license: str) -> str {
        normalized = license.strip().upper();
        if normalized == "" {
            return "unknown";
        }
        approved = False;
        for entry in self.allowlist {
            if entry.upper() == normalized {
                approved = True;
            }
        }
        if approved {
            return "compatible";
        }
        return "incompatible";
    }

    def already_seen(name: str) -> bool {
        seen = False;
        for v in self.visited {
            if v == name {
                seen = True;
            }
        }
        return seen;
    }

    can start with Root entry {
        visit [-->];
    }

    can audit with Package entry {
        if self.already_seen(here.name) {
            visit [-->];
            return;
        }
        self.visited.append(here.name);
        verdict = self.classify(here.license);
        self.report_node.total += 1;
        if verdict == "compatible" {
            here.approved = True;
            here.audited = True;
            self.report_node.compatible += 1;
            print(f"[OK]   {here.name}@{here.version} -> {here.license}");
        } elif verdict == "incompatible" {
            here.audited = True;
            here.blocked = True;
            here.reason = "license not in allowlist";
            self.report_node.incompatible += 1;
            print(f"[FAIL] {here.name}@{here.version} -> {here.license} (gates build)");
