    has name: str = "";
    has version: str = "";
    has license: str = "";
    has approved: bool = False;
}

edge DependsOn {
    has scope: str = "runtime";
}

walker LicenseAuditor {
    has visited: list[str] = [];
    has allowlist: list[str] = ["MIT", "Apache-2.0", "BSD-2-Clause", "BSD-3-Clause"];
    has findings: list[str] = [];

    can start with Root entry {
        print("Starting license audit of transitive dependency graph");
        visit [-->];
    }

    can audit with Package entry {
        # Cycle guard: explicit in walker (jac 0.36.1 has no built-in once-per-node).
        if here.name in self.visited {
            print(f"  [skip] {here.name} already audited (cycle guard)");
            disengage;
        }
        self.visited.append(here.name);

        verdict = self.classify(here);
        marker = "OK" if verdict == "allow" else "FLAG";
        print(f"  [{marker}] {here.name}@{here.version} :: {here.license} -> {verdict}");
        if verdict != "allow" {
            note = f"{here.name}@{here.version} ({here.license}) is {verdict}";
            self.findings.append(note);
        }

        # Walk transitive dependencies via typed edge.
        visit [->:DependsOn:->];
    }

    def classify(pkg: Package) -> str {
        declared = pkg.license;
        if declared == "" {
            return "unknown";
        }
        if declared in self.allowlist {
            return "allow";
        }
        if declared in ["GPL-3.0", "AGPL-3.0", "OSL-3.0", "BUSL-1.1"] {
            return "incompatible";
        }
        return "unknown";
    }
}

