    newtonsoft = Package(name="Newtonsoft.Json", version="13.0.3", license="MIT", approved=True);
    cliwrap = Package(name="CliWrap", version="3.7.0", license="MIT", approved=True);

    # Transitive: one clean Apache dep, one problematic GPL dep reached via two paths.
    system_text_encodings_web = Package(name="System.Text.Encoding.Web", version="7.0.0",
                                         license="Apache-2.0", approved=True);
    gpl_leak = Package(name="GPLLeak", version="0.1.0", license="GPL-3.0", approved=False);

    # Another transitive of unknown license to demonstrate the unknown bucket.
    mystery_pkg = Package(name="MysteryPkg", version="0.0.1", license="", approved=False);

    # Build the dependency tree. Use typed edges so the auditor can scope its walk.
    root ++> app;
    app +>:DependsOn(scope="direct"):+> serilog;
    app +>:DependsOn(scope="direct"):+> newtonsoft;
    app +>:DependsOn(scope="direct"):+> cliwrap;
    serilog +>:DependsOn(scope="transitive"):+> system_text_encodings_web;
    newtonsoft +>:DependsOn(scope="transitive"):+> gpl_leak;
    # Second path to the GPL leak to exercise the cycle/visited guard.
    cliwrap +>:DependsOn(scope="transitive"):+> gpl_leak;
    serilog +>:DependsOn(scope="transitive"):+> mystery_pkg;

    auditor = LicenseAuditor();
    root spawn auditor;

    print(f"\nAudit complete: visited {len(auditor.visited)} packages, "
          f"{len(auditor.findings)} flagged");
    for finding in auditor.findings {
        print(f"  - {finding}");
    }
    print("\nRequired action: reviewer approval recorded in PR for any non-allowlisted license.");
}

