flag any package whose declared license is not on the project allowlist.

Models issue #86: a project ships under MIT, but a transitive dependency
could silently pull in GPL/AGPL/OSL/BSL. A walker performs the recursive
enumeration that the issue describes and reports every package whose
license falls outside the documented allowlist."""

node Package {
    has name: str = "";
    has version: str = "";
    has license: str = "";
    has approved: bool = False;
}

node License {
    has spdx_id: str = "";
    has compatible: bool = False;
}

edge DependsOn { has scope: str = "transitive"; }
edge Allows { }

walker LicenseAuditor {
    has project_license: str = "MIT";
    has audited: list[str] = [];
    has flagged: list[str] = [];

    can start with Root entry {
        print(f"Auditing transitive deps for project under {self.project_license}");
        visit [-->];
    }

    can walk_deps with Package entry {
        if here.name in self.audited {
            visit [-->];
        }
        self.audited.append(here.name);
        label = "OK" if here.approved else "FLAG";
        line = f"[{label}] {here.name}@{here.version} -> {here.license}";
        print(line);
        if not here.approved {
            self.flagged.append(line);
        }
        visit [-->];
    }

    can visit_licenses with License entry {
        status = "ALLOWED" if here.compatible else "BLOCKED";
        print(f"  license {here.spdx_id}: {status}");
    }

    can summarize with Root entry {
        print("--- AUDIT SUMMARY ---");
        print(f"project license: {self.project_license}");
        print(f"packages audited: {len(self.audited)}");
        print(f"flagged packages: {len(self.flagged)}");
        for entry in self.flagged {
            print(f"  * {entry}");
        }
        visit [-->] else { disengage; }
    }
}

