import io;
import from contextlib { redirect_stdout }

test "cascade recomputes dirty ops and skips clean ops" {
    doc = Document(name="Doc1");
    job = Job(label="J1");
    tc = ToolController(label="TC");
    op_clean = Operation(label="CleanOp", last_exec_ms=500);
    op_dirty = Operation(label="DirtyOp", last_exec_ms=300);

    doc +>:Owns:+> job;
    job +>:Owns:+> tc;
    tc +>:Owns:+> op_clean;
    tc +>:Owns:+> op_dirty;
    op_dirty.dirty = True;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = doc spawn RecomputeCascade();
    }
    out = buf.getvalue();

    assert "DirtyOp" in out, f"dirty op should be reported: {out}";
    assert "CleanOp" in out, f"clean op should still be visited: {out}";
    assert res.recomputed_count >= 1, (
        f"dirty op must increment recomputed_count, got {res.recomputed_count}"
    );
    assert res.skipped_count >= 1, (
        f"clean op must increment skipped_count, got {res.skipped_count}"
    );
    assert op_dirty.dirty == False, "dirty flag must be cleared after recompute";
    assert op_clean.dirty == False, "clean op untouched";
}

