"""Test annex for the Dancer2 LSP conformance tracker."""

import io;
import from contextlib { redirect_stdout }

test "positive fixture is fully audited with all route kinds and refs" {
    root ++> DancerApp(appname="HelloWorld");
    app = [root -->][0];
    app +>:DeclaresRoute:+> Route(method="get", pattern="/hello", arity=2);
    app +>:DeclaresRoute:+> Route(method="post", pattern="/submit", arity=3);
    app +>:DeclaresRoute:+> Route(method="any", pattern="/any", arity=2, route_kind="any");
    app +>:DeclaresRoute:+> Route(method="get", pattern=r"^/items/(\d+)$", route_kind="regex");
    app +>:DeclaresRoute:+> Route(method="get", pattern="/named", is_named=True, route_name="show_named");
    app +>:DeclaresHook:+> Hook(hook_name="before_request", hook_kind="canonical");
    app +>:DeclaresHook:+> Hook(hook_name="init", hook_kind="alias");
    app +>:ReferencesRoute:+> RouteRef(target_name="show_named", ref_kind="literal", safe_for_rename=True);
    app +>:ReferencesRoute:+> RouteRef(target_name="dyn_target", ref_kind="dynamic", safe_for_rename=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ConformanceAuditor();
    }
    out = buf.getvalue();

    assert "auditing Dancer2 app 'HelloWorld'" in out, f"missing app banner: {out}";
    assert res.route_count == 5, f"expected 5 routes, got {res.route_count}";
    assert res.hook_count == 2, f"expected 2 hooks, got {res.hook_count}";
    assert res.ref_count == 2, f"expected 2 refs, got {res.ref_count}";
    assert res.rejections == [], f"unexpected rejections: {res.rejections}";
    assert "route[named] get /named" in out, f"named route not labeled: {out}";
    assert "route[anon] get /hello" in out, f"anon route not labeled: {out}";
    assert "rename-safe" in out, f"rename-safe verdict missing: {out}";
    assert "refused" in out, f"refused verdict missing: {out}";
}

test "missing module is rejected with no routes tallied" {
    root ++> DancerApp(appname="Broken", missing_module=True);
    app = [root -->][0];
    app +>:DeclaresRoute:+> Route(method="get", pattern="/x");
    app +>:DeclaresHook:+> Hook(hook_name="before_request");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ConformanceAuditor();
    }
    out = buf.getvalue();

    assert "missing Dancer2" in str(res.rejections), f"expected missing-module rejection, got {res.rejections}";
    assert res.route_count == 0, f"missing-module app must not tally routes, got {res.route_count}";
    assert res.hook_count == 0, f"missing-module app must not tally hooks, got {res.hook_count}";
    assert res.ref_count == 0, f"missing-module app must not tally refs, got {res.ref_count}";
    assert "auditing" not in out, f"auditor must disengage before printing banner: {out}";
}

