    root ++> DancerApp(appname="OldApp", supported_version=False);
    app = [root -->][0];
    app +>:DeclaresRoute:+> Route(method="get", pattern="/legacy", is_named=True, route_name="legacy");
    app +>:ReferencesRoute:+> RouteRef(target_name="legacy", ref_kind="literal");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ConformanceAuditor();
    }

    assert len(res.rejections) == 1, f"expected 1 rejection, got {res.rejections}";
    assert "unsupported version" in res.rejections[0], f"wrong rejection reason: {res.rejections[0]}";
    assert "OldApp" in res.rejections[0], f"rejection must name the app: {res.rejections[0]}";
