# ---- Edge archetypes ----------------------------------------------------

edge DependsOn {
    has version_range: str = "";
}

# ---- Node archetypes ----------------------------------------------------

node Package {
    has name: str = "";
    has version: str = "";
    has license: str = "";
    has origin: str = "transitive";

    def label() -> str {
        return f"{self.name}@{self.version}";
    }

    def license_kind() -> str {
        n = self.license.lower();
        ok_markers = ["mit", "apache-2.0", "bsd-2-clause", "bsd-3-clause", "isc", "mpl-2.0"];
        blocked_markers = ["gpl", "agpl", "osl", "sspl", "bsl", "business-source", "source-available"];
        for m in blocked_markers {
            if n.find(m) != -1 {
                return "blocked";
            }
        }
        for m in ok_markers {
            if n.find(m) != -1 {
                return "ok";
            }
        }
        return "unknown";
    }
}

# A Project is the root artifact whose own license gates the audit.
node Project {
    has name: str = "";
    has license: str = "MIT";
}

# ---- Walker: descends the dependency tree, deduplicating by package ----

walker LicenseAuditor {
    has visited: list[str] = [];
    has report: list[dict] = [];
    has policy_license: str = "MIT";

    can start with Project entry {
        self.policy_license = here.license;
        print(f"Auditing transitive deps of {here.name} (shipped under {here.license})");
        # Walk direct dependencies of the project.
        visit [->:DependsOn:->];
    }

    can descend with Package entry {
        key = here.label();
        # Explicit cycle / repeat guard — walkers do not dedupe on their own.
        if key in self.visited {
            visit [->:DependsOn:->];
            return;
        }
        self.visited.append(key);

        kind = here.license_kind();
        verdict = "OK" if kind == "ok" else ("REVIEW" if kind == "unknown" else "BLOCKED");
        entry = {
            "name": here.name,
            "version": here.version,
            "license": here.license,
            "origin": here.origin,
            "verdict": verdict,
        };
        self.report.append(entry);
        marker = " " if verdict == "OK" else ("?" if verdict == "REVIEW" else "!");
        print(f"  {marker} {here.label()} [{here.license}] -> {verdict}");

        visit [->:DependsOn:->];
