def add_package(graph_root: Project, name: str, version: str, license: str) -> Package {
    p = Package(name=name, version=version, license=license, origin="transitive");
    graph_root +>:DependsOn(version_range="*") :+> p;
    return p;
}

def add_dep(parent: Package, name: str, version: str, license: str) -> Package {
    p = Package(name=name, version=version, license=license, origin="transitive");
    parent +>:DependsOn(version_range="^" + version) :+> p;
