            here.flagged = True;
        }

        entry = {
            "package": here.name,
            "version": here.version,
            "license": here.license if here.license else "<missing>",
            "verdict": verdict,
            "reason": reason,
        };
        self.report.append(entry);
        license_label = here.license if here.license else "<missing>";
