"""Regression tests for issue #1237: recursive CTE-style subquery.

The scenario models a Base-Query whose result feeds into a downstream
query. Two walkers cooperate:
  - CollectSubtree: recursively walks a ParentOf tree, gathering node ids.
  - QueryWithSubquery: filters a collection of Foo nodes by membership
    in the id set produced by CollectSubtree.

These tests assert the behavior described in the issue: the CTE walker
descends through every reachable node in the tree, and the consumer
walker only yields Foo nodes whose id appears in the collected set.
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
test "collect subtree gathers every descendant id in parent-of order" {
    rt_node = Root();
    root_node = TreeNode(id=0, name="root");
    a = TreeNode(id=1, name="a");
    b = TreeNode(id=2, name="b");
    c = TreeNode(id=3, name="c");
    d = TreeNode(id=4, name="d");
    root_node +>:ParentOf:+> a;
    a +>:ParentOf:+> b;
    a +>:ParentOf:+> c;
    c +>:ParentOf:+> d;
    rt_node ++> root_node;

    cte = CollectSubtree();
    root_node spawn cte;

    # Root plus all four descendants must be present.
    assert 0 in cte.collected_ids, f"root id missing: {cte.collected_ids}";
    assert 1 in cte.collected_ids, f"id 1 missing: {cte.collected_ids}";
    assert 2 in cte.collected_ids, f"id 2 missing: {cte.collected_ids}";
    assert 3 in cte.collected_ids, f"id 3 missing: {cte.collected_ids}";
    assert 4 in cte.collected_ids, f"id 4 missing: {cte.collected_ids}";
    assert len(cte.collected_ids) == 5,
