import io;
import from contextlib { redirect_stdout }

test "all ready produces approved decision and no pending items" {
    docker = HostCapability(title="WSL 2 + Docker Desktop operational", ready=True);
    py = PythonEnv(title="Python 3.13 + Neo4j driver 6.1.0 + pytest 9.0.2", ready=True);
    harness_spec = RepositoryGap(title="Test harness specification approved", ready=True);
