    }
    out = buf.getvalue();

    assert "[APPROVED]" in out, f"expected APPROVED marker, got: {out}";
    assert "[BLOCKED]" not in out, f"expected no BLOCKED marker, got: {out}";
    assert decision.approved == True, f"decision should be approved, got {decision.approved}";
