node Document {
    has title: str = "";
    has difficulty: int = 0;
    has routed: bool = False;
}

node LearningPath {
    has role: str = "";
    has depth: int = 0;
}

edge Contains {
    has order: int = 0;
}

walker RouteAuditor {
    has visited_docs: list = [];
    has visited_paths: list = [];
    has orphans: list = [];

    can start with Root entry {
        print("Beginning learning-path routing audit");
        visit [-->];
    }

    can audit_path with LearningPath entry {
        self.visited_paths.append(here.role);
        print(f"Path: {here.role} (depth {here.depth})");
        visit [->:Contains:->];
    }

    can audit_doc with Document entry {
        title = here.title if here.title != "" else "untitled";
        if not here.routed {
            self.orphans.append(title);
        }
        self.visited_docs.append(title);
        visit [->:Contains:->];
    }

    can collect_doc with Document entry {
        title = here.title if here.title != "" else "untitled";
        here.routed = True;
