"""ATLANTIS 7-Day Operational Alpha: a request flows through authorization,
normalization, planning, routing, durable execution, tool use, independent
verification, memory/evidence, and finally response. The pipeline is modelled
as a graph of typed stages connected by typed control edges; a walker
traverses the workflow, enforces the fail-closed policy, and accumulates
evidence along the way."""

# ---------- Core entity archetypes (stages of the ATLANTIS workflow) ----------

node Stage {
    has name: str = "";
    has passed: bool = False;
}

node Request {
    has title: str = "";
    has authorized: bool = False;
}

node Plan {
    has branch: str = "";
    has tests_run: bool = False;
}

node Execution {
    has durable_id: str = "";
    has tool_used: bool = False;
}

node Evidence {
    has trace: str = "";
    has verified: bool = False;
}

# ---------- Typed control edges (each relationship carries meaning) ----------

edge FlowsTo { has order: int = 0; }
edge Authorizes { has approver: str = ""; }
edge Records { }

# ---------- Walker that drives the end-to-end ATLANTIS workflow ----------

walker AtlantisAlpha {
    has report: list[str] = [];
    has budget_remaining: int = 3;

    can start with Root entry {
        print("ATLANTIS Day-7 alpha initiated");
        visit [-->];
    }

    can accept with Request entry {
        if self.budget_remaining <= 0 {
            print("FAIL-CLOSED: budget exhausted before authorization");
            self.report.append("BLOCKED: budget");
            disengage;
        }
        # Authorization stage: fail-closed policy gate.
        here.authorized = True;
        self.report.append(f"authorized request: {here.title}");
        self.budget_remaining -= 1;
        visit [->:FlowsTo:->];
    }

    can process with Plan entry {
        # Planning: produce an isolated branch and run regression suite.
        here.tests_run = True;
        self.report.append(f"planned on branch {here.branch}; tests executed");
        visit [->:FlowsTo:->];
    }

    can execute with Execution entry {
        # Durable execution + tool use: must carry a durable task identity.
        if here.durable_id == "" {
            print("FAIL-CLOSED: durable task identity missing");
            self.report.append("BLOCKED: no durable id");
            disengage;
        }
        here.tool_used = True;
        self.report.append(f"durable execution {here.durable_id}; tool invoked");
        visit [->:FlowsTo:->];
    }

    can verify with Evidence entry {
        # Independent verification: must be a separate node from execution.
        here.verified = True;
        self.report.append("independent verification: PASS");
        visit [->:FlowsTo:->];
    }
}

# ---------- Demo wiring ----------

with entry {
    req = Request(title="repo-improvement: tighten policy gate");
    plan = Plan(branch="atlantis/alpha-001");
    exec0 = Execution(durable_id="task-7f3a");
    ev = Evidence();

    root +>:FlowsTo(order=1):+> req;
    req +>:Authorizes(approver="sec-officer"):+> plan;
    plan +>:FlowsTo(order=2):+> exec0;
    exec0 +>:FlowsTo(order=3):+> ev;
    ev +>:Records:+> root;

    print("--- ATLANTIS happy-path run ---");
    a = AtlantisAlpha();
    root spawn a;
    for line in a.report {
        print(line);
    }
    print(f"final budget remaining: {a.budget_remaining}");

    print("--- ATLANTIS fail-closed run (no durable id) ---");
    req2 = Request(title="repo-improvement: tighten policy gate");
    plan2 = Plan(branch="atlantis/alpha-002");
    bad_exec = Execution(durable_id="");  # missing identity
    ev2 = Evidence();
    root +>:FlowsTo(order=1):+> req2;
    req2 +>:Authorizes(approver="sec-officer"):+> plan2;
    plan2 +>:FlowsTo(order=2):+> bad_exec;
    bad_exec +>:FlowsTo(order=3):+> ev2;

    b = AtlantisAlpha();
    root spawn b;
    for line in b.report {
        print(line);
    }
}

