"""Versioned task pipeline: persist task definitions as a graph and validate cached records after a restart.

Models the essential scenario from Yuxin-Ren-SZ/Yuxin_MEA issue #6:
- Tasks are registered at runtime in a forward-dependency registry.
- Cached task records carry dependency lists that are NOT the scheduling source.
- After a "restart" (re-loading a new graph), stale cached records must be detected
  and invalidated when the registered definition diverges from the persisted one.
"""

# ----------------------------------------------------------------------
# Archetypes
# ----------------------------------------------------------------------

# A persisted task definition. The `version` field is what makes the graph
# "versioned" — when a task's definition changes, its version bumps, and any
# cached record pinned to an older version is now stale.
node TaskDef {
    has name: str = "";
    has version: int = 1;
}

# A cached, run-time task record. It remembers a snapshot of the dependency
# list it was last computed against plus the version of the TaskDef it was
# pinned to. In the issue, this record is what gets persisted across restarts
# while the real graph is re-registered by callers.
node TaskRecord {
    has name: str = "";
    has pinned_version: int = 0;
    has cached_deps: list[str] = [];
}

# ----------------------------------------------------------------------
# Typed edges — the relationship carries meaning, so it gets a name.
# ----------------------------------------------------------------------

# "TaskDef `a` depends on TaskDef `b`" — the registration-time forward edge.
edge Dep {}

# "Cached record `r` was computed against TaskDef `a` at this version" —
# a pointer from a cached record to the definition it pinned to.
edge PinnedTo {}

# ----------------------------------------------------------------------
# Walker: graph audit
# ----------------------------------------------------------------------

walker Auditor {
    has stale: list[str] = [];

    can start with Root entry {
        # Step 1: walk every TaskDef → TaskRecord link and check each record's
        # pinned version against the live definition version.
        visit [->:PinnedTo:->];
    }

    can audit with TaskDef entry {
        # One record is reachable per PinnedTo edge out of this TaskDef.
        for record in [->:PinnedTo:->] {
            record_name = record.name;
            record_version = record.pinned_version;
            live_version = here.version;
            deps_match = record.cached_deps == [->:Dep:->].name;
            if record_version != live_version or not deps_match {
                self.stale.append(record_name);
            }
        }
        visit [->:Dep:->];
    }

    can report with Root entry {
        if self.stale {
            print(f"STALE records requiring re-migration: {self.stale}");
        } else {
            print("All cached records match the registered definition.");
        }
    }
}

walker DependencyOrder {
    has order: list[str] = [];
    has visiting: list[str] = [];

    can start with Root entry {
        visit [->:Dep:->];
