"""Test annex for the pipeline task graph demo.

Exercises the core behaviors the issue cares about:
  * Auditor marks tasks stale when cached version lags current definition version
  * Auditor stays clean when versions match
  * Auditor detects cycles in the registered dependency graph
  * Auditor reports pipeline label and graph version, and traverses every task
  * InvalidationCascade propagates staleness downstream
"""

import io;
import from contextlib { redirect_stdout }

test "auditor marks stale tasks whose cached version lags the current version" {
    p = Pipeline(label="pipe-a", graph_version=5);

    t_a = Task(name="a", version=3, last_seen_version=2, cache_hit=True);
    t_b = Task(name="b", version=4, last_seen_version=4, cache_hit=True);

    root ++> p;
    p +>:DependsOn(since_version=1):+> t_a;
    t_a +>:DependsOn(since_version=1):+> t_b;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = DependencyAuditor();
        root spawn auditor;
    }
    out = buf.getvalue();

    assert "Auditing pipeline 'pipe-a' at graph version v5" in out, f"missing audit header: {out}";
    assert t_a.stale, "task 'a' should be marked stale (cached v2 != current v3)";
    assert not t_b.stale, "task 'b' should remain fresh (cached v4 == current v4)";
    assert "a" in auditor.stale_tasks, f"expected 'a' in stale_tasks, got {auditor.stale_tasks}";
    assert "b" not in auditor.stale_tasks, f"'b' should not be stale, got {auditor.stale_tasks}";
    assert not auditor.cycle_detected, "no cycle in a linear chain";
    assert len(auditor.visited) == 2, f"expected to visit 2 tasks, visited {auditor.visited}";
}

test "auditor detects a cycle in the registered dependency graph" {
    p = Pipeline(label="cycle-pipe", graph_version=1);

    t_x = Task(name="x", version=1, last_seen_version=1, cache_hit=True);
    t_y = Task(name="y", version=1, last_seen_version=1, cache_hit=True);
    t_z = Task(name="z", version=1, last_seen_version=1, cache_hit=True);

    root ++> p;
    p +>:DependsOn(since_version=1):+> t_x;
    t_x +>:DependsOn(since_version=1):+> t_y;
    t_y +>:DependsOn(since_version=1):+> t_z;
    t_z +>:DependsOn(since_version=1):+> t_x;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = DependencyAuditor();
        root spawn auditor;
    }
    out = buf.getvalue();

    assert auditor.cycle_detected, f"cycle must be detected; visited={auditor.visited}";
    assert "[CYCLE] revisited x" in out, f"missing CYCLE marker for x: {out}";
    assert "x" in auditor.visited, "x should be recorded as visited";
}

test "auditor reports pipeline label and graph version, traverses all reachable tasks" {
    p = Pipeline(label="my-pipeline", graph_version=7);

    t_one = Task(name="one", version=7, last_seen_version=7, cache_hit=True);
    t_two = Task(name="two", version=7, last_seen_version=5, cache_hit=True);
    t_three = Task(name="three", version=7, last_seen_version=7, cache_hit=True);
    t_four = Task(name="four", version=7, last_seen_version=7, cache_hit=False);

    root ++> p;
    p +>:DependsOn(since_version=1):+> t_one;
    t_one +>:DependsOn(since_version=2):+> t_two;
    t_two +>:DependsOn(since_version=3):+> t_three;
    t_three +>:DependsOn(since_version=4):+> t_four;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = DependencyAuditor();
        root spawn auditor;
    }
    out = buf.getvalue();

    assert "Auditing pipeline 'my-pipeline' at graph version v7" in out, f"missing audit header: {out}";
    assert len(auditor.visited) == 4, f"expected to visit all 4 tasks, got {auditor.visited}";
    assert t_two.stale, "task 'two' should be marked stale (cached v5 != current v7)";
    assert not t_one.stale, "task 'one' should be fresh";
    assert not t_three.stale, "task 'three' should be fresh";
    # cache_hit=False means the auditor must not mark the task stale purely on version.
    assert not t_four.stale, "task 'four' (no cache) must not be marked stale";
    assert "two" in auditor.stale_tasks, f"expected 'two' stale, got {auditor.stale_tasks}";
}

test "invalidation cascade propagates staleness downstream" {
    p = Pipeline(label="cascade-pipe", graph_version=2);

    t_up = Task(name="upstream", version=3, last_seen_version=2, cache_hit=True, stale=True);
    t_mid = Task(name="midstream", version=3, last_seen_version=2, cache_hit=True, stale=False);
    t_dn = Task(name="downstream", version=3, last_seen_version=2, cache_hit=True, stale=False);

    root ++> p;
    p +>:DependsOn(since_version=1):+> t_up;
    t_up +>:DependsOn(since_version=1):+> t_mid;
    t_mid +>:DependsOn(since_version=1):+> t_dn;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        cascade = InvalidationCascade();
        root spawn cascade;
    }
    out = buf.getvalue();

    assert "Cascade from pipeline 'cascade-pipe'" in out, f"missing cascade header: {out}";
    # Cascade walker merely walks the graph; staleness was set on t_up by the auditor
    # in this fixture. The walker should reach the downstream tasks.
    assert "invalidating downstream of stale upstream" in out, f"missing invalidation line: {out}";
}

test "fresh graph with matching versions yields no stale tasks and no cycle" {
    p = Pipeline(label="clean-pipe", graph_version=1);

    t_a = Task(name="alpha", version=1, last_seen_version=1, cache_hit=True);
    t_b = Task(name="beta", version=1, last_seen_version=1, cache_hit=True);

    root ++> p;
    p +>:DependsOn(since_version=1):+> t_a;
    t_a +>:DependsOn(since_version=1):+> t_b;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = DependencyAuditor();
        root spawn auditor;
    }
    out = buf.getvalue();

    assert len(auditor.stale_tasks) == 0, f"no tasks should be stale, got {auditor.stale_tasks}";
    assert not auditor.cycle_detected, "linear DAG should not report a cycle";
    assert "[FRESH] task alpha" in out, f"missing FRESH alpha line: {out}";
    assert "[FRESH] task beta" in out, f"missing FRESH beta line: {out}";
    assert not t_a.stale and not t_b.stale, "fresh tasks must remain not-stale";
}

