"""Models the Firebase Performance NSURLSession delegate proxy crash scenario.

In FirebasePerformance/Sources/Instrumentation/FPRProxyObjectHelper.m, the SDK
wraps NSURLSession delegate objects in an NSProxy subclass that holds the
*real* delegate as a weak forward target. When CFNetwork invalidates the
session and calls -respondsToSelector: on the wrapper, the wrapper must
reach into the weak target to forward the query. If the weak target has
already been deallocated (the object is gone but the proxy still lives),
dereferencing it produces a crash.

This program lifts that scenario into idiomatic Jac: the session and its
proxies are nodes, the weak/delegate relationship is a typed edge, and a
walker simulates CFNetwork's invalidation traversal across the session,
checking each proxy's reachability and reporting weak targets that have
gone away (the same condition that produces the objc_loadWeakRetained
crash stack in the real bug).
"""

node Session {
    has name: str = "";
    has invalidated: bool = False;
}

node ProxyTarget {
    """The real NSURLSession delegate. May be deallocated at any time."""
    has label: str = "";
    has alive: bool = True;
}

edge Wraps {
    """Weak forward reference from a session's proxy to the real delegate.

    In the real iOS code this is an NSProxy + PAGWeakProxy wrapper; here we
    model the *behavior*: a proxy exposes the same interface as its target
    by forwarding through a weak reference.
    """
    has installed: str = "";
}

node Proxy {
    """The NSProxy-style wrapper that CFNetwork holds onto."""
    has kind: str = "NSProxy";
}

walker Invalidate {
    """Mimics CFNetwork's NSURLSession delegate invalidation walk.

    Visits every proxy attached to a session, then asks each proxy whether
    its forward target still answers -respondsToSelector:. A proxy whose
    target has been deallocated represents the same hazard as PAGWeakProxy
    in the production crash: reading the weak reference would normally
    crash here, so the walker reports (instead of dereferencing) every
    dangling forward target it finds.
    """
    has crash_risk: int = 0;
    has probes: int = 0;
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can on_session with Session entry {
        here.invalidated = True;
        print(f"Invalidating session: {here.name}");
        visit [->:Wraps:->];
    }

    can on_proxy with Proxy entry {
        self.probes += 1;
        # The proxy's only outgoing relationship is the Wraps edge to the
        # real delegate target. CFNetwork walks the same way during
        # finalizeDelegateWithError:.
        visit [->:Wraps:->];
