import io;
import from contextlib { redirect_stdout }

test "dead weak proxy fails closed during invalidation" {
    real = Delegate(kind="NSURLSessionDelegate", responds=True);
    proxy = Proxy(label="PAGWeakProxy", target_alive=False);
    session = Session(name="com.example.api");

    root ++> session;
    session +>:DelegatesTo:+> proxy;
    proxy +>:Wraps(via_weak=True):+> real;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Invalidate();
    }
    out = buf.getvalue();

    assert session.invalidated == True, f"session invalidated={session.invalidated}";
    assert res.crash_site == "PAGWeakProxy respondsToSelector: via PAGWeakProxy", f"got {res.crash_site}";
    assert "CRASH: objc_loadWeakRetained returned nil" in out, f"missing crash marker: {out}";
    assert "invalidation callback dispatched" not in out, f"unexpected callback: {out}";
}

test "live weak proxy resolves the real delegate" {
    real = Delegate(kind="NSURLSessionDelegate", responds=True);
    proxy = Proxy(label="PAGWeakProxy", target_alive=True);
    session = Session(name="com.example.api");

    root ++> session;
    session +>:DelegatesTo:+> proxy;
    proxy +>:Wraps(via_weak=True):+> real;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Invalidate();
