    has reply_limit: int = 5;
    has visible: int = 0;
    has overflow: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can land on Article with Article entry {
        print(f"Article: {here.title} [{here.slug}]");
        visit [-->];
    }

    can walk_thread with Comment entry {
        if here.depth > self.reply_limit {
            self.overflow += 1;
            print(f"  {'  ' * here.depth}... [Load More: {here.reply_count} more replies]");
            return;
        }
        self.visible += 1;
        status = "[leaf]" if here.reply_count == 0 else f"[{here.reply_count} replies]";
        print(f"  {'  ' * here.depth}{here.author}: {here.body} {status}");
        visit [->:ThreadedReply:->];
    }
}

