    assert res.report[0]["author"] == "alice", f"got {res.report}";
    assert res.report[1]["author"] == "bob", f"got {res.report}";
    assert res.report[2]["author"] == "carol", f"got {res.report}";
    assert res.report[2]["marker"] == "+", f"got {res.report[2]}";
