    reply = Comment(author="bob", body="Reply", depth=1, open=True);
    already_closed = Comment(author="carol", body="Closed", depth=0, open=False);
    nested = Comment(author="dave", body="Nested", depth=2, open=True);

    post +>:ReplyTo(order=1):+> top;
    post +>:ReplyTo(order=2):+> already_closed;
    top +>:ReplyTo(order=1):+> reply;
    reply +>:ReplyTo(order=1):+> nested;

