    a3 = Advancement(description="Promoted to Champion", awarded_xp=5);
    a4 = Advancement(description="Held a scrap patch", awarded_xp=2);

    # Wire the graph:
        # ContentFighter <-Models-- Fighter <-Granted-- Advancement
        #                                  ^----OfSkill---- Skill
        #                                  ^----OfAction--- CampaignAction
    f1 +>:Models:+> ganger;
    f2 +>:Models:+> champ;
    f1 +>:Granted:+> a1;
    a1 +>:OfSkill:+> sk_stealth;
    f1 +>:Granted:+> a2;
    a2 +>:OfSkill:+> sk_ballistic;
