"""Health-aware middleware: model a service health tracker where downstream
errors are filtered before they poison the service's health window, and
demonstrate the previously-dead ``HealthCheckError.checkFailed`` path by
constructing it from a walker that audits the health monitor.

Original Swift issue: ``HealthCheckMiddleware.execute`` blindly records
every thrown error as a service failure, and ``HealthCheckError.checkFailed``
is declared but never constructed. This Jac program models both the
unhealthy propagation chain and the audit walker that surfaces the
distinction.
"""

# ---------------------------------------------------------------------------
# Node archetypes
# ---------------------------------------------------------------------------

node Command {
    has name: str = "";
    has should_fail_validation: bool = False;
    has should_fail_authorization: bool = False;
    has should_succeed: bool = True;
}

node Service {
    has service_name: str = "";
    has failure_count: int = 0;
    has success_count: int = 0;
    has unhealthy: bool = False;
}

node HealthMonitor {
    has recorded_failures: int = 0;
    has recorded_checkfailed: int = 0;
    has recorded_other: int = 0;
}

# A plain validation/authorization error is unrelated to the downstream
# service's actual availability, so a healthy pipeline must NOT count it
# against the service. The ``HealthCheckMiddleware`` node owns the policy.
node HealthCheckMiddleware {
    has mode: str = "strict";
}

# ---------------------------------------------------------------------------
# Typed edges
# ---------------------------------------------------------------------------

# A command is executed against a target service via middleware.
edge Executes { }
# The middleware consults the health monitor for the target service.
edge Monitors { }
# The middleware is wired in front of the service.
edge Protects { }

# ---------------------------------------------------------------------------
# Walker: run a command through middleware, classify errors, and only let
# service-availability problems pollute the service's health window.
# ---------------------------------------------------------------------------

walker RunCommand {
    has failures_logged: int = 0;
    has checkfailed_logged: int = 0;
    has other_logged: int = 0;
    has carried: Command | None = None;

    can start with Root entry {
        visit [-->];
    }

    can dispatch with Command entry {
        self.carried = Command(
            name=here.name,
            should_fail_validation=here.should_fail_validation,
            should_fail_authorization=here.should_fail_authorization,
            should_succeed=here.should_succeed,
        );
        # Hand the command off to the middleware node protecting the service.
        visit [here ->:Executes:->];
    }

    can run with HealthCheckMiddleware entry {
        cmd = self.carried;
        if cmd is None {
            visit [-->];
        }
        # Simulate the downstream execution the middleware would do.
        err_kind = "";
        if cmd.should_fail_validation {
            err_kind = "validation";
        } elif cmd.should_fail_authorization {
            err_kind = "authorization";
        } elif cmd.should_fail_authorization is False and cmd.should_fail_validation is False and cmd.should_succeed is False {
            err_kind = "checkFailed";
        }

        if err_kind == "" {
            # Genuine success: log on the monitor via the service link.
            visit [here ->:Protects:->];
        } else {
            self.classify(middleware=here, kind=err_kind);
            visit [-->];
        }
    }

    can serve with Service entry {
        # Healthy path: a genuine success increments the service counters.
        here.success_count += 1;
        visit [here ->:Monitors:->];
    }

    can note with HealthMonitor entry {
        here.recorded_failures += self.failures_logged;
        here.recorded_checkfailed += self.checkfailed_logged;
        here.recorded_other += self.other_logged;
        visit [-->];
    }
}

# Helper ability: kept as a method on the walker for clarity.
# In idiomatic Jac this is just a method that mutates walker state and the
# middleware's view of which errors count as service problems.
impl RunCommand {
    def classify(middleware: HealthCheckMiddleware, kind: str) -> None {
        if kind == "checkFailed" {
            # A real health-check failure: pollute the service's health.
            self.failures_logged += 1;
            self.checkfailed_logged += 1;
            # Walk to the service this middleware protects and mark it.
            target = [middleware ->:Protects:->][0] if len([middleware ->:Protects:->]) > 0 else None;
            if target is not None {
                target.failure_count += 1;
                if target.failure_count >= 1 {
                    target.unhealthy = True;
                }
            }
        } else {
            # Validation / authorization errors are NOT service problems.
            self.other_logged += 1;
        }
    }
}

# ---------------------------------------------------------------------------
# Walker: audit the health monitor for the previously-dead ``checkFailed``
# construction site. Demonstrates that ``checkFailed`` is now reachable.
# ---------------------------------------------------------------------------

walker AuditHealthMonitor {
    has saw_checkfailed: int = 0;
    has saw_other: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with HealthMonitor entry {
        print(f"[audit] recorded checkFailed={here.recorded_checkfailed} other={here.recorded_other} failures={here.recorded_failures}");
        if here.recorded_checkfailed > 0 {
            self.saw_checkfailed = here.recorded_checkfailed;
        }
        if here.recorded_other > 0 {
            self.saw_other = here.recorded_other;
        }
        visit [-->];
    }
}

# ---------------------------------------------------------------------------
# Walker: walk services to report which ones are now marked unhealthy.
# ---------------------------------------------------------------------------

walker ReportServices {
    can start with Root entry {
        visit [-->];
    }

    can report with Service entry {
        state_label = "UNHEALTHY" if here.unhealthy else "healthy";
        print(f"[service] {here.service_name}: failures={here.failure_count} successes={here.success_count} -> {state_label}");
        visit [-->];
    }
}

# ---------------------------------------------------------------------------
# Demo wiring
# ---------------------------------------------------------------------------

with entry {
    monitor = HealthMonitor();
    middleware = HealthCheckMiddleware(mode="strict");

    checkout = Service(service_name="checkout");
    payments = Service(service_name="payments");

    cmd_validation = Command(
        name="place-order",
        should_fail_validation=True,
        should_fail_authorization=False,
