"""HealthCheckMiddleware: model the bug where every downstream error
counts against a service's health, and `.checkFailed` is never raised.

Two service nodes are wired into a request chain. A `Request` walker
visits the chain. When a service "fails", the walker must decide
whether the failure should count against that service's health window
by inspecting the error type, instead of blindly recording every
thrown error as evidence of an outage. The demo also constructs a
`HealthCheckError.checkFailed` to show the previously dead case is
now reachable.
"""

node HealthCheckError {
    has kind: str = "timeout";
    has reason: str = "";
}

node Service {
    has name: str = "";
    has failure_count: int = 0;
    has healthy: bool = True;
    has last_error_kind: str = "";
}

edge DependsOn {
    has label: str = "";
}

walker Request {
    has service_name: str = "";
    has error_to_throw: str = "";

    can start with Root entry {
        visit [->:DependsOn:->];
    }

    can hit with Service entry {
        target_name = here.name;
        if self.service_name != "" and self.service_name != target_name {
            visit [->:DependsOn:->];
            return;
        }

        if self.error_to_throw == "" {
            print(f"  ok    : {target_name}");
            visit [->:DependsOn:->];
            return;
        }

        # BUG SHAPE: the original middleware catches EVERY error and
        # records it as a service-health failure. Here we surface that
        # decision so a maintainer can wire the fix.
        if self.error_to_throw == "validation" {
            print(f"  skip  : {target_name} got validation error "
                  f"(not a service-health concern)");
        } elif self.error_to_throw == "auth" {
            print(f"  skip  : {target_name} got authorization error "
                  f"(not a service-health concern)");
        } elif self.error_to_throw == "timeout" {
            err = HealthCheckError(kind="timeout");
            here.failure_count += 1;
            here.last_error_kind = err.kind;
            print(f"  FAIL  : {target_name} timed out -> counted "
                  f"({here.failure_count})");
        } elif self.error_to_throw == "checkFailed" {
            err = HealthCheckError(kind="checkFailed",
                                   reason="probe returned non-2xx");
            here.failure_count += 1;
            here.last_error_kind = err.kind;
            print(f"  FAIL  : {target_name} check failed: "
                  f"{err.reason} -> counted ({here.failure_count})");
        } else {
            print(f"  FAIL  : {target_name} unknown error "
                  f"-> counted (this is the buggy path)");
            here.failure_count += 1;
            here.last_error_kind = "unknown";
        }

        if here.failure_count >= 3 {
            here.healthy = False;
        }

        visit [->:DependsOn:->];
    }
}

