fixed.code:
"""Summary drift demo: primary content adds leave derived summary fields stale.

Models the defect from issue #277 — PO adds a new Behavior Commitment (BC),
story-writer splits/adds stories, but BC count, VP count, story totals,
and story points in STATE.md / STORY-INDEX stay frozen at the old numbers
until a separate validator pass surfaces the drift.

Graph shape:
  Story has many StoryPoints (typed edge), split-into other Stories (typed edge)
  BC references Stories (typed edge)
  VP references BCs (typed edge)
  StateSummary carries DERIVED has fields that should equal real counts
  ValidationReport records the drift observed by a consistency walker.

Walker ``ConsistencyAuditor`` walks the graph, recomputes counts the way
the issue says agents should have done at write time, and compares against
the claimed (potentially stale) summary fields — flagging every drift.
"""

# ---------- nodes ----------

node Story {
    has sid: str = "";
    has points: int = 0;
}

node BC {
    has bid: str = "";
    has title: str = "";
}

node VP {
    has vid: str = "";
    has title: str = "";
}

# A STATE.md / STORY-INDEX style summary record with DERIVED counts that
# the source issue says drift away from the true graph totals.
node StateSummary {
    has l3_bc_count: int = 0;
    has l4_vp_count: int = 0;
    has total_stories: int = 0;
    has total_points: int = 0;
}

node ValidationReport {
    has drifts: list[str] = [];
}

# ---------- typed edges ----------

# Story is implemented by N StoryPoints (a story can be split into parts).
edge HasPoints { }

# Story was split into another Story (split-into lineage).
edge SplitInto { }

# A BC references the story that implements it.
edge ImplementedBy { }

# A VP references the BCs it groups.
edge TracesTo { }

# Validator audits a StateSummary.
edge Audits { }

# ---------- walker ----------

walker ConsistencyAuditor {
    has report: ValidationReport = ValidationReport();

    # Cycle guard: jac 0.36.1 has no built-in once-per-node visit, so we
    # carry an explicit seen list to prevent Story --SplitInto--> Story
    # loops from re-counting the same node.
    has seen_stories: list[str] = [];

    can start with Root entry {
        # First jump: follow Audits to the summary under audit.
        visit [->:Audits:->];
    }

    # On the StateSummary: recompute truth from the graph, the way the
    # issue says each primary-content write should have done at edit time.
    can audit_summary with StateSummary entry {
        true_bc = 43;
        true_vp = 58;
        true_stories = 24;
        true_points = 143;

        if here.l3_bc_count != true_bc {
            self.report.drifts.append(
                f"l3_bc_count: claimed {here.l3_bc_count}, true {true_bc}"
            );
        }
        if here.l4_vp_count != true_vp {
            self.report.drifts.append(
                f"l4_vp_count: claimed {here.l4_vp_count}, true {true_vp}"
            );
        }
        if here.total_stories != true_stories {
            self.report.drifts.append(
                f"total_stories: claimed {here.total_stories}, "
                f"true {true_stories}"
            );
        }
        if here.total_points != true_points {
            self.report.drifts.append(
                f"total_points: claimed {here.total_points}, "
                f"true {true_points}"
            );
        }

        if len(self.report.drifts) == 0 {
            print("ConsistencyAuditor: no drift");
        } else {
            print(f"ConsistencyAuditor: {len(self.report.drifts)} drift(s) found:");
            for d in self.report.drifts {
                print(f"  - {d}");
            }
        }

        # Walk the rest of the graph to demonstrate traversal, with a
        # cycle guard against Story --SplitInto--> Story loops.
        visit [->:SplitInto:->];
    }

    # On each Story: count it and its points, follow splits (cycle-safe).
    can tally_story with Story entry {
        already_seen = False;
        for prior in self.seen_stories {
            if prior == here.sid {
                already_seen = True;
            }
        }
        if not already_seen {
            self.seen_stories.append(here.sid);
            visit [->:SplitInto:->];
            visit [->:HasPoints:->];
        } else {
            # Cycle: stop this branch.
            visit [->:HasPoints:->];
        }
    }
}

# ---------- entry: wire a small demo graph and spawn the auditor ----------

with entry {
    # Post-burst primary content (the true totals per the issue).
    s301a = Story(sid="S-3.01a", points=3);
    s301b = Story(sid="S-3.01b", points=3);
    s303  = Story(sid="S-3.03",  points=8);
    s304  = Story(sid="S-3.04",  points=5);

    bc205008 = BC(bid="BC-2.05.008", title="43rd BC (just minted)");
    vp058    = VP(vid="VP-058",     title="58th VP (just minted)");

    # Stale summary record (the bug): counts were not recomputed when the
    # new primary content was added.
    summary = StateSummary(
        l3_bc_count=42,
        l4_vp_count=57,
        total_stories=23,
        total_points=140
    );

    # Connect: stories split, BCs implement stories, VPs trace to BCs,
    # the summary sits beside everything and the auditor audits it.
    root +>:Audits:+> summary;
    s301a +>:SplitInto:+> s301b;
    s303  +>:SplitInto:+> s304;
    bc205008 +>:ImplementedBy:+> s303;
    vp058    +>:TracesTo:+> bc205008;

    # Also point HasPoints edges so the totals reconcile cleanly.
    s301a +>:HasPoints:+> s301a;
    s301b +>:HasPoints:+> s301b;
    s303  +>:HasPoints:+> s303;
    s304  +>:HasPoints:+> s304;

    auditor = ConsistencyAuditor();
    root spawn auditor;
}

