"""Cycle-safe JSON field collector.

Models the `collectJSONFields` helper from go-hooppy issue #123, where
recursing into self-referential embedded structs caused a stack overflow
instead of a proper diagnostic. The fix threads a visited set through the
walk so a type already on the path is skipped, mirroring what
`encoding/json`'s `typeFields` does.

The walker below is the idiomatic Jac equivalent: a `FieldCollector`
walker traverses embedded-field edges through the type graph, accumulating
field names on a single typed `has` accumulator. Without the visited set
the walker would loop forever on cyclic graphs (jac 0.36.1 has no
built-in once-per-node visitation), exactly matching the original bug.
"""

# ---------------------------------------------------------------------------
# Entity archetypes
# ---------------------------------------------------------------------------

node GoType {
    has name: str = "";
    has fields: list[str] = [];

    def describe() -> str {
        return f"{self.name}={self.fields}";
    }
}

# A concrete struct type with a list of (field_name, embedded_type_name)
# pairs. embedded targets are resolved via `Embeds` typed edges so the
# graph is the relationship, not a string lookup.
node StructType(GoType) {
    has embeds: list[str] = [];

    override def describe() -> str {
        return f"struct {self.name} embeds={self.embeds} fields={self.fields}";
    }
}

# ---------------------------------------------------------------------------
# Relationship: "struct X embeds struct Y by name"
# ---------------------------------------------------------------------------

edge Embeds { has since: str = "v1"; }

# ---------------------------------------------------------------------------
# Walker: cycle-safe JSON field collector
# ---------------------------------------------------------------------------

walker FieldCollector {
    has visited: list[GoType] = [];
    has collected: list[str] = [];

    def already_seen(t: GoType) -> bool {
        for v in self.visited {
            if v.name == t.name {
                return True;
            }
        }
        return False;
    }

    def mark(t: GoType) -> None {
        self.visited.append(t);
        for fname in t.fields {
            self.collected.append(fname);
        }
    }

    can start with Root entry {
        visit [-->];
    }

    # Single union ability handles both kinds of GoType we model.
    # The body's only shared contract is `name` + `fields` (declared on
    # the base) plus the traversal via the typed `Embeds` edge.
    can collect with GoType entry {
        if self.already_seen(here) {
            # Cycle hit: skip this type, do NOT re-enter its edges.
            # This is the fix from issue #123.
            print(f"[skip-cycle] {here.name} already on path");
        } else {
            self.mark(here);
            print(f"[collect]  {here.describe()}");
            visit [->:Embeds:->];
        }
    }
}

# ---------------------------------------------------------------------------
# Demo graph
# ---------------------------------------------------------------------------

with entry {
    # ----- Cyclic case: selfRef { *selfRef; A int } ------------------------
    self_ref = StructType(name="selfRef", fields=["a"], embeds=["selfRef"]);

    # ----- Mutual recursion: mutA embeds *mutB embeds *mutA ---------------
    mut_a = StructType(name="mutA", fields=["x"], embeds=["mutB"]);
    mut_b = StructType(name="mutB", fields=["y"], embeds=["mutA"]);

    # ----- Acyclic case: ordinary embedded chain --------------------------
    base = StructType(name="Base", fields=["id"], embeds=[]);
    middle = StructType(name="Middle", fields=["name"], embeds=["Base"]);
    top = StructType(name="Top", fields=["leaf"], embeds=["Middle"]);

    # Wire the edges. Cycles are intentional — the walker must NOT die.
    self_ref +>:Embeds:+> self_ref;
    mut_a +>:Embeds:+> mut_b;
    mut_b +>:Embeds:+> mut_a;
    top +>:Embeds:+> middle;
    middle +>:Embeds:+> base;

    # ----- Run the collector on each entry point ---------------------------
    for entry_node in [self_ref, mut_a, top] {
        print(f"\n--- collecting from {entry_node.name} ---");
        w = FieldCollector();
        root spawn w;
        # Manually seed the walker onto the chosen entry by re-rooting:
        # since walkers spawn at root, we instead just collect by
        # dispatching the same visited/collected logic into a fresh walker
        # whose start fires at our node. To keep the demo single-shot we
        # detach the node from root and re-attach, then spawn.
        root del --> entry_node;
        root ++> entry_node;
        w2 = FieldCollector();
        root spawn w2;
        print(f"result for {entry_node.name}: {w2.collected}");
    }

    # Re-attach the acyclic one for the final showcase run.
    print("\n=== showcase: selfRef must NOT overflow ===");
    root del --> mut_a;
    root del --> top;
    root ++> self_ref;
    walker_show = FieldCollector();
    root spawn walker_show;
    print(f"collected from selfRef: {walker_show.collected}");
    print("returned without stack overflow");
}

