"""Tests for the cycle-safe JSON field collector (issue #123).

These tests verify the acceptance criteria from the issue:
- Self-referential embedded structs do not loop forever and report their
  concrete fields (here, `a`).
- Mutual recursion across two types also terminates and reports fields from
  both types.
- Acyclic chains still traverse normally and aggregate every field.
- Removing the cycle guard (or, equivalently, asserting the cycle is hit
  and skipped) pins the test against the actual failure mode: an infinite
  loop, not an assertion failure.

Each test builds its own isolated graph so the walker is exercised on the
intended fixture, not on leftover state from the demo.
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Shared fixture builders. Keeping these local avoids relying on the
# program's demo `with entry` block (which does not run under `jac test`).
# ---------------------------------------------------------------------------

def build_self_ref_graph() -> object {
    self_ref = StructType(name="selfRef", fields=["a"], embeds=["selfRef"]);
    self_ref +>:Embeds:+> self_ref;
    root ++> self_ref;
    return self_ref;
}

def build_mutual_graph() -> tuple {
    mut_a = StructType(name="mutA", fields=["x"], embeds=["mutB"]);
    mut_b = StructType(name="mutB", fields=["y"], embeds=["mutA"]);
    mut_a +>:Embeds:+> mut_b;
    mut_b +>:Embeds:+> mut_a;
    root ++> mut_a;
    return (mut_a, mut_b);
}

def build_chain_graph() -> tuple {
    base = StructType(name="Base", fields=["id"], embeds=[]);
    middle = StructType(name="Middle", fields=["name"], embeds=["Base"]);
    top = StructType(name="Top", fields=["leaf"], embeds=["Middle"]);
    top +>:Embeds:+> middle;
    middle +>:Embeds:+> base;
    root ++> top;
    return (base, middle, top);
}

# ---------------------------------------------------------------------------
# Tests
# ---------------------------------------------------------------------------

test "self-referential embedded type terminates and reports its field" {
    entry_node = build_self_ref_graph();

    buf = io.StringIO();
    w = FieldCollector();
    with redirect_stdout(buf) {
        root spawn w;
    }
    out = buf.getvalue();

    # Acceptance #1: must return, must report 'a'.
    assert "a" in w.collected, f"expected 'a' in collected, got {w.collected}";
    # The cycle guard must have fired exactly once on the self-edge.
    assert "[skip-cycle] selfRef already on path" in out,
        f"expected skip-cycle marker, got: {out}";
    assert "returned without stack overflow" not in out  # demo not running
        or True;  # tautology so the assertion is always reachable
}

test "mutual recursion across two types terminates" {
    (mut_a, mut_b) = build_mutual_graph();

    buf = io.StringIO();
    w = FieldCollector();
    with redirect_stdout(buf) {
        root spawn w;
    }
    out = buf.getvalue();

    # Acceptance #2: both types' concrete fields must be reported.
    assert "x" in w.collected, f"expected 'x' from mutA, got {w.collected}";
    assert "y" in w.collected, f"expected 'y' from mutB, got {w.collected}";
    # The walker must have hit the cycle on the second visit of one type.
    skip_markers = [line for line in out.split("\n") if "[skip-cycle]" in line];
    assert len(skip_markers) >= 1,
        f"expected at least one skip-cycle marker, got: {out}";
}

test "acyclic chain aggregates every field in order" {
    (base, middle, top) = build_chain_graph();

    buf = io.StringIO();
    w = FieldCollector();
    with redirect_stdout(buf) {
        root spawn w;
    }
    out = buf.getvalue();

    # All three layers contribute their concrete field.
    assert "leaf" in w.collected, f"expected 'leaf' from Top, got {w.collected}";
    assert "name" in w.collected, f"expected 'name' from Middle, got {w.collected}";
    assert "id" in w.collected, f"expected 'id' from Base, got {w.collected}";
    # No cycle on an acyclic graph -> no skip-cycle markers.
    skip_markers = [line for line in out.split("\n") if "[skip-cycle]" in line];
    assert len(skip_markers) == 0,
        f"acyclic graph must not hit the cycle guard, got: {out}";
    # All three types must have been collected.
    collect_markers = [line for line in out.split("\n") if "[collect]" in line];
    assert len(collect_markers) == 3,
        f"expected 3 [collect] markers (Top, Middle, Base), got: {out}";
}

test "visited list contains each type at most once" {
    # Build the cyclic graph and confirm the walker's `visited` accumulator
    # is itself the visited set: no GoType appears twice, even though the
    # graph has a cycle. This is the structural pin against the bug — the
    # failure mode was "loop forever", which would have produced an
    # unbounded visited list (or a stack overflow). A bounded visited list
    # proves the guard fired.
    entry_node = build_self_ref_graph();

    buf = io.StringIO();
    w = FieldCollector();
    with redirect_stdout(buf) {
        root spawn w;
    }
    out = buf.getvalue();

    names = [v.name for v in w.visited];
    assert len(names) == len(set(names)),
        f"visited must be a set-equivalent, got duplicates: {names}";
    assert "selfRef" in names, f"selfRef missing from visited: {names}";
    # The cycle only has one type, so visited must hold exactly one entry.
    assert len(names) == 1, f"expected 1 visited entry on selfRef cycle, got {names}";

    # Sanity: the cycle-skip log line is present so we know the guard ran.
    assert "[skip-cycle] selfRef already on path" in out,
        f"cycle guard did not fire: {out}";
}

test "falsify: an unguarded collector would loop on the selfRef cycle" {
    # This test documents the failure mode the guard prevents. It does not
    # actually run an unguarded walker (which would hang the test process),
    # but it pins the bug by asserting that:
    #   1. the cycle edge is present (so an unguarded walk would revisit it)
    #   2. the guard fires on that exact edge
    # A future regression that removes the visited check will flip assertion #2
    # to "marker missing" (and, in practice, hang the suite) — exactly the
    # "process kill, not a red test" failure the issue calls out.
    entry_node = build_self_ref_graph();

    # The self-edge is present and is the only out-edge from selfRef.
    outs = [entry_node ->:Embeds:->];
    assert len(outs) == 1, f"selfRef must have exactly one Embeds edge, got {len(outs)}";
    assert outs[0].name == "selfRef",
        f"self-edge must point back at selfRef, got {outs[0].name}";

    buf = io.StringIO();
    w = FieldCollector();
    with redirect_stdout(buf) {
        root spawn w;
    }
    out = buf.getvalue();

    # The guard must fire on the cycle edge. If it doesn't, the walker is
    # looping (and this test will hang before reaching the assert).
    assert "[skip-cycle] selfRef already on path" in out,
        f"cycle guard did not fire — walker would loop forever. Output: {out}";
    # And we must have returned with a bounded collected list, not a hang.
    assert len(w.collected) >= 1,
        f"expected at least one collected field, got {w.collected}";
}

