"""Category tree: hierarchical product categories walked via typed parent/child edges.

Models the GET /api/categories scenario: categories form a tree, products
belong to categories, and a walker traverses parent -> child edges to build
a hierarchical view with depth limits and product counts.
"""

node Category {
    has id: str = "";
    has name: str = "";
    has slug: str = "";
    has description: str = "";
    has image_url: str = "";
    has image_alt: str = "";
    has is_active: bool = True;
    has display_order: int = 0;
    has product_count: int = 0;
}

node Product {
    has id: str = "";
    has name: str = "";
    has price: float = 0.0;
}

edge ParentOf {
    has order: int = 0;
}

edge CategorizedAs {
    has assignment_order: int = 0;
}

walker ProductCounter {
    has target: str = "";
    has tally: int = 0;

    can start with Category entry {
        visit [->:CategorizedAs:->];
    }

    can count with Product entry {
        self.tally = self.tally + 1;
    }
}

walker CategoryBrowser {
    has max_depth: int = 2;
    has current_depth: int = 0;
    has include_empty: bool = False;
    has include_count: bool = True;
    has visited_ids: list[str] = [];
    has snapshot: list[dict] = [];
    has report: list[str] = [];

    can start with Root entry {
        self.current_depth = 0;
        self.visited_ids = [];
        self.snapshot = [];
        visit [-->];
    }

    can browse with Category entry {
        if self.current_depth >= self.max_depth {
            disengage;
        }
        for vid in self.visited_ids {
            if vid == here.id {
                disengage;
            }
        }
        self.visited_ids.append(here.id);

        show = self.include_empty or here.product_count > 0;
        if show {
            reported_count = here.product_count if self.include_count else 0;
            indent = "  " * self.current_depth;
            line = f"{indent}- {here.name} (count={reported_count}, order={here.display_order})";
            self.report.append(line);
            entry: dict = {
                "id": here.id,
                "name": here.name,
                "slug": here.slug,
                "description": here.description,
                "isActive": here.is_active,
                "displayOrder": here.display_order,
                "productCount": reported_count,
                "children": []
            };
            self.snapshot.append(entry);
        }
        self.current_depth = self.current_depth + 1;
        visit [->:ParentOf:->];
    }
}

walker EmptyCategoryPruner {
    has pruned_ids: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can prune with Category entry {
        if here.product_count == 0 {
            self.pruned_ids.append(here.id);
        }
        visit [-->];
    }
}

