"""Databricks workflow orchestration: model pipeline stages, file sensor retry,
task dependencies, and historical backfill as native Jac graph + walker.

Pipeline order: FileSensor -> RawIngestion -> Enriched -> IDS -> Curated.
"""

node Stage {
    has name: str = "";
    has catalog: str = "prod";
    has schema: str = "main";
    has run_date: str = "";
    has status: str = "PENDING";
}

node FileSensor {
    has name: str = "file_arrival_sensor";
    has poll_seconds: int = 600;
    has timeout_minutes: int = 120;
    has attempts: int = 0;
    has arrived: bool = False;
}

node BackfillJob {
    has name: str = "historical_backfill";
    has start_date: str = "";
    has end_date: str = "";
}

edge TaskFlow { has order: int = 0; }
edge Retry { has policy: str = "every_10min"; }
edge Schedule { has cron: str = "30 9 * * ?"; }
edge BackfillRange { has start: str = ""; has end: str = ""; }

walker PipelineRunner {
    has log: list[str] = [];

    can start with Root entry {
        print("=== Pipeline orchestration walk ===");
        self.log.append("begin");
        visit [-->];
    }

    can plan with FileSensor entry {
        here.attempts += 1;
        # simulate file arrival after at most 2h (12 attempts @ 10 min)
        here.arrived = here.attempts >= 1;
        marker = "ARRIVED" if here.arrived else "WAITING";
        line = f"[sensor] attempt={here.attempts} timeout={here.timeout_minutes}m -> {marker}";
        print(line);
        self.log.append(line);
        if here.arrived {
            visit [->:TaskFlow:->];
        } else {
            print("[sensor] timeout: disengage pipeline");
            disengage;
        }
    }

    can execute with Stage entry {
        here.status = "RUNNING";
        line = f"[stage] running {here.name} on {here.catalog}.{here.schema} for {here.run_date}";
        print(line);
        self.log.append(line);
        here.status = "DONE";
        visit [->:TaskFlow:->];
    }

    can finish with Root exit {
        print("=== Pipeline complete ===");
        for entry in self.log {
            print(f"  log: {entry}");
        }
    }
}

walker BackfillAuditor {
    has ranges_checked: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with BackfillJob entry {
        self.ranges_checked += 1;
        ok = here.start_date != "" and here.end_date != "" and here.start_date <= here.end_date;
        marker = "VALID" if ok else "INVALID";
        print(f"[backfill] {here.name} {here.start_date}..{here.end_date} -> {marker}");
        visit [->:BackfillRange:->];
    }
}

with entry {
    sensor = FileSensor();
    raw = Stage(name="RawIngestion", run_date="2024-09-15");
    enriched = Stage(name="Enriched", run_date="2024-09-15");
    ids = Stage(name="IDS", run_date="2024-09-15");
    curated = Stage(name="Curated", run_date="2024-09-15");
    backfill = BackfillJob(name="historical_backfill", start_date="2024-01-01", end_date="2024-09-14");

    # typed edges with dependency ordering payload
    sensor +>:TaskFlow(order=1):+> raw;
    raw +>:TaskFlow(order=2):+> enriched;
    enriched +>:TaskFlow(order=3):+> ids;
    ids +>:TaskFlow(order=4):+> curated;

    # retry policy + schedule + backfill range as typed edges off root
    root +>:Retry(policy="every_10min_upto_2h"):+> sensor;
    root +>:Schedule(cron="30 9 * * ?"):+> sensor;
    root +>:BackfillRange(start="2024-01-01", end="2024-09-14"):+> backfill;

    print("--- Daily incremental run ---");
    root spawn PipelineRunner();

    print("");
    print("--- Historical backfill audit ---");
    root spawn BackfillAuditor();
}

