# ----------------------------------------------------------------------
# Walker: bumps the epoch so we can re-run lookups against the same
# graph without rebuilding it.
# ----------------------------------------------------------------------

walker EpochReset {
    has next_epoch: int = 0;
    can begin with Root entry {
        # Walkers don't share state; in a real port the epoch is a
        # global. We simulate that by handing it out via a node field.
        epoch_node = LookupRoot(query="__epoch__");
        epoch_node.last_epoch = self.next_epoch;
        root ++> epoch_node;
        epoch_node spawn Lookup(current_epoch=self.next_epoch, query="libc.so.6");
    }
}

# ----------------------------------------------------------------------
# Helper: expose a way to run two lookups in succession on the same
# graph so the demo shows the epoch stamping both runs share storage.
# ----------------------------------------------------------------------

node EpochGate {
    has last_epoch: int = 0;
    has hits: list[str] = [];
    has query: str = "";
}

walker TwoPassAudit {
    can begin with Root entry {
        visit [-->];
    }
    can run with EpochGate entry {
        # Run a lookup, then re-run it; the second pass should still
        # correctly detect the cycle because the epoch advances.
        epoch = here.last_epoch;
        first = Lookup(current_epoch=epoch, query=here.query);
        second = Lookup(current_epoch=epoch + 1, query=here.query);
        # Just print the plan; actual spawn happens in `with entry`.
        print(f"plan: run epoch {epoch}, then epoch {epoch + 1}");
    }
}

# ----------------------------------------------------------------------
# Demo wiring: build a dependency graph with a deliberate cycle and
# spawn the walker.
# ----------------------------------------------------------------------

with entry {
    # Build the dependency graph. The cycle A -> B -> C -> A exercises
    # the cycle-detection path; D is a dangling leaf so the demo also
    # exercises dead-end handling.
    a = DlNode(name="libfoo.so", so_path="/usr/lib/libfoo.so");
    b = DlNode(name="libbar.so", so_path="/usr/lib/libbar.so");
    c = DlNode(name="libc.so.6", so_path="/lib/x86_64/libc.so.6");
    d = DlNode(name="libquux.so", so_path="/usr/lib/libquux.so");

    # Typed edges: each dependency edge carries the name of the
    # required library.
    a +>:DependsOn(required_lib="libbar.so"):+> b;
    b +>:DependsOn(required_lib="libc.so.6"):+> c;
    c +>:DependsOn(required_lib="libfoo.so"):+> a;  # the cycle
    b +>:DependsOn(required_lib="libquux.so"):+> d;

    # Entry point for the lookup.
    entry_node = LookupRoot(query="libc.so.6");
    root ++> entry_node;

    # Hook the dependency graph onto the entry so `visit [->:DependsOn:->]`
    # has somewhere to go from Root.
    root ++> a;

    # First lookup at epoch 0.
    print("=== first lookup (epoch 0) ===");
    entry_node spawn Lookup(current_epoch=0, query="libc.so.6");

    # Second lookup at a fresh epoch. The graph is unchanged but the
    # stamps from the first run no longer match, so the walker is free
    # to revisit nodes that are part of the cycle until it hits the
    # already-visited-this-epoch guard again.
    print("=== second lookup (epoch 1) ===");
    entry_node spawn Lookup(current_epoch=1, query="libc.so.6");
}

fixed.code:
"""Dependency lookup with epoch-based cycle detection.

Models the nanvix dlfcn scenario: a lookup walker traverses a graph of
libraries connected by typed dependency edges. Instead of allocating a
per-call visited set (the hand-rolled BTreeSet machinery), the walker
relies on a global epoch counter stamped onto each dependency node via
its `last_visited_epoch` field — graph coloring, native-style.
"""

# ----- Entity archetypes -----

node DlNode {
    has name: str = "";
    has last_visited_epoch: int = 0;
    has bound: bool = False;
}

node Library {
    has name: str = "";
}

# A typed edge: "this DlNode depends on that Library" (and, transitively,
# all of its DlNodes). Carries no payload beyond the relationship.
edge DependsOn { }

# ----- Walker -----

walker Lookup {
    # Global epoch counter — incremented at the start of every lookup.
    # Lives on the walker instance so each spawned walker has its own
    # coloring run, exactly like the per-call atomic in the issue.
    has epoch: int = 0;
    # Bound libraries accumulated during the traversal.
    has bound_order: list[str] = [];

    can begin with Root entry {
        # Bump the global epoch for this lookup. This is the analog of
        # `CURRENT_EPOCH.fetch_add(1, Relaxed)` in the proposal.
        self.epoch = Lookup.next_epoch();
        visit [-->];
    }

    can follow_lib with Library entry {
        print(f"  entering library {here.name}");
        # Now descend into every DlNode attached via DependsOn.
        visit [->:DependsOn:->];
    }

    can color_and_bind with DlNode entry {
        # Graph-coloring check: if this node already carries the current
        # epoch, we are revisiting it on a cycle — skip without locking.
        if here.last_visited_epoch == self.epoch {
            print(f"  skip {here.name}: already colored this epoch (cycle)");
            return;
        }
        # Stamp the node with the current epoch — the "color" for this
        # round. Then do the bind work that the issue's lookup performs.
        here.last_visited_epoch = self.epoch;
        here.bound = True;
        self.bound_order.append(here.name);
        print(f"  bound {here.name}");
        visit [-->];
    }

    # Shared, monotonically increasing epoch source across all walkers.
    static has _clock: int = 0;

    static def next_epoch() -> int {
        Lookup._clock = Lookup._clock + 1;
        return Lookup._clock;
    }
}

# ----- Demo wiring -----

with entry {
    # Build a small library graph with a cycle, the bug that motivated
    # the original BTreeSet fix and the proposed coloring scheme.
    lib_a = Library(name="lib_a");
    lib_b = Library(name="lib_b");
    lib_c = Library(name="lib_c");

    # Dependency nodes hang off each library via typed DependsOn edges.
    # The same node may be reached from multiple libraries — the cycle.
    a1 = DlNode(name="a1");
    a2 = DlNode(name="a2");
    b1 = DlNode(name="b1");
    c1 = DlNode(name="c1");
    shared = DlNode(name="shared");   # creates the cycle a1 -> b1 -> shared -> a2 -> shared

    root ++> lib_a;
    root ++> lib_b;
    root ++> lib_c;

    lib_a +>:DependsOn:+> a1;
    a1 +>:DependsOn:+> b1;
    lib_b +>:DependsOn:+> b1;
    b1 +>:DependsOn:+> shared;
    shared +>:DependsOn:+> a2;
    lib_a +>:DependsOn:+> a2;
    a2 +>:DependsOn:+> shared;        # back-edge forming the cycle
    lib_c +>:DependsOn:+> c1;

    print("=== first lookup (epoch 1) ===");
    lk1 = Lookup();
    root spawn lk1;
    print(f"bound order: {lk1.bound_order}");
    # The shared node must be bound exactly once even though it is
    # reachable on two distinct paths — coloring guarantees that.

    print("=== second lookup (epoch 2) ===");
    lk2 = Lookup();
    root spawn lk2;
    print(f"bound order: {lk2.bound_order}");
}

