"""Structural invariant checkers (BST ordering, heap property, linked-list acyclicity).

Models data-structure invariants as graph archetypes: BST nodes connected by
``BSTEdge``, heap slots connected by ``HeapEdge``, and linked-list nodes
connected by ``NextEdge``. Walker(s) traverse each structure and report
violations through a shared ``InvariantResult`` counterexample format.
"""

node TreeNode {
    has value: int = 0;
    has lo: int = 0;
    has hi: int = 0;
}

node HeapNode {
    has value: int = 0;
    has parent_value: int = 0;
    has is_root: bool = False;
}

node ListNode {
    has value: int = 0;
}

edge BSTEdge { }
edge HeapEdge { }
edge NextEdge { }

node InvariantResult {
    has name: str = "";
    has passed: bool = True;
    has counterexample: str = "";
}

walker BSTChecker {
    can start with Root entry {
        visit [->:BSTEdge:->];
    }

    can check with TreeNode entry {
        ok_lo = here.value >= here.lo;
        ok_hi = here.value <= here.hi;
        if not ok_lo or not ok_hi {
            msg = (
                f"BST violation at value={here.value}: "
                f"expected {here.lo} <= v <= {here.hi}"
            );
            print(f"[BST] FAIL :: {msg}");
            result = InvariantResult(name="bst_ordering", passed=False, counterexample=msg);
            disengage;
        } else {
            print(f"[BST] ok :: value={here.value} in [{here.lo},{here.hi}]");
            visit [->:BSTEdge:->];
        }
    }
}

walker HeapChecker {
    can start with Root entry {
        visit [->:HeapEdge:->];
    }

    can check with HeapNode entry {
        if here.is_root {
            print(f"[HEAP] ok :: root value={here.value}");
            visit [->:HeapEdge:->];
        } else {
            if here.parent_value <= here.value {
                print(
                    f"[HEAP] ok :: parent={here.parent_value} <= "
                    f"child={here.value}"
                );
                visit [->:HeapEdge:->];
            } else {
                msg = (
                    f"Heap violation: parent={here.parent_value} "
                    f"> child={here.value}"
                );
                print(f"[HEAP] FAIL :: {msg}");
                result = InvariantResult(name="heap_property", passed=False, counterexample=msg);
                disengage;
            }
        }
    }
}

walker CycleChecker {
    has seen: list[int] = [];

    can start with Root entry {
        visit [->:NextEdge:->];
    }

    can check with ListNode entry {
        marker = here.value;
        already = False;
        for s in self.seen {
            if s == marker {
                already = True;
            }
        }
        if already {
            msg = f"Cycle detected revisiting node value={marker}";
            print(f"[LIST] FAIL :: {msg}");
            result = InvariantResult(name="acyclicity", passed=False, counterexample=msg);
            disengage;
        } else {
            self.seen.append(marker);
            print(f"[LIST] ok :: visited value={marker}");
            visit [->:NextEdge:->];
        }
    }
}

with entry {
    # --- BST demo: one bad insert that breaks ordering ---
    n1 = TreeNode(value=10, lo=-1000, hi=1000);
    n2 = TreeNode(value=5, lo=-1000, hi=10);
