"""Taint-reachability mismatch demo.

Models the scenario from knostic/OpenAnt issue #310: a documented reachability
filter promises exploitability, but the computation is actually a forward BFS
over a *static call graph*. Some units that look "isolated" only look that way
because the parser failed to record a call edge (alias imports, ``@property``
reads, methods on typed parameters, ``__init__.py`` functions, etc.). The
walker below reports the discrepancy between what the documentation claims
("not reachable ⇒ not exploitable") and what the BFS actually proves.

The fix in the issue is documentation-only; here we surface the gap with a
walker that compares the BFS-reachable set against the four known missing-edge
constructs, so the maintainer can see that "isolated" units and
"parser-blind" units collapse into the same bucket.
"""

# ---------------------------------------------------------------------------
# Node archetypes
# ---------------------------------------------------------------------------

node Unit {
    # A callable in the analyzed codebase. ``kind`` distinguishes real entry
    # points (user-facing handlers) from helpers, properties, and methods that
    # the parser may or may not have wired into the call graph.
    has name: str = "";
    has kind: str = "helper";  # "entry" | "helper" | "property" | "method"
    has recorded_calls: list[str] = [];  # names of units this one calls (edges the parser saw)
    has documented_safe: bool = True;  # the docstring's claim: no caller ⇒ not exploitable
}

node Finding {
    # A finding about a unit's reachability + the missing-edge class that
    # explains why the BFS might mis-classify it. ``severity`` is a string so
    # the walker can sort/report without extra wiring.
    has unit_name: str = "";
    has verdict: str = "";          # "reachable" | "isolated"
    has why: str = "";              # "parser-blind" | "genuinely-dead" | "ok"
    has severity: str = "info";
}

# ---------------------------------------------------------------------------
# Typed edges
# ---------------------------------------------------------------------------

# Calls edges carry the source → target relationship the static parser
# actually recorded. A unit with zero outgoing Calls edges AND zero incoming
# edges is what the filter calls "isolated".
edge Calls {
    has site: str = "";  # where the call was recorded (file:line) — purely informative
}

# Documents: the pipeline manual claims a unit is "not exploitable" when the
# reachability filter drops it. This edge represents that *claim*, not a real
# call — keeping it separate from Calls makes the misuse visible.
edge Documents {
    has claim: str = "";
}

# ---------------------------------------------------------------------------
# Walker: compare BFS reachability against the four documented missing-edge
# classes and report each unit's verdict + the reason for the gap.
# ---------------------------------------------------------------------------

walker ReachabilityAuditor {
    has visited: list[str] = [];
    has forward_reachable: list[str] = [];

    can start with Root entry {
        # Phase 1: forward BFS over typed Calls edges from every entry-point
        # Unit. We do this manually because jac 0.36.1 walkers have no
        # built-in visited-set on `visit [->:Calls:->]`, and we need to stop
        # at a known frontier without revisiting nodes.
        for u in [-->]:
            if u.kind == "entry" {
                self._bfs(u);
            }
        self.forward_reachable = self.visited;

        # Phase 2: build one Finding per Unit. For each unit we record the
        # BFS verdict and, when the unit is "isolated", we annotate it with
        # the parser-blind class it falls into. This is the gap the issue
        # describes: the documentation cannot tell these apart.
        for u in [-->]:
            f = Finding(
                unit_name=u.name,
                verdict = "reachable" if u.name in self.forward_reachable else "isolated",
                why = self._classify(u),
                severity = "warn" if (u.kind in ["entry", "property", "method"])
                                  and (u.name not in self.forward_reachable)
                                  else "info",
            );
            root +>:Documents(claim="not reachable ⇒ not exploitable"):+> f;
        }

        # Single exit report.
        report {
            "forward_reachable": self.forward_reachable,
            "findings": [f.unit_name + "=" + f.verdict + " (" + f.why + ")" for f in [-->]],
        };
        disengage;
    }

    # The BFS uses a queue + visited list because typed-edge visits in jac
    # 0.36.1 don't dedupe (probe-verified). This is the exact "scaffolding"
    # the original Python reachability_analyzer hand-rolled.
    def _bfs(u: Unit) -> None {
        queue: list[Unit] = [u];
        i = 0;
        while i < len(queue) {
            cur = queue[i];
            i += 1;
            if cur.name in self.visited {
                continue;
            }
            self.visited.append(cur.name);
            for callee in [cur->:Calls:->]:
                if callee.name not in self.visited {
                    queue.append(callee);
                }
            }
        }
    }

    # Classify why a unit ended up in the "isolated" bucket. The four
    # categories mirror issue #309's reported missing-edge constructs.
    def _classify(u: Unit) -> str {
        if u.name in self.forward_reachable {
            return "ok";
        }
        tag = u.kind;
        if tag == "property" {
            return "parser-blind:@property read produces no Calls edge";
        }
        if tag == "method" {
            return "parser-blind:method on type-annotated param produces no Calls edge";
        }
        if tag == "entry" {
            return "parser-blind:__init__.py function / import-alias seed missing";
        }
        # default helpers with no recorded calls are genuinely unreachable
        return "genuinely-dead:no recorded caller";
    }
}

with entry {
    # Entry points — the parser did record these as roots.
    e1 = Unit(name="views.handle_request", kind="entry");
    e2 = Unit(name="cli.dispatch", kind="entry");

    # A normal helper reached by a recorded call.
    h1 = Unit(name="auth.check_token", kind="helper");

    # The four parser-blind units. Each has no outgoing Calls edge in the
    # static graph, so the BFS will mark them "isolated" — the same bucket
    # as a genuinely-dead helper — even though at least two of them are
    # genuinely called at runtime (alias import, property read, method on
    # typed param, __init__.py function).
    blind_property = Unit(name="User.is_admin", kind="property");
    blind_method = Unit(name="parse_typed.handle", kind="method");
    blind_alias = Unit(name="pkg.compat.shim", kind="entry");   # ``from X import f as g``
    blind_init = Unit(name="pkg.bootstrap", kind="entry");      # function in __init__.py

    # Genuinely dead helper — no calls anywhere.
    truly_dead = Unit(name="legacy.maybe_used", kind="helper");

    # Wire the recorded calls. ``e1 -> h1`` is the one happy path.
    root ++> e1 +>:Calls(site="views.py:12"):+> h1;
    root ++> e2;
    root ++> blind_property;
    root ++> blind_method;
    root ++> blind_alias;
    root ++> blind_init;
    root ++> truly_dead;

    auditor = ReachabilityAuditor();
    root spawn auditor;
    for line in auditor.report {
        print(line);
    }
}

