"""Reachability filter: forward BFS over a call graph with no taint state.

Models the gap between the documented claim ("not reachable ⇒ not exploitable")
and what the filter actually computes ("no recorded call edge ⇒ dropped"). The
filter is a plain forward closure over the typed Call edge; unrecorded edges
look identical to genuinely dead code in the output.
"""

node Function {
    has name: str = "";
    has reachable: bool = False;
}

node EntryPoint {
    has name: str = "";
}

edge Call {
    # A typed edge from caller -> callee representing one recorded call site.
}

walker ReachabilityAnalyzer {
    has visited: list[str] = [];

    can start with Root entry {
        print("BFS forward from entry points over typed Call edges");
        visit [->:Call:->];
    }

    can step with Function entry {
        # Forward BFS over the call graph: mark reached, continue along Calls.
        if here.name not in self.visited {
            self.visited.append(here.name);
            here.reachable = True;
            print(f"REACHABLE  {here.name}");
        }
        visit [->:Call:->];
    }
}

walker ExploitabilityReporter {
    # Reads the documented promise and reports it against the actual state.
    can start with Root entry {
        print("--- exploitability verdict (per documentation) ---");
        visit [-->];
    }

    can report with Function entry {
        verdict = "exploitable" if here.reachable else "not exploitable";
        print(f"{here.name}: {verdict}");
        visit [-->];
    }
}

with entry {
    # Entry seeds — what the analyzer starts from.
    e1 = EntryPoint(name="main_handler");

    # The call graph as typed Call edges.
    a = Function(name="route_request");
    b = Function(name="unsafe_eval");
    c = Function(name="helper_function");
    d = Function(name="log_event");

    e1 +>:Call:+> a;
    a +>:Call:+> b;
    a +>:Call:+> d;

    # `helper_function` deliberately has NO incoming Call edge — the documented
    # "isolated" case. It looks identical to genuinely dead code from here.
    root ++> e1 ++> a ++> b;
    root ++> c ++> d;

    root spawn ReachabilityAnalyzer();
    print("");
    root spawn ExploitabilityReporter();
    print("");
    print("note: helper_function() has no recorded caller and is reported");
    print("      'not exploitable' even though 'no edge recorded' != 'dead code'");
}

