"""Mobile app store prep: dependency-ordered task graph for T126 Privacy Labels.

Models the issue's "Polish & Store Prep" phase as a typed-edge dependency DAG.
A walker traverses the task graph in dependency order (so T126 only runs
after T122 is done) and reports which tasks are ready, blocked, or complete.
Includes a depth-bounded cascade invalidation walker for when a prerequisite
fails, mirroring the issue's "regression blocks release" rule.
"""

# ---------- Entity archetypes ----------

node Task {
    has task_id: str = "";
    has title: str = "";
    has phase: int = 0;
    has status: str = "pending";   # pending | in_progress | done | failed
    has parallelizable: bool = False;
}

node Gate {
    has gate_id: str = "";
    has phase: int = 0;
    has passed: bool = False;
}

node Evidence {
    has gate_id: str = "";
    has kind: str = "";            # lint | typecheck | test | archive | a11y | external_testflight
    has result: str = "pending";   # pending | green | red
}

# ---------- Typed edges (relationship carries meaning) ----------

edge DependsOn { }       # a DependsOn b: a needs b to finish first
edge BelongsTo { }       # Task BelongsTo Gate
edge VerifiesGate { }    # Evidence VerifiesGate Gate
edge Follows { }         # Task Follows Task (sequential gate ordering)

# ---------- Walker: order tasks by dependency for T126 ----------

walker DependencyAuditor {
    has visited_ids: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 8;

    can start with Root entry {
        print(f"Auditing mobile store-prep dependency graph (depth cap={self.max_depth})...");
        visit [-->];
    }

    # Union trigger: a Task or a Gate may sit on the root's outgoing frontier.
    can scan with Task | Gate | Evidence entry {
        if self.depth > self.max_depth {
            print(f"  depth cap hit at depth={self.depth}; disengaging to prevent runaway traversal");
            disengage;
        }
        self.depth += 1;

        if isinstance(here, Task) {
            self._record_visit(here.task_id);
            ready = self._count_incomplete_prereqs();
            label = "READY" if ready == 0 and here.status == "pending" else here.status.upper();
            print(f"  Task {here.task_id} ({here.title}) phase={here.phase} -> {label}; open_prereqs={ready}");
            if here.task_id == "T126" and ready == 0 and here.status == "pending" {
                print("  >> T126 prerequisites all complete: Privacy labels can be finalized.");
            }
        elif isinstance(here, Gate) {
            mark = "GREEN" if here.passed else "BLOCKED";
            print(f"  Gate {here.gate_id} phase={here.phase} -> {mark}");
        else {
            # Evidence
            mark = "GREEN" if here.result == "green" else here.result.upper();
            print(f"  Evidence[{here.kind}] for {here.gate_id} -> {mark}");
        }

        # Continue traversal across typed edges. No native once-per-node
        # dedupe in jac 0.36.1, so the visited_ids set on the walker is
        # the explicit cycle policy (issue §5 keep semantics).
        visit [->:DependsOn:->] else { visit [->:BelongsTo:->] else { visit [->:VerifiesGate:->] else { visit [->:Follows:->]; }; }; };
    }

    def _record_visit(id: str) -> None {
        if id not in self.visited_ids {
            self.visited_ids.append(id);
        }
    }

    def _count_incomplete_prereqs() -> int {
        # Walk only the DependsOn edges from the current Task and tally
        # non-done prereqs. This is the "N+1 query" the issue complains
        # about, lifted into a typed-edge traversal.
        n = 0;
        for prereq in [->:DependsOn:->] {
            if prereq.status != "done" {
                n += 1;
            }
        }
        return n;
    }
}

# ---------- Walker: cascade-invalidate downstream tasks when a gate fails ----------

walker CascadeInvalidator {
    has failed_gate: str = "";
    has invalidated: list[str] = [];

    can start with Root entry {
        print(f"Cascade-invalidating any task that depends on failed gate {self.failed_gate}");
        visit [-->];
    }

    can scan with Task entry {
        # A Task is invalidated if it BelongsTo a gate that has not passed,
        # or if any of its DependsOn prereqs were already invalidated.
        blocked_by_gate = False;
        for g in [->:BelongsTo:->] {
            if g.gate_id == self.failed_gate and not g.passed {
                blocked_by_gate = True;
                break;
            }
        }

        blocked_by_prereq = False;
        for p in [->:DependsOn:->] {
            if p.task_id in self.invalidated {
                blocked_by_prereq = True;
                break;
            }
        }

        if blocked_by_gate or blocked_by_prereq {
            if here.status not in ["done", "failed"] {
                here.status = "failed";
                self.invalidated.append(here.task_id);
                print(f"  ! invalidated {here.task_id} ({here.title})");
            }
        }

        visit [->:DependsOn:->];
    }
}

# ---------- Demo wiring ----------

with entry {
    # Gates along the release train (phase 14 = Polish & Store Prep).
    g2 = Gate(gate_id="G2", phase=2, passed=True);
    g3 = Gate(gate_id="G3", phase=3, passed=True);
    g5 = Gate(gate_id="G5", phase=5, passed=True);
