    t_labls = Task(task_id="T126", title="Finalize Privacy labels in App Store Connect", phase=14);
    t_rever = Task(task_id="T127", title="Performance re-verification", phase=14);

    # Dependency edges: T126 and T127 both depend on T122 (the draft).
    # T127 also depends on T125 (accessibility) per spec quickstart §G6.
    t_labls +>:DependsOn:+> t_draft;
    t_rever +>:DependsOn:+> t_draft;
    t_rever +>:DependsOn:+> t_audit;

    # Tasks belong to G6 (this phase's gate).
    t_draft +>:BelongsTo:+> g6;
    t_audit +>:BelongsTo:+> g6;
    t_labls +>:BelongsTo:+> g6;
    t_rever +>:BelongsTo:+> g6;

    # Evidence items feeding G6 — Constitution says no check-off without
    # green evidence. T127 is the only one not yet green.
    ev_lint    = Evidence(gate_id="G6", kind="lint",          result="green");
    ev_type    = Evidence(gate_id="G6", kind="typecheck",     result="green");
    ev_arch    = Evidence(gate_id="G6", kind="architecture",  result="green");
    ev_a11y    = Evidence(gate_id="G6", kind="a11y",          result="pending");
    ev_archive = Evidence(gate_id="G6", kind="archive",       result="green");
    ev_tf      = Evidence(gate_id="G6", kind="external_testflight", result="pending");

    for ev in [ev_lint, ev_type, ev_arch, ev_a11y, ev_archive, ev_tf] {
        ev +>:VerifiesGate:+> g6;
    }

    # Root wires the whole graph together.
    root ++> g2 ++> g3 ++> g5 ++> g6;
    root ++> t_draft ++> t_audit ++> t_labls ++> t_rever;

    # Run the dependency auditor.
    DependencyAuditor() spawn root;

    # Now suppose the accessibility evidence comes back red and G6 fails —
    # cascade-invalidate everything downstream of G6.
    print("");
    ev_a11y.result = "red";
    g6.passed = False;
    CascadeInvalidator(failed_gate="G6") spawn root;
