"""Vote state pill: model voters, vote targets, and a walker that audits
shared target state across test specs — the root cause of the
vote-state-pill flake.

The original bug: ``user-profile.spec.ts`` casts an up-vote on
``survivor:20`` as the shared authed user, then ``vote-state-pill.spec.ts``
clicks the up button again on the same target — which retracts the
vote, dropping the distinct-voter count to 0. The next anon-viewer
assertion therefore sees "be the first to vote" instead of
"/votes? so far$/".

We model three entity types (TestSpec, Voter, VoteTarget) connected by
typed edges, then spawn a ``SpecOrderAuditor`` walker that walks specs
in file order and reports each spec's vote on the shared target so the
deterministic ordering of the failure is observable in the demo.
"""

node VoteTarget {
    has slug: str = "";
    has distinct_voters: int = 0;
}

node Voter {
    has handle: str = "";
    has is_authed: bool = False;
}

node TestSpec {
    has file_name: str = "";
    has line: int = 0;
    has action: str = "";
}

edge Targets {
    has target_slug: str = "";
}

edge Casts {
    has vote: int = 0;
}

edge RunsBefore {
    has order_index: int = 0;
}

walker SpecOrderAuditor {
    has shared_target: str = "survivor:20";
    has log: list[str] = [];

    can start with Root entry {
        visit [->:RunsBefore:->];
    }

    can audit with TestSpec entry {
        spec_name = here.file_name;
        entry = (
            f"[{spec_name}:{here.line}] "
            f"{here.action} on {self.shared_target}"
        );
        self.log.append(entry);
        visit [->:RunsBefore:->];
    }

    can tally with VoteTarget entry {
        if here.slug == self.shared_target {
            self.log.append(
                f"final distinct_voters on {here.slug} = "
                f"{here.distinct_voters}"
            );
        }
    }
}

walker VoteStateProbe {
    can start with Root entry {
        visit [->:Targets:->];
    }

    can probe with VoteTarget entry {
        label = "votes so far" if here.distinct_voters >= 1 else "be the first to vote";
        print(f"{here.slug}: {here.distinct_voters} voter(s) -> \"{label}\"");
        visit [->:Casts:->];
    }

    can observe with Voter entry {
        print(f"  voter seen: {here.handle} (authed={here.is_authed})");
    }
}

with entry {
    survivor20 = VoteTarget(slug="survivor:20", distinct_voters=0);

    authed = Voter(handle="e2e-shared-user", is_authed=True);
    anon = Voter(handle="anon-viewer", is_authed=False);

    user_profile_a = TestSpec(file_name="user-profile.spec.ts", line=90, action="cast up-vote");
    user_profile_b = TestSpec(file_name="user-profile.spec.ts", line=152, action="cast up-vote");
    vote_pill_click = TestSpec(file_name="vote-state-pill.spec.ts", line=176, action="click up (retracts)");
    vote_pill_anon = TestSpec(file_name="vote-state-pill.spec.ts", line=212, action="assert pair label");

    root +>:RunsBefore(order_index=1):+> user_profile_a;
    user_profile_a +>:RunsBefore(order_index=2):+> user_profile_b;
    user_profile_b +>:RunsBefore(order_index=3):+> vote_pill_click;
    vote_pill_click +>:RunsBefore(order_index=4):+> vote_pill_anon;

    root +>:Targets(target_slug="survivor:20"):+> survivor20;
    user_profile_a +>:Casts(vote=1):+> authed;
    authed +>:Casts(vote=1):+> survivor20;
    survivor20.distinct_voters = 1;
    user_profile_b +>:Casts(vote=1):+> authed;
    user_profile_b +>:Casts(vote=1):+> survivor20;
    survivor20.distinct_voters = 1;

    vote_pill_click +>:Casts(vote=-1):+> authed;
    authed +>:Casts(vote=-1):+> survivor20;
    survivor20.distinct_voters = 0;

    anon +>:Casts(vote=0):+> survivor20;

    auditor = SpecOrderAuditor(shared_target="survivor:20");
    root spawn auditor;

    print("spec execution trace:");
    for (i, line) in enumerate(auditor.log) {
        print(f"  {i + 1}. {line}");
    }

    print("");
    print("final vote-state probe:");
    root spawn VoteStateProbe();
}

