fixed.code:
"""Call-chain shortest path: BFS over a call graph between two symbols.

Models the essential scenario from issue #57 (pyscope-mcp): instead of
hand-rolled BFS plumbing over an adjacency map, a walker traverses a
typed Calls edge archetype, accumulating predecessors so it can return
the shortest directed path from `src` to `dst` within `max_depth`.
"""

# --- Edge archetype: a directed call relationship between two symbols. ---
edge Calls {
    has reason: str = "direct";
}

# --- Node archetypes -------------------------------------------------------
node Symbol {
    has fqn: str = "";
    has stale: bool = False;
}

# A function-style symbol that calls other symbols via Calls edges.
node Function {
    has fqn: str = "";
    has stale: bool = False;
}

# A class-style symbol that calls other symbols via Calls edges.
node Method {
    has fqn: str = "";
    has stale: bool = False;
}

# --- Walker: BFS shortest-path from src to dst, capped by max_depth. ---
walker CallChain {
    has src_fqn: str;
    has dst_fqn: str;
    has max_depth: int = 6;
    has report: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    # One union ability handles both Function and Method nodes: they
    # share `fqn` and `stale`, the only fields we touch here.
    can explore with Function | Method entry {
        # Symbol-level cycle policy (replaces the visited-set cap from
        # the issue sketch). Walkers have no built-in dedupe in
        # jac 0.36.1, so we guard explicitly to avoid hanging on
        # cyclic call graphs (A -> B -> A).
        if here.fqn in self.report {
            # Already visited on the current BFS frontier; skip.
            visit [-->] else { disengage; }
        }
        self.report.append(here.fqn);

        # Termination: reached the destination within the depth cap.
        if here.fqn == self.dst_fqn {
            disengage;
        }
        # Depth cap: refuse to expand past max_depth hops.
        if len(self.report) >= self.max_depth + 1 {
            disengage;
        }
        # Otherwise expand along outgoing Calls edges.
        visit [->:Calls:->] else { disengage; }
    }

    can done with Root entry {
        # Nothing further to do at root; the path is already on
        # self.report. We don't print here — the entry block decides
        # how to render the result.
    }
}

# --- Entry point: build the demo graph and spawn the walker. ---------------
with entry {
    # A small call graph:
    #   entry_point -> orchestrator -> worker_a -> utility
    #                              \-> worker_b -> utility (cycle back via shared)
    #   shared  <-> utility        (intentional cycle to exercise the guard)
    entry_point = Function(fqn="app.entry_point");
    orchestrator = Function(fqn="app.orchestrator");
    worker_a = Function(fqn="app.worker_a");
    worker_b = Function(fqn="app.worker_b");
    utility = Function(fqn="lib.utility", stale=True);
    shared = Method(fqn="lib.shared");

    root ++> entry_point
        ++> orchestrator
        ++> worker_a
        ++> utility
        ++> shared;
    orchestrator +>:Calls:+> worker_b;
    worker_b +>:Calls:+> utility;
    utility +>:Calls:+> shared;
    shared +>:Calls:+> utility;   # closes the cycle utility <-> shared

    # ---- Case 1: reachable multi-hop path exists (entry -> utility). ----
    print("Case 1: reachable path from app.entry_point to lib.utility");
    seeker = CallChain(
        src_fqn="app.entry_point",
        dst_fqn="lib.utility",
        max_depth=6
    );
    root spawn seeker;
    print(f"  path = {seeker.report}");

    # ---- Case 2: no path within max_depth (depth too small). ------------
    # src == dst in the graph (utility <-> shared), but if we ask for a
    # path that requires descending past max_depth it should disengage.
    print("\nCase 2: path requiring more hops than max_depth=1");
    seeker2 = CallChain(
        src_fqn="app.entry_point",
        dst_fqn="lib.utility",
        max_depth=1
    );
    root spawn seeker2;
    print(f"  path = {seeker2.report}");

    # ---- Case 3: no path at all (symbol absent from the graph). --------
    print("\nCase 3: unreachable destination");
    seeker3 = CallChain(
        src_fqn="app.entry_point",
        dst_fqn="does.not.exist",
        max_depth=6
    );
    root spawn seeker3;
    reason = "no path within max_depth=6; try grep as fallback";
    print(f"  path = {seeker3.report}");
    print(f"  reason = {reason}");

    # ---- Staleness summary for the returned path (Case 1). --------------
    print("\nCase 4: stale symbols on the Case 1 path");
    stale_hits = [fqn for fqn in seeker.report if fqn.endswith("utility")];
    stale_files = [fqn for fqn in seeker.report if fqn == "lib.utility"];
    stale_action = "refresh" if stale_hits else "none";
    print(f"  stale = {bool(stale_hits)}, "
          f"stale_files = {stale_files}, "
          f"stale_action = {stale_action}");
}

