test "direct call chain uses the default depth" {
    src = Function(fqn="app.src");
    dst = Method(fqn="lib.dst");

    root ++> src;
    src +>:Calls:+> dst;

    res = root spawn CallChain(
        src_fqn="app.src",
        dst_fqn="lib.dst"
    );

    assert res.report == ["app.src", "lib.dst"], f"got {res.report}";
}

test "multi-hop call chain preserves traversal order" {
    src = Function(fqn="app.src");
    mid = Method(fqn="app.mid");
    dst = Function(fqn="lib.dst");

    root ++> src;
    src +>:Calls:+> mid;
    mid +>:Calls:+> dst;

    res = root spawn CallChain(
        src_fqn="app.src",
        dst_fqn="lib.dst",
        max_depth=3
    );

    assert res.report == ["app.src", "app.mid", "lib.dst"], f"got {res.report}";
}

test "missing destination is not reported as reachable" {
    src = Function(fqn="app.src");
    helper = Function(fqn="app.helper");

    root ++> src;
    src +>:Calls:+> helper;

    res = root spawn CallChain(
        src_fqn="app.src",
        dst_fqn="does.not.exist"
    );

    assert "does.not.exist" not in res.report, f"got {res.report}";
    assert res.report == ["app.src", "app.helper"], f"got {res.report}";
}

test "cyclic calls terminate within the depth bound" {
    first = Function(fqn="app.first");
    second = Method(fqn="app.second");

    root ++> first;
    first +>:Calls:+> second;
    second +>:Calls:+> first;

    res = root spawn CallChain(
        src_fqn="app.first",
        dst_fqn="missing.target",
        max_depth=2
    );

    assert len(res.report) <= 3, f"cycle exceeded depth cap: {res.report}";
    assert res.report[0] == "app.first", f"got {res.report}";
}

