"""Cargo build timings: model dependency resolution and download phases as a graph.

The original issue complains that `cargo build --timings` produces a graph
where dependency resolution + crate downloads happen "off-graph", leaving
large silent gaps. This demo lifts that machinery into idiomatic Jac:
each build phase is a node, each timing event is recorded by walking the
dependency tree and reporting per-phase durations via a walker that emits
a single exit report.
"""

# ---- Entity archetypes ---------------------------------------------------------

node BuildPhase {
    has name: str = "";
    has duration_ms: int = 0;
}

node IndexUpdate {
    has registry: str = "crates.io";
    has duration_ms: int = 0;
}

node CrateDownload {
    has crate_name: str = "";
    has version: str = "";
    has duration_ms: int = 0;
}

# ---- Typed edges (relationship carries meaning) --------------------------------

edge PhaseOf { has order: int = 0; }
edge DependsOn { }

# ---- Walker: traverse the build timing graph and emit a single report ---------

walker TimingAuditor {
    has total_ms: int = 0;
    has phase_count: int = 0;
    has slow_downloads: list = [];

    can start with Root entry {
        visit [->:PhaseOf:->];
    }

    can audit_phase with BuildPhase entry {
        self.phase_count += 1;
        self.total_ms += here.duration_ms;
        print(f"[phase] {here.name}: {here.duration_ms} ms");
        visit [->:DependsOn:->];
    }

    can audit_index with IndexUpdate entry {
        self.phase_count += 1;
        self.total_ms += here.duration_ms;
        print(f"[index] update {here.registry}: {here.duration_ms} ms");
        visit [->:DependsOn:->];
    }

    can audit_download with CrateDownload entry {
        self.phase_count += 1;
        self.total_ms += here.duration_ms;
        marker = "SLOW" if here.duration_ms > 200 else "ok";
        print(f"[crate] {here.crate_name}@{here.version}: "
              f"{here.duration_ms} ms ({marker})");
        if here.duration_ms > 200 {
            self.slow_downloads.append(
                [here.crate_name, here.version, here.duration_ms]
            );
        }
    }

    can summarize with Root entry {
        print("--- timing report ---");
        print(f"total phases: {self.phase_count}");
        print(f"total time:   {self.total_ms} ms");
        if len(self.slow_downloads) > 0 {
            print("slow downloads flagged:");
            for entry in self.slow_downloads {
                name = entry[0];
                ver = entry[1];
                ms = entry[2];
                print(f"  {name}@{ver} = {ms} ms");
            }
        } else {
            print("no slow downloads");
        }
    }
}

# ---- Demo wiring ---------------------------------------------------------------

with entry {
    # Build phase timeline: index_update -> resolve -> compile -> link
    index_update = IndexUpdate(registry="crates.io", duration_ms=1900);
    resolve = BuildPhase(name="resolve", duration_ms=80);
    compile = BuildPhase(name="compile", duration_ms=450);
    link = BuildPhase(name="link", duration_ms=60);

    # Crate downloads (some slow, some fast).
    serde = CrateDownload(crate_name="serde", version="1.0.219",
                          duration_ms=120);
    tokio = CrateDownload(crate_name="tokio", version="1.41.1",
                          duration_ms=340);
    clap = CrateDownload(crate_name="clap", version="4.5.20",
                         duration_ms=90);

    # Wire the timeline with typed edges. PhaseOf carries ordering.
    root +>:PhaseOf(order=0):+> index_update;
    root +>:PhaseOf(order=1):+> resolve;
    root +>:PhaseOf(order=2):+> compile;
    root +>:PhaseOf(order=3):+> link;

    # Index update feeds into resolution.
    index_update +>:DependsOn:+> resolve;

    # Resolution triggers downloads; compile depends on each download.
    resolve +>:DependsOn:+> serde;
    resolve +>:DependsOn:+> tokio;
    resolve +>:DependsOn:+> clap;
    compile +>:DependsOn:+> serde;
    compile +>:DependsOn:+> tokio;
    compile +>:DependsOn:+> clap;

    # Link depends on compile.
    link +>:DependsOn:+> compile;

    print("=== Timing audit ===");
    root spawn TimingAuditor();
}

