    assert len(dependency_edges) == 1, f"dependency edges: {dependency_edges}";
    assert download in download_edges, f"dependency targets: {download_edges}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn TimingAuditor();
    }

    assert res.total_ms == 60, f"total time: {res.total_ms}";
    assert res.phase_count == 3, f"phase count: {res.phase_count}";
}

