        location="jendrikseipp/vulture/scanner.py:88",
        appeared=True,
    );
    # Pre-existing finding the regression touches
    f4 = Finding(
        kind="unused-import",
        location="jendrikseipp/vulture/cli.py:12",
        appeared=False,
    );
    bad_run +>:DetectedBy:+> f1;
    bad_run +>:DetectedBy:+> f2;
    bad_run +>:DetectedBy:+> f3;
    bad_run +>:DetectedBy:+> f4;

    # The fix run only re-emits f4 (the regressions f1/f2/f3 disappear)
    fix_run +>:DetectedBy:+> f4;

    # Findings reference one another (related findings graph - cycles live here)
    f1 +>:Mentions:+> f3;
    f3 +>:Mentions:+> f1;       # <- cycle: f1 <-> f3

    # Repos that surfaced each finding
    repo_vulture = CorpusRepo(name="jendrikseipp/vulture", files=320);
    repo_requests = CorpusRepo(name="kennethreitz/requests", files=410);
    repo_flask = CorpusRepo(name="pallets/flask", files=275);

    repo_vulture +>:Hosted:+> f1;
    repo_vulture +>:Hosted:+> f2;
    repo_vulture +>:Hosted:+> f4;
    repo_requests +>:Hosted:+> f3;
    repo_flask +>:Hosted:+> f4;

    root ++> bad_run ++> fix_run;
    root ++> pr;

    root spawn BlastRadius();
}

