import io;
import from contextlib { redirect_stdout }

test "depth cap refuses nested review" {
    turn = ReviewTurn(label="root-review", depth=0);
    skill = Skill(
        name="local-review-helper",
        description="broad review matcher",
        launches_review=True,
        depth=0
    );
    root ++> turn;
    turn +>:InheritsSkill(inherited_at="parent"):+> skill;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ReviewChain(max_depth=1);
    }
    out = buf.getvalue();

    assert "[TURN depth=0] root-review" in out, f"missing root turn: {out}";
    assert "[GUARD] would exceed max_depth=1" in out, f"missing guard: {out}";
    assert "child-" not in out, f"unexpected child review: {out}";
}

