"""bioc-registry gap: a package is propagated but invisible when upstream loses metadata.

The scenario: an index entry can carry artifacts in the CAS while the upstream
record becomes a null stub, so the package exists by URL but is unreachable by
name from PACKAGES/VIEWS. The walker audits reachability of every propagated
package, surfaces the gap, and can either purge the invisible ones or restore
them from the propagation ledger.
"""

node Universe {
    has name: str = "";
    has index_size: int = 0;
}

node Package {
    has name: str = "";
    has version: str = "";
    has in_index: bool = False;
    has in_packages: bool = False;
    has in_views: bool = False;
    has desc: str = "";
    has meta: str = "";
    has upstream_alive: bool = False;
    has cas_has_artifact: bool = False;
}

node LedgerEntry {
    has pkg_name: str = "";
    has captured_version: str = "";
    has captured_desc: str = "";
    has captured_meta: str = "";
}

edge Propagated {
    has since: str = "";
}

edge Described {
    has source: str = "";
}

edge Recorded {
    has log_ts: str = "";
}

walker GapAuditor {
    has invisible: list = [];
    has installable: list = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Universe entry {
        print(f"--- auditing universe '{here.name}' (index entries: {here.index_size}) ---");
        visit [->:Propagated:->];
    }

    can tally with Package entry {
        reachable = here.in_packages and here.in_views;
        if here.in_index and here.cas_has_artifact and not reachable {
            reason = "null upstream, no desc stored";
            if not here.upstream_alive {
                reason = "upstream lost metadata, never re-described";
            }
            self.invisible.append((here.name, here.version, reason));
            print(f"[INVISIBLE] {here.name} {here.version}: {reason}");
        } elif here.in_index and reachable {
            self.installable.append((here.name, here.version));
            print(f"[OK] {here.name} {here.version}");
        }
        visit [-->];
    }
}

walker GapRecoverer {
    """Option (3): backfill from the propagation ledger so the package becomes installable."""

    can start with Root entry {
        visit [-->];
    }

    can enter_universe with Universe entry {
        visit [->:Propagated:->];
    }

    can maybe_recover with Package entry {
        reachable = here.in_packages and here.in_views;
        if not (here.in_index and here.cas_has_artifact and not reachable) {
            visit [-->];
            disengage;
        }
        visit [->:Recorded:->];
    }

    can restore with LedgerEntry entry {
        report = here.captured_desc != "" and here.captured_meta != "";
        if report {
            print(f"  ledger hit for {here.pkg_name}: desc+meta available -> mark installable");
        } else {
            print(f"  ledger miss for {here.pkg_name}: no desc to backfill");
        }
        visit [-->];
    }
}

walker Invalidator {
    """Cascade: any package whose upstream went null AND has no ledger backup gets purged from view."""

    can start with Root entry {
        visit [-->];
    }

    can scan with Universe entry {
        visit [->:Propagated:->];
    }

    can decide with Package entry {
        has_ledger = False;
        for _ in [->:Recorded:->] {
            has_ledger = True;
            break;
        }
        reachable = here.in_packages and here.in_views;
        if here.in_index and here.cas_has_artifact and not reachable and not has_ledger {
            print(f"[PURGE] {here.name} {here.version}: invisible, no ledger backup");
            del here;
        } else {
            print(f"[KEEP] {here.name} {here.version}");
        }
        visit [-->];
    }
}

