}

walker GapAuditor {
    has report: list = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Package entry {
        # A package is "described-but-invisible" when we propagated it with
        # real bytes (CAS artifact exists) but the registry lacks both a
        # DESCRIPTION and presence in the PACKAGES / VIEWS indices.
        if here.has_bytes and not here.desc_present
            and not here.in_packages_index and not here.in_views_index {
            entry = {
                "name": here.name,
                "version": here.version,
                "note": "propagated but invisible to R"
