"""Dependency performance demo for a CAD document graph.

Models a nui4-style document where compile / evaluation must traverse a
graph of components connected by typed dependency edges. The walker
captures the recursive traversal the issue is about: dependency walk
with an explicit visited set (Jac 0.36.1 walkers have no built-in
once-per-node guarantee, so cycle policy is explicit), cascade
invalidation when a producer node is dirtied, and an order summary
on return to root.
"""

node Component {
    has name: str = "";
    has kind: str = "compute";
    has dirty: bool = False;
}

edge DependsOn {
    has weight: int = 1;
}

edge Owns { }

walker DependencyWalker {
    has visited: list[str] = [];
    has visit_order: list[str] = [];
    has cycle_found: bool = False;
    has invalidated: list[str] = [];

    can start with Root entry {
        print(f"== walking dependency graph from root ==");
        self.visited = [];
        self.visit_order = [];
        visit [->:DependsOn:->];
    }

    can visit_node with Component entry {
        if here.name in self.visited {
            cycle_label = f"cycle detected at {here.name}";
            self.cycle_found = True;
            print(cycle_label);
            disengage;
        }
        self.visited.append(here.name);
        self.visit_order.append(here.name);
        print(f"  -> component {here.name} ({here.kind})");
        if here.dirty {
            inv_label = f"invalidate:{here.name}";
            self.invalidated.append(inv_label);
            for anc_name in self.visited {
                cascade_label = f"cascade:{anc_name}";
                self.invalidated.append(cascade_label);
            }
        }
        visit [->:DependsOn:->];
    }

    can summarize with Root entry {
        joined = ", ".join(self.visit_order);
        print(f"visit order: {joined}");
        cycle_msg = "yes" if self.cycle_found else "no";
        print(f"cycle detected: {cycle_msg}");
        inv_count = len(self.invalidated);
        print(f"invalidations issued: {inv_count}");
    }
}

with entry {
    comp_a = Component(name="A", kind="source");
    comp_b = Component(name="B", kind="transform");
    comp_c = Component(name="C", kind="transform");
    comp_d = Component(name="D", kind="sink");

