# ---------------------------------------------------------------------------
# Test 1: Basic traversal visits config + 4 global deps + 4 global envs.
# ---------------------------------------------------------------------------
test "auditor visits all top-level config nodes" {
    root ++> Config(name="turbo.json", schema="https://turbo.build/schema.json");

    c = [root -->][0];
    c +>:Requires:+> GlobalDep(path="**/.env.*local", kind="dotenv");
    c +>:Requires:+> GlobalDep(path="**/tsconfig.json", kind="tsconfig");
    c +>:Requires:+> GlobalDep(path=".nvmrc", kind="nvmrc");
