    c +>:Requires:+> GlobalEnv(name="GITHUB_ACTIONS");
    c +>:Requires:+> GlobalEnv(name="LOG_LEVEL", affects_cache=False);

    auditor = TurboAuditor();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn auditor;
    }
    out = buf.getvalue();

    assert "[CONFIG]" in out, f"missing CONFIG marker: {out}";
    assert "turbo.json" in out, f"missing config name: {out}";
