    assert "**/tsconfig.json" in out, f"missing tsconfig dep: {out}";
    assert ".nvmrc" in out, f"missing .nvmrc dep: {out}";
    assert "pnpm-lock.yaml" in out, f"missing lockfile dep: {out}";
    assert "NODE_ENV" in out, f"missing NODE_ENV env: {out}";
    assert "CI" in out, f"missing CI env: {out}";
    assert "GITHUB_ACTIONS" in out, f"missing GITHUB_ACTIONS env: {out}";
    assert "LOG_LEVEL" in out, f"missing LOG_LEVEL env: {out}";

    # 1 config + 4 deps + 4 envs = 9 nodes recorded in `visited`.
    assert len(auditor.visited) == 9, f"expected 9 visited nodes, got {len(auditor.visited)}: {auditor.visited}";
}

# ---------------------------------------------------------------------------
# Test 2: env-local deps are labelled differently from config deps.
