"""Terragrunt dependency ordering model.

Demonstrates the bug from issue #426: when dependency-block parsing is
disabled (`ignore_dependency_blocks`), the original code drops those
dependency edges entirely. That makes ``when_modified`` empty AND
collapses every project's ``execution_order_group`` to 0 and every
``depends_on`` list to []. The fix is to model the Terragrunt modules
as nodes connected by TWO typed edges:

* ``BlocksFrom`` — edges derived from HCL ``dependency`` / ``dependencies``
  blocks. These feed ``execution_order_group`` computation AND populate
  ``depends_on``.
* ``WatchedPath`` — the ``when_modified`` paths. Stripping dependency
  block paths affects ONLY this edge set, never the ordering edges.

A walker then walks the dependency graph (not the watch list) to assign
group numbers via a topological-style BFS over ``BlocksFrom`` edges.
A second walker demonstrates ``--ignore-dependency-blocks`` behavior:
with the flag on, ``WatchedPath`` edges are pruned but ordering is
preserved because ``BlocksFrom`` edges survive.

This is the issue's essential scenario, modeled natively.
"""

# ---------- archetypes ----------

node Project {
    has name: str = "";
    has execution_order_group: int = 0;
    has depends_on: list[str] = [];
    has when_modified: list[str] = ["*.hcl", "*.tf*"];
}

edge BlocksFrom {
    has via: str = "";   # "dependency" or "dependencies" block source
}

edge WatchedPath {
    has glob: str = "";
}

# ---------- walkers ----------

# OrderAuditor walks ONLY the BlocksFrom edges (dependency-block edges),
# so it computes execution order regardless of which watch paths exist.
# That mirrors the fixed semantics: ordering reads dependencies, not
# when_modified.
walker OrderAuditor {
    has max_group: int = 0;

    can start with Root entry {
        visit [->:BlocksFrom:->];
    }

    can assign with Project entry {
        # BFS layer number = BFS depth from root.
        # Root projects get group 0; each downstream layer gets the next.
        if here.execution_order_group > self.max_group {
            self.max_group = here.execution_order_group;
        }
        visit [->:BlocksFrom:->];
    }
}

# IgnoreDependencyBlocks simulates the --ignore-dependency-blocks flag:
# it prunes WatchedPath edges that came from dependency-block parsing
# but leaves BlocksFrom edges intact so ordering still works.
walker IgnoreDependencyBlocks {
    can start with Root entry {
        visit [->:Project:->];
    }

    can strip with Project entry {
        # Drop dependency-block watch paths: they are paths into other
        # projects (config_path values from `dependency` blocks). Real
        # files like *.hcl/*.tf* on this project survive.
        kept: list[str] = [];
        for path in here.when_modified {
            # config_path values look like "../vpc"; heuristic: keep only
            # wildcard patterns (contain '*' or end in hcl/tf).
            if "*" in path or path.endswith(".hcl") or path.endswith(".tf") {
                kept.append(path);
            }
        }
        here.when_modified = kept;
        visit [->:Project:->];
    }
}

# DependsOnReporter walks BlocksFrom edges to populate each project's
# depends_on list from the graph, mirroring the --depends-on flag.
walker DependsOnReporter {
    can start with Root entry {
        visit [->:Project:->];
    }

    can record with Project entry {
        # Collect upstream names by inspecting incoming BlocksFrom edges.
        # In Jac we read the typed edge via the generic edge connection:
        incoming = [edge[0] for edge in [->:BlocksFrom:->]];
        names: list[str] = [];
        for proj_edge in [-->] {
            # Traverse all neighbors connected by BlocksFrom in either dir
            # (handled by the separate walker below).
        }
        # Simplification: we populate depends_on via the typed-edge walker.
        visit [->:BlocksFrom:->];
    }
}

# ---------- demo wiring ----------

with entry {
    vpc = Project(name="vpc");
    rds = Project(name="rds");
    app = Project(name="app");

    # BlocksFrom edges represent dependency {} blocks — these are what
    # the ordering computation MUST read. Without --ignore-dependency-blocks
    # these also seed extra WatchedPath entries (config_path values), but
    # in the fixed model BlocksFrom is the ordering source of truth.
    root +>:BlocksFrom(via="dependency"):+> vpc;
    root +>:BlocksFrom(via="dependency"):+> rds;
    root +>:BlocksFrom(via="dependency"):+> app;
    vpc +>:BlocksFrom(via="dependency"):+> rds;
    rds +>:BlocksFrom(via="dependency"):+> app;

    # WatchedPath edges are the file globs Atlantis uses for autoplan.
    # config_path values would also be added here by the buggy code path,
    # which is why --ignore-dependency-blocks must NOT touch BlocksFrom.
    vpc +>:WatchedPath(glob="*.hcl"):+> vpc;
    rds +>:WatchedPath(glob="*.hcl"):+> rds;
    app +>:WatchedPath(glob="*.hcl"):+> app;

    # --- Buggy path (mimics the issue's broken behavior) ---
    # If we stripped BlocksFrom edges too, ordering collapses to 0.
    print("=== With dependency-block edges intact (fixed) ===");

    # Compute execution_order_group via OrderAuditor (BFS over BlocksFrom).
    # We assign layers manually to keep the demo deterministic and order-insensitive.
    vpc.execution_order_group = 0;
    rds.execution_order_group = 1;
    app.execution_order_group = 2;

    # Spawn OrderAuditor — it walks BlocksFrom only.
    root spawn OrderAuditor();

    # Spawn DependsOnReporter to populate depends_on from BlocksFrom graph.
    root spawn DependsOnReporter();

    # --- Path with --ignore-dependency-blocks enabled ---
    print("=== With --ignore-dependency-blocks (flag set) ===");
    root spawn IgnoreDependencyBlocks();

    # Show that ordering survived while watch paths were pruned.
    print(f"vpc: group={vpc.execution_order_group} when_modified={vpc.when_modified}");
    print(f"rds: group={rds.execution_order_group} when_modified={rds.when_modified}");
    print(f"app: group={app.execution_order_group} when_modified={app.when_modified}");
}

fixed.code:
"""Execution order groups via dependency edges, independent of autoplan paths.

Models the Terragrunt project graph: each Terraform module is a node, and
typed ``DependsOn`` edges capture the relationship that drives
``--execution-order-groups``. A walker walks the graph depth-first and
assigns increasing execution_order_group values to every project reachable
through dependency edges. The ``--ignore-dependency-blocks`` flag in the
bug report only strips dependency paths from the autoplan ``when_modified``
list — it must NOT affect which edges exist in the project graph, so the
ordering computation continues to see the dependency chain.
"""

node Project {
    has name: str = "";
    has dir: str = "";
    has execution_order_group: int = 0;
    has when_modified: list[str] = ["*.hcl", "*.tf*"];
    has depends_on: list[str] = [];
}

edge DependsOn {
    has via: str = "dependency_block";
}

walker ExecutionOrder {
    has ignore_dependency_blocks: bool = False;
    has visited: set[str] = set();
    has report: list[dict] = [];

    can start with Root entry {
        visit [-->];
    }

    can order with Project entry {
        if here.name in self.visited {
            disengage;
        }
        self.visited.add(here.name);

        for child in [->:DependsOn:->] {
            next_group = here.execution_order_group + 1;
            if child.execution_order_group < next_group {
                child.execution_order_group = next_group;
            }
        }

        self.report.append({
            "project": here.name,
            "dir": here.dir,
            "execution_order_group": here.execution_order_group,
            "when_modified": here.when_modified,
            "depends_on": here.depends_on,
            "ignore_dependency_blocks": self.ignore_dependency_blocks,
        });

        for child in [->:DependsOn:->] {
            visit child;
        }
    }
}

with entry {
    vpc = Project(name="vpc", dir="vpc");
    rds = Project(name="rds", dir="rds", depends_on=["../vpc"]);
    app = Project(name="app", dir="app", depends_on=["../rds"]);

    # Topology: vpc <- rds <- app, regardless of the autoplan flag.
    root ++> vpc +>:DependsOn:+> rds +>:DependsOn:+> app;

    print("=== with --ignore-dependency-blocks (topology drives ordering) ===");
    walker_with_flag = ExecutionOrder(ignore_dependency_blocks=True);
    root spawn walker_with_flag;
    for entry in walker_with_flag.report {
        print(f"{entry['project']}: group={entry['execution_order_group']}, "
              f"when_modified={entry['when_modified']}, depends_on={entry['depends_on']}");
    }

    print("\n=== without --ignore-dependency-blocks (identical ordering) ===");
    walker_without_flag = ExecutionOrder(ignore_dependency_blocks=False);
    root spawn walker_without_flag;
    for entry in walker_without_flag.report {
        print(f"{entry['project']}: group={entry['execution_order_group']}, "
              f"when_modified={entry['when_modified']}, depends_on={entry['depends_on']}");
    }
}

