for G3 search). A walker re-walks the train, re-measures both numbers
on the reference build, and flags regressions that block the G6
release per the project's Constitution.
"""

node Phase {
    has name: str = "";
    has gate: str = "";
    has evidence_pasted: bool = False;
    has g2_seconds: float = 0.0;
    has g3_ms: float = 0.0;
    has g2_budget: float = 5.0;
    has g3_budget: float = 50.0;
}

node Report {
    has reference_device: str = "iPhone 13";
    has build: str = "release";
    has g2_seconds: float = 0.0;
    has g3_ms: float = 0.0;
    has g2_within_budget: bool = False;
    has g3_within_budget: bool = False;
    has regression: bool = False;
}

edge Trains {
    has order_index: int = 0;
}

edge Measures {
    has delta: float = 0.0;
}

walker Verifier {
    has visited: list = [];
    has order: int = 0;

    can start with Root entry {
        self.visited = [];
        self.order = 0;
        visit [->:Trains:->];
    }

    can audit with Phase entry {
        self.order += 1;
        visit_marker = f"G{self.order}";
        self.visited.append([visit_marker, here.name, here.evidence_pasted]);
        visit [->:Measures:->];
    }

    can recheck with Report entry {
        g2_ok = here.g2_seconds <= here.owner.g2_budget;
        g3_ok = here.g3_ms <= here.owner.g3_budget;
        here.owner.g2_within_budget = g2_ok;
        here.owner.g3_within_budget = g3_ok;
        here.owner.regression = (not g2_ok) or (not g3_ok);
        verdict = "GREEN" if (g2_ok and g3_ok) else "RED";
        print(
            f"[{verdict}] {here.reference_device} / {here.build}: "
            f"G2={here.g2_seconds:.2f}s (budget {here.owner.g2_budget:.2f}s), "
            f"G3={here.g3_ms:.1f}ms (budget {here.owner.g3_budget:.1f}ms)"
        );
    }
}

walker Summary {
    can start with Root entry {
        print("Release-train re-verification (T127):");
        visit [->:Trains:->];
    }

    can roll_up with Phase entry {
        verdict = "GREEN" if not here.regression else "RED";
        evidence = "evidence attached" if here.evidence_pasted else "MISSING evidence";
        print(
            f"  {here.gate} ({here.name}) -> {verdict}; {evidence}; "
            f"G2={here.g2_seconds:.2f}s, G3={here.g3_ms:.1f}ms"
        );
        visit [->:Trains:->];
    }
}

with entry {
    p1 = Phase(
        name="Phase 12 — Stabilization",
        gate="G4",
        evidence_pasted=True,
        g2_seconds=4.6,
        g3_ms=42.0
    );
    p2 = Phase(
        name="Phase 13 — Hardening",
        gate="G5",
        evidence_pasted=True,
        g2_seconds=4.8,
        g3_ms=45.0
    );
    p3 = Phase(
        name="Phase 14 — Polish & Store Prep",
        gate="G6",
        evidence_pasted=False,
        g2_seconds=5.4,
        g3_ms=61.0
    );

    root +>:Trains(order_index=1):+> p1;
    root +>:Trains(order_index=2):+> p2;
    root +>:Trains(order_index=3):+> p3;

    p1 +>:Measures(delta=-0.4):+> Report(g2_seconds=4.6, g3_ms=42.0);
    p2 +>:Measures(delta=-0.2):+> Report(g2_seconds=4.8, g3_ms=45.0);
    p3 +>:Measures(delta=+0.4):+> Report(g2_seconds=5.4, g3_ms=61.0);

    root spawn Verifier();
    print("---");
    root spawn Summary();
}

