"""Tests for the performance re-verification auditor graph.

Covers: gate pass/fail thresholds, blocker detection for tasks without
evidence, cycle detection, topological ordering, and reachability of gates."""

import io;
import from contextlib { redirect_stdout }


test "G2 passes when measured under 5s with evidence" {
    root ++> Gate(name="G2", threshold_s=5.0, threshold_ms=0.0,
                  measured_s=4.2, measured_ms=0.0, has_evidence=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Auditor();
    }
    out = buf.getvalue();

    assert "Gate G2: measured 4.2s / 0.0ms vs threshold 5.0s / 0.0ms -> G2+G3 within budget" in out, f"missing pass line: {out}";
}

test "G2 regresses blocks release when over threshold" {
    # Constitution V: regression blocks release.
    root ++> Gate(name="G2", threshold_s=5.0, threshold_ms=0.0,
                  measured_s=7.8, measured_ms=0.0, has_evidence=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Auditor();
    }
    out = buf.getvalue();

    assert "REGRESSION" in out, f"regression not flagged: {out}";
    assert "G2+G3 within budget" not in out, f"G2 falsely marked pass: {out}";
}

test "G3 regresses blocks release when over 50ms" {
    # The other half of the T127 measurement pair.
    root ++> Gate(name="G3", threshold_s=0.0, threshold_ms=50.0,
                  measured_s=0.0, measured_ms=120.0, has_evidence=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Auditor();
    }
    out = buf.getvalue();

    assert "REGRESSION" in out, f"G3 ms regression not flagged: {out}";
}

test "task without evidence is recorded as a blocker" {
    # Constitution III: no check-off without green evidence.
    missing = Task(title="T_evidence", phase=14, has_evidence=False);
    root ++> missing;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
    out = buf.getvalue();

    assert "BLOCKER: task T_evidence missing evidence" in out, f"missing blocker line: {out}";
    assert "task T_evidence missing evidence" in res.blockers, f"blocker not recorded on walker: {res.blockers}";
    assert res.cycle_found is False, f"unexpected cycle flag: {res.cycle_found}";
}

test "dependency cycle is detected and audit aborts" {
    # A -> B -> A should trip cycle detection and prevent infinite traversal.
    a = Task(title="cycle_A", phase=14, has_evidence=True);
    b = Task(title="cycle_B", phase=14, has_evidence=True);
    root ++> a ++> b;
    a +>:DependsOn:+> b;
    b +>:DependsOn:+> a;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
    out = buf.getvalue();

    assert res.cycle_found is True, f"cycle not detected: order={res.order} blockers={res.blockers}";
    assert "CYCLE detected revisiting task cycle_A" in out, f"cycle marker missing: {out}";
}

