walker CatalogAdmin {
    has visited: list[str] = [];
    has cascade_removed: list[str] = [];
    has cycle_guard: list[str] = [];

    can begin with Root entry {
        print("=== Capability catalog walk ===");
        # Enter each top-level capability subtree in turn.
        visit [-->];
