    # Fires for any Capability node. Single ability covers all levels of the
    # tree; depth is recorded on the node itself rather than derived from a
    # shared base.
    can walk_tree with Capability entry {
        if here.capability_id in self.cycle_guard {
            disengage;
        }
        self.cycle_guard.append(here.capability_id);
        self.visited.append(here.capability_id);

        indent = "  " * here.depth;
        print(f"{indent}- [{here.capability_id}] {here.name} "
              f"(d={here.depth}, kids={here.descendant_count})");

