        visit [->:HasChild:->];
    }

    # Backtrack point — after the walker finishes a subtree, this exit
    # ability fires and the walker continues with the next sibling.
    can backtrack with Capability exit {
        # No-op; traversal order is unspecified but every reachable node
        # is recorded exactly once by the cycle guard above.
    }
}

# Performs a single-node move (BD-11 compliant): detaches the node from its
# current parent and re-attaches under a new parent at the end of the
# sibling list. Then it walks the OLD parent's children to re-sequence
# their sort_order values in place.
walker SingleNodeMover {
    has target_id: str = "";
    has new_parent_id: str = "";
    has moved: bool = False;

    can begin with Root entry {
        # First pass: locate the target + new parent and perform the
        # detach + reattach. Walk the whole catalog via typed edges.
        visit [->:HasChild:->];
    }

    can rewire with Capability entry {
        if not self.moved and here.capability_id == self.target_id {
            # Detach from current parent.
            for p in [-->] {
                p del --> here;
            }
        }
        if here.capability_id == self.new_parent_id {
            target_node: Capability | None = None;
            for c in [-->] {
                if c.capability_id == self.target_id {
                    target_node = c;
                }
            }
            if target_node is not None {
                # Re-attach under the new parent at end-of-siblings.
                here +>:HasChild(sort_order=99999):+> target_node;
                self.moved = True;
            }
        }
        visit [->:HasChild:->];
    }
