# Resequences siblings under one parent: walks every child reachable via
# HasChild and rewrites their sort_order to 0,1,2,... in walker-arrival
# order (BD-11: relative reordering is single-node only, but after a move
# the surviving siblings need a tight 0..N-1 sequence).
walker Resequencer {
    has parent_id: str = "";
    has next_order: int = 0;

    can begin with Root entry {
        visit [->:HasChild:->];
    }

    can resequence with Capability entry {
        if here.capability_id == self.parent_id {
            # Landed on the parent — now walk its children.
            visit [->:HasChild:->];
        } else {
            # We are at a child of the parent: stamp its order.
            here.sort_order = self.next_order;
            self.next_order += 1;
            # Don't recurse further — siblings only.
        }
    }
}

# Cascade-deletes a capability and every descendant beneath it. Uses an
# explicit cycle guard so re-entrant graph edits during deletion cannot
# send the walker into a loop.
walker CascadeDeleter {
    has target_id: str = "";
    has removed: list[str] = [];
    has guard: list[str] = [];

    can begin with Root entry {
        print(f"\n=== Cascade delete '{self.target_id}' ===");
        visit [->:HasChild:->];
    }

    can sweep with Capability entry {
        if self.target_id in self.guard {
            disengage;
        }

        if here.capability_id == self.target_id {
            # Descend into the subtree, removing each capability as we go.
            self.guard.append(here.capability_id);
            visit [->:HasChild:->];
            # After the subtree is gone, drop this node itself.
            self.removed.append(here.capability_id);
            del here;
            return;
        }

        # Otherwise just traverse normally.
        visit [->:HasChild:->];
    }
}

# ---------- Demo wiring ---------------------------------------------------

