    admin = CatalogAdmin();
    root spawn admin;
    print(f"\nVisited order: {admin.visited}");

    # 2. BD-11 compliant single-node move: re-parent "Go" under "Frontend".
    mover = SingleNodeMover(target_id="C-GO", new_parent_id="C-FE");
    root spawn mover;
    print(f"\nGo moved under Frontend? {mover.moved}");

    # 3. Resequence Backend's remaining children (it now has zero children
