    reseq = Resequencer(parent_id="C-BE");
    root spawn reseq;

    # 4. Cascade delete the "Frontend" capability (and React beneath it).
    deleter = CascadeDeleter(target_id="C-FE");
    root spawn deleter;
    print(f"Cascade removed: {deleter.removed}");
}

