fixed.code:
"""Bulk creation of related objects: model the O(N) save() problem and
demonstrate an O(1) walker-based bulk insert over typed parent/child edges.

This is the OSP translation of issue #297 from model-bakers/model_bakery:
`_quantity=N` previously triggered N individual save() calls on the related
class, producing N+1 queries. The idiomatic Jac version expresses the same
graph (Main → Related) as a walker that visits the related node and reports
batch insertion in a single traversal pass.
"""

# ---------------------------------------------------------------------------
# Entity archetypes
# ---------------------------------------------------------------------------

node MainModel {
    has name: str = "";
    has child_count: int = 0;
}

node RelatedModel {
    has label: str = "";
    has saved_individually: bool = True;
    has bulk_inserted: bool = False;
}

# ---------------------------------------------------------------------------
# Relationship archetype: the FK from MainModel to RelatedModel.
# ---------------------------------------------------------------------------

edge RelatedTo {
    has fk_field: str = "related";
}

# ---------------------------------------------------------------------------
# Walker that performs the OLD O(N) save() loop the issue complains about,
# then a second walker that does the O(1) bulk-insert traversal.
# ---------------------------------------------------------------------------

walker NaiveMaker {
    # Counts how many individual RelatedModel.save() calls would be issued
    # for one MainModel with N children. This is the bug from the issue.
    has saves: int = 0;
    has quantity: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can fan_out with MainModel entry {
        print(f"[NaiveMaker] MainModel={here.name}: simulating {here.child_count} individual save() calls");
        self.saves += here.child_count;
        visit [-->];
    }

    can count_save with RelatedModel entry {
        # Each RelatedModel reached via the FK forces one save().
        if here.saved_individually {
            self.saves += 1;
        }
        visit [-->];
    }

    can report with Root entry {
        print(f"[NaiveMaker] total save() calls = {self.saves}  (expected O(N), here N={self.quantity})");
    }
}

walker BulkMaker {
    # Single-pass bulk insert: visits all RelatedModels reachable through
    # the FK edge and reports one batched insert instead of N saves.
    has quantity: int = 0;
    has batched: int = 0;
    has batches: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can collect with MainModel entry {
        print(f"[BulkMaker] MainModel={here.name}: bulk-inserting {here.child_count} children in one query");
        self.batches += 1;
        visit [->:RelatedTo:->];
    }

    can batch with RelatedModel entry {
        # The walker fans across the FK edge; all reached children are
        # committed in one bulk_create() — only one DB round-trip.
        if not here.bulk_inserted {
            here.bulk_inserted = True;
            self.batched += 1;
        }
        visit [-->];
    }

    can report with Root entry {
        print(f"[BulkMaker] total children bulk-inserted = {self.batched} across {self.batches} batch(es)  (O(1) queries per parent)");
    }
}

# ---------------------------------------------------------------------------
# Demonstration: wire a MainModel with N RelatedModel children, show the
# O(N) vs O(1) contrast side by side.
# ---------------------------------------------------------------------------

with entry {
    N = 6;

    main = MainModel(name="primary", child_count=N);
    root ++> main;

    # Build the FK chain: main -> RelatedTo -> RelatedModel (x N).
    for i in range(N) {
        rel = RelatedModel(label=f"rel-{i}");
        main +>:RelatedTo(fk_field="related"):+> rel;
    }

    # Wire a second, smaller main so the walker has something to compare.
    small = MainModel(name="secondary", child_count=2);
    root ++> small;
    for i in range(2) {
        rel = RelatedModel(label=f"sec-rel-{i}");
        small +>:RelatedTo(fk_field="related"):+> rel;
    }

    print(f"--- Issue #297 demo: N = {N} ---");
    print("Schema: Root -> MainModel ->[:RelatedTo]-> RelatedModel");
    print("");

    # Run the naive O(N) walk first.
    naive = NaiveMaker(quantity=N);
    root spawn naive;

    print("");

    # Then the O(1) bulk walk over the same graph.
    bulk = BulkMaker(quantity=N);
    root spawn bulk;

    print("");
    print(f"Naive total saves={naive.saves}; Bulk batches={bulk.batches}, children={bulk.batched}");
    print(f"Speedup: {naive.saves} queries (old) vs {bulk.batches} queries (new) for {N} related rows.");
}

