    root ++> main;
    for i in range(N) {
        rel = RelatedModel(label=f"r-{i}");
        main +>:RelatedTo(fk_field="related"):+> rel;
    }
    naive = root spawn NaiveMaker(quantity=N);
    assert naive.saves == 2 * N, f"expected {2 * N} save() calls for N={N}, got {naive.saves}";
    assert naive.saves > N, f"naive saves {naive.saves} should scale linearly beyond O(1)";
