        rel = RelatedModel(label=f"rel-{i}");
        main +>:RelatedTo(fk_field="related"):+> rel;
    }
    naive = root spawn NaiveMaker(quantity=N);
    bulk = root spawn BulkMaker(quantity=N);
    assert bulk.batches == 1, f"expected 1 bulk batch, got {bulk.batches}";
    assert bulk.batches < naive.saves, f"bulk {bulk.batches} batches should beat naive {naive.saves} saves";
