}

test "deletes only old unreferenced versions" {
    amd = Version(digest="sha-amd", age_days=30, untagged=True, platform="amd64");
    arm = Version(digest="sha-arm", age_days=30, untagged=True, platform="arm64");
    orphan = Version(digest="sha-old", age_days=40, untagged=True, platform="amd64");
