"""Retained-mode UI tree with cascade invalidation and lifecycle walks.

Models the essential scenario from the Pixely retained-mode UI issue:
elements are nodes in a retained tree, typed edges express parent/child
ownership, and walkers perform the manual machinery the issue complains
about -- measure/arrange/paint invalidation propagation, cascade
lifecycle on subtree removal, and hit-test routing -- as native graph
walks.
"""

node UiElement {
    has name: str = "";
    has depth: int = 0;

    # Per-level dirty flags: layout (measure+arrange) and paint.
    has layout_dirty: bool = True;
    has paint_dirty: bool = True;

    # Last cached measure / arrange results, mutated in place so identity
    # is retained across frames.
    has measured_w: int = 0;
    has measured_h: int = 0;
    has bounds_x: int = 0;
    has bounds_y: int = 0;
    has bounds_w: int = 0;
    has bounds_h: int = 0;
}

# Typed edge: an element is exclusively owned by exactly one parent.
edge ParentOf {
    has child_index: int = 0;
}

# Typed edge: an element appears in some other element's overlay stack
# (multiple ownership is legal for overlays; we model one canonical
# stacking edge type so walkers can distinguish stacks from children).
edge StackedUnder {
    has z_order: int = 0;
}

walker Invalidator {
    has origin_name: str = "";
    has reached_relayout_boundary: bool = False;

    # Walk into the root of the retained tree, then descend toward the
    # root boundary that cannot change size -- the "relayout boundary".
    # Layout invalidation propagates UP toward root (we simulate this by
    # walking forward over children then up via the typed parent edge
    # would be a back-edge; instead we propagate from the leaf by
    # walking the subtree and reporting the first ancestor that is
    # size-stable).
    can start with Root entry {
        print(f"[Invalidator] begin cascade from '{self.origin_name}'");
        visit [-->];
    }

    can descend with UiElement entry {
        label = "DIRTY" if here.layout_dirty else "clean";
        print(f"  inspect {here.name} (depth={here.depth}) layout={label}");
        visit [->:ParentOf:->] else { disengage; }
    }

    can collect_boundary with UiElement entry {
        if not self.reached_relayout_boundary {
            self.reached_relayout_boundary = True;
            print(f"  -> relayout boundary at '{here.name}'");
            here.paint_dirty = True;
            visit [<--] else { disengage; }
        } else {
            here.paint_dirty = True;
            visit [<--] else { disengage; }
        }
    }
}

walker LifecycleClearer {
    has cleared: int = 0;

    # Cascade-clear root state that refers to a removed subtree: hover,
    # pressed, focus, retained rendering resources. In the model these
    # are per-node flags; the walker visits the doomed subtree and
    # resets them so reparenting a fresh element doesn't inherit stale
    # state.
    can start with Root entry {
        print("[LifecycleClearer] cascade clear subtree");
        visit [-->];
    }

    can clear with UiElement entry {
        here.layout_dirty = True;
        here.paint_dirty = True;
        here.bounds_w = 0;
        here.bounds_h = 0;
        self.cleared += 1;
        print(f"  cleared '{here.name}'");
        visit [->:ParentOf:->] else { disengage; }
    }
}

walker HitRouter {
    has target_x: int = 0;
    has target_y: int = 0;
    has hit_name: str = "";

    # Half-open bounds containment test (the issue specifically warns
    # against the inclusive Rectangle.Intersects for adjacent UI). The
    # walker descends the tree in document order, but as soon as it
    # finds a containing element with no further typed children we
    # record it as the deepest hit and disengage.
    can start with Root entry {
        print(f"[HitRouter] route point ({self.target_x},{self.target_y})");
        visit [-->];
    }

    can route with UiElement entry {
        bx = here.bounds_x;
        by = here.bounds_y;
        bw = here.bounds_w;
        bh = here.bounds_h;
        inside = (self.target_x >= bx) and (self.target_x < bx + bw)
                 and (self.target_y >= by) and (self.target_y < by + bh);
        if inside {
            self.hit_name = here.name;
            visit [->:ParentOf:->] else { disengage; }
        } else {
            disengage;
        }
    }
}

with entry {
    # Build a small retained tree:
    #   root
    #     panel (ParentOf)
    #       row
    #         label
    #         button
    #       overlay_badge (StackedUnder, z=1)
    root ++> (panel := UiElement(name="panel", depth=1))
        +>:ParentOf(child_index=0):+> (row := UiElement(name="row", depth=2))
        +>:ParentOf(child_index=1):+> (overlay_badge := UiElement(name="badge", depth=2));
    row +>:ParentOf:+> UiElement(name="label", depth=3, bounds_x=0, bounds_y=0, bounds_w=40, bounds_h=20);
    row +>:ParentOf:+> (button := UiElement(name="button", depth=3, bounds_x=0, bounds_y=20, bounds_w=40, bounds_h=20));

    panel +>:StackedUnder(z_order=1):+> overlay_badge;

    # --- Demo 1: invalidation cascade when a leaf changes ---
    button.layout_dirty = True;
    button.paint_dirty = True;
    inv = Invalidator(origin_name="button");
    root spawn inv;

    # --- Demo 2: lifecycle cascade when a subtree is removed ---
    print("");
    clearer = LifecycleClearer();
    row spawn clearer;
    print(f"  total cleared = {clearer.cleared}");

    # --- Demo 3: hit-test routing with half-open containment ---
    print("");
    router = HitRouter(target_x=15, target_y=25);
    root spawn router;
    print(f"  deepest hit = '{router.hit_name}'");
}

