"""Recursive parser walker: models the mutually recursive nested-function
abort scenario from scriptc issue #32.

The original problem was a recursive-descent parser where `primary`,
`comparison`, `and`, `or` were nested inside `parse()` and called each
other in a cycle (e.g. `primary` calling `or` for parenthesised
sub-expressions). The compile succeeded, then the binary aborted with
no diagnostic.

Here we lift that scenario into idiomatic Jac:
  * Parse-rule archetypes become `node` types.
  * The "nesting" relationship is a typed edge (`CallsInto`).
  * A `Parser` walker traverses the rule graph depth-first, carrying
    an explicit visited-set so cycles are *detected and named* instead
    of producing a silent abort.
  * A separate `Parser` pass also demonstrates dependency ordering
    (post-order rules used before the rule that calls them) and
    cascade invalidation (deleting a node purges its dependent edges).
"""

node Rule {
    has name: str = "";
    has kind: str = "";
    has depth: int = 0;
}

edge CallsInto {
    has label: str = "";
}

walker Parser {
    has seen: list[str] = [];
    has cycle_found: str = "";

    can start with Root entry {
        print("Parser entering rule graph...");
        visit [->:CallsInto:->];
    }

    can descend with Rule entry {
        # Cycle policy: explicit guard. In the original bug this guard
        # was implicit / broken and the runtime aborted with no message.
        # Here the cycle is detected and reported by name.
        for tag in self.seen {
            if tag == here.name {
                self.cycle_found = here.name;
                print(f"[CYCLE DETECTED] rule '{here.name}' re-entered");
                disengage;
            }
        }
        self.seen.append(here.name);
        print(f"  -> visiting rule '{here.name}' ({here.kind}, depth={here.depth})");
        visit [->:CallsInto:->];
    }

    can summarize with Root entry {
        if self.cycle_found != "" {
            print(f"Aborted traversal at cycle on '{self.cycle_found}' (was the silent-abort trigger)");
        } else {
            print(f"Traversal complete; visited {len(self.seen)} rules: {self.seen}");
        }
    }
}

walker DependencyOrderer {
    has order: list[str] = [];

    can start with Root entry {
        # Post-order: dependencies must be reported before the rule
        # that calls them. We collect callees first via a forward pass,
        # then emit in reverse-dependency order.
        visit [->:CallsInto:->];
    }

    can collect with Rule entry {
        order_label = f"{here.name}({here.kind})";
        self.order.append(order_label);
        visit [->:CallsInto:->];
    }

    can emit with Root entry {
        # Reverse so a callee appears before its caller in the list.
        n = len(self.order);
        reversed_order: list[str] = [];
        for i in range(n - 1, -1, -1) {
            reversed_order.append(self.order[i]);
        }
        print("Dependency order (callees before callers):");
        for item in reversed_order {
            print(f"  {item}");
        }
    }
}

walker CascadeInvalidator {
    has purged: list[str] = [];

    can start with Root entry {
        print("Cascade invalidation: deleting 'primary' rule purges dependents");
        visit [->:CallsInto:->];
    }

    can sweep with Rule entry {
        purged_label = f"{here.name}";
        self.purged.append(purged_label);
        print(f"  purging rule '{here.name}'");
        # In Jac 0.36.1, `del here` destroys the node AND auto-purges
        # its remaining typed edges -- the cascade is native.
        del here;
        visit [->:CallsInto:->];
    }

    can report with Root entry {
        print(f"Cascade purge complete; removed {len(self.purged)} rules");
    }
}

with entry {
    # Build the recursive-descent rule graph:
    #   parse -> or -> and -> comparison -> primary
    #   primary -> or  (the cycle that caused the silent abort)
    parse_r = Rule(name="parse", kind="entry", depth=0);
    or_r = Rule(name="or", kind="binary", depth=1);
    and_r = Rule(name="and", kind="binary", depth=2);
    cmp_r = Rule(name="comparison", kind="binary", depth=3);
    primary_r = Rule(name="primary", kind="atom", depth=4);

    root +>:CallsInto(label="entry"):+> parse_r;
    parse_r +>:CallsInto(label="dispatch"):+> or_r;
    or_r +>:CallsInto(label="both"):+> and_r;
    and_r +>:CallsInto(label="both"):+> cmp_r;
    cmp_r +>:CallsInto(label="atom"):+> primary_r;
    # The offending cycle: primary calls back into or for parenthesised sub-exprs.
    primary_r +>:CallsInto(label="paren-subexpr"):+> or_r;

    print("=== Cycle-detection traversal ===");
    p = Parser();
    root spawn p;

    print("\n=== Dependency ordering ===");
    d = DependencyOrderer();
    root spawn d;

    print("\n=== Cascade invalidation ===");
    c = CascadeInvalidator();
    root spawn c;
}

