"""Recursive parser nodes: model mutual recursion among nested function
declarations as walker traversal over a parenthesised expression tree.

The issue describes a recursive-descent parser where `primary()` calls
`or()` for parenthesised sub-expressions, all nested inside `parse()`.
A cycle among the nested declarations aborts at runtime. We model that
as a tree walker that walks all sub-nodes and detects a cycle."""

node Expr {
    has label: str = "";
}

node Literal(Expr) {
    has value: int = 0;
}

node BinOp(Expr) {
    has op: str = "";
    has lhs: Expr | None = None;
    has rhs: Expr | None = None;
}

edge Sub {
    has role: str = "";
}

walker CycleHunter {
    has depth_limit: int = 32;
    has seen: list[str] = [];

    can start with Root entry {
        self.seen = [];
        visit [->:Sub:->];
    }

    can descend with BinOp entry {
        self.seen.append(here.label);
        if self.seen.count(here.label) > 1 {
            print(f"CYCLE detected at {here.label} after {self.seen} steps");
            disengage;
        }
        if len(self.seen) > self.depth_limit {
            print(f"DEPTH LIMIT hit at {here.label}");
            disengage;
        }
        print(f"visit BinOp {here.label} (op={here.op}), trail={self.seen}");
        visit [here ->:Sub:->];
    }

    can collect with Literal entry {
        print(f"collect Literal {here.label}={here.value}, trail={self.seen}");
    }
}

with entry {
    # Build an expression tree:
    #   parse
    #     and
    #       or
    #         primary
    #           5
    #         5
    #       3
    root_lit = Literal(label="L_5a", value=5);
    primary = Literal(label="primary", value=42);
    sub_call = BinOp(label="or", op="||", lhs=root_lit, rhs=primary);
    eq_node = BinOp(label="and", op="&&", lhs=sub_call, rhs=Literal(label="L_3", value=3));

    # Connect: parse -> and -> or -> primary (the cycle: or's rhs is `primary`,
    # but `primary` is also reachable from parse via the same edge chain).
    # To make a true cycle we wire `or` back to `and` so the walker revisits.
    root +>:Sub(role="parse"):+> eq_node;
    eq_node +>:Sub(role="lhs"):+> sub_call;
    eq_node +>:Sub(role="rhs"):+> Literal(label="L_3", value=3);
    sub_call +>:Sub(role="lhs"):+> root_lit;
    sub_call +>:Sub(role="rhs"):+> primary;
    # The cycle: or points back up to and, mirroring the mutual recursion
    # between nested declarations `or` <-> `and` in the original parser.
    sub_call +>:Sub(role="up"):+> eq_node;

    print("=== walking expression graph (cycle mirrors nested mutual recursion) ===");
    root spawn CycleHunter(depth_limit=8);
}

