"""Tests for CycleHunter walker over BinOp/Literal sub-graph."""

import io;
import from contextlib { redirect_stdout }

test "cycle in nested sub-graph is detected" {
    # Mirror the issue: mutual recursion between nested declarations.
    # or <-> and cycle, like the parser `or()` / `and()` calling each other.
    root_lit = Literal(label="L_5a", value=5);
    primary = Literal(label="primary", value=42);
    sub_call = BinOp(label="or", op="||", lhs=root_lit, rhs=primary);
    eq_node = BinOp(label="and", op="&&", lhs=sub_call, rhs=Literal(label="L_3", value=3));

    root +>:Sub(role="parse"):+> eq_node;
    eq_node +>:Sub(role="lhs"):+> sub_call;
    sub_call +>:Sub(role="lhs"):+> root_lit;
    sub_call +>:Sub(role="rhs"):+> primary;
    # The cycle: or -> and (mutual recursion among nested declarations).
    sub_call +>:Sub(role="up"):+> eq_node;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CycleHunter(depth_limit=8);
    }
    out = buf.getvalue();
    assert "CYCLE detected" in out, f"expected cycle detection, got: {out}";
    assert "and" in out or "or" in out, f"expected cycle label in output: {out}";
}

test "acyclic expression tree traverses all leaves" {
    # No cycle: tree walks every BinOp and collects every Literal cleanly.
    l1 = Literal(label="L_1", value=1);
    l2 = Literal(label="L_2", value=2);
    l3 = Literal(label="L_3", value=3);
    or_node = BinOp(label="or", op="||", lhs=l1, rhs=l2);
    and_node = BinOp(label="and", op="&&", lhs=or_node, rhs=l3);

    root +>:Sub(role="parse"):+> and_node;
    and_node +>:Sub(role="lhs"):+> or_node;
    and_node +>:Sub(role="rhs"):+> l3;
    or_node +>:Sub(role="lhs"):+> l1;
    or_node +>:Sub(role="rhs"):+> l2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CycleHunter(depth_limit=32);
    }
    out = buf.getvalue();
    # No cycle message should be present.
    assert "CYCLE detected" not in out, f"false cycle in acyclic tree: {out}";
    assert "DEPTH LIMIT" not in out, f"unexpected depth limit: {out}";
    # All three literals should have been collected.
    assert "L_1" in out and "L_2" in out and "L_3" in out, f"missing leaves: {out}";
    # Both BinOps should have been visited.
    assert "visit BinOp or" in out, f"missing `or` visit: {out}";
    assert "visit BinOp and" in out, f"missing `and` visit: {out}";
}

test "deep nesting without cycle hits depth limit" {
    # Build a long chain of BinOps -> BinOps, no Literal leaves at the chain tips
    # except the deepest; should walk until depth_limit trips (default 32).
    head = BinOp(label="n0", op="+", lhs=None, rhs=None);
    prev = head;
    for i in range(1, 30) {
        nxt = BinOp(label=f"n{i}", op="+", lhs=None, rhs=None);
        prev +>:Sub(role="lhs"):+> nxt;
        prev = nxt;
    }
    root +>:Sub(role="parse"):+> head;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CycleHunter(depth_limit=10);
    }
    out = buf.getvalue();
    assert "DEPTH LIMIT" in out, f"expected depth limit, got: {out}";
    assert "CYCLE detected" not in out, f"false cycle in linear chain: {out}";
}

test "graph shape: Sub edges connect BinOps to their sub-expressions" {
    # Verify the typed-edge topology itself: each BinOp fans out via Sub edges.
    l_a = Literal(label="A", value=1);
    l_b = Literal(label="B", value=2);
    top = BinOp(label="top", op="+", lhs=l_a, rhs=l_b);

    root +>:Sub(role="parse"):+> top;
    top +>:Sub(role="lhs"):+> l_a;
    top +>:Sub(role="rhs"):+> l_b;

    # From root, exactly one Sub edge to `top`.
    children = [root->:Sub:->];
    assert len(children) == 1, f"expected 1 sub from root, got {len(children)}";
    assert children[0].label == "top", f"expected `top`, got {children[0].label}";

    # `top` has two Sub children: A and B.
    subs = [top ->:Sub:->];
    assert len(subs) == 2, f"expected 2 subs from top, got {len(subs)}";
    labels = sorted([s.label for s in subs]);
    assert labels == ["A", "B"], f"unexpected sub labels: {labels}";

    # End-to-end walker still works (no cycle).
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CycleHunter(depth_limit=16);
    }
    out = buf.getvalue();
    assert "CYCLE detected" not in out, f"false cycle: {out}";
    assert "collect Literal A" in out, f"missing A collection: {out}";
    assert "collect Literal B" in out, f"missing B collection: {out}";
}

