"""Glasswork Parent Task hierarchy: typed edges, leaf-first execution, ancestor rollup.

Models the core scenario from Issue #505: tasks form a parent/child hierarchy,
only Parent Tasks own cross-file children, leaves carry actionable work, and a
walker traverses the tree to gather an ancestor breadcrumb and roll up child
activity without distributed write coordination.
"""

node Task {
    has title: str = "";
    has kind: str = "task";
    has source_kind: str = "";
    has available: bool = True;
    has notes: int = 0;
    has artifacts: int = 0;
}

edge OwnsChild {
    has created_on: str = "";
}

walker HierarchyInspector {
    has path: list[str] = [];
    has rollup_notes: int = 0;
    has rollup_artifacts: int = 0;
    has leaf_count: int = 0;
    has parent_count: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can descend with Task entry {
        if here.kind == "parent" {
