    page_idx = res.pending.index("innermost_page");
    assert outer_idx < middle_idx, f"outer gate must precede middle: {res.pending}";
    assert middle_idx < inner_idx, f"middle gate must precede inner layout: {res.pending}";
    assert inner_idx < page_idx, f"descendant must run after all gated ancestors: {res.pending}";

    o_pos = out.find("gate cleared: (outer-gated)");
    m_pos = out.find("gate cleared: (middle-gated)");
