    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = public spawn LoadRunner();
    }
    out = buf.getvalue();

    assert "(public)" in res.pending, f"layout itself should be recorded: {res.pending}";
    assert "landing" in res.pending, f"landing must run: {res.pending}";
    assert "about" in res.pending, f"about must run: {res.pending}";
    assert res.aborted == False, f"non-gated layout must not abort: {res.aborted}";
    assert "gate cleared" not in out, f"non-gated layout must not print gate output: {out!r}";
    assert "redirect ->" not in out, f"non-gated layout must not print redirect: {out!r}";
    assert "resolved user" not in out, f"non-gated layout must not print user resolve: {out!r}";
    assert landing.has_run == True, "landing must run under ungated layout";
    assert about.has_run == True, "about must run under ungated layout";
