fixed.code:
"""Marlin MoE within-expert token ordering: model experts, tokens, and
the ordering-dependence complaint with a walker that traverses tokens
assigned to experts and reports whether they are equivalent-order."""

# An expert processes tokens; the order in which tokens are fed to the
# expert matters when they would have been combined (sum-reduction is
# commutative, but the Marlin kernel path applies a non-commutative
# fused operation, so different within-expert orderings yield different
# numerical results).
node Expert {
    has name: str = "";
    has expert_id: int = 0;
    # The two orderings under comparison; the bug surfaces when these
    # produce different outputs.
    has order_a: list[int] = [];
    has order_b: list[int] = [];
}

# A token carries its identifier and the expert it was dispatched to.
node Token {
    has tok_id: int = 0;
    has value: float = 0.0;
}

# The dispatcher assigns a token to an expert.
edge AssignedTo {
    has slot: int = 0;
}

# The auditor walks every expert, collects the tokens dispatched to it
# in two distinct within-expert orderings, and reports whether the
# orderings are equivalent (same token sequence) or not.
walker OrderingAuditor {
    has report: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with Expert entry {
        seq_a: list[int] = [];
        seq_b: list[int] = [];
        for tok in [->:AssignedTo:->] {
            if isinstance(tok, Token) {
                seq_a.append(tok.tok_id);
            }
        }
        # A second pass that mirrors the "equivalent reordering" the
        # issue describes: the same set of tokens, but visited in a
        # different slot order. Because traversal order is unspecified,
        # we re-emit the sequence sorted by slot to model the alternate
        # ordering the kernel might see.
        for tok in [->:AssignedTo:->] {
            if isinstance(tok, Token) {
                seq_b.append(tok.tok_id);
            }
        }
        seq_b_sorted: list[int] = [];
        for x in sorted(seq_b) {
            seq_b_sorted.append(x);
        }
        verdict: str = "";
        if seq_a == seq_b_sorted {
            verdict = "EQUIVALENT";
        } else {
            verdict = "ORDERING-DEPENDENT (bug reproduced)";
        }
        line: str = (
            f"expert {here.expert_id} ({here.name}): "
            f"orderA={seq_a} orderB={seq_b_sorted} -> {verdict}"
        );
        self.report.append(line);
        visit [-->];
    }
}

with entry {
    # Two experts. Expert 0 receives tokens in ascending id order;
    # Expert 1 receives them out of order — exactly the within-expert
    # reorder the issue complains about.
    e0 = Expert(name="ffn_0", expert_id=0);
    e1 = Expert(name="ffn_1", expert_id=1);

    root ++> e0 ++> e1;

    # Expert 0: tokens 10, 20, 30 dispatched (already sorted).
    root +>:AssignedTo(slot=0):+> Token(tok_id=10, value=1.0);
    root +>:AssignedTo(slot=1):+> Token(tok_id=20, value=2.0);
    root +>:AssignedTo(slot=2):+> Token(tok_id=30, value=3.0);

    # Expert 1: same token ids, but the slots are reversed — this is
    # the "equivalent within-expert ordering" that the Marlin kernel
    # mishandles.
    root +>:AssignedTo(slot=0):+> Token(tok_id=30, value=3.0);
    root +>:AssignedTo(slot=1):+> Token(tok_id=20, value=2.0);
    root +>:AssignedTo(slot=2):+> Token(tok_id=10, value=1.0);

    auditor = OrderingAuditor();
    root spawn auditor;

    for line in auditor.report {
        print(line);
    }
}

