"""Test annex for ADWF audit ledger dependency-ordered pre-audit read."""

import io;
import from contextlib { redirect_stdout }

test "pre-audit reader traverses must-read-before chain and reports cycle" {
    foundation = AuditEntry(
        item_id="FND",
        title="Foundation",
        year=2026,
        baseline_sha="aaaaaaaa",
        status="ACCEPTED"
    );
    roadmap = AuditEntry(
        item_id="RM",
        title="Roadmap",
        year=2026,
        baseline_sha="bbbbbbbb",
        status="COMPLETED"
    );
    aiwork = AuditEntry(
        item_id="AW",
        title="AI work",
        year=2026,
        baseline_sha="cccccccc",
        status="COMPLETED"
    );
    root ++> foundation;
    foundation +>:MustReadBefore:+> roadmap;
    roadmap +>:MustReadBefore:+> aiwork;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn PreAuditReader();
    }
    out = buf.getvalue();

    assert "[AUDIT] FND" in out, f"foundation audit not read first: {out}";
    assert "[AUDIT] RM" in out, f"roadmap audit not read in order: {out}";
    assert "[AUDIT] AW" in out, f"aiwork audit not read in order: {out}";
    assert res.cycle_detected == False, f"acyclic chain flagged as cycle: {res.cycle_detected}";
    assert res.reads == 3, f"expected 3 audit reads, got {res.reads}";
    assert len(res.visited) == 3, f"visited list wrong: {res.visited}";
}

test "cycle fail-closed on mutual must-read-before" {
    a = AuditEntry(item_id="A", title="a", year=2026, baseline_sha="x", status="PROBE");
    b = AuditEntry(item_id="B", title="b", year=2026, baseline_sha="y", status="PROBE");
    root ++> a;
    a +>:MustReadBefore:+> b;
    b +>:MustReadBefore:+> a;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn PreAuditReader();
    }
    out = buf.getvalue();

    assert res.cycle_detected == True, "cycle must be detected on mutual must-read-before";
    assert "CYCLE FAIL-CLOSED" in out, f"no CYCLE FAIL-CLOSED message: {out}";
    assert res.reads == 2, f"expected reads=2 before cycle break, got {res.reads}";
}

test "self-loop must-read-before is fail-closed" {
    rm = AuditEntry(item_id="RM", title="rm", year=2026, baseline_sha="r", status="X");
    root ++> rm;
    rm +>:MustReadBefore:+> rm;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn PreAuditReader();
    }
    out = buf.getvalue();

    assert res.cycle_detected == True, "self-loop must trip cycle detection";
    assert res.reads == 1, f"only one read should occur before self-loop blocks, got {res.reads}";
}

test "decision records and evidence are traversed" {
    fnd = AuditEntry(item_id="FND", title="f", year=2026, baseline_sha="aa", status="ACCEPTED");
    dag = Decision(item_id="DAG", title="dag", year=2026, verdict="ACCEPTED", summary="strict DAG");
    ev = Evidence(title="merge proof", year=2026, kind="merge", ref="PR #1");
    root ++> fnd;
    fnd +>:Records:+> dag;
    dag +>:Validates:+> ev;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn PreAuditReader();
    }
    out = buf.getvalue();

    assert "[AUDIT] FND" in out, f"audit entry missing: {out}";
    assert "[DECISION] DAG: ACCEPTED" in out, f"decision not surfaced: {out}";
    assert "evidence: merge PR #1" in out, f"evidence not cited: {out}";
    assert res.reads == 2, f"expected reads=2 (audit + decision), got {res.reads}";
}

test "supersession guard walks accepts and marks retired decisions" {
    defer = Decision(item_id="OLD", title="legacy", year=2026, available=False, verdict="DEFER", summary="kept old");
    accept = Decision(item_id="NEW", title="managed", year=2026, verdict="ACCEPTED", summary="new path");
    accept +>:Supersedes(reason="GOV-009 / PR #35 evidence"):+> defer;
    root ++> accept;
    root ++> defer;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SupersessionGuard();
    }
    out = buf.getvalue();

    assert "Active decision NEW supersedes:" in out, f"ACCEPTED did not announce supersession: {out}";
    assert "BLOCKED: OLD" in out, f"retired decision not blocked: {out}";
    assert "NOTED: NEW" in out, f"ACCEPTED decision not annotated: {out}";
    assert "do not re-propose without new evidence" in out, f"guidance missing: {out}";
}

