"""No-publish rehearsal authority & public-state proof model.

Models the scenario from issue #8576: a rehearsal candidate claims
``publish_authorized: false`` but may still carry effective release
mutation authority. The demo walks the reachable authority graph,
classifies each node, and emits a typed before/after receipt across
topology-derived public-state surfaces — proving the rehearsal has no
effective public mutation authority and no external side effects.
"""

# ---------------------------------------------------------------
# Topology-derived surface inventory (from release_topology.v1)
# ---------------------------------------------------------------

enum SurfaceStatus {
    UNCHANGED = "unchanged";
    MUTATED = "mutated";
    NOT_APPLICABLE = "not_applicable";
    NOT_PROVEN = "not_proven";
}

enum NodeClassification {
    READ_ONLY = "read_only";
    ARTIFACT_LOCAL_WRITE = "artifact_local_write";
    CANDIDATE_EVIDENCE_WRITE = "candidate_evidence_write";
    PUBLIC_MUTATION_DISABLED = "public_mutation_disabled";
    PUBLIC_MUTATION_UNREACHABLE = "public_mutation_unreachable";
    PUBLIC_MUTATION_AUTHORIZED = "public_mutation_authorized";
    NOT_PROVEN = "not_proven";
}

# Edge archetypes: relationships carry meaning, so they are typed.
edge Calls { has call_sha: str = ""; }
edge Inherits { has secret_name: str = ""; }
edge RunsOn { has runner: str = "ubuntu-latest"; }
edge Observes { has endpoint: str = ""; }
edge Dispatches { has target: str = ""; }

# A topology-derived external surface (registry / marketplace / tag store).
node Surface {
    has name: str = "";
    has channel_kind: str = "";
    has status: str = SurfaceStatus.UNCHANGED.value;
    has before_digest: str = "";
    has after_digest: str = "";
}

# A reachable workflow node (job / step / reusable call / dispatch).
node AuthorityNode {
    has label: str = "";
    has classification: str = NodeClassification.NOT_PROVEN.value;
    has carries_publisher_token: bool = False;
    has write_permission: bool = False;
    has publisher_environment: bool = False;
    has dry_run: bool = False;
}

# The rehearsal candidate root.
node Rehearsal {
    has candidate_sha: str = "";
    has packet_digest: str = "";
    has publish_authorized: bool = False;
    has release_cut: bool = False;
    has has_external_side_effects: bool = False;
    has authority_blocked: bool = False;
}

# ---------------------------------------------------------------
# Walkers: preflight authority + public-state proof
# ---------------------------------------------------------------

walker AuthorityPreflight {
    has report_lines: list[str] = [];
    has blocked: bool = False;

    can start with Rehearsal entry {
        self.report_lines.append(
            f"rehearsal sha={self.here.candidate_sha} digest={self.here.packet_digest}"
        );
        self.report_lines.append(
            f"publish_authorized={self.here.publish_authorized} release_cut={self.here.release_cut}"
        );
        visit [->:Calls:->];
    }

    can classify with AuthorityNode entry {
        cls = here.classification;
        verdict = "ok";
        if here.carries_publisher_token {
            verdict = "blocked:publisher_token";
            cls = NodeClassification.PUBLIC_MUTATION_AUTHORIZED.value;
        } elif here.publisher_environment {
            verdict = "blocked:publisher_environment";
            cls = NodeClassification.PUBLIC_MUTATION_AUTHORIZED.value;
        } elif here.write_permission and not here.dry_run {
            verdict = "blocked:write_permission";
            cls = NodeClassification.PUBLIC_MUTATION_AUTHORIZED.value;
        } elif here.classification == NodeClassification.NOT_PROVEN.value {
            verdict = "blocked:not_proven";
        }
        self.report_lines.append(
            f"node[{here.label}] -> {cls} ({verdict})"
        );
        if verdict != "ok" {
            self.blocked = True;
        }
        visit [->:Calls:->];
    }
}

walker PublicStateProof {
    has report_lines: list[str] = [];
    has side_effect: bool = False;

    can start with Rehearsal entry {
        if self.here.has_external_side_effects {
            self.report_lines.append("FAIL: external mutation observed");
            self.side_effect = True;
        } else {
            self.report_lines.append("OK: no external mutation observed");
        }
        visit [->:Observes:->];
    }

    can observe with Surface entry {
        before = here.before_digest;
        after = here.after_digest;
        if before == after {
            self.report_lines.append(
                f"surface[{here.name}/{here.channel_kind}] {here.status} {before}=={after}"
            );
        } else {
            self.report_lines.append(
                f"surface[{here.name}/{here.channel_kind}] MUTATED {before}->{after}"
            );
            here.status = SurfaceStatus.MUTATED.value;
            self.side_effect = True;
        }
        visit [->:Observes:->];
    }
}

# Single walker that produces the combined oracle report.
walker NoPublishOracle {
    can start with Root entry {
        visit [-->];
    }

    can audit with Rehearsal entry {
        print("=== authority preflight ===");
        pre = AuthorityPreflight();
        here spawn pre;
        if pre.blocked {
            here.authority_blocked = True;
            print("RESULT: authority preflight BLOCKED");
        } else {
            print("RESULT: authority preflight CLEAR");
        }
        print("=== public-state proof ===");
        proof = PublicStateProof();
        here spawn proof;
        if proof.side_effect {
            here.has_external_side_effects = True;
            print("RESULT: public-state proof FAILED");
        } else {
            print("RESULT: public-state proof PASSED");
        }
        print("=== final oracle ===");
        verdict = "GREEN" if not here.authority_blocked and not here.has_external_side_effects else "RED";
        print(
            f"publish_authorized={here.publish_authorized} "
            f"authority_blocked={here.authority_blocked} "
            f"external_side_effects={here.has_external_side_effects} -> {verdict}"
        );
