    # Spawn the controller on the root of the delegation tree.
    ctrl = FleetController();
    root spawn ctrl;

    print(f"--- summary ---");
    print(f"accepted={ctrl.accepted} rejected={ctrl.rejected} "
          f"frozen={ctrl.frozen} cycle={ctrl.cycle_detected}");
}

