edge Spans {
    # Spine -> Lane: the L1 collaboration spine orders consumer lanes.
    has lane_index: int = 0;
}

edge Owns {
    # Lane -> Landing: each Lane owns its Landings (the work items).
    has priority: int = 0;
}

edge Spawns {
    # Landing -> Wave: every Landing spawns one implementation wave.
    has wave_id: str = "";
}

