}

node Landing {
    # A single piece of work, owned by a Lane, that spawns a Wave.
    has issue_id: str = "";
    has status: str = "pending";  # pending | running | landed
}

node Wave {
    # The implementation wave a Landing spawns; reports back via ReportsTo.
    has wave_key: str = "";
    has outcome: str = "open";
}

# ---------- Walker: the L3 worker-orchestrated swarm -------------------------

walker SwarmCoordinator {
    # The GLM-style coordinator that walks the spine, audits each Lane,
    # follows Landings to Waves, and records a single ledger report.
    has ledger: list[str] = [];
    has visited: list[object] = [];

    can start with Root entry {
        # Boot the sweep: walk the Spine forward across its Lanes.
        print(f"[coordinator] booting sweep across '{here.title if hasattr(here, 'title') else 'root'}'");
        visit [-->] else { disengage; }
    }

    can sweep_spine with Spine entry {
        # Enter the spine: catalogue it, then continue across its Lanes.
        self.visited.append(here);
        self.ledger.append(f"spine:{here.title}");
        print(f"[coordinator] on spine '{here.title}' "
              f"({here.landed_count} landings already landed)");
        visit [->:Spans:->] else { disengage; }
    }

    can audit_lane with Lane entry {
        # Walk each Lane and follow its Landings into their Waves.
        self.visited.append(here);
        self.ledger.append(f"lane:{here.lane_name}:ring{here.ring}");
        print(f"[coordinator] auditing lane '{here.lane_name}' (ring {here.ring})");
        visit [->:Owns:->] else { disengage; }
    }

    can audit_landing with Landing entry {
        # Record the Landing, then descend into the Wave it spawned.
        self.visited.append(here);
        here.status = "running";
        self.ledger.append(f"landing:{here.issue_id}:{here.status}");
        print(f"[coordinator]   landing {here.issue_id} -> {here.status}");
        visit [->:Spawns:->] else { disengage; }
    }

    can harvest_wave with Wave entry {
        # A worker reports its wave outcome back up the spine.
        self.visited.append(here);
        here.outcome = "landed";
        self.ledger.append(f"wave:{here.wave_key}:{here.outcome}");
        print(f"[coordinator]   wave {here.wave_key} -> {here.outcome}");
        # Walk the typed report edge back up the spine. The visit filter
        # guards against the (legitimate) cycle: a wave reports to the
        # spine, which we have already visited. Without the guard this
        # sweep would re-enter the Spine forever.
        next_targets = [t for t in [->:ReportsTo:->] if not t in self.visited];
        if next_targets {
            visit next_targets;
        } else {
            disengage;
        }
    }

    can tally with Root entry {
        # Final report: print the ledger once the sweep returns to root.
        print("[coordinator] sweep complete; ledger entries:");
        for entry in self.ledger {
            print(f"  - {entry}");
        }
    }
}

# ---------- Demo wiring ------------------------------------------------------

with entry {
    # L1 spine: one BD3 collaboration spine for the sweep campaign.
    bd3 = Spine(title="BD3", landed_count=0);

    # L2 consumer lanes, parallel across rings 1 and 2.
    ring1_a = Lane(ring=1, lane_name="78-board-worker");
