    bd3 +>:Spans(lane_index=0):+> ring1_a;
    bd3 +>:Spans(lane_index=1):+> ring1_b;
    bd3 +>:Spans(lane_index=2):+> ring1_c;
    bd3 +>:Spans(lane_index=3):+> ring2_a;
    bd3 +>:Spans(lane_index=4):+> ring2_b;

    # Each lane owns one landing (the work item) -> wave pair.
    ring1_a +>:Owns(priority=1):+> (l78 := Landing(issue_id="#78"))
        +>:Spawns(wave_id="wave-78"):+> (w78 := Wave(wave_key="wave-78"));

    ring1_b +>:Owns(priority=1):+> (l85 := Landing(issue_id="#85"))
        +>:Spawns(wave_id="wave-85"):+> (w85 := Wave(wave_key="wave-85"));

    ring1_c +>:Owns(priority=1):+> (l47 := Landing(issue_id="#47"))
        +>:Spawns(wave_id="wave-47"):+> (w47 := Wave(wave_key="wave-47"));

    ring2_a +>:Owns(priority=1):+> (l88 := Landing(issue_id="#88"))
        +>:Spawns(wave_id="wave-88"):+> (w88 := Wave(wave_key="wave-88"));

    ring2_b +>:Owns(priority=1):+> (l89 := Landing(issue_id="#89"))
        +>:Spawns(wave_id="wave-89"):+> (w89 := Wave(wave_key="wave-89"));

    # Each completed Wave reports back to the spine via ReportsTo, with
    # the worker that executed it and the claim it produced.
    w78 +>:ReportsTo(worker="deepseek", claim="#78 grant law landed"):+> bd3;
    w85 +>:ReportsTo(worker="deepseek", claim="#85 hermetic capability landed"):+> bd3;
    w47 +>:ReportsTo(worker="deepseek", claim="#47 readiness landed"):+> bd3;
