"""Tests for the Frontier Sweep demo: spine traversal, QA patrol, cycle guard."""

import io;
import from contextlib { redirect_stdout }

test "frontier sweep lands L0/L1/L2 and skips open L3" {
    l0 = FrontierLevel(title="L0", ring=0, landed=True, step=0);
    l1 = FrontierLevel(title="L1", ring=0, landed=True, step=1);
    l2 = FrontierLevel(title="L2 consumers", ring=1, landed=True, step=2);
    l3 = FrontierLevel(title="L3 swarm pattern", ring=2, landed=False, step=3);
    root +>:Spine:+> l0;
    l0 +>:Spine:+> l1;
    l1 +>:Spine:+> l2;
    l2 +>:Spine:+> l3;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn FrontierSweeper();
    }
    assert res.landed_levels == 3, f"expected 3 landed levels (L0/L1/L2), got {res.landed_levels}";
    assert res.landed_levels != 4, f"L3 must NOT count as landed (open frontier), got {res.landed_levels}";
}

test "frontier sweep visits every consumer lane via Hosts edge from L2" {
    l0 = FrontierLevel(title="L0", ring=0, landed=True, step=0);
    l1 = FrontierLevel(title="L1", ring=0, landed=True, step=1);
    l2 = FrontierLevel(title="L2 consumers", ring=1, landed=True, step=2);
    l3 = FrontierLevel(title="L3", ring=2, landed=False, step=3);
    root +>:Spine:+> l0;
    l0 +>:Spine:+> l1;
    l1 +>:Spine:+> l2;
    l2 +>:Spine:+> l3;

    lane_a = ConsumerLane(title="a", issue_num=1, landed=True, commit_hash="aaaaaaa");
    lane_b = ConsumerLane(title="b", issue_num=2, landed=True, commit_hash="bbbbbbb");
    lane_c = ConsumerLane(title="c", issue_num=3, landed=True, commit_hash="ccccccc");
    lane_d = ConsumerLane(title="d", issue_num=4, landed=False, commit_hash="");
    l2 +>:Hosts:+> lane_a;
    l2 +>:Hosts:+> lane_b;
    l2 +>:Hosts:+> lane_c;
    l2 +>:Hosts:+> lane_d;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn FrontierSweeper();
    }
    assert res.lanes_seen == 4, f"expected 4 lanes seen, got {res.lanes_seen}";
    assert res.landed_lanes == 3, f"expected 3 landed lanes (d is open), got {res.landed_lanes}";
    assert lane_a in [l2 ->:Hosts:->], "lane_a must be linked via Hosts from l2";
    assert lane_b in [l2 ->:Hosts:->], "lane_b must be linked via Hosts from l2";
    assert lane_c in [l2 ->:Hosts:->], "lane_c must be linked via Hosts from l2";
    assert lane_d in [l2 ->:Hosts:->], "lane_d must be linked via Hosts from l2";
}

test "cycle guard blocks reflexive revisits along the spine" {
    # Build a spine where a reflexive Spine edge loops L1 back to itself.
    l0 = FrontierLevel(title="L0", ring=0, landed=True, step=0);
    l1 = FrontierLevel(title="L1", ring=0, landed=True, step=1);
    l2 = FrontierLevel(title="L2 consumers", ring=1, landed=True, step=2);
    l3 = FrontierLevel(title="L3", ring=2, landed=False, step=3);
    root +>:Spine:+> l0;
    l0 +>:Spine:+> l1;
    l1 +>:Spine:+> l1;  # reflexive cycle: l1 ->:Spine:-> l1
    l1 +>:Spine:+> l2;
    l2 +>:Spine:+> l3;

    lane_x = ConsumerLane(title="x", issue_num=1, landed=True, commit_hash="1234567");
    l2 +>:Hosts:+> lane_x;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn FrontierSweeper();
    }
    out = buf.getvalue();
    assert "[CYCLE-GUARD]" in out, f"cycle guard must fire on reflexive Spine edge, got: {out}";
    # The walker should not have re-counted l1 as a second landed level.
    assert res.landed_levels <= 4, f"landed_levels must not exceed 4, got {res.landed_levels}";
}

test "QA patrol counts passes and watches then settles the ledger" {
    l0 = FrontierLevel(title="L0", ring=0, landed=True, step=0);
    l1 = FrontierLevel(title="L1", ring=0, landed=True, step=1);
    l2 = FrontierLevel(title="L2 consumers", ring=1, landed=True, step=2);
    l3 = FrontierLevel(title="L3", ring=2, landed=False, step=3);  # open -> watch
    root +>:Monitors:+> l0;
    root +>:Monitors:+> l1;
    root +>:Monitors:+> l2;
    root +>:Monitors:+> l3;

    landed_lane = ConsumerLane(title="done", issue_num=78, landed=True, commit_hash="9ec8e97");
    open_lane = ConsumerLane(title="open", issue_num=89, landed=False, commit_hash="");
    root +>:Monitors:+> landed_lane;
