    root +>:Monitors:+> qa;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn QAPatrol();
    }
    # l0, l1, l2, landed_lane -> pass (4); l3, open_lane -> watch (2)
    assert res.pass_count == 4, f"expected 4 passes, got {res.pass_count}";
    assert res.watch_count == 2, f"expected 2 watches (L3 + open lane), got {res.watch_count}";
    assert qa.reviews_done == 6, f"ledger reviews_done must be 6, got {qa.reviews_done}";
    # Gate is GREEN iff watch_count == 0; we have 2 watches so gate must be WATCH.
    assert qa.gate_green == False, f"gate must be WATCH when any item is open, got {qa.gate_green}";
}

