"""Tests for jolt-aspect-packs gate audit. Verifies gate non-vacuity, phase
audit lost-update detection, and that open issues are ignored rather than
counted as gaps."""

import io;
import from contextlib { redirect_stdout }

test "fork-fixed issue with portable regression counts as coverage, not a gap" {
    rt = CorrectnessPack(pack_name="p", baseline_fork_fixed=1);
    klass = FailureClass(name="gate-non-vacuity", rank=0, leverage="high");
    iss = Issue(issue_id=47, title="poller lost update", status="fork-fixed");
    reg = PortableRegression(script="poller.jac", bad_sha="99e19320", fixed_sha="6f562e55");
    rt +>:PackTracks:+> klass;
    klass +>:Classifies:+> iss;
    iss +>:CoveredBy:+> reg;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = rt spawn GateAuditor();
    }
    out = buf.getvalue();

    assert "[OK] script=poller.jac" in out, f"missing OK marker: {out}";
    assert "no portable regression" not in out, f"unexpected violation: {out}";
    assert auditor.regressions_found == 1, f"regressions_found={auditor.regressions_found}";
    assert auditor.debt_found == 0, f"debt_found={auditor.debt_found}";
    assert auditor.gaps == 0, f"gaps={auditor.gaps}";
}

test "fork-fixed issue with extraction debt counts as debt, not a gap" {
    rt = CorrectnessPack(pack_name="p", baseline_fork_fixed=1);
    klass = FailureClass(name="gate-non-vacuity", rank=0, leverage="high");
    iss = Issue(issue_id=99, title="errno read after yield", status="fork-fixed");
    debt = ExtractionDebt(reason="not yet extracted", issue_tag="#99");
    rt +>:PackTracks:+> klass;
    klass +>:Classifies:+> iss;
    iss +>:OwedDebt:+> debt;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = rt spawn GateAuditor();
    }
    out = buf.getvalue();

    assert "[DEBT] #99" in out, f"missing DEBT marker: {out}";
    assert "no portable regression" not in out, f"unexpected violation: {out}";
    assert auditor.regressions_found == 0, f"regressions_found={auditor.regressions_found}";
    assert auditor.debt_found == 1, f"debt_found={auditor.debt_found}";
    assert auditor.gaps == 0, f"gaps={auditor.gaps}";
}

test "open status issues are not audited and do not produce gaps" {
    rt = CorrectnessPack(pack_name="p", baseline_fork_fixed=1);
    klass = FailureClass(name="gate-non-vacuity", rank=0, leverage="high");
    open_iss = Issue(issue_id=1, title="still open", status="open");
    closed_iss = Issue(issue_id=2, title="not fork-fixed", status="closed");
    rt +>:PackTracks:+> klass;
    klass +>:Classifies:+> open_iss;
    klass +>:Classifies:+> closed_iss;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = rt spawn GateAuditor();
    }
    out = buf.getvalue();

    assert "Issue #1" not in out, f"open issue was audited: {out}";
    assert "Issue #2" not in out, f"closed issue was audited: {out}";
    assert auditor.gaps == 0, f"open issues should not count as gaps, got {auditor.gaps}";
    assert auditor.regressions_found == 0, f"unexpected regressions: {auditor.regressions_found}";
    assert auditor.debt_found == 0, f"unexpected debt: {auditor.debt_found}";
}

test "phase auditor detects lost update when commit has no prior reserve" {
    commit_only = PhaseStep(phase="commit", label="never-observed");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = commit_only spawn PhaseAuditor();
    }
    out = buf.getvalue();

    assert "LOST UPDATE" in out, f"missing LOST UPDATE: {out}";
    assert auditor.lost_update is True, f"lost_update flag not set: {auditor.lost_update}";
    assert auditor.reserve_seen is False, f"reserve_seen should be False: {auditor.reserve_seen}";
}

test "phase auditor detects lost update when commit follows stale reserve" {
    reserve = PhaseStep(phase="reserve", label="fd-7");
    commit = PhaseStep(phase="commit", label="fd-7", observation_valid=False);
    reserve +>:NextPhase:+> commit;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = reserve spawn PhaseAuditor();
    }
    out = buf.getvalue();

    assert "[reserve] observed pending=fd-7" in out, f"missing reserve: {out}";
    assert "LOST UPDATE" in out, f"missing LOST UPDATE for stale obs: {out}";
    assert "stale observation 'fd-7'" in out, f"missing stale detail: {out}";
    assert auditor.lost_update is True, f"lost_update flag not set: {auditor.lost_update}";
}

test "phase auditor passes when reserve then valid commit complete normally" {
    reserve = PhaseStep(phase="reserve", label="fd-3");
    commit = PhaseStep(phase="commit", label="fd-3", observation_valid=True);
    reserve +>:NextPhase:+> commit;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = reserve spawn PhaseAuditor();
    }
    out = buf.getvalue();

    assert "LOST UPDATE" not in out, f"unexpected LOST UPDATE: {out}";
    assert "[commit] published pending=fd-3" in out, f"missing publish: {out}";
    assert auditor.lost_update is False, f"lost_update should be False: {auditor.lost_update}";
    assert auditor.reserve_seen is True, f"reserve_seen should be True: {auditor.reserve_seen}";
