"""TLAS UPDATE gate: an ordered BLAS-address sequence compared by `decide_use_update`
forces a full BUILD every frame because the per-frame draw sort is not frame-stable.

This demo models the essential scenario natively:
  - Entities are the things whose BLASes contribute to the TLAS.
  - A frame-stable *digest* of the address multiset makes the gate UPDATE-friendly
    under camera motion, instead of an ordered list that churns every frame.
"""

node Blas {
    has entity_id: int = 0;
    has device_address: int = 0;
}

node Camera {
    has frame: int = 0;
    has position: float = 0.0;
}

# Typed edge: the relationship "this entity's BLAS participates in the TLAS
# for the current frame" carries meaning (the address it contributes), so it
# is a typed edge rather than a plain connection.
edge ContributesBlas {
    has address: int = 0;
}

# Cached state: the last frame's multiset of BLAS device addresses, plus a
# frame-stable digest (sum-of-squares mod a large prime). The digest is the
# commutative signature `decide_use_update` should compare against.
node TlasCache {
    has last_addresses: list[int] = [];
    has last_digest: int = 0;
    has last_frame: int = -1;
    has build_count: int = 0;
    has update_count: int = 0;
}

walker FrameCollector {
    has frame: int = 0;
    has addresses: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    # Union trigger: the only neighbours off Root are Camera and TlasCache.
    can gather with Camera | TlasCache entry {
        visit [-->];
    }

    # Walk the typed `ContributesBlas` edges to collect every BLAS device
    # address produced by the per-frame draw sort. Order intentionally
    # follows the unstable raster/RT partition + depth-primary alpha sort.
    can collect_blases with Blas entry {
        self.addresses.append(here.device_address);
        visit [->:ContributesBlas:->];
    }
}

walker DecideUseUpdate {
    can start with Camera entry {
        cache = [here->:TlasCache:->][0];
        collector = root spawn FrameCollector(frame=here.frame);
        current_addresses = collector.addresses;

        # (a) Element-for-element ordered compare — the buggy path.
        ordered_matches = (
            len(cache.last_addresses) == len(current_addresses)
            and all(
                a == b
                for (a, b) in zip(cache.last_addresses, current_addresses)
            )
        );

        # (b) Commutative digest compare — the preferred fix.
        digest = 0;
        for addr in current_addresses {
            digest = (digest + addr * addr) % 1000003;
        }
        digest_matches = (
            len(cache.last_addresses) == len(current_addresses)
            and cache.last_digest == digest
        );

        # First frame is always a cold BUILD (cache.last_frame == -1).
        first_frame = cache.last_frame == -1;
        ordered_ok = ordered_matches and not first_frame;
        digest_ok = digest_matches and not first_frame;

        verdict = "BUILD" if first_frame else (
            "UPDATE (digest)" if digest_ok else (
                "UPDATE (ordered)" if ordered_ok else "BUILD"
            )
        );
        print(
            f"frame {here.frame}: "
            f"addresses={current_addresses} "
            f"digest={digest} "
            f"-> {verdict}"
        );

        if first_frame or not digest_ok {
            cache.build_count += 1;
        } else {
            cache.update_count += 1;
        }
        cache.last_addresses = current_addresses;
        cache.last_digest = digest;
        cache.last_frame = here.frame;

        visit [-->];
    }
}

with entry {
    camera = Camera(frame=0, position=0.0);
    cache = TlasCache();

    # Three entities whose BLASes contribute to the TLAS. Each gets its
    # own typed `ContributesBlas` edge from the camera so the per-frame
    # sort order is visible to the collector walker.
    blas_a = Blas(entity_id=1, device_address=0x1000);
    blas_b = Blas(entity_id=2, device_address=0x2000);
    blas_c = Blas(entity_id=3, device_address=0x3000);

    camera +>:ContributesBlas(address=blas_a.device_address):+> blas_a;
    camera +>:ContributesBlas(address=blas_b.device_address):+> blas_b;
    camera +>:ContributesBlas(address=blas_c.device_address):+> blas_c;

    root ++> camera ++> cache;

    # Frame 0: cold cache -> always BUILD.
    # Frame 1: same multiset -> digest matches -> UPDATE (digest).
    # Frame 2: order permuted by the unstable draw sort -> ordered path
    #   would fall back to BUILD; digest path still says UPDATE (digest).
    frames = [
        ([0x1000, 0x2000, 0x3000], 1),
        ([0x1000, 0x2000, 0x3000], 2),
        ([0x2000, 0x1000, 0x3000], 3),
    ];

    for (order, fnum) in frames {
        # Re-wire the addresses in the requested order to model the
        # per-frame draw sort's unstable output.
        for (i, addr) in enumerate(order) {
            (camera +>:ContributesBlas:+> [
                blas_a, blas_b, blas_c
            ][i]).address = addr;
        }
        # Also reflect the same addresses on the BLAS nodes so the
        # collector sees the current frame's value.
        for (i, addr) in enumerate(order) {
            [blas_a, blas_b, blas_c][i].device_address = addr;
        }
        camera.frame = fnum;
        camera spawn DecideUseUpdate();
    }

    print(
        f"final: builds={cache.build_count}, "
        f"updates={cache.update_count} "
        f"(digest path absorbed the order churn)"
    );
}

