    has token_count: int = 0;
    has max_depth: int = 0;
    has whitelist_ok: bool = True;
}

node ParseTree {
    has ast_depth: int = 0;
    has error_count: int = 0;
    has edition: str = "2024";
}

node TypedAST {
    has accepted_kinds: list[str] = [];
    has rejected_kinds: list[str] = [];
}

# --- IR + value -----------------------------------------------------------

node IRFunction {
    has name: str = "";
    has fuel_budget: int = 1000;
}

node IRValue {
    has kind: str = "int";
    has payload: int = 0;
}

# --- Edges (typed where relationship carries meaning) ---------------------

edge Produced {
    has stage: str = "";
}

edge InlinedFrom {
    has cost: int = 0;
}

