edge FeedsInto { has note: str = ""; }
edge ChildOf { }

walker PipelineRunner {
    can start with Root entry {
        visit [->:Inspects:->] else { disengage; };
    }

    can preflight with SourceUnit entry {
        print(
            f"preflight {here.path}: {here.byte_size}B, "
            f"{here.token_count} tokens"
