        visit [->:FeedsInto:->] else { disengage; };
    }

    can run_stage with AdmitStage entry {
        verdict = "accept" if here.ok else "reject";
        print(f"  [{here.order}] {here.name}: {verdict}");
        visit [->:FeedsInto:->] else { disengage; };
    }
}

walker SyntaxPreorder {
    has max_depth: int = 8;
    has seen: list[str] = [];

    can start with Root entry {
        visit [->:ChildOf:->] else { disengage; };
    }

    can walk with AstNode | SyntaxError entry {
