        for t in [-->(?:Ticket)] {
            if t.title == self.start_id {
                start = t;
                break;
            }
        }
        if start is None {
            print(f"start ticket {self.start_id} not found");
            disengage;
        }
        print(f"Auditing dependencies starting at {here} -> {start}");
        self.path = [start];
        self.seen = [start];
        self.report_lines = [];
        visit start;
    }

    can audit with Ticket entry {
        # Cycle guard: if we've already visited this ticket, record it
        if self.seen.count(here) > 1 {
            self.report_lines.append(
                f"CYCLE detected at {here.title} (path={self.path})"
            );
            return;
        }
        depth = self.path.length;
        if depth > self.max_depth {
            self.report_lines.append(
                f"DEPTH CAP hit at {here.title} (depth={depth})"
            );
            disengage;
        }

        # Print current ticket, then walk outgoing "Blocks" edges
        label = "DONE" if here.status == "done" else here.status.upper();
        self.report_lines.append(
            f"[depth={depth}] {here.title} ({here.kind}, {label}, prio={here.priority})"
        );
        nexts = [here->:Blocks:->];
        if nexts.length == 0 {
            disengage;
        }
        for nxt in nexts {
            # Append nxt to path, push nxt into seen, then visit
            self.path = self.path + [nxt];
            self.seen = self.seen + [nxt];
            visit nxt;
        }
