# Walker: cascade-invalidate downstream tickets when one is reopened
walker CascadeInvalidator {
    has blocked: list = [];

    can start with Root entry {
        # Invalidate from ticket #12
        target = None;
        for t in [-->(?:Ticket)] {
            if t.title == "#12" {
                target = t;
                break;
            }
        }
        if target is None {
            print("target #12 not found");
            disengage;
        }
        print(f"Cascade-invalidation starting at {target.title}");
        self.blocked = [];
        visit target;
    }

    can invalidate with Ticket entry {
        if here.status != "open" {
            here.status = "open";
            print(f"reopened: {here.title}");
        }
        # Traverse downstream via Blocks edges
        for nxt in [here->:Blocks:->] {
            self.blocked = self.blocked + [nxt];
            visit nxt;
        }
    }
}

