        source_uri="file:///pets.asyncapi.yaml",
        spec_version="3.1.0"
    );
    alpha = ComponentSchema(
        name="Alpha",
        authored_id="https://example.com/alpha",
        description="An object"
    );
    enabled = ComponentSchema(
        name="EnabledFlag",
        is_boolean=True,
        boolean_value=True
    );
    unused = ComponentSchema(name="UnusedWidget");
    leaky = ComponentSchema(name="LegacyShape", parser_metadata=True);

    root ++> doc;
    doc +>:Defines:+> alpha;
    doc +>:Defines:+> enabled;
    doc +>:Defines:+> unused;
    doc +>:Defines:+> leaky;

    root_children = len([root-->]);
    defined_components = len([doc ->:Defines:->]);
    assert root_children == 1, f"root direct children: {root_children}";
    assert defined_components == 4, f"defined components: {defined_components}";

    buf1 = io.StringIO();
    with redirect_stdout(buf1) {
        result1 = root spawn SchemaBundler();
        enabled spawn result1;
        unused spawn result1;
        leaky spawn result1;
        result1.report();
    }
    out1 = buf1.getvalue();

    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        result2 = root spawn SchemaBundler();
        enabled spawn result2;
        unused spawn result2;
        leaky spawn result2;
        result2.report();
    }
    out2 = buf2.getvalue();

    assert result1.collected == [
        "Alpha",
        "EnabledFlag",
        "UnusedWidget",
        "LegacyShape"
    ], f"collected: {result1.collected}";
    assert result1.stripped == 1, f"stripped: {result1.stripped}";
    assert result1.errors == [], f"errors: {result1.errors}";
    assert "  \"EnabledFlag\" (boolean)" in out1, f"missing boolean definition: {out1}";
    assert "  \"LegacyShape\" (object)" in out1, f"missing metadata-stripped definition: {out1}";
    assert out1 == out2, f"reports differ: {out1} / {out2}";
}

test "reports duplicate authored ids" {
    doc = ApiDocument(
        source_uri="file:///duplicate.yaml",
        spec_version="2.6.0"
    );
    first_schema = ComponentSchema(
        name="First",
        authored_id="https://example.com/shared"
    );
    second_schema = ComponentSchema(
        name="Second",
        authored_id="https://example.com/shared"
    );

    root ++> doc;
    doc +>:Defines:+> first_schema;
    doc +>:Defines:+> second_schema;

    result = root spawn SchemaBundler();
    second_schema spawn result;

    assert len(result.errors) == 1, f"duplicate errors: {result.errors}";
    assert result.errors[0] == (
        "duplicate $id https://example.com/shared on component Second"
    ), f"error: {result.errors[0]}";
}

test "guards self and mutual recursive references" {
    left = ComponentSchema(name="Left");
    right = ComponentSchema(name="Right");

    left +>:RefersTo(
        ref_pointer="#/components/schemas/Right"
    ):+> right;
    right +>:RefersTo(
        ref_pointer="#/components/schemas/Left"
    ):+> left;

    left_refs = len([left ->:RefersTo:->]);
    right_refs = len([right ->:RefersTo:->]);
    assert left_refs == 1, f"left refs: {left_refs}";
    assert right_refs == 1, f"right refs: {right_refs}";

    mutual = RefAuditor();
    mutual_result = left spawn mutual;
    assert mutual_result.guarded == 1, f"mutual guards: {mutual_result.guarded}";

    loop_schema = ComponentSchema(name="Loop");
    loop_schema +>:RefersTo:+> loop_schema;

    self_auditor = RefAuditor();
    self_result = loop_schema spawn self_auditor;
    assert self_result.guarded == 1, f"self guards: {self_result.guarded}";
}

