"""Tests for SkillTurnExecutor: budget enforcement, idempotency, and conflict detection."""

import io;
import from contextlib { redirect_stdout }

test "fresh call executes and records evidence" {
    chat = Question(thread_id="chat-A");
    turn = SkillTurn(max_calls=4, cpu_budget_ms=100, wall_budget_ms=200);
    root ++> chat;
    chat +>:Hosts:+> turn;

    call = SkillCall(
        tool_call_id="tc-1",
        fingerprint="fp-alpha",
        script_path="summarize.py",
        cpu_cost_ms=30,
        wall_cost_ms=40,
    );
    turn +>:ScheduledIn(seq=1):+> call;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SkillTurnExecutor();
    }
    out = buf.getvalue();

    assert "[EXECUTE] tc-1 summarize.py" in out, f"missing execute line: {out}";
    assert res.executed == 1, f"expected 1 executed, got {res.executed}";
    assert res.replayed == 0, f"expected 0 replayed, got {res.replayed}";
    assert res.conflicts == 0, f"expected 0 conflicts, got {res.conflicts}";
    assert res.budget_rejects == 0, f"expected 0 rejects, got {res.budget_rejects}";
    assert turn.calls_consumed == 1, f"expected calls_consumed=1, got {turn.calls_consumed}";
    assert turn.cpu_consumed_ms == 30, f"expected cpu=30, got {turn.cpu_consumed_ms}";
    assert turn.wall_consumed_ms == 40, f"expected wall=40, got {turn.wall_consumed_ms}";
    assert len([chat->:EvidenceSlot:->]) == 1, "expected 1 evidence slot on host";
    assert len([call->:RecordedAs:->]) == 1, "expected 1 RecordedAs edge from call";
}

test "duplicate call with same fingerprint replays without sandbox" {
    chat = Question(thread_id="chat-B");
    turn = SkillTurn(max_calls=4, cpu_budget_ms=100, wall_budget_ms=200);
    root ++> chat;
    chat +>:Hosts:+> turn;

    first = SkillCall(
        tool_call_id="tc-1",
        fingerprint="fp-alpha",
        script_path="summarize.py",
        cpu_cost_ms=30,
        wall_cost_ms=40,
    );
    dupe = SkillCall(
        tool_call_id="tc-1",
        fingerprint="fp-alpha",
        script_path="summarize.py",
        cpu_cost_ms=30,
        wall_cost_ms=40,
    );
    turn +>:ScheduledIn(seq=1):+> first;
    turn +>:ScheduledIn(seq=2):+> dupe;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SkillTurnExecutor();
    }
    out = buf.getvalue();

    assert "[EXECUTE] tc-1 summarize.py" in out, f"missing first execute: {out}";
    assert "[REPLAY] tc-1 stored outcome" in out, f"missing replay line: {out}";
    assert res.executed == 1, f"expected 1 executed, got {res.executed}";
    assert res.replayed == 1, f"expected 1 replayed, got {res.replayed}";
    assert res.conflicts == 0, f"expected 0 conflicts, got {res.conflicts}";
    assert turn.calls_consumed == 1, f"budget must not be charged on replay, got {turn.calls_consumed}";
    assert turn.cpu_consumed_ms == 30, f"cpu must not be charged on replay, got {turn.cpu_consumed_ms}";
}

test "same tool_call_id with different fingerprint is a conflict" {
    chat = Question(thread_id="chat-C");
    turn = SkillTurn(max_calls=4, cpu_budget_ms=100, wall_budget_ms=200);
    root ++> chat;
    chat +>:Hosts:+> turn;

    first = SkillCall(
        tool_call_id="tc-1",
        fingerprint="fp-alpha",
        script_path="summarize.py",
        cpu_cost_ms=20,
        wall_cost_ms=25,
    );
    clash = SkillCall(
        tool_call_id="tc-1",
        fingerprint="fp-beta",
        script_path="other.py",
        cpu_cost_ms=10,
        wall_cost_ms=10,
    );
    turn +>:ScheduledIn(seq=1):+> first;
    turn +>:ScheduledIn(seq=2):+> clash;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SkillTurnExecutor();
    }
    out = buf.getvalue();

    assert "[EXECUTE] tc-1 summarize.py" in out, f"missing first execute: {out}";
    assert "[CONFLICT] tc-1 script_call_conflict" in out, f"missing conflict line: {out}";
    assert res.executed == 1, f"expected 1 executed, got {res.executed}";
    assert res.conflicts == 1, f"expected 1 conflict, got {res.conflicts}";
    assert res.replayed == 0, f"expected 0 replayed, got {res.replayed}";
    assert turn.calls_consumed == 1, f"conflict must not consume a slot, got {turn.calls_consumed}";
}

test "cpu and wall budgets reject calls that exceed remaining capacity" {
    chat = Question(thread_id="chat-D");
    turn = SkillTurn(max_calls=4, cpu_budget_ms=100, wall_budget_ms=200);
    root ++> chat;
    chat +>:Hosts:+> turn;

    first = SkillCall(
        tool_call_id="tc-1",
        fingerprint="fp-alpha",
        script_path="a.py",
        cpu_cost_ms=30,
        wall_cost_ms=40,
    );
    too_much_cpu = SkillCall(
        tool_call_id="tc-2",
        fingerprint="fp-b",
        script_path="b.py",
        cpu_cost_ms=80,
        wall_cost_ms=40,
    );
    turn +>:ScheduledIn(seq=1):+> first;
    turn +>:ScheduledIn(seq=2):+> too_much_cpu;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SkillTurnExecutor();
    }
    out = buf.getvalue();

    assert "[EXECUTE] tc-1 a.py" in out, f"missing first execute: {out}";
    assert "[REJECT] tc-2 cpu budget exceeded" in out, f"missing cpu reject line: {out}";
    assert res.executed == 1, f"expected 1 executed, got {res.executed}";
    assert res.budget_rejects == 1, f"expected 1 reject, got {res.budget_rejects}";
    assert turn.calls_consumed == 1, f"rejected call must not advance counter, got {turn.calls_consumed}";
    assert turn.cpu_consumed_ms == 30, f"rejected call must not charge cpu, got {turn.cpu_consumed_ms}";
}

test "call cap rejects after max_calls reached" {
    chat = Question(thread_id="chat-E");
    turn = SkillTurn(max_calls=1, cpu_budget_ms=1000, wall_budget_ms=2000);
    root ++> chat;
    chat +>:Hosts:+> turn;

    first = SkillCall(
        tool_call_id="tc-1",
        fingerprint="fp-a",
        script_path="a.py",
        cpu_cost_ms=10,
        wall_cost_ms=10,
    );
    second = SkillCall(
        tool_call_id="tc-2",
        fingerprint="fp-b",
        script_path="b.py",
        cpu_cost_ms=10,
        wall_cost_ms=10,
    );
    turn +>:ScheduledIn(seq=1):+> first;
    turn +>:ScheduledIn(seq=2):+> second;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SkillTurnExecutor();
    }
    out = buf.getvalue();

    assert "[EXECUTE] tc-1 a.py" in out, f"missing first execute: {out}";
    assert "[REJECT] tc-2 call cap exceeded" in out, f"missing cap reject line: {out}";
    assert res.executed == 1, f"expected 1 executed, got {res.executed}";
    assert res.budget_rejects == 1, f"expected 1 reject, got {res.budget_rejects}";
    assert turn.calls_consumed == 1, f"calls_consumed must stay at 1, got {turn.calls_consumed}";
}

