"""Tests for the Agents Live span correlation demo."""

import io;
import from contextlib { redirect_stdout }

# ---- Reusable fixture: builds the full demo graph and returns the root. ----

def build_demo_graph() -> object {
    rt = Run(run_id="run-7f3a", title="watcher debounce retry tree");

    trigger = Span(span_id="s1", phase="trigger", status="ok", duration_ms=12, paired=True);
    rt +>:InRun:+> trigger;

