    dispatch = Span(span_id="s4", phase="dispatch", status="ok", duration_ms=5, paired=True);
    debounce +>:ChildSpan(ordinal=2):+> dispatch;

    attempt1 = Span(
        span_id="s5",
        phase="agent_call",
        status="error",
        duration_ms=3200,
        sensitivity="content",
        paired=True
    );
    dispatch +>:ChildSpan(ordinal=1):+> attempt1;

    attempt2 = Span(
