        paired=True
    );
    dispatch +>:ChildSpan(ordinal=2):+> attempt2;

    post = Span(span_id="s7", phase="post_processor", status="ok", duration_ms=40, paired=True);
    debounce +>:ChildSpan(ordinal=3):+> post;

    proc_obs = Observation(
        span_id="s8",
        phase="done",
