        paired=True
    );
    post +>:ChildSpan(ordinal=1):+> proc_obs;

    run_fail = RunOutcome(
        span_id="s9",
        phase="done",
        status="error",
        duration_ms=5100,
        sensitivity="operational",
        paired=True
    );
    rt +>:InRun:+> run_fail;

    orphan = Span(span_id="s10", phase="orphan_probe", status="running", paired=False);
    rt +>:InRun:+> orphan;

    return rt;
}


test "timeline renderer produces nested run with grandchildren and unpaired flag" {
    rt = build_demo_graph();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn TimelineRenderer();
    }
    out = buf.getvalue();

    # The Run header is printed.
    assert "=== Run run-7f3a: watcher debounce retry tree ===" in out, f"missing run header: {out!r}";

    # The renderer descends at least two levels: it should reach the
    # grandchildren below debounce (quiet_window, dispatch, post_processor).
    assert "quiet_window" in out, f"grandchild quiet_window missing: {out!r}";
    assert "dispatch" in out, f"grandchild dispatch missing: {out!r}";
    assert "post_processor" in out, f"grandchild post_processor missing: {out!r}";

    # A repeated phase (agent_call) should appear as two distinct entries,
    # proving the renderer pairs them by identity (span_id), not by phase.
    assert "s5" in out and "s6" in out, f"both agent_call attempts must be rendered: {out!r}";

    # Unpaired spans must be visually marked.
    assert "UNPAIRED" in out, f"unpaired span must be flagged: {out!r}";
    assert "open" in out, f"unpaired span should show 'open' duration: {out!r}";
}


test "export projection denies content-bearing spans and counts allow/deny" {
    rt = build_demo_graph();

    projector = ExportProjector();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt spawn projector;
    }
    out = buf.getvalue();

    # The two content-bearing agent_call attempts must be denied.
    assert "DENY" in out, f"expected a DENY line: {out!r}";
    assert "sensitivity=content" in out, f"denial must cite sensitivity: {out!r}";
    assert "s5" in out, f"span s5 must appear in scan: {out!r}";
    assert "s6" in out, f"span s6 must appear in scan: {out!r}";

    # The operational spans (trigger, debounce, quiet_window, dispatch,
    # post_processor, the Observation, the RunOutcome, and the orphan probe)
    # should be allowed. Orphan is operational too, so it must be ALLOW.
    assert "ALLOW" in out, f"expected an ALLOW line: {out!r}";

    # Run-level counters on the walker must match what's printed.
    # 5 content-bearing (s5, s6 are content; others are operational)...
    # Content-bearing: s5, s6  -> suppressed == 2
    # Operational under run: s1, s2, s3, s4, s7, s8, s9, s10 -> exported == 8
    assert projector.exported == 8, f"exported count wrong: {projector.exported}";
    assert projector.suppressed == 2, f"suppressed count wrong: {projector.suppressed}";
}


test "health streak counts only RunOutcome, not Observation rows" {
    rt = build_demo_graph();

    streak = HealthStreak();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt spawn streak;
    }
    out = buf.getvalue();

    # The Observation at s8 has phase=done, status=error — same string pair
    # as a real failed run, but Observation.is_health_signal() returns False.
    # Only the RunOutcome at s9 should count.
    assert streak.consecutive_failures == 1, (
        f"only the RunOutcome failure should count, got {streak.consecutive_failures}"
    );

    # The Observation span must have been visited (it appears in the scan
    # header for the run) but must NOT have contributed to the streak.
    assert "Export scan" not in out, f"this test belongs to HealthStreak, not ExportProjector: {out!r}";
}


test "validator flags unpaired span and no cycle in well-formed graph" {
    rt = build_demo_graph();

    validator = SpanValidator();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt spawn validator;
    }
    out = buf.getvalue();

    # Exactly one structural issue should be reported: the unpaired orphan.
    assert len(validator.issues) == 1, (
        f"expected exactly 1 issue (the unpaired span), got {validator.issues!r}"
    );
    assert "missing start/end pair" in validator.issues[0], (
        f"expected unpaired issue, got: {validator.issues[0]!r}"
    );
    assert "s10" in validator.issues[0], (
        f"the unpaired span is s10, got: {validator.issues[0]!r}"
    );

    # No cycle/duplicate-id issue should be raised for a well-formed graph.
    for issue in validator.issues {
        assert "cycle or duplicate" not in issue, (
            f"well-formed graph should not report a cycle: {issue!r}"
        );
    }
}

