    has name: str = "";
    has sample_count: int = 0;
    has samples: list[str] = [];
}

node AugPolicy {
    has name: str = "";
    has policy_dict: dict = {};
    has version: int = 1;
}

node SeedSchedule {
    has base_seed: int = 0;
    has salt: str = "sample";
}

node TransformedDataset {
    has name: str = "";
    has path: str = "";
    has sample_seeds: dict = {};
    has policy_fingerprint: str = "";
}

edge AppliedBy { has step: str = "augment"; }
edge SeededBy { has role: str = "rng"; }
edge Produces { has step: str = "prepare"; }

def derive_seed(base: int, salt: str, sample_id: str) -> int {
    # Stable, order-independent per-sample seed: hash(base, salt, sample_id).
    h = (base * 2654435761) ^ (len(salt) * 40503);
    for ch in sample_id {
        h = (h * 16777619) ^ ord(ch);
    }
    return h & 0x7FFFFFFF;
}

def fingerprint_policy(p: AugPolicy, s: SeedSchedule) -> str {
    # Cheap stable digest of policy fields + seed base; in real life this
    # would be a hash of A.to_dict(p.policy_dict) + base_seed.
    tag = f"{p.name}#{p.version}#{s.base_seed}#{s.salt}";
    return tag;
}

walker ReproducibilityAuditor {
