fixed.code:
"""Recursive planner sub-graph: trimmed DependsOn edges vs stale depends_on metadata.

Models frankenbeast issue #4349 — _buildSubGraph discards the validated
PlanGraph and returns raw nodes whose dependsOn still list cross-graph
dependencies stripped from internal edges.
"""

node Task {
    has task_id: str = "";
    has title: str = "";
    has depends_on: list[str] = [];
}

edge DependsOn { }

walker MetadataExporter {
    can start with Root entry {
        print("HITL export — task.depends_on metadata (may be stale):");
        visit [-->];
    }

    can export with Task entry {
        dep_label = ", ".join(here.depends_on) if here.depends_on else "(none)";
        print(f"  {here.task_id}: depends_on=[{dep_label}]");
        visit [-->];
    }
}

walker EdgeAuditor {
    has from_id: str = "";

    can start with Root entry {
        print("DependsOn edges in sub-graph (scheduling truth):");
        visit [-->];
    }

    can scan with Task entry {
        self.from_id = here.task_id;
        visit [->:DependsOn:->] else {
            print(f"  {here.task_id} -> (none)");
        };
        visit [-->];
    }

    can follow with Task entry {
        print(f"  {self.from_id} -> {here.task_id}");
        visit [-->];
    }
}

walker StaleProbe {
    has scope: list[str] = [];

    can start with Root entry {
        print("Inconsistency probe — metadata references absent from sub-graph:");
        visit [-->];
    }

    can probe with Task entry {
        for dep_id in here.depends_on {
            if dep_id not in self.scope {
                print(
                    f"  BUG: {here.task_id}.depends_on lists external "
                    f"'{dep_id}' (no node, no edge)"
                );
            }
        }
        visit [-->];
    }
}

walker CycleGuard {
    has visiting: list[str] = [];
    has valid: bool = True;

    can start with Root entry {
        print("Cycle check on trimmed DependsOn edges:");
        visit [-->];
    }

    can dfs with Task entry {
        if here.task_id in self.visiting {
            print(f"  CYCLE at {here.task_id}");
            self.valid = False;
            disengage;
        }
        self.visiting.append(here.task_id);
        visit [->:DependsOn:->] else {
            # dead end along dependency edge
        };
        _ = self.visiting.pop();
        if self.valid and not self.visiting {
            print("  no cycles detected");
        }
        visit [-->];
    }
}

walker MetadataTrimmer {
    has scope: list[str] = [];

    can start with Root entry {
        print("Fix — trim depends_on to internal scope (fromTasks result):");
        visit [-->];
    }

    can trim with Task entry {
        trimmed: list[str] = [];
        for dep_id in here.depends_on {
            if dep_id in self.scope {
                trimmed.append(dep_id);
            }
        }
        here.depends_on = trimmed;
        dep_label = ", ".join(here.depends_on) if here.depends_on else "(none)";
        print(f"  {here.task_id}: depends_on=[{dep_label}]");
        visit [-->];
    }
}

with entry {
    subgraph_scope = ["compile", "link", "test"];

    compile = Task(task_id="compile", title="Compile sources", depends_on=[]);
    link = Task(
        task_id="link",
        title="Link binary",
