    root ++> compile;
    root ++> link;
    root ++> test;
    link +>:DependsOn:+> compile;
    test +>:DependsOn:+> link;

    root spawn MetadataExporter();
    root spawn EdgeAuditor();
    root spawn StaleProbe(scope=subgraph_scope);
    root spawn CycleGuard();
    root spawn MetadataTrimmer(scope=subgraph_scope);
}

