"""Second Brain Control Tower: exact-head review queue modeled as typed graph.

The pain in the original Python workflow was hand-rolled recursion over
``parent_id`` style adjacencies to walk the review queue, plus
classify-collision helpers that had to be re-derived per ticket. Here
the queue, tickets, findings, and collision classes are node archetypes,
edges carry the relationships, and a walker walks the queue exactly the
way the reviewer does: pending requests first, then prior findings, then
a collision-class scan that fails closed on incomplete evidence.
"""

# --- Entity archetypes -------------------------------------------------------

node ReviewQueue {
    has name: str = "Control Tower";
    has project: str = "SECOND_BRAIN";
}

node PullRequest {
    has pr_number: int = 0;
    has exact_head: str = "";
    has base_main: str = "";
    has priority: int = 99;
    has status: str = "PENDING";  # PENDING | ACCEPTED | CHANGES_REQUIRED | BLOCKED
}

node ReviewResult {
    has schema: str = "REVIEW_RESULT/v1";
    has verdict: str = "PENDING";  # ACCEPT | CHANGES_REQUIRED | BLOCKED
    has evidence_ref: str = "";
    has reviewer: str = "GPT_INDEPENDENT_REVIEWER";
    has attestation: str = "NO_PRODUCTION_CODE_OR_REMEDIATION_ON_REVIEWED_HEAD";
}

node Finding {
    has severity: str = "P1";      # P1 | NON_BLOCKING | FUTURE
    has section: str = "MUST_FIX_BLOCKERS";
    has title: str = "";
    has status: str = "OPEN";      # OPEN | CLOSED | SUPERSEDED | NOT_APPLICABLE
}

# A collision class represents how an active-work item overlaps a head.
# Empty/default surfaces must NOT silently degrade to NO_MATERIAL_OVERLAP;
# the walker fails closed when required evidence is missing.
node CollisionClass {
    has label: str = "O0_NO_MATERIAL_OVERLAP";
    has surfaces_present: bool = False;  # false => evidence incomplete
    has overlap_code: str = "O0";
}

# --- Edge archetypes (relationships carry meaning) --------------------------

edge HoldsTicket {}      # queue -> pr ticket
edge ResolvedBy {}       # pr ticket -> review result
edge Reported {}         # review result -> finding
edge ClassifiedAs {}     # pr ticket -> collision class
edge Supersedes {}       # newer exact head -> older exact head

# --- Walker: review the queue exactly like the human reviewer ----------------

walker Reviewer {
    can start with Root entry {
        print(f"[{self}] entering Control Tower review queue");
        visit [->:HoldsTicket:->];
    }

    can audit with ReviewQueue entry {
        print(f"auditing queue: {here.name} (project={here.project})");
        visit [->:HoldsTicket:->];
    }

    # Process one PR ticket: find its result, scan findings, check collision
    # classification. Fail closed on incomplete collision evidence.
    can inspect with PullRequest entry {
        head_short = here.exact_head[:7] if here.exact_head else "<none>";
        print(
            f"PR #{here.pr_number} head={head_short} "
            f"priority={here.priority} status={here.status}"
        );

        # Walk to the result and findings in two phases.
        visit [->:ResolvedBy:->];
    }

    can read_result with ReviewResult entry {
        verdict = here.verdict;
        if verdict == "PENDING" {
            # No result yet: this is a pending ticket.
            print(f"  -> PENDING (no REVIEW_RESULT/v1 yet)");
            # Now also check the collision class for this ticket.
            # (We got here via ResolvedBy; in real graph it would also
            # attach ClassifiedAs on the ticket node itself.)
            visit [here->:Reported:->];
        } else {
            print(f"  -> verdict={verdict} evidence={here.evidence_ref}");
            visit [here->:Reported:->];
        }
    }

    # Single ability that handles findings on a result AND collision
    # classification on a ticket. Union trigger requires a shared
    # surface: both expose a `status` field we can inspect.
    can inspect with Finding | CollisionClass entry {
        if here.status == "OPEN" {
            print(f"  [OPEN] {here.severity} / {here.section}: {here.title}");
        } else if here.status == "CLOSED" {
            print(f"  [CLOSED] {here.title}");
        } else {
            # CollisionClass: if surfaces missing, fail closed.
            if not here.surfaces_present {
                print(
                    f"  [FAIL-CLOSED] collision class {here.overlap_code} "
                    f"has incomplete evidence -> must remain UNKNOWN, "
                    f"not O0/NO_MATERIAL_OVERLAP"
                );
            } else {
                print(f"  collision class {here.overlap_code} ({here.label})");
            }
        }
    }
}

# --- Walker: walk the exact-head lineage via Supersedes edges ----------------

walker LineageWalker {
    can start with Root entry {
        visit [-->];
    }

    can walk with PullRequest entry {
        head_short = here.exact_head[:7] if here.exact_head else "<none>";
        print(f"lineage node: PR #{here.pr_number} @ {head_short}");
        visit [->:Supersedes:->];
    }

    # If we land on a queue node (no more supersedes), stop cleanly.
    can stop with ReviewQueue entry {
        print(f"end of lineage at queue '{here.name}'");
    }
}

# --- Demo graph --------------------------------------------------------------

with entry {
    queue = ReviewQueue(name="Control Tower", project="SECOND_BRAIN");

    # First exact head, with CHANGES_REQUIRED + an open P1 finding.
    pr_first = PullRequest(
        pr_number=452,
        exact_head="de550c6e7bc80b6346b2bbbed13addd25ac67f0d",
        base_main="71c70f6bc3683eff4c19020a7d4cc998517c6ba1",
        priority=1,
        status="CHANGES_REQUIRED",
    );
    result_first = ReviewResult(
        verdict="CHANGES_REQUIRED",
        evidence_ref="issuecomment-5414443426",
    );
    finding_p1 = Finding(
        severity="P1",
        section="MUST_FIX_BLOCKERS",
        title=(
            "incomplete active-work collision evidence can degrade "
            "UNKNOWN to O0/no-overlap"
        ),
        status="OPEN",
    );
    # Collision class with INCOMPLETE evidence (the original bug).
    collision_incomplete = CollisionClass(
