(Project Phoenix v2). Three habitats (agrarian, industrial, research) must
compete for declining mirror capacity as six mirrors fail in steps; the
crew reallocates repeatedly. The BorSunInvestigator walker traverses the
mirror network along typed Service edges, observes each habitat's claim
strength via HasClaim edges, and reports a standing allocation.

No bespoke scenario system is built here -- just typed nodes, typed
edges, and walker traversal over the network. The "standing allocation"
the issue complains about (a hand-rolled traversal over a hand-rolled
graph) becomes a single walker that walks the network natively.
"""

# ---------- Edge archetypes ----------

# A habitat is served by a mirror along a Service relationship.
# Carries the current contracted allocation in capacity units.
edge Service {
    has allocation: int = 0;
}

# A habitat asserts a Claim against a mirror with a legitimacy tier
# (1 = sympathetic/weak, 2 = contractual, 3 = political cover).
edge Claim {
    has legitimacy: int = 1;
    has need: int = 0;
}

# Institutional voice supplies a Filed record about a mirror with a
# provenance class: 0 = contractor ops, 1 = consortium audit, 2 =
# independent observatory. The dossier tier on a record is what the
# Comms predicate `has_evidence` keys off in the real mission.
edge Filed {
    has provenance: int = 0;
    has tier: int = 1;
    has claim: str = "";
}

# ---------- Node archetypes ----------

node Mirror {
    has label: str = "";
    has capacity: int = 10;
    has degraded: bool = False;
}

node Habitat {
    has name: str = "";
    has kind: str = "";
}

# Three institutional voices. They share a base shape so a single
# union ability on the investigator can read their fields.
node Voice {
    has name: str = "";
    has bias: str = "";
}

node ContractorOps(Voice) {
    override def __init__() -> None {
        self.name = "ContractorOps";
        self.bias = "industrial-first";
    }
}

node Consortium(Voice) {
    override def __init__() -> None {
        self.name = "Consortium";
        self.bias = "balanced";
    }
}

node Observatory(Voice) {
    override def __init__() -> None {
        self.name = "Observatory";
        self.bias = "evidence-led";
    }
}

# ---------- Walker ----------

walker BorSunInvestigator {
    has seen: list = [];
    has round: int = 0;

    # The standing allocation is revisited every time capacity moves,
    # so each visit records the current mirror's contribution.
    can start with Root entry {
        self.round += 1;
        print(f"--- Allocation round {self.round} ---");
        visit [-->] else { disengage; }
    }

    # Walk the mirror network along typed edges. Forward Service edges
    # from mirrors lead to the habitats they serve; mirrors also chain
    # to other mirrors via plain connections so a single walker visit
    # covers the whole orbital network.
    can sweep with Mirror entry {
        status = "DEGRADED" if here.degraded else "STABLE";
        print(f"mirror {here.label}: capacity={here.capacity} [{status}]");
        visit [here->:Service:->];
        visit [-->];
    }

    # A single union ability handles every institutional voice: they
    # all carry `name` and `bias` via the base Voice node, so reading
    # those fields is legal on the union. Reports the dossier tier of
    # any filed record found via Filed edges.
    can hear with ContractorOps | Consortium | Observatory entry {
        print(f"voice {here.name} (bias={here.bias}) weighing in");
        visit [here->:Filed:->];
    }

    # On each habitat, sum the standing Claim edges and report which
    # legitimacy tier dominates the negotiation.
    can tally with Habitat entry {
        claims = [here->:Claim:->];
        strongest = 0;
        total_need = 0;
        for c in claims {
            total_need += c.need;
            strongest = c.legitimacy if c.legitimacy > strongest else strongest;
        }
        print(
            f"habitat {here.name} ({here.kind}): "
            f"need={total_need}, top legitimacy tier={strongest}"
        );
    }

    # Records share a base shape across the three voices, so a union
    # ability is legal here -- all that matters for the standing
    # allocation is provenance and tier.
    can read with Mirror | Habitat entry {
        records = [here->:Filed:->];
        for r in records {
            print(
                f"  filed [{r.provenance}@{r.tier}]: {r.claim}"
            );
        }
        visit [-->];
    }
}

# ---------- Demonstration graph ----------

with entry {
    # Six mirrors, each with realistic per-failure capacity steps.
    m1 = Mirror(label="M1", capacity=10);
    m2 = Mirror(label="M2", capacity=10);
    m3 = Mirror(label="M3", capacity=8, degraded=True);
    m4 = Mirror(label="M4", capacity=6, degraded=True);
    m5 = Mirror(label="M5", capacity=10);
    m6 = Mirror(label="M6", capacity=10);

    # Three habitats with deliberately misaligned need / contract /
    # legitimacy profiles, as the issue demands.
    agrarian = Habitat(name="Agrarian", kind="agrarian");
    industrial = Habitat(name="Industrial", kind="contractor");
    research = Habitat(name="Research", kind="medical");

    # Chain the orbital network from root so a single walker visit
    # sweeps all six mirrors; typed Service edges point mirrors at the
    # habitats they currently serve.
    root ++> m1 ++> m2 ++> m3 ++> m4 ++> m5 ++> m6;
    m1 +>:Service(allocation=3):+> agrarian;
    m2 +>:Service(allocation=5):+> industrial;
    m3 +>:Service(allocation=2):+> agrarian;
    m5 +>:Service(allocation=4):+> research;

    # Habitat claims: agrarian sympathetic/weak, industrial strong
    # contract, research small but political cover.
    agrarian +>:Claim(legitimacy=1, need=6):+> m1;
    agrarian +>:Claim(legitimacy=1, need=6):+> m3;
    industrial +>:Claim(legitimacy=3, need=10):+> m2;
    industrial +>:Claim(legitimacy=3, need=10):+> m4;
    research +>:Claim(legitimacy=2, need=2):+> m5;

    # Three institutional voices, each filing a record of a different
    # provenance class about mirror M4 -- the deferred-maintenance
    # finding the issue says is the campaign-marked truth.
    ops = ContractorOps();
    cons = Consortium();
    obs = Observatory();

    ops +>:Filed(provenance=0, tier=2, claim="M4 nominal, no defects"):+> m4;
    cons +>:Filed(provenance=1, tier=2, claim="M4 audit flags deferred maintenance"):+> m4;
    obs +>:Filed(provenance=2, tier=3, claim="M4 beam pattern shows focus drift"):+> m4;

    root ++> ops ++> cons ++> obs;

    # Spawn the investigator. Because the walker walks Service, Filed,
    # and plain connections, one spawn covers the mirror network, the
    # habitat claims, and the three voices' filings -- the standing
    # allocation the issue says used to be hand-rolled.
    root spawn BorSunInvestigator();
}

