"""Borrowed Sun: rolling mirror allocation, orbital failure cascade, and conflicting evidence resolution."""

node Mirror {
    has name: str = "";
    has capacity: int = 100;
    has failed: bool = False;
    has in_repair: bool = False;
}

node Habitat {
    has name: str = "";
    has need: int = 0;
    has contract_strength: int = 0;
    has legitimacy: int = 0;
    has precedent_pct: int = 0;
    has allocated: int = 0;
}

node Evidence {
    has subject: str = "";
    has tier: int = 0;
    has provenance: str = "";
    has claim: str = "";
}

edge OrbitalLink { }

edge Concerns { }

walker EvidenceInvestigator {
    has target_subject: str = "deferred_maintenance";
    has best_tier: int = 0;
    has best_provenance: str = "";
    has best_claim: str = "";

    can start with Root entry {
        print("=== Evidence trail: conflicting authentic records ===");
        visit [-->];
    }

    can weigh with Evidence entry {
        if here.subject == self.target_subject {
            print(f"  [tier {here.tier}] {here.provenance}: {here.claim}");
            sensor_wins = here.provenance == "sensor";
            incumbent_sensor = self.best_provenance == "sensor";
            if here.tier > self.best_tier {
                self.best_tier = here.tier;
                self.best_provenance = here.provenance;
                self.best_claim = here.claim;
            } elif here.tier == self.best_tier and sensor_wins and not incumbent_sensor {
                self.best_provenance = here.provenance;
                self.best_claim = here.claim;
            }
        }
        visit [-->];
    }

    can stop with Mirror | Habitat entry {
        disengage;
    }
}

walker AllocationSteward {
    has round: int = 1;
    has total_capacity: int = 0;
    has weight_sum: int = 125;
    has override_authority: bool = False;
    has capacity_reported: bool = False;

    can start with Root entry {
        if self.override_authority {
            self.weight_sum = 16;
            print(f"=== Round {self.round}: emergency override allocation ===");
        } else {
            self.weight_sum = 125;
            print(f"=== Round {self.round}: consent-path allocation ===");
        }
        visit [-->];
    }

    can passthrough with Evidence entry {
        visit [-->];
    }

    can survey with Mirror entry {
        if here.failed and not here.in_repair {
            effective = 0;
            print(f"  [FAIL] {here.name} offline (-{here.capacity} capacity)");
        } elif here.in_repair {
            effective = here.capacity // 2;
            print(f"  [REPAIR] {here.name} partial recovery ({effective})");
        } else {
            effective = here.capacity;
            print(f"  [OK] {here.name} contributing {effective}");
        }
        self.total_capacity += effective;
        visit [-->];
    }

    can allocate with Habitat entry {
        if not self.capacity_reported {
            print(f"  Network capacity: {self.total_capacity}");
            self.capacity_reported = True;
        }
        if self.override_authority {
            weight = here.contract_strength;
            mode = "OVERRIDE";
        } else {
            weight = here.need + here.precedent_pct;
            mode = "CONSENT";
        }
        share = (weight * self.total_capacity) // self.weight_sum;
        here.allocated = share;
        if share >= here.need {
            status = "met";
        } else {
            status = "SHORT";
        }
        print(
            f"  [{mode}] {here.name}: {share}/{here.need} ({status}) "
            f"— cites {here.precedent_pct}% precedent"
        );
        visit [--> ] else {
            if self.override_authority {
                print("  Compliance degrading: habitats draining buffers, blocking repair berth");
            } else {
                print("  Negotiation complete; allocations stand until next capacity shift");
            }
            disengage;
        };
    }
}

walker FailureCascade {
    can start with Root entry {
        print("=== Failure cascade along orbital mirror ring ===");
        visit [-->];
    }

    can passthrough with Evidence entry {
        visit [-->];
    }

    can passthrough_habitat with Habitat entry {
        disengage;
    }

    can propagate with Mirror entry {
        if here.failed {
            print(f"  Debris lane seeded on {here.name} track — transfer routes degraded");
        }
        visit [->:OrbitalLink:->] else { disengage; };
    }
}

