"""Tests for Borrowed Sun: evidence resolution, allocation, failure cascade."""

import io;
import from contextlib { redirect_stdout }

test "evidence_investigator_picks_sensor_at_top_tier" {
    sensor = Evidence(subject="deferred_maintenance", tier=4, provenance="sensor", claim="defocus sweep confirms glaze fatigue on Gamma");
    contractor = Evidence(subject="deferred_maintenance", tier=2, provenance="contractor", claim="mirrors fully serviced in Q3 filings");
    consortium = Evidence(subject="deferred_maintenance", tier=2, provenance="consortium", claim="audit flags skipped mirror inspections");
    m = Mirror(name="Alpha");
    root ++> contractor ++> consortium ++> sensor ++> m;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn EvidenceInvestigator();
    }
    assert res.best_tier == 4, f"expected best_tier=4 (sensor scan wins), got {res.best_tier}";
    assert res.best_provenance == "sensor", f"expected sensor provenance, got {res.best_provenance}";
    assert "glaze fatigue" in res.best_claim, f"expected sensor claim, got {res.best_claim}";
}

test "evidence_investrator_ignores_other_subjects" {
    on_topic = Evidence(subject="deferred_maintenance", tier=3, provenance="sensor", claim="scan confirms fatigue");
    off_topic = Evidence(subject="orbital_debris", tier=5, provenance="sensor", claim="debris density rising");
    m = Mirror(name="Alpha");
    root ++> off_topic ++> on_topic ++> m;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn EvidenceInvestigator();
    }
    assert res.best_tier == 3, f"investigator should only weigh deferred_maintenance evidence, got tier {res.best_tier}";
    assert "fatigue" in res.best_claim, f"should pick on-topic claim, got {res.best_claim}";
}

test "allocation_consent_path_distributes_by_need_and_precedent" {
    dom = Habitat(name="Agrarian Dome", need=40, contract_strength=2, legitimacy=9, precedent_pct=35);
    sta = Habitat(name="Industrial Station", need=50, contract_strength=9, legitimacy=4, precedent_pct=40);
    res_fac = Habitat(name="Research Facility", need=15, contract_strength=5, legitimacy=7, precedent_pct=10);
    m1 = Mirror(name="A", capacity=100);
    m2 = Mirror(name="B", capacity=100);
    m3 = Mirror(name="C", capacity=100);
    root ++> m1 ++> m2 ++> m3 ++> dom ++> sta ++> res_fac;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        st = root spawn AllocationSteward(round=1);
    }
    assert st.total_capacity == 300, f"all three mirrors contributing, expected 300 total, got {st.total_capacity}";
    # weight_sum = 125 for consent (need + precedent)
    # Agrarian: w=75 (40+35) -> (75*300)//125 = 180
    # Industrial: w=90 (50+40) -> (90*300)//125 = 216
    # Research: w=25 (15+10) -> (25*300)//125 = 60
    assert dom.allocated == 180, f"consent allocation for Agrarian Dome should be 180, got {dom.allocated}";
    assert sta.allocated == 216, f"consent allocation for Industrial Station should be 216, got {sta.allocated}";
    assert res_fac.allocated == 60, f"consent allocation for Research Facility should be 60, got {res_fac.allocated}";
}

test "allocation_override_path_uses_contract_strength_only" {
    dom = Habitat(name="Agrarian Dome", need=40, contract_strength=2, legitimacy=9, precedent_pct=35);
    sta = Habitat(name="Industrial Station", need=50, contract_strength=9, legitimacy=4, precedent_pct=40);
    res_fac = Habitat(name="Research Facility", need=15, contract_strength=5, legitimacy=7, precedent_pct=10);
    m1 = Mirror(name="A", capacity=100);
    m2 = Mirror(name="B", capacity=100);
    m3 = Mirror(name="C", capacity=100);
    root ++> m1 ++> m2 ++> m3 ++> dom ++> sta ++> res_fac;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        st = root spawn AllocationSteward(round=3, override_authority=True);
    }
    # override weight_sum = 16; weights are contract_strength only
    # Agrarian: 2 -> (2*300)//16 = 37
    # Industrial: 9 -> (9*300)//16 = 168
    # Research: 5 -> (5*300)//16 = 93
    assert dom.allocated == 37, f"override should penalise weak contract; Agrarian got {dom.allocated}";
    assert sta.allocated == 168, f"override should reward strong contract; got {sta.allocated}";
    assert res_fac.allocated == 93, f"override should reward medium contract; got {res_fac.allocated}";
    out = buf.getvalue();
    assert "OVERRIDE" in out, f"override mode label missing: {out}";
    assert "Compliance degrading" in out, f"override path must surface compliance cost: {out}";
}

test "failure_cascade_follows_orbital_links_in_order" {
    alpha = Mirror(name="Alpha", capacity=100);
    beta = Mirror(name="Beta", capacity=100, failed=True);
    gamma = Mirror(name="Gamma", capacity=100);
    dom = Habitat(name="Agrarian Dome", need=40, contract_strength=2);
    e = Evidence(subject="deferred_maintenance", tier=3, provenance="sensor", claim="x");
    root ++> e ++> alpha ++> beta ++> gamma ++> dom;
    alpha +>:OrbitalLink:+> beta;
    beta +>:OrbitalLink:+> gamma;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn FailureCascade();
    }
    out = buf.getvalue();
    assert "Debris lane seeded on Beta" in out, f"failed mirror Beta should seed debris lane: {out}";
    # cascade should reach Gamma via the OrbitalLink chain
    assert "Debris lane seeded on Gamma" not in out, f"Gamma is not failed; should not seed debris: {out}";
}

