"""Redis frontier outage modeling: transient vs. permanent failure surfacing.

Models the core scenario from nicholasbraun/job-crawler-poc issue #160:
a frontier retry guard that masks a permanent Redis outage as an infinite
silent stall. We surface the stall by giving the walker an explicit
retry-budget and a circuit-breaker ping node, instead of retrying forever.
"""

# ---------- edge archetypes ----------

# A frontier attempt on a Redis-backed frontier queue.
edge FrontierEdge { has attempt: int = 0; }

# A health probe relationship between runner and a Redis instance.
edge HealthProbe { has pings: int = 0; }

# ---------- frontier / runner / redis nodes ----------

node Redis {
    has name: str = "";
    has alive: bool = True;
    # Distinguish transient blips (BUSY / pool timeout / i/o timeout)
    # from terminal outages (OOM-killed -> container exit -> DNS NXDOMAIN).
    has mode: str = "healthy";
    # Permanent outages stay false once raised.
    has terminal: bool = False;
}

# A frontier queue holds URLs; transient errors retry, terminal errors
# must surface immediately per issue #160.
node Frontier {
    has label: str = "";
    has pending: list[str] = [];
}

# The runner orchestrates the crawl. It owns the retry budget and the
# health-probe policy. Transient blips: bounded retry. Permanent outage:
# fail loud and stop.
node Runner {
    has name: str = "";
    has max_retries: int = 3;
    has retry_count: int = 0;
    has probe_every: int = 2;
    has last_error: str = "";
    has stalled: bool = False;
    has failed: bool = False;
}

node Root {
    can collect with Runner exit {
        report = {
            "failed": here.failed,
            "stalled": here.stalled,
            "retries": here.retry_count,
            "last_error": here.last_error,
        };
    }
}

# ---------- walker: FrontierDriver ----------

walker FrontierDriver {
    has tick: int = 0;

    # Spawned at root, hop into the runner.
    can start with Root entry {
        visit [-->];
    }

    # The runner has one typed frontier edge and one typed probe edge.
    can drive with Runner entry {
        self.tick += 1;
        next_nodes = [->:FrontierEdge:->];
        probe_nodes = [->:HealthProbe:->];
        if next_nodes.length == 0 or probe_nodes.length == 0 {
            # No frontier or no Redis attached -> nothing to do, exit clean.
            report = {
                "failed": False,
                "stalled": False,
                "retries": 0,
                "last_error": "",
            };
            disengage;
        }
        frontier = next_nodes[0];
        redis = probe_nodes[0];

        # Health probe: a dead Redis flips the runner failed instantly.
        # This is the "Redis liveness signal" the issue asks about.
        if not redis.alive {
            runner = here;
            runner.last_error = f"redis {redis.name} unreachable ({redis.mode})";
            runner.failed = True;
            report = {
                "failed": runner.failed,
                "stalled": False,
                "retries": runner.retry_count,
                "last_error": runner.last_error,
            };
            disengage;
        }

        # Bound the transient retry budget. This is the fix for #160:
        # the old guard retried forever, masking a permanent outage
        # as an infinite silent stall. We fail loud after `max_retries`.
        op = frontier.pending.pop() if frontier.pending else None;
        if op is None {
            # Empty frontier with a healthy Redis: clean exit.
            report = {
                "failed": False,
                "stalled": False,
                "retries": here.retry_count,
                "last_error": "",
            };
            disengage;
        }

        # Simulate the frontier op outcome. Transient errors bump the
        # budget; terminal errors surface immediately.
        outcome = self.classify(redis.mode);
        if outcome == "ok" {
            here.retry_count = 0;
        } elif outcome == "transient" {
            here.retry_count += 1;
            here.last_error = f"transient blip on {redis.name} ({redis.mode})";
            if here.retry_count >= here.max_retries {
                # Budget exhausted on a still-transient error: the
                # original bug. Surface as stall-with-error, not silence.
                here.stalled = True;
                here.last_error = (
                    f"frontier stalled retrying {redis.name} for "
                    f"{here.retry_count} attempts ({redis.mode})"
                );
                report = {
                    "failed": False,
                    "stalled": here.stalled,
                    "retries": here.retry_count,
                    "last_error": here.last_error,
                };
                disengage;
            }
        } else {
            # Terminal error class (OOM-kill, DNS NXDOMAIN, exit 137).
            # The issue's root cause: this was being treated as transient.
            here.failed = True;
            here.last_error = (
                f"terminal outage on {redis.name} ({redis.mode})"
            );
            report = {
                "failed": here.failed,
                "stalled": False,
                "retries": here.retry_count,
                "last_error": here.last_error,
            };
            disengage;
        }
        visit [-->];
    }

    def classify(mode: str) -> str {
        # "healthy"     -> ok
        # "i_o_timeout" -> transient (retry budget applies)
        # "busy"        -> transient
        # "pool"        -> transient
        # "oom_killed"  -> terminal (container exit 137 -> DNS NXDOMAIN)
        # "dns_nx"      -> terminal
        if mode == "healthy" {
            return "ok";
        }
        if mode == "i_o_timeout" or mode == "busy" or mode == "pool" {
            return "transient";
        }
        return "terminal";
    }
}

with entry {
    # ---- healthy baseline: clean exit, no retries ----
    healthy_redis = Redis(name="r1", alive=True, mode="healthy");
    healthy_frontier = Frontier(label="main", pending=["u1", "u2", "u3"]);
    runner1 = Runner(name="run-A");
    runner1 +>:FrontierEdge:+> healthy_frontier;
    runner1 +>:HealthProbe:+> healthy_redis;
    root ++> runner1;
    r1 = root spawn FrontierDriver();
    print(f"[healthy ] {r1}");

    # ---- transient blip: bounded retry then success ----
    blip_redis = Redis(name="r2", alive=True, mode="i_o_timeout");
    blip_frontier = Frontier(label="blip", pending=["u1"]);
    runner2 = Runner(name="run-B");
    runner2 +>:FrontierEdge:+> blip_frontier;
    runner2 +>:HealthProbe:+> blip_redis;
    root ++> runner2;
    # Two ticks lets the walker recover after the budget resets on success.
    r2a = root spawn FrontierDriver();
    blip_redis.mode = "healthy";
    r2b = root spawn FrontierDriver();
