"""Frontier retry guard demo: permanent Redis outage stalls silently; terminal MISCONF fails the run."""

node CrawlerRun {
    has run_id: str = "";
    has status: str = "running";
    has progress: int = 0;
    has error_msg: str = "";
}

node RedisFrontier {
    has name: str = "";
}

node RedisBackend {
    has host: str = "";
    has error_kind: str = "healthy";
    has error_detail: str = "";
}

edge Uses { }
edge ConnectsTo { }

walker Orchestrator {
    has active_run: CrawlerRun | None = None;
    has max_retries_shown: int = 3;

    can start with Root entry {
        visit [-->];
    }

    can drive with CrawlerRun entry {
        print(f"\n=== Run {here.run_id} (status={here.status}) ===");
        self.active_run = here;
        visit [->:Uses:->];
    }

    can at_frontier with RedisFrontier entry {
        print(f"  frontier '{here.name}' - queue empty, zero progress");
        visit [->:ConnectsTo:->];
    }

    can redis_op with RedisBackend entry {
        run = self.active_run;
        kind = here.error_kind;
        detail = here.error_detail;

        if run is None {
            disengage;
        } else {
            if kind == "healthy" {
                run.progress += 1;
                print(f"  Next OK - progress={run.progress}");
            } else {
                if kind == "terminal" {
                    run.status = "failed";
                    run.error_msg = detail;
                    print(f"  TERMINAL: {detail}");
                    print("  orchestrator marks run FAILED");
                } else {
                    blip_label = "transient blip" if kind == "transient" else "permanent outage";
                    attempt = 0;
                    while attempt < self.max_retries_shown {
                        attempt += 1;
                        print(f"  retry {attempt} [{blip_label}]: {detail}");
                        print(f"    run still '{run.status}', progress={run.progress}, no error recorded");
                    }
                    print("  [demo] ADR-0024 retry guard would loop forever - silent stall");
                }
            }
            visit [-->] else { disengage; };
        }
    }
}

