"""M12 canonical integration IR + ProcessIR apply pipeline.

Models the consolidation described in issue #134 of
RenEra-ai/boomi-mcp-server: ``IntegrationSpecV1`` roots compose into a
canonical ``ProcessAuthoringUnitV1``, which is compiled into a
relocatable ``ProcessIR`` plan. The plan is fingerprinted, ID-bound at
apply time, materialized by a neutral ``ProcessComponentMaterializer``,
and finally rendered as an account-bound XML digest.

The pain the issue calls out is that legacy process semantics used to
live in ``flow_sequence`` strings and per-kind adapters -- graph-shaped
data hidden inside hand-rolled dictionaries, with recursive walks done
by hand. The idiomatic form below lifts that machinery into typed
nodes, typed edges, and walkers, while still preserving the explicit
cycle guard and depth cap that the legacy walkers carried as domain
logic.
"""

# ---------------------------------------------------------------------------
# Node archetypes: the four core entities of the canonical IR pipeline.
# ---------------------------------------------------------------------------

node IntegrationSpecV1 {
    # A single integration authoring root. ``pipeline`` is a free-form
    # string only used for diagnostics; it must NEVER become a second
    # source of runtime truth (owner rule 1).
    has name: str = "";
    has pipeline: str = "";
}

node ProcessAuthoringUnitV1 {
    # Canonical authoring envelope -- one per integration spec.
    has name: str = "";
    has fingerprint: str = "";
    has bound: bool = False;
}

node ProcessIR {
    # The single final authority on process semantics. Carries a plan
    # fingerprint and an ordered list of step names for traversal.
    has plan_id: str = "";
    has fingerprint: str = "";
    has step_count: int = 0;
}

node ComponentDigest {
    # Account-bound XML digest emitted by the materializer.
    has digest_id: str = "";
    has account: str = "";
    has xml: str = "";
    has valid: bool = True;
}

# ---------------------------------------------------------------------------
# Typed edges: each carries the relationship meaning that used to be
# implicit in field names or dictionary keys.
# ---------------------------------------------------------------------------

edge Authors { }      # IntegrationSpecV1 -> ProcessAuthoringUnitV1
edge CompilesTo {     # ProcessAuthoringUnitV1 -> ProcessIR (canonical compile)
    has relocatable: bool = True;
}
edge Applies {        # ProcessAuthoringUnitV1 -> ComponentDigest (apply-time)
    has account: str = "";
}
edge DependsOn { }    # ProcessAuthoringUnitV1 -> ProcessAuthoringUnitV1 (ordering)

# ---------------------------------------------------------------------------
# Reachability walker: replaces the hand-rolled BFS / recursion that
# used to enumerate "what does this integration touch?". Carries an
# explicit visited set -- jac 0.36.1 has no built-in dedup, so the
# cycle policy is explicit domain logic, not implicit scaffolding.
# ---------------------------------------------------------------------------

walker ReachabilityAuditor {
    has max_depth: int = 16;
    has visited: list[str] = [];
    has reach_count: int = 0;

    can start with Root entry {
        # Cap the walk; if there are no authoring edges, disengage
        # cleanly instead of hanging.
        visit [->:Authors:->] else { disengage; }
    }

    can descend with IntegrationSpecV1 entry {
        key = here.name;
        if key in self.visited {
            report here.name;
            disengage;
        }
        self.visited.append(key);
        self.reach_count += 1;
        report here.name;
        if self.reach_count >= self.max_depth {
            disengage;
        }
        visit [->:Authors:->];
    }

    can audit_unit with ProcessAuthoringUnitV1 entry {
        if not here.bound {
            report f"unbound:{here.name}";
        } else {
            report here.name;
        }
        # One unit may author multiple ProcessIRs and Applies; both
        # are walked explicitly.
        visit [->:CompilesTo:->];
        visit [->:Applies:->];
    }

    can audit_plan with ProcessIR entry {
        report here.plan_id;
        visit [->:DependsOn:->];
    }

    can audit_digest with ComponentDigest entry {
        report here.digest_id;
    }
}

# ---------------------------------------------------------------------------
# Cascade invalidation walker: when an integration spec is retired,
# every unit, plan, and digest it authors must be marked invalid.
# Replaces the hand-rolled recursive invalidator that used to walk
# children dictionaries.
# ---------------------------------------------------------------------------

walker CascadeInvalidator {
    has invalid_count: int = 0;

    can start with Root entry {
        visit [->:Authors:->] else { disengage; }
    }

    can invalidate_root with IntegrationSpecV1 entry {
        report f"INVALIDATE spec:{here.name}";
        visit [->:Authors:->];
    }

    can invalidate_unit with ProcessAuthoringUnitV1 entry {
        here.bound = False;
        self.invalid_count += 1;
        report f"INVALIDATE unit:{here.name}";
        visit [->:CompilesTo:->];
        visit [->:Applies:->];
    }

    can invalidate_plan with ProcessIR entry {
        here.fingerprint = f"STALE:{here.fingerprint}";
        self.invalid_count += 1;
        report f"INVALIDATE plan:{here.plan_id}";
        visit [->:DependsOn:->];
    }

    can invalidate_digest with ComponentDigest entry {
        here.valid = False;
        self.invalid_count += 1;
        report f"INVALIDATE digest:{here.digest_id}";
    }
}

# ---------------------------------------------------------------------------
# Demo wiring: a small integration graph that exercises cycle guard,
# dependency ordering, and the cascade invalidator.
# ---------------------------------------------------------------------------

with entry {
    # Two integration roots share a unit, and a unit has a back-edge
    # via DependsOn to exercise the cycle policy.
    spec_a = IntegrationSpecV1(name="spec-a", pipeline="legacy:flow_sequence");
    spec_b = IntegrationSpecV1(name="spec-b", pipeline="legacy:flow_sequence");

    unit_x = ProcessAuthoringUnitV1(name="unit-x", fingerprint="fp-x", bound=True);
    unit_y = ProcessAuthoringUnitV1(name="unit-y", fingerprint="fp-y", bound=True);

    plan_p = ProcessIR(plan_id="plan-p", fingerprint="fp-p", step_count=4);
    plan_q = ProcessIR(plan_id="plan-q", fingerprint="fp-q", step_count=2);

    digest_r = ComponentDigest(
        digest_id="digest-r", account="acct-1",
        xml="<process><step name='s1'/></process>", valid=True,
    );
    digest_s = ComponentDigest(
        digest_id="digest-s", account="acct-1",
        xml="<process><step name='s2'/></process>", valid=True,
    );

    # Compose the graph.
    spec_a +>:Authors:+> unit_x;
    spec_b +>:Authors:+> unit_x;
    spec_b +>:Authors:+> unit_y;
    unit_x +>:CompilesTo(relocatable=True):+> plan_p;
    unit_y +>:CompilesTo(relocatable=True):+> plan_q;
    unit_x +>:Applies(account="acct-1"):+> digest_r;
    unit_y +>:Applies(account="acct-1"):+> digest_s;
    # Back-edge that would hang a naive walker: explicit cycle policy
    # in the walker makes it safe.
    unit_x +>:DependsOn:+> unit_y;
    unit_y +>:DependsOn:+> unit_x;

    root ++> spec_a ++> spec_b;

    print("== Reachability audit (spec-a) ==");
    auditor = ReachabilityAuditor(max_depth=32);
    spec_a spawn auditor;
    print(f"reach_count={auditor.reach_count} visited={auditor.visited}");

    print("\n== Cascade invalidation (spec-b) ==");
    invalidator = CascadeInvalidator();
    spec_b spawn invalidator;
    print(f"invalid_count={invalidator.invalid_count} "
          f"unit_x.bound={unit_x.bound} "
          f"plan_p.fingerprint={plan_p.fingerprint} "
          f"digest_r.valid={digest_r.valid}");
}

