fixed.jac_tests:
"""Tests for agent parent-chain depth with cycle guards.

Verifies the behavior promised by issue #1263:
  - healthy chains return correct depth
  - cyclic chains halt (no hang, no infinite loop)
  - depth cap fires for very deep chains
  - state recovery detects cyclic subtrees
"""

import io;
import from contextlib { redirect_stdout }

test "healthy parent chain returns correct depth" {
    a = Agent(agent_id="h_alpha", title="root");
    b = Agent(agent_id="h_beta", title="mid");
    c = Agent(agent_id="h_gamma", title="leaf");
    c +>:ParentOf:+> b;
    b +>:ParentOf:+> a;

    w = AgentDepthWalker(max_depth=100);
    c spawn w;

    assert w.cycle_detected == False, f"healthy chain flagged cycle: {w.cycle_detected}";
    assert w.depth == 2, f"expected depth=2 (gamma->beta->alpha), got {w.depth}";
    assert "h_gamma" in w.visited, f"origin agent missing from visited: {w.visited}";
    assert "h_beta" in w.visited, f"mid ancestor missing: {w.visited}";
    assert "h_alpha" in w.visited, f"root ancestor missing: {w.visited}";
}

test "two-node cycle halts without hanging" {
    p = Agent(agent_id="cyc_p", title="P");
    q = Agent(agent_id="cyc_q", title="Q");
    p +>:ParentOf:+> q;
    q +>:ParentOf:+> p;

    w = AgentDepthWalker(max_depth=100);
    p spawn w;

    assert w.cycle_detected == True, "cycle must be detected on 2-node loop";
    # With cycle detection on entry, origin counts 0 parents traversed,
    # so depth stays at 0 when first hop revisits an origin... but here
    # p is origin and is visited first, then q, then loop back to p
    # which IS seen -> disengage. So depth should be 1 (the q hop).
    assert w.depth == 1, f"expected depth=1 on 2-cycle before halt, got {w.depth}";
    assert w.visited == ["cyc_p", "cyc_q"], f"unexpected visited order: {w.visited}";
}

test "self-loop cycle halts immediately" {
    s = Agent(agent_id="self_loop", title="Self");
    s +>:ParentOf:+> s;

    w = AgentDepthWalker(max_depth=100);
    s spawn w;

    assert w.cycle_detected == True, "self-loop must be detected";
    # Origin visited, then the single edge returns to origin which is seen.
    assert w.depth == 0, f"expected depth=0 on self-loop halt, got {w.depth}";
}

test "depth cap prevents runaway on long chain" {
    # Build a chain longer than max_depth.
    head = Agent(agent_id="cap_head", title="head");
    prev = head;
    cap = 10;
    for i in range(1, cap + 2) {
        n = Agent(agent_id=f"cap_n{i}", title=str(i));
        n +>:ParentOf:+> prev;
        prev = n;
    }
    tail = prev;

    w = AgentDepthWalker(max_depth=cap);
    tail spawn w;

    assert w.cycle_detected == False, "long-but-acyclic chain flagged cycle";
    # depth should never exceed the cap; on hitting cap we disengage.
    assert w.depth <= cap, f"depth {w.depth} exceeded cap {cap}";
    # Specifically: origin adds 0, each subsequent step adds 1; we
    # disengage when depth >= max_depth, so final depth == cap exactly
    # (we incremented to cap, then on the NEXT entry would disengage, but
    # we already disengaged upon reaching == cap on that step). Verify
    # the cap fired by checking we didn't traverse past it.
    assert w.depth == cap, f"expected depth to land at cap={cap}, got {w.depth}";
}

test "state recovery rejects cyclic subtrees" {
    # Healthy subtree.
    ha = Agent(agent_id="rec_h_a", title="a");
    hb = Agent(agent_id="rec_h_b", title="b");
    hc = Agent(agent_id="rec_h_c", title="c");
    hc +>:ParentOf:+> hb;
    hb +>:ParentOf:+> ha;

    # Cyclic subtree.
    ca = Agent(agent_id="rec_cyc_a", title="ca");
    cb = Agent(agent_id="rec_cyc_b", title="cb");
    cc = Agent(agent_id="rec_cyc_c", title="cc");
    ca +>:ParentOf:+> cb;
    cb +>:ParentOf:+> cc;
    cc +>:ParentOf:+> ca;

    root ++> hc;
    root ++> ca;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        rec = StateRecoverer();
        root spawn rec;
    }
    out = buf.getvalue();

    assert rec.recovered == 1, f"expected 1 healthy recovery, got {rec.recovered}";
    assert rec.cycle_count == 1, f"expected 1 cyclic rejection, got {rec.cycle_count}";
    assert "recover_agent_records" in out, f"missing recovery banner: {out}";
    assert "recover rejected cyclic chain" in out, f"missing cycle warning: {out}";
    assert "rec_cyc_a" in out, f"cyclic root not named: {out}";
}

