    creds_map +>:Contains:+> scalar_pwd_field;
    history_list +>:Contains:+> scalar_token;
    history_list +>:Contains:+> scalar_safe;
    config_map +>:Contains:+> scalar_big;

    # Attach the value tree to multiple boundaries to show the recursive
