    assert out.index("[2] Maze 1") < out.index("[3] Solution for maze 1"), f"wrong first pair order: {out}";
    assert out.index("[3] Solution for maze 1") < out.index("[4] Maze 2"), f"wrong page order: {out}";
}

test "audits an increasing difficulty ramp" {
    maze1 = MazePage(page_num=1, grid_size=8, maze_index=1);
    sol1 = SolutionPage(page_num=2, maze_index=1);
    maze2 = MazePage(page_num=3, grid_size=12, maze_index=2);
    sol2 = SolutionPage(page_num=4, maze_index=2);
    maze3 = MazePage(page_num=5, grid_size=16, maze_index=3);

    maze1 +>:NextPage:+> sol1;
    sol1 +>:NextPage:+> maze2;
    maze2 +>:NextPage:+> sol2;
    sol2 +>:NextPage:+> maze3;

