    out = buf.getvalue();
    assert v1.ok, f"v1 should accept whole-record read, got ok={v1.ok}";
    assert v1.copied_a == 5, f"v1 copied_a should be 5, got {v1.copied_a}";
    assert "PASSED" in out, f"missing PASSED marker: {out}";
}


test "tbir rejects the same let bind" {
    inner = Inner(a=5);
    root ++> inner;
    outer = Outer(r=7);
    root ++> outer;
    outer +>:NestedField:+> inner;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        tbir = TbirLetBind();
        outer spawn tbir;
    }
    out = buf.getvalue();
    assert not tbir.ok, f"tbir should reject whole-record read, got ok={tbir.ok}";
    assert tbir.reason != "", f"tbir must surface a reason, got '{tbir.reason}'";
    assert "REJECTED" in out, f"missing REJECTED marker: {out}";
}


test "parity gap exists between v1 and tbir" {
    inner = Inner(a=5);
    root ++> inner;
    outer = Outer(r=7);
    root ++> outer;
    outer +>:NestedField:+> inner;

    v1 = V1LetBind();
    outer spawn v1;
    tbir = TbirLetBind();
    outer spawn tbir;

    gap = v1.ok and not tbir.ok;
    assert gap, f"parity gap expected (v1.ok={v1.ok}, tbir.ok={tbir.ok})";
    assert v1.copied_a == tbir.reason == "" or v1.copied_a == 5, "v1 copied value sanity";
}


test "field chain resolves depth and leaf" {
    inner = Inner(a=42);
    root ++> inner;
    outer = Outer(r=1);
    root ++> outer;
    outer +>:NestedField:+> inner;

    chain = FieldChainResolve();
    outer spawn chain;

    assert chain.ok, f"chain should resolve, got ok={chain.ok}";
    assert chain.depth == 2, f"depth should be 2, got {chain.depth}";
    assert chain.leaf_a == 42, f"leaf_a should be 42, got {chain.leaf_a}";
}


test "field-copy path works: read then write" {
    src = Inner(a=9);
    root ++> src;
    o = Outer(r=1);
    root ++> o;
    o +>:NestedField:+> src;

    dst = Inner(a=0);
    root ++> dst;
    p = Outer(r=0);
    root ++> p;
    p +>:NestedField:+> dst;

    reader = FieldCopyRead();
    o spawn reader;
    assert reader.captured_a == 9, f"reader captured_a should be 9, got {reader.captured_a}";

    writer = FieldCopyWrite(source_a=reader.captured_a);
    p spawn writer;
    assert writer.done, f"writer should be done, got {writer.done}";
    assert dst.a == 9, f"dst.a should be 9 after copy, got {dst.a}";
}


test "dependency ordering: Inner emit before Outer" {
    inner_def = RecordDef(name="Inner");
    outer_def = RecordDef(name="Outer");
    root ++> inner_def;
    root ++> outer_def;
    outer_def +>:DependsOn:+> inner_def;

    emit = EmitOrder();
    outer_def spawn emit;

    assert emit.ordered, f"topological emit order should be ordered, got {emit.ordered}";
    # Confirm the DependsOn edge exists and points Inner
    targets = [outer_def ->:DependsOn:->];
    assert len(targets) == 1, f"Outer should have one DependsOn edge, got {len(targets)}";
    assert targets[0].name == "Inner", f"Outer should depend on Inner, got {targets[0].name}";
}

