"""Per-case receipt model: case identity, plan binding, observable execution result, and pass invariant enforcement.

Models the core of issue #9898: a recorder accumulates load-bearing check
evidence and typed harness/protocol failures, then a finalizer derives the
result state from the evidence rather than letting callers assert an
arbitrary outcome. A finish_pass attempt after a recorded failure cannot
produce a valid pass receipt; that is enforced by the pass invariant.

Entities:
  Case       - the test case under observation (stable case_id, target).
  Plan       - the run plan this case is bound to (plan_id, tier, profile).
  Check      - a load-bearing assertion recorded against the case.
  Failure    - a typed observable harness/protocol failure (closed vocab).
  Receipt    - the assembled per-case receipt (result, evidence, identity).

Relationships (typed edges, declared below):
  bound_to_plan  - Case -> Plan
  recorded_check - Case -> Check
  typed_failure  - Case -> Failure
  finalized_into - Case -> Receipt

Traversal: an Auditor walker visits a case's recorded evidence and decides
whether the receipt may be marked as pass. The pass invariant is enforced
in the walker's logic: any recorded failed check or terminal typed failure
causes the receipt to be marked fail, regardless of any caller intent to
finish_pass. Exact replay fields are bound from case + plan identity.
"""

node Case {
    has case_id: str = "";
    has target_kind: str = "";
    has target_name: str = "";
    has full_test_name: str = "";
    has workflow_display: str = "";
    has repo_sha: str = "";
    has run_id: str = "";
    has attempt: int = 0;
}

node Plan {
    has plan_id: str = "";
    has plan_digest: str = "";
    has tier: str = "";
    has feature_profile: str = "";
    has operational_role: str = "";
}

node Check {
    has label: str = "";
    has passed: bool = False;
    has detail: str = "";
}

node Failure {
    has kind: str = "";
    has detail: str = "";
}

node Receipt {
    has result: str = "pending";
    has passed_count: int = 0;
    has failed_count: int = 0;
    has failure_kinds: str = "";
    has case_id: str = "";
    has plan_id: str = "";
    has replay_cargo: str = "";
    has replay_just: str = "";
    has schema_version: str = "ux_case_receipt.v2";
}

edge bound_to_plan {}
edge recorded_check {}
edge typed_failure {}
edge finalized_into {}

walker Auditor {
    can start with Case entry {
        print(f"Auditing case {here.case_id} (target={here.target_name})");
        visit [->:recorded_check:->];
        visit [->:typed_failure:->];
    }

    can tally_check with Check entry {
        if here.passed {
            self.passed_so_far += 1;
        } else {
            self.failed_so_far += 1;
        }
    }

    can note_failure with Failure entry {
        if self.failure_kinds == "" {
            self.failure_kinds = here.kind;
        } else {
            self.failure_kinds = f"{self.failure_kinds};{here.kind}";
        }
    }

    can finalize with Receipt entry {
        # Pass invariant: all load-bearing checks must pass AND no typed
        # failure recorded AND the caller did not already record a fail.
        result = "pass" if (self.failed_so_far == 0 and self.failure_kinds == "") else "fail";
        here.result = result;
        here.passed_count = self.passed_so_far;
        here.failed_count = self.failed_so_far;
        here.failure_kinds = self.failure_kinds;
        here.case_id = self.case_id;
        here.plan_id = self.plan_id;
        here.replay_cargo = (
            f"cargo test -p {self.target_kind} -- {self.full_test_name} "
