        print(
            f"Receipt[{here.schema_version}] case={here.case_id} "
            f"plan={here.plan_id} result={here.result} "
            f"passed={here.passed_count} failed={here.failed_count} "
            f"failures=[{here.failure_kinds}]"
        );
        print(f"  exact replay: {here.replay_cargo}");
        print(f"  just replay : {here.replay_just}");
        if here.result == "fail" and self.caller_wants_pass {
            print(
                f"  INVARIANT: caller requested finish_pass but recorded "
                f"evidence forces fail (failed_checks={here.failed_count}, "
                f"typed_failures=[{here.failure_kinds}])"
            );
        }
    }

    has passed_so_far: int = 0;
    has failed_so_far: int = 0;
    has failure_kinds: str = "";
    has case_id: str = "";
    has plan_id: str = "";
    has full_test_name: str = "";
    has target_kind: str = "";
    has caller_wants_pass: bool = False;
