"""Regression tests for ux_case_receipt.v2 pass/fail derivation."""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
test "finish_pass_blocked_when_load_bearing_check_failed" {
    base = UxCase(
        case_id="case-002",
        target_name="perl_lsp_ux",
        full_test_name="ux::completion_exact"
    );
    base +>:RecordedCheck(order=1):+> LoadBearingCheck(name="rpc_ready", passed=True);
    bad = LoadBearingCheck(name="completion_items", passed=False);
    base +>:RecordedCheck(order=2):+> bad;
    receipt = UxCaseReceipt(case_id="case-002", caller_requested_pass=True);
    base +>:ReceiptFor:+> receipt;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = base spawn ReceiptFinalizer();
    }
    out = buf.getvalue();

    # Walker must NOT have produced a valid pass, despite caller_requested_pass=True.
    assert not receipt.valid, f"receipt wrongly validated: {out}";
    assert receipt.result == "assertion_mismatch", f"got result={receipt.result}, out={out}";
    assert receipt.failure_kind == "pass_invariant_violation", f"got failure_kind={receipt.failure_kind}";
    assert receipt.finalized, "receipt must be finalized";
    assert receipt.assertions_failed == 1, f"got failed_count={receipt.assertions_failed}";
    assert res.failed_count == 1, f"walker failed_count={res.failed_count}";
    assert "[REJECT]" in out, f"expected rejection marker: {out}";
    assert "pass_invariant" in out or "finish_pass" in out or "blocked" in out, f"missing block msg: {out}";
}

# ---------------------------------------------------------------------------
test "real_failed_check_produces_assertion_mismatch" {
    base = UxCase(
        case_id="case-real-fail",
        target_name="perl_lsp_ux",
        full_test_name="ux::diagnostics_exact"
    );
    base +>:RecordedCheck(order=1):+> LoadBearingCheck(name="rpc_ready", passed=True);
    base +>:RecordedCheck(order=2):+>
        LoadBearingCheck(name="diagnostic_line", passed=False);
    receipt = UxCaseReceipt(case_id="case-real-fail");
    base +>:ReceiptFor:+> receipt;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = base spawn ReceiptFinalizer();
    }
    out = buf.getvalue();

    assert not receipt.valid, f"receipt wrongly validated: {out}";
    assert receipt.result == "assertion_mismatch", f"got result={receipt.result}";
    assert receipt.failure_kind == "assertion_mismatch", f"got failure_kind={receipt.failure_kind}";
    assert receipt.finalized, "receipt must be finalized";
    assert receipt.assertions_failed == 1, f"got failed_count={receipt.assertions_failed}";
    assert res.failed_count == 1, f"walker failed_count={res.failed_count}";
    assert "[FAIL]" in out, f"expected FAIL marker: {out}";
    # Ensure rejection of pass invariant is distinct from natural fail path.
    assert "[REJECT]" not in out, f"natural fail should not use REJECT marker: {out}";
}

# ---------------------------------------------------------------------------
test "non_load_bearing_failures_ignored" {
    base = UxCase(
        case_id="case-soft",
        target_name="perl_lsp_ux",
        full_test_name="ux::hover_exact"
    );
    base +>:RecordedCheck(order=1):+> LoadBearingCheck(name="rpc_ready", passed=True);
    base +>:RecordedCheck(order=2):+> LoadBearingCheck(name="hover_text", passed=True);
    # Soft check: not load-bearing and failing — must NOT poison the receipt.
    base +>:RecordedCheck(order=3):+>
        LoadBearingCheck(name="soft_trace", passed=False, load_bearing=False);
    receipt = UxCaseReceipt(case_id="case-soft");
    base +>:ReceiptFor:+> receipt;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = base spawn ReceiptFinalizer();
    }
    out = buf.getvalue();

    assert receipt.valid, f"receipt must validate when only soft checks fail: {out}";
    assert receipt.result == "assertions_passed", f"got result={receipt.result}";
    assert receipt.failure_kind == "", f"got failure_kind={receipt.failure_kind}";
    assert receipt.finalized, "receipt must be finalized";
    assert receipt.assertions_failed == 0, f"got failed_count={receipt.assertions_failed}";
    assert res.failed_count == 0, f"walker failed_count={res.failed_count}";
    assert res.check_count == 3, f"walker should have visited all 3 checks, got {res.check_count}";
    assert "[PASS]" in out, f"expected PASS marker: {out}";
