    can start with Root entry {
        print("=== Projection-aware cache invalidation sweep ===");
        visit [-->];
    }

    # Single union ability handles all entity types uniformly.
    can audit with Claim | Evidence | Round | Dispute | Reputation | Wallet entry {
        key = f"{type(here).__name__}:{here.__dict__}";
        if key in self.cycle_guard {
            disengage;
        }
        self.cycle_guard[key] = True;
        self.seen.append(key);

        # Walk typed outgoing edges; this is the projection-aware traversal
        # that replaces the cache-wide churn from the old code.
        next_edges = [];
        if isinstance(here, Claim) {
            next_edges = [->:BelongsTo:->, ->:Supports:->, ->:Disputes:->];
        } elif isinstance(here, Evidence) {
            next_edges = [->:BelongsTo:->, ->:Supports:->];
        } elif isinstance(here, Round) {
            next_edges = [->:Settles:->, ->:BelongsTo:->];
        } elif isinstance(here, Dispute) {
            next_edges = [->:BelongsTo:->, ->:RewardsTo:->];
        } elif isinstance(here, Reputation) {
            next_edges = [->:RewardsTo:->];
        } elif isinstance(here, Wallet) {
            next_edges = [->:Owns:->];
        }

        # Cache-entry edges still need visiting from any node.
        visit next_edges;
        visit [->:Caches:->];
    }

    can record with CacheEntry entry {
        if here.invalidated {
            return;
        }
        if here.state == FinalityState.REORGED {
            here.invalidated = True;
            self.invalidations.append(here.canonical_key);
            print(f"  REORGED -> evict {here.canonical_key}");
            return;
        }
        if here.state == FinalityState.OBSERVED {
            here.invalidated = True;
            self.invalidations.append(here.canonical_key);
            print(f"  OBSERVED -> evict {here.canonical_key} (stale-projection)");
            return;
        }
        if here.state == FinalityState.SAFE {
            label = "keep-warm";
            print(f"  SAFE -> {label} {here.canonical_key}");
            return;
        }
        if here.state == FinalityState.FINALIZED {
            label = "promote";
            print(f"  FINALIZED -> {label} {here.canonical_key}");
            return;
        }
    }
}

walker CascadeInvalidator {
    has visited: dict[str, bool] = {};

    can start with Root entry {
        print("=== Cascade invalidation from confirmed projection ===");
        visit [-->];
    }

    can sweep with CacheEntry entry {
        key = here.canonical_key;
        if key in self.visited {
            return;
        }
        self.visited[key] = True;
        if here.state == FinalityState.REORGED {
            here.invalidated = True;
            print(f"  cascade-evict {key} (REORGED)");
            visit [->:Caches:->];
        }
    }
}

with entry {
    # Build a small graph: a Claim with Evidence, in a Round, with a Dispute,
    # and a Reputation that rewards the disputer via a Wallet.
    c = Claim(claim_id="C-001", bond_amount=1000, state=FinalityState.SAFE);
    e = Evidence(evidence_id="E-001", content_hash="0xabc", state=FinalityState.FINALIZED);
    r = Round(round_id="R-001", round_number=7, state=FinalityState.SAFE);
    d = Dispute(dispute_id="D-001", verdict="upheld", state=FinalityState.OBSERVED);
    rep = Reputation(voter="0xAlice", score=42, state=FinalityState.SAFE);
    w = Wallet(address="0xAlice", chain_id=10, state=FinalityState.SAFE);

    # Typed connections carry finality/projection meaning.
    c +>:BelongsTo(since_block=100):+> r;
    e +>:Supports(weight=5):+> c;
    d +>:BelongsTo(since_block=105):+> r;
    d +>:Disputes:+> c;
    rep +>:RewardsTo(amount=50):+> d;
    w +>:Owns:+> rep;
    root ++> c ++> e ++> r ++> d ++> rep ++> w;

    # Cache entries live as their own nodes, reached via Caches edges.
    cache_claim = CacheEntry(canonical_key="claims:C-001", entity_ref="C-001",
                             state=FinalityState.OBSERVED);
    cache_evidence = CacheEntry(canonical_key="evidence:E-001", entity_ref="E-001",
                                state=FinalityState.FINALIZED);
    cache_dispute = CacheEntry(canonical_key="disputes:D-001", entity_ref="D-001",
                               state=FinalityState.REORGED);
    cache_round = CacheEntry(canonical_key="rounds:R-001", entity_ref="R-001",
                             state=FinalityState.SAFE);
    c +>:Caches(query_key="claims:C-001"):+> cache_claim;
    e +>:Caches(query_key="evidence:E-001"):+> cache_evidence;
    d +>:Caches(query_key="disputes:D-001"):+> cache_dispute;
    r +>:Caches(query_key="rounds:R-001"):+> cache_round;

    # Spawn the projection-aware auditor from root.
    root spawn InvalidationAuditor();
    print(f"Total projection-aware invalidations: {len(InvalidationAuditor().invalidations)}");

    # Spawn cascade invalidator over cache entries only.
    root spawn CascadeInvalidator();
}

