node InvalidationTrigger {
    has kind: str = "";
    has downgrade_to: str = "reorged";
}

node ConfirmedTx(InvalidationTrigger) {
    has tx_hash: str = "";
}

node ProjectionEvent(InvalidationTrigger) {
    has stream: str = "";
    has affected_domain: str = "";
}

node QueryEntry {
    has domain: str = "";
    has cache_key: str = "";
    has freshness: str = "finalized";
}

edge Invalidates { }

edge DependsOn { }

walker CacheInvalidator {
    has seen_keys: list[str] = [];
    has downgrade_to: str = "reorged";
    has invalidated_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can on_trigger with ConfirmedTx | ProjectionEvent entry {
        self.downgrade_to = here.downgrade_to;
        print(f"[TRIGGER] {here.kind} targets downgrade to {self.downgrade_to}");
        visit [->:Invalidates:->] else { disengage; }
