node Binding {
    has name: str = "";
    has expr_kind: str = "";      # "JSX" | "Pure" | "Effect"
    has is_memoized: bool = False;
}

edge Precedes { }     # statement-order within a React.do block
edge MemoKey  { }     # lifted bind -> key it depends on
edge InReactDo { }   # DoStatementLet -> the React.do block it lives in

walker ScopeWalker {
    has scope_order: int = 0;
    has jsx_memos: int = 0;
    has lifted_names: list[str] = [];

    can start with Root entry {
        visit [->:InReactDo:->];
    }

    can analyze with Binding entry {
        # The "scope" at this insertion point is every preceding
        # Binding connected via a chain of Precedes edges (positional,
        # not name-keyed, so do-level shadowing is handled correctly).
        prior: list[Binding] = [->:Precedes:-> : Binding];
        here.scope_order = len(prior);

        # Memoize only JSX-valued `let`s — these are the only ones
        # that buy React a referentially-stable subtree to bail on.
        # Non-JSX memos have a provably-zero bailout ceiling.
        if here.expr_kind == "JSX" {
            key_name = f"_memo_key_{here.name}";
            here.is_memoized = True;
            self.jsx_memos += 1;
            self.lifted_names = self.lifted_names + [here.name];
            # Attach the dependency key as a typed edge so downstream
            # readers can trace what each memo was keyed on.
            (b := Binding(name=key_name, expr_kind="Pure")) +>:Precedes:+> here;
            here +>:MemoKey:+> b;
        }

        visit [->:Precedes:->];
    }
}

with entry {
    # The repo's single React.do block contains four `let`s; only one
    # (`moves`) is JSX-valued, so v1 emits exactly one useMemo bind.
    block = Binding(name="<react.do root>", expr_kind="Block");
    s1 = Binding(name="xIsNext", expr_kind="Pure");
    s2 = Binding(name="currentSquares", expr_kind="Pure");
    s3 = Binding(name="moves", expr_kind="JSX");
    s4 = Binding(name="status", expr_kind="Pure");

    # Connect in source order via the typed Precedes edge.
    block +>:Precedes:+> s1;
    s1   +>:Precedes:+> s2;
    s2   +>:Precedes:+> s3;
    s3   +>:Precedes:+> s4;

    # All four bindings live inside this React.do block.
    block +>:InReactDo:+> s1;
    block +>:InReactDo:+> s2;
    block +>:InReactDo:+> s3;
    block +>:InReactDo:+> s4;

    sw = ScopeWalker();
    block spawn sw;

    print(f"positional scope (statement index) of 'moves' = {s3.scope_order}");
    print(f"jsx memos emitted = {sw.jsx_memos}");
    print(f"lifted binding names = {sw.lifted_names}");
}

