"""Purs-memo dependency model: positional scope stability over a React.do AST.

Models the core domain from tools/purs-memo/: a `React.do` block holds
`DoLet` bindings whose values reference earlier-bound names. Stability
of each binding depends on its *positional* scope (names bound strictly
before the binding's insertion point), and memoized deps are key-equality
compared. A walker walks the do-block in order, decides memoization
eligibility per binding, and accumulates a single keyed stability map.
"""

# ---------- Entity archetypes ----------

node DoBlock {
    has label: str = "";
}

node DoLet {
    has name: str = "";
    has is_jsx: bool = False;
    has inserted_index: int = 0;
}

node ExprRef {
    has ident: str = "";
    has is_record_field: bool = False;
}

# ---------- Typed edges: relationships carry meaning ----------

edge ContainsLet {
    has order_index: int = 0;
}

edge RefersTo {
    # Forward-reference flag: True if the ref points to a binding
    # declared AFTER the current binding (broken in v1; must be filtered).
    has is_forward: bool = False;
}

# ---------- Walker ----------

walker MemoAnalyzer {
    # Keyed stability map: name -> "stable" | "shadowed"
    has report: dict[str, str] = {};

    can start with Root entry {
        visit [-->];
    }

    can enter_block with DoBlock entry {
        # Visit the contained DoLets in insertion order via the typed edge.
        visit [->:ContainsLet:->];
    }

    can analyze with DoLet entry {
        # Only JSX-valued `let`s get a memo key (mirrors v1's behavior:
        # bailout ceiling on non-JSX is zero; their only purpose is
        # stabilizing downstream JSX keys).
        if here.is_jsx {
            self.report[here.name] = "stable";
        } else {
            self.report[here.name] = "key-only";
        }
        visit [->:ContainsLet:->];
    }
}

walker ForwardRefScanner {
    # Catches the v1 defect: a binding whose key contains a name bound
    # *after* the binding itself would emit "Unknown value" at build.
    # In v2 positional-scope terms, such references must be filtered.
    has violations: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can scan_block with DoBlock entry {
        visit [->:ContainsLet:->];
    }

    can scan_binding with DoLet entry {
        # Walk every outgoing RefersTo edge out of the bindings nested
        # under this block. The walker has no built-in visited set, so
        # we rely on the typed-edge structure being a DAG (one Let per
        # binding, refs only point at other Lets in the same block).
        visit [here ->:RefersTo:->];
    }

    can collect_ref with ExprRef entry {
        if here.is_record_field {
            # tokensOf cannot tell a record field label from an Ident.
            # Such refs are ambiguous and must be excluded from any key.
            self.violations.append(here.ident);
        }
        # else: a regular forward/backward ref; nothing to flag here.
    }
}

# ---------- Demo wiring ----------

with entry {
    block = DoBlock(label="React.do");
    root ++> block;

    let_node = DoLet(name="xIsNext", is_jsx=False, inserted_index=0);
    squares_node = DoLet(name="currentSquares", is_jsx=False, inserted_index=1);
    moves_node = DoLet(name="moves", is_jsx=True, inserted_index=2);
    play_node = DoLet(name="handlePlay", is_jsx=False, inserted_index=3);

    block +>:ContainsLet(order_index=0):+> let_node;
    block +>:ContainsLet(order_index=1):+> squares_node;
    block +>:ContainsLet(order_index=2):+> moves_node;
    block +>:ContainsLet(order_index=3):+> play_node;

    # The single JSX-valued `let` (moves) is the only real bailout point.
    # Refs from moves point to currentSquares (earlier) and xIsNext (earlier).
    moves_node +>:RefersTo(is_forward=False):+> squares_node;
    moves_node +>:RefersTo(is_forward=False):+> let_node;

    # The forward-reference / record-field ambiguity defect: a name
    # bound later that v1 would have folded into a key because tokensOf
    # treats it as an Ident. Flagged as a violation to filter out.
    ref_field = ExprRef(ident="handlePlay", is_record_field=True);
    moves_node +>:RefersTo(is_forward=True):+> ref_field;

    # Run the memo analyzer.
    analyzer = MemoAnalyzer();
    root spawn analyzer;
    print("Stability report:");
    for (k, v) in analyzer.report.items() {
        print(f"  {k} -> {v}");
    }

    # Run the forward-ref / record-field ambiguity scanner.
    scanner = ForwardRefScanner();
    root spawn scanner;
    print("Forward-ref / record-field violations to filter out:");
    for item in scanner.violations {
        print(f"  {item}");
    }
}

