import from contextlib { redirect_stdout }

test "acyclic project loads packages in dependency order and merges sources" {
    app = Project(name="app", root_manifest="cx.toml");
    php = Package(
        name="php",
        version="0.1.0",
        manifest_path="packages/php/php.toml",
        canonical_path="/workspace/packages/php/php.toml",
    );
    common = Package(
        name="common",
        version="0.1.0",
        manifest_path="packages/common/common.toml",
        canonical_path="/workspace/packages/common/common.toml",
    );
    app +>:DeclaresPackage:+> php;
    php +>:DeclaresPackage:+> common;
    app +>:HasSource:+> SourceFile(path="src/main.cx");
    php +>:HasSource:+> SourceFile(path="packages/php/src/bindings.cx");
    common +>:HasSource:+> SourceFile(path="packages/common/src/log.cx");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        loader = ManifestLoader();
        app spawn loader;
    }
    out = buf.getvalue();

    assert loader.errors == [], f"unexpected errors: {loader.errors}";
    assert len(loader.merged_sources) == 3, f"got {len(loader.merged_sources)} sources: {loader.merged_sources}";
    assert "src/main.cx" in loader.merged_sources, f"missing app source: {loader.merged_sources}";
    assert "packages/php/src/bindings.cx" in loader.merged_sources, f"missing php source: {loader.merged_sources}";
    assert "packages/common/src/log.cx" in loader.merged_sources, f"missing common source: {loader.merged_sources}";
    assert "resolving project 'app' from cx.toml" in out, f"missing project resolve line: {out}";
    assert "loaded package php" in out, f"missing php load line: {out}";
    assert "loaded package common" in out, f"missing common load line: {out}";
    assert out.index("loaded package php") < out.index("loaded package common"), f"common should load after php (transitive): {out}";
    assert "merged source src/main.cx" in out, f"missing merged src/main.cx line: {out}";
}

