"""Regression tests for the correct/store parity defect and the
entity_type contract gap modeled in main.jac."""

import io;
import from contextlib { redirect_stdout }

test "store fields are raw and correct fields are stringified" {
    root ++> Entity(entity_type="session_digest", entity_id="ent_store_good");

    e1 = [root -->][0];
    e1 +>:Store:+> Field(
        name="tasks_claimed", value="[1,2,3]",
        value_type="list[int]", encoded=False, owner_id="ent_store_good"
    );
    e1 +>:Store:+> Field(
        name="artifacts", value="[{\"id\":1}]",
        value_type="list[dict]", encoded=False, owner_id="ent_store_good"
    );
    e1 +>:Correct:+> Field(
        name="decisions", value="\"[{\\\"k\\\":1}]\"",
        value_type="list[dict]", encoded=True, owner_id="ent_store_good"
    );

    collector = SnapshotCollector();
    res = root spawn collector;

    assert res.field_count == 3, f"expected 3 fields, got {res.field_count}";
    assert res.corrupted == 1, f"expected 1 corrupted, got {res.corrupted}";

    raw_lines = [l for l in res.report if l.startswith("raw ")];
    bad_lines = [l for l in res.report if l.startswith("STRINGIFIED ")];
    assert len(raw_lines) == 2, f"expected 2 raw lines, got {len(raw_lines)}";
    assert len(bad_lines) == 1, f"expected 1 STRINGIFIED line, got {len(bad_lines)}";

    assert any("tasks_claimed" in l for l in raw_lines), "tasks_claimed should be raw";
    assert any("artifacts" in l for l in raw_lines), "artifacts should be raw";
    assert any("decisions" in l and "STRINGIFIED" in l for l in res.report), (
        "decisions should be flagged STRINGIFIED"
    );
}

test "backfill advisor only flags stringified fields" {
    root ++> Entity(entity_type="session_digest", entity_id="ent_a");
    root ++> Entity(entity_type="session_digest", entity_id="ent_b");

    entities = [root -->];
    entities[0] +>:Store:+> Field(
        name="tags", value="[\"a\",\"b\"]",
        value_type="list[str]", encoded=False, owner_id="ent_a"
    );
    entities[0] +>:Correct:+> Field(
        name="decisions", value="\"[1,2]\"",
        value_type="list[int]", encoded=True, owner_id="ent_a"
    );
    entities[1] +>:Correct:+> Field(
        name="choices", value="\"[\\\"x\\\"]\"",
        value_type="list[str]", encoded=True, owner_id="ent_b"
    );
    entities[1] +>:Correct:+> Field(
        name="weights", value="\"[0.1]\"",
        value_type="list[float]", encoded=True, owner_id="ent_b"
    );

    advisor = BackfillAdvisor();
    res = root spawn advisor;

    assert len(res.advice) == 3, (
        f"expected 3 backfill advisories, got {len(res.advice)}: {res.advice}"
    );

    assert any("ent_a" in a and "decisions" in a for a in res.advice), (
        "must advise backfill of decisions on ent_a"
    );
    assert any("ent_b" in a and "choices" in a for a in res.advice), (
        "must advise backfill of choices on ent_b"
    );
    assert any("ent_b" in a and "weights" in a for a in res.advice), (
        "must advise backfill of weights on ent_b"
    );

    for line in res.advice {
        assert "store+target_id" in line, (
            f"advisory must point callers at store+target_id workaround: {line}"
        );
    }

    for line in res.advice {
        assert "tags" not in line, (
            f"non-corrupted field 'tags' must NOT appear in advice: {line}"
        );
    }
}

test "reachable walker visits entities in chain order and respects cycle guard" {
    root ++> Entity(entity_type="session_digest", entity_id="ent_r1");
    a = [root -->][0];
    a ++> Entity(entity_type="session_digest", entity_id="ent_r2");
    b = [a -->][0];
    b ++> Entity(entity_type="session_digest", entity_id="ent_r3");

    reacher = Reachable(max_hops=10);
    res = root spawn reacher;

    assert res.frontier == ["ent_r1", "ent_r2", "ent_r3"], (
        f"expected ['ent_r1','ent_r2','ent_r3'], got {res.frontier}"
    );
    assert "ent_r1" in res.visited, "ent_r1 should be visited";
    assert "ent_r2" in res.visited, "ent_r2 should be visited";
    assert "ent_r3" in res.visited, "ent_r3 should be visited";

    root ++> Entity(entity_type="session_digest", entity_id="ent_cycle");
    cyc = [root -->];
    target = cyc[-1];
    target +>:Correct:+> Field(
        name="loop", value="\"[1]\"",
        value_type="list[int]", encoded=True, owner_id="ent_cycle"
    );

    reacher2 = Reachable(max_hops=10);
    res2 = root spawn reacher2;
    assert "ent_cycle" in res2.frontier, (
        f"ent_cycle must be visited, got {res2.frontier}"
    );
}

test "call_correct requires entity_type and names the missing field" {
    result = call_correct("session_digest", "ent_x", {"k": 1});
    assert result == {
        "entity_type": "session_digest",
        "entity_id": "ent_x",
        "fields": {"k": 1}
    }, f"unexpected return: {result}";

    raised = False;
    msg = "";
    try {
        call_correct(None, "ent_x", {"k": 1});
    } except ValueError as err {
        raised = True;
        msg = str(err);
    }
    assert raised, "call_correct(None, ...) must raise ValueError";
    assert "entity_type" in msg, (
        f"error message must name the missing field 'entity_type', got: {msg!r}"
    );

    buf = io.StringIO();
    with redirect_stdout(buf) {
        try {
            call_correct(None, "ent_x", {"k": 1});
        } except ValueError as err {
            print(f"contract error: {err}");
        }
    }
    out = buf.getvalue();
    assert "contract error:" in out, f"missing contract error marker: {out!r}";
    assert "entity_type" in out, (
        f"printed contract error must name entity_type: {out!r}"
    );
}

