test "accepts a nested relative extension path" {
    extensions_dir = Dir(name="extensions", depth=0);
    tools_dir = Dir(name="tools", depth=1);
    linters_dir = Dir(name="linters", depth=2);
    request = Extension(title="safe-ext", proposed_name="tools/linters");
    root ++> request;
    request +>:Contains:+> extensions_dir;
    extensions_dir +>:Contains:+> tools_dir;
    tools_dir +>:Contains:+> linters_dir;
    res = root spawn PathAuditor();
    assert res.safe == True, f"got {res.safe}";
    assert res.reason == "", f"got {res.reason}";
}

test "rejects parent traversal from the extensions root" {
    extensions_dir = Dir(name="extensions", depth=0);
    request = Extension(title="evil-ext", proposed_name="../evil");
    root ++> request;
    request +>:Contains:+> extensions_dir;
    res = root spawn PathAuditor();
    assert res.safe == False, f"got {res.safe}";
    assert res.reason == "traversal escapes extensions root", f"got {res.reason}";
}

test "rejects an absolute extension path" {
    extensions_dir = Dir(name="extensions", depth=0);
    request = Extension(title="abs-ext", proposed_name="/usr/local/bin");
    root ++> request;
    request +>:Contains:+> extensions_dir;
    res = root spawn PathAuditor();
    assert res.safe == False, f"got {res.safe}";
    assert res.reason == "absolute path rejected", f"got {res.reason}";
}

test "rejects backslash parent traversal" {
    extensions_dir = Dir(name="extensions", depth=0);
    request = Extension(title="windows-evil", proposed_name="..\\evil");
    root ++> request;
    request +>:Contains:+> extensions_dir;
    res = root spawn PathAuditor();
    assert res.safe == False, f"got {res.safe}";
    assert res.reason == "traversal escapes extensions root", f"got {res.reason}";
}

