"""Cloud Streams subscriber retry policy bypass: failed dispatches recurse with no backoff.

Models neuroglia-io/cloud-streams#131 — RetryDispatchAsync and DispatchAsync mutually
recurse, resetting Polly counters and inflating TotalDeliveryFailures instead of honoring
maxAttempts, backoffDuration, and circuitBreaker settings.
"""

edge RetryToDispatch {
    has label: str = "retry";
}

edge DispatchToRetry {
    has label: str = "dispatch";
}

edge DeliversTo {
    has since_offset: int = 0;
}

node RetryPolicy {
    has max_attempts: int = 3;
    has backoff_seconds: int = 3;
    has break_after: int = 3;
    has break_duration_seconds: int = 5;
}

node Subscription {
    has name: str = "";
    has subscriber_uri: str = "";
    has policy: RetryPolicy = RetryPolicy();
    has available: bool = True;
}

node Subscriber {
    has uri: str = "";
    has returns_success: bool = False;
    has available: bool = True;
}

node DispatchAttempt {
    has offset: int = 0;
    has http_status: int = 503;
    has available: bool = True;
}

walker BrokenBroker {
    has delivery_failures: int = 0;
    has policy_builds: int = 0;
    has attempt_in_policy: int = 0;
    has recursion_depth: int = 0;
    has max_demo_depth: int = 6;

    can start with Root entry {
        print("=== Broken path: mutual recursion bypasses retry policy ===");
        visit [-->];
    }

    can retry_dispatch with Subscription entry {
        self.policy_builds += 1;
        self.attempt_in_policy = 0;
        print(
            f"RetryDispatch: fresh Polly policy #{self.policy_builds} "
            f"(maxAttempts={here.policy.max_attempts} never reached)"
        );
        visit [->:RetryToDispatch:->] else { disengage; };
    }

    can dispatch_async with DispatchAttempt entry {
        self.recursion_depth += 1;
        self.attempt_in_policy += 1;
        self.delivery_failures += 1;
        outcome = "FAIL" if here.http_status >= 400 else "OK";
        print(
            f"  DispatchAsync(retryOnError=false) depth={self.recursion_depth} "
            f"status={here.http_status} [{outcome}] "
            f"policy_attempt={self.attempt_in_policy} "
            f"total_failures={self.delivery_failures}"
        );
        if here.http_status >= 400 {
            if self.recursion_depth >= self.max_demo_depth {
                print(
                    f"  Demo cap at depth {self.max_demo_depth}; "
                    f"real broker recurses with NO backoff and NO cap"
                );
                disengage;
            }
            visit [->:DispatchToRetry:->] else { disengage; };
        } else {
            visit [-->];
        }
    }
}

walker PolicyBroker {
    has attempts: int = 0;
    has delivery_failures: int = 0;
    has consecutive_failures: int = 0;
    has circuit_open: bool = False;

    can start with Root entry {
        print("=== Correct path: single policy governs bounded retries ===");
        visit [-->];
    }

    can apply_policy with Subscription entry {
        if self.circuit_open {
            print(
                f"Circuit OPEN — delivery paused to {here.subscriber_uri} "
                f"for {here.policy.break_duration_seconds}s"
            );
            disengage;
        }
        while self.attempts < here.policy.max_attempts {
            self.attempts += 1;
            self.delivery_failures += 1;
            self.consecutive_failures += 1;
            print(
                f"  Polly attempt {self.attempts}/{here.policy.max_attempts} "
                f"-> {here.subscriber_uri} [503 FAIL]"
            );
            if self.consecutive_failures >= here.policy.break_after {
                self.circuit_open = True;
                print(
                    f"  Circuit breaker opened after "
                    f"{here.policy.break_after} consecutive failures"
                );
                break;
            }
            if self.attempts < here.policy.max_attempts {
                print(
                    f"  Backoff: waiting {here.policy.backoff_seconds}s "
                    f"before next attempt"
                );
            }
        }
        print(
            f"Policy stopped after {self.attempts} real attempts, "
            f"failures={self.delivery_failures}, "
            f"circuit_open={self.circuit_open}"
        );
        visit [-->];
    }
}

with entry {
    failing_sub = Subscriber(
        uri="http://localhost:8888/some-endpoint",
        returns_success=False
    );
    sub = Subscription(
        name="all-events",
        subscriber_uri="http://localhost:8888/some-endpoint",
        policy=RetryPolicy(
            max_attempts=3,
            backoff_seconds=3,
            break_after=3,
            break_duration_seconds=5
