    has pool_policies: dict[str, list[str]] = {};

    def seen(n: str) -> bool {
        for v in self.visited {
            if v == n {
                return True;
            }
        }
        return False;
    }

    def mark(n: str) -> None {
        if not self.seen(n) {
            self.visited.append(n);
        }
    }

    def record_parent(pool: str, gw: str) -> None {
        existing = self.pool_parents.get(pool, []);
        if gw not in existing {
            existing.append(gw);
            self.pool_parents[pool] = existing;
        }
    }

    def record_policy(pool: str, scope: str) -> None {
        existing = self.pool_policies.get(pool, []);
        if scope not in existing {
            existing.append(scope);
            self.pool_policies[pool] = existing;
        }
    }

    def index_pool(pool_name: str) -> None {
        full_list: list[str] = [];
        if pool_name in self.pool_parents {
            full_list = self.pool_parents[pool_name];
        }
        for gw in full_list {
            for (i, p) in enumerate(full_list) {
                if i == 0 {
                    self.pool_policies[pool_name] = [f"routing-policy-for-{gw}"];
                } else {
                    self.pool_policies[pool_name].append(f"routing-policy-for-{gw}");
                }
                break;
            }
        }
    }

    can start with Root entry {
        visit [-->];
    }

    can enter_gateway with Gateway entry {
        self.mark(here.name);
        attached_models = [-->->:AttachedTo:->](?:AgentgatewayModel);
        for m in attached_models {
            m spawn IndexFromModel(scope=here.scope);
        }
        visit [-->];
    }
}

walker IndexFromModel {
    has scope: str = "";

    can start with AgentgatewayModel entry {
        if here.kind == "Virtual" {
            visit [->:FailoverTarget:->];
        } else {
            visit [->:BackendRef:->];
        }
    }

    can resolve_target with AgentgatewayModel entry {
        visit [->:BackendRef:->];
    }

    can reach_pool with InferencePool entry {
        active = root spawn AncestorIndexer();
        scope_label = "";
        if self.scope != "" {
            scope_label = self.scope;
        } else {
            scope_label = "unknown";
        }
        active.record_parent(here.name, scope_label);
        if scope_label not in active.pool_policies.get(here.name, []) {
            existing_p = active.pool_policies.get(here.name, []);
            existing_p.append(scope_label);
            active.pool_policies[here.name] = existing_p;
        }
    }
}

walker ReportAncestors {
    can start with Root entry {
        active = root spawn AncestorIndexer();
        pool_names: list[str] = [];
        for k in active.pool_parents.keys() {
            pool_names.append(k);
