"""InferencePool ancestry through virtual AgentgatewayModel failover targets.

Demonstrates gateway-to-pool reachability: a direct backend-ref walk misses
virtual-model failover chains; a failover-aware propagator credits every gateway
that can route traffic to the pool.
"""

node Gateway {
    has name: str = "";
}

node AgentgatewayModel {
    has name: str = "";
    has is_virtual: bool = False;
}

node InferencePool {
    has name: str = "";
    has direct_parents: list[str] = [];
    has full_parents: list[str] = [];
}

edge FailoverTarget { }

edge BackendRef { }

walker DirectBackendIndexer {
    has gateway_name: str = "";

    can start with Gateway entry {
        self.gateway_name = here.name;
        visit [-->];
    }

    can on_model with AgentgatewayModel entry {
        if here.is_virtual {
            disengage;
        }
        visit [->:BackendRef:->] else { disengage; };
    }

    can on_pool with InferencePool entry {
        if self.gateway_name not in here.direct_parents {
            here.direct_parents.append(self.gateway_name);
        }
        disengage;
    }
}

walker AncestorPropagator {
    has gateway_name: str = "";
    has seen_models: list[str] = [];

    can start with Gateway entry {
        self.gateway_name = here.name;
        visit [-->];
    }

    can descend with AgentgatewayModel entry {
        if here.name in self.seen_models {
            disengage;
        }
        self.seen_models.append(here.name);
        if here.is_virtual {
            visit [->:FailoverTarget:->] else { disengage; };
        } else {
            visit [->:BackendRef:->] else { disengage; };
        }
    }

    can register with InferencePool entry {
        if self.gateway_name not in here.full_parents {
            here.full_parents.append(self.gateway_name);
        }
        disengage;
    }
}

