    );

    root ++> run;
    run +>:DependsOn:+> ingest;
    ingest +>:DependsOn:+> validate;
    validate +>:DependsOn:+> send_email;
    send_email +>:DependsOn:+> post_reply;

    print("=== Phase 1: recover crash-stuck running claims ===");
    sweeper = LeaseSweeper();
    root spawn sweeper;

    print("=== Phase 2: dependency-ordered node execution ===");
    executor = DependencyExecutor();
    root spawn executor;

    print("=== Phase 3: cycle guard (clean graph) ===");
    guard = CycleGuard();
    root spawn guard;

    cycle_status = "yes" if guard.found_cycle else "no";
    print(
        f"Summary: recovered={sweeper.recovered}, "
        f"executed={executor.executed}, "
        f"side_effects={executor.side_effects}, "
        f"cycle={cycle_status}"
    );
}

