"""Symlink-aware scope walker.

Models the essential symlink resolution defects from issue #865:
directory-of-links expansion, link-name vs target routing, cycle
widening when a child link points to an ancestor, and the
core.symlinks=false "pointer file" mode where lstat would lie.

The rule is named in the module: route by the link's location in the
graph, never by the resolved target path. A cycle guard caps the
walk so an ancestor-pointing link cannot widen the scope.
"""

# ---------------------------------------------------------------------------
# Node archetypes
# ---------------------------------------------------------------------------

# A Scope is a named collection of paths a check applies to. The
# `kind` distinguishes "directory" scopes from "file" scopes so the
# walker can expand a directory into its visible children.
node Scope {
    has name: str = "";
    has kind: str = "directory";  # "directory" | "file"
}

# A Path is something resolvable on the filesystem graph. It models
# what `git ls-files` and `lstatSync()` together report. When
# `core.symlinks=false`, git writes mode 120000 as a regular file
# whose contents are the target path -- `lstat.isSymbolicLink()` is
# then false even though `is_pointer` is true.
node Path {
    has label: str = "";          # the name git ls-files reports
    has is_link: bool = False;    # honest symlink per lstat
    has is_pointer: bool = False; # core.symlinks=false mode 120000
    has target: str = "";         # path string a link points at
    has is_directory: bool = False;
}

# A Skill project is what the .claude/skills directory contains. We
# model only the subset needed to show the defect: a directory Scope
# of directory links. Each link is a child of the skill Scope.
node SkillProject {
    has name: str = "";
    has has_ts: bool = False;  # True only for "upstream-report"
}

# ---------------------------------------------------------------------------
# Edge archetypes
# ---------------------------------------------------------------------------

# "Contents" is a typed relationship from a directory Scope to a Path
# or a SkillProject sitting inside it. This is the parent-of edge
# the original code walks manually.
edge Contents { }

# "Resolves" connects a symlink/pointer Path to the Path it points
# at. Cyclic graphs are the danger: a child link pointing at an
# ancestor creates a Contents -> Resolves -> Contents loop. We model
# it so the walker can demonstrate the cycle-widening defect.
edge Resolves { }

# ---------------------------------------------------------------------------
# Walker
# ---------------------------------------------------------------------------

walker RoutePaths {
    # The single rule, named: route by the path's *location* in the
    # graph (the Scope it was listed under), not by the path its
    # link resolves to. `seen` is the explicit cycle guard -- in
    # jac 0.36.1 walkers do not dedupe nodes on their own.
    has seen: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 32;
    has hits: list[str] = [];

    can begin with Root entry {
        visit [-->];
    }

    can route with Scope entry {
        print(f"scope[{here.name}] kind={here.kind}");
        if here.kind == "directory" {
            visit [->:Contents:->];
        }
    }

    # Single union ability for both Path and SkillProject children.
    # Shared surface: every node reachable via a Contents edge has
    # a `name` (paths use `label`, projects use `name`). We pick
    # whichever exists and use it as the routing key, matching the
    # "route by the link's name in its listed scope" rule.
    can walk_link with Path | SkillProject entry {
        key = here.label if isinstance(here, Path) else here.name;
        if key in self.seen {
            print(f"  skip (cycle guard) {key}");
            disengage;
        }
        if self.depth >= self.max_depth {
            print(f"  stop (depth cap) {key}");
            disengage;
        }
        self.seen.append(key);
        self.depth += 1;
        self.hits.append(key);

