import from contextlib { redirect_stdout }

# ---------- Defect 1: directory-of-symlinks expands under .claude/skills ----------
test "defect 1: directory symlinks under .claude/skills expand and check files" {
    skills = Directory(name="skills", path=".claude/skills");
    skill_link = Symlink(
        name="upstream-report",
        path=".claude/skills/upstream-report",
        target_path="skills/upstream-report",
        is_native_link=True
    );
    skill_proj = Directory(name="upstream-report", path="skills/upstream-report");
    skill_ts = File(
        name="index.ts",
        path="skills/upstream-report/index.ts",
        content="export const x: number = 1;"
    );
    root ++> skills;
    skills +>:Contains:+> skill_link;
    skill_link +>:PointsTo(via="dir-link"):+> skill_proj;
    skill_proj +>:Contains:+> skill_ts;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        skills spawn InputResolver(scope_name="types", scope_prefix=".claude/skills");
    }
    out = buf.getvalue();

    assert "[EXPAND] linked dir skills/upstream-report via .claude/skills/upstream-report" in out, f"expected expansion of dir-link, got: {out}";
    assert "[CHECK]" in out, f"expected at least one check through the link, got: {out}";
    assert "skills/upstream-report/index.ts" in out, f"expected the linked ts file to be checked, got: {out}";
}

# ---------- Defect 2: banned-patterns over src/ catches banned content via file link ----------
test "defect 2: file-link under src/ routes by link location and catches banned content" {
    src = Directory(name="src", path="src");
    src_link = Symlink(
        name="utils",
        path="src/utils",
        target_path="scripts/banned.ts",
        is_native_link=True
    );
    banned_file = File(
        name="banned.ts",
        path="scripts/banned.ts",
        content="eval(userInput);"
    );
    root ++> src;
    src +>:Contains:+> src_link;
    src_link +>:PointsTo(via="file-link"):+> banned_file;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        src spawn InputResolver(scope_name="banned-patterns", scope_prefix="src/");
    }
    out = buf.getvalue();

    assert "route=src/utils content=scripts/banned.ts -> BANNED" in out, f"expected banned content caught via file-link routing, got: {out}";
    assert "[SYMLINK] route at src/utils" in out, f"expected symlink routing marker, got: {out}";
}

# ---------- Defect 4: pointer file (core.symlinks=false) still routes ----------
test "defect 4: pointer file under .claude/skills routes despite non-native link" {
    skills = Directory(name="skills", path=".claude/skills");
    pointer_link = Symlink(
        name="skill-ref",
        path=".claude/skills/skill-ref",
        target_path="skills/other",
        is_native_link=False
    );
    pointer_proj = Directory(name="other", path="skills/other");
    pointer_ts = File(
        name="report.ts",
        path="skills/other/report.ts",
        content="export const y: number = 2;"
    );
    root ++> skills;
    skills +>:Contains:+> pointer_link;
    pointer_link +>:PointsTo(via="pointer-file"):+> pointer_proj;
    pointer_proj +>:Contains:+> pointer_ts;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        skills spawn InputResolver(scope_name="skill-types", scope_prefix=".claude/skills");
    }
    out = buf.getvalue();

    assert "[POINTER] route at .claude/skills/skill-ref" in out, f"expected pointer (non-native link) marker, got: {out}";
    assert "[CHECK] route=.claude/skills/skill-ref content=skills/other/report.ts" in out, f"expected pointer link to route to ts content, got: {out}";
    assert "POINTER" in out, f"expected POINTER kind to be reported (not SYMLINK), got: {out}";
}

# ---------- Defect 5: ancestor link must not escape named directory ----------
test "defect 5: ancestor link up->.. under nested/trap is blocked and does not escape" {
    trap = Directory(name="trap", path="nested/trap");
    up_link = Symlink(
        name="up",
        path="nested/trap/up",
        target_path="..",
        is_native_link=True
    );
    outside = Directory(name="outside", path="nested");
    outside_file = File(
        name="secret.ts",
        path="nested/secret.ts",
        content="export const z: number = 3;"
    );
    root ++> trap;
    trap +>:Contains:+> up_link;
    root ++> outside;
    outside +>:Contains:+> outside_file;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        trap spawn InputResolver(scope_name="trap-walk", scope_prefix="nested/trap");
    }
    out = buf.getvalue();

    assert "[BLOCKED] ancestor link at nested/trap/up would escape nested/trap" in out, f"expected ancestor escape to be blocked, got: {out}";
    assert "secret.ts" not in out, f"ancestor link must not leak outside-directory file, got: {out}";
}

# ---------- Cycle/visited guard: revisiting same dir should not double-count ----------
test "visited guard: revisiting a directory is skipped and not double-counted" {
    skills = Directory(name="skills", path=".claude/skills");
    skill_link = Symlink(
        name="upstream-report",
        path=".claude/skills/upstream-report",
        target_path="skills/upstream-report",
        is_native_link=True
    );
    skill_proj = Directory(name="upstream-report", path="skills/upstream-report");
    skill_ts = File(
        name="index.ts",
        path="skills/upstream-report/index.ts",
        content="export const x: number = 1;"
    );
    root ++> skills;
    skills +>:Contains:+> skill_link;
    skill_link +>:PointsTo(via="dir-link"):+> skill_proj;
    skill_proj +>:Contains:+> skill_ts;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        skills spawn InputResolver(scope_name="types", scope_prefix=".claude/skills");
    }
    out = buf.getvalue();

    assert out.count("[CHECK]") == 1, f"expected exactly one check (no double-count via revisit), got {out.count('[CHECK]')} checks: {out}";
    assert out.count("[EXPAND] linked dir skills/upstream-report via .claude/skills/upstream-report") == 1, f"expected expand emitted once, got: {out}";
}

