"""Assembly call-target projection: typed traversal from one LibraryBodyIndex
through retained assembly participants to resolved member definitions,
modeling the design called out in issue #5116.

The traversal proves which assembly candidate supplied an external member.
Selection alone is not enough — the walker must physically reach the
definition (or report a visible negative outcome) without ever inspecting
inactive shadows or ambiguous candidates.
"""

# Nodes ----------------------------------------------------------------

node LibraryBodyIndex {
    # The root call-site context. Carries the assembly descriptor it was
    # bound to plus the retained (post-selection) participant set.
    has assembly_name: str = "";
    has member_name: str = "";
}

node Assembly {
    # A retained participant. Carries an availability flag so inactive
    # shadows and ambiguous candidates can be excluded by traversal.
    has name: str = "";
    has is_active: bool = True;
    has is_ambiguous: bool = False;
}

node Member {
    # A concrete definition exposed by an assembly. Inactive members are
    # never inspected by the projection walker.
    has name: str = "";
    has is_inactive: bool = False;
}

# Typed edges ----------------------------------------------------------

edge HasParticipant {
    # LibraryBodyIndex -> retained Assembly. The owner has already selected
    # these; nothing else participates.
}

edge Declares {
    # Assembly -> Member it defines. Inactive shadows live on this edge.
}

# Walker ---------------------------------------------------------------

walker CallTargetProjector {
    # Accumulates typed outcomes as it walks from a single LibraryBodyIndex
    # through retained participants to a member definition.
    has manifest_frozen: bool = False;
    has outcomes: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can project with LibraryBodyIndex entry {
        print(f"[index] assembly={here.assembly_name} member={here.member_name}");
        # Freeze the manifest at projection time. Source mutation after this
        # point cannot change what Analysis observes.
        self.manifest_frozen = True;
        # Only retained, active, unambiguous participants participate.
        visit [->:HasParticipant:->];
    }

    can inspect with Assembly entry {
        # Skip inactive shadows and ambiguous candidates entirely.
        if (not here.is_active) or here.is_ambiguous {
            print(f"[skip] assembly={here.name} (inactive={not here.is_active}, ambiguous={here.is_ambiguous})");
            visit [-->] else { disengage; };
        }
        print(f"[scan] assembly={here.name}");
        visit [->:Declares:->];
    }

    can resolve with Member entry {
        # Skip inactive member shadows.
        if here.is_inactive {
            print(f"[skip-member] {here.name} (inactive shadow)");
            visit [-->] else { disengage; };
        }
        # The walker always reports at most one exit record: a single typed
        # outcome line derived from the current node's properties.
        status = "resolved-definition" if (here.name == "Target") else "member-missing";
        self.outcomes.append(f"{status}:{here.name}");
        print(f"[{status}] member={here.name}");
        # No further traversal — projection is single-shot per index.
        disengage;
    }
}

# Demo wiring ----------------------------------------------------------

with entry {
    # One root LibraryBodyIndex bound to assembly 'Primary' looking for
    # member 'Target'.
    index = LibraryBodyIndex(assembly_name="Primary", member_name="Target");

    # Two retained participants: the correct one and a near miss.
    primary = Assembly(name="Primary", is_active=True, is_ambiguous=False);
    fallback = Assembly(name="Fallback", is_active=True, is_ambiguous=False);

    # An inactive shadow and an ambiguous candidate — must be skipped.
    shadow = Assembly(name="Shadow", is_active=False, is_ambiguous=False);
    ambiguous = Assembly(name="Ambiguous", is_active=True, is_ambiguous=True);

    # Members declared by each retained, active assembly.
    primary_target = Member(name="Target", is_inactive=False);
    primary_other = Member(name="Helper", is_inactive=False);
    fallback_target = Member(name="Target", is_inactive=False);

    # Member under the inactive shadow that must NOT be inspected.
    shadow_target = Member(name="Target", is_inactive=True);

    # Wire the graph. Only HasParticipant and Declares carry meaning.
    root +>:HasParticipant:+> index;
