"""Test annex for assembly call-target traversal."""

import io;
import from contextlib { redirect_stdout }

test "frozen plan with full requests marks resolved-definition" {
    root ++> LibraryBodyIndex(name="App.Assembly", descriptor="app,v1.0", is_active=True);
    body = [root -->][?:LibraryBodyIndex][0];
    platform = SelectedParticipant(name="Platform", is_available=True);
    body +>:Retains(role="selected"):+> platform;
    plan = CorrespondencePlan(
        is_frozen=True,
        requests=["declaring", "parameter", "return", "generic", "custom-modifier"]
    );
    body +>:Retains(role="manifest"):+> plan;
    member_ref = ExternalMemberRef(member_name="Helper.WriteLine", signature_kind="declaring", call_site_id="site-0x42");
    body +>:Targets(kind="call-target"):+> member_ref;
    defn = Definition(name="Helper.WriteLine", matches=True);
    member_ref +>:ResolvesTo(outcome="resolved-definition"):+> defn;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = body spawn CallGraphProjection();
    }

    assert res.plan_frozen, f"plan_frozen flag must be True, got {res.plan_frozen}";
    assert "resolved-definition" in res.outcomes, f"outcomes missing resolved-definition: {res.outcomes}";
    assert "correspondence-incomplete" not in res.outcomes, f"plan was frozen so incomplete must not appear: {res.outcomes}";
}

test "unfrozen plan forces correspondence-incomplete outcome" {
    root ++> LibraryBodyIndex(name="App.Assembly", descriptor="app,v1.0", is_active=True);
    body = [root -->][?:LibraryBodyIndex][0];
    plan = CorrespondencePlan(is_frozen=False, requests=["declaring"]);
    body +>:Retains(role="manifest"):+> plan;
    member_ref = ExternalMemberRef(member_name="Foo.Bar", signature_kind="declaring", call_site_id="site-1");
    body +>:Targets(kind="call-target"):+> member_ref;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = body spawn CallGraphProjection();
    }

    assert not res.plan_frozen, f"plan_frozen must be False for an unfrozen plan, got {res.plan_frozen}";
    assert "correspondence-incomplete" in res.outcomes, f"expected correspondence-incomplete, got {res.outcomes}";
    assert "resolved-definition" not in res.outcomes, f"no definition may resolve under an unfrozen plan: {res.outcomes}";
}

test "ambiguous and inactive-shadow candidates are skipped" {
    root ++> LibraryBodyIndex(name="App.Assembly", descriptor="app,v1.0", is_active=True);
    body = [root -->][?:LibraryBodyIndex][0];
    good = SelectedParticipant(name="Platform");
    ambig = SelectedParticipant(name="AmbiguousOne", is_ambiguous=True);
    shadow = SelectedParticipant(name="ShadowOne", is_inactive_shadow=True);
    body +>:Retains(role="selected"):+> good;
    body +>:Retains(role="selected"):+> ambig;
    body +>:Retains(role="selected"):+> shadow;
    plan = CorrespondencePlan(is_frozen=True, requests=["declaring"]);
    body +>:Retains(role="manifest"):+> plan;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = body spawn CallGraphProjection();
    }

    assert "candidate-unavailable" not in res.outcomes, f"ambiguity/shadow must not produce unavailable outcome: {res.outcomes}";
    assert "resolved-definition" not in res.outcomes, f"no member ref was attached, should not resolve: {res.outcomes}";

    real_edges = [good ->:ResolvesTo:->];
    assert len(real_edges) == 0, f"clean participant must not own any ResolvesTo edges, got {len(real_edges)}";
    assert len([ambig ->:ResolvesTo:->]) == 0, f"ambiguous candidate must own no ResolvesTo edges";
    assert len([shadow ->:ResolvesTo:->]) == 0, f"inactive shadow must own no ResolvesTo edges";
}

test "unavailable candidate yields candidate-unavailable and preserves call-site identity" {
    root ++> LibraryBodyIndex(name="App.Assembly", descriptor="app,v1.0", is_active=True);
    body = [root -->][?:LibraryBodyIndex][0];
    dead = SelectedParticipant(name="EmptyPlatform", is_available=False);
    body +>:Retains(role="selected"):+> dead;
    plan = CorrespondencePlan(is_frozen=True, requests=["declaring", "parameter"]);
    body +>:Retains(role="manifest"):+> plan;
    member_ref = ExternalMemberRef(member_name="Helper.WriteLine", signature_kind="declaring", call_site_id="site-0x42");
    body +>:Targets(kind="call-target"):+> member_ref;
    missing = MissingMember(reason="member-missing");
    dead +>:ResolvesTo(outcome="member-missing"):+> missing;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = body spawn CallGraphProjection();
    }

    assert "candidate-unavailable" in res.outcomes, f"expected candidate-unavailable, got {res.outcomes}";
    assert "member-missing" in res.outcomes, f"expected member-missing from the dead candidate, got {res.outcomes}";
    assert "resolved-definition" not in res.outcomes, f"unavailable participant must not resolve: {res.outcomes}";

    assert member_ref.call_site_id == "site-0x42", f"call-site identity must be preserved on the MemberRef node";
    refs_to_member = [body ->:Targets:->];
    assert member_ref in refs_to_member, f"member ref must be reachable from body via Targets edge";
}

test "inactive root index halts traversal before any resolution" {
    root ++> LibraryBodyIndex(name="App.Assembly", descriptor="app,v1.0", is_active=False);
    body = [root -->][?:LibraryBodyIndex][0];
    good = SelectedParticipant(name="Platform");
    body +>:Retains(role="selected"):+> good;
    plan = CorrespondencePlan(is_frozen=True, requests=["declaring"]);
    body +>:Retains(role="manifest"):+> plan;
    member_ref = ExternalMemberRef(member_name="Helper.WriteLine", signature_kind="declaring", call_site_id="site-0x42");
    body +>:Targets(kind="call-target"):+> member_ref;
    defn = Definition(name="Helper.WriteLine", matches=True);
    member_ref +>:ResolvesTo(outcome="resolved-definition"):+> defn;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = body spawn CallGraphProjection();
    }

    assert res.outcomes == [], f"inactive root must yield no outcomes, got {res.outcomes}";
    assert not res.plan_frozen, f"inactive root must not flip plan_frozen, got {res.plan_frozen}";
}

