"""Stacked merge request dispatch: model dependent issues, blockers, and the
parent-selection walker that decides when a child can branch off a blocker.

This demo captures the core of the issue's dispatch policy as graph machinery:
dependent issues link to blocker issues, a walker walks the blocker set to
classify states, picks a deterministic parent (or refuses), and reports a
dispatch decision. A second walker rebases the child when the chosen parent
becomes merged.
"""

node Issue {
    has title: str = "";
    has state: str = "Todo";
    has branch: str = "";
    has sha: str = "";
}

# A blocker relationship carries an explicit label so a child knows which parent
# edge to follow for stacked-branch targeting.
edge Blocks { has reason: str = ""; }

# Typed edge used by the rebaser walker to walk only eligible Human-Review
# blockers when selecting a parent.
edge CandidateParent { }

walker DispatchPlanner {
    has decision: str = "";
    has parent_title: str = "";
    has wait_reason: str = "";

    can start with Root entry {
        visit [-->];
    }

    # Union ability: fires for either blocker kind. We only touch fields shared
    # by both (title + state) which are declared on the base Issue.
    can classify with Issue entry {
        if here.state == "Todo" {
            self.wait_reason = "child still Todo";
            disengage;
        }
        visit [-->];
    }
}

walker ParentSelector {
    has parent_title: str = "";
    has base: str = "";
    has wait_reason: str = "";
    has unmerged_count: int = 0;
    has review_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    # One union ability handles every blocker-issue type — they share the
    # base Issue fields, so the body is identical regardless of subtype.
    can evaluate with Issue entry {
        if here.state != "Merged" {
            self.unmerged_count += 1;
            if here.state == "Human Review" and here.branch != "" {
                self.review_count += 1;
                self.parent_title = here.title;
            }
        }
        visit [-->];
    }

    can finalize with Root exit {
        if self.unmerged_count == 0 {
            self.base = "origin/main";
        } elif self.unmerged_count == 1 and self.review_count == 1 {
            self.base = "parent-branch";
        } else {
            self.wait_reason = "multiple unmerged blockers";
            self.base = "";
        }
        report {
            "parent": self.parent_title,
            "base": self.base,
            "wait": self.wait_reason,
        };
