"""Diagnosing a deeply recursive async stack: tests that recurse through
parent/child policy chains blow the test harness's 2 MiB thread stack.

The original Rust codebase hit SIGSEGV inside ``render_doctor_*`` because
deeply nested async state machines produced very large stack frames under
test threads. We model the same shape natively: a graph of
``DiagnosticCheck`` nodes linked by ``DependsOn`` edges, a ``PolicyStore``
that owns them, and a ``Doctor`` walker that walks the dependency chain to
``report`` a topologically ordered execution plan. A ``CycleHunter`` walker
detects cycles the same way a smoke test would, and a ``CascadePurger``
walker demonstrates the cascade-delete traversal. The walker carries an
explicit visited set because Jac 0.36.1 walkers have no built-in
once-per-node visitation — cycle safety stays explicit.
"""

# ── Edge archetypes ────────────────────────────────────────────────────────
# A diagnostic check depends on one or more other checks; the edge carries
# the dependency relationship with an optional hard/soft flag.
edge DependsOn {
    has hard: bool = True;
}

# ── Node archetypes ────────────────────────────────────────────────────────
# A policy store hosts a set of diagnostic checks (root container).
node PolicyStore {
    has name: str = "";
}

# A diagnostic check that may depend on other checks. The result and tier
# fields are the payload the doctor walk reports up.
node DiagnosticCheck {
    has label: str = "";
    has tier: str = "advisory";
    has result: str = "pass";
    has visited: bool = False;
    has order: int = 0;
}

# ── Walkers ────────────────────────────────────────────────────────────────
# Doctor: traverses DependsOn edges depth-first, recording the post-order
# execution plan on each visited check. Uses an explicit visited set on the
# walker so cycles cannot loop forever (the SIGSEVG-shaped bug we are
# modeling: recursion with no guard).
walker Doctor {
    has plan: list[str] = [];
    has visited: list[DiagnosticCheck] = [];

    can start with Root entry {
        visit [-->(?:PolicyStore)];
    }

    can plan_store with PolicyStore entry {
        # Fan out to every check directly attached to the store.
        visit [-->(?:DiagnosticCheck)];
    }

    can plan_check with DiagnosticCheck entry {
        # Cycle guard: if we have already entered this node, skip.
        if here in self.visited {
            report f"cycle detected at {here.label}";
            return;
        }
        self.visited.append(here);
        here.visited = True;
        # First visit all dependencies (post-order), then record self.
        children = [-->(?:DiagnosticCheck)];
        if children.length > 0 {
            visit [-->];
        }
        self.plan.append(here.label);
        here.order = self.plan.length;
    }
}

# CycleHunter: dedicated cycle detector. Walks DependsOn edges with an
# explicit stack so cycles are reported, not infinite-looped.
walker CycleHunter {
    has stack: list[DiagnosticCheck] = [];
    has cycles: list[str] = [];

    can start with Root entry {
        visit [-->(?:PolicyStore)];
    }

    can enter_store with PolicyStore entry {
        visit [-->(?:DiagnosticCheck)];
    }

    can enter_check with DiagnosticCheck entry {
        if here in self.stack {
            cycle_label = f"cycle through {here.label}";
            self.cycles.append(cycle_label);
            report cycle_label;
            disengage;
        }
        self.stack.append(here);
        visit [-->(?:DiagnosticCheck)];
        # Pop only if we did not disengage mid-walk.
        if self.stack.length > 0 and self.stack[-1].label == here.label {
            self.stack.pop();
        }
    }
}

# CascadePurger: invalidates every reachable check from a store. Models the
# cascade-delete traversal that the issue's "N+1 query loops" complaint
# would map onto.
walker CascadePurger {
    can start with Root entry {
        visit [-->(?:PolicyStore)];
    }

    can purge_store with PolicyStore entry {
        visit [-->(?:DiagnosticCheck)];
    }

    can purge_check with DiagnosticCheck entry {
        report f"invalidating {here.label} (tier={here.tier}, result={here.result})";
        visit [-->(?:DiagnosticCheck)];
    }
}

# ── Demo wiring ────────────────────────────────────────────────────────────
with entry {
    # Build a tiny policy store with a realistic dependency chain. The
    # depth mirrors what the Rust issue describes as the recursion culprit.
    store = PolicyStore(name="doctor-render");
    root ++> store;

    c0 = DiagnosticCheck(label="boot_config", tier="critical", result="pass");
    c1 = DiagnosticCheck(label="auth_store", tier="critical", result="pass");
    c2 = DiagnosticCheck(label="security_profile", tier="warning", result="pass");
    c3 = DiagnosticCheck(label="swarm_slo", tier="advisory", result="pass");
    c4 = DiagnosticCheck(label="render_concise", tier="advisory", result="pass");
    c5 = DiagnosticCheck(label="render_json", tier="advisory", result="pass");

    store ++> c0 ++> c1 ++> c2 ++> c3 ++> c4 ++> c5;

    # Typed edge: c5 has a soft dependency back on c2 (advisory summary).
    c5 +>:DependsOn(hard=False):+> c2;

    # ── 1. Doctor walk: produce an execution plan ──────────────────────
    doc = Doctor();
    root spawn doc;
    print("Doctor execution plan (post-order):");
    for step in doc.plan {
        print(f"  {step}");
    }

    # ── 2. CycleHunter walk: prove the cycle guard works ──────────────
    # Inject a cycle: c5 already depends on c2; add c2 -> c5 to close it.
