"""Tests for daily student attendance walker — sis-v2 wayfinder #111."""

import io;
import from contextlib { redirect_stdout }

test "late counts as present for the figure" {
    root ++> Student(name="X") +>:MarkedOn(date="2026-03-04"):+> AttendanceMark(
        status="late", marked_by="t1", counts_as_present=True, date="2026-03-04"
    );
    root ++> Student(name="Y") +>:MarkedOn(date="2026-03-04"):+> AttendanceMark(
        status="absent", marked_by="t1", counts_as_present=False, date="2026-03-04"
    );

