    assert auditor.absent_total == 1, f"absent should be 1, got {auditor.absent_total}";
}

test "present mark increments present tally only" {
    root ++> Student(name="P") +>:MarkedOn(date="2026-03-04"):+> AttendanceMark(
        status="present", marked_by="t1", counts_as_present=True, date="2026-03-04"
