node Routine {
    has name: str = "";
    has version: int = 0;
    has current: bool = True;
    has summary: str = "";
    has invalidated: bool = False;
}

node CallSite {
    has name: str = "";
    has context: str = "scalar";
    has observed_version: int = 0;
    has callee_version: int = 0;
    has depth: int = 0;
    has exact: bool = True;
    has bounded: bool = True;
}

edge Owns {
    has ordinal: int = 0;
}

edge Calls {
    has context: str = "";
}

