    has reason: str = "";
}

walker SemanticComposer {
    has max_depth: int = 2;
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Routine entry {
        if (here.name in self.seen) {
            print(f"cycle guard stopped at {here.name}");
        } else {
            self.seen.append(here.name);
            print(f"summary {here.name} v{here.version}: {here.summary}");
            visit [->:Owns:->] else {
                disengage;
            }
        }
