}

# --------------------------- auditor walker --------------------------------

walker DiagnosticAuditor {
    has findings: list = [];
    has visited: list = [];

    can start with Project entry {
        self.visited.append(here.name);
        print(f"audit: project {here.name} mode={here.network_mode}");
        # First visit the networks owned by the project (typed edge).
        visit [->:Owns:->];
    }

    # Union trigger: same audit step for Service and Dependency so we touch
    # only fields shared by both (Finding-bearing node categories).
    can audit_artifact with Service | Dependency entry {
        label = here.title;
        findings = self.findings;

        # --- restart loop with real blocking error ---
        if label and here.restart_count >= 3 {
            findings.append(
                Finding(
                    category="restart_loop",
                    severity="error",
                    evidence=f"{label} restarted {here.restart_count}x",
                )
            );
        }

        # --- stale fatal in pre-restart history ---
        if label and here.stale_fatal_in_history {
            findings.append(
                Finding(
                    category="stale_fatal",
                    severity="info",
                    evidence=f"{label} history contains pre-restart fatal",
                )
            );
        }

        # --- HTTP behavior: 4xx / 5xx flagged ---
        if here.http_status >= 500 {
            findings.append(
                Finding(
                    category="http_5xx",
                    severity="error",
                    evidence=f"{label} HTTP {here.http_status}",
                )
            );
        } elif here.http_status >= 400 {
            findings.append(
                Finding(
                    category="http_4xx",
                    severity="warn",
                    evidence=f"{label} HTTP {here.http_status}",
                )
            );
        }

        # --- Host / Origin sensitivity regression scenarios ---
        if here.host_sensitive {
            findings.append(
                Finding(
                    category="host_header",
                    severity="warn",
                    evidence=f"{label} is host-sensitive",
                )
            );
        }
        if here.origin_sensitive {
            findings.append(
                Finding(
                    category="origin_header",
                    severity="warn",
                    evidence=f"{label} is origin-sensitive",
                )
            );
        }

        # --- dependency status (Reachable / Refused / TimedOut / DnsFailure) ---
        if here.status == "Refused" {
            findings.append(
                Finding(
                    category="tcp_refused",
                    severity="error",
                    evidence=f"dep {label} refused",
                )
            );
        } elif here.status == "TimedOut" {
            findings.append(
                Finding(
                    category="tcp_timeout",
                    severity="error",
                    evidence=f"dep {label} timed out",
                )
            );
        } elif here.status == "DnsFailure" {
            findings.append(
                Finding(
                    category="dns_resolution",
                    severity="error",
                    evidence=f"dep {label} DNS failed",
                )
            );
        } elif here.status == "Missing" {
            findings.append(
                Finding(
                    category="missing_dependency",
                    severity="error",
                    evidence=f"dep {label} missing",
                )
            );
        }

        visit [->:DependsOn:->];
    }

    can collect with Network entry {
        self.visited.append(here.name);
        print(f"audit: network {here.name}");
        visit [-->];
    }

    can finalize with Root entry {
        print(f"audit: complete, {len(self.findings)} findings");
        for f in self.findings {
            print(f"  [{f.severity}] {f.category}: {f.evidence}");
        }
        report self.findings;
    }
}

