"""Job cascade reachability: model a parent_id job chain and walk it with a
walker to surface the grandchild-stuck-waiting bug the raw-SQL cascade has.

Three jobs form a chain A -> B -> C (each has a parent_id pointing at the
previous). A reclaim-exhausted cascade that only follows direct parent_id
children would mark B failed but leave C waiting. The walker here walks the
entire reachable subtree (with an explicit cycle guard, since walkers in
jac 0.36.1 have no built-in once-per-node visitation) and reports every
job's resolved state, exposing the grandchild that the raw cascade misses.
"""

node Job {
    has name: str = "";
    has state: str = "waiting";   # waiting | running | done | failed | cancelled
    has attempts: int = 0;

    def is_terminal() -> bool {
        return self.state == "done"
            or self.state == "failed"
            or self.state == "cancelled";
    }
}

# Typed edge carries the parent_id relationship between jobs.
edge SpawnedBy {
    has weight: int = 1;
}

# Walker that follows the SpawnedBy chain forward from a starting job
# and reports each descendant's state. Uses an explicit visited set on
# `has` because jac walkers do not dedupe cycles natively.
walker CascadeReach {
    has seen: list[str] = [];
    has report_lines: list[str] = [];
    has dead_end: bool = False;

    can start with Job entry {
        self.seen.append(here.name);
        line = f"{here.name}: {here.state} (attempts={here.attempts})";
        self.report_lines.append(line);
        # Continue down the chain via the SpawnedBy edge.
        visit [->:SpawnedBy:->] else {
            self.dead_end = True;
            disengage;
        }
    }

    can descend with Job entry {
        # Cycle guard: if we have already reported this job, stop the walk
        # along this branch rather than looping.
        if here.name in self.seen {
            self.report_lines.append(f"{here.name}: cycle-broken");
            disengage;
        }
        self.seen.append(here.name);
        line = f"{here.name}: {here.state} (attempts={here.attempts})";
        self.report_lines.append(line);
        visit [->:SpawnedBy:->] else {
            disengage;
        }
    }
}

