    d = Job(name="D", state="waiting");

    root ++> a;
    a +>:Parent(order=0):+> b;
    b +>:Parent(order=1):+> c;
    b +>:Parent(order=2):+> d;

    cascade = Cascade();
    root spawn cascade;

    assert c.state == "failed", f"grandchild C must be failed before reaper runs, got {c.state}";
    assert d.state == "failed", f"grandchild D must be failed before reaper runs, got {d.state}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Propagate();
    }
    out = buf.getvalue();

    assert "reaping failed job A" in out, f"A should be reaped, got: {out}";
    assert "reaping failed job B" in out, f"B should be reaped, got: {out}";
    assert "reaping failed job C" in out, f"C (grandchild) should be reaped, got: {out}";
    assert "reaping failed job D" in out, f"D (grandchild) should be reaped, got: {out}";
}

