"""Regression tests for the streaming transcript pipeline demo."""

import io;
import from contextlib { redirect_stdout }


# ---------- Shared helpers ----------------------------------------------------

def build_pipeline(history: list, streaming_tail: object) -> tuple {
    blocks = Blocks();
    merged = MergedMessages();
    display = DisplayItems();
    visible = VisibleItems();

    # Chain pipeline stages.
    blocks +>:Feeds:+> merged +>:Feeds:+> display +>:Feeds:+> visible;

    # Attach the full transcript under every stage.
    for m in history {
        blocks ++> m;
        merged ++> m;
        display ++> m;
        visible ++> m;
    }
    blocks ++> streaming_tail;
    merged ++> streaming_tail;
    display ++> streaming_tail;
    visible ++> streaming_tail;

    return (blocks, merged, display, visible);
}


# ---------- Tests -------------------------------------------------------------

test "full pipeline visits all four stages in order" {
    history = [
        Message(role="user", content="hi", tokens=2),
        Message(role="assistant", content="hello", tokens=3),
    ];
    tail = Message(role="assistant", content="typing", tokens=1);

    (blocks, merged, display, visible) = build_pipeline(history, tail);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = blocks spawn FullPipelineReprocess(stream_delta="+1tok");
    }
    # No printing should be observed from the walker itself; the print in
    # the demo `with entry` block is NOT executed under `jac test`.
    assert buf.getvalue() == "", f"walker should not print, got {buf.getvalue()}";

    # The walker must traverse blocks -> merged -> display -> visible.
    assert res.stages_visited == ["blocks", "merged", "display", "visible"], (
        f"stages in order, got {res.stages_visited}"
    );

    # Work is summed at each of the 4 stages over the full transcript
    # (history + 1 streaming tail = 3 messages) with tokens 2+3+1=6 each time.
    expected = (2 + 3 + 1) * 4;
    assert res.work_per_stage == expected, (
        f"work_per_stage={res.work_per_stage}, expected {expected}"
    );
}

test "tail-only walker mutates only the last message" {
    history = [
        Message(role="user", content="hi", tokens=2),
        Message(role="assistant", content="hello", tokens=3),
        Message(role="user", content="explain graphs", tokens=4),
        Message(role="assistant", content="sure", tokens=5),
    ];
    tail = Message(role="assistant", content="typing", tokens=1);

    (blocks, merged, display, visible) = build_pipeline(history, tail);

    # Snapshot every message's content before the walker runs.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = blocks spawn TailOnlyAppend();
    }
    assert buf.getvalue() == "", f"walker should not print, got {buf.getvalue()}";

    assert res.appended_to_tail is True, "tail append must be flagged true";

    # The streaming tail under blocks is the one referenced by every stage
    # (it's a single object shared via the helper). Verify it grew by +1tok
    # and exactly one token was added to its token count.
    tail_msgs = [blocks -->][?:Message];
    assert len(tail_msgs) >= 1, "tail must be present under blocks";
    last = tail_msgs[-1];
    assert last.content == "typing+1tok", f"tail content={last.content}";
    assert last.tokens == 2, f"tail tokens={last.tokens}";

    # And a history entry was left alone (structural sharing: unchanged
    # prefixes must keep their identity/content).
    first = tail_msgs[0];
    assert first.content == "hi", f"first message must be untouched, got {first.content}";
    assert first.tokens == 2, f"first message tokens={first.tokens}";
}

test "pipeline is a linear chain via typed Feeds edges" {
    history = [Message(role="user", content="hi", tokens=2)];
    tail = Message(role="assistant", content="typing", tokens=1);

    (blocks, merged, display, visible) = build_pipeline(history, tail);

    # Each stage points to exactly one next stage via a Feeds edge.
    assert len([blocks ->:Feeds:->]) == 1, "blocks must have exactly one Feeds edge";
    assert len([merged ->:Feeds:->]) == 1, "merged must have exactly one Feeds edge";
    assert len([display ->:Feeds:->]) == 1, "display must have exactly one Feeds edge";
    assert len([visible ->:Feeds:->]) == 0, "visible is terminal (no outgoing Feeds)";

    # And the chain follows the expected order.
    assert [blocks ->:Feeds:->][0] == merged, "blocks -> merged";
    assert [merged ->:Feeds:->][0] == display, "merged -> display";
    assert [display ->:Feeds:->][0] == visible, "display -> visible";
}

test "full pipeline work scales with transcript length" {
    # Build a transcript of 6 history messages + 1 tail = 7 messages.
    history = [
        Message(role="user", content="a", tokens=1),
        Message(role="assistant", content="b", tokens=2),
        Message(role="user", content="c", tokens=3),
        Message(role="assistant", content="d", tokens=4),
        Message(role="user", content="e", tokens=5),
        Message(role="assistant", content="f", tokens=6),
    ];
    tail = Message(role="assistant", content="typing", tokens=1);

    (blocks, merged, display, visible) = build_pipeline(history, tail);

    res = blocks spawn FullPipelineReprocess(stream_delta="+1tok");

    # 4 stages * sum-of-tokens(1..6 + 1) = 4 * (21 + 1) = 88 token-units.
    token_sum = 1 + 2 + 3 + 4 + 5 + 6 + 1;
    expected = token_sum * 4;
    assert res.work_per_stage == expected, (
        f"work_per_stage={res.work_per_stage}, expected {expected} "
        f"(4 stages * {token_sum} tokens)"
    );

    # Each stage was visited exactly once.
    assert res.stages_visited == ["blocks", "merged", "display", "visible"], (
        f"stages_visited={res.stages_visited}"
    );
    assert len(res.stages_visited) == 4, (
        f"expected 4 stage visits, got {len(res.stages_visited)}"
    );
}

