fixed.code:
"""Workplane M2E: fixed work-item lifecycle and dependency DAG.

Models the essential scenario from the issue as a small OSP graph:
work items belong to projects, projects belong to organizations, and
work items are linked by typed dependency edges (blocks / relates /
caused-by). A walker validates a proposed dependency add against the
fixed lifecycle, derives blocking from unresolved `blocks` edges, and
detects blocking cycles before commit. Only `blocks` participates in
cycle detection.
"""

node Organization {
    has name: str = "";
}

node Project {
    has code: str = "";
}

node WorkItem {
    has title: str = "";
    has state: str = "open";
    has version: int = 1;
    has blocked: bool = False;

    def is_terminal() -> bool {
        return self.state == "done" or self.state == "cancelled";
    }

    def can_transition_to(target: str) -> bool {
        if self.is_terminal() {
            return False;
        }
        if target == "in_progress" {
            return self.state == "open" or self.state == "in_review";
        }
        if target == "in_review" {
            return self.state == "in_progress";
        }
        if target == "done" {
            return self.state == "in_review";
        }
        if target == "cancelled" {
            return self.state != "done" and self.state != "cancelled";
        }
        return False;
    }
}

edge BelongsTo {
    has org_code: str = "";
}

edge Blocks {
}

edge Relates {
}

edge CausedBy {
}

walker DependencyAuditor {
    has proposed_target: str = "";
    has proposed_kind: str = "blocks";
    has visited_titles: list[str] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can begin with WorkItem entry {
        self.visited_titles = self.visited_titles + [here.title];
        if self.proposed_kind == "blocks" {
            self.cycle_found = self.proposed_target in self.visited_titles;
        }
        if self.cycle_found {
            print(
                f"REJECTED dependency_cycle: {here.title} --[{self.proposed_kind}]--> "
                f"{self.proposed_target}"
            );
        } else {
            verdict = "accepted";
            status = "BLOCKED" if here.blocked else "CLEAR";
            print(
                f"{verdict}: {here.title} ({status}, state={here.state}, "
                f"version={here.version}) + {self.proposed_kind} -> {self.proposed_target}"
            );
        }
        visit [-->] else { disengage; }
    }
}

with entry {
    acme = Organization(name="Acme");
    core = Project(code="CORE");
    edge_proj = Project(code="EDGE");

    wi_open = WorkItem(title="WI-1: spec", state="open", version=1);
    wip = WorkItem(title="WI-2: impl", state="in_progress", version=2);
    review = WorkItem(title="WI-3: review", state="in_review", version=1);
    done = WorkItem(title="WI-4: ship", state="done", version=4);

    cascade = WorkItem(title="WI-5: cascade", state="open", version=1);
    head_node = WorkItem(title="WI-6: head", state="in_review", version=3);

    acme +>:BelongsTo(org_code="Acme"):+> core;
    acme +>:BelongsTo(org_code="Acme"):+> edge_proj;

    core ++> wi_open;
    core ++> wip;
    core ++> review;
    core ++> done;

    edge_proj ++> cascade;
    edge_proj ++> head_node;

    wi_open +>:Blocks:+> wip;
    wip +>:Blocks:+> review;
    review +>:Blocks:+> done;

    cascade +>:Blocks:+> head_node;

    wi_open.blocked = True;
    cascade.blocked = True;

    print("=== Lifecycle transitions ===");
    print(f"  WI-1 open->in_progress: {wi_open.can_transition_to('in_progress')}");
    print(f"  WI-1 open->done: {wi_open.can_transition_to('done')}");
    print(f"  WI-2 in_progress->in_review: {wip.can_transition_to('in_review')}");
    print(f"  WI-3 in_review->done: {review.can_transition_to('done')}");
    print(f"  WI-4 done->in_progress: {done.can_transition_to('in_progress')}");

    print("");
    print("=== Cross-project blocks edge (allowed within org) ===");
    cascade +>:Blocks:+> wi_open;

    print("");
    print("=== Audit: legal blocks add ===");
    root spawn DependencyAuditor(
        proposed_target="WI-2: impl", proposed_kind="blocks"
    );

    print("");
    print("=== Audit: relates edge never triggers cycle failure ===");
    root spawn DependencyAuditor(
        proposed_target="WI-4: ship", proposed_kind="relates"
    );

    print("");
    print("=== Audit: self-cycle on a blocks edge (rejected) ===");
    root spawn DependencyAuditor(
        proposed_target="WI-2: impl", proposed_kind="blocks"
    );

    print("");
    print("=== Derived blocking (never persisted as state) ===");
    for wi in [wi_open, wip, review, done, cascade, head_node] {
        badge = "BLOCKED" if wi.blocked else "CLEAR";
        print(f"  {badge}: {wi.title} state={wi.state}");
    }
}

fixed.jac_tests:
"""Regression tests for Workplane M2E lifecycle + dependency DAG.

Exercises the behaviors the issue promises:
- fixed lifecycle transitions (open->in_progress->in_review->done, plus
  in_review->in_progress bounce and cancellation from nonterminal states)
- blocking is never persisted as state, only derived from unresolved
  Blocks edges (set via the `blocked` has flag in the fixture)
- typed dependency edges: Blocks / Relates / CausedBy
- only Blocks participates in cycle detection (self-cycle rejected;
  relates edge to a visited target is NOT rejected)
- DependencyAuditor prints REJECTED dependency_cycle when its proposed
  target appears in visited work-item titles and the kind is blocks
"""

import io;
import from contextlib { redirect_stdout }

test "lifecycle allows open to in_progress but not open to done" {
    root ++> WorkItem(title="A", state="open", version=1);
    a = [root -->][0];
    assert a.can_transition_to("in_progress"), "open must allow in_progress";
    assert not a.can_transition_to("done"), "open must NOT skip directly to done";
    assert not a.can_transition_to("in_review"), "open must NOT skip in_review";
    assert a.can_transition_to("cancelled"), "open must allow cancellation";
}

test "lifecycle bounce from in_review back to in_progress is allowed" {
    root ++> WorkItem(title="B", state="in_review", version=1);
    b = [root -->][0];
    assert b.can_transition_to("in_progress"), "in_review->in_progress must be allowed (bounce)";
    assert b.can_transition_to("done"), "in_review->done must be allowed";
    assert not b.can_transition_to("open"), "in_review must NOT go back to open";
}

test "terminal states reject all further transitions including cancellation" {
    root ++> WorkItem(title="D", state="done", version=4);
    d = [root -->][0];
    assert d.is_terminal(), "done is terminal";
    assert not d.can_transition_to("in_progress"), "done must reject in_progress";
    assert not d.can_transition_to("in_review"), "done must reject in_review";
    assert not d.can_transition_to("cancelled"), "done must reject cancelled (terminal)";

    root ++> WorkItem(title="X", state="cancelled", version=1);
    x = [root -->][1];
    assert x.is_terminal(), "cancelled is terminal";
    assert not x.can_transition_to("in_progress"), "cancelled must reject in_progress";
}

test "dependency auditor rejects self blocking cycle on blocks edges" {
    root ++> WorkItem(title="WI-2: impl", state="in_progress", version=2);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DependencyAuditor(
            proposed_target="WI-2: impl",
            proposed_kind="blocks"
        );
    }
    out = buf.getvalue();
    assert "REJECTED dependency_cycle" in out, f"blocks self-cycle must be rejected, got: {out}";
    assert res.cycle_found, "cycle_found flag must be set for blocks self-cycle";
}

test "dependency auditor does not reject relates edges even when target is visited" {
    root ++> WorkItem(title="WI-4: ship", state="done", version=4);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DependencyAuditor(
            proposed_target="WI-4: ship",
            proposed_kind="relates"
        );
    }
    out = buf.getvalue();
    assert "REJECTED dependency_cycle" not in out, f"relates must never trigger cycle failure, got: {out}";
    assert not res.cycle_found, "cycle_found must stay False for relates kind";
}

test "typed edges: Blocks Relates CausedBy are all distinct edge archetypes" {
    root ++> WorkItem(title="src", state="open", version=1);
    root ++> WorkItem(title="dst", state="open", version=1);
    src = [root -->][0];
    dst = [root -->][1];
    src +>:Blocks:+> dst;
    src +>:Relates:+> dst;
    src +>:CausedBy:+> dst;
    blocks_targets = [src ->:Blocks:->];
    relates_targets = [src ->:Relates:->];
    caused_targets = [src ->:CausedBy:->];
    assert len(blocks_targets) == 1, "exactly one Blocks edge must exist";
    assert len(relates_targets) == 1, "exactly one Relates edge must exist";
    assert len(caused_targets) == 1, "exactly one CausedBy edge must exist";
    assert dst in blocks_targets, "Blocks edge must point to dst";
    assert dst in relates_targets, "Relates edge must point to dst";
    assert dst in caused_targets, "CausedBy edge must point to dst";
}

test "blocking is derived not persisted as a state value" {
    root ++> WorkItem(title="blocked_one", state="open", version=1, blocked=True);
    wi = [root -->][0];
    assert wi.blocked is True, "blocked flag is the derived signal";
    assert wi.state == "open", "blocked must NEVER replace the persisted state";
    assert wi.state != "blocked", "blocked must never appear as a work-item state value";
    assert wi.can_transition_to("in_progress"), "blocked-open item must still be transitionable";
}

