"""Test annex for the DSC resource dependency resolver (issue #23).

Verifies the Kahn-style topological sort walker over a typed Requires edge
graph: linear chain ordering, diamond ordering, fan-in ordering, cycle
detection (with cycle members named), and missing-reference detection.
"""
import io;
import from contextlib { redirect_stdout }

# ---------- helpers ----------

def build_chain() -> tuple {
    a = Resource(name="A");
    b = Resource(name="B", depends_on=["A"]);
    c = Resource(name="C", depends_on=["B"]);
    d = Resource(name="D", depends_on=["C"]);
    a +>:Requires:+> b;
    b +>:Requires:+> c;
    c +>:Requires:+> d;
    return (a, b, c, d);
}

def build_diamond() -> tuple {
    a = Resource(name="A");
    b = Resource(name="B", depends_on=["A"]);
    c = Resource(name="C", depends_on=["A"]);
    d = Resource(name="D", depends_on=["B", "C"]);
    a +>:Requires:+> b;
    a +>:Requires:+> c;
    b +>:Requires:+> d;
    c +>:Requires:+> d;
    return (a, b, c, d);
}

def build_fan_in() -> list {
    leaves = [Resource(name=f"L{i}") for i in range(5)];
    mid = Resource(name="Mid", depends_on=["L0", "L1", "L2", "L3", "L4"]);
    sink = Resource(name="Sink", depends_on=["Mid"]);
    for leaf in leaves {
        leaf +>:Requires:+> mid;
    }
    mid +>:Requires:+> sink;
    return leaves + [mid, sink];
}

def build_cycle() -> tuple {
    a = Resource(name="A", depends_on=["C"]);
    b = Resource(name="B", depends_on=["A"]);
    c = Resource(name="C", depends_on=["B"]);
    a +>:Requires:+> b;
    b +>:Requires:+> c;
    c +>:Requires:+> a;
    return (a, b, c);
}

def build_missing() -> tuple {
    a = Resource(name="A");
    b = Resource(name="B", depends_on=["Ghost"]);
    a +>:Requires:+> b;
    return (a, b);
}

# ---------- tests ----------

test "linear chain emits topological order A B C D" {
    (a, b, c, d) = build_chain();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DependencyResolver(remaining=[a, b, c, d]);
    }
    out = buf.getvalue();
    assert "topo order:" in out, f"expected success line, got: {out}";
    assert "ERROR" not in out, f"unexpected error in linear chain: {out}";
    assert res.order == ["A", "B", "C", "D"], f"got order {res.order}";
    assert res.cycle_members == [], f"got cycle_members {res.cycle_members}";
    assert res.known_names == ["A", "B", "C", "D"], f"got known {res.known_names}";
}

test "diamond: A before B and C, both before D" {
    (a, b, c, d) = build_diamond();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DependencyResolver(remaining=[a, b, c, d]);
    }
    out = buf.getvalue();
    assert "topo order:" in out, f"expected success line, got: {out}";
    assert "ERROR" not in out, f"unexpected error in diamond: {out}";
    o = res.order;
    assert len(o) == 4, f"expected 4 resources ordered, got {o}";
    assert o[0] == "A", f"A must be first, got {o[0]}";
    assert o[-1] == "D", f"D must be last, got {o[-1]}";
    assert "B" in o and "C" in o, f"B and C missing from {o}";
    a_idx = o.index("A");
    b_idx = o.index("B");
    c_idx = o.index("C");
    d_idx = o.index("D");
    assert a_idx < b_idx, f"A must precede B: {o}";
    assert a_idx < c_idx, f"A must precede C: {o}";
    assert b_idx < d_idx, f"B must precede D: {o}";
    assert c_idx < d_idx, f"C must precede D: {o}";
    assert res.cycle_members == [], f"got cycle_members {res.cycle_members}";
}

test "wide fan-in: all leaves before Mid, Mid before Sink" {
    nodes = build_fan_in();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DependencyResolver(remaining=nodes);
    }
    out = buf.getvalue();
    assert "topo order:" in out, f"expected success line, got: {out}";
    assert "ERROR" not in out, f"unexpected error in fan-in: {out}";
    o = res.order;
    assert len(o) == 7, f"expected 7 ordered, got {o}";
    mid_idx = o.index("Mid");
    sink_idx = o.index("Sink");
    for i in range(5) {
        leaf_name = f"L{i}";
        assert leaf_name in o, f"leaf {leaf_name} missing from {o}";
        assert o.index(leaf_name) < mid_idx, f"{leaf_name} must precede Mid: {o}";
    }
    assert mid_idx < sink_idx, f"Mid must precede Sink: {o}";
    assert res.cycle_members == [], f"got cycle_members {res.cycle_members}";
}

test "cycle: names the resources caught in the loop" {
    (a, b, c) = build_cycle();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DependencyResolver(remaining=[a, b, c]);
    }
    out = buf.getvalue();
    assert "ERROR: Dependency cycle" in out, f"expected cycle error, got: {out}";
    assert "topo order:" not in out, f"unexpected success line in cycle case: {out}";
    assert len(res.cycle_members) == 3, f"expected 3 cycle members, got {res.cycle_members}";
    assert "A" in res.cycle_members, f"A missing from cycle members {res.cycle_members}";
    assert "B" in res.cycle_members, f"B missing from cycle members {res.cycle_members}";
    assert "C" in res.cycle_members, f"C missing from cycle members {res.cycle_members}";
    assert len(res.order) < 3, f"cycle case should not fully resolve, got {res.order}";
}

test "missing reference: names the unknown dependency" {
    (a, b) = build_missing();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DependencyResolver(remaining=[a, b]);
    }
    out = buf.getvalue();
    assert "unknown resource" in out, f"expected missing-ref error, got: {out}";
    assert "Ghost" in out, f"unknown name 'Ghost' not reported: {out}";
    assert "B" in out, f"dependent resource 'B' not named: {out}";
}

fixed.code:
"""MCP stdio server cold-start deadline race.

Models the scenario from the bug report: Claude Desktop launches a stdio
MCP server through a package runner (e.g. uvx). The runner must first
download and install dependencies (botocore, etc.) before the actual
server process exists. A hardcoded 60 s deadline on the initialize
handshake cancels the request before the runner finishes, so the
fully-functional server is left unreachable.

Three entity archetypes capture the moving parts:

* Desktop      — the host application (Claude Desktop) that owns the
  hardcoded 60 s deadline and discards late servers.
* McpServer    — a configured server slot from claude_desktop_config.json.
* Launcher     — a package runner (uvx, npx, pipx run) that assembles
  the environment before execing the real binary.
* Backend      — the actual MCP server process; only exists once the
  dependency download finishes.

Relationships:

* Configured — desktop -> server slot (carries config fields).
* RunsVia    — server slot -> launcher (the launcher chosen in config).
* Spawns     — launcher -> backend (only after env is resolved).

Two walkers demonstrate the failure mode and a possible recovery:

* DeadlineRacer — walks Configured -> RunsVia -> Spawns and reports
  which stage each server reached when the 60 s budget runs out.
* LateAttacher — walks the chain looking for backends that appeared
  after the deadline and reports them as reachable but orphaned
  (mirroring the "retry / late attach" expectation in the issue).
"""

node Desktop {
    has host_name: str = "ClaudeDesktop";
    has init_deadline_s: int = 60;
}

node McpServer {
    has title: str = "";
    has launcher_cmd: str = "";
    has deps: str = "";
    has deadline_hit: bool = False;
    has stage_reached: str = "spawning";
}

node Launcher {
    has runner: str = "";
    has cold_start_s: int = 0;
    has downloaded: bool = False;
}

node Backend {
    has process_name: str = "";
    has tools_exposed: int = 0;
    has reachable: bool = False;
}

edge Configured { has config_key: str = ""; }
edge RunsVia { }
edge Spawns { has pid: int = 0; }

walker DeadlineRacer {
    has deadline_s: int = 60;

    can start with Desktop entry {
        print(f"Desktop {here.host_name} enforces {here.init_deadline_s}s init deadline");
        visit [->:Configured:->];
    }

    can race with McpServer entry {
        server = here;
        launcher_nodes = [here->:RunsVia:->];
        if not launcher_nodes {
            server.stage_reached = "no-launcher";
            server.deadline_hit = True;
            print(f"  [{server.title}] no launcher configured");
            visit [->:Configured:->];
            disengage;
        }
        launcher = launcher_nodes[0];
        if launcher.cold_start_s > self.deadline_s {
            server.deadline_hit = True;
            server.stage_reached = "downloading";
            print(f"  [{server.title}] cancelled at {self.deadline_s}s while {launcher.runner} was resolving {server.deps}");
        } else {
            server.stage_reached = "backend-ready";
            print(f"  [{server.title}] backend ready in {launcher.cold_start_s}s");
        }
        visit [->:Configured:->];
    }
}

walker LateAttacher {
    can start with Desktop entry {
        print(f"Late attach pass: checking for backends that came up after the deadline");
        visit [->:Configured:->];
    }

    can find with McpServer entry {
        launcher_nodes = [here->:RunsVia:->];
        if launcher_nodes {
            backend_nodes = [launcher_nodes[0]->:Spawns:->];
            if here.deadline_hit and backend_nodes {
                backend = backend_nodes[0];
                backend.reachable = False;
                print(f"  [orphan] {here.title}: {backend.process_name} is up with {backend.tools_exposed} tools but unreachable");
            }
        }
        visit [->:Configured:->];
    }
}

with entry {
    desktop = Desktop(host_name="ClaudeDesktop", init_deadline_s=60);
    root ++> desktop;

    # Server 1: cold start inside the 60 s window — works fine.
    s1 = McpServer(title="weather", launcher_cmd="uvx weather-mcp", deps="httpx");
    desktop +>:Configured(config_key="weather"):+> s1;
    l1 = Launcher(runner="uvx", cold_start_s=20, downloaded=True);
    s1 +>:RunsVia:+> l1;
    b1 = Backend(process_name="weather-mcp", tools_exposed=4, reachable=True);
    l1 +>:Spawns(pid=4101):+> b1;

    # Server 2: cold start exceeds 60 s — matches the bug report.
    s2 = McpServer(title="opensearch", launcher_cmd="uvx opensearch-mcp-server-py", deps="botocore,boto3");
    desktop +>:Configured(config_key="opensearch"):+> s2;
    l2 = Launcher(runner="uvx", cold_start_s=110, downloaded=True);
    s2 +>:RunsVia:+> l2;
    b2 = Backend(process_name="opensearch-mcp-server-py", tools_exposed=7, reachable=True);
    l2 +>:Spawns(pid=4102):+> b2;

    # Server 3: another over-budget cold start, no backend ever spawned.
    s3 = McpServer(title="metrics", launcher_cmd="uvx metrics-mcp", deps="numpy,scipy");
    desktop +>:Configured(config_key="metrics"):+> s3;
    l3 = Launcher(runner="uvx", cold_start_s=140, downloaded=False);
    s3 +>:RunsVia:+> l3;

    desktop spawn DeadlineRacer(deadline_s=60);
    desktop spawn LateAttacher();
}

