"""Regression tests for the NexaChat #210 desktop-dependency demo.

Covers:
  - Auditor flags the vulnerable glib 0.18.5 reachable from desktop root.
  - Auditor flags unmaintained gtk and webkit2gtk chains.
  - Reachability probe reports glib reachable and records a path.
  - Auditor does not loop on cyclic dependencies and visits each crate once.
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# 1) Auditor flags the vulnerable glib 0.18.5 from desktop root.
# ---------------------------------------------------------------------------
test "auditor flags vulnerable glib 0.18.5 reachable from desktop root" {
    rt = Root();

    tauri = Crate(name="nexa-desktop", version="2.11.5");
    gtk = Crate(name="gtk", version="0.18.2");
    glib = Crate(name="glib", version="0.18.5", vulnerable=True);

    rt ++> tauri;
    tauri +>:DependsOn:+> gtk;
    gtk +>:DependsOn:+> glib;

    buf = io.StringIO();
    res = None;
    with redirect_stdout(buf) {
        res = rt spawn Auditor();
    }

    # glib must appear in findings exactly once.
    vuln_notes = [n for n in res.findings if n.startswith("VULN glib@")];
    assert len(vuln_notes) == 1, f"expected 1 VULN glib note, got {vuln_notes}";
    assert vuln_notes[0] == "VULN glib@0.18.5 reachable", f"got {vuln_notes[0]}";

    # tauri and gtk are not themselves flagged as vulnerable / unmaintained.
    for n in res.findings {
        assert not n.startswith("VULN nexa-desktop@"), f"tauri should not be VULN: {n}";
        assert not n.startswith("VULN gtk@"), f"gtk 0.18.2 should not be VULN: {n}";
    }

    # The walker visits every crate exactly once.
    assert sorted(res.visited) == ["glib", "gtk", "nexa-desktop"], f"visited={res.visited}";
}

# ---------------------------------------------------------------------------
# 2) Auditor flags unmaintained gtk and webkit2gtk chains.
# ---------------------------------------------------------------------------
test "auditor flags unmaintained gtk and webkit2gtk chains" {
    rt = Root();

    tauri = Crate(name="nexa-desktop", version="2.11.5");
    gtk = Crate(name="gtk", version="0.18.2", unmaintained=True);
    tauri_runtime = Crate(name="tauri-runtime-wry", version="2.11.5");
    wry = Crate(name="wry", version="2.11.5");
    tao = Crate(name="tao", version="2.11.5");
    webkit2gtk = Crate(name="webkit2gtk", version="2.11.5", unmaintained=True);

    rt ++> tauri;
    tauri +>:DependsOn:+> gtk;
    tauri +>:DependsOn:+> tauri_runtime;
    tauri_runtime +>:DependsOn:+> wry;
    wry +>:DependsOn:+> tao;
    tao +>:DependsOn:+> webkit2gtk;

    buf = io.StringIO();
    res = None;
    with redirect_stdout(buf) {
        res = rt spawn Auditor();
    }

    out = buf.getvalue();

    unmaintained_targets = sorted([
        n for n in res.findings if n.startswith("UNMAINTAINED ")
    ]);
    # Both gtk 0.18.2 and webkit2gtk 2.11.5 must surface; intermediate
    # crates (wry, tao, tauri-runtime-wry) must NOT.
    assert "UNMAINTAINED gtk@0.18.2 reachable" in unmaintained_targets, (
        f"missing gtk unmaintained note: {unmaintained_targets}"
    );
    assert "UNMAINTAINED webkit2gtk@2.11.5 reachable" in unmaintained_targets, (
        f"missing webkit2gtk unmaintained note: {unmaintained_targets}"
    );
    for n in unmaintained_targets {
        assert not n.startswith("UNMAINTAINED wry@"), f"wry should not be flagged: {n}";
        assert not n.startswith("UNMAINTAINED tao@"), f"tao should not be flagged: {n}";
        assert not n.startswith("UNMAINTAINED tauri-runtime-wry@"), (
            f"tauri-runtime-wry should not be flagged: {n}"
        );
    }

    # No vulnerable flags should appear in this graph.
    assert len([n for n in res.findings if n.startswith("VULN ")]) == 0, (
        f"unexpected VULN findings: {res.findings}"
    );

    # Every unmaintained crate is printed (stdout capture).
    assert "[OUT]UNMAINTAINED gtk@0.18.2 reachable" not in out, (
        f"stdout should not contain literal [OUT] marker: {out!r}"
    );
    assert "UNMAINTAINED gtk@0.18.2 reachable" in out, f"stdout missing gtk note: {out!r}";
    assert "UNMAINTAINED webkit2gtk@2.11.5 reachable" in out, (
        f"stdout missing webkit2gtk note: {out!r}"
    );
}

# ---------------------------------------------------------------------------
# 3) Reachability probe reports glib reachable and records path.
# ---------------------------------------------------------------------------
test "reachability probe reports glib reachable and records path" {
    rt = Root();

    tauri = Crate(name="nexa-desktop", version="2.11.5");
    gtk = Crate(name="gtk", version="0.18.2");
    glib = Crate(name="glib", version="0.18.5", vulnerable=True);

    rt ++> tauri;
    tauri +>:DependsOn:+> gtk;
    gtk +>:DependsOn:+> glib;

    buf = io.StringIO();
    probe = None;
    with redirect_stdout(buf) {
        probe = rt spawn ReachabilityProbe(target="glib");
    }

    assert probe.found is True, f"glib should be reachable, probe={probe.path}";
    assert probe.path == ["glib"], f"path should record target only, got {probe.path}";

    # A probe for a crate that does not exist must report not-found
    # and an empty path.
    buf2 = io.StringIO();
    miss = None;
    with redirect_stdout(buf2) {
        miss = rt spawn ReachabilityProbe(target="nonexistent-crate");
    }
    assert miss.found is False, f"missing target must report not found: {miss.path}";
    assert miss.path == [], f"path must stay empty on miss, got {miss.path}";
}

# ---------------------------------------------------------------------------
# 4) Auditor terminates on cyclic dependencies and visits each crate once.
# ---------------------------------------------------------------------------
test "auditor does not loop on cyclic dependency and visits each crate once" {
    rt = Root();

    a = Crate(name="crate-a", version="1.0.0");
    b = Crate(name="crate-b", version="1.0.0");
    c = Crate(name="crate-c", version="1.0.0", vulnerable=True);

    rt ++> a;
    a +>:DependsOn:+> b;
    b +>:DependsOn:+> c;
    c +>:DependsOn:+> a;  # cycle back to a

    buf = io.StringIO();
    res = None;
    with redirect_stdout(buf) {
        res = rt spawn Auditor();
    }

    # Each crate must be visited at most once.
    assert sorted(res.visited) == ["crate-a", "crate-b", "crate-c"], (
        f"visited mismatch (cycle not guarded): {res.visited}"
    );
    assert len(res.visited) == 3, f"expected 3 unique visits, got {res.visited}";

    # Only the vulnerable crate-c should be flagged.
    assert res.findings == ["VULN crate-c@1.0.0 reachable"], (
        f"unexpected findings on cyclic graph: {res.findings}"
    );
}

