"""Bench v9 generator spec: per-run ontology, compositional query programs,
independent renderers, and counterfactual/metamorphic families — modeled
as a graph where relationships between the latent state, the generated
records, and the query/answer surface are typed edges, and walkers do the
traversal that the issue's hand-rolled machinery used to do.

Walkers visit per-seed ontology/schema, walk recursive query programs,
enumerate renderer classes, and traverse counterfactual families. A cycle
guard (`seen`) keeps recursive query expansion from looping forever on
self-referential subqueries, mirroring the explicit cycle policy v9
requires (jac 0.36.1 walkers do not dedupe by default)."""

# ---------- entity archetypes ----------

node Ontology {
    # Per-run: entity types, relationships, fields, corrections, units, role depth.
    has seed_id: str = "";
    has entity_types: list[str] = [];
    has relationships: list[str] = [];
    has field_names: list[str] = [];
}

node QueryProgram {
    # Recursive compositional program: joins, time, corrections, constraints,
    # aggregation, indirection. depth tracks program depth.
    has label: str = "";
    has depth: int = 0;
    has parts: list[str] = [];
}

node Renderer {
    # Independent renderers that express the same latent state:
    # conversation, document, email, story, table, fragmented record.
    has kind: str = "";
}

node AnswerEvidence {
    # A piece of evidence the renderer emitted; multiple cross-record
    # evidence is what makes the benchmark hard to compiler-shape.
    has source: str = "";
    has payload: str = "";
}

# ---------- typed edges (relationship carries meaning) ----------

edge DescribesOntology {}     # QueryProgram -> Ontology  (what schema it targets)
edge Emits {}                 # Renderer    -> AnswerEvidence (what it rendered)
edge SourcedFrom {}           # AnswerEvidence -> Ontology (latent provenance)
edge CounterfactualOf {}     # AnswerEvidence -> AnswerEvidence (metamorphic sibling)
edge SubqueryOf {}            # QueryProgram -> QueryProgram (recursive expansion)

# ---------- walker: walk a recursive query program tree ----------

walker QueryAuditor {
    # Cycles are real: subquery recursion can point back at an ancestor.
    # v9 invariant — keep the explicit guard, do not rely on walker dedupe.
    has seen: list[str] = [];
    has depth_budget: int = 6;
    has expanded: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with QueryProgram entry {
        here_label = here.label;
        if here_label in self.seen {
            print(f"[cycle-guard] revisit blocked at {here_label}");
            disengage;
        }
        self.seen.append(here_label);
        if here.depth > self.depth_budget {
            print(f"[depth-cap] {here_label} at depth {here.depth}");
            disengage;
        }
        print(f"[query] {here_label} (depth={here.depth}, parts={here.parts})");
        # Schema this program targets.
        for o in [->:DescribesOntology:->] {
            print(f"  targets ontology seed={o.seed_id} types={o.entity_types}");
        }
        # Recurse into subqueries — visit typed edge to keep semantics.
        visit [->:SubqueryOf:->];
    }
}

# ---------- walker: sweep renderers, surface counterfactual siblings ----------

walker RendererSweep {
    has rendered: int = 0;
    has cross_record_ok: bool = True;

    can start with Root entry {
        visit [-->];
    }

    can sweep with Renderer entry {
        print(f"[renderer] class={here.kind}");
        for ev in [->:Emits:->] {
            self.rendered += 1;
            print(f"  evidence[{self.rendered}] from={ev.source} payload={ev.payload}");
            # Latent provenance — same ontology across renderer swaps is the
            # metamorphic invariant: renderer change -> answer must remain.
            for onto in [ev->:SourcedFrom:->] {
                print(f"    latent={onto.seed_id} types={onto.entity_types}");
            }
            # Counterfactual/metamorphic sibling: same scaffold, one causal
            # fact changed -> the answer must change.
            for sib in [ev->:CounterfactualOf:->] {
                print(f"    cf-sibling from={sib.source} payload={sib.payload}");
            }
        }
        visit [-->];
    }
}

# ---------- walker: spec gate — confirm v9 invariants on a seed ----------

walker SpecGate {
    has seed_label: str = "";
    has renderer_count: int = 0;
    has query_count: int = 0;
    has cf_count: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can gate with Ontology entry {
        self.seed_label = here.seed_id;
        print(f"[spec-gate] seed={here.seed_id}");
        print(f"  ontology types={here.entity_types}");
        print(f"  relationships={here.relationships}");
        print(f"  field_names={here.field_names}");
        visit [-->];
    }

    can count with Renderer entry {
        self.renderer_count += 1;
    }

    can count with QueryProgram entry {
        self.query_count += 1;
    }

    can count with AnswerEvidence entry {
        for _ in [->:CounterfactualOf:->] {
            self.cf_count += 1;
        }
    }
}

# ---------- demo wiring ----------

with entry {
    # Per-run ontology (content-bound into dataset identity, no stable
    # family/template id at the harness boundary).
    onto = Ontology(
        seed_id="seed-001",
        entity_types=["Trip", "Leg", "LedgerEntry"],
        relationships=["TripLeg", "LedgerTrip"],
        field_names=["depart", "arrive", "fare"]
    );

    # Recursive query program: joins + temporal + correction + aggregation.
    q_join = QueryProgram(label="join_trip_leg", depth=1,
                          parts=["join:Leg on Trip", "time:depart in window"]);
    q_corr = QueryProgram(label="correct_fare", depth=2,
                          parts=["correction:fare+=rebate"]);
    q_agg  = QueryProgram(label="aggregate_total", depth=3,
                          parts=["agg:sum(fare)", "filter:status=confirmed"]);
    # Intentional cycle: aggregate references join again -> guard must fire.
    q_cycle = QueryProgram(label="join_trip_leg", depth=4, parts=["rejoin"]);

    # Independent renderer classes expressing the same latent state.
    r_conv = Renderer(kind="conversation");
    r_doc  = Renderer(kind="pasted_document");
    r_tbl  = Renderer(kind="table");

    # Evidence emitted by each renderer; cross-record means >= 2 long memories.
    ev_conv = AnswerEvidence(source="chat", payload="fare came to 42 after rebate");
    ev_doc  = AnswerEvidence(source="doc",  payload="Trip 7 total = 42 (rebated)");
    ev_tbl  = AnswerEvidence(source="table",payload="trip|fare\n7|42");
    # Counterfactual: same scaffold, fare bumped -> answer must change.
    ev_cf   = AnswerEvidence(source="table",payload="trip|fare\n7|45");

    # Wire the graph.
    root ++> onto;
    root ++> q_join ++> q_corr ++> q_agg;
    q_agg +>:SubqueryOf:+> q_cycle;   # intentional back-edge to test guard
    q_join  +>:DescribesOntology:+> onto;
    q_corr  +>:DescribesOntology:+> onto;
    q_agg   +>:DescribesOntology:+> onto;
    root ++> r_conv ++> r_doc ++> r_tbl;
    r_conv +>:Emits:+> ev_conv;
    r_doc  +>:Emits:+> ev_doc;
    r_tbl  +>:Emits:+> ev_tbl;
    r_tbl  +>:Emits:+> ev_cf;          # second emission on same renderer
    ev_conv +>:SourcedFrom:+> onto;
    ev_doc  +>:SourcedFrom:+> onto;
    ev_tbl  +>:SourcedFrom:+> onto;
    ev_cf   +>:SourcedFrom:+> onto;
    ev_cf   +>:CounterfactualOf:+> ev_tbl;

    # 1. Walk the recursive query program (exercises cycle guard + depth cap).
    QueryAuditor() spawn root;

    # 2. Sweep renderers, surface latent provenance and counterfactual sibling.
    RendererSweep() spawn root;

    # 3. Spec gate: tally v9 invariants on this seed.
    gate = SpecGate();
    gate spawn root;
    print(
