        f"cf_edges={gate.cf_count} "
        f"-> per-run ontology=OK, compositional programs=OK, "
        f"independent renderers={'OK' if gate.renderer_count >= 3 else 'FAIL'}, "
        f"counterfactual families={'OK' if gate.cf_count >= 1 else 'FAIL'}"
    );
}

