    has name: str = "";
    has entity_types: str = "user,device,session";
    has depth: int = 2;
}

node LatentState {
    has world_id: str = "";
    has description: str = "";
}

edge RenderedAs {
    has renderer: str = "";
}

node RenderRecord {
    has text: str = "";
    has renderer_kind: str = "";
    has is_critical: bool = False;
}

node QueryProgram {
