"""Tests for the V9 bench gate demo: per-run ontology, multi-renderer
rendering of one latent state, recursive query-program descent, and
cycle detection on repeated program visits."""

import io;
import from contextlib { redirect_stdout }

test "multi-renderer projection covers all renderer kinds" {
    root ++> LatentState(world_id="run-A", description="latent A");
    bench = [root -->][?:LatentState][0];
    onto = OntologyDef(name="ont-A", entity_types="user,device,session,plan", depth=3);
    conv = RenderRecord(text="hey i switched plans", renderer_kind="chat", is_critical=True);
    doc = RenderRecord(text="account ledger row 7", renderer_kind="ledger", is_critical=False);
    email = RenderRecord(text="from support: confirm device swap", renderer_kind="email", is_critical=True);
    bench +>:RenderedAs(renderer="chat"):+> conv;
    bench +>:RenderedAs(renderer="ledger"):+> doc;
    bench +>:RenderedAs(renderer="email"):+> email;
    bench +>:HasOntology(version="v9"):+> onto;

    records = [bench ->:RenderedAs:->];
    assert len(records) == 3, f"expected 3 renderers, got {len(records)}";

    kinds = sorted([r.renderer_kind for r in records]);
    assert kinds == ["chat", "email", "ledger"], f"renderer kinds: {kinds}";

    critical = [r for r in records if r.is_critical];
    assert len(critical) == 2, f"expected 2 critical records, got {len(critical)}";

    assert onto in [bench ->:HasOntology:->], "ontology edge must point from latent state to OntologyDef";
    assert onto.depth == 3, f"ontology depth: {onto.depth}";
}

test "audit walker reports latent, ontology, and critical records in order" {
    root ++> LatentState(world_id="run-B", description="user owns device");
    bench = [root -->][?:LatentState][0];
    onto = OntologyDef(name="ont-B", entity_types="acct,device", depth=2);
    conv = RenderRecord(text="chat line", renderer_kind="chat", is_critical=True);
    info = RenderRecord(text="ledger note", renderer_kind="ledger", is_critical=False);
    bench +>:RenderedAs(renderer="chat"):+> conv;
    bench +>:RenderedAs(renderer="ledger"):+> info;
    bench +>:HasOntology(version="v9"):+> onto;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn AuditSweep();
    }
    out = buf.getvalue();

    assert "[latent] run-B" in out, f"missing latent line: {out}";
    assert "[ontology] ont-B" in out, f"missing ontology line: {out}";
    assert "CRIT" in out, f"missing CRIT marker: {out}";
    assert "renderer=chat" in out, f"missing chat renderer: {out}";
    assert "renderer=ledger" in out, f"missing ledger renderer: {out}";

    assert res.cycle_detected is False, "no cycle on a tree-shaped query program";
}

test "query program recursion reports each depth and respects parent label" {
    root ++> LatentState(world_id="run-C", description="x");
    bench = [root -->][?:LatentState][0];
    q1 = QueryProgram(operations="join", depth=1, parent_op="root");
    q2 = QueryProgram(operations="time", depth=2, parent_op="join");
    q3 = QueryProgram(operations="aggregate", depth=3, parent_op="time");
    q1 +>:Decomposes(label="then"):+> q2;
    q2 +>:Decomposes(label="then"):+> q3;
    root ++> q1;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn AuditSweep();
