    out = buf.getvalue();

    assert "[query] join@1" in out, f"missing join@1: {out}";
    assert "[query] time@2" in out, f"missing time@2: {out}";
    assert "[query] aggregate@3" in out, f"missing aggregate@3: {out}";
    assert "parent=root" in out, f"missing parent=root: {out}";
    assert "parent=join" in out, f"missing parent=join: {out}";
    assert "parent=time" in out, f"missing parent=time: {out}";

    visited = sorted(res.visited_programs);
    assert visited == ["aggregate@3", "join@1", "time@2"], f"visited order: {visited}";
    assert res.cycle_detected is False, f"unexpected cycle: {visited}";

    children = [q1 ->:Decomposes:->];
    assert len(children) == 1, f"expected one child of q1, got {len(children)}";
    assert children[0] is q2, "Decomposes edge from q1 must target q2";
}

test "cycle in query program is detected and traversal halts" {
    root ++> LatentState(world_id="run-D", description="cycle");
    q1 = QueryProgram(operations="join", depth=1, parent_op="root");
    q2 = QueryProgram(operations="time", depth=2, parent_op="join");
    q1 +>:Decomposes(label="then"):+> q2;
    q2 +>:Decomposes(label="loop"):+> q1;
    root ++> q1;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn AuditSweep();
    }
    out = buf.getvalue();

    assert res.cycle_detected is True, f"cycle_detected should be True, got {res.cycle_detected}; visited={res.visited_programs}";
    assert "[cycle]" in out, f"missing cycle marker: {out}";
    assert "join@1" in res.visited_programs, f"join@1 must be visited first: {res.visited_programs}";

    q1_seen = sum(1 for p in res.visited_programs if p == "join@1");
    assert q1_seen == 1, f"join@1 should appear once before disengage, got {q1_seen}: {res.visited_programs}";
}

test "ontology cascade does not affect unrelated latent state nodes" {
    a = LatentState(world_id="run-E1", description="state one");
