fixed.jac_tests:
"""Test annex for Hermes Mac-control execution context propagation.

Exercises the behaviors the issue promises:
- Verified trusted context flows untouched from gateway ingress through to a
  Mac-control tool.
- Tampered/caller-injected context is rejected at the first typed boundary
  it appears.
- Session isolation: two concurrent sessions with the same verified context
  each reach their tool without cross-contamination.
- Missing bind/reset on the raw threading.Thread seam is caught.
- The auditor walker reports zero mismatches on a clean pipeline.
"""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

def build_trusted_chain {
    gateway = GatewayIngress(
        ingress_id="gw-trusted",
        verified_context="broker-ctx-MAC-CTRL-v1",
        verified_tool_call_id="tcid-7f3a",
        trusted=True
    );
    s = Session(
        session_id="sess-trusted",
        ambient_context="broker-ctx-MAC-CTRL-v1",
        tool_call_id="tcid-7f3a"
    );
    disp = Dispatcher(dispatcher_name="ws-dispatcher", copy_context_applied=True);
    raw = RawThreadSeam(
        thread_name="agent-build-thread",
        inherited_context=True,
        bind_reset_applied=True,
        ambient_context="broker-ctx-MAC-CTRL-v1"
    );
    tool = MacControlTool(
        tool_name="open_app",
        received_context="broker-ctx-MAC-CTRL-v1",
        received_tool_call_id="tcid-7f3a",
        is_mac_control=True
    );
    gateway +>:Authenticated(verified_at="2024-01-01T00:00:00Z"):+> s;
    s +>:SessionBound(bound_at="2024-01-01T00:00:01Z"):+> disp;
    disp +>:Dispatched(dispatch_id="d-1"):+> raw;
    raw +>:RawThreadFork(fork_reason="agent-build"):+> tool;
    return [gateway, tool];
}

# ---------------------------------------------------------------------------
# 1. End-to-end happy path: trusted broker context reaches the Mac-control tool
#    with zero rejections and the tool still carries the broker payload.
# ---------------------------------------------------------------------------
test "trusted context propagates end-to-end" {
    buf = io.StringIO();
    (gateway, tool) = build_trusted_chain();
    root ++> gateway;
    with redirect_stdout(buf) {
        res = root spawn ContextPropagator();
    }
    out = buf.getvalue();
    assert res.failures == 0, f"expected zero failures, got {res.failures}; out={out}";
    assert "ingress gw-trusted verified context OK" in out, f"missing ingress OK: {out}";
    assert "forwarded verified context into tool open_app" in out, f"missing tool forward: {out}";
    assert "REJECT" not in out, f"unexpected rejection in clean path: {out}";
    assert tool.received_context == "broker-ctx-MAC-CTRL-v1", f"tool got wrong ctx: {tool.received_context}";
    assert tool.received_tool_call_id == "tcid-7f3a", f"tool got wrong tcid: {tool.received_tool_call_id}";
}

# ---------------------------------------------------------------------------
# 2. Tampered gateway payload is refused at the first typed boundary and
#    never advances to the tool. The walker must disengage, so the tool's
#    received payload stays whatever the graph was wired with.
# ---------------------------------------------------------------------------
test "tampered ingress payload is rejected at gateway" {
    buf = io.StringIO();
    bad_gw = GatewayIngress(
        ingress_id="gw-bad",
        verified_context="caller-injected-ctx",
        verified_tool_call_id="tcid-evil",
        trusted=True
    );
    s = Session(
        session_id="sess-bad",
        ambient_context="broker-ctx-MAC-CTRL-v1",
        tool_call_id="tcid-7f3a"
    );
    tool = MacControlTool(
        tool_name="open_app",
        received_context="broker-ctx-MAC-CTRL-v1",
        received_tool_call_id="tcid-7f3a",
        is_mac_control=True
    );
    bad_gw +>:Authenticated(verified_at="t"):+> s;
    s +>:SessionBound(bound_at="t"):+> Dispatcher(
        dispatcher_name="d", copy_context_applied=True
    );
    root ++> bad_gw;
    with redirect_stdout(buf) {
        res = root spawn ContextPropagator();
    }
    out = buf.getvalue();
    assert res.failures >= 1, f"tampered ingress must fail; got {res.failures}; out={out}";
    assert "REJECT at ingress gw-bad" in out, f"expected ingress rejection: {out}";
    assert "forwarded verified context into tool" not in out, f"tampered ctx must NOT reach tool: {out}";
}

# ---------------------------------------------------------------------------
# 3. Raw threading.Thread seam that forgot to bind/reset must be caught.
#    Acceptance criterion: explicit bind/reset is required on this seam.
# ---------------------------------------------------------------------------
test "raw thread seam without bind/reset is rejected" {
    buf = io.StringIO();
    gw = GatewayIngress(
        ingress_id="gw",
        verified_context="broker-ctx-MAC-CTRL-v1",
        verified_tool_call_id="tcid-7f3a",
        trusted=True
    );
    s = Session(
        session_id="s",
        ambient_context="broker-ctx-MAC-CTRL-v1",
        tool_call_id="tcid-7f3a"
    );
    disp = Dispatcher(dispatcher_name="d", copy_context_applied=True);
    raw = RawThreadSeam(
        thread_name="no-bind-thread",
        inherited_context=True,
        bind_reset_applied=False,   # forgot the explicit bind/reset
        ambient_context="broker-ctx-MAC-CTRL-v1"
    );
    gw +>:Authenticated(verified_at="t"):+> s;
    s +>:SessionBound(bound_at="t"):+> disp;
    disp +>:Dispatched(dispatch_id="d"):+> raw;
    root ++> gw;
    with redirect_stdout(buf) {
        res = root spawn ContextPropagator();
    }
    out = buf.getvalue();
    assert res.failures >= 1, f"missing bind/reset must be a failure: {res.failures}";
    assert "explicit bind/reset missing" in out, f"expected bind/reset rejection: {out}";
    assert "forwarded verified context into tool" not in out, f"context must not advance past seam: {out}";
}

# ---------------------------------------------------------------------------
# 4. Two simultaneous sessions must remain isolated: each pipeline keeps the
#    same verified context, and the auditor sees zero mismatches on either.
# ---------------------------------------------------------------------------
test "concurrent sessions stay isolated and auditor sees no mismatches" {
    buf = io.StringIO();
    (gw, tool1) = build_trusted_chain();
    gw2 = GatewayIngress(
        ingress_id="gw-2",
        verified_context="broker-ctx-MAC-CTRL-v1",
        verified_tool_call_id="tcid-7f3a",
        trusted=True
    );
    s2 = Session(
        session_id="sess-2",
        ambient_context="broker-ctx-MAC-CTRL-v1",
        tool_call_id="tcid-7f3a"
    );
    disp2 = Dispatcher(dispatcher_name="ws-dispatcher", copy_context_applied=True);
    raw2 = RawThreadSeam(
        thread_name="agent-build-thread-2",
        inherited_context=True,
        bind_reset_applied=True,
        ambient_context="broker-ctx-MAC-CTRL-v1"
    );
    tool2 = MacControlTool(
        tool_name="close_app",
        received_context="broker-ctx-MAC-CTRL-v1",
        received_tool_call_id="tcid-7f3a",
        is_mac_control=True
    );
    gw2 +>:Authenticated(verified_at="t"):+> s2;
    s2 +>:SessionBound(bound_at="t"):+> disp2;
    disp2 +>:Dispatched(dispatch_id="d2"):+> raw2;
    raw2 +>:RawThreadFork(fork_reason="agent-build"):+> tool2;
    root ++> gw;
    root ++> gw2;
    with redirect_stdout(buf) {
        auditor = root spawn ContextAuditor();
    }
    out = buf.getvalue();
    assert auditor.mismatched == 0, f"auditor saw mismatches on clean pipelines: {auditor.mismatched}; out={out}";
    # Two independent Mac-control tools both received the broker payload.
    assert tool1.received_context == "broker-ctx-MAC-CTRL-v1", f"tool1 ctx mutated: {tool1.received_context}";
    assert tool2.received_context == "broker-ctx-MAC-CTRL-v1", f"tool2 ctx mutated: {tool2.received_context}";
    assert tool1.tool_name != tool2.tool_name, "tools should be distinct nodes";
}

