"""ADWF audit ledger: track audit entries, architectural deltas, and decision
traceability as a graph. A walker walks the audit chain and reports decisions,
while a cascade walker propagates invalidation across an entry's outgoing
relationships when its acceptance status changes.

Models entities as native archetypes:
- AuditEntry node carrying baseline SHA, status, mode, owner decision.
- ArchitectureDelta node linking an audit entry to a rolling-wave decision
  and a supersession chain between deltas.

Relationships are modeled as typed edges:
- ProducedDelta connecting AuditEntry to its ArchitectureDelta children.
- Supersedes connecting one ArchitectureDelta to the next (supersession
  chain, with cycle policy preserved via an explicit visited guard).

Traversal uses walkers; cycle policy of the original ledger (no delta may
refer back to an already-walked entry) is preserved as an explicit guard
set on the walker, not delegated to library plumbing.
"""

node AuditEntry {
    has title: str = "";
    has baseline_sha: str = "";
    has mode: str = "";
    has status: str = "";
    has owner_decision: str = "";
}

node ArchitectureDelta {
    has title: str = "";
    has rationale: str = "";
    has evidence: str = "";
    has invalidated: bool = False;
}

edge ProducedDelta {
    has rationale: str = "";
}

edge Supersedes {
    has reason: str = "";
}

walker LedgerAuditor {
    has visited: list[str] = [];
    has report_lines: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can audit with AuditEntry entry {
        self.visited.append(here.title);
        line = (
            f"[AUDIT] {here.title} | status={here.status}"
            f" | mode={here.mode} | baseline={here.baseline_sha}"
        );
        self.report_lines.append(line);
        line2 = f"  owner_decision: {here.owner_decision}";
        self.report_lines.append(line2);
        visit [->:ProducedDelta:->];
    }

    can review with ArchitectureDelta entry {
        if here.title in self.visited {
            self.report_lines.append(
                f"[CYCLE] refusing to revisit {here.title}"
            );
            disengage;
        }
        self.visited.append(here.title);
        label = "INVALIDATED" if here.invalidated else "LIVE";
        self.report_lines.append(
            f"[DELTA/{label}] {here.title}"
            f" | rationale={here.rationale}"
        );
        visit [->:Supersedes:->];
    }
}

walker CascadeInvalidator {
    has origin: str = "";
    has invalidations: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can locate with AuditEntry entry {
        if here.title == self.origin {
            self.invalidations.append(here.title);
            visit [->:ProducedDelta:->];
        } else {
            visit [-->];
        }
    }

    can invalidate with ArchitectureDelta entry {
        here.invalidated = True;
        self.invalidations.append(here.title);
        visit [->:Supersedes:->];
    }
}

with entry {
    foundation = AuditEntry(
        title="ADWF-FOUNDATION-2026-08-15",
        baseline_sha="8f47de35957297037b2516d19e9b9775ace1e734",
        mode="READ_ONLY_DESIGN_ONLY",
        status="ACCEPTED_AS_PLANNING_BASELINE",
        owner_decision="ADWF is not rewritten; strong governance core preserved",
    );
    root ++> foundation;

    delta_dev = ArchitectureDelta(
        title="DEVENV-001+SKILL-001",
        rationale="AI session needs exact-SHA git workspace and skill lifecycle",
        evidence="PR #24, #32, #35 merged",
    );
    delta_roadmap = ArchitectureDelta(
        title="ROADMAP-001",
        rationale="Roadmap DAG + Verified Outcome Progress as separate capability",
        evidence="PR #38 merged at fdbe95f7722bd0c11a7c1c6b1bd3d8ac7c7226aa",
    );
    delta_aiwork = ArchitectureDelta(
        title="AIWORK-001/GOV-011",
        rationale="AI Work Contracts kept separate from durable traceability",
        evidence="PR #41 merged at a2fad617af9ba8265212043f4ed882046994baef",
    );

    foundation +>:ProducedDelta(rationale="emitted"):+> delta_dev;
    foundation +>:ProducedDelta(rationale="emitted"):+> delta_roadmap;
    foundation +>:ProducedDelta(rationale="emitted"):+> delta_aiwork;
    delta_dev +>:Supersedes(reason="dependency resolved first"):+> delta_roadmap;
    delta_roadmap +>:Supersedes(reason="downstream contract layering"):+> delta_aiwork;

    auditor = LedgerAuditor();
    root spawn auditor;
    for line in auditor.report_lines {
        print(line);
    }

    print("--- cascade invalidation from DEVENV delta ---");
    invalidator = CascadeInvalidator(
        origin="DEVENV-001+SKILL-001",
    );
    root spawn invalidator;
    for entry_title in invalidator.invalidations {
        print(f"invalidated: {entry_title}");
    }
    dev_state = "INVALIDATED" if delta_dev.invalidated else "LIVE";
    roadmap_state = "INVALIDATED" if delta_roadmap.invalidated else "LIVE";
    aiwork_state = "INVALIDATED" if delta_aiwork.invalidated else "LIVE";
    print(
