"""Tests for the plugin-build cycle detector walker."""

import io;
import from contextlib { redirect_stdout }

test "cycle is reported when present" {
    a = PluginBuild(name="dedebug");
    b = PluginBuild(name="dependency-analysis-gradle-plugin");
    c = PluginBuild(name="com.gradle.develocity");

    root +>:IncludeBuild(reason="pluginManagement"):+> a;
    a +>:IncludeBuild(reason="includeBuild('../b')"):+> b;
    b +>:IncludeBuild(reason="plugin coords"):+> c;
    c +>:IncludeBuild(reason="includeBuild('../b')"):+> b;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CycleDetector();
    }
    out = buf.getvalue();

    assert "CYCLE detected" in out, f"expected cycle marker in: {out!r}";
    assert "dedebug" in out, f"path should include dedebug: {out!r}";
    assert "dependency-analysis-gradle-plugin" in out, f"path should include the repeated plugin: {out!r}";
    assert "com.gradle.develocity" in out, f"path should include develocity: {out!r}";
}

test "no cycle on a clean chain" {
    a = PluginBuild(name="dedebug");
    b = PluginBuild(name="dependency-analysis-gradle-plugin");

    root +>:IncludeBuild(reason="pluginManagement"):+> a;
    a +>:IncludeBuild(reason="includeBuild('../b')"):+> b;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CycleDetector();
    }
    out = buf.getvalue();

    assert "CYCLE detected" not in out, f"clean chain should not report a cycle: {out!r}";
    assert res.path == ["dedebug", "dependency-analysis-gradle-plugin"], f"path should walk the chain fully, got {res.path}";
    assert len(res.seen) == 2, f"seen should hold both nodes, got {res.seen}";
}

test "self loop is treated as a cycle" {
    a = PluginBuild(name="dedebug");
    root +>:IncludeBuild(reason="pluginManagement"):+> a;
    a +>:IncludeBuild(reason="self"):+> a;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CycleDetector();
    }
    out = buf.getvalue();

    assert "CYCLE detected" in out, f"self loop should be flagged, got {out!r}";
    assert "dedebug" in out, f"cycle message must name the offending node: {out!r}";
}

test "walker disengages on first cycle" {
    a = PluginBuild(name="dedebug");
    b = PluginBuild(name="dependency-analysis-gradle-plugin");
    c = PluginBuild(name="com.gradle.develocity");
    d = PluginBuild(name="other-plugin");

    root +>:IncludeBuild(reason="pluginManagement"):+> a;
    a +>:IncludeBuild(reason="includeBuild('../b')"):+> b;
    b +>:IncludeBuild(reason="includeBuild('../c')"):+> c;
    c +>:IncludeBuild(reason="includeBuild('../b')"):+> b;
    c +>:IncludeBuild(reason="unreached"):+> d;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CycleDetector();
    }
    out = buf.getvalue();

    assert "CYCLE detected" in out, f"expected cycle in output: {out!r}";
    assert "other-plugin" not in out, f"walker should disengage before reaching other-plugin: {out!r}";
    assert "com.gradle.develocity -> dependency-analysis-gradle-plugin" in out, f"back edge should be named: {out!r}";
}

test "graph shape reflects included builds" {
    a = PluginBuild(name="dedebug");
    b = PluginBuild(name="dependency-analysis-gradle-plugin");
    c = PluginBuild(name="com.gradle.develocity");

    root +>:IncludeBuild(reason="pluginManagement"):+> a;
    a +>:IncludeBuild(reason="includeBuild('../b')"):+> b;
    b +>:IncludeBuild(reason="plugin coords"):+> c;
    c +>:IncludeBuild(reason="includeBuild('../b')"):+> b;

    includes = [root ->:IncludeBuild:->];
    assert len(includes) == 1, f"root should have exactly one included build, got {len(includes)}";

    b_includes = [b ->:IncludeBuild:->];
    assert len(b_includes) == 1, f"b should include exactly one build, got {len(b_includes)}";

    c_includes = [c ->:IncludeBuild:->];
    assert len(c_includes) == 1, f"c should include exactly one build, got {len(c_includes)}";
    assert c_includes[0].name == "dependency-analysis-gradle-plugin", f"c should include b, got {c_includes[0].name}";
}

