"""Tests for cross-branch agreement fold over positional-union wrappers."""

import io;
import from contextlib { redirect_stdout }

# ---------- helpers ----------------------------------------------------------

def build_all_bigint_union {
    leaf_a = LeafSelect(label="leaf-A");
    leaf_a.output_columns = [
        Column(name="id", js_type="bigint"),
        Column(name="count", js_type="bigint"),
    ];
    leaf_b = LeafSelect(label="leaf-B");
    leaf_b.output_columns = [
        Column(name="id", js_type="bigint"),
        Column(name="count", js_type="bigint"),
    ];
    u = SetOperation(label="UNION-ok");
    u +>:BranchesTo(position=0):+> leaf_a;
    u +>:BranchesTo(position=1):+> leaf_b;
    return u;
}

def build_disagree_union {
    leaf_a = LeafSelect(label="leaf-disagree-A");
    leaf_a.output_columns = [
        Column(name="id", js_type="bigint"),
        Column(name="label", js_type="number"),
    ];
    leaf_b = LeafSelect(label="leaf-disagree-B");
    leaf_b.output_columns = [
        Column(name="id", js_type="bigint"),
        Column(name="label", js_type="raw"),
    ];
    u = SetOperation(label="UNION-mixed");
    u +>:BranchesTo(position=0):+> leaf_a;
    u +>:BranchesTo(position=1):+> leaf_b;
    return u;
}

def build_simple_cte {
    inner = LeafSelect(label="cte-inner");
    inner.output_columns = [
        Column(name="id", js_type="bigint"),
        Column(name="value", js_type="number"),
    ];
    c = CteWrap(label="CTE-simple");
    c +>:OuterWraps:+> inner;
    return c;
}

def build_recursive_cte {
    base = LeafSelect(label="rec-base");
    base.output_columns = [
        Column(name="node_id", js_type="bigint"),
        Column(name="payload", js_type="number"),
    ];
    step = LeafSelect(label="rec-step");
    step.output_columns = [
        Column(name="node_id", js_type="bigint"),
        Column(name="payload", js_type="raw"),
    ];
    r = RecursiveCte(label="RecursiveCTE");
    r +>:BranchesTo(position=0):+> base;
    r +>:BranchesTo(position=1):+> step;
    return r;
}

# ---------- tests ------------------------------------------------------------

test "all-agreeing UNION: every position kept, all convert" {
    u = build_all_bigint_union();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = u spawn ProvenanceFolder();
    }
    out = buf.getvalue();
