test "cap stops traversal when depth reaches limit" {
    root ++> ShellInvocation(command="render_hostname", env_stripped=True);
    inv = [root -->][?:ShellInvocation][0];
    scope = CgroupScope(scope_path="/s.slice/x.scope", pids_max=32, current_tasks=2, frozen=False);
    inv +>:RanIn(start_ts=1):+> scope;

    scope +>:Spawned(at_depth=0):+> BashProcess(pid=2001, cmdline="bash -c 'x'", depth=0, exited_normally=False);
    scope +>:Spawned(at_depth=1):+> BashProcess(pid=2002, cmdline="bash -c 'x'", depth=1, exited_normally=False);
    scope +>:Spawned(at_depth=2):+> BashProcess(pid=2003, cmdline="bash -c 'x'", depth=2, exited_normally=False);
    scope +>:Spawned(at_depth=3):+> BashProcess(pid=2004, cmdline="bash -c 'x'", depth=3, exited_normally=False);

    res = inv spawn Sandbox(cap=2);
    assert res.chain_length == 3, f"expected chain_length=3, got {res.chain_length}";
    assert res.runaway_detected is True, f"runaway should be detected when depth>=cap, got {res.runaway_detected}";
}

test "runaway is flagged for any non-exited bash process" {
    root ++> ShellInvocation(command="render_hostname", env_stripped=True);
    inv = [root -->][?:ShellInvocation][0];
    scope = CgroupScope(scope_path="/s.slice/y.scope", pids_max=32, current_tasks=1, frozen=False);
    inv +>:RanIn(start_ts=1):+> scope;

    scope +>:Spawned(at_depth=0):+> BashProcess(pid=3001, cmdline="bash -c 'render_hostname'", depth=0, exited_normally=False);

    res = inv spawn Sandbox(cap=16);
    assert res.runaway_detected is True, f"single non-exited bash must flag runaway, got {res.runaway_detected}";
    assert res.chain_length == 1, f"expected chain_length=1, got {res.chain_length}";
}

