    has title: str = "";
    has status: str = "DRAFT";
}

node Requirement {
    has title: str = "";
    has priority: int = 0;
    has verified: bool = False;
}

node Decision {
    has title: str = "";
    has rationale: str = "";
    has adopted: bool = False;
}

edge Drives {
    has weight: int = 1;
}

edge Satisfies {
    has confidence: float = 1.0;
}

edge Invalidates {
    has reason: str = "";
}

walker TraceAuditor {
    has findings: list[str] = [];
    has visited: list[str] = [];
    has broken: bool = False;

    can start with Root entry {
        print("ADWF Foundation trace audit begins");
        visit [-->];
