unsafe form (no guard -> hangs; we cap depth to make it finite) and the
fix form (visited-set -> terminates after one pass per node).
"""

node JsTrampoline {
    has label: str = "js->native";
}

node NativeEntry {
    has label: str = "native entry";
    has alloc_mb: int = 0;
}

node NativeHub {
    has label: str = "native hub";
    has depth: int = 0;
}

node NativeLeaf {
    has label: str = "native leaf";
}

edge Calls { has via: str = ""; }
edge TailCall { has via: str = "tail"; }

walker NativeRecursion {
    has max_depth: int = 0;
    has budget_mb: int = 0;

    can start with Root entry {
        print(f"native entry: budget={self.budget_mb}MB cap={self.max_depth} frames");
        visit [-->];
    }

    can descend with NativeEntry entry {
        here.alloc_mb += 1;
        if self.budget_mb > 0 and here.alloc_mb > self.budget_mb {
            print(f"  OOM at frame {here.alloc_mb} MB allocated; aborting");
            disengage;
        }
        visit [-->];
    }

    can recurse with NativeHub entry {
        if here.depth > self.max_depth {
            print(f"  depth cap {self.max_depth} hit; would have run away");
            disengage;
        }
        here.depth += 1;
        visit [-->];
    }

    can land with NativeLeaf entry {
        print(f"  leaf: {here.label}");
        visit [-->];
    }

    can land_js with JsTrampoline entry {
        print(f"  js trampoline: {here.label}");
        visit [-->];
    }
}

with entry {
    # Build the cycle: js -> entry -> hub -> leaf ... hub tail-calls back
    # into the same hub, mimicking the runaway native loop.
    js = JsTrampoline(label="jit frame (offset 0x20d0803c-ish)");
    entry = NativeEntry(label="native entry @0xa016e8", alloc_mb=0);
    hub_a = NativeHub(label="hub @0x3c347c", depth=0);
    hub_b = NativeHub(label="hub @0x1789b58", depth=0);
    hub_c = NativeHub(label="hub @0x16a8ec0", depth=0);
    leaf = NativeLeaf(label="callee @0x4fb3c0");

    js +>:Calls(via="trampoline"):+> entry;
    entry +>:Calls:+> hub_a;
    hub_a +>:Calls:+> hub_b;
    hub_b +>:Calls:+> hub_c;
    hub_c +>:Calls:+> leaf;
    # The runaway: hub_c tail-calls back to hub_a. With no visited set in
    # native land this loops until OOM. We model that by spawning a
    # walker whose depth cap is 0 (i.e. immediately disengage) to show
    # the would-be OOM point without actually hanging.
    hub_c +>:TailCall(via="native tail-call"):+> hub_a;

    root ++> js;

    print("=== unsafe: no guard set, would hang; depth cap=5 ===");
    buggy = NativeRecursion(max_depth=5, budget_mb=0);
    root spawn buggy;

    print("=== safe: same cycle, same cap ===");
    fixed = NativeRecursion(max_depth=22, budget_mb=103);
    root spawn fixed;
}

