"""Native recursion runaway: a self-similar cycle in a linked structure
that a walker keeps re-entering because the graph has no depth bound.

This is the OSP analogue of the bun issue: a recursive descent over a
linked structure with no termination policy grows without bound. The
walker here models the unsafe traversal, and a second walker models the
fixed traversal that bounds the walk.
"""

node Frame {
    # A node in the recursive call chain (analogous to a native stack
    # frame). It carries the offsets the bug report lists so the cycle
    # is observable in the report.
    has offset: int = 0;
    has label: str = "";
    has payload: int = 0;
}

node Entry {
    # The outermost call site (analogous to the bun entry point).
    has name: str = "main";
}

edge Calls {
    # "this frame calls that frame" — a typed edge so traversal follows
    # the call relationship rather than every connection in the graph.
    has depth: int = 0;
}

walker Runaway {
    # The unsafe walker: recurses along Calls edges with no visited set
    # and no depth cap, exactly as the runaway native recursion does.
    # On a cyclic structure it never terminates.
    has frames_visited: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can descend with Entry entry {
        print(f"entry: {here.name}");
        visit [->:Calls:->];
    }

    can recurse with Frame entry {
        self.frames_visited += 1;
        if self.frames_visited > 5000 {
            # The OS would have killed the process long before this in
            # the real bug; here we just disengage so the demo halts.
            print("memory-bounded: disengaging after runaway budget");
            disengage;
        }
        print(f"  frame +0x{here.offset:x} ({here.label}) payload={here.payload}");
        visit [->:Calls:->];
    }
}

walker Safe {
    # The fixed walker: explicit visited set + depth cap. The
    # scaffolding (hand-rolled cycle guard) is preserved because it is
    # domain logic, not plumbing.
    has visited: set[int] = set();
    has depth_cap: int = 32;
    has frames_visited: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can descend with Entry entry {
        print(f"safe entry: {here.name}");
        visit [->:Calls:->];
    }

    can recurse with Frame entry {
        key = here.offset;
        if key in self.visited {
            print(f"  cycle short-circuit at +0x{here.offset:x} ({here.label})");
            disengage;
        }
        if self.frames_visited >= self.depth_cap {
            print(f"  depth cap ({self.depth_cap}) reached, disengaging");
            disengage;
        }
        self.visited.add(key);
        self.frames_visited += 1;
        print(f"  frame +0x{here.offset:x} ({here.label}) payload={here.payload} "
              f"[depth={self.frames_visited}]");
        visit [->:Calls:->];
    }
}

with entry {
    # Build the call graph from the bug report. The innermost 6 frames
    # form the recursing cycle, and the outermost path leads into it.
    # Offsets are the ones the stackshot listed.
    f1 = Frame(offset=0x4fb3c0,  label="leaf",           payload=1);
    f2 = Frame(offset=0xa1a244,  label="propagate",      payload=2);
    f3 = Frame(offset=0x1a08c54, label="resolve",        payload=3);
    f4 = Frame(offset=0x1919438, label="enter-cycle",    payload=4);

    c1 = Frame(offset=0x3c347c,  label="cycle-A",        payload=10);
    c2 = Frame(offset=0x1789b58, label="cycle-B",        payload=11);
    c3 = Frame(offset=0x16a8ec0, label="cycle-C",        payload=12);
    c4 = Frame(offset=0x1919500, label="cycle-D",        payload=13);
    c5 = Frame(offset=0x16a89ec, label="cycle-E-branch", payload=14);
    c6 = Frame(offset=0x178921c, label="cycle-F-branch", payload=15);

    # Linear preamble that leads into the cycle.
    preamble = Entry(name="bun-entry");
    preamble +>:Calls(depth=0):+> f1;
    f1 +>:Calls(depth=1):+> f2;
    f2 +>:Calls(depth=2):+> f3;
    f3 +>:Calls(depth=3):+> f4;
    f4 +>:Calls(depth=4):+> c1;

    # The self-similar cycle: c1 -> c2 -> c3 -> c4 -> c1, with
    # branches c3 -> c5 and c4 -> c6 that rejoin at c4 / c1.
    c1 +>:Calls(depth=5):+>  c2;
    c2 +>:Calls(depth=6):+>  c3;
    c3 +>:Calls(depth=7):+>  c4;
    c4 +>:Calls(depth=8):+>  c1;
    c3 +>:Calls(depth=9):+>  c5;
    c5 +>:Calls(depth=10):+> c4;
    c4 +>:Calls(depth=11):+> c6;
    c6 +>:Calls(depth=12):+> c1;

    root ++> preamble;

    print("=== Runaway walker (no cycle guard, no depth cap) ===");
    root spawn Runaway();

    print("=== Safe walker (visited set + depth cap) ===");
    root spawn Safe(depth_cap=20);
}

