"""Tests for scoped catalog view: label-level access control."""

import io;
import from contextlib { redirect_stdout }

test "alice sees only allowed labels via list_visible" {
    snap = ReadSnapshot(
        principal_name="alice",
        visible_labels=["User", "Post"]
    );
    visible = snap.list_visible();
    assert "User" in visible, f"User should be visible, got {visible}";
    assert "Post" in visible, f"Post should be visible, got {visible}";
    assert "Secret" not in visible, f"Secret must NOT be visible, got {visible}";
    assert len(visible) == 2, f"exactly 2 labels visible, got {visible}";
}

test "materialize denies rows in labels outside the scope" {
    snap = ReadSnapshot(
        principal_name="bob",
        visible_labels=["User"]
    );
    out = snap.materialize("Secret", row_tombstoned=False);
    assert out is None, f"Secret row must be denied for bob, got {out}";

    out2 = snap.materialize("User", row_tombstoned=False);
    assert out2 == "User", f"User row must be allowed for bob, got {out2}";
}

test "materialize filters tombstoned rows even within an allowed label" {
    snap = ReadSnapshot(
        principal_name="alice",
        visible_labels=["User", "Post"]
    );
    out = snap.materialize("Post", row_tombstoned=True);
    assert out is None, f"tombstoned Post must be hidden, got {out}";

    out2 = snap.materialize("User", row_tombstoned=False);
    assert out2 == "User", f"live User must be visible, got {out2}";
}

test "count fast path returns zero for denied label and tracks blocked_count" {
    snap = ReadSnapshot(
        principal_name="carol",
        visible_labels=["User", "Post"]
    );
    blocked_before = snap.blocked_count;
    n = snap.count("Secret");
    assert n == 0, f"denied label count must be 0, got {n}";
    assert snap.blocked_count == blocked_before + 1, (
        f"blocked_count must increment, was {blocked_before}, "
        f"now {snap.blocked_count}"
    );

    # An allowed label does NOT bump the blocked counter.
    blocked_pre = snap.blocked_count;
    allowed = snap.count("User");
    assert allowed == 1, f"allowed label count must be 1, got {allowed}";
    assert snap.blocked_count == blocked_pre, (
        f"blocked_count must NOT change for allowed labels, "
        f"was {blocked_pre}, now {snap.blocked_count}"
    );
}

test "reason is uniform so absent is indistinguishable from forbidden" {
    snap = ReadSnapshot(
        principal_name="dave",
        visible_labels=["User"]
    );
    msg_present = snap.reason();
    # Reason must be a stable uniform string — the whole surface
    # that an unauthorized caller sees when probing.
    assert msg_present == "not found", f"reason must be 'not found', got {msg_present!r}";
    # Calling again must return the same uniform message.
    assert snap.reason() == msg_present, "reason must be stable across calls";
}

test "walker builds the scoped snapshot at the single catalog chokepoint" {
    # Build a small graph: catalog -> MemberOf -> rows, with a
    # principal that is allowed only "User" and "Post".
    cat = Catalog(name="c", labels=["User", "Post", "Secret"]);
    p = Principal(name="eve", allowed_labels=["User", "Post"]);

    root ++> p;
    root +>:Executes(query_kind="READ"):+> cat;
    cat +>:MemberOf:+> Row(label_name="User", tombstoned=False);
    cat +>:MemberOf:+> Row(label_name="Post", tombstoned=False);
    cat +>:MemberOf:+> Row(label_name="Post", tombstoned=True);
    cat +>:MemberOf:+> Row(label_name="Secret", tombstoned=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        w = root spawn ScopeAndTraverse(principal_name="eve");
    }
    out = buf.getvalue();

    # The walker must produce a snapshot whose visible_labels
    # excludes "Secret" — the whole point of the chokepoint.
    snap_obj = w.summary["snap"];
    assert isinstance(snap_obj, ReadSnapshot), (
        f"walker must produce a ReadSnapshot, got {snap_obj!r}"
    );
    visible = snap_obj.list_visible();
    assert "Secret" not in visible, (
        f"scoped snapshot must omit Secret, got {visible}"
    );
    assert "User" in visible and "Post" in visible, (
        f"allowed labels must be present, got {visible}"
    );
    assert snap_obj.principal_name == "eve", (
        f"principal_name must propagate, got {snap_obj.principal_name}"
    );

    # The traversal output must show the Secret row hidden and
    # the tombstoned Post row hidden — denial happens at the
    # single materialization path, not at scattered call sites.
    assert "Secret" in out and "denied label" in out, (
        f"Secret row must be reported as denied, got:\n{out}"
    );
    assert "tombstoned" in out, (
        f"tombstoned row must be reported as hidden, got:\n{out}"
    );
    assert "visible row: User" in out, (
        f"live User row must be reported visible, got:\n{out}"
    );
}

