"""M0 exit review: walk the finding graph against a frozen baseline and publish one bounded decision.

Models the bounded critical path from the issue:
  - a frozen baseline commit,
  - five findings (#5, #8, #53, #54, #55) each classified once as Exit blocker,
    Accepted risk, or Backlog,
  - two acceptance commands and one visible runtime exercise,
  - a single Decision node that receives exactly one GO / CONDITIONAL GO / NO-GO.

Typed edges carry the relationship meaning: Blocks, MitigatedBy, ClassifiedAs,
Exercises, RunsCommand. A Reviewer walker performs an explicit-depth traversal
with a guard set (cycle policy) so the cycle-prone review graph terminates.
"""

# --- Entity archetypes ---------------------------------------------------

node BaselineCommit {
    has sha: str = "";
    has summary: str = "";
}

node Finding {
    has finding_id: str = "";
    has title: str = "";
    has category: str = "Backlog";
    has rationale: str = "";
}

node AcceptanceCommand {
    has label: str = "";
    has cmd: str = "";
    has passed: bool = True;
    has note: str = "";
}

node VisibleRuntime {
    has scenario: str = "";
    has executed: bool = False;
}

node Decision {
    has outcome: str = "PENDING";
    has reasoning: str = "";
}

# --- Typed edges ---------------------------------------------------------

edge Blocks {
    has severity: str = "exit";
}

edge MitigatedBy {
    has boundary: str = "";
}

edge ClassifiedAs {
    has bucket: str = "";
}

edge Exercises {
    has step: str = "";
}

edge RunsCommand {
    has order_index: int = 0;
}

# --- Reviewer walker -----------------------------------------------------

walker Reviewer {
    # Cycle policy: guard set of visited node identities plus a depth cap.
    has visited: list = [];
    has depth_remaining: int = 16;
    has seen_findings: list = [];
    has commands_passed: bool = True;
    has runtime_executed: bool = False;

    can start with Root entry {
        print("Reviewer starting against frozen baseline");
        visit [-->] else { disengage; }
    }

    can review_baseline with BaselineCommit entry {
        if self._seen(here.sha) {
            visit [-->] else { disengage; };
        }
        self._mark(here.sha);
        print(f"[BASELINE] {here.sha} -- {here.summary}");
        self.depth_remaining = self.depth_remaining - 1;
        if self.depth_remaining <= 0 {
            disengage;
        }
        visit [-->] else { disengage; };
    }

    can review_finding with Finding entry {
        if self._seen(here.finding_id) {
            visit [-->] else { disengage; };
        }
        self._mark(here.finding_id);
        self.seen_findings.append(here.finding_id);
        print(f"[FINDING] {here.finding_id} {here.title} -> {here.category}");
        if here.category == "Exit blocker" {
            print(f"          rationale: {here.rationale}");
        }
        self.depth_remaining = self.depth_remaining - 1;
        if self.depth_remaining <= 0 {
            disengage;
        }
        visit [-->] else { disengage; };
    }

    can review_command with AcceptanceCommand entry {
        key = here.label;
        if self._seen(key) {
            visit [-->] else { disengage; };
        }
        self._mark(key);
        verdict = "PASS" if here.passed else "FAIL";
        print(f"[CMD {verdict}] {here.label}: {here.cmd}");
        if not here.passed {
            print(f"          note: {here.note}");
            self.commands_passed = False;
        }
        self.depth_remaining = self.depth_remaining - 1;
        if self.depth_remaining <= 0 {
            disengage;
        }
        visit [-->] else { disengage; };
    }

    can review_runtime with VisibleRuntime entry {
        key = "runtime:" + here.scenario;
        if self._seen(key) {
            visit [-->] else { disengage; };
        }
        self._mark(key);
        verdict = "RUN" if here.executed else "SKIP";
        print(f"[RUNTIME {verdict}] {here.scenario}");
        if here.executed {
            self.runtime_executed = True;
        }
        self.depth_remaining = self.depth_remaining - 1;
        if self.depth_remaining <= 0 {
            disengage;
        }
        visit [-->] else { disengage; };
    }

    can record_decision with Decision entry {
        key = "decision:" + here.outcome + ":" + here.reasoning;
        if self._seen(key) {
            disengage;
        }
        self._mark(key);

        # Confirm the five bounded-critical-path findings were all classified.
        needed = ["#5", "#8", "#53", "#54", "#55"];
        covered = 0;
        for fid in self.seen_findings {
            for n in needed {
                if fid == n {
                    covered = covered + 1;
                }
            }
        }
        print(f"[COVERAGE] {covered} of 5 bounded-critical-path findings seen");

        # Publish exactly one outcome.
        if not self.commands_passed {
            here.outcome = "NO-GO";
            here.reasoning = "An acceptance command failed on the frozen baseline.";
        } elif not self.runtime_executed {
            here.outcome = "NO-GO";
            here.reasoning = "Required visible runtime exercise did not execute.";
        } elif covered < 5 {
            here.outcome = "NO-GO";
            here.reasoning = "Bounded critical path was not fully classified.";
        } else {
            here.outcome = "CONDITIONAL GO";
            here.reasoning = "No exit blocker remains; accepted risks documented with owners and boundaries.";
        }
        print(f"[DECISION] {here.outcome} -- {here.reasoning}");
    }

    # Helpers (methods on a walker — self is implicit).
    def _seen(key: str) -> bool {
        for k in self.visited {
            if k == key {
                return True;
            }
        }
        return False;
    }

    def _mark(key: str) -> None {
        self.visited.append(key);
    }
}

