"""GitHub Actions CI pipeline modeled as a typed-edge graph.

Stages are connected by DependsOn edges (the CI dependency order). Jobs own
their stages via AssignedTo edges. A walker enforces the pipeline sequence,
detects cycles, and halts when a critical stage fails. The runner has been
folded into the Stage node (it just carries a host label); the whole demo is
self-contained and avoids any filesystem state.
"""

node Stage {
    has title: str = "";
    has command: str = "";
    has passed: bool = False;
    has critical: bool = True;
    has host: str = "";
}

node Job {
    has name: str = "";
}

edge DependsOn {
    has order: int = 0;
}

edge AssignedTo {
    has slot: int = 0;
}

walker CIPipeline {
    has blocked: bool = False;
    has visited: list[str] = [];

    can start with Root entry {
        print("git push received -> GitHub Actions triggered");
        visit [-->];
    }

    can enter_job with Job entry {
        print(f"  [job] {here.name}");
        visit [-->];
    }

    can run_stage with Stage entry {
        # Cycle guard: stages are tracked by title; revisit = cycle.
        for tag in self.visited {
            if tag == here.title {
                cycle_msg = f"    CYCLE detected at stage '{here.title}'";
                print(cycle_msg);
                self.blocked = True;
                disengage;
            }
        }
        self.visited.append(here.title);

        if not here.passed {
            outcome = "FAIL";
            print(f"    [{outcome}] {here.title}: {here.command} on {here.host}");
            if here.critical {
                self.blocked = True;
                print("    critical stage failed -> workflow halted");
                disengage;
            }
        } else {
            print(f"    [PASS] {here.title}: {here.command} on {here.host}");
        }
        visit [-->];
    }
}

