import io;
import from contextlib { redirect_stdout }

test "passes a green stage through typed edges" {
    job = Job(name="tests");
    stage = Stage(title="tests", command="pytest", passed=True, critical=True, host="ubuntu");
    next_stage = Stage(title="build", command="python -m build", passed=True, critical=True, host="ubuntu");

    root ++> job;
    job +>:AssignedTo(slot=0):+> stage;
    stage +>:DependsOn(order=1):+> next_stage;

    assert len([root-->]) == 1, f"got {len([root-->])} root children";
    assert job in [root-->], f"missing job child";
    assert stage in [job ->:AssignedTo:->], f"missing assigned stage";
    assert next_stage in [stage ->:DependsOn:->], f"missing dependency";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        runner = CIPipeline();
        root spawn runner;
    }
    out = buf.getvalue();

    assert runner.blocked == False, f"workflow unexpectedly blocked: {out}";
    assert "[PASS] tests" in out, f"missing tests pass: {out}";
    assert "[PASS] build" in out, f"missing build pass: {out}";
}

test "halts on a critical failed stage" {
    job = Job(name="lint");
    failed_stage = Stage(title="lint", command="ruff check", passed=False, critical=True, host="ubuntu");
    downstream = Stage(title="build", command="python -m build", passed=True, critical=True, host="ubuntu");

    root ++> job;
    job +>:AssignedTo(slot=0):+> failed_stage;
    failed_stage +>:DependsOn(order=1):+> downstream;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        runner = CIPipeline();
        root spawn runner;
    }
    out = buf.getvalue();

    assert runner.blocked == True, f"failed stage did not block: {out}";
    assert "[FAIL] lint" in out, f"missing failure output: {out}";
    assert "critical stage failed -> workflow halted" in out, f"missing halt output: {out}";
    assert "[PASS] build" not in out, f"downstream stage ran: {out}";
}

test "detects a dependency cycle" {
    job = Job(name="tests");
    first = Stage(title="tests", command="pytest", passed=True, critical=True, host="ubuntu");
    second = Stage(title="lint", command="ruff check", passed=True, critical=True, host="ubuntu");

    root ++> job;
    job +>:AssignedTo(slot=0):+> first;
    first +>:DependsOn(order=0):+> second;
    second +>:DependsOn(order=1):+> first;

