"""Azure Compute Gallery image lineage: model VM image versions, their
typed parent/child derivation chain, and walk the ancestry with a
lineage auditor. Recursive, immutable, cycle-safe."""

# ---------------------------------------------------------------------------
# Core entity archetypes
# ---------------------------------------------------------------------------

node Resource {
    has resource_id: str = "";
    has resource_type: str = "";
    has subscription: str = "";
    has tenant: str = "";
    has created_at: str = "";
    has content_hash: str = "";
    has lineage_unavailable: bool = False;
}

node GalleryImageVersion(Resource) {
    has version_name: str = "";
    has published: bool = False;
}

node ManagedImage(Resource) {
    has image_name: str = "";
}

node ManagedDisk(Resource) {
    has disk_name: str = "";
    has size_gb: int = 0;
}

node Snapshot(Resource) {
    has snapshot_name: str = "";
}

# ---------------------------------------------------------------------------
# Typed edges: derivation relationships carry the workflow that produced the
# child artifact. The payloads are kept so traversal and reporting can show
# exactly how a child was produced from its parent.
# ---------------------------------------------------------------------------

edge DerivedFrom {
    has workflow: str = "";
    has recorded_at: str = "";
}

# ---------------------------------------------------------------------------
# Walker: Lineage Auditor
#
# Walks the derivation graph upward via [<-:DerivedFrom:<-] from any starting
# artifact, accumulating the full ancestry chain up to a golden root. Cycle
# policy is explicit: a guard set tracks visited nodes because jac 0.36.1
# walkers have no built-in dedupe on cyclic graphs.
# ---------------------------------------------------------------------------

walker LineageAuditor {
    has visited_ids: list[str] = [];
    has lineage_chain: list[dict] = [];
    has root_reached: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can audit with Resource entry {
        # Cycle policy: refuse to re-visit a node we've already audited so
        # cyclic derivation chains (e.g. mutual copies) cannot hang the walk.
        if here.resource_id in self.visited_ids {
            print(f"[cycle] revisiting {here.resource_id}; stopping upward walk");
            self.root_reached = True;
            disengage;
        }
        self.visited_ids.append(here.resource_id);

        if here.lineage_unavailable {
            print(f"[imported] {here.resource_id} ({here.resource_type}) "
                  f"-- lineage unavailable, was imported externally");
            self.root_reached = True;
            disengage;
        }

        record = {
            "resource_id": here.resource_id,
            "resource_type": here.resource_type,
            "subscription": here.subscription,
            "tenant": here.tenant,
            "created_at": here.created_at,
            "content_hash": here.content_hash,
            "lineage_unavailable": here.lineage_unavailable,
        };
        self.lineage_chain.append(record);
        print(f"[step] {here.resource_id} ({here.resource_type}) "
              f"sub={here.subscription} tenant={here.tenant} "
              f"hash={here.content_hash}");

        # Walk upward along the derivation edge. If there is no parent we
        # have reached the root source of this lineage.
        parents = [<-:DerivedFrom:<-];
        if parents {
            visit parents;
        } else {
            self.root_reached = True;
            print(f"[root] reached golden source: {here.resource_id}");
        }
    }
}

# ---------------------------------------------------------------------------
# Walker: Cycle Detector
#
# Starts from any node and reports whether a cycle is reachable in the
# derivation graph. Uses the same guard-set policy as the auditor.
# ---------------------------------------------------------------------------

walker CycleDetector {
    has visited_ids: list[str] = [];
    has cycle_found: bool = False;

    can start with Root entry {
        visit [-->];
    }

    can probe with Resource entry {
        if here.resource_id in self.visited_ids {
            self.cycle_found = True;
            print(f"[cycle] re-entered {here.resource_id}");
            disengage;
        }
        self.visited_ids.append(here.resource_id);

        children = [->:DerivedFrom:->];
        if children {
            visit children;
        }
    }
}

