"""Tests for RiskAssessor blast-radius walker behavior.

The bug being modeled: counting unique physical assets affected by a
workflow must look at the System nodes reachable via typed Exposes
edges, not at the URL strings or operation types on Endpoint nodes.
"""

import io;
import from contextlib { redirect_stdout }

test "two distinct systems same operation count as two assets" {
    # Bug repro: both endpoints carry operation="EthernetInterfaces" but
    # point to different physical systems. Naive last-segment logic would
    # collapse these to one. The walker must report 2 unique assets.
    rt = root;
    sys_a = System(system_id="System.Embedded.1");
    sys_b = System(system_id="System.Embedded.2");

    ep_a = Endpoint(
        url="/redfish/v1/Systems/System.Embedded.1/EthernetInterfaces",
        operation="EthernetInterfaces",
    );
    ep_b = Endpoint(
        url="/redfish/v1/Systems/System.Embedded.2/EthernetInterfaces",
        operation="EthernetInterfaces",
    );

    wf = Workflow(name="PatchEthernet");

    rt ++> wf;
    wf +>:Touches:+> ep_a;
    wf +>:Touches:+> ep_b;
    ep_a +>:Exposes(note="binding"):+> sys_a;
    ep_b +>:Exposes(note="binding"):+> sys_b;

    auditor = BlastAuditor();
    wf spawn auditor;

    assert auditor.unique_count == 2, (
        f"expected 2 unique assets, got {auditor.unique_count}; "
        f"seen={auditor.seen}"
    );
    assert auditor.seen == ["System.Embedded.1", "System.Embedded.2"], (
        f"unexpected seen order/contents: {auditor.seen}"
    );
}

test "two endpoints on the same system collapse to one asset" {
    # Distinct Endpoint nodes bound to the SAME System must count once.
    rt = root;
    sys_a = System(system_id="System.Embedded.1");

    ep_a = Endpoint(
        url="/redfish/v1/Systems/System.Embedded.1/EthernetInterfaces",
        operation="EthernetInterfaces",
    );
    ep_b = Endpoint(
        url="/redfish/v1/Systems/System.Embedded.1/EthernetInterfaces/1",
        operation="EthernetInterfaces",
    );

    wf = Workflow(name="PatchEthernet");

    rt ++> wf;
    wf +>:Touches:+> ep_a;
    wf +>:Touches:+> ep_b;
    ep_a +>:Exposes(note="binding"):+> sys_a;
    ep_b +>:Exposes(note="binding"):+> sys_a;

    auditor = BlastAuditor();
    wf spawn auditor;

    assert auditor.unique_count == 1, (
        f"expected 1 unique asset for shared system, got {auditor.unique_count}"
    );
    assert auditor.seen == ["System.Embedded.1"], (
        f"unexpected seen: {auditor.seen}"
    );
}

test "blast multiplier derived from unique asset count" {
    # Per the demo wiring: blast_multiplier = 1.0 + 0.5 * unique_count.
    # Three systems across 3 distinct endpoints -> 1.0 + 0.5*3 = 2.5.
    rt = root;
    sys_a = System(system_id="System.Embedded.1");
    sys_b = System(system_id="System.Embedded.2");
    sys_c = System(system_id="System.Embedded.3");

    ep_a = Endpoint(
        url="/redfish/v1/Systems/System.Embedded.1/EthernetInterfaces",
        operation="EthernetInterfaces",
    );
    ep_b = Endpoint(
        url="/redfish/v1/Systems/System.Embedded.2/EthernetInterfaces",
        operation="EthernetInterfaces",
    );
    ep_c = Endpoint(
        url="/redfish/v1/Systems/System.Embedded.3/EthernetInterfaces",
        operation="EthernetInterfaces",
    );

    wf = Workflow(name="PatchEthernet");

    rt ++> wf;
    wf +>:Touches:+> ep_a;
    wf +>:Touches:+> ep_b;
    wf +>:Touches:+> ep_c;
    ep_a +>:Exposes:+> sys_a;
    ep_b +>:Exposes:+> sys_b;
    ep_c +>:Exposes:+> sys_c;

    auditor = BlastAuditor();
    wf spawn auditor;

    assert auditor.unique_count == 3, (
        f"expected 3 unique assets, got {auditor.unique_count}"
    );

    wf.unique_targets = auditor.unique_count;
    wf.blast_multiplier = 1.0 + 0.5 * auditor.unique_count;

    assert wf.unique_targets == 3, f"wf.unique_targets={wf.unique_targets}";
    assert wf.blast_multiplier == 2.5, (
        f"expected blast_multiplier=2.5, got {wf.blast_multiplier}"
    );
}

test "spawning on root traverses into workflow and reports assets" {
    # Spawning on Root entry visits Root's outgoing edges. From there the
    # walker must reach the Workflow and run the tally. The Walker's
    # printed summary must reflect the unique-asset count derived from
    # System nodes reached via Exposes edges.
    rt = root;
    sys_a = System(system_id="System.Embedded.1");
    sys_b = System(system_id="System.Embedded.2");

    ep_a = Endpoint(
        url="/redfish/v1/Systems/System.Embedded.1/EthernetInterfaces",
        operation="EthernetInterfaces",
    );
    ep_b = Endpoint(
        url="/redfish/v1/Systems/System.Embedded.2/EthernetInterfaces",
        operation="EthernetInterfaces",
    );

    wf = Workflow(name="PatchEthernet");

    rt ++> wf;
    wf +>:Touches:+> ep_a;
    wf +>:Touches:+> ep_b;
    ep_a +>:Exposes:+> sys_a;
    ep_b +>:Exposes:+> sys_b;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = rt spawn BlastAuditor();
        auditor2 = BlastAuditor();
        wf spawn auditor2;

        wf.unique_targets = auditor2.unique_count;
        wf.blast_multiplier = 1.0 + 0.5 * auditor2.unique_count;

        print(
            f"workflow={wf.name} unique_assets={wf.unique_targets} "
            f"blast_multiplier={wf.blast_multiplier}"
        );
        print(f"seen asset ids: {auditor2.seen}");
    }
    out = buf.getvalue();

    assert "unique_assets=2" in out, f"missing unique_assets=2 in: {out}";
    assert "blast_multiplier=2.0" in out, f"missing blast_multiplier=2.0 in: {out}";
    assert "System.Embedded.1" in out, f"missing sys_a id in: {out}";
    assert "System.Embedded.2" in out, f"missing sys_b id in: {out}";
}

test "graph shape: workflow touches endpoints which expose systems" {
    # Assert the typed-edge topology that makes the walker correct:
    # Workflow --Touches--> Endpoint --Exposes--> System.
    rt = root;
    sys_a = System(system_id="System.Embedded.1");
    sys_b = System(system_id="System.Embedded.2");

    ep_a = Endpoint(
        url="/redfish/v1/Systems/System.Embedded.1/EthernetInterfaces",
        operation="EthernetInterfaces",
    );
    ep_b = Endpoint(
        url="/redfish/v1/Systems/System.Embedded.2/EthernetInterfaces",
        operation="EthernetInterfaces",
    );

    wf = Workflow(name="PatchEthernet");

    rt ++> wf;
    wf +>:Touches:+> ep_a;
    wf +>:Touches:+> ep_b;
    ep_a +>:Exposes:+> sys_a;
    ep_b +>:Exposes:+> sys_b;

    assert wf in [rt -->], "wf must be linked from root";

    touched = [wf ->:Touches:->];
    assert len(touched) == 2, f"expected 2 Touches edges from wf, got {len(touched)}";
    assert ep_a in touched and ep_b in touched, (
        f"touched edges should include both endpoints: {touched}"
    );

    assert sys_a in [ep_a ->:Exposes:->], (
        "ep_a must Expose sys_a via a typed Exposes edge"
    );
    assert sys_b in [ep_b ->:Exposes:->], (
        "ep_b must Expose sys_b via a typed Exposes edge"
    );

    # Walker result must reflect physical-asset identity, not operation string.
    auditor = BlastAuditor();
    wf spawn auditor;
    assert auditor.unique_count == 2, (
        f"operation strings must NOT collapse distinct systems; "
        f"got unique_count={auditor.unique_count}"
    );
}

