"""Sandbox credential scoping: model the admin-scoped env-var bug from issue #1344.

Core scenario: BigQuery-CLI jobs run as `job.requestedBy`, but sandbox env
resolution is gated by a role-tier hierarchy. A `member`-level owner asking
for an `admin`-scoped credential (e.g. `google_sa_key_b64`) gets an empty
value injected, so the CLI activation command silently fails with
`exit status 1`.

This demo models that mismatch with a typed-edge graph and walks it with a
walker that reports exactly the silent-empty-injection failure mode.
"""

node User {
    has name: str = "";
    has level: int = 0;  # member=0, power_user=1, admin=2
}

node Credential {
    has env_var: str = "";
    has scope_level: int = 0;  # minimum role tier required to see this var
}

node Job {
    has title: str = "";
    has requested_by: str = "";
}

edge Owns {}
edge Requires {}
edge Granted {}

walker CredentialAuditor {
    has findings: list[str] = [];
    has guard: set[str] = set();  # explicit cycle policy (jac 0.36.1 has none built-in)

    can start with Root entry {
        visit [-->];
    }

    can audit with Job entry {
        self.guard.add(here.title);
        # A job references some required credentials via typed `Requires` edges.
        visit [->:Requires:->];
    }

    can inspect with Credential entry {
        # Walk back to the User via `Owns`, then forward to `Granted` creds
        # the sandbox resolver would have picked for that user.
        visit [<--:Owns:--];
    }

    can compare with User entry {
        # Look at every Granted credential the sandbox would inject for
        # this user and check whether the Job's Required credentials are
        # all covered at the user's role tier.
        for granted in [->:Granted:->] {
            for required in [<--:Requires:--] {
                if granted.env_var == required.env_var {
                    if here.level < required.scope_level {
                        finding = (
                            f"[SILENT-EMPTY] job '{required.title}' "
                            f"requested by '{here.name}' (level={here.level}) "
                            f"needs '{granted.env_var}' "
                            f"(scope_level={required.scope_level})"
                        );
                        self.findings.append(finding);
                    } else {
                        ok = (
                            f"[OK] job '{required.title}' requested by "
                            f"'{here.name}' has '{granted.env_var}' "
                            f"at scope_level={required.scope_level}"
                        );
                        self.findings.append(ok);
                    }
                }
            }
        }
    }
}

with entry {
    # Two users: Nuria (member) and an admin. Same scenario as the issue.
    nuria = User(name="Nuria Verdejo", level=0);
    admin = User(name="Mako Admin", level=2);

    # Credentials the sandbox knows about (mirrors sandbox.ts resolveUserCredentials).
    google_sa = Credential(env_var="GOOGLE_SA_KEY_B64", scope_level=2);  # admin-scoped, the bug.
    basic_token = Credential(env_var="WORKSPACE_TOKEN", scope_level=0);  # member-scoped, fine.

    # Jobs owned by users (mirrors execute-job.ts:335 getSandboxEnvs(job.requestedBy)).
    prospect = Job(title="nuria-daily-prospect-list", requested_by="Nuria Verdejo");
    prospect_test = Job(title="nuria-daily-prospect-test", requested_by="Nuria Verdejo");
    admin_job = Job(title="mako-nightly-etl", requested_by="Mako Admin");

    # Wire the graph: User --Owns--> Job --Requires--> Credential
    #                 User --Granted--> Credential (what the sandbox would inject)
    nuria +>:Owns:+> prospect;
    nuria +>:Owns:+> prospect_test;
    admin +>:Owns:+> admin_job;

    prospect +>:Requires:+> google_sa;       # the wall from the issue
    prospect +>:Requires:+> basic_token;
    prospect_test +>:Requires:+> google_sa;  # 3x failures from the report
    admin_job +>:Requires:+> basic_token;

    # Granted set: nuria is a member, so google_sa is NEVER granted to her.
    nuria +>:Granted:+> basic_token;
    admin +>:Granted:+> google_sa;
    admin +>:Granted:+> basic_token;

    auditor = CredentialAuditor();
    root spawn auditor;

    print("=== credential audit findings ===");
    for line in auditor.findings {
        print(line);
    }
    print(f"=== {len(auditor.findings)} findings ===");
}

fixed.code:
"""BigQuery job credential scoping: model the silent admin-credential loss.

Walks a job graph from owner → job → script → referenced env vars, evaluates
each env var's required scope against the owner's role tier, and reports the
silently-empty admin credentials that break member-owned jobs.
"""

node Owner {
    has name: str = "";
    has role: str = "member";      # member | power_user | admin
}

node Job {
    has title: str = "";
    has status: str = "scheduled"; # scheduled | running | failed | stale_killed
    has minutes_stale: int = 0;
}

node Script {
    has body: str = "";
}

node Credential {
    has env_var: str = "";
    has scope: str = "member";     # member | power_user | admin
}

edge Owns { }
edge Runs { }
edge References { }
edge Requires { }

walker CredentialAuditor {
    has failures: list[str] = [];
    has tier_map: dict[str, int] = {"member": 0, "power_user": 1, "admin": 2};

    can start with Root entry {
        visit [-->];
    }

    can audit_owner with Owner entry {
        visit [->:Owns:->];
    }

    can audit_job with Job entry {
        visit [->:Runs:->];
    }

    can audit_script with Script entry {
        visit [->:References:->];
    }

    can audit_credential with Credential entry {
        # Walk back to the owner of the job that referenced this credential.
        # The walker doesn't natively reverse, so we re-derive via `here`'s
        # context: every credential is only reached through Owner→Owns→Job→
        # Runs→Script→References→Credential on this demo graph.
        needed = self.tier_map[here.scope] if here.scope in self.tier_map else 0;
        # The owner is whichever Owner spawned this walker (we mirror it).
        owner_level = self.tier_map[self.owner_role] if self.owner_role in self.tier_map else 0;
        if owner_level < needed {
            note = (f"SILENT FAIL: job owner (role={self.owner_role}) "
                    f"cannot access {here.env_var} (scope={here.scope})");
            self.failures.append(note);
        }
        visit [-->] else { disengage; }
    }

    has owner_role: str = "member";
}

with entry {
    # Two demo owners: an admin and a member — same script reference graph.
    admin_owner = Owner(name="Admin Root", role="admin");
    member_owner = Owner(name="Nuria Verdejo", role="member");

    # A member-owned daily job that depends on an admin-scoped credential.
    nuria_job = Job(title="nuria-daily-prospect-list", status="stale_killed", minutes_stale=200);
    prospect_script = Script(body="echo $GOOGLE_SA_KEY_B64 | base64 -d > /tmp/sa.json; gcloud auth activate-service-account --key-file=/tmp/sa.json");

    # An admin-scoped warehouse service-account credential.
    sa_cred = Credential(env_var="GOOGLE_SA_KEY_B64", scope="admin");

    # Wire the dependency chain: owner OWNS job, job RUNS script, script
    # REFERENCES the credential, and the credential REQUIRES admin scope.
