"""Test annex for the M3C orphan-vertex modeling demo.

The issue is about M3C's compaction: candidates with `node_type > 0` are
kept as output vertices, but some of them are unreferenced by any
triangle. Approach 1 (MarkingAudit) reports the orphan count; approach 2
(CompactionAudit) shows what compaction would emit if it dropped
unreferenced kept candidates. These tests pin down both behaviors and
the graph shape that drives them.
"""

import io;
import from contextlib { redirect_stdout }

test "marking audit reports the c3 orphan and excludes node_type=0" {
    # Fresh graph mirroring the demo's candidate/triangle topology.
    c1 = Candidate(label="c1", node_type=2, referenced=True);
    c2 = Candidate(label="c2", node_type=3, referenced=True);
    c3 = Candidate(label="c3", node_type=4, referenced=False);
    c4 = Candidate(label="c4", node_type=0, referenced=False);
    root ++> c1 ++> c2 ++> c3 ++> c4;

    t1 = Triangle(label="t1");
    t2 = Triangle(label="t2");
    root ++> t1 +>:Uses(slot=0):+> c1;
    root ++> t1 +>:Uses(slot=1):+> c2;
    root ++> t2 +>:Uses(slot=0):+> c1;
    root ++> t2 +>:Uses(slot=2):+> c2;

    a1 = MarkingAudit();
    res = root spawn a1;
    assert res.kept_count == 3, f"c1/c2/c3 are kept (node_type>0); got {res.kept_count}";
    assert res.unreferenced_kept == 1, f"only c3 is orphan; got {res.unreferenced_kept}";
    assert res.orphan_labels == ["c3"], f"orphan labels wrong: {res.orphan_labels}";
}

test "compaction audit drops unreferenced kept candidates" {
    c1 = Candidate(label="c1", node_type=2, referenced=True);
    c2 = Candidate(label="c2", node_type=3, referenced=True);
    c3 = Candidate(label="c3", node_type=4, referenced=False);
    c4 = Candidate(label="c4", node_type=0, referenced=False);
    root ++> c1 ++> c2 ++> c3 ++> c4;

    t1 = Triangle(label="t1");
    root ++> t1 +>:Uses(slot=0):+> c1;
    root ++> t1 +>:Uses(slot=1):+> c2;

    a2 = CompactionAudit();
    res = root spawn a2;
    assert sorted(res.emitted) == ["c1", "c2"], f"emitted labels: {res.emitted}";
    assert res.skipped_orphans == ["c3"], f"skipped orphans: {res.skipped_orphans}";
}

test "compaction does not skip node_type=0 candidates" {
    # A candidate with node_type=0 is already dropped by the prefix-scan,
    # so it must not appear in skipped_orphans (which tracks the orphan
    # class: kept-but-unreferenced).
    c1 = Candidate(label="c1", node_type=2, referenced=True);
    c_unref_kept = Candidate(label="cu", node_type=1, referenced=False);
    c_zero = Candidate(label="cz", node_type=0, referenced=False);
    root ++> c1 ++> c_unref_kept ++> c_zero;

    t1 = Triangle(label="t1");
    root ++> t1 +>:Uses(slot=0):+> c1;

    a2 = CompactionAudit();
    res = root spawn a2;
    assert res.emitted == ["c1"], f"only c1 emitted: {res.emitted}";
    assert res.skipped_orphans == ["cu"], f"only 'cu' is a kept-orphan: {res.skipped_orphans}";
    assert "cz" not in res.skipped_orphans, "node_type=0 must not be classified as orphan";
}

test "demo entry block prints the issue's two summary lines" {
    # Build the demo's graph fresh in this test (entry block is stripped
    # by the harness, so we replay its setup and capture stdout).
    c1 = Candidate(label="c1", node_type=2, referenced=True);
    c2 = Candidate(label="c2", node_type=3, referenced=True);
    c3 = Candidate(label="c3", node_type=4, referenced=False);
    c4 = Candidate(label="c4", node_type=0, referenced=False);
    root ++> c1 ++> c2 ++> c3 ++> c4;

    t1 = Triangle(label="t1");
    t2 = Triangle(label="t2");
    root ++> t1 +>:Uses(slot=0):+> c1;
    root ++> t1 +>:Uses(slot=1):+> c2;
    root ++> t2 +>:Uses(slot=0):+> c1;
    root ++> t2 +>:Uses(slot=2):+> c2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        a1 = MarkingAudit();
        root spawn a1;
        print(f"approach1 kept={a1.kept_count} "
              f"orphan_kept={a1.unreferenced_kept} "
              f"labels={a1.orphan_labels}");

        a2 = CompactionAudit();
        root spawn a2;
        print(f"approach2 emitted={a2.emitted} "
              f"dropped_orphans={a2.skipped_orphans}");

