    assert "approach2 emitted=['c1', 'c2'] dropped_orphans=['c3']" in out, f"missing approach2 line: {out}";
    assert "post-fix: only referenced+kept candidates became OutputVertex nodes" in out, f"missing post-fix line: {out}";
}

test "OutputVertex rewrite produces exactly the referenced+kept set" {
    # After running CompactionAudit and materializing OutputVertex nodes
    # for each emitted label, root should have exactly 2 OutputVertex
    # children labeled c1 and c2.
    c1 = Candidate(label="c1", node_type=2, referenced=True);
    c2 = Candidate(label="c2", node_type=3, referenced=True);
    c3 = Candidate(label="c3", node_type=4, referenced=False);
    c4 = Candidate(label="c4", node_type=0, referenced=False);
    root ++> c1 ++> c2 ++> c3 ++> c4;

    t1 = Triangle(label="t1");
    root ++> t1 +>:Uses(slot=0):+> c1;
    root ++> t1 +>:Uses(slot=1):+> c2;

    a2 = CompactionAudit();
    res = root spawn a2;
    for label in res.emitted {
        root ++> OutputVertex(label=label);
    }

    outs = [root -->][?:OutputVertex];
    labels = sorted([o.label for o in outs]);
    assert labels == ["c1", "c2"], f"expected 2 OutputVertex nodes labeled c1,c2, got {labels}";
    assert len(outs) == 2, f"expected 2 OutputVertex nodes, got {len(outs)}";
}

