"""Tests for Stephanos Codex dispatch bridge demo.

Each test builds its own fresh subgraph and spawns Bridge, capturing stdout
to verify the canonical lifecycle: canonicalize -> claim -> execute -> review,
plus the fail-closed duplicate guard.
"""

import io;
import from contextlib { redirect_stdout }

def make_chain {
    instr = RepairInstruction(
        title="Wire guarded implementation pickup",
        issue_number=1622,
        source_head="abc123",
        branch="codex/implementation-1622",
        bounded_scope="src/dispatch/implementation.py"
    );
    dispatch = DispatchRecord(
        task_id="impl-1622",
        exact_head="abc123",
        branch="codex/implementation-1622",
        lease_id="lease-7f2",
        status="OPEN"
    );
    claim = ClaimReceipt(
        worker_id="",
        task_id="impl-1622",
        exact_head="abc123",
        branch="codex/implementation-1622",
        lease_id="lease-7f2",
        heartbeat=0
    );
    review = ReviewDispatch(task_id="impl-1622");
    return [instr, dispatch, claim, review];
}

test "canonical lifecycle emits all four stages and flips review verdict" {
    chain = make_chain();
    root +>:CanonicalizedAs:+> chain[0]
        +>:ClaimedBy:+> chain[1]
        +>:ExecutesUnder:+> chain[2]
        +>:ReviewedBy:+> chain[3];

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Bridge();
    }
    out = buf.getvalue();

    assert "[bridge] worker-01 begins canonical lifecycle walk" in out, f"missing start: {out}";
    assert "canonicalizing instruction 'Wire guarded implementation pickup' (issue #1622)" in out,
        f"missing canonicalize: {out}";
    assert "heartbeat 1 on impl-1622" in out, f"missing execute/heartbeat: {out}";
    assert "review dispatched for impl-1622: ACCEPTED" in out, f"missing review: {out}";
    assert chain[3].verdict == "ACCEPTED", f"verdict not flipped, got {chain[3].verdict}";
    assert chain[3].reviewer == "exact-head-reviewer",
        f"reviewer not assigned, got {chain[3].reviewer}";
}

test "claim receipt binds worker and bumps heartbeat exactly once" {
    chain = make_chain();
    root +>:CanonicalizedAs:+> chain[0]
        +>:ClaimedBy:+> chain[1]
        +>:ExecutesUnder:+> chain[2]
        +>:ReviewedBy:+> chain[3];

    _ = root spawn Bridge(worker_id="worker-42");

    assert chain[2].worker_id == "worker-42",
        f"worker not bound, got {chain[2].worker_id}";
    assert chain[2].heartbeat == 1,
        f"heartbeat should be exactly 1, got {chain[2].heartbeat}";
    assert chain[2].task_id == "impl-1622",
        f"task_id propagated wrong: {chain[2].task_id}";
    assert chain[2].exact_head == "abc123",
        f"exact_head drifted: {chain[2].exact_head}";
}

test "duplicate or conflicting dispatch is rejected fail-closed" {
    chain = make_chain();
    # Pre-mark the dispatch as a duplicate/conflicting active task.
    chain[1].status = "OPEN";
    chain[1].duplicate = True;
    root +>:CanonicalizedAs:+> chain[0]
        +>:ClaimedBy:+> chain[1]
        +>:ExecutesUnder:+> chain[2]
        +>:ReviewedBy:+> chain[3];

    buf = io.StringIO();
    with redirect_stdout(buf) {
        _ = root spawn Bridge();
    }
    out = buf.getvalue();

    assert "reject: duplicate/conflicting dispatch impl-1622" in out,
        f"missing reject marker: {out}";
    # Execute stage must NOT have run: heartbeat stays 0, worker empty,
    # review verdict stays PENDING.
    assert chain[2].heartbeat == 0,
        f"heartbeat mutated under reject: {chain[2].heartbeat}";
    assert chain[2].worker_id == "",
        f"worker bound despite reject: {chain[2].worker_id}";
    assert chain[3].verdict == "PENDING",
        f"review flipped despite reject: {chain[3].verdict}";
}

test "exact-head mismatch prevents claim from transitioning to CLAIMED" {
    chain = make_chain();
