    root +>:CanonicalizedAs:+> chain[0]
        +>:ClaimedBy:+> chain[1]
        +>:ExecutesUnder:+> chain[2]
        +>:ReviewedBy:+> chain[3];

    # DispatchRecord is OPEN and not marked duplicate, so the claim
    # ability will accept it -- the bridge itself does not enforce head
    # equality; the test confirms status transitions cleanly when the
    # only divergence is the instruction-side head metadata.
    _ = root spawn Bridge();

    assert chain[1].status == "CLAIMED",
        f"status should transition to CLAIMED, got {chain[1].status}";
    assert chain[1].duplicate == False,
        f"duplicate flag should remain False, got {chain[1].duplicate}";
    # The instruction-side head is preserved untouched.
    assert chain[0].source_head == "different-head",
        f"instruction head mutated: {chain[0].source_head}";
    # The dispatch's exact_head and the claim's exact_head must agree.
    assert chain[1].exact_head == chain[2].exact_head,
        f"dispatch/claim head divergence: {chain[1].exact_head} vs {chain[2].exact_head}";
