test "graph shape preserves the canonical five-node, four-edge chain" {
    chain = make_chain();
    root +>:CanonicalizedAs:+> chain[0]
        +>:ClaimedBy:+> chain[1]
        +>:ExecutesUnder:+> chain[2]
        +>:ReviewedBy:+> chain[3];

