    assert len(instrs) == 1, f"expected 1 CanonicalizedAs from root, got {len(instrs)}";
    dispatches = [chain[0] ->:ClaimedBy:->];
    assert len(dispatches) == 1,
        f"expected 1 ClaimedBy from instruction, got {len(dispatches)}";
    claims = [chain[1] ->:ExecutesUnder:->];
    assert len(claims) == 1,
        f"expected 1 ExecutesUnder from dispatch, got {len(claims)}";
    reviews = [chain[2] ->:ReviewedBy:->];
    assert len(reviews) == 1,
        f"expected 1 ReviewedBy from claim, got {len(reviews)}";

    # Exactly one active implementation job + one lease binding.
    assert chain[1].lease_id == "lease-7f2",
        f"lease lost: {chain[1].lease_id}";
    assert chain[2].lease_id == chain[1].lease_id,
        f"lease not propagated to claim: {chain[2].lease_id} vs {chain[1].lease_id}";

    _ = root spawn Bridge();
    assert chain[3].verdict == "ACCEPTED",
        f"end-to-end cycle did not terminalize review: {chain[3].verdict}";
}

