    has triggered_at: str = "";
}

edge FrozenAt {
    has freeze_ts: str = "";
}

edge Snapshotted {
    has snapshot_role: str = "";
}

edge CapturedRow {
    has ordinal: int = 0;
}

edge PairedWith {
}

edge EmitsSidecar {
    has ordinal: int = 0;
}

walker SidecarAuditor {
    has missing_rows: list = [];
    has broken_pings: list = [];
    has report: dict = {};

    can begin with Root entry {
        print(f"Auditor scanning lineage from root at {self.report}");
        visit [-->];
    }

    can audit with DataPing entry {
        if not here.accepted {
            visit [-->];
            disengage;
        }
        sidecars = [-->EmitsSidecar:->];
        if sidecars.length == 0 {
            self.broken_pings.append(here.ping_id);
            here.bread_replayability = "FAIL";
            visit [-->];
            disengage;
        }
        can start with Sidecar entry {
            sc = here;
            rows = [->:CapturedRow:->];
            if rows.length != sc.row_count {
                self.broken_pings.append(sc.path);
                sc.replayability = "FAIL";
            }
            self.report["sidecar"] = sc.content_sha256;
            visit [-->];
        }
        for sc in sidecars {
            sc spawn SidecarAuditor();
        }
        visit [-->];
    }
}

