            if here.replayability != "PASS" or here.artifact_bytes == 0 or here.row_count == 0 {
                self.fail_closed = True;
                disengage;
            }
            visit [->:Retains:->];
        }

        can record_page with CoinPage entry {
            self.pages_seen += 1;
            self.membership_hashes.append(here.membership_sha256);
            self.breadth_ratios.append(here.breadth_ratio);
            self.hops += 1;
            visit [->:Retains:->];
        }

        can record_row with ConstituentRow entry {
            self.rows_seen += 1;
            self.hops += 1;
            visit [->:Retains:->];
        }
    }

    walker ReplayWalker {
        has expected_breadth: float = 0.0;
        has expected_hash: str = "";
        has recovered_breadth: float = 0.0;
        has recovered_hash: str = "";
        can start with Root entry {
            visit [->:Retains:->];
