        can walk_to_page with DataPing | Sidecar entry {
            visit [->:Retains:->];
        }
        can replay_page with CoinPage entry {
            self.recovered_breadth = here.breadth_ratio;
            self.recovered_hash = here.membership_sha256;
            visit [->:Retains:->];
        }
    }

    lineage_walker = LineageWalker();
    root spawn lineage_walker;

    print("Lineage hops:", lineage_walker.hops);
    print("Rows seen:", lineage_walker.rows_seen);
    print("Pages seen:", lineage_walker.pages_seen);
    print("Membership hashes collected:", lineage_walker.membership_hashes);
    print("Breadth ratios collected:", lineage_walker.breadth_ratios);
    print("Fail-closed triggered:", lineage_walker.fail_closed);

    replay_walker = ReplayWalker(expected_breadth=0.55, expected_hash="b2" + "0" * 62);
    ping spawn replay_walker;
    print("Replay breadth match:",
        replay_walker.recovered_breadth == replay_walker.expected_breadth);
