    );
    page2 = CoinPage(
        page_label="page-2",
        page_timestamp="2026-07-29T00:00:00Z",
        membership_sha256="b2" + "0" * 62,
        breadth_ratio=0.55
    );

    sidecar +>:Retains(slot="page-1"):+> page1;
    sidecar +>:Retains(slot="page-2"):+> page2;

    assert page1.page_timestamp == "2026-07-28T23:59:30Z", f"page1 timestamp substituted, got {page1.page_timestamp}";
    assert page2.page_timestamp == "2026-07-29T00:00:00Z", f"page2 timestamp substituted, got {page2.page_timestamp}";
    assert page1.page_timestamp != page2.page_timestamp, f"page pair must retain distinct source timestamps";
    assert sidecar.retrieved_at == "2026-07-29T00:00:01Z", f"retrieved_at missing, got {sidecar.retrieved_at}";
    assert sidecar.frozen_at == "2026-07-29T00:00:02Z", f"frozen_at missing, got {sidecar.frozen_at}";
    assert sidecar.frozen_at != sidecar.retrieved_at, f"freeze must differ from retrieval";
    assert page2.breadth_ratio == 0.55, f"replay breadth must come from retained page, got {page2.breadth_ratio}";
    assert page2.membership_sha256 == "b2" + "0" * 62, f"replay hash must come from retained page";
