    assert excluded_row.return_24h == -0.04, f"excluded return must not be zeroed, got {excluded_row.return_24h}";

    assert missing_row.coin_id == "", f"missing coin_id must stay unknown not fabricated, got {missing_row.coin_id}";
    assert missing_row.symbol == "", f"missing symbol must stay unknown not fabricated, got {missing_row.symbol}";
    assert missing_row.rank == 0, f"missing rank must stay unknown not fabricated as nonzero, got {missing_row.rank}";
    assert missing_row.reason_code == "", f"missing row must not invent a reason, got {missing_row.reason_code}";

    page_children = [page ->:Retains:->];
    assert len(page_children) == 2, f"retained rows count wrong, got {len(page_children)}";
    assert missing_row not in page_children, f"missing row must not be fabricated into lineage";
}

