"""Tests for recursive module resolution walker."""

import io;
import from contextlib { redirect_stdout }


test "walker records the trace of visited shared roots" {
    proj = Project(name="webapp", base_dir="/repo/apps/webapp");
    sr_a = SharedRoot(directory_name="shared/components");
    sr_b = SharedRoot(directory_name="shared/utils");
    sr_c = SharedRoot(directory_name="shared/legacy", drained=True);
    proj +>:OwnedBy:+> sr_a;
    proj +>:OwnedBy:+> sr_b;
    proj +>:OwnedBy:+> sr_c;
    proj +>:SearchedAt:+> sr_a;
    proj +>:SearchedAt:+> sr_b;
    proj +>:SearchedAt:+> sr_c;

    req = ImportRequest(specifier="components/Button", status="pending");
    root ++> req;
    req +>:Requests:+> proj;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        resolver = ResolveRequest();
        req spawn resolver;
    }
    out = buf.getvalue();
    assert "shared/components" in resolver.trace, f"trace={resolver.trace}, out={out}";
    assert "shared/utils" in resolver.trace, f"trace={resolver.trace}, out={out}";
    assert "shared/legacy" not in resolver.trace, (
        f"drained root must be skipped, trace={resolver.trace}, out={out}"
    );
    assert len(resolver.trace) == 2, f"expected 2 roots, got {resolver.trace}";
}


test "first matching module wins among resolved candidates" {
