# Live statement tail returns to the next iteration step.
edge LiveTailBack { }

# Terminal statement tail must NOT loop back (verifier rule).
edge TerminalTail { }

# Exhaustion exit after the producer is drained.
edge Exhausts { }

# Topic restoration relationship on every claimed normal/transfer exit.
edge RestoresTopic { }

# --- Walker -------------------------------------------------------------

walker LowerPostfix {
    has issues: list[str] = [];

    can begin with Root entry {
        visit [-->];
