    # Step 1+2: evaluate the iterable once in list context and establish the
    # iteration region + topic place + restoration relationship.
    can establish with PostfixIter entry {
        producers = [->:DemandsList:->];
        bindings = [->:Establishes:->];
        if producers.length == 0 {
