"""Postfix for/foreach iteration: model explicit PIR-A iteration semantics
as typed edges between an iteration region, an iterable producer, an implicit
topic place, and per-iteration statement bindings. A walker descends through
the CFG contract of: establish iterable -> bind topic -> execute body -> back
-> exhaust -> exit, proving the structural shape that downstream consumers
(verifier, transfer-sibling) will hook into.
"""

# ---- Entity archetypes (nodes) ---------------------------------------------

# The iteration region owns the loop body and the back/exit relationships.
node Region {
    has label: str = "";
    has depth: int = 0;
}

# The iterable / list producer. Carries list-context demand and a surface
# spelling so the model can reject "iterable-as-truth-test" misuse.
node Iterable {
    has producer_id: str = "";
    has list_context: bool = True;
    has element_count: int = 0;
}

# The implicit topic place ($_). The iteration binds/aliases an element here
# before the body executes, and restores the prior topic on every exit.
node Topic {
    has place_id: str = "";
    has current_value: str = "";
    has prior_value: str = "<undef>";
    has restore_pending: bool = False;
}

# The statement executed under the postfix iteration. Carries an entry and
# a live-tail disposition so the verifier can reject "back from terminal".
node Statement {
    has text: str = "";
    has terminal: bool = False;
    has executed: bool = False;
}

# ---- Edge archetypes (typed relationships that carry meaning) -------------

# IterableEstablish: iterable -> region. Lowered once, before iteration.
edge IterableEstablish {
    has evaluated_once: bool = True;
}

# TopicBind: region -> topic. Per-iteration alias of the current element.
edge TopicBind {
    has element_index: int = 0;
}

# StatementEntry: region -> statement. Body executes only after a bind.
edge StatementEntry { }

# IterationBack: statement -> region. Live tail returns to advance iteration.
edge IterationBack { }

# IterationExit: region -> exit sink (a sentinel statement). Exhaustion path.
edge IterationExit { }

# TopicRestore: any claimed exit -> topic. Restoration on normal exit.
edge TopicRestore { }

# Nest: parent region -> child region. Nested postfix loops get fresh IDs.
edge Nest {
    has parent_depth: int = 0;
}

# ---- Walker: descends the iteration contract ------------------------------

walker IterationAuditor {
    has region_count: int = 0;
    has bind_count: int = 0;
    has restore_count: int = 0;
    has violations: list[str] = [];

    can begin with Root entry {
        print("=== PIR-A iteration audit begin ===");
        visit [-->];
    }

    can audit with Iterable entry {
        if not here.list_context {
            self.violations.append(
                f"[FAIL] iterable {here.producer_id} lost list-context demand"
            );
        }
        if here.element_count == 0 {
            print(f"  empty iterable {here.producer_id} -> exit only");
            visit [-->];
            return;
        }
        visit [->:IterableEstablish:->];
    }

    can audit_region with Region entry {
        self.region_count += 1;
        label = f"region[{self.region_count}:{here.label}@d{here.depth}]";
        print(f"  entered {label}");

        # Region must establish iterable before binding any topic.
        visit [->:TopicBind:->];
    }

    can audit_bind with Topic entry {
        # Find the bind edge to learn which element index this is.
        visit [-->];
    }

    can audit_statement with Statement entry {
        here.executed = True;
        if here.terminal {
            print(f"    stmt executed (terminal tail) -> no back-edge");
            # A terminal tail must NOT have an IterationBack edge.
            visit [-->];
            return;
        }
        print(f"    stmt executed (live tail) -> iteration back");
        visit [-->->:IterationBack:->];
    }

    can audit_exit with Statement entry {
        # The exit sink is itself a Statement node. Restoration belongs
        # to TopicRestore, not the sink.
        visit [-->];
    }

    can audit_topic_restore with Topic entry {
        if here.restore_pending {
            self.restore_count += 1;
            here.restore_pending = False;
            print(f"  topic {here.place_id} restored on exit");
        }
        # Done walking this branch; disengage so we don't recurse forever.
        disengage;
    }
}

# ---- Walker: cycle / nesting sanity ---------------------------------------
walker NestingInspector {
    has max_depth: int = 0;

    can begin with Root entry {
        print("=== nesting depth scan ===");
        visit [-->];
    }

    can scan with Region entry {
        if here.depth > self.max_depth {
            self.max_depth = here.depth;
        }
        visit [->:Nest:->];
    }
}

# ---- Wire it up -------------------------------------------------------------

with entry {
    # Outer iteration: foreach over a 3-element literal list.
    r1 = Region(label="outer", depth=1);
    it1 = Iterable(producer_id="lit-3", list_context=True, element_count=3);
    topic1 = Topic(place_id="$_", current_value="<undef>",
                   prior_value="<undef>", restore_pending=True);
    body1_a = Statement(text="body step A", terminal=False, executed=False);
    body1_b = Statement(text="body step B (terminal)", terminal=True,
                        executed=False);
    exit1 = Statement(text="EXIT_outer", terminal=True, executed=False);

    # Inner (nested) iteration over a 2-element range. Different IDs for
    # region/topic — the verifier rejects shared IDs across nesting.
    r2 = Region(label="inner", depth=2);
    it2 = Iterable(producer_id="range-2", list_context=True, element_count=2);
    topic2 = Topic(place_id="$_inner", current_value="<undef>",
                   prior_value="<undef>", restore_pending=True);
    body2 = Statement(text="inner body", terminal=False, executed=False);
    exit2 = Statement(text="EXIT_inner", terminal=True, executed=False);

    # Wire the structural CFG contract.
    root ++> it1 +>:IterableEstablish:+> r1;
    r1 +>:TopicBind(element_index=0):+> topic1;
    r1 +>:StatementEntry:+> body1_a +>:IterationBack:+> r1;
    body1_a ++> body1_b;          # control-flow fallthrough inside body
    r1 +>:IterationExit:+> exit1;
    exit1 +>:TopicRestore:+> topic1;

    # Inner loop nested under the outer body's first step.
    body1_a +>:Nest(parent_depth=1):+> r2;
    r2 +>:IterableEstablish:+> it2;
    r2 +>:TopicBind(element_index=0):+> topic2;
    r2 +>:StatementEntry:+> body2 +>:IterationBack:+> r2;
    r2 +>:IterationExit:+> exit2;
    exit2 +>:TopicRestore:+> topic2;

    # Run both walkers from root.
    root spawn IterationAuditor();
    root spawn NestingInspector();

    auditor = IterationAuditor();
    print("=== summary ===");
    print(f"regions visited: {auditor.region_count}");
}

