import io;
import from contextlib { redirect_stdout }

test "foreach establishes the iterable before a bound live body" {
    r = Region(label="foreach", depth=1);
    it = Iterable(producer_id="foreach-lit-3", list_context=True, element_count=3);
    topic = Topic(place_id="$_", current_value="<undef>",
                  prior_value="old", restore_pending=True);
    body = Statement(text="write $_", terminal=False, executed=False);
    terminal = Statement(text="terminal tail", terminal=True, executed=False);
    exit_sink = Statement(text="EXIT_foreach", terminal=True, executed=False);

    root ++> it;
    it +>:IterableEstablish:+> r;
    r +>:TopicBind(element_index=0):+> topic;
    r +>:StatementEntry:+> body;
    body +>:IterationBack:+> r;
    body ++> terminal;
    r +>:IterationExit:+> exit_sink;
    exit_sink +>:TopicRestore:+> topic;

    establish_edges = [edge it ->:IterableEstablish:->];
    bind_edges = [edge r ->:TopicBind:->];

    assert len([root-->]) == 1, f"root children: {len([root-->])}";
    assert it in [root-->], f"iterable is not rooted: {it.producer_id}";
    assert len(establish_edges) == 1, f"establish edges: {len(establish_edges)}";
    assert establish_edges[0].evaluated_once == True,
        f"evaluated_once: {establish_edges[0].evaluated_once}";
    assert it.list_context == True, f"list_context: {it.list_context}";
    assert r in [it ->:IterableEstablish:->],
        f"iterable does not establish region: {r.label}";
    assert len(bind_edges) == 1, f"bind edges: {len(bind_edges)}";
    assert bind_edges[0].element_index == 0,
        f"bind index: {bind_edges[0].element_index}";
    assert topic.place_id == "$_", f"topic place: {topic.place_id}";
    assert body in [r ->:StatementEntry:->], f"body entry missing: {body.text}";
    assert r in [body ->:IterationBack:->],
        f"live tail lacks iteration back: {body.text}";
    assert terminal in [body-->], f"terminal tail missing: {terminal.text}";
    assert len([terminal ->:IterationBack:->]) == 0,
        f"terminal tail has back edge: {terminal.text}";
    assert exit_sink in [r ->:IterationExit:->],
        f"exhaustion exit missing: {exit_sink.text}";
    assert topic in [exit_sink ->:TopicRestore:->],
        f"topic restore missing: {topic.place_id}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn IterationAuditor();
    }
    assert res.region_count == 1, f"audited regions: {res.region_count}";
    assert len(res.violations) == 0, f"unexpected violations: {res.violations}";
}

test "empty for source exits without selecting an element" {
    r = Region(label="empty-for", depth=1);
    it = Iterable(producer_id="for-empty-list", list_context=True, element_count=0);
    topic = Topic(place_id="$_empty", current_value="<undef>",
                  prior_value="old", restore_pending=True);
    exit_sink = Statement(text="EXIT_for", terminal=True, executed=False);

    root ++> it;
    it +>:IterableEstablish:+> r;
    r +>:IterationExit:+> exit_sink;
    exit_sink +>:TopicRestore:+> topic;

    empty_binds = [r ->:TopicBind:->];

    assert it.list_context == True, f"empty source lost list context: {it.list_context}";
    assert it.element_count == 0, f"source count: {it.element_count}";
    assert len(empty_binds) == 0,
        f"empty loop must not bind a topic: {len(empty_binds)}";
    assert exit_sink in [r ->:IterationExit:->],
        f"empty loop lacks exhaustion exit: {exit_sink.text}";
    assert topic in [exit_sink ->:TopicRestore:->],
        f"empty loop lacks restoration: {topic.place_id}";
}

test "nested for and foreach regions keep separate topic identities" {
    outer = Region(label="outer-foreach", depth=1);
    inner = Region(label="inner-for", depth=2);
    outer_it = Iterable(producer_id="foreach-array", list_context=True,
                        element_count=2);
    inner_it = Iterable(producer_id="for-range", list_context=True,
                        element_count=3);
    outer_topic = Topic(place_id="$_outer", current_value="<undef>",
                        prior_value="old", restore_pending=True);
    inner_topic = Topic(place_id="$_inner", current_value="<undef>",
                        prior_value="outer", restore_pending=True);
    outer_body = Statement(text="outer reads and writes $_",
                           terminal=False, executed=False);
    inner_body = Statement(text="inner body", terminal=False, executed=False);
    outer_exit = Statement(text="EXIT_outer", terminal=True, executed=False);
    inner_exit = Statement(text="EXIT_inner", terminal=True, executed=False);

    root ++> outer_it;
    outer_it +>:IterableEstablish:+> outer;
    outer +>:TopicBind(element_index=0):+> outer_topic;
    outer +>:StatementEntry:+> outer_body;
    outer_body +>:IterationBack:+> outer;
    outer +>:IterationExit:+> outer_exit;
    outer_exit +>:TopicRestore:+> outer_topic;
    outer_body +>:Nest(parent_depth=1):+> inner;
    inner_it +>:IterableEstablish:+> inner;
    inner +>:TopicBind(element_index=0):+> inner_topic;
    inner +>:StatementEntry:+> inner_body;
    inner_body +>:IterationBack:+> inner;
    inner +>:IterationExit:+> inner_exit;
    inner_exit +>:TopicRestore:+> inner_topic;

    nest_edges = [edge outer_body ->:Nest:->];

    assert inner in [outer_body ->:Nest:->],
        f"nested region missing: {inner.label}";
    assert len(nest_edges) == 1, f"nest edges: {len(nest_edges)}";
    assert nest_edges[0].parent_depth == 1,
        f"parent depth: {nest_edges[0].parent_depth}";
    assert outer.depth == 1 and inner.depth == 2,
        f"depths: {outer.depth}/{inner.depth}";
    assert outer.label != inner.label,
        f"region identities collide: {outer.label}/{inner.label}";
    assert outer_topic.place_id != inner_topic.place_id,
        f"topic places collide: {outer_topic.place_id}/{inner_topic.place_id}";
    assert outer in [outer_it ->:IterableEstablish:->],
        f"outer iterable not established: {outer_it.producer_id}";
    assert inner in [inner_it ->:IterableEstablish:->],
        f"inner iterable not established: {inner_it.producer_id}";
    assert outer_topic in [outer ->:TopicBind:->],
        f"outer bind missing: {outer_topic.place_id}";
    assert inner_topic in [inner ->:TopicBind:->],
        f"inner bind missing: {inner_topic.place_id}";
    assert outer in [outer_body ->:IterationBack:->],
        f"outer live tail lacks back edge: {outer_body.text}";
    assert inner in [inner_body ->:IterationBack:->],
        f"inner live tail lacks back edge: {inner_body.text}";
    assert outer_topic in [outer_exit ->:TopicRestore:->],
        f"outer restoration missing: {outer_topic.place_id}";
    assert inner_topic in [inner_exit ->:TopicRestore:->],
        f"inner restoration missing: {inner_topic.place_id}";
}

test "scalar or magical iterable is reported as a closed boundary" {
    it = Iterable(producer_id="magical", list_context=False, element_count=2);
    root ++> it;

    buf = io.StringIO();
    with redirect_stdout(buf) {
