    assert "[FAIL]" in res.violations[0],
        f"missing fail-closed marker: {res.violations[0]}";
    assert "magical" in res.violations[0],
        f"wrong iterable in violation: {res.violations[0]}";
    assert "lost list-context demand" in res.violations[0],
        f"wrong boundary claim: {res.violations[0]}";
}

