fixed.jac_tests:
"""Tests for the ML model governance graph (Spec §12.6).

Covers: governance graph shape, owner/audit/SHAP/review checks, CI-gate
behavior on bias-audit failure, SHAP retention policy (7-year minimum),
retired-model skip, and promotion flag.
"""

import io;
import from contextlib { redirect_stdout }

test "governance graph shape has expected nodes and typed edges" {
    root ++> Model(name="BPFS", use_case="lender-ready credit scoring");
    bpfs = [root -->][?:Model][0];

    bpfs +>:Owns:+> Owner(team="Risk ML", signed_off=True);
    bpfs +>:HasAudit:+> BiasAudit(quarter="Q3-2025", four_fifths_pass=True, parity_pass=True, blocked_promotion=False);
    bpfs +>:HasShap:+> ShapRetention(retention_years=7, retained=True);
    bpfs +>:HasReview:+> ExternalReview(year=2025, approved=True);

    assert len([root -->]) == 1, f"root should have 1 child Model, got {len([root -->])}";
    assert len([bpfs ->:Owns:->]) == 1, "BPFS must have exactly one Owns edge";
    assert len([bpfs ->:HasAudit:->]) == 1, "BPFS must have exactly one HasAudit edge";
    assert len([bpfs ->:HasShap:->]) == 1, "BPFS must have exactly one HasShap edge";
    assert len([bpfs ->:HasReview:->]) == 1, "BPFS must have exactly one HasReview edge";
}

test "clean governance promotes BPFS and prints PROMOTE" {
    root ++> Model(name="BPFS", use_case="lender-ready credit scoring");
    bpfs = [root -->][?:Model][0];
    bpfs +>:Owns:+> Owner(team="Risk ML", signed_off=True);
    bpfs +>:HasAudit:+> BiasAudit(quarter="Q3-2025", four_fifths_pass=True, parity_pass=True, blocked_promotion=False);
    bpfs +>:HasShap:+> ShapRetention(retention_years=7, retained=True);
    bpfs +>:HasReview:+> ExternalReview(year=2025, approved=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Governor();
    }
    out = buf.getvalue();

    assert "[PROMOTE]" in out, f"expected PROMOTE marker, got: {out}";
    assert "BPFS" in out, f"expected BPFS in output, got: {out}";
    assert bpfs.promoted == True, f"bpfs.promoted should be True after clean audit, got {bpfs.promoted}";
}

test "failing 4/5ths bias audit blocks promotion (CI gate)" {
    root ++> Model(name="BPFS", use_case="lender-ready credit scoring");
    bpfs = [root -->][?:Model][0];
    bpfs +>:Owns:+> Owner(team="Risk ML", signed_off=True);
    # ECOA 4/5ths rule failed AND explicit blocked flag set
    bpfs +>:HasAudit:+> BiasAudit(quarter="Q3-2025", four_fifths_pass=False, parity_pass=True, blocked_promotion=True);
    bpfs +>:HasShap:+> ShapRetention(retention_years=7, retained=True);
    bpfs +>:HasReview:+> ExternalReview(year=2025, approved=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Governor();
    }
    out = buf.getvalue();

    assert "[BLOCKED]" in out, f"expected BLOCKED for failing 4/5ths, got: {out}";
    assert "4/5=False" in out, f"expected 4/5=False in output, got: {out}";
    assert bpfs.promoted == False, f"promoted must remain False on bias failure, got {bpfs.promoted}";
}

test "shap retention under 7 years holds promotion even when audit passes" {
    root ++> Model(name="ChurnClassifier", use_case="retention marketing");
    churn = [root -->][?:Model][0];
    churn +>:Owns:+> Owner(team="Growth ML", signed_off=True);
    churn +>:HasAudit:+> BiasAudit(quarter="Q3-2025", four_fifths_pass=True, parity_pass=True, blocked_promotion=False);
    # SHAP retained only 5 years, below 7-year requirement
    churn +>:HasShap:+> ShapRetention(retention_years=5, retained=True);
    churn +>:HasReview:+> ExternalReview(year=2024, approved=True);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Governor();
    }
    out = buf.getvalue();

    assert "[PROMOTE]" not in out, f"5-year SHAP should not promote, got: {out}";
    assert "[HOLD]" in out, f"expected HOLD on SHAP short-retention, got: {out}";
    assert "shap=False" in out, f"expected shap=False in HOLD line, got: {out}";
    assert churn.promoted == False, f"churn.promoted must be False with only 5yr SHAP, got {churn.promoted}";
}

test "retired model is skipped by governor walk" {
    root ++> Model(name="Legacy", use_case="deprecated scoring");
    legacy = [root -->][?:Model][0];
    legacy +>:Owns:+> Owner(team="Risk ML", signed_off=True);
    legacy +>:HasAudit:+> BiasAudit(quarter="Q1-2024", four_fifths_pass=True, parity_pass=True, blocked_promotion=False);
    legacy +>:HasShap:+> ShapRetention(retention_years=7, retained=True);
    legacy +>:HasReview:+> ExternalReview(year=2024, approved=True);
    legacy.retired = True;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Governor();
    }
    out = buf.getvalue();

    assert "[SKIP]" in out, f"retired model must be skipped, got: {out}";
    assert "Legacy" in out, f"expected Legacy in skip message, got: {out}";
    assert "[PROMOTE]" not in out, f"retired model must not be promoted, got: {out}";
    assert legacy.promoted == False, f"retired.promoted should stay False, got {legacy.promoted}";
}

