    store +>:ProjectsFrom:+> Doctor();
    store +>:ProjectsFrom:+> CLI();
    store +>:ProjectsFrom:+> TUI();

    # Mutation flow through the replication pipeline.
    upsert_mut = Mutation(
        mutation_id="m-001",
        entity_type="observation",
        entity_id="obs-42",
        operation="upsert",
        canonical_project="engram",
        contract_version=1,
        occurred_at="2026-01-15T10:00:00Z",
    );
    delete_mut = Mutation(
        mutation_id="m-002",
        entity_type="observation",
        entity_id="obs-42",
        operation="delete",
        canonical_project="engram",
        contract_version=1,
        occurred_at="2026-01-15T10:05:00Z",
    );
    root +>:FlowsMutation(step="emit"):+> upsert_mut
         +>:FlowsMutation(step="emit"):+> delete_mut;

    # Spawn the conformance auditor from root.
    auditor = Auditor();
    root spawn auditor;

    print(f"\nConformance report: violations={auditor.violations}");
}

