# Entity archetypes
# ----------------------------------------------------------------------

node Company {
    has ticker: str = "";
    has name: str = "";
    has sector: str = "";
}

node Filing {
    has company: str = "";
    has fiscal_year: int = 0;
    has revenue: float = 0.0;
    has net_income: float = 0.0;
}

# ----------------------------------------------------------------------
# Typed edges — the relationships that vector-RAG cannot natively traverse
# ----------------------------------------------------------------------

edge OwnsShare {
    has pct: float = 0.0;
    has as_of: str = "";
}

edge Filed {
    has period: str = "";
}

