import io;
import from contextlib { redirect_stdout }

test "KG-RAG counts hops and follows ownership" {
    a = Company(name="Acme Holdings", ticker="ACM", sector="Conglomerate");
    b = Company(name="Beacon Capital", ticker="BCN", sector="Conglomerate");
    root ++> a;
    root ++> b;

    s1 = Subsidiary(name="Acme Foods LLC", ownership_pct=100.0);
    s2 = Subsidiary(name="Acme Energy GmbH", ownership_pct=80.0);
    bsub = Subsidiary(name="Beacon Logistics Inc", ownership_pct=100.0);
    a +>:Owns(since="2018", filed_period="FY2023"):+> s1;
    a +>:Owns(since="2020", filed_period="FY2023"):+> s2;
    b +>:Owns(since="2015", filed_period="FY2023"):+> bsub;
    a +>:Compares(metric="revenue"):+> b;

    q1 = Question(text="What sector is Acme in?", hops=1, qtype="single-hop");
    q2 = Question(text="Which entity owns Acme Foods?", hops=2, qtype="two-hop");
    q3 = Question(text="Compare Acme vs Beacon revenue.", hops=3, qtype="comparison");
    root ++> q1;
    root ++> q2;
    root ++> q3;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn KgRag();
    }
    out = buf.getvalue();

    assert len([root-->]) == 5, f"got {len([root-->])} direct children";
    own_count = len([a ->:Owns:->]);
    assert own_count == 2, f"got {own_count} owned subsidiaries";
    assert s1 in [a ->:Owns:->], f"missing {s1.name} on outgoing Owns edges";
    assert len([s1 ->:Owns:->]) == 0, f"ownership edge points backward from {s1.name}";
    assert b in [a ->:Compares:->], f"missing comparison target {b.name}";
    assert res.answered == 3, f"got {res.answered} answered questions";
    assert res.by_hop.get(1, 0) == 1, f"got {res.by_hop} for hop 1";
    assert res.by_hop.get(2, 0) == 1, f"got {res.by_hop} for hop 2";
    assert res.by_hop.get(3, 0) == 1, f"got {res.by_hop} for hop 3";
    assert res.visited == [q1.text, q2.text, q3.text], f"got {res.visited}";
    assert "parent: Acme Holdings (ACM)" in out, f"missing parent traversal: {out}";
    assert "-> subsidiary: Acme Foods LLC (100.0%)" in out, f"missing subsidiary traversal: {out}";
    assert "[KG-RAG qtype=comparison hops=3]" in out, f"missing question classification: {out}";
}

test "Vector-RAG classifies questions by hop difficulty" {
    q1 = Question(text="Single-hop fact", hops=1, qtype="single-hop");
    q2 = Question(text="Two-hop ownership", hops=2, qtype="two-hop");
    q3 = Question(text="Multi-hop comparison", hops=3, qtype="multi-hop");
