"""Profiler capability expansion — model a profiler's flag catalog where
enabling a parent flag must imply its descendants (or the leaf is a silent
no-op), and where stalled spans need to be attributed to root causes
(Typhon code, GC, runtime suspension, lock contention, scheduling).

Entities (nodes):
  Flag         — a profiler flag (e.g. "Runtime:ThreadScheduling")
  CaptureSource— a cause emitter (GC, ETW scheduling, contention, ...)
  Stall        — an observed multi-millisecond span with no child spans
  Cause        — a classified attribution for a stall

Relationships (typed edges):
  Implies      — Flag -> Flag (parent-implies-child in the flag tree)
  Emits        — CaptureSource -> Cause (this source can produce this cause)
  Observed     — Stall -> Flag (stall was seen while this flag was on)
  AttributedTo — Stall -> Cause (walker's verdict: which cause best fits)

The flag-config walker enforces the parent-implies-children rule on the catalog
and rejects orphan leaves. The stall-attribution walker reaches from a Stall
through Observed -> Flag -> Implies (ancestor flag tree) -> CaptureSource ->
Emits -> Cause, and reports the best-matching cause (or NONE). A guard set
prevents the back-edge on the Implies cycle from looping forever.
"""

node Flag {
    has key: str = "";
    has enabled: bool = False;
}

node CaptureSource {
    has name: str = "";
}

node Cause {
    has label: str = "";
    has priority: int = 0;
}

node Stall {
    has label: str = "";
    has duration_ms: float = 0.0;
}

edge Implies {
    has weight: int = 1;
}

edge Emits {
    has cadence: str = "";
}

edge Observed {
    has depth_ms: float = 0.0;
}

edge AttributedTo {
    has confidence: float = 0.0;
}

walker FlagAuditor {
    """Walk the Implies tree from every enabled flag and confirm no leaf
    is enabled while an ancestor is disabled. Reports orphan leaves and
    dead (disabled) subtrees."""
    can start with Root entry {
        visit [-->];
    }

    can audit_flag with Flag entry {
        print(f"[flag] {here.key} enabled={here.enabled}");
        # Ancestors of this flag through Implies (walking UP the tree).
        ancestor_ok = self._ancestors_all_enabled(here);
        if here.enabled and not ancestor_ok {
            print(f"  ORPHAN LEAF: '{here.key}' enabled but an "
                  f"ancestor is disabled — silent no-op in trace");
            self.orphan_count += 1;
        }
        # Continue into children (forward along Implies).
        visit [->:Implies:->];
    }

    def _ancestors_all_enabled(self, start: Flag) -> bool {
        # Walk backward along Implies, with a visited-set guard so the
        # parent walk can't loop on a malformed tree.
        guard: set = set();
        cur = start;
        while cur is not None {
            if cur in guard {
                break;
            }
            guard.add(cur);
            parents = [p for p in (cur <-:Implies:--) if isinstance(p, Flag)];
            if not parents {
                break;
            }
            cur = parents[0];
            if not cur.enabled {
                return False;
            }
        }
        return True;
    }
}

walker StallAttributor {
    """From a Stall, reach through Observed -> Flag, climb the Implies tree
    to ancestor flags, hop to CaptureSources that Emit causes, and pick
    the cause with the highest priority as the attribution. Uses a guard
    set so cycles in the Implies graph don't hang the walker."""
    has verdict: str = "NONE";
    has best_priority: int = -1;
    has best_label: str = "NONE";

    can start with Root entry {
        visit [-->];
    }

    can inspect_stall with Stall entry {
        print(f"[stall] {here.label} duration={here.duration_ms}ms");
        # Reset per-stall verdict.
        self.verdict = "NONE";
        self.best_priority = -1;
        self.best_label = "NONE";
        # Walk into flags observed under this stall.
        visit [->:Observed:->];
    }

    can climb with Flag entry {
        print(f"  observed flag: {here.key}");
        # From this flag, climb ancestors via Implies and from each
        # reachable flag, hop to CaptureSources that Emit causes.
        ancestors = self._collect_ancestors(here);
        for anc in ancestors {
            for src in [s for s in (anc --> ?[?:CaptureSource]) if isinstance(s, CaptureSource)] {
                for c in [c2 for c2 in (src -[?:Emits]-> ?[?:Cause]) if isinstance(c2, Cause)] {
                    if c.priority > self.best_priority {
                        self.best_priority = c.priority;
                        self.best_label = c.label;
                    }
                }
            }
        }
        if self.best_label != "NONE" {
            self.verdict = self.best_label;
            print(f"  -> attributed to: {self.verdict} "
                  f"(priority={self.best_priority})");
        } else {
            print(f"  -> NO matching cause found in the catalog");
        }
    }

    def _collect_ancestors(self, start: Flag) -> list {
        guard: set = set();
        out: list = [start];
        cur = start;
        while cur is not None {
            if cur in guard {
                break;
            }
            guard.add(cur);
            parents = [p for p in (cur <-:Implies:--) if isinstance(p, Flag)];
            if not parents {
                break;
            }
            cur = parents[0];
            out.append(cur);
        }
        return out;
    }
}

with entry {
    # ---- Build the flag catalog (Implies tree) ----
    runtime = Flag(key="Runtime", enabled=True);
    thread_sched = Flag(key="Runtime:ThreadScheduling", enabled=True);
    tiered = Flag(key="Runtime:TieredCompilation", enabled=True);
    gc = Flag(key="GcTracing", enabled=True);
    contention = Flag(key="Runtime:Contention", enabled=False);
    adaptive = Flag(key="AdaptiveWaiter:YieldOrSleep", enabled=False);

    root ++> runtime ++> thread_sched;
    runtime ++> tiered;
    root ++> gc;
    runtime ++> contention;
    root ++> adaptive;

    # Implies relationships (parent -> child meaning).
    runtime +>:Implies(weight=1):+> thread_sched;
    runtime +>:Implies(weight=1):+> tiered;
    runtime +>:Implies(weight=1):+> contention;

    # ---- Build capture sources and the causes they emit ----
    clr_runtime = CaptureSource(name="CLR-RuntimeEvents");
    etw_sched = CaptureSource(name="ETW-SchedulingPump");
    contention_src = CaptureSource(name="Runtime-ContentionKeyword");

    cause_gc = Cause(label="GC", priority=10);
    cause_suspend = Cause(label="RuntimeSuspension", priority=80);
    cause_contention = Cause(label="LockContention", priority=70);
    cause_scheduling = Cause(label="Scheduling", priority=60);

    clr_runtime +>:Emits(cadence="event"):+> cause_gc;
    clr_runtime +>:Emits(cadence="event"):+> cause_suspend;
    etw_sched +>:Emits(cadence="event"):+> cause_scheduling;
    contention_src +>:Emits(cadence="event"):+> cause_contention;

    # CaptureSources hang off the flags that subscribe to them.
    thread_sched --> etw_sched;
    tiered --> clr_runtime;
    contention --> contention_src;

    # ---- Build an observed stall (the July investigation's symptom) ----
    stall = Stall(label="Runtime.WriteTickFence.Cluster", duration_ms=14.0);
    # The stall was observed while Runtime:TieredCompilation was on;
    # tiered's ancestor runtime is the one actually subscribed to CLR events.
    stall +>:Observed(depth_ms=14.0):+> tiered;

    root ++> stall;

    # ---- Run the demonstrations ----
    print("=== Flag audit (parent-implies-children rule) ===");
    fa = FlagAuditor();
    fa.orphan_count = 0;
    root spawn fa;

    print("");
    print("=== Stall attribution walk ===");
    sa = StallAttributor();
    root spawn sa;
    print(f"final verdict for stall: {sa.verdict}");
}

fixed.code:
"""Typhon profiler config ergonomics: modeled as a graph where enabling a leaf
flag without its ancestors is a silent no-op.

The 232-flag Typhon:Profiler:* tree resolves strictly parent-implies-children:
"Parent off -> all descendants off (regardless of their own keys)." Enabling a
leaf without its ancestors is a silent no-op -- no warning, no data, a
plausible-looking trace. The ConfigAuditor walker traverses every flag from
the root and reports which ones are actually live in the trace vs. which were
silently dropped because an ancestor on the path to root was disabled.
"""

# A flag node: a leaf or branch in the Profiler config tree.
node Flag {
    has name: str = "";
    has enabled: bool = False;
    has children: list = [];
    has is_root: bool = False;
}

# Typed edge from a parent flag to a child flag in the Profiler tree.
edge SubFlag { }

walker ConfigAuditor {
    has live_flags: list = [];
    has silently_dropped: list = [];

    can start with Root entry {
        # Begin by entering each top-level flag branch from the root.
        visit [->:SubFlag:->];
    }

    can audit with Flag entry {
        # Root catalog has no enablement; its descendants do.
        if here.is_root {
            visit [->:SubFlag:->];
        } elif here.enabled {
            # Seed: a flag is only live if no known-broken ancestor
            # silently dropped it (i.e. an ancestor was off but a leaf
            # was hand-enabled). If this flag itself is on the known-
            # broken list, treat it as dropped for the summary.
            self.live_flags.append(here.name);
            visit [->:SubFlag:->];
        } else {
            # This flag is OFF; every descendant is silently dropped.
            for child in here.children {
                self.silently_dropped.append(child);
            }
            visit [->:SubFlag:->];
        }
    }

    can summarize with Root entry {
        final_live: list = [];
        final_dropped: list = [];

        for n in self.live_flags {
            if n in self.silently_dropped {
                final_dropped.append(n);
            } else {
                final_live.append(n);
            }
        }

        print("LIVE FLAGS (actually emitted to trace):");
        for n in final_live {
            print(f"  + {n}");
        }
        print("");
        print("SILENTLY DROPPED (enabled but ancestor off):");
        for n in final_dropped {
            print(f"  ! {n}");
        }
    }
}

with entry {
    # Build a small slice of the flag catalog: a Profiler root with a
    # Runtime child and an AdaptiveWaiter child. The Runtime branch contains
    # ThreadScheduling (a real flag) and TieredCompilation (a leaf that the
    # July investigator enabled by hand, forgetting its Runtime parent).
    profiler = Flag(name="Profiler", is_root=True);
    runtime = Flag(name="Runtime", children=["TieredCompilation"]);
    sched = Flag(name="ThreadScheduling", enabled=True);
    tiered = Flag(name="TieredCompilation", enabled=True);
    adaptive = Flag(name="AdaptiveWaiter", enabled=False);
    yields = Flag(name="YieldOrSleep", enabled=True);

    root +>:SubFlag:+> profiler;
    profiler +>:SubFlag:+> runtime;
    runtime +>:SubFlag:+> sched;
    runtime +>:SubFlag:+> tiered;
    profiler +>:SubFlag:+> adaptive;
    adaptive +>:SubFlag:+> yields;

    auditor = ConfigAuditor();
    root spawn auditor;
}

