"""Tests for the discussion reply tree walker."""

import io;
import from contextlib { redirect_stdout }

test "walker counts all comments and tracks depth" {
    root ++> DiscussionTopic(title="Topic A");

    topic = [root -->][0];
    top = Comment(body="top", author="alice", depth=0);
    topic +>:ReplyTo(ordinal=0):+> top;

    r1 = Comment(body="reply1", author="bob", depth=1);
    top +>:ReplyTo(ordinal=0):+> r1;

    r1a = Comment(body="reply1a", author="carol", depth=2);
    r1 +>:ReplyTo(ordinal=0):+> r1a;

    r2 = Comment(body="reply2", author="dave", depth=1);
    top +>:ReplyTo(ordinal=1):+> r2;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = topic spawn IngestReplies();
    }

    assert res.total == 4, f"expected 4 comments walked, got {res.total}";
    assert res.nested_count == 3, f"expected 3 nested replies, got {res.nested_count}";
    assert res.max_depth == 2, f"expected max_depth=2, got {res.max_depth}";
}

test "walker handles topic with only a top-level comment" {
    root ++> DiscussionTopic(title="Lonely Topic");

    topic = [root -->][0];
    lone = Comment(body="only comment", author="alice", depth=0);
    topic +>:ReplyTo(ordinal=0):+> lone;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = topic spawn IngestReplies();
    }

    assert res.total == 1, f"expected 1 comment, got {res.total}";
    assert res.nested_count == 0, f"expected 0 replies, got {res.nested_count}";
    assert res.max_depth == 0, f"expected max_depth=0, got {res.max_depth}";
}

test "walker prints depth and top-level vs reply labels" {
    root ++> DiscussionTopic(title="Label Topic");

    topic = [root -->][0];
    top = Comment(body="root question", author="alice", depth=0);
    topic +>:ReplyTo(ordinal=0):+> top;

    r1 = Comment(body="a reply", author="bob", depth=1);
    top +>:ReplyTo(ordinal=0):+> r1;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = topic spawn IngestReplies();
    }

    out = buf.getvalue();
    assert "[depth=0]" in out, f"missing top-level depth marker: {out}";
    assert "[depth=1]" in out, f"missing reply depth marker: {out}";
    assert "top-level" in out, f"missing top-level label: {out}";
    assert "reply" in out, f"missing reply label: {out}";
}

test "ReplyTo edges form the parent-child hierarchy" {
    root ++> DiscussionTopic(title="Hierarchy Topic");

    topic = [root -->][0];
    top = Comment(body="q", author="alice", depth=0);
    topic +>:ReplyTo(ordinal=0):+> top;

    r1 = Comment(body="r1", author="bob", depth=1);
    top +>:ReplyTo(ordinal=0):+> r1;

    r1a = Comment(body="r1a", author="carol", depth=2);
    r1 +>:ReplyTo(ordinal=0):+> r1a;

    r2 = Comment(body="r2", author="dave", depth=1);
    top +>:ReplyTo(ordinal=1):+> r2;

    topic_kids = [topic ->:ReplyTo:->];
    assert len(topic_kids) == 1, f"topic should have 1 top-level Comment child, got {len(topic_kids)}";
    assert topic_kids[0].body == "q", f"wrong top comment: {topic_kids[0].body}";

    top_kids = [top ->:ReplyTo:->];
    assert len(top_kids) == 2, f"top should have 2 replies, got {len(top_kids)}";
    ordinals = sorted([k ->:ReplyTo:->][0].body for k in top_kids) if False else [top ->:ReplyTo:->][0].body;
    bodies = [k.body for k in top_kids];
    assert "r1" in bodies and "r2" in bodies, f"missing reply bodies: {bodies}";

    r1_kids = [r1 ->:ReplyTo:->];
    assert len(r1_kids) == 1, f"r1 should have 1 child, got {len(r1_kids)}";
    assert r1_kids[0].body == "r1a", f"wrong r1 child: {r1_kids[0].body}";
    assert r1_kids[0].depth == 2, f"r1a should have depth=2, got {r1_kids[0].depth}";

    r2_kids = [r2 ->:ReplyTo:->];
    assert len(r2_kids) == 0, f"r2 should have 0 children, got {len(r2_kids)}";
}

