"""Regression tests for the stale-pin auditor graph model.

These tests build fresh graphs (parallel-isolated workers), spawn the
StalePinAuditor walker, and assert on the audit findings the program
emits. The PROBLEM promises:

  * Inline `run:` pins surface EOL tools (the whole point of the issue).
  * Manifest pins surface what they host.
  * `findings` order reflects traversal order of children of Root.
  * The walker is guarded by `seen` (no infinite recursion via a self-loop
    back to a Tool whose host already produced a finding).
  * A `WorkflowPin` with no hosted tool (None) does not crash the walker
    and produces no finding for that branch.
  * A `ManifestPin` with no hosted tool (None) disengages early.
  * Walker `findings` length matches the number of distinct tools visited.
"""

import io;
import from contextlib { redirect_stdout }

test "inline workflow pin surfaces EOL eslint 8.57.1" {
    eol_eslint = Tool(name="eslint", version="8.57.1", eol=True);
    pin = WorkflowPin(
        workflow="eslint.yml",
        run_line=72,
        pinned_version="8.57.1",
        hosted_tool=eol_eslint
    );
    root +>:VersionOf:+> pin;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn StalePinAuditor();
    }
    out = buf.getvalue();

    assert "[STALE] eslint@8.57.1" in res.findings, (
        f"EOL inline pin must produce STALE finding, got {res.findings}"
    );
    assert "  -> reporting: [STALE] eslint@8.57.1" in out, (
        f"auditor must print the reporting line for EOL tools; stdout was: {out!r}"
    );
}

test "manifest pin surfaces supported eslint 10.0.0" {
    modern = Tool(name="eslint", version="10.0.0", eol=False);
    pin = ManifestPin(ecosystem="npm", hosted_tool=modern);
    root +>:VersionOf:+> pin;

    res = root spawn StalePinAuditor();

    assert "[OK] eslint@10.0.0" in res.findings, (
        f"supported manifest pin must produce OK finding, got {res.findings}"
    );
    assert not any(f.startswith("[STALE]") for f in res.findings), (
        f"no STALE finding expected when only a supported pin exists; got {res.findings}"
    );
}

test "both manifest and inline pins are audited in spawn order" {
    modern = Tool(name="eslint", version="10.0.0", eol=False);
    eol_eslint = Tool(name="eslint", version="8.57.1", eol=True);
    manifest = ManifestPin(ecosystem="npm", hosted_tool=modern);
    workflow = WorkflowPin(
        workflow="eslint.yml",
        run_line=72,
        pinned_version="8.57.1",
        hosted_tool=eol_eslint
    );
    root +>:VersionOf:+> manifest;
    root +>:VersionOf:+> workflow;

    res = root spawn StalePinAuditor();

    assert len(res.findings) == 2, (
        f"one finding per distinct Tool; got {res.findings}"
    );
    assert res.findings[0] == "[OK] eslint@10.0.0", (
        f"first child of Root is the manifest pin; expected OK first, got {res.findings[0]}"
    );
    assert res.findings[1] == "[STALE] eslint@8.57.1", (
        f"second child of Root is the workflow pin; expected STALE second, got {res.findings[1]}"
    );
}

test "workflow pin with no hosted tool yields no finding" {
    pin = WorkflowPin(
        workflow="eslint.yml",
        run_line=72,
        pinned_version="8.57.1",
        hosted_tool=None
    );
    root +>:VersionOf:+> pin;

    res = root spawn StalePinAuditor();

    assert res.findings == [], (
        f"a WorkflowPin hosting nothing must produce no findings; got {res.findings}"
    );
    assert pin in [root ->:VersionOf:->], (
        "the empty pin must still be reachable from Root"
    );
}

test "seen guard prevents re-audit on VersionOf cycle back to same Tool" {
    t = Tool(name="eslint", version="8.57.1", eol=True);
    pin = ManifestPin(ecosystem="npm", hosted_tool=t);
    root +>:VersionOf:+> pin;
    # closed loop: pin -> tool -> pin (typed VersionOf both directions)
    pin +>:VersionOf:+> t;
    t +>:VersionOf:+> pin;

    res = root spawn StalePinAuditor();

    # Each distinct (name, version) pair appears exactly once even with a cycle.
    assert len(res.findings) == 1, (
        f"cycle via VersionOf must not duplicate findings; got {res.findings}"
    );
    assert res.findings[0] == "[STALE] eslint@8.57.1", (
        f"expected the single STALE finding; got {res.findings[0]}"
    );
}

