    recursive = Container(name="recursive", payload="self");
    root +>:Holds(order=0):+> recursive;
    recursive +>:Holds(order=1):+> recursive;

    res = root spawn ReprWalker();

    assert res.cycle_detected, f"cycle flag was {res.cycle_detected}";
    assert res.self_ref_name == "recursive", f"self reference was {res.self_ref_name}";
    assert recursive.visited, f"recursive container visited was {recursive.visited}";
}

test "detects transitive containment cycle" {
    outer = Container(name="outer", payload="box");
    inner = Container(name="inner", payload="crate");
    recursive = Container(name="recursive", payload="self");

    root +>:Holds(order=0):+> outer;
    outer +>:Holds(order=1):+> inner;
    inner +>:Holds(order=2):+> recursive;
    recursive +>:Holds(order=3):+> recursive;

    res = root spawn ReprWalker();

    assert res.cycle_detected, f"cycle flag was {res.cycle_detected}";
    assert res.self_ref_name == "recursive", f"self reference was {res.self_ref_name}";
    assert outer.visited, f"outer visited was {outer.visited}";
    assert inner.visited, f"inner visited was {inner.visited}";
    assert recursive.visited, f"recursive visited was {recursive.visited}";
}

test "does not report a cycle for acyclic containment" {
    outer = Container(name="outer", payload="box");
    inner = Container(name="inner", payload="crate");
    leaf = Container(name="leaf", payload="widget");

    root +>:Holds(order=0):+> outer;
    outer +>:Holds(order=1):+> inner;
    inner +>:Holds(order=2):+> leaf;

    res = root spawn ReprWalker();

    assert not res.cycle_detected, f"cycle flag was {res.cycle_detected}";
    assert res.self_ref_name == "", f"self reference was {res.self_ref_name}";
    assert outer.visited, f"outer visited was {outer.visited}";
    assert inner.visited, f"inner visited was {inner.visited}";
    assert leaf.visited, f"leaf visited was {leaf.visited}";
}

