fixed.jac_tests:
import io;
import from contextlib { redirect_stdout }

test "valid png import sets adaptive path and persists cache hash" {
    icon = IconAsset(
        display_name="launcher",
        source_uri="file:///picker/app.png",
        source_hash="hash1",
        cached_hash=""
    );
    root +>:IconImport(original_format="png"):+> icon;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn IconImporter(original_format="png", expected_source_hash="hash1");
    }
    out = buf.getvalue();

    assert icon.is_valid == True, f"expected valid icon, got is_valid={icon.is_valid}";
    assert icon.processed_path == "/cache/icons/launcher.adaptive.png", f"path={icon.processed_path}";
    assert icon.cached_hash == "hash1", f"cached_hash={icon.cached_hash}";
    assert "[Importer] imported: launcher" in out, f"missing success output: {out}";
}

test "ico format rejected with clear failure message" {
    icon = IconAsset(
        display_name="favicon",
        source_uri="file:///picker/favicon.ico",
        source_hash="x",
        cached_hash=""
    );
    root +>:IconImport(original_format="ico"):+> icon;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn IconImporter(original_format="ico", expected_source_hash="x");
    }
    out = buf.getvalue();

    assert icon.is_valid == False, f"expected invalid icon, got is_valid={icon.is_valid}";
    assert "ICO not supported" in icon.failure_reason, f"reason={icon.failure_reason}";
    assert "[Importer] FAILED" in out and "ICO format rejected" in out, f"missing failure output: {out}";
}

test "empty source URI fails closed with clear message" {
    icon = IconAsset(
        display_name="broken",
        source_uri="",
        source_hash="",
        cached_hash=""
    );
    root +>:IconImport(original_format="png"):+> icon;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn IconImporter(original_format="png", expected_source_hash="");
    }
    out = buf.getvalue();

    assert icon.is_valid == False, f"expected invalid icon, got is_valid={icon.is_valid}";
    assert icon.failure_reason == "empty source URI", f"reason={icon.failure_reason}";
    assert "no source URI" in out, f"missing URI failure output: {out}";
}

test "janitor purges stale cache when source hash changes" {
    prof = Profile(name="Work", pwa_id="com.example.work");
    icon = IconAsset(
        display_name="shortcut",
        source_uri="file:///picker/s.png",
        source_hash="newhash",
        cached_hash="oldhash",
        is_valid=True
    );
    root ++> prof;
    prof +>:OwnsIcon:+> icon;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CacheJanitor();
    }
    out = buf.getvalue();

    assert res.purged_count >= 1, f"purged_count={res.purged_count}";
    assert res.stale_count >= 1, f"stale_count={res.stale_count}";
    assert "stale cache" in out and "reprocessing" in out, f"missing stale output: {out}";
}

test "janitor keeps fresh valid cache entry for shortcut reuse" {
    prof = Profile(name="App", pwa_id="com.example.app");
    icon = IconAsset(
        display_name="launcher",
        source_uri="file:///picker/app.png",
        source_hash="same",
        cached_hash="same",
        processed_path="/cache/icons/launcher.adaptive.png",
        is_valid=True
    );
    root ++> prof;
    prof +>:OwnsIcon:+> icon;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CacheJanitor();
    }
    out = buf.getvalue();

    assert res.purged_count == 0, f"expected 0 purged, got {res.purged_count}";
    assert res.stale_count == 0, f"expected 0 stale, got {res.stale_count}";
    assert "fresh: launcher" in out, f"missing fresh output: {out}";
}

