"""Helicarrier Runtime Platform: model the deterministic execution platform as nodes
and edges, and walk the dependency chain with a certifier walker that enforces
ordering, cycle detection, and reachability before any dispatch is authorized."""

# --- Node archetypes ----------------------------------------------------------

node Stage {
    has name: str = "";
    has queue: str = "";
    has done: bool = False;
}

node Platform {
    has name: str = "";
    has role: str = "";
    has deterministic: bool = True;
}

node Responsibility {
    has label: str = "";
    has owner: str = "";
}

node Notebook {
    has topic: str = "";
    has curator: str = "";
    has durable: bool = True;
}

# --- Edge archetypes ----------------------------------------------------------

edge Prereq { has note: str = ""; }
edge Governs { has authority: str = ""; }
edge Compiles { has deterministic: bool = True; }
edge Records { has kind: str = ""; }

# --- Walker: dependency-ordering certifier ------------------------------------

walker Certifier {
    has visited: list[str] = [];
    has order: list[str] = [];
    has cycle_flag: bool = False;

    can start with Root entry {
        print(f"[Certifier] platform={self.platform_name} starting stage sweep");
        visit [->:Prereq:->];
    }

    can audit_stage with Stage entry {
        if here.queue == "production" and not here.done {
            print(f"  production stage '{here.name}' not yet complete — halting");
            disengage;
        }
        self.visited.append(here.name);
        self.order.append(here.name);
        print(f"  audited stage: {here.name} (queue={here.queue})");
        visit [->:Prereq:->] else { disengage; }
    }

    has platform_name: str = "Helicarrier";
    has violations: int = 0;
    has authorized_dispatch: bool = False;
}

# --- Walker: governance boundary inspector ------------------------------------

walker BoundaryInspector {
    has checks: list[str] = [];

    can start with Root entry {
        print("[BoundaryInspector] verifying governance boundaries");
        visit [->:Governs:->];
    }

    can inspect_platform with Platform entry {
        ok = "PASS" if here.deterministic and "reasoning" not in here.role.lower() else "FAIL";
        self.checks.append(f"{here.name}={ok}");
        print(f"  platform {here.name} role='{here.role}' deterministic={here.deterministic} -> {ok}");
        visit [->:Compiles:->];
    }

    can inspect_resp with Responsibility entry {
        forbidden = ["interprets requirements", "creates authority", "changes mission scope"];
        bad = here.label.lower() in forbidden;
        verdict = "VIOLATION" if bad else "ok";
        self.checks.append(f"resp:{here.label}={verdict}");
        print(f"  responsibility '{here.label}' owner={here.owner} -> {verdict}");
        visit [-->];
    }
}

# --- Walker: notebook continuity reachability ---------------------------------

walker NotebookReach {
    has reachable: list[str] = [];
    has max_hops: int = 3;
    has hops: int = 0;

    can start with Root entry {
        print("[NotebookReach] tracing notebook continuity chain");
        visit [->:Records:->];
    }

    can trace with Notebook entry {
        if self.hops >= self.max_hops {
            print(f"  hop cap reached at '{here.topic}'");
            disengage;
        }
        self.reachable.append(here.topic);
        self.hops += 1;
        print(f"  reached notebook '{here.topic}' (curator={here.curator}, durable={here.durable})");
        visit [->:Records:->] else { disengage; }
    }
}

# --- Demo wiring --------------------------------------------------------------

with entry {
    # Production queue chain (Stage A Certification v1 prerequisite)
    stageA = Stage(name="Stage A Cert v1", queue="architecture", done=True);
    helicarrier = Platform(name="Helicarrier", role="deterministic execution platform");
    notebook = Notebook(topic="Mission Knowledge / Notebooks", curator="Hill");

    # Responsibilities assigned to the platform layer
    r_validate = Responsibility(label="governance validation", owner="Helicarrier");
    r_compile = Responsibility(label="deterministic prompt compilation", owner="Helicarrier");
    r_replay = Responsibility(label="replay protection", owner="Helicarrier");
    r_authority = Responsibility(label="creates authority", owner="FORBIDDEN");

    # Typed edges: governance separates from execution, platform compiles,
    # notebook records durable continuity.
    root +>:Prereq(note="Stage A gates Helicarrier"):+> stageA;
    stageA +>:Prereq(note="architecture queue precedes runtime contracts"):+> helicarrier;
    helicarrier +>:Prereq(note="notebook continuity feeds Runtime Contracts v1"):+> notebook;

    root +>:Governs(authority="decides what may happen"):+> helicarrier;
    helicarrier +>:Compiles(deterministic=True):+> r_compile;
    helicarrier +>:Compiles(deterministic=True):+> r_validate;
    helicarrier +>:Compiles(deterministic=True):+> r_replay;
    r_authority +>:Governs(authority="FORBIDDEN at platform layer"):+> helicarrier;

    notebook +>:Records(kind="architecture decision"):+> stageA;
    notebook +>:Records(kind="rejected alternative"):+> helicarrier;

    cert = Certifier();
    root spawn cert;
    print(f"[Certifier] traversal order: {cert.order}");

    insp = BoundaryInspector();
    root spawn insp;
    print(f"[BoundaryInspector] checks: {insp.checks}");

    reach = NotebookReach();
    root spawn reach;
    print(f"[NotebookReach] reachable notebooks: {reach.reachable}");
}

