    has command: str = "";
    has timeout: int = 9;
    has matcher: str = "";
    has fail_closed: bool = False;
    has approved: bool = False;
}

edge OwnsHooks {}
edge HookOf {}
edge Allowlisted {}

walker AppendConfig {
    has event: str = "pre_llm_call";
    has command: str = "";
    has timeout: int = 9;
    has appended: bool = False;

    can start with ConfigRoot entry {
        print(f"config {here.name} (v{here.version}): requesting append to {self.event}");
        visit [->:OwnsHooks:->];
    }

    can descend with HookList entry {
        if here.event == self.event {
            already_present = False;
            for n in [-->] {
                if n.command == self.command {
                    already_present = True;
                }
            }
            if already_present {
                print(f"hook already present: {self.command}");
                disengage;
            }
            new_entry = HookEntry(
                command=self.command,
                timeout=self.timeout,
                matcher="*",
                fail_closed=False
            );
            here +>:HookOf:+> new_entry;
            self.appended = True;
            print(f"appended hook to {here.event}: command={self.command}");
            disengage;
        }
    }
}

