fixed.jac_tests:
"""Tests for the Hermes config append scenario.

The issue: hand-rolled config machinery can't append to a list field, and
the security guard refuses whole-file rewrites, leaving no honest way to
register a hook. This annex verifies the in-graph model:
  - appending adds exactly one HookEntry
  - duplicates don't grow the list
  - approval sets approved=True and adds an Allowlisted self-edge
  - the audit walk distinguishes APPROVED vs PENDING
  - the OwnsHooks root has both event lists wired
"""

import io;
import from contextlib { redirect_stdout }

test "append adds one new hook entry to the target event list" {
    cfg = ConfigRoot();
    pre = HookList(event="pre_llm_call");
    post = HookList(event="post_llm_call");
    cfg +>:OwnsHooks:+> pre;
    cfg +>:OwnsHooks:+> post;

    existing = HookEntry(command="/old/pre.py", timeout=9, matcher="*",
                         fail_closed=False, approved=True);
    pre +>:HookOf:+> existing;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = cfg spawn AppendConfig(
            event="pre_llm_call",
            command="/path/new.py",
            timeout=12
        );
    }
    out = buf.getvalue();

    assert res.appended == True, f"appended flag should be True, got {res.appended}";
    hooks = [pre ->:HookOf:->];
    assert len(hooks) == 2, f"expected 2 entries after append, got {len(hooks)}";
    cmds = sorted([h.command for h in hooks]);
    assert cmds == ["/old/pre.py", "/path/new.py"], f"unexpected command set: {cmds}";
    new_hook = [h for h in hooks if h.command == "/path/new.py"][0];
    assert new_hook.timeout == 12, f"timeout should round-trip, got {new_hook.timeout}";
    assert new_hook.approved == False, f"new hook must start PENDING, got approved={new_hook.approved}";
    assert "appended hook to pre_llm_call" in out, f"missing append log: {out}";

    post_hooks = [post ->:HookOf:->];
    assert len(post_hooks) == 0, f"append must not touch post_llm_call, got {len(post_hooks)}";
}

test "duplicate command is detected and does not grow the list" {
    cfg = ConfigRoot();
    pre = HookList(event="pre_llm_call");
    cfg +>:OwnsHooks:+> pre;

    first = HookEntry(command="/path/new.py", timeout=12, matcher="*",
                      fail_closed=False, approved=False);
    pre +>:HookOf:+> first;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = cfg spawn AppendConfig(
            event="pre_llm_call",
            command="/path/new.py",
            timeout=12
        );
    }
    out = buf.getvalue();

    assert res.appended == False, f"duplicate must leave appended=False, got {res.appended}";
    hooks = [pre ->:HookOf:->];
    assert len(hooks) == 1, f"duplicate must not add a second entry, got {len(hooks)}";
    assert "hook already present" in out, f"missing dedup log: {out}";
}

test "approval marks the hook and adds an Allowlisted self-edge" {
    cfg = ConfigRoot();
    pre = HookList(event="pre_llm_call");
    cfg +>:OwnsHooks:+> pre;

    pending = HookEntry(command="/path/new.py", timeout=12, matcher="*",
                        fail_closed=False, approved=False);
    pre +>:HookOf:+> pending;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        cfg spawn ApproveHook(
            event="pre_llm_call",
            command_match="/path/new.py"
        );
    }
    out = buf.getvalue();

    assert pending.approved == True, f"approved flag should be True, got {pending.approved}";
    allow_edges = [pending ->:Allowlisted:->];
    assert len(allow_edges) == 1, f"expected exactly 1 Allowlisted edge, got {len(allow_edges)}";
    assert allow_edges[0] is pending, f"Allowlisted should be a self-edge on the hook";
    assert "approved hook: /path/new.py" in out, f"missing approve log: {out}";
}

test "audit distinguishes approved from pending hooks" {
    cfg = ConfigRoot();
    pre = HookList(event="pre_llm_call");
    cfg +>:OwnsHooks:+> pre;

    a = HookEntry(command="/old/pre.py", timeout=9, matcher="*",
                  fail_closed=False, approved=True);
    b = HookEntry(command="/path/new.py", timeout=12, matcher="*",
                  fail_closed=False, approved=False);
    pre +>:HookOf:+> a;
    pre +>:HookOf:+> b;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        cfg spawn AuditHooks(event="pre_llm_call");
    }
    out = buf.getvalue();

    assert "[APPROVED] /old/pre.py" in out, f"missing approved line: {out}";
    assert "[PENDING] /path/new.py" in out, f"missing pending line: {out}";
    assert out.count("[APPROVED]") == 1, f"expected exactly 1 APPROVED, got {out}";
    assert out.count("[PENDING]") == 1, f"expected exactly 1 PENDING, got {out}";
    assert "audit pre_llm_call hooks" in out, f"missing audit header: {out}";
}

test "config root owns both event lists via OwnsHooks edges" {
    cfg = ConfigRoot(name="~/.hermes/config.yaml", version=37);
    pre = HookList(event="pre_llm_call");
    post = HookList(event="post_llm_call");
    cfg +>:OwnsHooks:+> pre;
    cfg +>:OwnsHooks:+> post;

    owned = [cfg ->:OwnsHooks:->];
    assert len(owned) == 2, f"root should own exactly 2 HookLists, got {len(owned)}";
    events = sorted([l.event for l in owned]);
    assert events == ["post_llm_call", "pre_llm_call"], f"unexpected events: {events}";
    assert cfg.version == 37, f"version field should round-trip, got {cfg.version}";
}

