    has name: str = "";
}

# Grammar provider selects a text boundary.
edge Selects {}

# UAX29 operates on a boundary at one level.
edge SegmentsAt {}

# UAX spans nest under their parent boundary/span (structural witness).
edge WitnessOf {}

# Downstream recipe requests further processing of a UAX span.
