"""UAX29 boundary walk: graphemes/words/sentences traverse text spans exactly once.

Models Laplace-Refactor issue #103: UAX29 grapheme/word/sentence spans are
terminal witnesses over a selected text boundary. Delimited/grammar providers
may select a boundary once; UAX output itself MUST NOT recursively redispatch
back into UAX29. A text boundary therefore receives exactly one grapheme pass,
one word pass, one sentence pass — child UAX spans never invoke UAX29 again.
"""

# --- Entity archetypes ------------------------------------------------------

node TextBoundary {
    has label: str = "";
    has text: str = "";
}

node DelimitedProvider {
    has name: str = "";
}

node GrammarProvider {
    has name: str = "";
}

node UaxGrapheme {
    has name: str = "grapheme";
}

node UaxWord {
    has name: str = "word";
}

node UaxSentence {
    has name: str = "sentence";
}

# A plain UAX output node: terminal witness, no further UAX29 redispatch.
node UaxOutput {
    has kind: str = "";
    has value: str = "";
}

# --- Typed edges -----------------------------------------------------------

# A provider selects a text boundary (the trigger relationship).
edge Selects {}

# UAX29 produces an output over a selected boundary (the witness relationship).
edge Witnesses {}

# --- Walker: UaxDispatcher --------------------------------------------------
#
# Traversal semantics mirror the fix for issue #103:
#   * A DelimitedProvider or GrammarProvider may pick a TextBoundary once.
#   * That boundary then receives one grapheme, one word, one sentence pass.
#   * UaxOutput is terminal: the walker does NOT recurse back into UAX29
#     children, so a child UAX span cannot re-trigger UAX29 on the same
#     boundary.

walker UaxDispatcher {
    has dispatches: int = 0;
    has grapheme_passes: int = 0;
    has word_passes: int = 0;
    has sentence_passes: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can from_provider with DelimitedProvider | GrammarProvider entry {
        # Provider selects the next boundary once, then walks into it.
        visit [->:Selects:->];
    }

    can dispatch_uax with TextBoundary entry {
        # ONE boundary gets ONE pass of each UAX layer. We dispatch to the
        # three UAX child nodes via the Witnesses edge. Each UaxXxx node
        # will report its pass once and terminate at the UaxOutput — the
        # UaxOutput does not redispatch back into UAX29 children, which
        # is exactly the fix for issue #103.
        self.dispatches += 1;
        visit [->:Witnesses:->];
    }

    can pass_grapheme with UaxGrapheme entry {
        self.grapheme_passes += 1;
        # UAX layer outputs its terminal witness and stops — no UAX29
        # redispatch through UaxOutput children.
        visit [->:Witnesses:->];
    }

    can pass_word with UaxWord entry {
        self.word_passes += 1;
        visit [->:Witnesses:->];
    }

    can pass_sentence with UaxSentence entry {
        self.sentence_passes += 1;
        visit [->:Witnesses:->];
    }

    can terminate with UaxOutput entry {
        # Terminal: UaxOutput does not re-enter UAX29. End of branch.
        disengage;
    }
}

# --- Demonstration ----------------------------------------------------------

with entry {
    # Two text boundaries (the structural witnesses over selected text).
    para1 = TextBoundary(label="para-1", text="Hello world.");
    para2 = TextBoundary(label="para-2", text="Goodbye.");

    # Two providers may select boundaries once each.
    delimited = DelimitedProvider(name="delim");
    grammar = GrammarProvider(name="grammar");

    # UAX29 layer nodes (the three passes).
    grapheme = UaxGrapheme();
    word = UaxWord();
    sentence = UaxSentence();

    # Provider -> boundary selections.
    delimited +>:Selects:+> para1;
    grammar +>:Selects:+> para2;

    # Boundary -> UAX layer (one of each kind per boundary).
    para1 +>:Witnesses:+> grapheme;
    para1 +>:Witnesses:+> word;
    para1 +>:Witnesses:+> sentence;

    para2 +>:Witnesses:+> grapheme;
    para2 +>:Witnesses:+> word;
    para2 +>:Witnesses:+> sentence;

    # Terminal UaxOutput children attached to each UAX layer. These are
    # the leaves that the OLD code re-entered UAX29 from; the fix
    # disengages here instead.
    grapheme +>:Witnesses:+> UaxOutput(kind="grapheme", value="H");
    grapheme +>:Witnesses:+> UaxOutput(kind="grapheme", value="e");
    word +>:Witnesses:+> UaxOutput(kind="word", value="Hello");
    word +>:Witnesses:+> UaxOutput(kind="word", value="world");
    sentence +>:Witnesses:+> UaxOutput(kind="sentence", value="Hello world.");

    # Wire the demo graph.
    root ++> delimited;
    root ++> grammar;

    # Spawn the dispatcher and run the traversal.
    dispatcher = UaxDispatcher();
    root spawn dispatcher;

    print(
        f"dispatches={dispatcher.dispatches} "
        f"grapheme_passes={dispatcher.grapheme_passes} "
        f"word_passes={dispatcher.word_passes} "
        f"sentence_passes={dispatcher.sentence_passes}"
    );
    # Expected: dispatches==2 (one per boundary),
    #           grapheme_passes==2, word_passes==2, sentence_passes==2.
    # The UaxOutput terminal leaves do NOT increment any UAX counter,
    # proving no recursive UAX29 redispatch over the same boundary.
}

