"""Sacred Geometry engine: cache idempotency hardening across the symbol/ratio/chakra lattice.

Models the engine-specific truth as a small OSP graph:
  - SacredForm (geometric archetype: pentagram, hexagram, ...)
  - RatioSpec (golden/phi/sqrt2 numeric precision contract)
  - CacheEntry (cache-idempotency slice: contract/engine/algorithm/source
                version fingerprint)
  - RenderedArtifact (the derived output, distinguishable from raw geometry)

Typed edges carry the relationships the engine complains about:
  - HasRatio      : SacredForm -> RatioSpec        (a form *binds* a ratio)
  - BindsChakra   : SacredForm -> SacredForm       (form -> chakra element)
  - CachedAs      : SacredForm -> CacheEntry       (cache-key projection)
  - Yields        : SacredForm -> RenderedArtifact (the produced output)

A walker (CacheAuditor) traverses the cached projection of a SacredForm,
prints the deterministic cache-key, and decides whether the entry is
stale based on the source-version field. A second walker
(Invalidator) walks the cache projection and invalidates stale entries,
matching the invalidation pass described in the issue.
"""

node SacredForm {
    has name: str = "";
    has form_kind: str = "";      # pentagram, hexagram, torus, ...
    has source_version: str = "";  # version that produced the rendered artifact
    has cached: bool = True;
}

node RatioSpec {
    has ratio_name: str = "";     # phi, sqrt2, silver, ...
    has precision: int = 6;       # decimal places the contract demands
}

node CacheEntry {
    has contract_version: str = "";
    has engine_version: str = "";
    has algorithm: str = "";
    has source_version: str = "";
    has fingerprint: str = "";
    has stale: bool = False;
}

node RenderedArtifact {
    has artifact_kind: str = "";  # svg, ascii, numeric-table, ...
    has bytes_hint: int = 0;
}

edge HasRatio { }
edge BindsChakra { }
edge CachedAs { }
edge Yields { }

walker CacheAuditor {
    has stale_seen: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit_form with SacredForm entry {
        # Walk the cache projection of this SacredForm; this is the
        # traversal the issue says is hand-rolled in the engine.
        visit [->:CachedAs:->];
    }

    can audit_entry with CacheEntry entry {
        label = "STALE" if here.stale else "FRESH";
        self.stale_seen += 1 if here.stale else 0;
        print(
            f"[{label}] key={here.fingerprint} "
            f"(contract={here.contract_version}, engine={here.engine_version}, "
            f"algo={here.algorithm}, src={here.source_version})"
        );
    }
}

walker Invalidator {
    has purged: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can sweep_form with SacredForm entry {
        visit [->:CachedAs:->];
    }

    can purge with CacheEntry entry {
        if here.stale {
            here.stale = False;
            here.fingerprint = here.fingerprint + ":repinned";
            self.purged += 1;
            print(f"revalidated -> {here.fingerprint}");
        }
    }
}

with entry {
    # Two sacred forms: one fresh cache, one stale cache key.
    pentagram = SacredForm(
        name="Pentagram",
        form_kind="five-pointed-star",
        source_version="src-1.0",
        cached=True,
    );
    hexagram = SacredForm(
        name="Hexagram",
        form_kind="six-pointed-star",
        source_version="src-1.2",
        cached=True,
    );

    # The ratio contract that each form binds.
    phi = RatioSpec(ratio_name="phi", precision=8);
    silver = RatioSpec(ratio_name="silver", precision=6);

    pentagram +>:HasRatio:+> phi;
    hexagram +>:HasRatio:+> silver;

    # Chakra bindings (form -> chakra element relationships).
    pentagram +>:BindsChakra:+> SacredForm(
        name="Solar Plexus", form_kind="chakra", source_version="src-1.0"
    );

    # Rendered artifacts, distinguishable from raw geometry.
    pentagram +>:Yields:+> RenderedArtifact(
        artifact_kind="svg", bytes_hint=4096
    );
    hexagram +>:Yields:+> RenderedArtifact(
        artifact_kind="ascii", bytes_hint=512
    );

    # Cache entries: contract/engine/algorithm/source fingerprint.
    # The stale one models a cache key whose source_version no longer
    # matches the SacredForm's source_version (the bug the issue asks
    # us to harden against).
    pentagram +>:CachedAs:+> CacheEntry(
        contract_version="v1",
        engine_version="eng-0.7",
        algorithm="phi-spiral",
        source_version="src-1.0",
        fingerprint="v1|eng-0.7|phi-spiral|src-1.0",
        stale=False,
    );
    hexagram +>:CachedAs:+> CacheEntry(
        contract_version="v1",
        engine_version="eng-0.6",
        algorithm="silver-mean",
        source_version="src-1.1",
        fingerprint="v1|eng-0.6|silver-mean|src-1.1",
        stale=True,
    );

    auditor = CacheAuditor();
    print("--- CacheAuditor pass ---");
    root spawn auditor;
    print(f"stale entries observed: {auditor.stale_seen}");

    invalidator = Invalidator();
    print("--- Invalidator pass ---");
    root spawn invalidator;
    print(f"entries revalidated: {invalidator.purged}");
