            self.report["orders_pending"] += 1;
        }
        # Identify the channel kind by walking back one Placed edge
        # (Order -> Channel) — here.channel is not stored; we infer
        # via the single inbound Placed neighbor.
        parent_channels = [here <-:Placed:-];
        if parent_channels.length > 0 {
            ch = parent_channels[0];
            bucket = self.report["channels"][ch.kind];
            bucket["order_count"] += 1;
            if here.completed {
                bucket["completed_count"] += 1;
                bucket["revenue_cents"] += here.subtotal_cents;
                self.report["channels_with_revenue"] += 1;
            } else {
                bucket["pending_count"] += 1;
            }
            print(f"        Order#{here.order_id} "
                  f"{here.subtotal_cents}c "
                  f"{'OK' if here.completed else 'PENDING'}");
        }
    }
