"""Roster cap determinism demo.

Models the SuperFamousGuy/AutoTiers issue: cap membership under tied vbd_score
must be deterministic. Players are nodes connected by ``OnRoster`` edges;
``CapAudit`` walks the position groups, sorts each by score with a stable
player_id tiebreak, slices the per-position floor, and finally drains the
remaining budget across positions in a stable order.
"""

node Player {
    has player_id: str = "";
    has vbd_score: float = 0.0;
    has pos: str = "";
}

node PositionGroup {
    has pos: str = "";
}

edge OnRoster {
    has rank_hint: int = 0;
}

walker CapAudit {
    has per_position_min: int = 1;
    has remaining_budget: int = 1;
    has survivors: list[str] = [];
    has pool: list = [];

    can start with Root entry {
        visit [-->];
    }

    can group with PositionGroup entry {
        members = [here ->:OnRoster:->];
        scored = [];
        for m in members {
            scored.append((-m.vbd_score, m.player_id, m));
        }
        scored = sorted(scored);
        idx = 0;
        for item in scored {
            if idx < self.per_position_min {
                self.survivors.append(item[2].player_id);
            } else {
                self.pool.append(item[2]);
            }
            idx += 1;
        }
        visit [-->];
    }

    can finalize with Root entry {
        cap_size = self.per_position_min + self.remaining_budget;
        pool_sorted = [];
        for p in self.pool {
            pool_sorted.append((-p.vbd_score, p.player_id, p));
        }
        pool_sorted = sorted(pool_sorted);
        idx = 0;
        for item in pool_sorted {
            if len(self.survivors) >= cap_size {
                break;
            }
            self.survivors.append(item[2].player_id);
            idx += 1;
        }
    }
}

