# sys.getrecursionlimit(); the issue's point is that the iterative walk
# must not depend on it at all.
glob RECURSION_BUDGET: int = 200;

walker RecursiveAssembler {
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can descend with Value entry {
        self.seen.append(here.label);
        if here.depth >= RECURSION_BUDGET {
            print(f"  [RECURSIVE] depth {here.depth} reached budget; "
                  f"would blow the stack here");
            disengage;
        }
        visit [-->];
    }
}

walker IterativeAssembler {
    has seen: list[str] = [];
    has cycles: list[str] = [];

    can start with Root entry {
        # The walker has no built-in once-per-node guarantee, so we keep
        # the cycle policy explicit — same posture as the source tooth.
        self.seen.append(here.label);
        visit [-->];
    }

    can descend with Value entry {
        # A coordinate the walker has already touched is a cycle, not
        # "more depth". Coordinates can separate those; frame names cannot.
        already = [label for label in self.seen if label == here.label];
        if already {
            self.cycles.append(here.label);
