            if v == here.username {
                already = True;
            }
        }
        if already {
            disengage;
        }
        self.visited = self.visited + [here.username];
        if here.username == self.target_name {
            self.done = True;
            disengage;
        }
        self.path = self.path + [here.username];
        self.hops = self.hops + 1;
        visit [->:Follows:->] else { disengage; }
    }
}

walker RecommendFriends {
    has seed_name: str = "";
    has seen: list[str] = [];
    has picks: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can seed with User entry {
        if here.username != self.seed_name {
            visit [-->];
        }
        self.seen = self.seen + [here.username];
        visit [->:Follows:->];
    }

    can hop with User entry {
        already = False;
        for v in self.seen {
            if v == here.username {
                already = True;
            }
        }
        if already {
            disengage;
        }
        self.seen = self.seen + [here.username];
        visit [->:Follows:->];
    }

    can candidate with User entry {
        if (here.username != self.seed_name) {
            dup = False;
            for p in self.picks {
                if p == here.username {
                    dup = True;
                }
            }
            if not dup {
                self.picks = self.picks + [here.username];
            }
        }
    }
}

walker CommonNeighbors {
    has a_name: str = "";
    has b_name: str = "";
    has common: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can first with User entry {
        if here.username != self.a_name {
            visit [-->];
        }
        visit [->:Follows:->];
    }

    can second with User entry {
        if here.username != self.b_name {
            visit [-->];
        }
        visit [->:Follows:->];
    }

    can collect with User entry {
        if (here.username != self.a_name) and (here.username != self.b_name) {
            self.common = self.common + [here.username];
        }
    }
}

walker CascadePurge {
    has owner: str = "";
    has removed_posts: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can pick with User entry {
        if here.username != self.owner {
            visit [-->];
        }
        visit [->:Authored:->];
    }

    can collect_post with Post entry {
        self.removed_posts = self.removed_posts + [here.title];
        del here;
    }
}

