"""Cross-contract reentrancy detection via multi-hop call-graph traversal.

Models ChainProof's CP-121 detector natively: contracts are nodes, external
calls become typed edges, and a walker traverses the call graph to find
chains that re-enter a contract whose state is still unfinalized. Guarded
chains are recognized and skipped to avoid false positives. Traversal is
bounded by a configurable depth cap, and cycles are short-circuited when
they involve finalized state.
"""

node Contract {
    has name: str = "";
    # `state_finalized` is True when the contract has applied its
    # checks-effects-interactions pattern (or any other guard) at the
    # point we are observing it. Unfinalized contracts are reentrancy-
    # sensitive.
    has state_finalized: bool = False;
    # `guarded` is True when the contract carries a reentrancy guard
    # modifier on the relevant entry function.
    has guarded: bool = False;
}

# External-call edge: from the caller contract to the callee contract.
# Carries the calling function and the called function as payload so the
# finding can report the full path.
edge Calls {
    has from_fn: str = "";
    has to_fn: str = "";
}

# Finding node: produced by the walker for every exploitable chain it
# discovers. Each finding records the full path as a list of contract
# names; the walker fills it on entry.
node Finding {
    has path: list[str] = [];
    has severity: str = "critical";
}

walker ReentrancyHunter {
    has max_depth: int = 3;
    # Per-walker accumulator of the contract names visited so far.
    has current_chain: list[str] = [];
    # Findings produced during this walk.
    has findings: list = [];

    can start with Root entry {
        # Kick the walker into every top-level contract.
        visit [-->];
    }

    can scan with Contract entry {
        # Cycle guard: we may revisit a contract only when we have
        # descended further along the chain. Revisits at the same depth
        # would otherwise spin forever (walker primitives do not
        # dedupe). We also short-circuit if the contract is guarded or
        # has finalized state at the entry point - no reentrancy
        # exploit possible from a guarded/finalized hop.
        already = False;
        for n in self.current_chain {
            if n == here.name {
                already = True;
                break;
            }
        }
        if already {
            # Cycle: bail out of this branch.
            disengage;
        }
        if here.guarded {
            # Reentrancy guard present, no exploitable chain here.
            disengage;
        }
        if here.state_finalized {
            # Checks-effects-interactions already applied: safe.
            disengage;
        }

        # Extend the chain and check for re-entry into a contract that
        # is unfinalized. The initial node of the chain is excluded:
        # a 1-hop chain is just a normal external call.
        self.current_chain.append(here.name);
        if self.current_chain.length > 1 {
            head_name = self.current_chain[0];
            if here.name == head_name and not here.state_finalized {
                self.findings.append(
                    Finding(path=list(self.current_chain), severity="critical")
                );
            }
        }

        # Bounded forward traversal along typed Calls edges.
        if self.current_chain.length < self.max_depth {
            visit [->:Calls:->];
        }

        # Pop on the way out so siblings start from the right prefix.
        self.current_chain.pop();
    }
}

with entry {
    # Build a tiny universe of contracts.
    vault = Contract(name="Vault", state_finalized=False, guarded=False);
    strategy = Contract(name="Strategy", state_finalized=False, guarded=False);
    flashloan = Contract(name="FlashLoan", state_finalized=False, guarded=False);
    safe = Contract(name="SafeBank", state_finalized=False, guarded=True);

    # Wire the call graph. Vault calls Strategy, Strategy calls back
    # into Vault (2-hop reentrancy). Vault also calls FlashLoan which
    # calls Strategy which calls back into Vault (3-hop reentrancy).
    # SafeBank is guarded and should never produce a finding.
    vault +>:Calls(from_fn="withdraw", to_fn="deposit"):+> strategy;
    strategy +>:Calls(from_fn="deposit", to_fn="withdraw"):+> vault;

