    flashloan +>:Calls(from_fn="borrow", to_fn="rebalance"):+> strategy;
    strategy +>:Calls(from_fn="rebalance", to_fn="withdraw"):+> vault;

    safe +>:Calls(from_fn="withdraw", to_fn="deposit"):+> strategy;
    strategy +>:Calls(from_fn="deposit", to_fn="withdraw"):+> safe;

    # Register the contracts under root so the walker can reach them.
    root ++> vault ++> strategy ++> flashloan ++> safe;

    hunter = ReentrancyHunter(max_depth=3);
    root spawn hunter;

    # Report findings the walker collected.
    if hunter.findings.length == 0 {
        print("No cross-contract reentrancy found.");
    } else {
        for f in hunter.findings {
            chain = " -> ".join(f.path);
            print(f"[{f.severity}] reentrancy chain: {chain}");
        }
    }
    print(f"total findings: {hunter.findings.length}");
}

