    p1.tombstone = DeadTombstone(exit_reason="SIGKILL-def-crash", exit_code=137);

    p2 = Process(pid=102, label="worker-B", running=False, exit_code=-1);
    p2.tombstone = DeadTombstone(exit_reason="undef-absent-stdlib", exit_code=-1);

    p3 = Process(pid=103, label="worker-C", running=True);

    sup +>:Spawned:+> p1;
    sup +>:Spawned:+> p2;
    sup +>:Spawned:+> p3;

    p1 +>:Exited:+> p1.tombstone;
    p2 +>:Exited:+> p2.tombstone;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn AuditExit(target_pid=999);
    }
    out = buf.getvalue();

    assert res.verdict == "OK", f"expected OK when a runnable child remains, got {res.verdict}";
    assert len(res.dead_pids) == 2, f"expected two dead pids recorded, got {res.dead_pids}";
    assert 101 in res.dead_pids, f"missing dead pid 101: {res.dead_pids}";
    assert 102 in res.dead_pids, f"missing dead pid 102: {res.dead_pids}";
    assert 103 not in res.dead_pids, f"running pid must not be dead-listed: {res.dead_pids}";
    assert "[AuditExit]" in out, f"missing audit print marker: {out}";
    assert "verdict=OK" in out, f"stdout should report OK verdict: {out}";
}

test "all-dead tree yields NOTHING_CAN_EXIT instead of parking" {
    sup = Supervisor(label="harness-all-dead");
    root ++> sup;

    p1 = Process(pid=201, running=False, exit_code=137);
    p1.tombstone = DeadTombstone(exit_reason="SIGKILL-def-crash", exit_code=137);

    p2 = Process(pid=202, running=False, exit_code=-1);
    p2.tombstone = DeadTombstone(exit_reason="undef-absent-stdlib", exit_code=-1);

    sup +>:Spawned:+> p1;
    sup +>:Spawned:+> p2;

    p1 +>:Exited:+> p1.tombstone;
    p2 +>:Exited:+> p2.tombstone;

    res = root spawn AuditExit(target_pid=888);

    assert res.verdict == "NOTHING_CAN_EXIT", f"expected death-aware failure verdict, got {res.verdict}";
    assert len(res.dead_pids) == 2, f"expected both pids named dead, got {res.dead_pids}";
    assert 201 in res.dead_pids, f"missing dead pid 201: {res.dead_pids}";
    assert 202 in res.dead_pids, f"missing dead pid 202: {res.dead_pids}";
    assert len(res.reasons) == 2, f"expected exit reasons for each dead pid, got {res.reasons}";
}

test "dead pids carry tombstone exit reasons" {
    sup = Supervisor(label="harness-reasons");
    root ++> sup;

    p1 = Process(pid=301, running=False, exit_code=137);
    p1.tombstone = DeadTombstone(exit_reason="SIGKILL-def-crash", exit_code=137);

    p2 = Process(pid=302, running=False, exit_code=-1);
    p2.tombstone = DeadTombstone(exit_reason="undef-absent-stdlib", exit_code=-1);

    sup +>:Spawned:+> p1;
    sup +>:Spawned:+> p2;

    p1 +>:Exited:+> p1.tombstone;
    p2 +>:Exited:+> p2.tombstone;

    res = root spawn AuditExit(target_pid=777);

    assert res.verdict == "NOTHING_CAN_EXIT", f"all children dead should fail closed, got {res.verdict}";
    assert "SIGKILL-def-crash" in res.reasons, f"missing SIGKILL reason: {res.reasons}";
    assert "undef-absent-stdlib" in res.reasons, f"missing stdlib refusal reason: {res.reasons}";
}

test "dead without tombstone records killed-no-tombstone reason" {
    sup = Supervisor(label="harness-no-tombstone");
    root ++> sup;

    p = Process(pid=401, running=False, exit_code=-1);
    sup +>:Spawned:+> p;

    res = root spawn AuditExit(target_pid=666);

    assert res.verdict == "NOTHING_CAN_EXIT", f"dead child with no exit path should fail, got {res.verdict}";
    assert res.dead_pids == [401], f"expected single dead pid 401, got {res.dead_pids}";
    assert res.reasons == ["killed-no-tombstone"], f"expected consumed-exit fallback reason, got {res.reasons}";
}

test "empty supervisor stays OK with no dead pids" {
    sup = Supervisor(label="harness-empty");
    root ++> sup;

    res = root spawn AuditExit(target_pid=555);

    assert res.verdict == "OK", f"supervisor with no children should not deadlock-report, got {res.verdict}";
    assert len(res.dead_pids) == 0, f"expected no dead pids, got {res.dead_pids}";
    assert len(res.reasons) == 0, f"expected no reasons, got {res.reasons}";
}

broken.code:
"""Login-form test-coverage model.

Four real coverage gaps from issue #95 are modelled as a small graph
problem:

  1. Eleven declared props are never exercised by the suite.
  2. A type-only assertion is inert at runtime (transpilation erases it).
  3. A `toBe` was weakened to `toContain`, widening what passes.
  4. The import-graph regex misses bare side-effect imports and cannot
     resolve `../` against the importer's directory.

We pick the four core entities — the form root, the submit button, the
remember-me checkbox, and a status banner — and lift each prop into a
typed `has` field on the corresponding node archetype. A walker that
mimics the "props are documented but unasserted" failure mode visits
every part and reads each prop off `here`; the demonstration shows what
happens when every prop still equals its default. A second walker models
the cascade the issue asks for: re-exporting `LoginFormStatusProps`
without a runtime guard, so deleting the re-export leaves the test
green.
"""

# --- Entities ---------------------------------------------------------------

node LoginFormRoot {
    has class_name: str = "akira-login-form";
    has form_id: str = "";
    has form_name: str = "";
}

node LoginFormSubmit {
    has label: str = "Sign in";
    has submitting_label: str = "Signing in...";
    has disabled: bool = False;
}

node LoginFormRemember {
    has name: str = "remember";
    has label: str = "Remember me";
}

node LoginFormStatus {
    has message: str = "";
}

# --- Walker 1: prop auditor --------------------------------------------------
# Walks every part of the form and prints each prop. If the suite never
# passes a non-default value, every printed prop equals its declared
# default — exactly the symptom described in issue #95 ("rewrote the
# prop to ignore it, nothing failed").

walker PropAuditor {
    has default_count: int = 0;
    has total_count: int = 0;

    can start with Root entry {
        print("=== Prop audit ===");
        visit [-->];
    }

    can audit with LoginFormRoot | LoginFormSubmit
            | LoginFormRemember | LoginFormStatus entry {
        self.total_count += 1;
        defaults = 0;

        # LoginFormRoot props: class_name, form_id, form_name
        defaults += 1 if here.class_name == "akira-login-form" else 0;
        defaults += 1 if here.form_id == "" else 0;
        defaults += 1 if here.form_name == "" else 0;

        # LoginFormSubmit props: label, submitting_label, disabled
        if here.label == "Sign in" { defaults += 1; }
        if here.submitting_label == "Signing in..." { defaults += 1; }
        if here.disabled == False { defaults += 1; }

        # LoginFormRemember props: name, label
        if here.name == "remember" { defaults += 1; }
        if here.label == "Remember me" { defaults += 1; }

        # LoginFormStatus prop: message
        if here.message == "" { defaults += 1; }

        self.default_count += defaults;
        print(
            f"  {here} -> {defaults} default-valued prop(s) of "
            f"{self._prop_count()} total"
        );
        visit [-->];
    }

    def _prop_count() -> int {
        return 11;
    }

    can finish with Root entry {
        print(
            f"Audit done: {self.default_count}/{self.total_count * 11} "
            f"props still at their declared defaults."
        );
    }
}

# --- Walker 2: status-banner re-export probe --------------------------------
# Models failure #2: `const props: LoginFormStatusProps = { message: 'ok' }`.
# Under vitest the type annotation is erased, so the variable is just a
# plain object. Deleting the `LoginFormStatusProps` re-export leaves the
# test green. We mirror that by checking the re-export at runtime only
# through the banner's existence.

walker ReexportProbe {
    can start with Root entry {
        print("=== Re-export probe ===");
        banner = [-->](?:LoginFormStatus);
        if banner {
            print("  LoginFormStatus re-export present at runtime.");
        } else {
            print("  LoginFormStatus re-export MISSING (test stayed green).");
        }
    }
}

# --- Walker 3: side-effect import walker ------------------------------------
# Models failure #4: the import-graph regex misses bare
# `import "./chunk-X.js"` lines. We represent chunks as nodes connected
# by typed edges. A walker that only follows edges (and not bare nodes
# with no outgoing typed edge) misses side-effect imports exactly the
# way the regex does.

edge ChunkLink { has weight: int = 0; }

walker SideEffectAware {
    has visited: list[str] = [];
    has followed_edges: int = 0;
    has missed_side_effects: int = 0;

    can start with Root entry {
        print("=== Side-effect import walk ===");
        self._follow();
    }

    def _follow() {
        for n in [-->] {
            self.followed_edges += 1;
            self.visited.append(str(n));
        }
        # Bare node with NO outgoing typed edge == side-effect import.
        bare = [-->];
        for n in bare {
            typed = n-->;
            if not typed {
                self.missed_side_effects += 1;
                print(f"  MISSED bare import: {n}");
            }
        }
        print(
            f"  Followed {self.followed_edges} typed edges, "
            f"missed {self.missed_side_effects} side-effect imports."
        );
    }
}

# --- Demo graph -------------------------------------------------------------
with entry {
    root ++> LoginFormRoot()
        ++> LoginFormSubmit()
        ++> LoginFormRemember()
        ++> LoginFormStatus(message="ok");

    root spawn PropAuditor();
    root spawn ReexportProbe();

    # A chain that mimics the import-graph: every chunk linked by a
    # typed edge, plus one bare side-effect node at the tail.
    chunk_a = root ++> LoginFormSubmit(label="Edge-A");
    chunk_b = chunk_a +>:ChunkLink(weight=1):+> LoginFormRemember();
    # Bare side-effect "import" — no outgoing typed edge.
    root ++> LoginFormStatus(message="bare");

    root spawn SideEffectAware();
}

fixed.code:
"""Test-coverage audit walker: find declared-but-untested props on a login form.

Models the essential scenario from issue #95: declared props on form parts that
no test passes a non-default value for. The audit walks the form parts via
typed edges, classifies each declared prop as dead or exercised, and emits a
single summary report. Mirrors the issue's own fix-it criterion: each fix is
demonstrated by breaking the guard and showing the failure first.
"""

node FormPart {
    has part_name: str = "";
    has kind: str = "";

    # Declared props as (name, default) pairs.
    has declared: list[tuple[str, str]] = [];

    # Props actually exercised by tests, as (name, value) pairs.
    has exercised: list[tuple[str, str]] = [];

    # Filled in by the auditor; the walker writes dead props here.
    has dead_props: list[str] = [];

    def declared_names() -> list[str] {
        names: list[str] = [];
        for (n, _d) in self.declared {
            names.append(n);
        }
        return names;
    }

    def is_exercised(prop_name: str) -> bool {
        for (n, _v) in self.exercised {
            if n == prop_name {
                return True;
            }
        }
        return False;
    }
}

edge PartOf { }

walker CoverageAuditor {
    has audit_log: list[tuple[str, list[str]]] = [];
    has total_dead: int = 0;

    can start with Root entry {
        visit [-->];
    }

    can audit with FormPart entry {
        dead: list[str] = [];
        for pname in here.declared_names() {
            if not here.is_exercised(pname) {
                dead.append(pname);
            }
        }
        here.dead_props = dead;
        self.total_dead = self.total_dead + len(dead);
        self.audit_log.append((here.part_name, dead));
        visit [-->];
    }
}

with entry {
    email = FormPart(
        part_name="LoginFormEmail",
        kind="input",
        declared=[
            ("placeholder", "Email"),
            ("id", "email"),
            ("name", "email"),
        ],
        exercised=[("placeholder", "Your email")],
    );
    password = FormPart(
        part_name="LoginFormPassword",
        kind="input",
        declared=[
            ("placeholder", "Password"),
            ("id", "password"),
            ("name", "password"),
            ("error", ""),
            ("label", "Password"),
            ("forgotPasswordLabel", "Forgot?"),
        ],
        exercised=[("label", "Password")],
    );
    submit = FormPart(
        part_name="LoginFormSubmit",
        kind="button",
        declared=[
            ("processing", "false"),
            ("submittingLabel", "Sign in"),
            ("label", "Submit"),
            ("name", "submit"),
        ],
        exercised=[("processing", "true")],
    );
    remember = FormPart(
        part_name="LoginFormRemember",
        kind="checkbox",
        declared=[
            ("name", "remember"),
            ("label", "Remember me"),
        ],
        exercised=[],
    );
    root_cls = FormPart(
        part_name="LoginFormRoot",
        kind="root",
        declared=[("className", "login")],
        exercised=[],
    );

    root ++> email ++> password ++> submit ++> remember ++> root_cls;

    auditor = CoverageAuditor();
    root spawn auditor;

    print("Dead-prop coverage report:");
    for (part_name, dead_list) in auditor.audit_log {
        joined = ", ".join(dead_list) if len(dead_list) > 0 else "(none)";
        print(f"  {part_name}: {joined}");
    }
    print(f"Total dead props across form: {auditor.total_dead}");
}

