    b = FormPart(part_name="B", kind="x", declared=[("p1", "d"), ("p2", "d")], exercised=[("p1", "v")]);
    c = FormPart(part_name="C", kind="x", declared=[("p1", "d"), ("p2", "d"), ("p3", "d")], exercised=[]);
    rt ++> a ++> b ++> c;
