import io;
import from contextlib { redirect_stdout }

test "initial shared slot: every shell read sees the same path" {
    slot = CwdSlot(path="/repo/main", last_writer="init");
    orch = Shell(owner="orchestrator", last_observed_path="/repo/main");
    root ++> slot;
    root ++> orch;
    root +>:EnterWorktree(target_path="/repo/lane-a", caller="subagent-A"):+>
        Shell(owner="subagent-A", last_observed_path="/repo/main");
    root +>:EnterWorktree(target_path="/repo/lane-b", caller="subagent-B"):+>
        Shell(owner="subagent-B", last_observed_path="/repo/main");

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn ReadCwd(owner="orchestrator");
        root spawn ReadCwd(owner="subagent-A");
        root spawn ReadCwd(owner="subagent-B");
    }
    out = buf.getvalue();
    assert "shell owner=orchestrator sees path=/repo/main writer=init" in out,
        f"orchestrator should read shared initial path: {out}";
    assert "shell owner=subagent-A sees path=/repo/main writer=init" in out,
        f"subagent-A should read same slot as orchestrator: {out}";
    assert "shell owner=subagent-B sees path=/repo/main writer=init" in out,
        f"subagent-B should read same slot as orchestrator: {out}";
}

test "EnterWorktree by subagent mutates shared slot observed by non-caller" {
    slot = CwdSlot(path="/repo/main", last_writer="init");
    orch = Shell(owner="orchestrator", last_observed_path="/repo/main");
    root ++> slot;
    root ++> orch;
    root +>:EnterWorktree(target_path="/repo/lane-a", caller="subagent-A"):+>
        Shell(owner="subagent-A", last_observed_path="/repo/main");

    slot.path = "/repo/lane-a";
    slot.last_writer = "subagent-A";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn ReadCwd(owner="orchestrator");
    }
    out = buf.getvalue();
    assert "shell owner=orchestrator sees path=/repo/lane-a writer=subagent-A" in out,
        f"orchestrator shell should see subagent-A's slot write: {out}";
}

test "deep subagent EnterWorktree last-writer-wins across orchestrator and siblings" {
    slot = CwdSlot(path="/repo/lane-b", last_writer="subagent-B");
    root ++> slot;
    root ++> Shell(owner="orchestrator", last_observed_path="/repo/main");
    root +>:EnterWorktree(target_path="/repo/lane-a", caller="subagent-A"):+>
        Shell(owner="subagent-A", last_observed_path="/repo/main");
    root +>:EnterWorktree(target_path="/repo/lane-b", caller="subagent-B"):+>
        Shell(owner="subagent-B", last_observed_path="/repo/main");
    root +>:EnterWorktree(target_path="/repo/lane-c", caller="subagent-A->subagent-C"):+>
        Shell(owner="subagent-C", last_observed_path="/repo/main");

    slot.path = "/repo/lane-c";
    slot.last_writer = "subagent-A->subagent-C";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn ReadCwd(owner="orchestrator");
        root spawn ReadCwd(owner="subagent-A");
        root spawn ReadCwd(owner="subagent-B");
    }
    out = buf.getvalue();
    assert "shell owner=orchestrator sees path=/repo/lane-c writer=subagent-A->subagent-C" in out,
        f"orchestrator should be clobbered by deep subagent: {out}";
    assert "shell owner=subagent-A sees path=/repo/lane-c writer=subagent-A->subagent-C" in out,
