import io;
import from contextlib { redirect_stdout }

test "split and merge triggers traverse touched clusters" {
    part = IndexPartition(
        partition_name="vec-part-0",
        generation=3,
        pinned_instant="mdt-20240501"
    );
    stats = ClusterStats();
    big = Cluster(cluster_id="C-big", size=11);
    mid = Cluster(cluster_id="C-mid", size=5);
    small = Cluster(cluster_id="C-small", size=1);

    root +>:TouchedByMaintenance(op="compaction"):+> part;
    part +>:Surfaces:+> stats;
    part +>:Owns:+> big;
    part +>:Owns:+> mid;
    part +>:Owns:+> small;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LireRebalancer();
    }
    out = buf.getvalue();

    assert res.rebalances == 2, f"got {res.rebalances}";
    assert res.splits == 1, f"got {res.splits}";
    assert res.merges == 1, f"got {res.merges}";
    assert stats.split_threshold == 8, f"got {stats.split_threshold}";
    assert stats.merge_threshold == 2, f"got {stats.merge_threshold}";
    assert "cluster=C-big size=11 -> SPLIT" in out, f"got {out}";
    assert "cluster=C-small size=1 -> MERGE" in out, f"got {out}";
}

test "replacement traversal mutates centroid and observes tombstone" {
    cluster = Cluster(cluster_id="C-old", size=5);
    replacement = Replacement(
        replacement_id="C-new",
        source_id="C-old",
        centroid=[4.0, 4.0]
    );
    tombstone = Tombstone(
        victim_id="C-old",
        reason="split-replaced"
    );

    root +>:Owns:+> cluster;
    cluster +>:ReplacedBy:+> replacement;
    replacement +>:Surfaces:+> tombstone;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LireRebalancer();
    }
    out = buf.getvalue();

    assert replacement.centroid == [-3.0, -3.0], f"got {replacement.centroid}";
    assert "replacement=C-new" in out, f"got {out}";
    assert "tombstone victim=C-old reason=split-replaced" in out, f"got {out}";
    assert res.rebalances == 0, f"got {res.rebalances}";
}

test "mismatch observer records rebuild trigger" {
    stats = ClusterStats();
    root +>:Surfaces:+> stats;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn MismatchObserver();
    }
    out = buf.getvalue();

    assert stats.mismatches == 4, f"got {stats.mismatches}";
    assert res.tally["mismatches"] == 4, f"got {res.tally}";
    assert "coarse-routing mismatches=4 -> trigger rebuild" in out, f"got {out}";
}

test "duplicate cluster reachability is counted once" {
    cluster = Cluster(cluster_id="C-retry", size=10);

    root +>:Owns:+> cluster;
    root +>:TouchedByMaintenance(op="retry"):+> cluster;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn LireRebalancer();
    }
    out = buf.getvalue();

    assert res.rebalances == 1, f"got {res.rebalances}";
    assert res.splits == 1, f"got {res.splits}";
    assert len(res.visited) == 1, f"got {res.visited}";
    assert "cluster=C-retry size=10 -> SPLIT" in out, f"got {out}";
}

