fixed.jac_tests:
"""Tests for the import-vs-Element issue (#59).

The promise of the fix is that imports live on the Package as a list of
strings and NEVER appear as nodes in the graph that the indexer walks.
Therefore:
  * Indexer traversal yields only PartDefinition/RequirementDefinition nodes.
  * `resolve_element` for a token matching an import path segment resolves
    to a real Element (or None), never to an Import pseudo-node.
  * `package_text` for embedding excludes import paths, even though they
    are recorded on the Package.
"""

import io;
import from contextlib { redirect_stdout }

test "indexer excludes import paths from the search index" {
    root ++> Package(name="Demo");
    demo = [root -->][0];
    # Record imports on the package (the fix). They are NOT nodes.
    demo.imports.append("Utilities::Common");
    demo.imports.append("Utilities::*");

    widget = PartDefinition(
        name="Widget",
        qualified_name="Demo.Widget",
        doc="a reusable widget"
    );
    common_req = RequirementDefinition(
        name="Common",
        qualified_name="Demo.Common",
        doc="real requirement"
    );
    demo +>:Contains:+> widget;
    demo +>:Contains:+> common_req;

    idx = Indexer();
    demo spawn idx;

    # The fix's core promise: imports are not nodes, so they are not indexed.
    assert len(idx.results) == 2, f"expected 2 indexed elements, got {len(idx.results)}";
    kinds = sorted([e.kind for e in idx.results]);
    assert kinds == ["PartDefinition", "RequirementDefinition"], f"kinds={kinds}";

    # The named-collision guarantee — the real Element wins.
    names = sorted([e.name for e in idx.results]);
    assert "Common" in names, f"real Common missing from index: {names}";
    assert "Utilities::Common" not in names, (
        f"import path leaked into index as if it were a node: {names}"
    );
    assert "Utilities::*" not in names, (
        f"wildcard import leaked into index as if it were a node: {names}"
    );
}

test "resolve_element does not surface an Import pseudo-element for colliding tokens" {
    root ++> Package(name="Demo");
    demo = [root -->][0];
    # The exact path from the issue repro.
    demo.imports.append("Utilities::Common");

    real_req = RequirementDefinition(
        name="Common",
        qualified_name="Demo.Common",
        doc="real requirement"
    );
    demo +>:Contains:+> real_req;

    idx = Indexer();
    demo spawn idx;

    # The query "Common" must hit the real RequirementDefinition,
    # NOT a phantom Import element (which doesn't exist as a node anyway).
    hit = resolve_element(idx, "Common");
    assert hit is not None, "resolve_element('Common') returned None — real Element was missed";
    assert hit.kind == "RequirementDefinition", (
        f"wrong kind resolved: {hit.kind} (Import pseudo-element should not exist)"
    );
    assert hit.name == "Common", f"unexpected resolved name: {hit.name}";
    assert hit.qualified_name == "Demo.Common", (
        f"resolved qualified_name should use dot-separator only, got: {hit.qualified_name}"
    );

    # Sanity: the import path string was never a candidate.
    for e in idx.results {
        assert "Utilities::Common" not in e.qualified_name, (
            f"import path polluted qualified_name: {e.qualified_name}"
        );
    }
}

test "resolve_element returns None when no real element has the token" {
    # No Element nodes at all — just a package with imports.
    root ++> Package(name="Empty");
    pkg = [root -->][0];
    pkg.imports.append("Utilities::Common");

    idx = Indexer();
    pkg spawn idx;

    assert len(idx.results) == 0, f"expected empty index, got {len(idx.results)}";

    # "Common" only exists as an import path on the Package. With the fix,
    # resolve_element must NOT fabricate a hit from the import list —
    # it returns None because there is no real Element named "Common".
    hit = resolve_element(idx, "Common");
    assert hit is None, (
        f"resolve_element must return None when only an import matches, got {hit.kind}"
    );
}

test "package_text and element_text keep imports out of the embedding surface" {
    root ++> Package(name="Demo");
    demo = [root -->][0];
    demo.imports.append("Utilities::Common");
    demo.imports.append("Utilities::*");

    widget = PartDefinition(
        name="Widget",
        qualified_name="Demo.Widget",
        doc="..."
    );
    demo +>:Contains:+> widget;

    # package_text is the embedding for the Package — must not leak imports.
    ptxt = package_text(demo);
    assert "Package - Demo" == ptxt, f"unexpected package_text: {ptxt}";
    assert "Utilities::Common" not in ptxt, (
        f"import leaked into Package embedding: {ptxt}"
    );
    assert "Utilities::*" not in ptxt, (
        f"wildcard import leaked into Package embedding: {ptxt}"
    );

    # element_text on the real PartDefinition also stays clean.
    etxt = element_text(widget);
    assert "PartDefinition - Widget" == etxt, f"unexpected element_text: {etxt}";
    assert "Import" not in etxt, f"element_text leaked Import label: {etxt}";

    # And the Indexer-driven walk that prints element_text never prints an
    # Import line, because no Import node was ever created.
    idx = Indexer();
    demo spawn idx;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        for e in idx.results {
            print(element_text(e));
        }
    }
    out = buf.getvalue();
    assert "Import" not in out, f"indexed output mentions Import: {out!r}";
    assert "PartDefinition - Widget" in out, f"missing real element in output: {out!r}";
}

test "indexer does not recurse into Package.imports as if they were children" {
    # The walker has no clause for Package.imports — those are string fields,
    # not nodes. We assert this concretely by giving a Package many imports
    # but no real elements, and confirming the index is empty.
    root ++> Package(name="Isolated");
    pkg = [root -->][0];
    pkg.imports.append("Utilities::Common");
    pkg.imports.append("Utilities::*");
    pkg.imports.append("Other::Helper");

    idx = Indexer();
    pkg spawn idx;

    assert len(idx.results) == 0, (
        f"import strings leaked as indexed elements: {[e.name for e in idx.results]}"
    );

    # Adding real elements under the same package does not disturb imports
    # and imports do not show up in the index either way.
    req = RequirementDefinition(
        name="Helper",
        qualified_name="Isolated.Helper",
        doc="real one"
    );
    pkg +>:Contains:+> req;

    idx2 = Indexer();
    pkg spawn idx2;
    assert len(idx2.results) == 1, f"expected 1 real element, got {len(idx2.results)}";
    assert idx2.results[0].name == "Helper", f"unexpected: {idx2.results[0].name}";
    assert idx2.results[0].qualified_name == "Isolated.Helper", (
        f"qualified_name should be dot-only: {idx2.results[0].qualified_name}"
    );
}

