"""MA2H §13.4 keyless consumer conformance demo.

Models the digest-recompute duty for HTTP consumers of the MA2H protocol.
The Hub-keyed MAC means a keyless consumer CANNOT recompute a verifying
digest; it compensates with structural validation (known/forbidden field
keep-lists, MAC well-formedness) and byte-verbatim forwarding to a
runtime that holds the Hub key. This walker performs that compensating
flow and reports whether the §13.4 MUST is satisfied under the keyless
carve-out.
"""

node Message {
    has payload: str = "";
    has transmitted_digest: str = "";
    has known_fields: list[str] = [];
    has forbidden_fields: list[str] = [];
    has mac: str = "";
}

node KeylessConsumer {
    has consumer_id: str = "";
    has hub_key: str = "";
}

node KeyedRuntime {
    has runtime_id: str = "";
    has hub_key: str = "";
}

node AuditReport {
    has passed: bool = False;
    has notes: list[str] = [];
}

edge Receives { has wire_bytes: str = ""; }
edge Forwards { }
edge Files { }
edge Validates { }

walker Auditor {
    has consumer_id_seen: str = "";

    can start with Root entry {
        visit [-->];
    }

    can audit with Message entry {
        notes: list[str] = [];

        well_formed = is_well_formed_mac(here.mac);
        if not well_formed {
            notes.append("MAC malformed");
        }

        bad_known = [f for f in here.known_fields if f not in {"agent_id", "ts", "nonce"}];
        if len(bad_known) > 0 {
            notes.append("unknown field present");
        }

        if len(here.forbidden_fields) > 0 {
            notes.append("forbidden field present");
        }

        notes.append("no Hub key — cannot recompute digest");

        verdict_pass = well_formed and len(bad_known) == 0 and len(here.forbidden_fields) == 0;
        finding = AuditReport(
            passed=verdict_pass,
            notes=notes,
        );
        here +>:Files:+> finding;
        visit [-->];
    }

    can forward_check with KeylessConsumer entry {
        self.consumer_id_seen = here.consumer_id;
        visit [-->];
    }

    can attest with KeyedRuntime entry {
        verdict_node = here;
        print(
            f"[{self.consumer_id_seen}] forwarding check: "
            f"runtime={verdict_node.runtime_id} has_hub_key="
            f"{'yes' if len(verdict_node.hub_key) > 0 else 'no'}"
        );
        visit [-->];
    }

    can review with AuditReport entry {
        verdict = "CONFORMANT" if here.passed else "NONCONFORMANT";
        print(f"[{verdict}] {self.consumer_id_seen}: {here.notes}");
        visit [-->];
    }
}

def is_well_formed_mac(mac: str) -> bool {
    return len(mac) == 64;
}

with entry {
    msg = Message(
        payload="opaque bytes",
        transmitted_digest="hub-keyed-mac-receipt",
        known_fields=["agent_id", "ts", "nonce"],
        forbidden_fields=[],
        mac="a" * 64,
    );
    consumer = KeylessConsumer(consumer_id="keyless-http-1", hub_key="");
    runtime = KeyedRuntime(runtime_id="verifier-1", hub_key="hub-shared-secret");

    root +>:Receives(wire_bytes="raw"):+> consumer;
    consumer +>:Validates:+> msg;
    root +>:Forwards:+> runtime;

    root spawn Auditor();
}

