"""Per-issue routing pipeline: refresh gate, grounding, complexity routing,
and safe skip behavior for needs_attention.

Models the documentation issue's call order:
  1. live refresh of an issue
  2. read-only grounding against the source issue
  3. complexity-based routing (actionable vs already-resolved)
  4. safe skip semantics when needs_attention fires
"""

# ---------------------------------------------------------------------------
# Entity archetypes
# ---------------------------------------------------------------------------

node Issue {
    has title: str = "";
    has depth: int = 0;
    has status: str = "open";
    has evidence: str = "";
}

node Decision {
    has verdict: str = "";
    has fingerprint: str = "";
    has rationale: str = "";
}

# ---------------------------------------------------------------------------
# Typed edges
# ---------------------------------------------------------------------------

edge ParentOf { }
edge DependsOn { }
edge RoutedTo { }

# ---------------------------------------------------------------------------
# Walker: walks the routing pipeline across the issue graph.
# ---------------------------------------------------------------------------

walker IssueRouter {
    has decision: Decision = Decision();

    can start with Root entry {
        print(f"Router bound at root, decision verdict="
              f"{self.decision.verdict or '<unset>'}");
        visit [-->];
    }

    can refresh with Issue entry {
        print(f"[refresh] {here.title} (depth={here.depth}, "
              f"status={here.status})");
        visit [-->];
    }

    can ground with Issue entry {
        print(f"[ground] {here.title}: lineage and deps checked "
              f"(read-only)");
        visit [-->];
    }

    can route with Issue entry {
        if here.status == "resolved" {
            if here.evidence == "" {
                self.decision = Decision(
                    verdict="non_completion",
                    fingerprint="evidence-missing",
                    rationale="already-resolved requires fresh concrete "
                              "verification evidence"
                );
                print(f"[route] {here.title} -> non_completion "
                      f"(no concrete evidence)");
            } else {
                self.decision = Decision(
                    verdict="resolved",
                    fingerprint=here.evidence,
                    rationale="verified with concrete evidence"
                );
                print(f"[route] {here.title} -> resolved (verified)");
            }
        } elif here.depth <= 3 {
            self.decision = Decision(
                verdict="actionable",
                fingerprint=f"impl-depth-{here.depth}",
                rationale="0-3 implementation threshold"
            );
            print(f"[route] {here.title} -> actionable (depth {here.depth})");
        } else {
            self.decision = Decision(
                verdict="decompose",
                fingerprint=f"decomp-depth-{here.depth}",
                rationale="4-5 decomposition threshold"
            );
            print(f"[route] {here.title} -> decompose (depth {here.depth})");
        }
        visit [-->];
    }

    can finalize with Decision entry {
        print(f"[finalize] decision={here.verdict} "
              f"fingerprint={here.fingerprint}");
        print(f"[finalize] rationale: {here.rationale}");
    }
}

# ---------------------------------------------------------------------------
# Walker: safe-skip for needs_attention.
# ---------------------------------------------------------------------------

walker NeedsAttentionSkipper {
    has recorded_fingerprint: str = "";
    has source_closed: bool = False;
    has delivery_attempted: bool = False;

    can start with Root entry {
        print("[skipper] entering pipeline");
        visit [-->];
    }

    can skip_attention with Issue entry {
        self.recorded_fingerprint = f"fp-{here.title}-{here.status}";
        self.source_closed = False;
        self.delivery_attempted = False;

        print(f"[skip] {here.title}: recorded fingerprint="
              f"{self.recorded_fingerprint}; source stays open; "
              f"no lgtm, no delivery");
        disengage;
    }
}

# ---------------------------------------------------------------------------
# Demo wiring
# ---------------------------------------------------------------------------

with entry {
    root_issue = Issue(
        title="issue-149-routing-documentation",
        depth=3,
        status="open"
    );

    parent_issue = Issue(
        title="issue-149-resolution-proof",
        depth=2,
        status="resolved",
        evidence="verified-by-tests-2024-Q4"
    );

    dep_issue = Issue(
        title="issue-149-safe-delivery",
        depth=2,
        status="resolved",
        evidence="delivery-receipt-2024-Q4"
    );

    child_low = Issue(
        title="issue-149-grounding-gate",
