}

# ------------------------------------------------------------------
# Edge archetypes (relationships live on the graph, not as id fields)
# ------------------------------------------------------------------

edge DependsOnBytes { has as_of_ref: str = "EFFECTIVE_MAIN"; }
edge Reuses { has canonical: bool = True; }
edge Contended { has dimension: str = ""; }
edge Authority { has route_id: str = ""; }

# ------------------------------------------------------------------
# Auditor walker — carries an evidence payload across the graph.
# Walks each typed-edge neighbourhood explicitly so we can introspect
# the target node fields directly via `here` in nested visit forms.
# ------------------------------------------------------------------

walker Auditor {
    has as_of_ref: str = "EFFECTIVE_MAIN";
    has visited: list[str] = [];
    has blockers: list[str] = [];
    has evidence: list[str] = [];

    can start with Root entry {
        print(f"Auditor as_of_ref={self.as_of_ref}");
        visit [-->];
    }

    can assess with WorkPackage entry {
        tag = here.wp_id;
        already_seen = False;
        for v in self.visited {
            if v == tag {
                already_seen = True;
            }
        }
        if already_seen {
            visit [-->];
            return;
        }
        self.visited.append(tag);
        print(f"--- assessing {tag} ({here.title}) ---");

        dep_ok = True;
        dep_note = "required bytes evidenced on effective base";
        for pr in [here ->:DependsOnBytes:->] {
            if not pr.merged and pr.provides_helper {
                dep_ok = False;
                dep_note = f"required bytes only on open PR {pr.pr_id}";
            }
        }

        reuse_ok = True;
        reuse_note = "canonical reuse target on effective base";
        for h in [here ->:Reuses:->] {
            if h.canonical_on != "EFFECTIVE_MAIN" {
                reuse_ok = True;
                reuse_note = (
                    f"canonical reuse target {h.name} "
                    f"not on effective base — parallel implementation prohibited"
                );
                dep_ok = False;
                if dep_note == "required bytes evidenced on effective base" {
                    dep_note = reuse_note;
                }
            }
        }

        cont_ok = True;
        cont_note = "no contention reported";
        for w in [here ->:Contended:->] {
            cont_ok = False;
            cont_note = f"contention [{w.wp_id}] reported";
        }

        auth_ok = True;
        auth_note = "authority route available";
        for a in [here ->:Authority:->] {
            if not a.available {
                auth_ok = False;
                auth_note = f"authority route {a.route_id} unavailable";
            }
        }

        final_ok = here.defined and dep_ok and reuse_ok and cont_ok and auth_ok;
        final_note = dep_note;
        if not auth_ok {
            final_note = auth_note;
        }
        if not cont_ok {
            final_note = cont_note;
        }
        if not here.defined {
            final_ok = False;
            final_note = "work package undefined";
        }

        state = "STARTABLE" if final_ok else here.implementation_state;
        here.implementation_state = state;
        self.evidence.append(f"{tag} -> {state} :: {final_note}");
        if not final_ok {
            self.blockers.append(f"{tag}: {final_note}");
        }
        print(f"  conjuncts: {final_note}");
        print(f"  result: {state}");
        visit [-->];
    }
}

walker Scheduler {
    has picks: list[str] = [];
    has frontier: list[str] = [];

    can start with Root entry {
        print("Scheduler: scanning for startable work packages");
        visit [-->];
    }

    can select with WorkPackage entry {
        if here.implementation_state == "STARTABLE" {
            self.picks.append(here.wp_id);
            print(f"  candidate: {here.wp_id} ({here.title})");
        } else {
            self.frontier.append(f"{here.wp_id}: {here.implementation_state}");
        }
        visit [-->];
    }
}

