"""Xark build invalidation: model artifact cache, source inputs, and a walker that cascades
invalidation across the dependency tree whenever the extraction stamp changes.

The scenario mirrors the RFC: a circuit package is built from a set of extraction inputs
(compiler binary, field, profile, output dir, required artifacts). When any input changes
or a required artifact is missing, all dependents of the circuit must be invalidated.
Identity builds (same stamp, same artifact set) must remain cache hits.
"""

# ---------- Entity archetypes ----------

node Artifact {
    has name: str = "";
    has kind: str = "json";
    has present: bool = True;
}

node SourceInput {
    has name: str = "";
    has value: str = "";
    has fingerprint: str = "";
}

node CircuitPackage {
    has name: str = "";
    has required_artifacts: list[str] = [];
}

# ---------- Edge archetypes (the relationships that carry meaning) ----------

edge DependsOn { has reason: str = ""; }
edge Produces { has stamp: str = ""; }
edge Invalidation { has reason: str = ""; }

# ---------- The walker ----------

walker InvalidationCascade {
    has stamp: str = "";
    has invalidated: list[str] = [];
    has cycle_guard: list[str] = [];
    has depth_limit: int = 8;

    can begin with Root entry {
        print(f"Begin invalidation cascade (stamp={self.stamp})");
        visit [-->] else { disengage; }
    }

    # Walk upstream from a source input to every circuit it touches, then
    # downward through every circuit's dependency edges, accumulating the
    # set of packages that must be rebuilt.
    can collect_circuits with SourceInput entry {
        if self.depth_limit <= 0 {
            print("  depth limit hit -- disengaging");
            disengage;
        }
        if here.name in self.cycle_guard {
            print(f"  cycle guard hit on {here.name} -- disengaging");
            disengage;
        }
        self.cycle_guard.append(here.name);
        self.depth_limit -= 1;

        print(f"  source input '{here.name}' changed (fp={here.fingerprint})");
        visit [->:Produces:->] else {
            print("  no circuits produce from this input");
            disengage;
        }
    }

    # For every circuit reachable from a source input, gather the artifacts
    # it produces and check the required-artifact set, then descend into
    # its dependents.
    can inspect_circuit with CircuitPackage entry {
        if here.name in self.cycle_guard {
            print(f"  cycle guard hit on circuit {here.name} -- disengaging");
            disengage;
        }
        self.cycle_guard.append(here.name);

        missing = self.check_required_artifacts(here);
        if missing {
            label = f"missing required artifact(s): {', '.join(missing)}";
        } else {
            label = "stamp change";
        }
        self.invalidated.append(here.name);
        print(f"  circuit '{here.name}' INVALIDATED ({label})");

        visit [->:DependsOn:->] else {
            print(f"  no dependents under {here.name}");
            disengage;
        }
    }

    # For each required artifact, find the matching Artifact node by name
    # and confirm it is present. Returns the list of missing names.
    def check_required_artifacts(circuit: CircuitPackage) -> list[str] {
        missing: list[str] = [];
        for req_name in circuit.required_artifacts {
            found = False;
            for art in [->:Produces:->Artifact:->] {
                if art.name == req_name {
                    if not art.present {
                        missing.append(req_name);
                    }
                    found = True;
                }
            }
            if not found {
                missing.append(req_name);
            }
        }
        return missing;
    }

    can note_artifact with Artifact entry {
        print(f"  artifact '{here.name}' ({here.kind}) present={here.present}");
        visit [-->] else { disengage; }
    }
}

