"""GatiGo roadmap loop-gate traversal.

Models the GatiGo web loop engineering roadmap (#12) as a graph of
issues connected by ``Blocks`` edges (a later gate cannot unlock until
the earlier behavior gate resolves) and ``BelongsTo`` edges (an issue
sits inside one of three execution loops). A walker marches through
the dependency DAG, skipping ``#15`` until it resolves, and reports
which loop is currently the "next unblocked" milestone for the
coordinator to pick up.
"""

# ---------- node archetypes ----------

node Issue {
    has title: str = "";
    has number: int = 0;
    has resolved: bool = False;
    has is_gate: bool = False;
    has loop_index: int = -1;
}

node Loop {
    has loop_name: str = "";
    has loop_index: int = 0;
}

# ---------- typed edges ----------

edge Blocks {
    # An issue blocks another until it resolves.
    has reason: str = "";
}

edge BelongsTo {
    # An issue belongs to a loop.
}

# ---------- walker ----------

walker RoadmapAuditor {
    has next_issue: str = "";
    has next_loop: int = -1;
    has next_loop_name: str = "";

    can start with Root entry {
        # Step into every loop group.
        visit [-->];
    }

    can scan_loops with Loop entry {
        # Record the current loop we're traversing, then walk into its issues.
        self.next_loop_name = here.loop_name;
        self.next_loop = here.loop_index;
        visit [->:BelongsTo:->];
    }

    can audit with Issue entry {
        # #15 is a blocking investigation, not a feature gate — skip it
        # explicitly until it resolves (mirrors the rule "do not collect
        # or interpret Gate 0 behavior until #15 resolves").
        if here.number == 15 {
            if not here.resolved {
                print(f"[skip] #{here.number} {here.title} — travel-time "
                      f"investigation still open");
            } else {
                print(f"[ok]   #{here.number} {here.title} — resolved, "
                      f"collecting Gate 0 behavior now");
            }
            return;
        }

        # Only behavior gates can unlock the next loop, and only if
        # the gate itself is resolved.
        if here.is_gate {
            label = "READY" if here.resolved else "BLOCKED";
            print(f"[{label}] gate #{here.number} {here.title} "
                  f"(loop {here.loop_index})");
            if not here.resolved {
                self.next_issue = f"#{here.number} {here.title}";
                self.next_loop = here.loop_index;
                self.next_loop_name = f"Loop {here.loop_index}";
            }
            return;
        }

        # Plain implementation tasks: report and keep walking.
        status = "done" if here.resolved else "todo";
        print(f"[{status}] #{here.number} {here.title}");
    }
}

# ---------- demo wiring ----------

with entry {
    # Loops in execution order.
    loop0 = Loop(loop_name="Loop 0 — activation", loop_index=0);
    loop1 = Loop(loop_name="Loop 1 — collaboration", loop_index=1);
    loop2 = Loop(loop_name="Loop 2 — decision", loop_index=2);

    # Issues per loop, with resolved status reflecting the issue body.
    # Each issue carries its own loop_index so the auditor can report it
    # without relying on a back-walk through a typed edge.
    i7   = Issue(title="Green CI and coordinator environment",
