    i8   = Issue(title="Candidate selection and share-intent fake door",
                 number=8,  resolved=True,  loop_index=0);
    i15  = Issue(title="Travel-time accuracy investigation",
                 number=15, resolved=False, loop_index=0);
    i9   = Issue(title="Gate 0: recommendation activation",
                 number=9,  is_gate=True,  resolved=False, loop_index=0);
    i2   = Issue(title="Persistent room and share link",
                 number=2,  resolved=False, loop_index=1);
    i3   = Issue(title="Guest departure-station response",
                 number=3,  resolved=False, loop_index=1);
    i10  = Issue(title="Gate 1: room sharing and guest response",
                 number=10, is_gate=True,  resolved=False, loop_index=1);
    i4   = Issue(title="Confirm place and map handoff",
                 number=4,  resolved=False, loop_index=2);
    i11  = Issue(title="Gate 2: confirmation and navigation handoff",
                 number=11, is_gate=True,  resolved=False, loop_index=2);

    # BelongsTo: every issue sits inside exactly one loop.
    loop0 +>:BelongsTo:+> i7;
    loop0 +>:BelongsTo:+> i8;
    loop0 +>:BelongsTo:+> i15;
    loop0 +>:BelongsTo:+> i9;
