"""Cost-arc layered DAG walk: cost-MDD shortest-path pruning via node potentials.

Models the scenario from issue #653 — a cost-MDD is a layered DAG whose edges
each carry a cost, and the question is whether any path from the start layer
to the end layer is short enough to still beat the current bound. A node
potential (the length of the shortest remaining path) certifies that pruning
is safe: a layer's potential is the min-cost-to-end from there, and an
upper-layer node is pruned when its accumulated cost exceeds the bound minus
the potential from the layer below it.
"""

# ----- Entities -----

node Layer {
    has index: int = 0;
    has label: str = "";
}

node Node {
    has layer_index: int = 0;
    has state_id: int = 0;
    has label: str = "";
    # Shortest distance from THIS node to the accepting layer.
    # Mirrors `ln[q]` in the cost-MDD recurrence — a potential function
    # that certificates the shortest-path pruning step.
    has potential: float = 0.0;
}

edge CostArc {
    has weight: int = 0;
    has transition: str = "";
}

# ----- Walkers -----

# Annotator computes the potential of every node by walking the DAG
# BACKWARD from the accepting layer, so each node's potential is the
# min over successors of (edge weight + successor.potential).
walker PotentialAnnotator {
    can start with Root entry {
        visit [-->];
    }
    can descend with Layer entry {
        visit [<--];
    }
    can annotate with Node entry {
        succs = [here->:CostArc:->];
        if succs {
            best = succs[0].potential + succs[0].weight;
            for s in succs {
                cand = s.potential + s.weight;
                best = cand if cand < best else best;
            }
            here.potential = best;
        } else {
            # Accepting / sink node: zero potential (zero edges to end).
            here.potential = 0.0;
        }
    }
}

# Pruner walks FORWARD from the start layer, accumulating the best known
# path cost so far. A node is pruned when its accumulated cost already
# exceeds (bound - potential-of-best-successor) — i.e. there is no way
# for any path through it to beat the bound, as certified by the
# precomputed potential.
walker CostBoundedPruner {
    has bound: float = 0.0;
    has pruned_count: int = 0;
    has kept_count: int = 0;

    can start with Root entry {
        visit [-->];
    }
    can descend with Layer entry {
        visit [-->];
    }
    can check with Node entry {
        succs = [here->:CostArc:->];
        if not succs {
            self.kept_count += 1;
            visit [-->] else { disengage; };
        }
        # Find the minimum successor potential (cheapest path to end).
        best_pot = succs[0].potential + succs[0].weight;
        for s in succs {
            cand = s.potential + s.weight;
            best_pot = cand if cand < best_pot else best_pot;
        }
        # If the cheapest path through this node cannot beat the bound,
        # the node is provably pruned — no certificate can rescue it.
        verdict = "PRUNED" if best_pot > self.bound else "KEPT";
        if best_pot > self.bound {
            self.pruned_count += 1;
        } else {
            self.kept_count += 1;
        }
        print(f"[{verdict}] {here.label}  best_tail={best_pot}  bound={self.bound}");
        if best_pot <= self.bound {
            visit [-->] else { disengage; };
        } else {
            disengage;
        }
    }
}

# ----- Demonstration -----

with entry {
