    n10 = Node(layer_index=1, state_id=0, label="q1");
    n11 = Node(layer_index=1, state_id=1, label="q1'");
    n20 = Node(layer_index=2, state_id=0, label="acc");
    n21 = Node(layer_index=2, state_id=1, label="acc'");

    root ++> l0 ++> l1 ++> l2;
    l0 ++> n00 ++> n01;
    l1 ++> n10 ++> n11;
    l2 ++> n20 ++> n21;

    # Cost-arc edges between successive layers.
    n00 +>:CostArc(weight=2, transition="x1=0"):+> n10;
    n00 +>:CostArc(weight=5, transition="x1=1"):+> n11;
    n01 +>:CostArc(weight=3, transition="x1=0"):+> n10;
    n01 +>:CostArc(weight=1, transition="x1=1"):+> n11;

    n10 +>:CostArc(weight=4, transition="x2=0"):+> n20;
    n10 +>:CostArc(weight=2, transition="x2=1"):+> n21;
    n11 +>:CostArc(weight=6, transition="x2=0"):+> n20;
    n11 +>:CostArc(weight=1, transition="x2=1"):+> n21;

    n20 +>:CostArc(weight=0, transition="eps"):+> n21;

    # Step 1: compute potentials by walking the DAG backward.
    # (Directionality note: PotentialAnnotator descends via <-- and we
    # spawn it on l2 so it reaches every node, including sinks.)
    print("=== Computing potentials (backward sweep) ===");
