import io;
import from contextlib { redirect_stdout }

test "prunes states above the cost cap and keeps boundary states" {
    layer = Layer(layer_index=0, label="only");
    kept_state = State(state_id="kept", layer_index=0, potential=5);
    pruned_state = State(state_id="pruned", layer_index=0, potential=6);

    root ++> layer;
    layer +>:Transition(weight=2):+> kept_state;
    layer +>:Transition(weight=3):+> pruned_state;

    output_buf = io.StringIO();
    with redirect_stdout(output_buf) {
        res = root spawn ShortestPathPruner(cost_cap=5);
    }
    output = output_buf.getvalue();

    assert len(res.pruned) == 1, f"got {res.pruned}";
    assert "pruned" in res.pruned, f"got {res.pruned}";
    assert "kept" not in res.pruned, f"got {res.pruned}";
    assert "prune pruned" in output, f"missing prune output: {output}";
    assert "keep  kept" in output, f"missing keep output: {output}";
}

test "traverses layered DAG edges in the forward direction" {
    layer0 = Layer(layer_index=0, label="start");
    layer1 = Layer(layer_index=1, label="middle");
    layer2 = Layer(layer_index=2, label="finish");
    state0 = State(state_id="s0", layer_index=0, potential=1);
    state1 = State(state_id="s1", layer_index=1, potential=2);
    state2 = State(state_id="s2", layer_index=2, potential=3);

    root ++> layer0 ++> layer1 ++> layer2;
    layer0 +>:Transition(weight=1):+> state0;
    layer1 +>:Transition(weight=2):+> state1;
    layer2 +>:Transition(weight=3):+> state2;
    state0 +>:LayerLink:+> state1;
    state1 +>:LayerLink:+> state2;

    assert len([root-->]) == 1, f"got {len([root-->])} root children";
    assert layer1 in [layer0-->], f"missing layer1 from layer0";
    assert state0 in [layer0 ->:Transition:->], f"missing state0 transition";
    assert state1 in [state0 ->:LayerLink:->], f"missing state1 layer link";
    assert state2 in [state1 ->:LayerLink:->], f"missing state2 layer link";

    res = root spawn ShortestPathPruner(cost_cap=10);

    assert len(res.pruned) == 0, f"got {res.pruned}";
}

test "default zero cap keeps zero potential and prunes positive potential" {
    low_layer = Layer(layer_index=0, label="low");
    high_layer = Layer(layer_index=1, label="high");
    zero_state = State(state_id="zero", potential=0);
    positive_state = State(state_id="positive", potential=1);

    root ++> low_layer;
    root ++> high_layer;
    low_layer +>:Transition:+> zero_state;
    high_layer +>:Transition(weight=1):+> positive_state;

    res = root spawn ShortestPathPruner();

    assert len([root-->]) == 2, f"got {len([root-->])} root children";
    assert len(res.pruned) == 1, f"got {res.pruned}";
    assert "positive" in res.pruned, f"got {res.pruned}";
    assert "zero" not in res.pruned, f"got {res.pruned}";
}

