test "mid-loop crash journals before apply and stops safely" {
    job = RewindJob(label="rewind-crash");
    f1 = File(title="alpha.cfg", content="original-alpha");
    f2 = File(title="beta.cfg", content="original-beta");
    f3 = File(title="gamma.cfg", content="original-gamma");
    snap1 = OriginalSnapshot(title="alpha.cfg", bytes="original-alpha");
    snap2 = OriginalSnapshot(title="beta.cfg", bytes="original-beta");
    snap3 = OriginalSnapshot(title="gamma.cfg", bytes="original-gamma");
    pen1 = PendingRestore(title="alpha.cfg", bytes="restored-alpha");
    pen2 = PendingRestore(title="beta.cfg", bytes="restored-beta");
    pen3 = PendingRestore(title="gamma.cfg", bytes="restored-gamma");

    root +>:Targets:+> job;
    job +>:Targets:+> f1;
    job +>:Targets:+> f2;
    job +>:Targets:+> f3;
    f1 +>:Previous:+> snap1;
    f2 +>:Previous:+> snap2;
    f3 +>:Previous:+> snap3;
    f1 +>:Pending:+> pen1;
    f2 +>:Pending:+> pen2;
    f3 +>:Pending:+> pen3;
    f1 +>:NextFile:+> f2;
    f2 +>:NextFile:+> f3;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn RewindWalker(walker_label="attempt-1", crash_after=1);
    }
    out = buf.getvalue();

    assert "CRASH simulated after journal, before apply" in out, f"missing crash marker: {out}";
    assert res.visited_count == 1, f"expected one completed file before crash, got {res.visited_count}";
    assert snap1.captured, f"alpha snapshot must be journaled: {snap1.captured}";
    assert pen1.applied, f"alpha pending should be applied before crash index: {pen1.applied}";
    assert f1.content == "restored-alpha", f"alpha content wrong after partial run: {f1.content}";
    assert snap2.captured, f"beta snapshot must be journaled before crash: {snap2.captured}";
    assert not pen2.applied, f"beta pending must not apply after crash disengage: {pen2.applied}";
    assert f2.content == "original-beta", f"beta content must stay original after crash: {f2.content}";
    assert not snap3.captured, f"gamma snapshot must not be reached: {snap3.captured}";
    assert not pen3.applied, f"gamma pending must not run: {pen3.applied}";
    assert f3.content == "original-gamma", f"gamma content must stay original: {f3.content}";
}

test "retry after crash completes all restores idempotently" {
    job = RewindJob(label="rewind-retry");
    f1 = File(title="alpha.cfg", content="original-alpha");
    f2 = File(title="beta.cfg", content="original-beta");
    f3 = File(title="gamma.cfg", content="original-gamma");
    snap1 = OriginalSnapshot(title="alpha.cfg", bytes="original-alpha");
