"""Tests for CI Workflow pipeline graph walker."""

import io;
import from contextlib { redirect_stdout }

test "topological order follows depends-on edges" {
    checkout = Stage(name="checkout", blocking=False);
    install = Stage(name="install", blocking=False);
    lint = Stage(name="lint", blocking=True);
    test_stage = Stage(name="test", blocking=True);
    build = Stage(name="build", blocking=True);
    checkout +>:DependsOn(since_pr=1):+> install;
    install +>:DependsOn(since_pr=1):+> lint;
    install +>:DependsOn(since_pr=1):+> test_stage;
    test_stage +>:DependsOn(since_pr=1):+> build;

    ci = Pipeline(name="ci");
    root ++> ci ++> checkout;

    runner = PipelineRunner(pr_number=42);
    ci spawn runner;

    assert "checkout" in runner.order, f"checkout missing from order: {runner.order}";
    assert "install" in runner.order, f"install missing: {runner.order}";
    assert runner.order.index("install") < runner.order.index("lint"), f"install must precede lint: {runner.order}";
    assert runner.order.index("install") < runner.order.index("test"), f"install must precede test: {runner.order}";
    assert runner.order.index("test") < runner.order.index("build"), f"test must precede build: {runner.order}";
    assert runner.cycle == False, f"unexpected cycle on linear chain: {runner.order}";
}

test "blocking stage flags PR as blocked" {
    nonblock = Stage(name="prep", blocking=False);
    block = Stage(name="verify", blocking=True);
    nonblock +>:DependsOn(since_pr=1):+> block;

    ci = Pipeline(name="ci");
    root ++> ci ++> nonblock;

    runner = PipelineRunner(pr_number=7);
    ci spawn runner;

    assert runner.blocked == True, f"blocking stage must set blocked: order={runner.order}";
    assert "verify" in runner.order, f"verify missing: {runner.order}";
}

test "non-blocking pipeline leaves PR open" {
    a = Stage(name="alpha", blocking=False);
    b = Stage(name="beta", blocking=False);
    a +>:DependsOn(since_pr=1):+> b;

    ci = Pipeline(name="ci");
    root ++> ci ++> a;

    runner = PipelineRunner(pr_number=3);
    ci spawn runner;

    assert runner.blocked == False, f"all-non-blocking must leave PR open: order={runner.order}";
    assert runner.cycle == False, f"no cycle on linear chain: {runner.order}";
}

test "cycle between two stages is detected" {
    a = Stage(name="a", blocking=False);
    b = Stage(name="b", blocking=False);
    a +>:DependsOn(since_pr=1):+> b;
    b +>:DependsOn(since_pr=1):+> a;

    ci = Pipeline(name="ci");
    root ++> ci ++> a;

    runner = PipelineRunner(pr_number=1);
    ci spawn runner;

    assert runner.cycle == True, f"cycle must be detected: order={runner.order}";
}

test "reporter prints pipeline summary" {
    checkout = Stage(name="checkout", blocking=False);
    install = Stage(name="install", blocking=False);
    lint = Stage(name="lint", blocking=True);
    checkout +>:DependsOn(since_pr=1):+> install;
    install +>:DependsOn(since_pr=1):+> lint;

    ci = Pipeline(name="release");
    root ++> ci ++> checkout;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Reporter();
    }
    out = buf.getvalue();

    assert "release" in out, f"pipeline name missing: {out}";
    assert "order" in out, f"order line missing: {out}";
    assert "cycle" in out, f"cycle line missing: {out}";
    assert "blocked" in out, f"blocked line missing: {out}";
}

