"""Lua backend module graph: model .lua source files and their require
dependencies, then walk the dependency closure with a walker that mirrors
the hand-rolled traversal described in issue #21 of repo-view.

The original code maintains module identity through a string-keyed dict
and recurses through a list of dependency names. Here the relationships
become typed edges and the traversal is a walker over them. Cycle policy
is preserved explicitly (jac 0.36.1 walkers do not dedupe on cyclic
graphs), as is a depth cap and a max-children cap that bound recovery
when generated or malformed sources produce runaway includes.
"""

# ---- Node archetypes --------------------------------------------------------

node LuaModule {
    has name: str = "";
    has kind: str = "script";   # "script" | "module" | "rockspec"
    has defines: list[str] = [];   # local fns / table fields discovered
    has exports: list[str] = [];   # returned table keys (module pattern)
    has doc_blocks: int = 0;       # --- style doc blocks preserved
}

# Common node superclass so a single walker ability can report on either
# an ordinary LuaModule or a generated/aggregate LuaFile.
node LuaSource {
    has path: str = "";
    has long_string_count: int = 0;  # [[ ]] / [=[ ]=] long strings seen
    has malformed: bool = False;     # recovery flag from bad chunks

    def label() -> str;
}

node LuaModule {
    override def label() -> str {
        return f"module:{self.name}";
    }
}

node LuaFile {
    has bytes: int = 0;

    override def label() -> str {
        return f"file:{self.path}";
    }
}

# ---- Edge archetypes --------------------------------------------------------

edge Requires {
    has dep_name: str = "";
    has literal: bool = True;   # false if dep name was runtime-computed
}

edge PartOf {
    has role: str = "discovered";  # "discovered" | "explicit" | "generated"
}

# ---- Walker: dependency closure --------------------------------------------

walker DepAudit {
    has max_depth: int = 32;
    has max_kids: int = 64;
    has seen: list[str] = [];
    has order: list[str] = [];
    has cycles: list[str] = [];
    has unresolved: list[str] = [];

    can start with Root entry {
        # Seed by walking typed Requires edges out of the root.
        visit [->:Requires:->];
    }

    can audit with LuaModule entry {
        if not self._mark_seen(here.name) {
            return;
        }
        if self._too_deep() {
            return;
        }
        self.order.append(here.name);
        self._report_module(here);
        kids = [-->](?:LuaModule);
        kids_count = len(kids);
        if kids_count > self.max_kids {
            self.cycles.append(
                f"{here.name}:fanout>{self.max_kids}"
            );
            return;
        }
        visit [->:Requires:->];
    }

    can file_pass with LuaFile entry {
        # Files (as opposed to modules) still count as sources but are
        # not recursed into -- the original backend never traversed raw
        # file content for requires.
        if here.malformed {
            self.cycles.append(f"file:{here.path}:malformed");
        }
        visit [-->];
    }
}

# Walker-side helpers (defs, not abilities, so they don't fire on nodes).
walker DepAudit {
    def _mark_seen(name: str) -> bool {
        for n in self.seen {
            if n == name {
                # Cycle: record once and refuse to recurse.
                self.cycles.append(f"{name}");
                return False;
            }
        }
        self.seen.append(name);
        return True;
    }

    def _too_deep() -> bool {
        return len(self.seen) > self.max_depth;
    }

    def _report_module(m: LuaModule) -> None {
        if m.malformed {
            print(f"[WARN] malformed module: {m.name}");
        }
        status = "OK" if m.doc_blocks > 0 else "UNDOC";
        print(f"[{status}] {m.name} kind={m.kind} "
              f"defs={len(m.defines)} exports={len(m.exports)} "
              f"docs={m.doc_blocks} longstr={m.long_string_count}");
        for d in m.defines {
            print(f"   def: {d}");
        }
        for e in m.exports {
            print(f"   exp: {e}");
        }
    }
}

# ---- Walker: cascade invalidation of a removed module -----------------------

walker Invalidate {
    has removed: str = "";
    has purged: list[str] = [];

    can start with Root entry {
        visit [->:Requires:->];
    }

    can drop with LuaModule entry {
        if here.name == self.removed {
            self.purged.append(here.name);
            here.del -->;   # disconnect from the graph; node purged
            disengage;
        }
        visit [->:Requires:->];
    }
