                       long_string_count=4);
    util   = LuaModule(name="util",   kind="module",
                       defines=["map", "reduce", "filter"],
                       exports=["map", "filter"],
                       doc_blocks=0,
                       malformed=False);
    bad    = LuaModule(name="bad",    kind="module",
                       defines=[],
                       exports=[],
                       doc_blocks=0,
                       malformed=True,
                       long_string_count=0);

