    print(f"cycles  : {auditor.cycles}");
    print(f"unres   : {auditor.unresolved}");

    # ---- Cascade-invalidate a removed module ----------------------------
    print("--- invalidate 'config' ---");
    invalidator = Invalidate(removed="config");
    root spawn invalidator;
    print(f"purged  : {invalidator.purged}");
