import from contextlib { redirect_stdout }

# --- 1. Linear recursion: a function that calls itself with n-1 -------------

test "linear recursion n-1 is classified as O(N)" {
    root ++> Function(name="factorial", arg_expr="n-1");
    f = [root-->][?:Function][0];
    # Self-edge with the linear step reduction arg.
    f +>:Calls(arg_expr="n-1"):+> f;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        w = root spawn CallGraphAnalyzer();
    }
    out = buf.getvalue();

    assert w.verdict == "O(N)", f"expected O(N), got {w.verdict}";
    assert out is not None, "stdout was not captured";
    assert "cycle closed at factorial" in out, f"missing cycle marker in: {out}";
    assert "stack depth: O(N)" in out, f"missing stack depth line in: {out}";
}

# --- 2. Logarithmic recursion: a function that calls itself with n//2 -------

test "logarithmic recursion n//2 is classified as O(log N)" {
    root ++> Function(name="binsearch", arg_expr="n//2");
    b = [root-->][?:Function][0];
    b +>:Calls(arg_expr="n//2"):+> b;

    buf = io.StringIO();
    with redirect_stdout(buf) {
