"""Schema-typed set diffing over nested blocks (idiomatic Jac demo).

Models the gap from issue #285: a Terraform resource schema that carries
nested blocks with `nesting_mode: "set"`. Top-level set attrs were already
collapsed by hash in #280/#284, but set-nested blocks still produce
positional findings. This demo builds a small `PlanSchemaTypes` tree,
walks it with a walker that diffs each set surface by hash (the desired
behavior), and contrasts that with the old positional walk that over-
reports on insertion.
"""

# ---- Edge archetypes (relationships carry meaning, so they are typed) ----

edge Owns { }            # a resource owns a block instance
edge ContainsSet { }     # a block instance contains a set of members

# ---- Node archetypes ----

# A schema attribute (top-level OR nested) with its declared type kind.
node SchemaAttribute {
    has name: str = "";
    has kind: str = "";      # "set" | "list" | "map" | "scalar"
    has collapsed: bool = False;  # true for set attrs (hash-keyed)
}

# A set-valued attribute whose members are addressable as a multiset.
node SetAttribute {
    has name: str = "";
    has members: list[str] = [];      # hash-keyed members (the desired view)
    has prior: list[str] = [];       # baseline for the diff
}

# A block instance (one row of a set-nested block). Holds child attributes.
node BlockInstance {
    has addr: str = "";              # human address, e.g. "dest_ip_groups[0]"
    has prior_addr: str = "";        # baseline index for positional diff
    has child_attrs: list[str] = []; # names of child set attrs it carries
}

# A resource is the root schema; it owns block instances and top-level attrs.
node Resource {
    has type_name: str = "";
}

# ---- Walker: schema-tree diff (the desired behavior) ----

# Walks the schema tree and reports each set surface's multiset delta.
walker SchemaSetDiff {
    has findings: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    # At a resource: descend into owned block instances and top-level set attrs.
    can at_resource with Resource entry {
        for attr_name in here.child_attrs {
            # Top-level set attrs are already collapsed (hash-keyed).
            self.findings.append(
                f"[top-set] {here.type_name}.{attr_name}: "
                f"multiset-delta members"
            );
        }
        visit [->:Owns:->];
    }

    # At a block instance: address it, then walk its set attrs.
    can at_block with BlockInstance entry {
        for attr_name in here.child_attrs {
            self.findings.append(
                f"[nested-set] {here.addr}.{attr_name}: "
                f"multiset-delta members"
            );
        }
        visit [->:ContainsSet:->];
    }

    # At a set attribute: compute the multiset delta (the desired diff).
    can at_set with SetAttribute entry {
        prior = here.prior;
        curr = here.members;
        added = [m for m in curr if m not in prior];
        removed = [m for m in prior if m not in curr];
        self.findings.append(
            f"  set[{here.name}] added={added} removed={removed}"
        );
    }
}

# ---- Walker: positional diff (the OLD, broken behavior) ----

# Walks the SAME graph but compares set members positionally — this is the
# defect the issue describes: one insertion produces N findings that each
# assert a change that did not happen.
walker PositionalSetDiff {
    has findings: list[str = []];

    can start with Root entry {
        visit [-->];
    }

    can at_resource with Resource entry {
        visit [->:Owns:->];
    }

    can at_block with BlockInstance entry {
        # Walk the contained set attrs (one per nested set surface).
        visit [->:ContainsSet:->];
    }

    can at_set with SetAttribute entry {
        prior = here.prior;
        curr = here.members;
        max_len = len(prior) if len(prior) > len(curr) else len(curr);
        for i in range(max_len) {
            old_val = prior[i] if i < len(prior) else "<absent>";
            new_val = curr[i] if i < len(curr) else "<absent>";
            if old_val != new_val {
                self.findings.append(
                    f"  positional[{here.name}@{i}] {old_val!r} -> {new_val!r}"
                );
            }
        }
    }
}

# ---- Walker: ordering audit (sanity-check that addresses are stable) ----

# Confirms block instances carry stable addresses (required for reviewers
# to act on collapsed findings — the issue calls this out explicitly).
walker AddressAudit {
    has unaddressed: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can at_resource with Resource entry {
        visit [->:Owns:->];
    }

    can at_block with BlockInstance entry {
        if here.addr == "" {
            self.unaddressed.append("<unaddressed block instance>");
        }
        visit [->:ContainsSet:->];
    }
}

# ---- Demo graph ----

with entry {
    # One resource of the kind that issue #285 calls out.
    r = Resource(type_name="example.dest_ip_groups");

    # Three block instances of a set-nested block (set-nested, so order is
    # NOT semantically meaningful; positions are still reported today).
    b0 = BlockInstance(
        addr="dest_ip_groups[0]",
        prior_addr="dest_ip_groups[0]",
        child_attrs=["cidrs"],
    );
    b1 = BlockInstance(
        addr="dest_ip_groups[1]",
        prior_addr="dest_ip_groups[1]",
        child_attrs=["cidrs"],
    );
    b2 = BlockInstance(
        addr="dest_ip_groups[2]",
        prior_addr="dest_ip_groups[2]",
        child_attrs=["cidrs"],
    );

    r +>:Owns:+> b0;
    r +>:Owns:+> b1;
    r +>:Owns:+> b2;

    # Each block carries a set-typed `cidrs` attribute. baseline vs. plan:
    # inserting "10.0.0.5" at index 1 of block 0 should NOT report changes
    # for blocks 1 and 2 in the desired (hash-collapsed) view.
    s0 = SetAttribute(
        name="cidrs",
        prior=["10.0.0.1", "10.0.0.2", "10.0.0.3"],
        members=["10.0.0.1", "10.0.0.5", "10.0.0.3"],
    );
    s1 = SetAttribute(
        name="cidrs",
        prior=["10.0.0.10", "10.0.0.11"],
        members=["10.0.0.10", "10.0.0.11"],
    );
    s2 = SetAttribute(
        name="cidrs",
        prior=["10.0.0.20"],
        members=["10.0.0.20"],
    );
    b0 +>:ContainsSet:+> s0;
    b1 +>:ContainsSet:+> s1;
    b2 +>:ContainsSet:+> s2;

    root ++> r;

    print("=== desired: hash-collapsed multiset diff over nested blocks ===");
