"""Producer-owned chart lineage repository (idiomatic Jac demo).

Models the DXRating read-only repository over the dxdata assembly pipeline:
publications own stable songs/charts, charts carry derivation steps and
field-resolution decisions, and source artifacts are referenced by opaque
evidence locators. A read-only walker traverses the publication lineage,
collecting every artifact and resolution decision into a typed report.
The walker carries an explicit cycle guard because jac 0.36.1 walkers
have no native once-per-node visitation, and it stops cleanly when the
lineage ends (dead-end ``visit ... else { disengage; }``).
"""

# ---------- Edge archetypes (relationship shape carries meaning) ----------

edge Publishes {
    has receipt: str = "";
    has fingerprint: str = "";
}

edge Derives {
    has step_index: int = 0;
}

edge Resolves {
    has candidate_index: int = 0;
    has winner: bool = False;
}

edge Stores {
    has object_key: str = "";
    has availability: str = "available";
}

# ---------- Node archetypes ----------

node Publication {
    has title: str = "";
    has year: int = 0;
    has registry_version: str = "";
    has registry_digest: str = "";
    has received: str = "";
}

node Chart {
    has title: str = "";
    has stable_id: str = "";
    has resolution_status: str = "unknown";
}

node DerivationStep {
    has ordinal: int = 0;
    has rule: str = "";
}

node Artifact {
    has object_key: str = "";
    has availability: str = "available";
    has locator: str = "";
}

# ---------- Walker: read-only lineage traversal ----------

walker LineageReader {
    has summary: list[str] = [];
    has seen: list[str] = [];
    has depth_cap: int = 16;
    has depth: int = 0;

    can begin with Root entry {
        visit [-->];
    }

    can read_pub with Publication entry {
        fid = here.registry_digest;
        already = False;
        for tag in self.seen {
            if tag == fid {
                already = True;
            }
        }
        if already {
            self.summary.append(
                f"[cycle-guard] skip repeat publication {here.title}"
            );
            disengage;
        }
        self.seen.append(fid);
        self.summary.append(
            f"publication={here.title} year={here.year} "
            f"registry={here.registry_version} digest={here.registry_digest}"
        );
        visit [-->];
    }

    can read_chart with Chart entry {
        self.summary.append(
            f"  chart={here.title} stable={here.stable_id} "
            f"resolution={here.resolution_status}"
        );
        visit [->:Derives:->];
    }

    can read_step with DerivationStep entry {
        self.summary.append(
            f"    step#{here.ordinal} rule={here.rule}"
        );
        visit [->:Resolves:->];
    }

    can read_artifact with Artifact entry {
        self.summary.append(
            f"    artifact key={here.object_key} "
            f"availability={here.availability}"
        );
        visit [->:Stores:->] else { disengage; }
    }
}

# ---------- Demonstration graph ----------

with entry {
    # Two publications share a stable chart; one is a revision of the other.
    pub_v1 = Publication(
        title="dxrating-2024-01",
        year=2024,
        registry_version="v3",
        registry_digest="sha256:aaa",
        received="2024-01-15"
    );
    pub_v2 = Publication(
        title="dxrating-2024-06",
        year=2024,
        registry_version="v3",
        registry_digest="sha256:bbb",
        received="2024-06-20"
    );

    chart = Chart(
        title="FIVNIGHT",
        stable_id="song-fiv-night",
        resolution_status="resolved"
    );

    step1 = DerivationStep(ordinal=1, rule="pick_highest_nominal");
    step2 = DerivationStep(ordinal=2, rule="apply_badge_bonus");

    artifact_ok = Artifact(
        object_key="s3://dxdata-internal/abc",
        availability="available",
        locator="evidence://chart/123"
    );
    artifact_gone = Artifact(
        object_key="s3://dxdata-internal/xyz",
        availability="expired",
        locator="evidence://chart/456"
    );

    # Wire the lineage graph using typed edges.
    root ++> pub_v1;
    root ++> pub_v2;
    pub_v1 +>:Publishes(receipt="rcpt-001", fingerprint="sha256:aaa"):+> chart;
    pub_v2 +>:Publishes(receipt="rcpt-002", fingerprint="sha256:bbb"):+> chart;
    chart +>:Derives(step_index=1):+> step1;
    chart +>:Derives(step_index=2):+> step2;
    step1 +>:Resolves(candidate_index=0, winner=True):+> artifact_ok;
    step2 +>:Resolves(candidate_index=1, winner=False):+> artifact_gone;

    # Run the read-only lineage walker over publication v2.
    reader = LineageReader();
    pub_v2 spawn reader;

    for line in reader.summary {
        print(line);
    }
}

