"""Recursive struct cycle detection: E3061 scenario modeled as a graph.

Models the typechecker scenario from grayscale-lang/grayscale issue #2529:
structs that reference themselves (directly or mutually) by value through
a type alias leak past the E3061 check. The fix breaks the cycle with a
pointer field. Here we lay it out as a small object graph and walk it
with a cycle-auditing walker that reproduces the failed compilation.
"""

# ---- Node archetypes ----

node TypeDef {
    has name: str = "";
}

node StructType {
    has name: str = "";
    has uses_pointer: bool = False;
}

node AliasType {
    has name: str = "";
}

# ---- Typed edges ----

edge DeclaredIn { }

edge AliasField { }

edge ResolvesTo { }

# ---- Walker: cycle auditor ----
#
# Walker 0.36.1 has no built-in dedup of visited nodes, so cycle policy
# must be explicit. We carry a stack of struct names we have descended
# into and report a violation any time we re-enter one. We use depth
# caps as a belt-and-braces guard against runaway traversal in the
# buggy cases (direct / alias self-reference and mutual recursion).

walker CycleAuditor {
    has findings: list[str] = [];
    has stack: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 6;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can enter_ns with TypeDef entry {
        visit [->:DeclaredIn:->] else { disengage; }
    }

    can scan_struct with StructType entry {
        if self.depth >= self.max_depth {
            label = "E3061: struct '" + here.name + "' cannot contain itself by value; use '^" + here.name + "' for recursive types";
            print("[" + label + "]");
            self.findings = self.findings + [label];
            disengage;
        }
        self.stack = self.stack + [here.name];
        self.depth = self.depth + 1;
        verdict = "ok";
        for frame in self.stack {
            if frame == here.name and frame != self.stack[-1] {
                verdict = "E3061: struct '" + here.name + "' cannot contain itself by value; use '^" + here.name + "' for recursive types";
            }
        }
        if verdict == "ok" {
            print("[reached] " + here.name);
        } else {
            print("[" + verdict + "]");
            self.findings = self.findings + [verdict];
        }
        visit [->:AliasField:->] else { disengage; }
    }

    can resolve_alias with AliasType entry {
        visit [->:ResolvesTo:->] else { disengage; }
    }
}

# ---- Walker: pointer-form auditor ----
#
# The expected-behavior half: a struct that breaks the cycle with a
# pointer field should compile and run, so this walker just confirms
# the fixed form is reachable from the namespace without tripping E3061.

walker PointerFormChecker {
    has visited_count: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can enter_ns with TypeDef entry {
        visit [-->] else { disengage; }
    }

    can confirm with StructType entry {
        self.visited_count = self.visited_count + 1;
        if here.uses_pointer {
            print("[compile-ok] " + here.name + " uses '^' field — no E3061");
        } else {
            print("[audit] " + here.name + " uses by-value fields — E3061 applies");
        }
    }
}

# ---- Demo wiring ----

with entry {
    ns = TypeDef(name="types");
    root ++> ns;

    # Case A: buggy direct self-reference through an alias.
    # Struct Node -> field NodeAlias -> resolves back to Node.
    buggy_node = StructType(name="Node");
    ns +>:DeclaredIn:+> buggy_node;
    next_alias = AliasType(name="NodeAlias");
    buggy_node +>:AliasField:+> next_alias;
    next_alias +>:ResolvesTo:+> buggy_node;

    # Case B: buggy mutual recursion through aliases.
    # A -> BAlias -> B, B -> AAlias -> A.
    a_struct = StructType(name="A");
    b_struct = StructType(name="B");
    ns +>:DeclaredIn:+> a_struct;
    ns +>:DeclaredIn:+> b_struct;
    a_alias = AliasType(name="AAlias");
    b_alias = AliasType(name="BAlias");
    a_struct +>:AliasField:+> b_alias;
    b_alias +>:ResolvesTo:+> b_struct;
    b_struct +>:AliasField:+> a_alias;
    a_alias +>:ResolvesTo:+> a_struct;

    # Case C: fixed form using a pointer field (Node -> ^Node).
    fixed_node = StructType(name="NodeFixed", uses_pointer=True);
    ns +>:DeclaredIn:+> fixed_node;
    fixed_alias = AliasType(name="NodeFixedAlias");
    fixed_node +>:AliasField:+> fixed_alias;
    fixed_alias +>:ResolvesTo:+> fixed_node;

    print("--- cycle auditor (buggy alias chains) ---");
    auditor = CycleAuditor();
    root spawn auditor;
    print("cycle auditor findings: " + str(auditor.findings));

    print("--- pointer-form checker (fixed forms) ---");
    checker = PointerFormChecker();
    root spawn checker;
    print("pointer-form checker visited " + str(checker.visited_count) + " structs");
}

