import io;
import from contextlib { redirect_stdout }

test "alias self-reference triggers E3061" {
    ns = TypeDef(name="types");
    root ++> ns;
    node_struct = StructType(name="Node");
    ns +>:DeclaredIn:+> node_struct;
    node_alias = AliasType(name="NodeAlias");
    node_struct +>:AliasField:+> node_alias;
    node_alias +>:ResolvesTo:+> node_struct;
    assert len([root-->]) == 1, "expected one root child, got " + str(len([root-->]));
    assert node_struct in [ns ->:DeclaredIn:->], "Node struct not declared in namespace";
    assert node_alias in [node_struct ->:AliasField:->], "alias field edge missing";
    assert node_struct in [node_alias ->:ResolvesTo:->], "alias must resolve back to Node";
    auditor = CycleAuditor(max_depth=4);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn auditor;
    }
    out = buf.getvalue();
    assert "E3061" in out, "expected E3061 in output, got: " + out;
    assert "Node" in out, "expected Node named in diagnostic, got: " + out;
    assert len(auditor.findings) > 0, "expected non-empty findings, got: " + str(auditor.findings);
}

test "mutual alias recursion triggers E3061" {
    ns = TypeDef(name="types");
    root ++> ns;
    a_struct = StructType(name="A");
    b_struct = StructType(name="B");
    ns +>:DeclaredIn:+> a_struct;
    ns +>:DeclaredIn:+> b_struct;
    a_alias = AliasType(name="AAlias");
    b_alias = AliasType(name="BAlias");
    a_struct +>:AliasField:+> b_alias;
    b_alias +>:ResolvesTo:+> b_struct;
    b_struct +>:AliasField:+> a_alias;
    a_alias +>:ResolvesTo:+> a_struct;
    assert len([ns ->:DeclaredIn:->]) == 2, "expected two declared structs, got " + str(len([ns ->:DeclaredIn:->]));
    assert b_alias in [a_struct ->:AliasField:->], "A must alias-field to BAlias";
    assert a_alias in [b_struct ->:AliasField:->], "B must alias-field to AAlias";
    auditor = CycleAuditor(max_depth=4);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn auditor;
    }
    out = buf.getvalue();
    assert "E3061" in out, "expected E3061 for mutual recursion, got: " + out;
    assert "cannot contain itself by value" in out, "expected by-value cycle message, got: " + out;
    assert len(auditor.findings) > 0, "expected findings for A/B cycle, got: " + str(auditor.findings);
}

test "pointer field form reports compile-ok" {
    ns = TypeDef(name="types");
    root ++> ns;
    fixed = StructType(name="NodeFixed", uses_pointer=True);
    ns +>:DeclaredIn:+> fixed;
    fixed_alias = AliasType(name="NodeFixedAlias");
    fixed +>:AliasField:+> fixed_alias;
    fixed_alias +>:ResolvesTo:+> fixed;
    checker = PointerFormChecker();
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn checker;
    }
    out = buf.getvalue();
    assert "[compile-ok]" in out, "expected compile-ok marker, got: " + out;
    assert "NodeFixed" in out, "expected NodeFixed in output, got: " + out;
    assert checker.visited_count == 1, "expected one struct visited, got: " + str(checker.visited_count);
    assert fixed.uses_pointer == True, "pointer flag should be set on fixed struct";
}

test "by-value struct flagged under pointer checker" {
    ns = TypeDef(name="types");
    root ++> ns;
    val_struct = StructType(name="ByValue", uses_pointer=False);
    ns +>:DeclaredIn:+> val_struct;
    checker = PointerFormChecker();
    buf = io.StringIO();
    with redirect_stdout(buf) {
