    b2 +>:Follows:+> c2;
    c2 +>:Follows:+> d2;
    d2 +>:Follows:+> e2;
    e2 +>:Follows:+> f2;
    f2 +>:Follows:+> e2;

    print("\n=== repeatUntilStable (fixed: register-forwarding accumulator) ===");
