                next_frontier.extend([e for e in [n-->] if not e.visited]);
            }
            frontier = next_frontier;
        }
        if not frontier {
            self.trace.append(f"fixed: stable after hop {i} (frontier exhausted)");
        }
    }
}

walker Reachability {
    has target: str = "";
    has found: bool = False;
    has trace: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can climb with Step entry {
        if here.name == self.target {
            self.found = True;
            self.trace.append(f"reachable: {here.name}");
            disengage;
        }
        visit [->:Follows:->];
    }
}

