"""Tests for the repeatUntilStable frontier-propagation demo.

Each test builds its own fresh graph (tests run in parallel isolated workers)
and asserts the behavior promised by the issue: the buggy walker terminates
after hop 1 (static seed binding), the fixed walker advances the frontier
across iterations and exhausts all reachable nodes, and reachability probes
on cyclic subgraphs still find their target."""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Buggy walker: the loop body re-walks from the seed every iteration so it
# never advances beyond hop 1 — exactly the static-register-binding bug.
# ---------------------------------------------------------------------------
test "buggy walker terminates after hop 1 (static seed bug)" {
    a = Step(name="A");
    b = Step(name="B");
    c = Step(name="C");
    d = Step(name="D");
    a +>:Follows:+> b;
    b +>:Follows:+> c;
    c +>:Follows:+> d;

    buggy = RepeatUntilStableBuggy();
    a spawn buggy;

    # Only the seed should ever be marked visited, because the buggy walker
    # re-walks from `here` every iteration rather than from R_1.
    assert a.visited, f"seed A should be visited; trace={buggy.trace}";
    assert not b.visited, f"B must NOT be visited (hop 1 frontier never forwarded); trace={buggy.trace}";
    assert not c.visited, f"C must NOT be visited; trace={buggy.trace}";
    assert not d.visited, f"D must NOT be visited; trace={buggy.trace}";

    # The trace must record the early-termination diagnostic from the walker.
    joined = "\n".join(buggy.trace);
    assert "buggy hop=1 reached A" in joined, f"missing hop=1 line: {joined}";
    assert "terminated after hop 1" in joined, f"missing termination marker: {joined}";

    # Only one hop should ever appear in the trace — the bug freezes the frontier.
    hop_lines = [ln for ln in buggy.trace if ln.startswith("buggy hop=")];
    assert len(hop_lines) == 1, f"expected exactly 1 hop line, got {len(hop_lines)}: {hop_lines}";
}

# ---------------------------------------------------------------------------
# Fixed walker: register-forwarding carries the frontier forward, so every
# transitive descendant on the linear DAG is reached.
# ---------------------------------------------------------------------------
test "fixed walker advances frontier along linear DAG (A->B->C->D)" {
    a = Step(name="A");
    b = Step(name="B");
    c = Step(name="C");
    d = Step(name="D");
    a +>:Follows:+> b;
    b +>:Follows:+> c;
    c +>:Follows:+> d;

    fixed = RepeatUntilStableFixed();
    a spawn fixed;

    # Every node on the linear chain must end up visited.
    assert a.visited, "A (seed) should be visited";
    assert b.visited, "B should be reached (hop 2)";
    assert c.visited, "C should be reached (hop 3)";
    assert d.visited, "D should be reached (hop 4)";

    # Hop distances track how many forwarding steps each node required.
    assert a.hop == 1, f"A.hop should be 1, got {a.hop}";
    assert b.hop == 2, f"B.hop should be 2, got {b.hop}";
    assert c.hop == 3, f"C.hop should be 3, got {c.hop}";
    assert d.hop == 4, f"D.hop should be 4, got {d.hop}";

    joined = "\n".join(fixed.trace);
    for nm in ["A", "B", "C", "D"] {
        assert f"reached {nm}" in joined, f"fixed trace missing reach for {nm}: {joined}";
    }
    assert "stable after hop 4" in joined, f"missing stable marker at hop 4: {joined}";
}

# ---------------------------------------------------------------------------
# Fixed walker on a cyclic subgraph: register-forwarding + visited-set
# accumulation must terminate and still visit every distinct node in the
# cycle (no infinite loop, no skipped members).
# ---------------------------------------------------------------------------
test "fixed walker handles cyclic branch and exhausts frontier" {
    a = Step(name="A");
    b = Step(name="B");
    e = Step(name="E");
    f = Step(name="F");
    a +>:Follows:+> b;
    b +>:Follows:+> e;
    e +>:Follows:+> f;
    f +>:Follows:+> e;

    fixed = RepeatUntilStableFixed();
    a spawn fixed;

    # All four distinct nodes must end up visited despite the E<->F cycle.
    assert a.visited, "A should be visited";
    assert b.visited, "B should be visited";
    assert e.visited, "E should be visited (cycle member)";
    assert f.visited, "F should be visited (cycle member)";

    # Both cycle members must appear in the trace — neither was skipped.
    joined = "\n".join(fixed.trace);
    assert "reached E" in joined, f"trace missing E: {joined}";
    assert "reached F" in joined, f"trace missing F: {joined}";

    # The fixed walker must terminate and report a stable frontier (it
    # ran out of *new* nodes to add to the accumulator).
    assert "stable after hop" in joined, f"missing stable marker: {joined}";
}

# ---------------------------------------------------------------------------
# Reachability: a depth-following probe must locate 'D' even when the seed
# is A, and the probe must terminate by setting found=True exactly once.
# ---------------------------------------------------------------------------
test "reachability probe finds a transitive descendant 'D'" {
    a = Step(name="A");
    b = Step(name="B");
    c = Step(name="C");
    d = Step(name="D");
    a +>:Follows:+> b;
    b +>:Follows:+> c;
    c +>:Follows:+> d;

    probe = Reachability(target="D");
    a spawn probe;

    assert probe.found, f"reachability should locate D; trace={probe.trace}";

    joined = "\n".join(probe.trace);
    assert "reachable: D" in joined, f"missing reachable:D line: {joined}";

    # Exactly one target notification — the walker disengages on the hit.
    hits = [ln for ln in probe.trace if ln.startswith("reachable:")];
    assert len(hits) == 1, f"expected 1 reachable line, got {len(hits)}: {hits}";
}

# ---------------------------------------------------------------------------
# End-to-end: spawn the buggy and fixed walkers in sequence on identically
# shaped graphs and confirm the buggy trace stops early while the fixed
# trace reaches every node.  Also exercise stdout capture of the demo.
# ---------------------------------------------------------------------------
test "end-to-end: buggy stalls, fixed reaches full transitive closure" {
    a = Step(name="A");
    b = Step(name="B");
    c = Step(name="C");
    d = Step(name="D");
    e = Step(name="E");
    f = Step(name="F");
    a +>:Follows:+> b;
    b +>:Follows:+> c;
    c +>:Follows:+> d;
    d +>:Follows:+> e;
    e +>:Follows:+> f;
    f +>:Follows:+> e;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        buggy = RepeatUntilStableBuggy();
        a spawn buggy;

        # Fresh subgraph for the fixed walker so visited flags are clean.
        a2 = Step(name="A");
        b2 = Step(name="B");
        c2 = Step(name="C");
        d2 = Step(name="D");
        e2 = Step(name="E");
        f2 = Step(name="F");
        a2 +>:Follows:+> b2;
        b2 +>:Follows:+> c2;
        c2 +>:Follows:+> d2;
        d2 +>:Follows:+> e2;
        e2 +>:Follows:+> f2;
        f2 +>:Follows:+> e2;

        fixed = RepeatUntilStableFixed();
        a2 spawn fixed;

        for line in buggy.trace { print(line); }
        print("---");
        for line in fixed.trace { print(line); }
    }

    out = buf.getvalue();

    # Buggy side: stuck after hop 1.
    assert "buggy hop=1 reached A" in out, f"missing buggy hop 1 line: {out}";
    assert "terminated after hop 1" in out, f"buggy did not report the early-termination marker: {out}";
    assert "buggy hop=2 reached" not in out, f"buggy must not advance to hop 2: {out}";

    # Fixed side: reached every node and reported stability.
    for nm in ["A", "B", "C", "D", "E", "F"] {
        assert f"fixed hop=" in out and f"reached {nm}" in out, f"fixed trace missing {nm}: {out}";
    }
    assert "stable after hop" in out, f"fixed walker missing stable marker: {out}";
}

