    has query_entity_ids: list[str] = [];
    has ranked: list[dict] = [];

    can start with Root entry {
        visit [-->];
    }

    can score with MemoryRecord entry {
        overlap = 0;
        for eid in here.mentions {
            if eid in self.query_entity_ids {
                overlap += 1;
            }
        }
        self.ranked.append({
            "memory_id": here.memory_id,
            "text": here.text,
            "shared_entities": overlap,
        });
        visit [->:RefersTo:->];
    }

    def report -> list {
        # Highest overlap first; ties keep insertion order.
        return sorted(self.ranked, key=lambda (r: dict) { -r["shared_entities"] }, reverse=False);
    }
}

