test "resolves a surface form to its canonical entity" {
    surface = EntityNode(
        entity_id="S-USER",
        canonical_name="the user",
    );
    alice = EntityNode(
        entity_id="E-ALICE",
        canonical_name="Alice",
    );

    root ++> surface;
    surface +>:AliasOf(weight=1.0):+> alice;

    res = root spawn EntityLinker(
        original_query="What did the user ship?"
    );
    linked = res.summarize();

    assert linked["original_query"] == "What did the user ship?", f"got {linked}";
    assert "S-USER" in linked["resolved_entity_ids"], f"got {linked}";
    assert "E-ALICE" in linked["resolved_entity_ids"], f"got {linked}";
    assert "the user" in linked["expanded_terms"], f"got {linked}";
    assert "Alice" in linked["expanded_terms"], f"got {linked}";
}

test "ranks memories by shared entity count" {
    alice = EntityNode(entity_id="E-ALICE", canonical_name="Alice");
    bob = EntityNode(entity_id="E-BOB", canonical_name="Bob");

    related = MemoryRecord(
        memory_id="M-RELATED",
        text="Alice shipped the fix.",
        mentions=["E-ALICE"],
    );
    unrelated = MemoryRecord(
        memory_id="M-UNRELATED",
        text="Bob filed a PR.",
        mentions=["E-BOB"],
    );

    root ++> related;
    root ++> unrelated;
    related +>:RefersTo(confidence=0.95):+> alice;
    unrelated +>:RefersTo(confidence=0.91):+> bob;

    res = root spawn MemoryRanker(query_entity_ids=["E-ALICE"]);
    ranked = res.summarize();

    assert len(ranked) == 2, f"got {ranked}";
    assert ranked[0]["memory_id"] == "M-RELATED", f"got {ranked}";
    assert ranked[0]["shared_entities"] == 1, f"got {ranked}";
    assert ranked[1]["memory_id"] == "M-UNRELATED", f"got {ranked}";
    assert ranked[1]["shared_entities"] == 0, f"got {ranked}";
}

test "counts multiple shared entities in one memory" {
