    # separately: they must stay with their owning family, not be moved).
    cmd_ingest_a = Command(name="ingest.run", is_schema_generated=True);
    cmd_ingest_b = Command(name="ingest.status");
    cmd_export_a = Command(name="export.to_parquet", is_schema_generated=True);
    cmd_export_b = Command(name="export.to_csv");
    cmd_cli_root = Command(name="ark", is_schema_generated=True);

