    # about. Exporting to parquet requires ingest to run first; editing
    # ingest forces a rebuild of the export family.
    cmd_export_a +>:Depends(reason="export"):+> cmd_ingest_a;

    # A back-edge that creates a cycle between export and the CLI root,
    # exercising the cycle guard on the family traversal.
    cmd_cli_root +>:Depends(reason="cli"):+> cmd_export_a;

    # Tag each Depends edge with the owning family of its source so the
    # auditor can classify without a second traversal.
    for e in [cmd_ingest_a->:Depends:->cmd_ingest_b] {
        e._owner_family = "ingest";
    }
    for e in [cmd_export_a->:Depends:->cmd_ingest_a] {
        e._owner_family = "export";
    }
    for e in [cmd_cli_root->:Depends:->cmd_export_a] {
        e._owner_family = "cli";
    }

    root spawn BuildAuditor();
