"""Regression tests for the CVE-2026-22745 vulnerable dependency graph."""

import io;
import from contextlib { redirect_stdout }

test "VulnerabilityScanner flags only vulnerable artifacts" {
    root ++> Artifact(gav="org.springframework.boot:spring-boot-starter-web",
                      version="3.0.3");
    webmvc = Artifact(gav="org.springframework:spring-webmvc",
                      version="6.0.5",
                      vulnerable=True);
    safe = Artifact(gav="org.springframework:spring-context",
                    version="6.0.5",
                    vulnerable=False);
    root +>:DependsOn:+> webmvc;
    root +>:DependsOn:+> safe;

    scanner = VulnerabilityScanner();
    res = root spawn scanner;

    assert len(res.findings) == 1, f"expected exactly 1 vulnerable hit, got {len(res.findings)}";
    assert res.findings[0].gav == "org.springframework:spring-webmvc", f"unexpected gav: {res.findings[0].gav}";
    assert res.findings[0].version == "6.0.5", f"unexpected version: {res.findings[0].version}";
    assert res.findings[0].vulnerable is True, "flagged node must be marked vulnerable";
}

