    a +>:DependsOn:+> b;
    b +>:DependsOn:+> c;
    c +>:DependsOn:+> d;

    scanner = VulnerabilityScanner();
    res = root spawn scanner;

    gavs = sorted([f.gav for f in res.findings]);
