"""Regression tests for the Phase-3 analytics prerequisite demo."""

import io;
import from contextlib { redirect_stdout }

test "prerequisite checker flags unmet spec and reports only the failing label" {
    analytics = Analytics(title="F-501");
    analytics +>:DependsOn:+> Prerequisite(label="Phase 1 complete", satisfied=True);
    analytics +>:DependsOn:+> Prerequisite(label="Spec approved", satisfied=False);
    analytics +>:DependsOn:+> Prerequisite(label="Workspace boundary defined", satisfied=True);
    analytics +>:DependsOn:+> Prerequisite(label="Application history retained (#17)", satisfied=True);

    spec_prereq = Prerequisite(label="Spec approved", satisfied=False);
    spec = Spec(title="Permit Performance Analytics", approved=False, owner="jzeng151", reviewer="unassigned");
    spec_prereq +>:DependsOn:+> spec;

    root ++> analytics ++> spec_prereq;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        checker = PrerequisiteChecker();
        root spawn checker;
    }

    assert not checker.ok, f"checker should fail when a prerequisite is unsatisfied, got ok={checker.ok}";
    assert len(checker.issues) == 1, f"exactly one issue expected, got {len(checker.issues)}: {checker.issues}";
    assert "Spec approved" in checker.issues[0], f"wrong issue label: {checker.issues[0]}";
    assert "Phase 1" not in str(checker.issues), f"satisfied prereqs should not be reported as issues: {checker.issues}";

    out = buf.getvalue();
    assert "[OK] Phase 1 complete" in out, f"missing satisfied prereq output: {out}";
    assert "[OK] Workspace boundary defined" in out, f"missing satisfied prereq output: {out}";
    assert "[OK] Application history retained (#17)" in out, f"missing satisfied prereq output: {out}";
}

