"""Agent Relay RFC #8 demo: decision authority, mission modes, evidence maturity, and stagnation escalation.

Models four orthogonal semantics as node archetypes with typed edges, and uses walkers to
exercise the protocol-level concerns the RFC raises: traversal of delegated decision authority,
escalation on repeated same-role failure, and evidence-maturity gating.
"""

# --- Mission modes (the "kind of work" axis) ---

node Mission {
    has title: str = "";
    has desired_outcome: str = "";
}

node MissionMode {
    has name: str = "";
    # A short tag describing the category of work this pass is performing.
    # Mirrors Anthropic's nine work modes without becoming a role.
    has category: str = "";
}

# --- Decision authority envelope ---

# A DecisionClass is a *class* of decision. The envelope assigns each class
# to a role/actor. Decisions and actors are stored as typed fields so the
# walker can compute which actor owns a decision class.

node DecisionClass {
    has label: str = "";
}

node AuthorityEnvelope {
    # The mission this envelope was issued under.
    has scope: str = "";
}

# Typed edge: which DecisionClass is delegated to which actor. Payload
# carries the actor's role name so the walker doesn't have to introspect
# node identity to read the delegation.
edge Delegates {
    has actor_role: str = "";
}

# Typed edge: which Mission a DecisionClass belongs to.
edge BelongsTo {
    has mission_title: str = "";
}

# --- Evidence maturity ---

node Evidence {
    has claim: str = "";
    has maturity: str = "unverified";  # unverified / partial / verified
    has verifiable_signal: bool = False;
}

# Typed edge: a Claim relies on an Evidence item. Payload carries the
# relying pass id so we can do whole-record invalidation when evidence
# maturity regresses.
edge ReliesOn {
    has relying_pass: str = "";
}

# --- Stagnation / escalation ---

# A FailureRecord is the trail of repeated same-role attempts. When its
# length crosses a threshold, the protocol escalates instead of retrying.
node FailureRecord {
    has pass_id: str = "";
    has role: str = "";
    has attempt: int = 0;
}

# Typed edge: a FailureRecord is filed against a Claim / pass attempt.
edge FiledAgainst {
    has target: str = "";
}

# Typed edge: an Escalation link from a stale FailureRecord to the new
# role/lens that should take over.
edge EscalatesTo {
    has reason: str = "";
}

# Escalation threshold: at this many same-role failures, escalate.
glob ESCALATION_THRESHOLD: int = 3;

# =====================================================================
# Walkers
# =====================================================================

# AuthorityInspector: traverses the envelope and reports which actor owns
# each DecisionClass. Demonstrates the "execution autonomy does not imply
# planning authority" concern by separating the two delegation classes.
walker AuthorityInspector {
    has report: list[str] = [];

    can start with Root entry {
        visit [->:BelongsTo:->];
    }

    can cross_class with DecisionClass entry {
        visit [->:Delegates:->];
    }

    can record_actor with AuthorityEnvelope | MissionMode | Mission entry {
        # Only AuthorityEnvelope triggers the report; the union catches
        # other targets so traversal doesn't stall.
        if self.__class__ == AuthorityEnvelope {
            label = here.scope;
            report_line = f"[AUTH] envelope '{label}' owns: " + ", ".join(self.report);
            print(report_line);
        }
        # Reset and continue.
        self.report = [];
        visit [->:BelongsTo:->];
    }

    can read_delegation with Mission entry {
        # Mission doesn't have a delegated actor directly; just continue.
        visit [->:Delegates:->];
    }
}

# EscalationWalker: walks the failure trail for a given role and decides
# whether the same-role retry loop should escalate. Models the "repeated
# failure should trigger a role/lens change" concern.
walker EscalationWalker {
    has role: str = "";
    has failed: list[str] = [];
    has escalated: bool = False;
    has new_role: str = "";

