# - ``arglist_hoisted`` marks the hoist that breaks ``tAdd`` in ``f() + tAdd()``.
node CallSite {
    has label: str = "";
    has callee_kind: str = "simple_identifier";
    has arglist_hoisted: bool = False;
}

# A function-body wrapper that holds the call sites of one caller.
node FunctionBody {
    has func_name: str = "";
}

