"""Goal & Task Planning: model goals decomposed into tasks across a project,
track lifecycle state, and walk the work graph to inspect progress and
detect invalid nesting."""

# ---------- Entity archetypes ----------

node Goal {
    has title: str = "";
    has state: str = "draft";
    # valid states for goals: draft, active, done, cancelled
}

node Task {
    has title: str = "";
    has state: str = "todo";
    # valid states for tasks: todo, in_progress, done, cancelled
}

node Project {
    has name: str = "";
}

# ---------- Relationship edges ----------

# A Project aims at a Goal.
edge AimsAt { }

# A Goal may be decomposed into sub-goals.
edge DecomposesTo { }

# A Goal may be decomposed into Tasks.
edge AchievedBy { }

# A large Task may be broken into smaller Tasks.
edge SubtaskOf { }

# ---------- Walkers ----------

# Walk every work item in a project and report its current state.
walker ProjectAuditor {
    has audit_log: list[str] = [];
    has bad: list[str] = [];

    can begin with Project entry {
        self.audit_log.append(f"Project: {here.name}");
        visit [->:AimsAt:->];
    }

    # Inspect a goal and keep walking its sub-structure.
    can audit_goal with Goal entry {
        line = f"  [Goal:{here.state}] {here.title}";
        self.audit_log.append(line);
        if here.state not in ["draft", "active", "done", "cancelled"] {
            self.bad.append(here.title);
        }
        visit [->:DecomposesTo:->];
        visit [->:AchievedBy:->];
    }

    # Inspect a task and keep walking its sub-tasks.
    can audit_task with Task entry {
        line = f"  [Task:{here.state}] {here.title}";
        self.audit_log.append(line);
        if here.state not in ["todo", "in_progress", "done", "cancelled"] {
            self.bad.append(here.title);
        }
        visit [->:SubtaskOf:->];
    }
}

# Find tasks in 'done' state that still have non-done sub-tasks
# (i.e. a work-breakdown inconsistency) using a walker traversal.
walker WorkBreakdownChecker {
    has issues: list[str] = [];

    can begin with Project entry {
        visit [->:AimsAt:->];
    }

    can check_goal with Goal entry {
        visit [->:DecomposesTo:->];
        visit [->:AchievedBy:->];
    }

    can check_task with Task entry {
        for sub in [->:SubtaskOf:->] {
            sub_task = sub;
            if here.state == "done" and sub_task.state != "done" {
                self.issues.append(
                    f"{here.title} is done but subtask {sub_task.title} is {sub_task.state}"
                );
            }
        }
        visit [->:SubtaskOf:->];
    }
}

# Cancel an entire goal subtree (cascade state update) by walking it.
walker GoalCanceller {
    can begin with Goal entry {
        cancel_goal(here);
        visit [->:DecomposesTo:->];
        visit [->:AchievedBy:->];
    }

    can cascade_goal with Goal entry {
        cancel_goal(here);
        visit [->:DecomposesTo:->];
        visit [->:AchievedBy:->];
    }

    can cascade_task with Task entry {
        cancel_task(here);
        visit [->:SubtaskOf:->];
    }
}

# Module-level helpers (regular defs, not abilities).
def cancel_goal(g: Goal) -> None {
    if g.state != "done" {
        g.state = "cancelled";
    }
}

def cancel_task(t: Task) -> None {
    if t.state != "done" {
        t.state = "cancelled";
    }
}

# ---------- Demo wiring ----------

with entry {
    # Build the project tree:
    #   Project "Apollo" -> Goal "Reach the moon"
    #       sub-goal "Build rocket"
    #           sub-goal "Build engines"
    #           task "Hire engineers" -> subtask "Find welders"
    #       task "Train astronauts" -> subtask "Medical clearance"
    #                              -> subtask "Flight simulation"
    apollo = Project(name="Apollo");
    root ++> apollo;

    root_goal = Goal(title="Reach the moon", state="active");
    apollo +>:AimsAt:+> root_goal;

    build_rocket = Goal(title="Build rocket", state="active");
    root_goal +>:DecomposesTo:+> build_rocket;

    build_engines = Goal(title="Build engines", state="active");
    build_rocket +>:DecomposesTo:+> build_engines;

    hire = Task(title="Hire engineers", state="in_progress");
    build_rocket +>:AchievedBy:+> hire;

    welders = Task(title="Find welders", state="in_progress");
    hire +>:SubtaskOf:+> welders;

    train = Task(title="Train astronauts", state="in_progress");
    root_goal +>:AchievedBy:+> train;

    medical = Task(title="Medical clearance", state="done");
    train +>:SubtaskOf:+> medical;

    sim = Task(title="Flight simulation", state="done");
    train +>:SubtaskOf:+> sim;

    # 1) Audit the project.
    auditor = ProjectAuditor();
    apollo spawn auditor;
    for line in auditor.audit_log {
        print(line);
    }
    if auditor.bad {
        print(f"Bad-state items: {auditor.bad}");
    } else {
        print("All items report a valid state.");
    }

    print("---");

    # 2) Work-breakdown consistency check.
    checker = WorkBreakdownChecker();
    apollo spawn checker;
    if checker.issues {
        for issue in checker.issues {
            print(f"WBD issue: {issue}");
        }
    } else {
        print("Work breakdown is consistent.");
    }

    print("---");

    # 3) Cascade-cancel the "Build rocket" goal subtree.
    canceller = GoalCanceller();
    build_rocket spawn canceller;

    # Tally how many goals/tasks ended up cancelled under Apollo.
    tally = ProjectAuditor();
    apollo spawn tally;
    cancelled_titles = [];
    for line in tally.audit_log {
        if ":cancelled]" in line {
            cancelled_titles.append(line);
        }
    }
    print(f"Cascade-cancelled {len(cancelled_titles)} items:");
    for line in cancelled_titles {
        print(f"  {line}");
    }
}

