test "raster prefix below gate selects serial sort" {
    gate = RenderGate(gate_name="DRAW_SORT_PARALLEL", threshold=3000, branch_taken="PARALLEL");
    root ++> gate;
    part = Partition(total=500, raster_len=150, tail_len=350);
