walker CC {
    has lane_label: str = "CAMPFIRE";
    has ledger: list[str] = [];
    has seen: list[str] = [];

    def already_visited(label: str) -> bool {
        for prior in self.seen {
            if prior == label {
                return True;
            }
        }
        return False;
    }

    def visited_count() -> int {
        return len(self.seen);
    }

