        # request: rebuild the slot at the requested size, then drop
        # the scratch buffer that was sized for the old max_instances.
        pending_edges = [root->:ShrinkRequested:->];
        has_pending = False;
        for e in pending_edges {
            if e.pending and slot_idx == slot_idx {
                has_pending = True;
