test "audits a dependency graph and reports failures" {
    api1 = ApiCall(name="chat_completion", model="gpt-4o", temperature=1.0);
    api2 = ApiCall(name="legacy_call", model="gpt-3.5", temperature=0.2);
    cfg1 = ConfigFile(name="openai.toml", max_tokens=512);
    cfg2 = ConfigFile(name="defaults.env", max_tokens=0);
    wf1 = Workflow(name="retry_loop", retries=3);
    wf2 = Workflow(name="infinite_retry", retries=999);

    root +>:DependsOn(criticality="high"):+> wf1;
    root +>:DependsOn(criticality="high"):+> wf2;
    wf1 +>:DependsOn(criticality="normal"):+> cfg1;
    wf2 +>:DependsOn(criticality="normal"):+> cfg2;
    cfg1 +>:DependsOn(criticality="critical"):+> api1;
    cfg2 +>:DependsOn(criticality="critical"):+> api2;

    assert len([root-->]) == 2, f"root children: {len([root-->])}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ComplianceAuditor();
    }
    out = buf.getvalue();

    assert len(res.seen) == 6, f"seen: {res.seen}";
    assert len(res.findings) == 3, f"findings: {res.findings}";
    assert "[OK]   chat_completion" in out, f"missing compliant API: {out}";
    assert "[FAIL] legacy_call" in out, f"missing API finding: {out}";
    assert "[FAIL] defaults.env" in out, f"missing config finding: {out}";
    assert "[FAIL] infinite_retry" in out, f"missing workflow finding: {out}";
}

