    api = ApiCall(name="default_temperature", model="gpt-4o", temperature=1.0);
    cfg = ConfigFile(name="capped_config", max_tokens=1);
    wf1 = Workflow(name="one_retry", retries=1);
    wf5 = Workflow(name="five_retries", retries=5);
    wf0 = Workflow(name="zero_retries", retries=0);
    wf6 = Workflow(name="six_retries", retries=6);

    root +>:DependsOn:+> api;
    api +>:DependsOn:+> cfg;
    cfg +>:DependsOn:+> wf1;
    wf1 +>:DependsOn:+> wf5;
    wf5 +>:DependsOn:+> wf0;
    wf0 +>:DependsOn:+> wf6;

