    slash = TreeEntry(name="src/main.py", is_blob=True);
    markdown = TreeEntry(name="### Title", is_blob=True, is_markdown_text=True);
    combined = TreeEntry(name="### Overview/src/main.py", is_blob=True, is_markdown_text=True);
    long_name = TreeEntry(name="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa", is_blob=True);
