    tree +>:Child(depth=0):+> slash;
    tree +>:Child(depth=0):+> markdown;
    tree +>:Child(depth=0):+> combined;
    tree +>:Child(depth=0):+> long_name;

    auditor = root spawn PathAuditor();

    assert len(auditor.suspicious) == 4, f"got {auditor.suspicious}";
    assert auditor.suspicious[0]["path"] == "src/main.py", f"got {auditor.suspicious[0]}";
    assert auditor.suspicious[0]["slashes"] == 1, f"got {auditor.suspicious[0]}";
    assert auditor.suspicious[0]["md"] == False, f"got {auditor.suspicious[0]}";
    assert auditor.suspicious[0]["level"] == "WARN", f"got {auditor.suspicious[0]}";
    assert auditor.suspicious[1]["md"] == True, f"got {auditor.suspicious[1]}";
    assert auditor.suspicious[1]["level"] == "WARN", f"got {auditor.suspicious[1]}";
    assert auditor.suspicious[2]["level"] == "HIGH", f"got {auditor.suspicious[2]}";
    assert auditor.suspicious[3]["long"] == True, f"got {auditor.suspicious[3]}";
}

test "auditor follows only typed child edges" {
    tree = GitTree(label="typed-tree");
    root ++> tree;
    typed_entry = TreeEntry(name="### Typed path", is_blob=True);
    untyped_entry = TreeEntry(name="### Hidden path", is_blob=True);
    tree +>:Child(depth=1):+> typed_entry;
    tree ++> untyped_entry;

    children = [tree ->:Child:->];
    assert len(children) == 1, f"got {len(children)}";
    assert typed_entry in children, "typed edge missing";
    assert untyped_entry not in children, "untyped edge leaked";

    auditor = root spawn PathAuditor();
    assert len(auditor.suspicious) == 1, f"got {auditor.suspicious}";
    assert auditor.suspicious[0]["path"] == "### Typed path", f"got {auditor.suspicious}";
}

test "invalidator marks matching entries and preserves safe entries" {
    tree = GitTree(label="repair-tree");
    root ++> tree;
    target = "### Overview\nThis is the body that leaked into the path";
    exact = TreeEntry(name=target, is_blob=True, body_preview="markdown body");
    embedded = TreeEntry(name="prefix/" + target, is_blob=True, body_preview="markdown body");
    safe = TreeEntry(name="README.md", is_blob=True, body_preview="keep me");
    tree +>:Child(depth=0):+> exact;
    tree +>:Child(depth=0):+> embedded;
    tree +>:Child(depth=0):+> safe;

    root spawn CascadeInvalidator(target_path=target);

    assert exact.is_blob == False, f"exact entry remained blob: {exact.is_blob}";
    assert exact.body_preview == "[INVALIDATED]", f"got {exact.body_preview}";
    assert embedded.is_blob == False, f"embedded entry remained blob: {embedded.is_blob}";
    assert embedded.body_preview == "[INVALIDATED]", f"got {embedded.body_preview}";
    assert safe.is_blob == True, f"safe entry changed: {safe.is_blob}";
    assert safe.body_preview == "keep me", f"safe preview changed: {safe.body_preview}";
}

test "audit summary prints the suspicious count" {
    tree = GitTree(label="summary-tree");
    root ++> tree;
    entry = TreeEntry(name="docs/### Overview", is_blob=True);
    tree +>:Child(depth=0):+> entry;

    auditor = root spawn PathAuditor();
    buf = io.StringIO();
