"""Statement RU accounting: producer-side evidence over a physical-plan forest.

Models the executor-side evidence collector that walks the Main plan, the
deduplicated CTE definition forest, and the scalar-subquery (Apply) trees
to gather per-executor RU input. Each executor archetype owns the
display-neutral scalar snapshot it publishes; the Statement RU consumer
walks the forest with one collector walker, accumulating evidence in a
single typed registry.

The four core archetypes picked here are:

  - ScanExecutor: response-level key-size evidence (request root).
  - SortTopNExecutor: lifecycle-bounded sufficient statistics.
  - RecursiveCTE: explicit opportunity + disposition states.
  - Apply: explicit outer/inner/cache opportunity states.

The collector walker enforces the IDForStorage-deduplicated CTE count
and fails closed when evidence is structurally inconsistent.
"""

# ----------------------------------------------------------------------
# Node archetypes
# ----------------------------------------------------------------------

node ScanExecutor {
    has plan_id: int = 0;
    has request_id: str = "";
    has resp_total_key_bytes: int = 0;
    has consumed: bool = False;
}

node SortTopNExecutor {
    has plan_id: int = 0;
    has lifecycle_id: str = "";
    has rows_in: int = 0;
    has began: bool = False;
    has completed: bool = False;
    has incomplete: bool = False;
}

node RecursiveCTE {
    has cte_id: int = 0;
    has phase_attempts: int = 0;
    has completed_rounds: int = 0;
    has skipped: bool = False;
    has executed_zero: bool = False;
    has evidence_missing: bool = False;
}

node Apply {
    has apply_id: int = 0;
    has outer_rows: int = 0;
    has filtered_outer: int = 0;
    has cache_hits: int = 0;
    has logical_inners: int = 0;
    has physical_inners: int = 0;
    has cancelled: bool = False;
}

# ----------------------------------------------------------------------
# Edge archetypes (typed where the relationship carries meaning)
# ----------------------------------------------------------------------

edge LivesUnderPlan {}
edge CTEEdge { has storage_id: int = 0; }
edge InnerOf {}

# ----------------------------------------------------------------------
# Walker: Statement RU consumer
# ----------------------------------------------------------------------

walker Collector {
    has evidence_complete: bool = True;
    has scan_bytes_total: int = 0;
    has sort_log_sum: float = 0.0;
    has cte_seen_storage_ids: list[int] = [];

    can start with Root entry {
        visit [-->];
    }

    # CTE definitions: count each IDForStorage exactly once.
    can gather_cte with RecursiveCTE entry {
        sid = here.cte_id;
        first = True;
        for prev in self.cte_seen_storage_ids {
            if prev == sid {
                first = False;
            }
        }
        if first {
            self.cte_seen_storage_ids.append(sid);
            if here.evidence_missing {
                self.evidence_complete = False;
            }
            if here.skipped and here.executed_zero {
                self.evidence_complete = False;
            }
        }
        visit [->:CTEEdge:->];
    }

    # Apply subtree: collect outer/inner/cache evidence; fail closed
    # when positive rows appear without any physical inner execution
    # (every physical opportunity must have been attempted).
    can gather_apply with Apply entry {
        if here.outer_rows > 0 and here.physical_inners == 0 and not here.cancelled {
            self.evidence_complete = False;
        }
        visit [->:InnerOf:->];
    }

    # Response-level scan evidence: aggregate request-scoped key bytes,
    # including close-time unconsumed responses.
    can gather_scan with ScanExecutor entry {
        self.scan_bytes_total += here.resp_total_key_bytes;
        visit [->:LivesUnderPlan:->];
    }

    # Sort/TopN: per-lifecycle sufficient statistic. Repeated CTE rounds
    # and correlated Apply executions merge by plan_id; rows are summed
    # per lifecycle so the consumer cannot reconstruct sum(n*log(n))
    # from aggregate rows alone.
    can gather_sort with SortTopNExecutor entry {
        n = here.rows_in;
        if n > 1 {
            contrib = n * (n.bit_length() - 1);
            self.sort_log_sum += float(contrib);
        }
        if here.began and (not here.completed) and (not here.incomplete) {
            self.evidence_complete = False;
        }
        visit [->:LivesUnderPlan:->];
    }
}

# ----------------------------------------------------------------------
# Demonstration wiring
# ----------------------------------------------------------------------

with entry {
    # --- CTE forest (deduplicated by IDForStorage) -------------------
    cte_seed = RecursiveCTE(
        cte_id=42,
        phase_attempts=1,
        completed_rounds=0,
        skipped=False,
        executed_zero=True
    );
    cte_recursive = RecursiveCTE(
        cte_id=42,
        phase_attempts=3,
        completed_rounds=2,
        skipped=False,
        executed_zero=False
    );
    cte_skipped = RecursiveCTE(
        cte_id=99,
        phase_attempts=0,
        completed_rounds=0,
        skipped=True,
        executed_zero=False
    );

