    apply_root = Apply(
        apply_id=1,
        outer_rows=10,
        filtered_outer=3,
        cache_hits=4,
        logical_inners=7,
        physical_inners=3,
        cancelled=False
    );
    apply_cancelled = Apply(
        apply_id=2,
        outer_rows=5,
        filtered_outer=1,
