    assert res.durable_count == 2, f"durable {res.durable_count}";
    assert ev1.durable == True, f"ev1.durable = {ev1.durable}";
    assert ev2.durable == True, f"ev2.durable = {ev2.durable}";
}

test "re-analysis bypasses the assessment cache" {
    s1 = Subject(label="alpha");
    root ++> s1;

    old = Assessment(score=0.42, cached=True);
    s1 +>:AssessedBy:+> old;

    assert old.cached == True, f"old.cached = {old.cached}";
    res = root spawn ReAnalyze(subject_label="alpha", fresh_score=0.99);

