fixed.jac_tests:
"""Regression tests for the guard/decoder byte-exactness invariant modeled in
main.jac. Spawning on a node of the wrong type silently fires nothing, so
each test builds its own graph and spawns the GuardDecoder walker on a node
type that matches an ability signature (Root entry) by spawning on root."""

import io;
import from contextlib { redirect_stdout }

test "divergence is reported when elem_width does not match guard assumption" {
    # The bug #4981 modeled: guard assumes a fixed 4-byte element width while
    # the decoder resolves the actual enum width (here: 2). One element is
    # deliberately mis-resolved to width 4 to exercise the divergence path.
    root ++> AttrBlob(name="MyAttr", raw_bytes=24);

    blob = ([root-->][?:AttrBlob])[0];

    enum_def = EnumDef(enum_name="MyEnum", width=2);
    elem0 = SzArrayElem(kind="MyEnum", payload_len=2, elem_width=2);
    elem1 = SzArrayElem(kind="MyEnum", payload_len=3, elem_width=2);
    elem2 = SzArrayElem(kind="MyEnum", payload_len=4, elem_width=4);

    blob +>:HoldsArg(ordinal=0):+> elem0;
    blob +>:HoldsArg(ordinal=1):+> elem1;
    blob +>:HoldsArg(ordinal=2):+> elem2;
    elem0 +>:ResolvesTo(resolved_width=2):+> enum_def;
    elem1 +>:ResolvesTo(resolved_width=2):+> enum_def;
    elem2 +>:ResolvesTo(resolved_width=2):+> enum_def;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        w = GuardDecoder();
        root spawn w;
    }
    out = buf.getvalue();

    # elem0: guard=2+2*4=10, decoder=2+2*2=6  -> diverge
    # elem1: guard=2+3*4=14, decoder=2+3*2=8  -> diverge
    # elem2: guard=2+4*4=18, decoder=2+4*4=18 -> agree
    assert w.divergences == 2, f"expected 2 divergences, got {w.divergences}";
    assert out.count("DIVERGENCE") == 2, f"expected 2 DIVERGENCE lines, got: {out}";
    assert "DIVERGENCE on MyEnum: guard=10 decoder=6 (elem_width=2)" in out, (
        f"missing elem0 divergence line: {out}"
    );
    assert "DIVERGENCE on MyEnum: guard=14 decoder=8 (elem_width=2)" in out, (
        f"missing elem1 divergence line: {out}"
    );
    assert "ok   MyEnum: guard=decoder=18 (elem_width=4)" in out, (
        f"missing elem2 agreement line: {out}"
    );
}

test "no divergence when guard and decoder agree on every element" {
    # The "fixed" scenario: every element resolves to the same width the
    # guard assumes (4). The guard/decoder invariant holds for the whole blob.
    root ++> AttrBlob(name="AlignedAttr", raw_bytes=32);

    blob = ([root-->][?:AttrBlob])[0];
    enum_def = EnumDef(enum_name="FlagsEnum", width=4);

    elem0 = SzArrayElem(kind="FlagsEnum", payload_len=2, elem_width=4);
    elem1 = SzArrayElem(kind="FlagsEnum", payload_len=5, elem_width=4);
    elem2 = SzArrayElem(kind="FlagsEnum", payload_len=1, elem_width=4);

    blob +>:HoldsArg(ordinal=0):+> elem0;
    blob +>:HoldsArg(ordinal=1):+> elem1;
    blob +>:HoldsArg(ordinal=2):+> elem2;
    elem0 +>:ResolvesTo(resolved_width=4):+> enum_def;
    elem1 +>:ResolvesTo(resolved_width=4):+> enum_def;
    elem2 +>:ResolvesTo(resolved_width=4):+> enum_def;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        w = GuardDecoder();
        root spawn w;
    }
    out = buf.getvalue();

    assert w.divergences == 0, f"expected 0 divergences, got {w.divergences}";
    assert "DIVERGENCE" not in out, f"unexpected divergence printed: {out}";
    assert out.count("ok   FlagsEnum") == 3, (
        f"expected 3 agreement lines, got: {out}"
    );
}

test "divergence count scales with misaligned elements" {
    # Every element misaligned: guard=2+n*4, decoder=2+n*2 for n in {1,2,3}.
    # All three must diverge. This is the "structural amplification" shape
    # the issue describes (#5047) per-element replay.
    root ++> AttrBlob(name="AmplifiedAttr", raw_bytes=40);

    blob = ([root-->][?:AttrBlob])[0];
    enum_def = EnumDef(enum_name="NarrowEnum", width=2);

    elem0 = SzArrayElem(kind="NarrowEnum", payload_len=1, elem_width=2);
    elem1 = SzArrayElem(kind="NarrowEnum", payload_len=2, elem_width=2);
    elem2 = SzArrayElem(kind="NarrowEnum", payload_len=3, elem_width=2);

    blob +>:HoldsArg(ordinal=0):+> elem0;
    blob +>:HoldsArg(ordinal=1):+> elem1;
    blob +>:HoldsArg(ordinal=2):+> elem2;
    elem0 +>:ResolvesTo(resolved_width=2):+> enum_def;
    elem1 +>:ResolvesTo(resolved_width=2):+> enum_def;
    elem2 +>:ResolvesTo(resolved_width=2):+> enum_def;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        w = GuardDecoder();
        root spawn w;
    }
    out = buf.getvalue();

    assert w.divergences == 3, f"expected 3 divergences, got {w.divergences}";
    assert out.count("DIVERGENCE") == 3, f"divergence line count wrong: {out}";
    assert "DIVERGENCE on NarrowEnum: guard=6 decoder=4 (elem_width=2)" in out, (
        f"missing elem0 line: {out}"
    );
    assert "DIVERGENCE on NarrowEnum: guard=10 decoder=6 (elem_width=2)" in out, (
        f"missing elem1 line: {out}"
    );
    assert "DIVERGENCE on NarrowEnum: guard=14 decoder=8 (elem_width=2)" in out, (
        f"missing elem2 line: {out}"
    );
}

test "blob with zero arguments produces zero divergences and no element lines" {
    # An attribute blob with no arguments: the guard/decode agreement should
    # hold trivially. This guards against regressing on the empty case.
    root ++> AttrBlob(name="NoArgAttr", raw_bytes=0);

    blob = ([root-->][?:AttrBlob])[0];
    enum_def = EnumDef(enum_name="Unused", width=4);
    blob ++> enum_def;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        w = GuardDecoder();
        root spawn w;
    }
    out = buf.getvalue();

    assert w.divergences == 0, f"expected 0 divergences, got {w.divergences}";
    assert "DIVERGENCE" not in out, f"unexpected divergence printed: {out}";
    assert "ok   " not in out, f"unexpected ok line on empty blob: {out}";
    assert "--- blob: NoArgAttr" in out, f"missing blob header: {out}";
}

