import from contextlib { redirect_stdout }

test "auditor dedupes duplicate event ids and marks sync-error fail" {
    root ++> PostureChangeEvent(
        event_id="evt-001", event_type="posture-changed",
        actor="alice", timestamp="2025-01-01T00:00:00Z",
        before="open", after="restricted"
    );
    root ++> IngestionSyncEvent(
        event_id="evt-010", event_type="sync-completed",
        actor="system", timestamp="2025-01-01T00:10:00Z",
        connector="github-catalog", asset_count=42, success=True
    );
    root ++> IngestionSyncEvent(
        event_id="evt-011", event_type="sync-error",
        actor="system", timestamp="2025-01-01T00:11:00Z",
        connector="github-catalog", asset_count=0, success=False,
        error="HTTP 503"
    );
    root ++> IngestionSyncEvent(
        event_id="evt-011", event_type="sync-error",
        actor="system", timestamp="2025-01-01T00:11:00Z",
        connector="github-catalog", asset_count=0, success=False,
        error="HTTP 503"
    );

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Auditor();
    }
    out = buf.getvalue();
    assert len(res.seen) == 3, f"expected 3 unique events, got {len(res.seen)}: {res.seen}";
    assert res.duplicates == 1, f"expected 1 duplicate, got {res.duplicates}";
    assert "posture-changed" in res.seen, f"missing posture-changed in {res.seen}";
    assert "sync-completed" in res.seen, f"missing sync-completed in {res.seen}";
    assert "[OK]" in out, f"missing OK marker for non-error events: {out}";
    assert "[FAIL]" in out, f"missing FAIL marker for sync-error: {out}";
    assert "[DUP]" in out, f"missing DUP marker for duplicate evt-011: {out}";
}

test "auditor records policy crud event types without duplicates" {
    root ++> PolicyCrudEvent(
        event_id="evt-002", event_type="policy-created",
        actor="bob", timestamp="2025-01-01T00:01:00Z",
        policy_id="pol-42", action="create"
    );
    root ++> PolicyCrudEvent(
        event_id="evt-003", event_type="policy-updated",
        actor="bob", timestamp="2025-01-01T00:02:00Z",
