        f"expected policy CRUD sequence, got {res.seen}";
    assert res.duplicates == 0, f"expected no duplicates, got {res.duplicates}";
    assert "[OK]" in out, f"policy events should log OK status: {out}";
    assert "actor=bob" in out, f"missing bob actor in output: {out}";
    assert "actor=carol" in out, f"missing carol actor in output: {out}";
}

test "disconnected replayer enqueues until capacity then drops overflow" {
    q1 = QueuedEvent(event_type="sync-completed", payload="github:42 assets");
    q2 = QueuedEvent(event_type="sync-error", payload="github:HTTP 503");
    q3 = QueuedEvent(event_type="policy-created", payload="pol-99");
    q4 = QueuedEvent(event_type="policy-updated", payload="pol-99");
