    assert res.replayed == 5, f"expected 5 enqueued replays, got {res.replayed}";
    assert "[ENQ]" in out, f"missing ENQ marker: {out}";
    assert "[DROP]" in out, f"missing DROP marker when queue full: {out}";
    assert "Cluster OFFLINE" in out, f"missing offline banner: {out}";
}

test "cycle hunter detects circular triggered connector dependencies" {
    c1 = IngestionSyncEvent(
        event_id="c1", event_type="sync-completed",
        actor="system", timestamp="t1", connector="github", asset_count=1
    );
    c2 = IngestionSyncEvent(
        event_id="c2", event_type="sync-completed",
        actor="system", timestamp="t2", connector="gitlab", asset_count=1
    );
    c3 = IngestionSyncEvent(
        event_id="c3", event_type="sync-completed",
        actor="system", timestamp="t3", connector="azure-devops", asset_count=1
    );
    root ++> c1;
    c1 +>:Triggered:+> c2;
    c2 +>:Triggered:+> c3;
    c3 +>:Triggered:+> c1;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CycleHunter(max_steps=10);
    }
    out = buf.getvalue();
    assert len(res.cycles) == 1, f"expected exactly 1 cycle, got {len(res.cycles)}: {res.cycles}";
    assert "github" in res.cycles[0], f"cycle path should include github: {res.cycles[0]}";
    assert "gitlab" in res.cycles[0], f"cycle path should include gitlab: {res.cycles[0]}";
    assert "azure-devops" in res.cycles[0], f"cycle path should include azure-devops: {res.cycles[0]}";
    assert "[CYCLE]" in out, f"missing CYCLE marker: {out}";
    assert "[VISIT]" in out, f"missing VISIT marker during traversal: {out}";
}

