    has notified: bool = False;

    def timeout(reason: str) -> None {
        self.notified = True;
        print(f"[op {self.correlation_id}] TIMEOUT delivered: {reason}");
    }
}

node SoapEnvelope {
    has operation: str = "";
    has correlation_id: str = "";
    has reason: str = "";
}

# Typed edges carry the relationship meaning the parser was rebuilding
# by string keys every call.
edge Carries {
    has payload_kind: str = "messageDeliveryTimeout";
}

edge Ack {
    has http_status: int = 200;
}

edge OfOperation {
    has role: str = "pending";
}

walker Deliver {
    can start with Root entry {
        visit [->:Carries:->];
    }

    # Hand-rolled if/elif chain over `operation` becomes a node-type
    # filter on the walk.  Only `SoapEnvelope` instances match.
    can inspect with SoapEnvelope entry {
        op_name = here.operation;
        if op_name == "messageDeliveryTimeout" {
            print(f"envelope: timeout notification corr={here.correlation_id}");
            visit [here->:Ack:->];
        } else {
            print(f"envelope: unknown NSI operation: {op_name!r}");
            disengage;
        }
    }

    # Follow the correlation edge from envelope to the pending operation.
    can resolve with Operation entry {
        here.timeout(here.summary);
        print("SOAP 200 OK: messageDeliveryTimeout acknowledged");
        disengage;
    }
}

with entry {
    store = ReservationStore(store_name="aggregator");
    op_a = Operation(correlation_id="corr-001", summary="path A still building");
    op_b = Operation(correlation_id="corr-002", summary="path B still building");

    # Wire the graph exactly the way the parser used to look it up.
    root +>:OfOperation:+> store;
    store +>:OfOperation:+> op_a;
    store +>:OfOperation:+> op_b;

    good_env = SoapEnvelope(
        operation="messageDeliveryTimeout",
        correlation_id="corr-002",
        reason="P2P child segment unreachable after 30s",
    );
    bogus_env = SoapEnvelope(
        operation="unicornGreeting",
        correlation_id="corr-xxx",
        reason="",
    );

    root +>:Carries:+> good_env +>:Ack:+> op_b;
    root +>:Carries:+> bogus_env;

    Deliver() spawn root;

    print(
        f"final: op_a.notified={op_a.notified}, op_b.notified={op_b.notified}"
    );
}

