"""Tests for the messageDeliveryTimeout callback dispatch model."""

import io;
import from contextlib { redirect_stdout }

test "valid messageDeliveryTimeout envelope dispatches and acknowledges" {
    root ++> ReservationStore(store_name="test-store");

    store = [root -->][?:ReservationStore];

    op_a = Operation(correlation_id="corr-001", summary="path A still building");
    op_b = Operation(correlation_id="corr-002", summary="path B still building");

