    }
    out = buf.getvalue();

    assert "envelope: timeout notification corr=corr-002" in out, f"missing inspect line: {out}";
    assert "[op corr-002] TIMEOUT delivered: path B still building" in out, f"op_b not notified: {out}";
    assert "SOAP 200 OK: messageDeliveryTimeout acknowledged" in out, f"missing SOAP ack: {out}";
    assert op_b.notified == True, f"op_b.notified should be True, got {op_b.notified}";
    assert op_a.notified == False, f"op_a.notified must stay False, got {op_a.notified}";
