# A residency-epoch tracker node carries the worldspace's current epoch
# counter. The ReconcileFrame walker reads it; ResidencyChange mutates it.
node ResidencyEpoch {
    has epoch: int = 0;
}

node TerrainBlock {
    has key: str = "";
    has lod_level: int = 0;
    has available: bool = True;
}

node ObjectBlock {
    has key: str = "";
    has lod_level: int = 0;
    has available: bool = True;
}

node FullCell {
    has key: str = "";
    has lod_level: int = 0;
}

node Landscape {
    has immutable: bool = True;
    has name: str = "";
}

edge ResidentIn {
    has since: str = "";
}

edge AdjacentTo {
    has seam_label: str = "";
}

edge HasFull {
    has at_level: int = 0;
}

walker ResidencyChange {
    has site: str = "";

    can start with Root entry {
        visit [->:ResidentIn:->];
    }

    can bump with ResidencyEpoch entry {
        here.epoch += 1;
        print(f"[residency] bump epoch -> {here.epoch} via {self.site}");
        visit [->:ResidentIn:->];
    }
}

walker ReconcileFrame {
    has frame: int = 0;
    has last_residency_epoch: int = -1;
    has last_coverage: str = "unset";
    has last_seam: str = "unset";
    has recomputed: bool = False;

    can start with Root entry {
        # Step into the world's residency-epoch tracker first.
        visit [->:ResidentIn:->];
    }

    can gate with ResidencyEpoch entry {
        current_epoch = here.epoch;
        if current_epoch != self.last_residency_epoch {
            print(f"[frame {self.frame}] residency epoch advanced "
                  f"({self.last_residency_epoch} -> {current_epoch}): "
                  f"recomputing coverage + seam");
            self.last_residency_epoch = current_epoch;
            self.last_coverage = "computed";
            self.last_seam = "computed";
            self.recomputed = True;
            visit [-->];
        } else {
            print(f"[frame {self.frame}] epoch unchanged "
                  f"({current_epoch}): SKIP coverage + seam recompute");
