import io;
import from contextlib { redirect_stdout }

test "buggy writer drops the second security block" {
    folder = Folder(name="example");
    first = SecurityBlock(
        inheritance_strategy="InheritParentStrategy",
        permissions=["hudson.model.Item.Read:devs"],
    );
    second = SecurityBlock(
        inheritance_strategy="NonInheritingStrategy",
        permissions=["hudson.model.Item.Build:ci"],
    );
    folder +>:HasBlock(ordinal=0):+> first;
    folder +>:HasBlock(ordinal=1):+> second;
    root ++> folder;

    counter = BlockCounter();
    root spawn counter;
    buggy = BuggyWriter();
    root spawn buggy;

    assert counter.block_count == 2, f"got {counter.block_count}";
    assert buggy.rendered_count == 1, f"got {buggy.rendered_count}";
    assert buggy.rendered_permissions == ["hudson.model.Item.Read:devs"], f"got {buggy.rendered_permissions}";
}

test "validating writer rejects multiple security blocks before apply" {
    folder = Folder(name="example");
    first = SecurityBlock(
        inheritance_strategy="InheritParentStrategy",
        permissions=["hudson.model.Item.Read:devs"],
    );
    second = SecurityBlock(
        inheritance_strategy="NonInheritingStrategy",
        permissions=["hudson.model.Item.Build:ci"],
    );
    folder +>:HasBlock(ordinal=0):+> first;
    folder +>:HasBlock(ordinal=1):+> second;
    root ++> folder;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        validator = ValidatingWriter();
        root spawn validator;
    }
    out = buf.getvalue();

    assert validator.accepted == False, f"got {validator.accepted}";
    assert validator.rendered_count == 0, f"got {validator.rendered_count}";
    assert "[REJECT]" in out, f"missing rejection output: {out}";
    assert "2 security blocks" in out, f"missing block count: {out}";
}

