"""Scoped-item write-set guard.

Issue #575 — enforce declared write-sets so a scoped item cannot silently
expand its blast radius. Models the host-side capability-denial posture:
each scoped item declares a write-set of file paths; the guard
refuses writes outside it deterministically; the harness still records
what actually changed.
"""

# A scoped work item: declares intent via a write-set of file paths.
node ScopedItem {
    has title: str = "";
    has declared_writes: list[str] = [];
    has attempted_writes: list[str] = [];
    has refused_writes: list[str] = [];
    has blocked: bool = False;
}

# A file the item wants to mutate.
node File {
    has path: str = "";
    has in_scope: bool = False;
}

# Typed edge: "this file is the target of an attempted write."
edge AttemptedOn { }

walker WriteGuard {
    has current_path: str = "";

    can begin with Root entry {
        visit [-->];
    }

    can audit with ScopedItem entry {
        # Two-phase mutation: collect every AttemptedOn target first,
        # then judge. Avoids mid-iteration mutation surprises.
        attempted = [];
        for f in [->:AttemptedOn:->] {
            attempted.append(f);
        }
        for f in attempted {
            self.current_path = f.path;
            declared = here.declared_writes;
            in_declared = False;
            for p in declared {
                if p == f.path {
                    in_declared = True;
                }
            }
            # Harness-managed paths are the recorded escape hatch.
            is_harness = False;
            if f.path.startswith("docs/decision-log/") {
                is_harness = True;
            }
            if f.path == "checkpoints" {
                is_harness = True;
            }
            if in_declared or is_harness {
