            print(f"[cascade] source failure: {here.title}");
            visit [->:Blocks:->];
        } else {
            prior = here.status;
            here.status = "blocked";
            self.invalidated.append(here.title);
            print(f"[cascade] {here.title}: {prior} -> blocked");
            visit [->:Blocks:->];
        }
    }
}

walker CycleInspector {
    has guard: list[str] = [];
    has cycles: list[str] = [];

    can start with Root entry {
        visit [-->];
    }

    can scan_spec with Spec entry {
        visit [->:BelongsTo:->];
    }

    can scan_task with Task entry {
        key = here.title;
        if key in self.guard {
            cycle = " -> ".join([k for k in self.guard] + [key]);
            self.cycles.append(cycle);
            print(f"[cycle] detected: {cycle}");
            disengage;
        }
        self.guard.append(key);
        visit [->:Blocks:->];
        self.guard.pop();
