"""SandboxDependencyManager: model the stale-cache-by-name bug as a graph.

A logical ``Sandbox`` (identified by lifecycle name) is replaced over time by
concrete ``Container`` instances. Each container carries the packages pip
has actually installed on its filesystem. The ``SandboxDependencyManager``
caches which packages are "already installed" for a given logical sandbox
name. When a container is evicted and a fresh one is created under the same
logical name, the cache must be invalidated, otherwise ``ensure_requirements``
will skip pip entirely on a container that has none of the packages.

Nodes: Sandbox (logical, named), Container (instance, generation),
       Requirement (pip requirement string).
Edges: ContainerOf (Sandbox -> Container, carries generation),
       InstalledOn (Container -> Requirement),
       Manages   (Root -> SandboxDependencyManager walker host).
Walker:  DependencyAuditor walks Container nodes, collects installed pkgs,
         compares to required set, flags stale-cache misses.
"""

node Sandbox {
    has name: str = "";
}

node Container {
    has generation: int = 0;
    has filesystem_label: str = "";
}

node Requirement {
    has pkg: str = "";
}

edge ContainerOf {
    has generation: int = 0;
}

edge InstalledOn {
    has version: str = "";
}

edge Manages { }

edge Current { }

walker DependencyAuditor {
    has required: list[str] = [];
    has findings: list[str] = [];
    has audited: list[str] = [];

    can start with Root entry {
        visit [->:Manages:->];
    }

    can audit with Sandbox entry {
        # Walk every container currently attached to this logical sandbox.
        visit [here ->:ContainerOf:->];
    }

    can collect_installed with Container entry {
        # Track which requirements are physically on this container.
        already_have = False;
        for a in self.audited {
            if a == here.filesystem_label {
                already_have = True;
            }
        }
        if not already_have {
            self.audited = self.audited + [here.filesystem_label];
            for req in [here ->:InstalledOn:->] {
                pkg_name = req.pkg;
                already_recorded = False;
                for f in self.findings {
                    if f == pkg_name {
                        already_recorded = True;
                    }
                }
                if not already_recorded {
                    self.findings = self.findings + [pkg_name];
                }
            }
        }
        visit [-->];
    }

    can summarize with Root entry {
        missing = [];
        for r in self.required {
            already_recorded = False;
            for f in self.findings {
                if f == r {
                    already_recorded = True;
                }
            }
            if not already_recorded {
                missing = missing + [r];
            }
        }
        print(f"observed packages across audited containers: {self.findings}");
        print(f"missing (should include mcp if cache was stale): {missing}");
    }
}

walker EvictionSimulator {
    can start with Root entry {
        visit [->:Manages:->];
    }

    can evict with Sandbox entry {
        # Find the newest generation container and drop the rest.
        containers = [here ->:ContainerOf:->];
        if not containers {
            disengage;
        }
        newest = containers[0];
        for c in containers {
            if c.generation > newest.generation {
                newest = c;
            }
        }
        kept_gen = newest.generation;
        kept_label = newest.filesystem_label;
        for c in containers {
            if c.generation < kept_gen {
                here del ->:ContainerOf:-> c;
                del c;
            }
        }
        print(f"Evicted old containers; keeping generation {kept_gen} ({kept_label})");
        visit [-->];
    }
}

with entry {
    # The manager host (a logical SandboxDependencyManager node attached to root).
    manager_label = "SandboxDependencyManager";
    print(f"Bootstrapping {manager_label}");

    # Logical sandbox: keyed by lifecycle name (the buggy cache key).
    sandbox_label = "vibe-prod-7";
    print(f"Logical sandbox name: {sandbox_label}");
    sb = Sandbox(name=sandbox_label);
