    can audit with Case entry {
        if here.case_id in self.guard {
            return;
        }
        self.guard.append(here.case_id);

        if not here.consented {
            self.findings[here.case_id] = {"status": "REJECTED_UNCONSENTED"};
            return;
        }
        if here.private_beta {
            self.findings[here.case_id] = {"status": "REJECTED_PRIVATE_BETA"};
            return;
        }

        visit [here->:DependsOn:->];
    }

    can synthesize with Result entry {
        self.findings[here.case_id] = {
            "provider": here.provider_name,
            "type_correct": here.type_correct,
            "field_valid": here.field_valid,
            "date_exact": here.date_exact,
            "entity_linked": here.entity_linked,
            "safe_review": here.safe_review,
            "false_update": here.false_update,
            "fallback_used": here.fallback_used,
            "failed": here.failed,
            "latency_ms": here.latency_ms,
            "cost": here.cost,
        };
    }

    def route_case(c: Case, primary: Provider, fallback: Provider) -> None {
        type_ok = not c.ambiguous;
        field_ok = not c.malformed;
        date_ok = not c.ambiguous;
        link_ok = not c.ambiguous;
        safe = c.category == "people" or c.category == "retainer";
        failed = False;
        used_fallback = False;
        provider_name = primary.name;

        timed_out = c.malformed and primary.alive;
        malformed_out = c.malformed;

        if timed_out or malformed_out {
            if fallback.alive {
                provider_name = fallback.name;
                used_fallback = True;
                failed = False;
                field_ok = True;
            } else {
                failed = True;
                field_ok = False;
            }
        }

        result = Result(
            case_id=c.case_id,
            provider_name=provider_name,
            type_correct=type_ok,
            field_valid=field_ok,
            date_exact=date_ok,
            entity_linked=link_ok,
            safe_review=safe,
            false_update=False,
            fallback_used=used_fallback,
            failed=failed,
            latency_ms=primary.timeout_ms if not used_fallback else fallback.timeout_ms,
            cost=primary.cost_per_call if not used_fallback else fallback.cost_per_call,
        );
        c +>:Routed:+> result;
    }
