    counter that drives the ``skin_palette.comp`` dispatch size.
  * ``SkinPool`` owns a ``max_used_slot`` high-water figure and the
    ``pose_dirty`` set, and points at the staging copies via ``HoldsStaging``
    edges.
  * ``SlotOwnsBone`` is a typed edge so a walker can enumerate a slot's
    bones without an adjacency dict.

The ``BoneUploadWalker`` performs the *current* (wasteful) traversal: it
copies every bone of every slot up to ``max_used_slot + 1`` into every
staging copy and tallies the wasted bytes. A second pass shows the
*narrowed* traversal: only slots in ``pose_dirty`` are copied, with each
dirty slot only refreshing the FIF copies whose stamp differs.
"""

node Bone {
    has bone_index: int = 0;
    has px: float = 0.0;
    has py: float = 0.0;
    has pz: float = 0.0;
    has is_identity: bool = False;
}

node Slot {
    has slot_id: int = 0;
    has entity_label: str = "";
    has pose_dirty_this_frame: bool = False;
    # Per-FIF last-written stamp so a single dirty slot refreshes both copies.
    has stamps: list[str] = [];
}

edge SlotOwnsBone {
    has bone_offset: int = 0;
}

edge HoldsStaging {
    has fif_index: int = 0;
}

node StagingBuffer {
    has fif_index: int = 0;
    has label: str = "";
    has last_bone_upload_bytes: int = 0;
}

node SkinPool {
    has pool_label: str = "";
    has max_used_slot: int = 0;
    has pose_dirty: list[int] = [];
    # Bytes counted by the current (wasteful) pass; reset per walker run.
    has full_pass_bytes: int = 0;
    # Bytes counted by the narrowed pass.
    has narrow_pass_bytes: int = 0;
}

walker BoneUploadWalker {
    has fif_labels: list[str] = [];
    has bone_size_bytes: int = 64;
    has bones_per_slot: int = 144;

    can begin with Root entry {
        visit [-->];
    }

    # The wasteful path: ignore pose_dirty, copy every slot up to the
    # high-water mark into every staging buffer. This mirrors
    # upload.rs:238-259.
    can full_pass with SkinPool entry {
        pool = here;
        total_slots = pool.max_used_slot + 1;
        # Whole high-water span, including clean slots and identity padding.
        full_bytes = total_slots * self.bones_per_slot * self.bone_size_bytes;
        pool.full_pass_bytes = full_bytes;
        print(
            f"[FULL] {pool.pool_label}: copying {total_slots} slots "
            f"x {self.bones_per_slot} bones = {full_bytes} B into "
            f"{len(self.fif_labels)} FIF copies"
        );
        visit [-->];
    }

    # The narrowed path: only dirty slots, only FIFs whose stamp differs.
    can narrow_pass with SkinPool entry {
        pool = here;
        dirty = pool.pose_dirty;
        if len(dirty) == 0 {
            pool.narrow_pass_bytes = 0;
            print(f"[NARROW] {pool.pool_label}: streak gate skips upload");
            visit [-->];
        }
        per_slot_bytes = self.bones_per_slot * self.bone_size_bytes;
        narrowed = len(dirty) * per_slot_bytes;
        pool.narrow_pass_bytes = narrowed;
        print(
            f"[NARROW] {pool.pool_label}: copying {len(dirty)} dirty slots "
            f"= {narrowed} B ({dirty})"
        );
        visit [-->];
    }

    # Union ability: a Slot visit stamps every FIF copy so subsequent runs
    # can detect which FIFs still need a refresh.
    can stamp_slot with Slot entry {
        slot = here;
        for fif_label in self.fif_labels {
            slot.stamps = slot.stamps + [f"{fif_label}:frame-{slot.slot_id}"];
        }
        visit [-->];
    }
}

with entry {
    MAX_BONES_PER_MESH = 144;
    BONE_BYTES = 64;

    # A pool whose high-water mark is 260 slots (the issue's example) but
    # whose pose_dirty set has a single entry — one walking NPC.
    pool = SkinPool(
        pool_label="main-rig-pool",
        max_used_slot=260,
        pose_dirty=[17]
    );
    root ++> pool;

    # FIF staging copies; the walker treats them symmetrically.
    fif_a = StagingBuffer(fif_index=0, label="fif-A");
    fif_b = StagingBuffer(fif_index=1, label="fif-B");
    pool +>:HoldsStaging(fif_index=0):+> fif_a;
    pool +>:HoldsStaging(fif_index=1):+> fif_b;

    # Build a few slots. Only slot 17 is dirty; slots up to 260 are clean,
    # but the wasteful pass still copies them all.
    slot_17 = Slot(slot_id=17, entity_label="walking-NPC");
    slot_250 = Slot(slot_id=250, entity_label="high-index-idle");
    pool ++> slot_17;
    pool ++> slot_250;

    # Give each slot its first bone (the 144-multiplier is the
    # ``MAX_BONES_PER_MESH`` constant, not a per-bone node count).
    b0 = Bone(bone_index=0, px=0.0, is_identity=True);
    b1 = Bone(bone_index=1, px=0.0, is_identity=True);
    slot_17 +>:SlotOwnsBone(bone_offset=0):+> b0;
    slot_250 +>:SlotOwnsBone(bone_offset=0):+> b1;

    uploader = BoneUploadWalker(
        fif_labels=["fif-A", "fif-B"],
        bone_size_bytes=BONE_BYTES,
        bones_per_slot=MAX_BONES_PER_MESH
    );

    # Pass 1: the current wasteful traversal.
    pool spawn uploader;
    full_bytes = pool.full_pass_bytes;
    narrow_bytes = pool.narrow_pass_bytes;
    saved = full_bytes - narrow_bytes;
    ratio = full_bytes / narrow_bytes if narrow_bytes > 0 else 0;
    print(
        f"=> wasteful: {full_bytes} B/frame, narrowed: {narrow_bytes} "
        f"B/frame, saved {saved} B ({ratio:.1f}x reduction)"
    );

    # Pass 2: a scene with no dirty slots demonstrates the streak gate.
    still_pool = SkinPool(
        pool_label="idle-pool",
        max_used_slot=260,
        pose_dirty=[]
    );
    root ++> still_pool;
    still_pool spawn BoneUploadWalker(
        fif_labels=["fif-A", "fif-B"],
        bone_size_bytes=BONE_BYTES,
        bones_per_slot=MAX_BONES_PER_MESH
    );
    print(
        f"=> idle-pool full pass still costs {still_pool.full_pass_bytes} "
        f"B; narrow pass = {still_pool.narrow_pass_bytes} B "
        f"({still_pool.full_pass_bytes / max(still_pool.narrow_pass_bytes, 1):.1f}x)"
    );
}

