"""Tests for the bone-world staging upload model.

Each test builds its own SkinPool + Slot graph, spawns BoneUploadWalker,
and asserts on the byte counts the issue's two multipliers are about:
  * full_pass_bytes = (max_used_slot + 1) * 144 * 64   (high-water + 144-multiplier)
  * narrow_pass_bytes = len(pose_dirty) * 144 * 64    (per dirty slot only)
The streak gate (pose_dirty empty) must zero narrow_pass_bytes but leave
full_pass_bytes at the high-water figure.
"""

import io;
import from contextlib { redirect_stdout }

# Per-program constants (mirror main.jac's with entry).
glob MAX_BONES_PER_MESH: int = 144;
glob BONE_BYTES: int = 64;
glob FIF_LABELS: list[str] = ["fif-A", "fif-B"];

test "full_pass copies whole high-water span into FIF copies" {
    root ++> SkinPool(pool_label="t1", max_used_slot=260, pose_dirty=[17]);
    pool = [root -->][?:SkinPool][0];

    buf = io.StringIO();
    with redirect_stdout(buf) {
        pool spawn BoneUploadWalker(
            fif_labels=FIF_LABELS,
            bone_size_bytes=BONE_BYTES,
            bones_per_slot=MAX_BONES_PER_MESH
        );
    }
    out = buf.getvalue();

    # 261 slots * 144 * 64 = 2,406,528 B  (~2.4 MB, the issue's figure).
    expected_full = (260 + 1) * MAX_BONES_PER_MESH * BONE_BYTES;
    assert pool.full_pass_bytes == expected_full, (
        f"full_pass_bytes = {pool.full_pass_bytes}, expected {expected_full}"
    );
    assert pool.full_pass_bytes > 2_400_000, (
        f"expected >2.4 MB high-water cost, got {pool.full_pass_bytes}"
    );
    assert "[FULL]" in out, f"missing FULL marker in: {out}";
    assert "261 slots" in out, f"missing slot count in: {out}";
    assert "2 FIF copies" in out, f"missing FIF count in: {out}";
}

test "narrow_pass ignores pose_dirty, only copies dirty slots" {
    root ++> SkinPool(pool_label="t2", max_used_slot=260, pose_dirty=[17]);
    pool = [root -->][?:SkinPool][0];

    buf = io.StringIO();
    with redirect_stdout(buf) {
        pool spawn BoneUploadWalker(
            fif_labels=FIF_LABELS,
            bone_size_bytes=BONE_BYTES,
            bones_per_slot=MAX_BONES_PER_MESH
        );
    }
    out = buf.getvalue();

    # 1 dirty slot * 144 * 64 = 9,216 B  (the "9 KB of changed data" the
    # issue says is the actual payload).
    expected_narrow = 1 * MAX_BONES_PER_MESH * BONE_BYTES;
    assert pool.narrow_pass_bytes == expected_narrow, (
        f"narrow_pass_bytes = {pool.narrow_pass_bytes}, expected {expected_narrow}"
    );
    assert pool.narrow_pass_bytes == 9216, (
        f"narrowed payload should be 9216 B, got {pool.narrow_pass_bytes}"
    );
    assert "[NARROW]" in out, f"missing NARROW marker in: {out}";
    assert "1 dirty slots" in out, f"missing dirty-count line in: {out}";
}

test "ratio between full and narrow matches issue's worked example" {
    # One walking NPC (slot 17 dirty) in a 260-slot high-water pool.
    root ++> SkinPool(pool_label="t3", max_used_slot=260, pose_dirty=[17]);
    pool = [root -->][?:SkinPool][0];

    buf = io.StringIO();
    with redirect_stdout(buf) {
        pool spawn BoneUploadWalker(
            fif_labels=FIF_LABELS,
            bone_size_bytes=BONE_BYTES,
            bones_per_slot=MAX_BONES_PER_MESH
        );
    }

    # 261 / 1 == 261x reduction; the issue says "9 KB of changed data" vs
    # ~2.4 MB, which is roughly 261x.
    ratio = pool.full_pass_bytes / max(pool.narrow_pass_bytes, 1);
    assert ratio == 261, (
        f"expected 261x reduction, got full={pool.full_pass_bytes} "
        f"narrow={pool.narrow_pass_bytes} ratio={ratio}"
    );
    saved = pool.full_pass_bytes - pool.narrow_pass_bytes;
    assert saved > 2_300_000, (
        f"expected to save >2.3 MB/frame, saved {saved}"
    );
}

test "empty pose_dirty zeroes narrow but full still pays high-water cost" {
    # Streak-gate scenario: nothing animated, full pass still copies all
    # 261 slots because the wasteful path ignores pose_dirty.
    root ++> SkinPool(pool_label="t4", max_used_slot=260, pose_dirty=[]);
    pool = [root -->][?:SkinPool][0];

    buf = io.StringIO();
    with redirect_stdout(buf) {
        pool spawn BoneUploadWalker(
            fif_labels=FIF_LABELS,
            bone_size_bytes=BONE_BYTES,
            bones_per_slot=MAX_BONES_PER_MESH
        );
    }
    out = buf.getvalue();

    assert pool.narrow_pass_bytes == 0, (
        f"streak gate must zero narrow, got {pool.narrow_pass_bytes}"
    );
    assert "streak gate skips upload" in out, (
        f"missing streak-gate message in: {out}"
    );
    # The whole bug: full pass is still ~2.4 MB on a pool with no
    # animated entities at all.
    assert pool.full_pass_bytes > 2_400_000, (
        f"idle full pass still wasted, got {pool.full_pass_bytes}"
    );
    assert pool.full_pass_bytes > pool.narrow_pass_bytes, (
        "full pass must exceed narrow pass even when nothing is dirty"
    );
}

test "stamp_slot appends one entry per FIF label" {
    # The narrowed fix's FIF-stamp mechanism: each FIF copy gets its own
    # stamp string per visit.
    root ++> Slot(slot_id=17, entity_label="walking-NPC");
    slot = [root -->][?:Slot][0];

    buf = io.StringIO();
    with redirect_stdout(buf) {
        slot spawn BoneUploadWalker(
            fif_labels=FIF_LABELS,
            bone_size_bytes=BONE_BYTES,
            bones_per_slot=MAX_BONES_PER_MESH
        );
    }

    assert len(slot.stamps) == len(FIF_LABELS), (
        f"expected one stamp per FIF, got {len(slot.stamps)} "
        f"({slot.stamps})"
    );
    # Both FIF labels must appear; nothing else.
    for fif_label in FIF_LABELS {
        assert any(fif_label in s for s in slot.stamps), (
            f"missing stamp for {fif_label} in {slot.stamps}"
        );
    }
    # Slot nodes must keep their slot_id intact (the stamp uses it).
    assert slot.slot_id == 17, f"slot_id mutated: {slot.slot_id}";
}

