    pile = EvalSlice(name="pile-val", token_count=1000, is_training_distribution=True);
    c0 = Checkpoint(step=1000, seed=0, loss=3.10, lambda_ca=0.92);
    c1 = Checkpoint(step=2000, seed=0, loss=2.70, lambda_ca=0.78);
    c2 = Checkpoint(step=3000, seed=0, loss=2.45, lambda_ca=0.55);
    root ++> pile;
    pile +>:ScoredOn(note="recomputed"):+> c0;
    c0 +>:NextStep(delta_step=1000):+> c1;
    c1 +>:NextStep(delta_step=1000):+> c2;
    res = pile spawn LossCollapser(slice_name="pile-val");
    assert len(res.pairs) == 3, f"expected 3 pairs, got {len(res.pairs)}";
    assert res.pairs[0][0] == 3.10, f"first loss wrong: {res.pairs[0]}";
    assert res.pairs[0][1] == 0.92, f"first lambda wrong: {res.pairs[0]}";
    assert res.pairs[2][0] == 2.45, f"last loss wrong: {res.pairs[2]}";
    assert res.pairs[2][1] == 0.55, f"last lambda wrong: {res.pairs[2]}";
}

