    pile = EvalSlice(name="pile-val", token_count=1000, is_training_distribution=True);
    c0 = Checkpoint(step=1, seed=0, loss=1.0, lambda_ca=2.0);
    c1 = Checkpoint(step=2, seed=0, loss=2.0, lambda_ca=4.0);
    c2 = Checkpoint(step=3, seed=0, loss=3.0, lambda_ca=6.0);
