    pile +>:ScoredOn(note="recomputed"):+> c0;
    c0 +>:NextStep(delta_step=1):+> c1;
    c1 +>:NextStep(delta_step=1):+> c2;
    c2 +>:NextStep(delta_step=0):+> ct;
