import io;
import from contextlib { redirect_stdout }

test "no swap reports hard kill and reserved slack" {
    inst = Instance(name="t3.medium", usable_mib=3700, reserved_mib=2500, swap_mib=0);
    root +>:HostedOn:+> inst;
    buf = io.StringIO();
    with redirect_stdout(buf) { res = root spawn PressureSweep(); }
    out = buf.getvalue();
    assert "[t3.medium]" in out, f"got {out}";
    assert "usable=3700MiB reserved=2500MiB slack=1200MiB" in out, f"got {out}";
    assert "swap=0MiB -> hard-killed" in out, f"got {out}";
}

test "swap changes pressure mode to degraded" {
    inst = Instance(name="t3.medium", usable_mib=3700, reserved_mib=2500, swap_mib=4096);
    root +>:HostedOn:+> inst;
    buf = io.StringIO();
    with redirect_stdout(buf) { res = root spawn PressureSweep(); }
    out = buf.getvalue();
    assert "usable=3700MiB reserved=2500MiB slack=1200MiB" in out, f"got {out}";
    assert "swap=4096MiB -> degraded (swap absorbs)" in out, f"got {out}";
    assert "hard-killed" not in out, f"got {out}";
}

test "typed relationships preserve hosting and blast direction" {
    inst = Instance(name="host", usable_mib=3700, reserved_mib=2500, swap_mib=0);
    scheduler = Task(name="scheduler", memory_mib=900, oom_kills=5);
    api = Task(name="api-server", memory_mib=700, oom_kills=3);
    triggerer = Task(name="triggerer", memory_mib=400, oom_kills=0);

    inst +>:HostedOn:+> scheduler;
    inst +>:HostedOn:+> api;
    inst +>:HostedOn:+> triggerer;
    scheduler +>:Blast(severity=2):+> api;
    scheduler +>:Blast(severity=1):+> triggerer;

    hosted = [inst ->:HostedOn:->];
    blast_targets = [scheduler ->:Blast:->];
    reverse_targets = [api ->:Blast:->];

    assert len(hosted) == 3, f"got {len(hosted)}";
    assert api in blast_targets, f"got {len(blast_targets)}";
    assert triggerer in blast_targets, f"got {len(blast_targets)}";
    assert scheduler not in reverse_targets, f"got {len(reverse_targets)}";
    assert inst.reserved_mib == 2500, f"got {inst.reserved_mib}";
    assert scheduler.oom_kills == 5, f"got {scheduler.oom_kills}";
}

