node ForkedSession {
    has title: str = "";
    has status: str = "idle";
}

node SubagentSession {
    has title: str = "";
    has status: str = "idle";
}

node ChannelThread {
    has title: str = "";
    has status: str = "idle";
}

# A session may also be a "child session" in the runtime ownership
# sense — used by the spawned/contained rows.
node ChildSession {
    has title: str = "";
    has status: str = "idle";
}

# ---- Edge archetypes ----------------------------------------------------

# Transcript provenance: "this session was forked from that session."
edge ForkSource {
    has forked_from_label: str = "";
}

# Runtime ownership / delegation.
edge SpawnedBy {
    has spawned_by_label: str = "";
}

# Channel / thread containment.
edge ChannelChild {
    has channel_label: str = "";
}

