    can start with Root entry {
        visit [-->];
    }

    can render with Session entry {
        print(f"[sidebar] session: {here.title} ({here.status})");
        visit [->:SpawnedBy:->];
        visit [->:ChannelChild:->];
    }

    can render with ForkedSession entry {
        # Forked sessions sit at the top of the section; no ownership
        # edge is followed.
        print(f"[sidebar] forked:  {here.title} ({here.status})");
    }

    can render with SubagentSession entry {
        print(f"[sidebar] subagent:{here.title} ({here.status})");
        visit [->:SpawnedBy:->];
    }

    can render with ChannelThread entry {
        print(f"[sidebar] thread:  {here.title} ({here.status})");
        visit [->:ChannelChild:->];
    }

    can render with ChildSession entry {
        print(f"[sidebar] child:   {here.title} ({here.status})");
        visit [->:SpawnedBy:->];
    }
}

walker LineageProbe {
