"""Regression tests for the smc-watch declared-dependency invalidation gap.

The cheap fingerprint walker only follows Imports + GovernedBy edges, so a
declared dependency's manifest change (along a Depends edge) is invisible to
it, while the DeclaredAudit walker that walks Depends edges does see it.
WatchInvalidator reports a GAP when the cheap walker misses a manifest that
the broader walker sees, marking the admitted cache STALE.
"""

import io;
import from contextlib { redirect_stdout }


def build_graph {
    entry_manifest = Manifest(owner="entry", content="entry-v1");

    m_app = Module(name="app", source="use core; use util;");
    m_core = Module(name="core", source="fn core() {}");
    m_util = Module(name="util", source="fn util() {}");

    dep_logger = DeclaredDep(name="logger", kind="runtime");
    dep_logger_manifest = Manifest(owner="logger", content="logger-v1");

    root +>:GovernedBy:+> entry_manifest;
    root ++> EntryPackage(name="svc");
    root +>:Imports(line=1):+> m_app;
    m_app +>:Imports(line=2):+> m_core;
    m_app +>:Imports(line=3):+> m_util;
    m_app +>:GovernedBy:+> Manifest(owner="app", content="app-v1");
    m_core +>:GovernedBy:+> Manifest(owner="core", content="core-v1");
    m_util +>:GovernedBy:+> Manifest(owner="util", content="util-v1");

    root +>:Depends(kind="runtime"):+> dep_logger;
    dep_logger +>:GovernedBy:+> dep_logger_manifest;

    return entry_manifest; }


def fresh_root {
    # Each test gets its own empty root so tests don't see each other's state.
    root_dummy = root;
    return root_dummy; }


test "cheap fingerprint only follows Imports edges from root" {
    build_graph();
    cheap = CheapFingerprint();
    root spawn cheap;
    # The cheap walker must see the 3 source-imported modules.
    assert "app" in cheap.visited, f"expected app in {cheap.visited}";
    assert "core" in cheap.visited, f"expected core in {cheap.visited}";
    assert "util" in cheap.visited, f"expected util in {cheap.visited}";
    # ...but it must NOT see the declared dependency "logger", which is only
    # reachable via a Depends edge.
    assert "logger" not in cheap.visited, (
        f"cheap walker leaked into Depends graph: {cheap.visited}"
    );
    # Fingerprint body must reference every imported module and its manifest.
    assert "M[app]" in cheap.fp, f"missing M[app] in fp {cheap.fp!r}";
    assert "M[core]" in cheap.fp, f"missing M[core] in fp {cheap.fp!r}";
    assert "M[util]" in cheap.fp, f"missing M[util] in fp {cheap.fp!r}";
    assert "G[app=app-v1]" in cheap.fp, f"missing app manifest in fp";
    assert "G[core=core-v1]" in cheap.fp, f"missing core manifest in fp";
    assert "G[util=util-v1]" in cheap.fp, f"missing util manifest in fp";
}


test "cheap fingerprint misses declared-dependency manifests" {
    build_graph();
    cheap = CheapFingerprint();
    root spawn cheap;
    # logger's governing manifest is connected only via Depends -> GovernedBy;
    # the cheap walker never visits logger, so it cannot fold logger's manifest.
    assert "logger" not in cheap.manifests_seen, (
        f"logger manifest leaked into cheap fp: {cheap.manifests_seen}"
    );
    # But the imported modules' manifests do show up.
    assert "app" in cheap.manifests_seen, (
        f"app manifest missing from cheap fp: {cheap.manifests_seen}"
    );
    assert "core" in cheap.manifests_seen, (
        f"core manifest missing from cheap fp: {cheap.manifests_seen}"
    );
}


test "declared audit walks Depends edges and folds their manifests" {
    build_graph();
    audit = DeclaredAudit();
    root spawn audit;
    # DeclaredAudit is rooted on root and follows Depends edges. logger is a
    # direct declared dep of root, so it must be visited and its manifest
    # must be folded into the surface.
    assert "logger" in audit.declared_seen, (
        f"logger not in declared surface: {audit.declared_seen}"
    );
    assert "G[logger=logger-v1]" in audit.surface, (
        f"logger manifest not folded: {audit.surface!r}"
    );
}


test "WatchInvalidator flags STALE when cheap fp misses declared manifests" {
    build_graph();
    buf = io.StringIO();
    res: WatchInvalidator = None;
    with redirect_stdout(buf) {
        res = root spawn WatchInvalidator();
    }
    out = buf.getvalue();
    # The watcher must observe the gap and mark the cache STALE because
    # logger's manifest is reachable through Depends but not through Imports.
    assert res.admitted_cache == "STALE", (
        f"expected STALE admission cache, got {res.admitted_cache}"
    );
    assert "[GAP]" in out, f"expected GAP marker in output, got: {out}";
    assert "logger" in out, f"expected logger in output, got: {out}";
    # The cheap fp itself must NOT contain a logger marker -- that's the bug.
    assert "logger" not in res.fp, (
        f"cheap fp unexpectedly contains logger: {res.fp!r}"
    );
}


test "WatchInvalidator reports OK when declared surface is empty" {
    # Build a graph with NO Depends edges from root. In that case the declared
    # surface is empty, so the cheap fingerprint trivially covers everything
    # that exists and the admitted cache stays VALID.
    entry_manifest = Manifest(owner="entry", content="entry-v1");
    m_app = Module(name="app", source="use core;");
    m_core = Module(name="core", source="fn core() {}");
    root +>:GovernedBy:+> entry_manifest;
    root +>:Imports(line=1):+> m_app;
    m_app +>:Imports(line=2):+> m_core;
    m_app +>:GovernedBy:+> Manifest(owner="app", content="app-v1");
    m_core +>:GovernedBy:+> Manifest(owner="core", content="core-v1");

    buf = io.StringIO();
    res: WatchInvalidator = None;
    with redirect_stdout(buf) {
        res = root spawn WatchInvalidator();
    }
    out = buf.getvalue();
    assert res.admitted_cache == "VALID", (
        f"expected VALID, got {res.admitted_cache}"
    );
    assert "[OK]" in out, f"expected OK marker, got: {out}";
    assert "[GAP]" not in out, f"unexpected GAP marker: {out}";
}

