    rxn +>:InputEdge(stoichiometry=1, curated=False):+> eFlat;
    rxn +>:InputEdge(stoichiometry=1, curated=False):+> mHigh;
    rxn +>:OutputEdge(stoichiometry=1, curated=False):+> eFlat;

