    has label: str = "";
    has mu_count: int = 0;
}

node Cut {
    has label: str = "";
    has eliminated: bool = False;
}

node Consumer {
    has label: str = "";
}

node LabelJoin {
    has label: str = "";
    has forwarded: bool = False;
}

edge Rewritten {
    has kind: str = "";
    has swapped_uniq: int = 0;
