import io;
import from contextlib { redirect_stdout }

test "NormalizePass flags Mu-under-Cut redex when Producer has mu_count" {
    p_mu = Producer(label="p_mu", mu_count=2);
    cut_a = Cut(label="mu/cut#A", eliminated=False);
    root +>:Rewritten(kind="subst", swapped_uniq=7):+> p_mu;
    p_mu +>:Rewritten(kind="cut-open"):+> cut_a;
    assert len([root-->]) == 1, f"root should have one Rewritten child, got {len([root-->])}";
    assert p_mu in [root ->:Rewritten:->], f"p_mu not linked from root via Rewritten";
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn NormalizePass();
    }
    out = buf.getvalue();
    assert res.redex_found, f"expected redex_found True, got {res.redex_found}";
    assert "p_mu" in res.visited, f"producer not visited: {res.visited}";
    assert "mu/cut#A" in res.visited, f"cut not visited: {res.visited}";
    assert "[normalize] walking redex rooted at p_mu" in out, f"missing redex log: {out}";
    assert "[normalize] cut mu/cut#A still pending" in out, f"missing pending cut log: {out}";
}

test "NormalizePass walks substitution-rewritten chain without redex when mu_count is zero" {
    p = Producer(label="done", mu_count=0);
    cut_a = Cut(label="mu/cut#B", eliminated=True);
    consumer = Consumer(label="downstream");
    label_join = LabelJoin(label="LJ", forwarded=False);
    root +>:Rewritten(kind="subst", swapped_uniq=5):+> p;
    p +>:Rewritten(kind="cut-open"):+> cut_a;
    cut_a +>:Rewritten(kind="forward"):+> consumer;
    consumer +>:Rewritten(kind="join"):+> label_join;
    res = root spawn NormalizePass();
    assert not res.redex_found, f"expected no redex, got redex_found={res.redex_found}";
    assert len(res.visited) == 4, f"expected 4 visited nodes, got {len(res.visited)}: {res.visited}";
    assert res.visited == ["done", "mu/cut#B", "downstream", "LJ"], f"wrong visit order: {res.visited}";
}

test "ResidualCheck records reachable Mu producers as bad sites" {
    p_bad = Producer(label="residual_mu", mu_count=1);
    cut_ok = Cut(label="eliminated_cut", eliminated=True);
    root +>:Rewritten(kind="subst", swapped_uniq=3):+> p_bad;
    p_bad +>:Rewritten(kind="cut-open"):+> cut_ok;
    res = root spawn ResidualCheck();
    assert len(res.bad_sites) == 1, f"expected one bad site, got {res.bad_sites}";
    assert res.bad_sites[0] == "residual_mu", f"wrong bad site label: {res.bad_sites}";
}

test "ResidualCheck reports no residual Mu-under-Cut when chain is clean" {
    p = Producer(label="clean", mu_count=0);
    cut_b = Cut(label="mu/cut#B", eliminated=True);
    consumer = Consumer(label="downstream");
    root +>:Rewritten(kind="subst", swapped_uniq=0):+> p;
    p +>:Rewritten(kind="cut-open"):+> cut_b;
    cut_b +>:Rewritten(kind="forward"):+> consumer;
    res = root spawn ResidualCheck();
    assert len(res.bad_sites) == 0, f"expected no residual producers, got {res.bad_sites}";
}

test "ResidualCheck flags pending cuts and forwarding label joins" {
    cut_pending = Cut(label="mu/cut#X", eliminated=False);
    label_join = LabelJoin(label="LJ", forwarded=True);
    root +>:Rewritten(kind="forward"):+> cut_pending;
    cut_pending +>:Rewritten(kind="join"):+> label_join;
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn ResidualCheck();
    }
    out = buf.getvalue();
    assert len(res.bad_sites) == 0, f"no mu producer on this graph: {res.bad_sites}";
    assert "[residual] cut mu/cut#X not eliminated" in out, f"missing cut residual log: {out}";
    assert "[residual] label-join LJ still forwarding" in out, f"missing join residual log: {out}";
}

