    w = Librarian();
    assert w.shelf_label == "Main", f"expected default shelf_label 'Main', got {w.shelf_label}";
}

# --- Test 3: Walker traverses shelf and prints IN/OUT status ---
test "librarian prints every book with correct IN/OUT status" {
    root ++> Book(title="Dune", year=1965)
        ++> Book(title="Neuromancer", year=1984)
        ++> Book(title="Circe", year=2018, available=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Librarian(shelf_label="Sci-Fi & Fantasy");
    }
    out = buf.getvalue();

    # Header line announces the shelf label passed in.
    assert "Sci-Fi & Fantasy" in out, f"missing shelf label in output: {out!r}";

    # Each book must appear with its title and year, and the right IN/OUT tag.
    assert "[IN] Dune (1965)" in out, f"missing Dune IN line: {out!r}";
    assert "[IN] Neuromancer (1984)" in out, f"missing Neuromancer IN line: {out!r}";
    assert "[OUT] Circe (2018)" in out, f"missing Circe OUT line: {out!r}";

    # Sanity: every IN/OUT tag corresponds to a real book (no extras invented).
    assert out.count("[IN]") == 2, f"expected 2 [IN] lines, got {out.count('[IN]')} in {out!r}";
    assert out.count("[OUT]") == 1, f"expected 1 [OUT] line, got {out.count('[OUT]')} in {out!r}";
}

