"""Tests for the hiking-trail Hiker walker."""

import io;
import from contextlib { redirect_stdout }

# ---------------------------------------------------------------------------
# Test 1: the demo graph shape the program's entry block constructs, and that
# spawning a Hiker on root produces exactly the documented trail output.
# ---------------------------------------------------------------------------
test "demo trail traversal prints every stop and completes" {
    root ++> Trailhead()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    assert "Departing trailhead" in out, f"missing depart line: {out!r}";
    assert "Stop 1" in out, f"missing Stop 1: {out!r}";
    assert "Stop 2" in out, f"missing Stop 2: {out!r}";
    assert "Stop 3" in out, f"missing Stop 3: {out!r}";
    assert "passed 3 waypoints" in out, f"missing completion count: {out!r}";
    assert "Trail complete" in out, f"missing completion line: {out!r}";

    # Stop numbers must appear in increasing order in the printed output.
    s1 = out.index("Stop 1");
    s2 = out.index("Stop 2");
    s3 = out.index("Stop 3");
    assert s1 < s2 < s3, f"stops out of order: indices {s1},{s2},{s3} in {out!r}";
}

# ---------------------------------------------------------------------------
# Test 2: the walker counts stops via the `stops` field, independent of any
# output capture, so we know it really walked through the waypoints.
# ---------------------------------------------------------------------------
test "hiker stops field equals number of waypoints visited" {
    root ++> Trailhead()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    assert res.stops == 2, f"expected 2 stops, got {res.stops}";
}

# ---------------------------------------------------------------------------
# Test 3: zero-waypoint trail — Hiker still completes cleanly and reports 0.
# ---------------------------------------------------------------------------
test "trail with no waypoints completes with zero stops" {
    root ++> Trailhead()
        ++> Summit();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    assert "Departing trailhead" in out, f"missing depart line: {out!r}";
    assert "passed 0 waypoints" in out, f"missing zero count: {out!r}";
    assert res.stops == 0, f"expected 0 stops, got {res.stops}";
}

# ---------------------------------------------------------------------------
# Test 4: a longer trail — count and printed stops must match the chain length.
# ---------------------------------------------------------------------------
test "longer trail counts and prints every waypoint in order" {
    root ++> Trailhead()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    assert res.stops == 5, f"expected 5 stops, got {res.stops}";
    for i in range(1, 6) {
        assert f"Stop {i}" in out, f"missing Stop {i}: {out!r}";
    }
    assert "passed 5 waypoints" in out, f"missing completion count: {out!r}";
}

