    assert "Stop 3" in out, f"missing Stop 3 in: {out!r}";
    assert "Trail complete" in out, f"missing completion line in: {out!r}";
    assert "passed 3 waypoints" in out, f"waypoint count missing in: {out!r}";
    assert "Summit" in out, f"summit name missing in: {out!r}";
    assert res.waypoint_count == 3, f"expected 3 waypoints counted, got {res.waypoint_count}";
}

test "hiker reports the trailhead name before walking" {
    root ++> Trailhead()
        ++> Waypoint()
        ++> Summit();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    assert "Departing from Trailhead" in out, f"missing departure line in: {out!r}";
    assert out.index("Departing") < out.index("Stop 1"), "departure must precede first stop";
}

test "hiker traverses the full Trailhead -> Waypoints -> Summit chain" {
    a = Waypoint();
    b = Waypoint();
    c = Waypoint();
    s = Summit();

    root ++> Trailhead() ++> a ++> b ++> c ++> s;

    # Verify the chain was built with the expected number of forward edges from root.
    forward_chain = [root-->];
    assert len(forward_chain) == 1, f"expected exactly one child of root, got {len(forward_chain)}";

