import io;
import from contextlib { redirect_stdout }

test "hiker walks short trail and completes when waypoints reached" {
    root ++> Trailhead()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker(target_waypoints=3);
    }
    out = buf.getvalue();

    # The hiker should have visited trailhead + 3 waypoints + summit = 5 stops,
    # passed exactly 3 waypoints (the target), and print the completion line.
    assert "Stop 1: trailhead" in out, f"missing trailhead stop: {out}";
    assert "Stop 5: summit" in out, f"missing summit stop: {out}";
    assert "passed 3 of 3 waypoints in 5 stops" in out, f"missing completion line: {out}";
    assert res.stop_number == 5, f"expected 5 stops, got {res.stop_number}";
    assert res.waypoints_passed == 3, f"expected 3 waypoints passed, got {res.waypoints_passed}";
}

test "hiker prints each waypoint stop in order" {
    root ++> Trailhead()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker(target_waypoints=4);
    }
    out = buf.getvalue();

    # All four waypoints should be announced with incrementing counts.
    assert "waypoint 1" in out, f"missing waypoint 1: {out}";
    assert "waypoint 2" in out, f"missing waypoint 2: {out}";
    assert "waypoint 3" in out, f"missing waypoint 3: {out}";
    assert "waypoint 4" in out, f"missing waypoint 4: {out}";
    assert res.waypoints_passed == 4, f"expected 4 waypoints, got {res.waypoints_passed}";
}

test "hiker completes only when target waypoints reached" {
    # Three waypoints, target is 3 — completion should fire and disengage.
    root ++> Trailhead()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker(target_waypoints=3);
    }
    out = buf.getvalue();

    # Completion line includes both passed and target counts.
    assert "passed 3 of 3 waypoints" in out, f"expected completion line, got: {out}";
    # Summit is the last visited node before disengage.
    assert out.strip().splitlines()[-1].startswith("Trail complete"), f"final line not completion: {out}";
}

test "trail graph shape is a single chain trailhead to summit" {
    rt = root ++> Trailhead()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit();

    th = [root -->][?:Trailhead];
    assert len(th) == 1, f"expected 1 Trailhead from root, got {len(th)}";

    # Trailhead should link to exactly one Waypoint (the chain head).
    th_node = th[0];
    first_wps = [th_node -->];
    assert len(first_wps) == 1, f"trailhead should link to one node, got {len(first_wps)}";

    # Walk forward from the trailhead and count nodes until no further links.
    count = 0;
    cur = th_node;
    while len([cur -->]) > 0 {
        nxt = [cur -->][0];
        count += 1;
        cur = nxt;
    }
    # 1 waypoint link + 1 summit link = 2 forward edges from trailhead
    # before exhausting the chain via summit's outgoing empty list.
    assert count == 3, f"expected to walk 3 links (2 wp + 1 summit), walked {count}";
}

