import from contextlib { redirect_stdout }

test "hiker counts every waypoint on the trail" {
    root ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    assert "Stop 1" in out, f"missing Stop 1 in: {out}";
    assert "Stop 2" in out, f"missing Stop 2 in: {out}";
    assert "Stop 3" in out, f"missing Stop 3 in: {out}";
    assert "Stop 4" in out, f"missing Stop 4 in: {out}";
    assert res.stop_count == 4, f"expected stop_count 4, got {res.stop_count}";
}

test "hiker prints completion line after the final waypoint" {
    root ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    assert "Trail complete" in out, f"missing completion line in: {out}";
    assert "passed 3 waypoints" in out, f"expected 'passed 3 waypoints' in: {out}";
    assert res.stop_count == 3, f"expected stop_count 3, got {res.stop_count}";
}

test "hiker disengages on a single-waypoint trail" {
    root ++> Waypoint();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    assert "Stop 1" in out, f"missing Stop 1 in: {out}";
    assert "Trail complete" in out, f"missing completion line in: {out}";
    assert "passed 1 waypoints" in out, f"expected 'passed 1 waypoints' in: {out}";
    assert res.stop_count == 1, f"expected stop_count 1, got {res.stop_count}";
}

test "hiker follows edges in chain order" {
    w1 = Waypoint();
    w2 = Waypoint();
    w3 = Waypoint();
    root ++> w1 ++> w2 ++> w3;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Hiker();
    }
    out = buf.getvalue();

    assert res.stop_count == 3, f"expected stop_count 3, got {res.stop_count}";

    # The first stop printed must correspond to w1 (root's only outgoing waypoint)
    first_waypoint = [root -->][?:Waypoint][0];
    assert first_waypoint == w1, "first waypoint from root should be w1";

    # Confirm the chain is exactly length 3 of Waypoint nodes
    wp_count = 0;
    cur = first_waypoint;
    while cur is not None {
        wp_count += 1;
        nxts = [cur -->];
        if len(nxts) == 0 {
            cur = None;
        } else {
            cur = nxts[0];
        }
    }
    assert wp_count == 3, f"chain should have 3 waypoints, found {wp_count}";
}

