"""Tests for the hiking trail program: counts waypoints and prints stop numbers."""

import io;
import from contextlib { redirect_stdout }


def run_hiker(trail_root) {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        trail_root spawn Hiker();
    }
    return buf.getvalue().splitlines();
}

test "zero waypoints — hiker goes straight from trailhead to summit" {
    root ++> Trailhead() ++> Summit();
    lines = run_hiker(root);
    assert lines[0] == "Starting at Trailhead", f"first line: {lines}";
    assert lines[-1] == "Trail complete — passed 0 waypoints to Summit", f"completion line: {lines}";
    assert len(lines) == 2, f"expected 2 lines, got {len(lines)}: {lines}";
}

test "three waypoints — each stop is numbered and completion reports count" {
    root ++> Trailhead()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit();
    lines = run_hiker(root);
    assert lines[0] == "Starting at Trailhead", f"first line: {lines}";
    assert lines[1] == "Stop 1", f"second line: {lines}";
    assert lines[2] == "Stop 2", f"third line: {lines}";
    assert lines[3] == "Stop 3", f"fourth line: {lines}";
    assert lines[4] == "Trail complete — passed 3 waypoints to Summit", f"completion: {lines}";
    assert len(lines) == 5, f"expected 5 lines, got {len(lines)}: {lines}";
}

test "one waypoint — counts exactly one stop and disengages at summit" {
    root ++> Trailhead() ++> Waypoint() ++> Summit();
    lines = run_hiker(root);
    assert "Stop 1" in lines, f"missing Stop 1 in {lines}";
    assert "Trail complete — passed 1 waypoints to Summit" in lines, f"missing completion in {lines}";
    assert "Stop 2" not in "\n".join(lines), f"unexpected Stop 2 in {lines}";
}

test "stop count is exactly the number of waypoints in the chain" {
    root ++> Trailhead()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Waypoint()
        ++> Summit();
    lines = run_hiker(root);
    completion = [l for l in lines if l.startswith("Trail complete")][0];
    assert "passed 5 waypoints" in completion, f"expected 5 waypoints, got: {completion}";
    stop_lines = [l for l in lines if l.startswith("Stop ")];
    assert len(stop_lines) == 5, f"expected 5 stop lines, got {len(stop_lines)}: {stop_lines}";
    assert stop_lines == ["Stop 1", "Stop 2", "Stop 3", "Stop 4", "Stop 5"], f"wrong order/values: {stop_lines}";
}

test "trailhead and summit titles are surfaced in output" {
    root ++> Trailhead(title="Eagle Creek") ++> Waypoint() ++> Summit(title="Mount Hood");
    lines = run_hiker(root);
    joined = "\n".join(lines);
    assert "Starting at Eagle Creek" in joined, f"missing trailhead title: {joined}";
    assert "Mount Hood" in joined, f"missing summit title: {joined}";
    assert "passed 1 waypoints" in joined, f"missing count: {joined}";
}

