    assert "Stop 2" in out, f"missing Stop 2: {out}";
    assert "Stop 3" in out, f"missing Stop 3: {out}";
    assert out.index("Stop 1") < out.index("Stop 2"), f"stops out of order: {out}";
    assert out.index("Stop 2") < out.index("Stop 3"), f"stops out of order: {out}";
