# --- Test 2: Scout collects all leg prices and tracks peak correctly ---
test "scout reports all leg prices and finds peak" {
    jfk = Airport(code="JFK");
    lax = Airport(code="LAX");
    ord = Airport(code="ORD");
    bos = Airport(code="BOS");
    root ++> jfk;

    leg1 = FlightLeg(ticket_price=450.0, origin_code="JFK", dest_code="LAX");
    jfk +>:leg1:+> lax;
    leg2 = FlightLeg(ticket_price=320.0, origin_code="LAX", dest_code="ORD");
    lax +>:leg2:+> ord;
    leg3 = FlightLeg(ticket_price=580.0, origin_code="ORD", dest_code="BOS");
    ord +>:leg3:+> bos;

    scout = Scout();
    root spawn scout;

    assert scout.peak_fare == 580.0, f"peak should be 580.0, got {scout.peak_fare}";
    assert len(scout.fare_report) == 3, f"expected 3 prices reported, got {len(scout.fare_report)}";
    assert 450.0 in scout.fare_report, "JFK->LAX price missing from report";
    assert 320.0 in scout.fare_report, "LAX->ORD price missing from report";
    assert 580.0 in scout.fare_report, "ORD->BOS price missing from report";
}

# --- Test 3: fare_fraction returns 0.0 when peak is non-positive (fail-closed) ---
test "fare_fraction returns zero for non-positive peak" {
    jfk = Airport(code="JFK");
    lax = Airport(code="LAX");
    root ++> jfk;
    jfk +>:FlightLeg(ticket_price=500.0, origin_code="JFK", dest_code="LAX"):+> lax;

