        share = leg.fare_fraction(peak);
        print(f"{share:.2%}");
    }
    out = buf.getvalue().strip();
    assert out == "100.00%", f"expected 100.00%, got {out}";
}

# --- Test 5: Scout disengages on revisiting an airport (seen-tracking) ---
test "scout disengages on previously seen airport code" {
    # Two airports that share a code shouldn't cause double reporting
    a1 = Airport(code="AAA");
    a2 = Airport(code="AAA");  # same code - should be treated as already seen
    root ++> a1;
    a1 +>:FlightLeg(ticket_price=100.0, origin_code="AAA", dest_code="BBB"):+> a2;

    scout = Scout();
    root spawn scout;

    # Disengage on second visit means only the first leg is reported
    assert len(scout.fare_report) == 1, f"expected 1 price report, got {len(scout.fare_report)}";
    assert scout.fare_report[0] == 100.0, f"expected 100.0, got {scout.fare_report[0]}";
}

