import io;
import from contextlib { redirect_stdout }

test "Scout collects all five leg prices into fare_report" {
    root ++> Airport(code="JFK");
    root ++> Airport(code="LAX");
    root ++> Airport(code="ORD");
    root ++> Airport(code="BOS");

    jfk = [root -->][0];
    lax = [root -->][1];
    ord_node = [root -->][2];
    bos = [root -->][3];

    leg1 = FlightLeg(ticket_price=450.0, origin_code="JFK", dest_code="LAX");
    leg2 = FlightLeg(ticket_price=320.0, origin_code="LAX", dest_code="ORD");
    leg3 = FlightLeg(ticket_price=580.0, origin_code="ORD", dest_code="BOS");
    leg4 = FlightLeg(ticket_price=275.0, origin_code="BOS", dest_code="JFK");
    leg5 = FlightLeg(ticket_price=510.0, origin_code="JFK", dest_code="ORD");

    jfk +>:leg1:+> lax;
    lax +>:leg2:+> ord_node;
    ord_node +>:leg3:+> bos;
    bos +>:leg4:+> jfk;
    jfk +>:leg5:+> ord_node;

    res = root spawn Scout();
    assert len(res.fare_report) == 5, f"expected 5 prices, got {len(res.fare_report)}";
    assert sorted(res.fare_report) == sorted([450.0, 320.0, 580.0, 275.0, 510.0]),
        f"price set mismatch: {res.fare_report}";
}

test "Scout reports the maximum fare as peak_fare" {
    jfk = Airport(code="JFK");
    lax = Airport(code="LAX");
    ord_node = Airport(code="ORD");
    root ++> jfk;
    root ++> lax;
    root ++> ord_node;

    jfk +>:FlightLeg(ticket_price=100.0, origin_code="JFK", dest_code="LAX"):+> lax;
    lax +>:FlightLeg(ticket_price=999.99, origin_code="LAX", dest_code="ORD"):+> ord_node;
    jfk +>:FlightLeg(ticket_price=250.0, origin_code="JFK", dest_code="ORD"):+> ord_node;

    res = root spawn Scout();
    assert res.peak_fare == 999.99, f"expected peak 999.99, got {res.peak_fare}";
}

