    leg_lax_ord = FlightLeg(ticket_price=320.0, origin_code="LAX", dest_code="ORD");
    leg_ord_bos = FlightLeg(ticket_price=580.0, origin_code="ORD", dest_code="BOS");
    leg_bos_jfk = FlightLeg(ticket_price=275.0, origin_code="BOS", dest_code="JFK");
    leg_jfk_ord = FlightLeg(ticket_price=510.0, origin_code="JFK", dest_code="ORD");

    jfk +>:leg_jfk_lax:+> lax;
    lax +>:leg_lax_ord:+> ord_node;
