        scout2 = root spawn Scout();
    }
    assert len(scout2.reports) == 4, f"expected 4 reported prices, got {len(scout2.reports)}";
    assert 410.0 in scout2.reports, f"expected 410.0 among reported prices, got {scout2.reports}";
    assert 180.0 in scout2.reports, f"expected 180.0 among reported prices, got {scout2.reports}";
}

test "fare_fraction returns 1.0 for the peak leg and ratio for others" {
    sfo = Airport(code="SFO", title="San Francisco");
    jfk = Airport(code="JFK", title="New York");
    sfo +>: (peak_leg := FlightLeg(price=500.0)):+> jfk;

    # peak leg against the top fare
    assert peak_leg.fare_fraction(500.0) == 1.0, f"peak leg fraction should be 1.0, got {peak_leg.fare_fraction(500.0)}";

    # a cheaper leg against the same top fare
    cheap = FlightLeg(price=125.0);
    frac = cheap.fare_fraction(500.0);
    assert abs(frac - 0.25) < 1e-9, f"expected 0.25 fraction, got {frac}";

    # exact reported prices from program: 320 / 410
    leg320 = FlightLeg(price=320.0);
    assert abs(leg320.fare_fraction(410.0) - (320.0 / 410.0)) < 1e-9, "320/410 ratio mismatch";
}

test "fare_fraction is fail-closed: returns 0.0 for non-positive top fare" {
    leg = FlightLeg(price=200.0);
    assert leg.fare_fraction(0.0) == 0.0, "zero top fare should yield 0.0, not division error";
    assert leg.fare_fraction(-50.0) == 0.0, "negative top fare should yield 0.0, not division error";

    # default top_fare parameter (i.e., no top) should also be 0.0 -> 0.0
    assert leg.fare_fraction(0.0) == 0.0, "default top_fare must not raise";
}

test "scout disengages on duplicate airport code" {
    a1 = Airport(code="AAA", title="A1");
    a2 = Airport(code="AAA", title="A2-dup");
    a3 = Airport(code="BBB", title="B");

    a1 +>: (leg_ab := FlightLeg(price=100.0)):+> a2;
    a2 +>: (leg_bc := FlightLeg(price=200.0)):+> a3;

    root ++> a1;

    scout = root spawn Scout();
    # From a1 (code AAA) we visit a2 via leg_ab -> report 100.0, append AAA.
    # Then a2's code is also AAA -> disengage. We should NOT have visited a3.
    assert scout.reports == [100.0], f"expected only [100.0] before disengage, got {scout.reports}";
    assert "AAA" in scout.seen_codes, f"AAA should be in seen_codes, got {scout.seen_codes}";
    assert "BBB" not in scout.seen_codes, f"BBB should NOT be visited due to disengage, got {scout.seen_codes}";
}

test "edge directions form the SFO->LAX->DEN->JFK->SFO ring exactly" {
    sfo = Airport(code="SFO");
    lax = Airport(code="LAX");
    den = Airport(code="DEN");
    jfk = Airport(code="JFK");

    sfo +>: (leg_sl := FlightLeg(price=320.0)):+> lax;
    lax +>: (leg_ld := FlightLeg(price=180.0)):+> den;
    den +>: (leg_dj := FlightLeg(price=410.0)):+> jfk;
    jfk +>: (leg_js := FlightLeg(price=290.0)):+> sfo;

    # Outgoing FlightLeg edges from each airport
    assert len([sfo ->:FlightLeg:->]) == 1, "SFO should have exactly 1 outgoing leg";
    assert len([lax ->:FlightLeg:->]) == 1, "LAX should have exactly 1 outgoing leg";
    assert len([den ->:FlightLeg:->]) == 1, "DEN should have exactly 1 outgoing leg";
    assert len([jfk ->:FlightLeg:->]) == 1, "JFK should have exactly 1 outgoing leg";

    # SFO's outgoing leg must point to LAX
    out_from_sfo = [sfo ->:FlightLeg:->];
    assert out_from_sfo[0].code == "LAX", f"SFO's leg should reach LAX, got {out_from_sfo[0].code}";

    # DEN's outgoing leg must point to JFK
    out_from_den = [den ->:FlightLeg:->];
    assert out_from_den[0].code == "JFK", f"DEN's leg should reach JFK, got {out_from_den[0].code}";

