    assert leg_ld.price == 180.0, f"leg_ld price mismatch: {leg_ld.price}";
    assert leg_dj.price == 410.0, f"leg_dj price mismatch: {leg_dj.price}";
    assert leg_js.price == 290.0, f"leg_js price mismatch: {leg_js.price}";
}

