    assert isinstance(lobby, Floor), f"root's child should be a Floor, got {type(lobby)}";
    assert lobby.floor_number == 1, f"first floor should be #1, got {lobby.floor_number}";
    assert lobby.department == "Lobby", f"first floor should be Lobby, got {lobby.department!r}";

    # Walk the chain manually and verify floor numbers are 1..4 in order.
    chain = [];
    cur = lobby;
    while cur is not None {
        chain.append(cur);
        nxts = [cur-->];
        cur = nxts[0] if len(nxts) > 0 else None;
    }
    assert len(chain) == 4, f"chain should have 4 floors, got {len(chain)}";
    assert [f.floor_number for f in chain] == [1, 2, 3, 4], f"unexpected floor numbers: {[f.floor_number for f in chain]}";
    assert [f.department for f in chain] == ["Lobby", "Finance", "Engineering", "Executive Suite"], f"unexpected departments: {[f.department for f in chain]}";

    # Sanity: spawning the guide actually walks all four floors (each presents a stop).
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn TourGuide(tour_name="Express");
    }
    out = buf.getvalue();
    assert all(f"Stop {f.floor_number}: {f.department}" in out for f in chain), f"not every floor announced: {out!r}";
}

