    assert "Stop 1: Lobby" in out, f"missing stop 1: {out}";
    assert "Stop 2: Marketing" in out, f"missing stop 2: {out}";
    assert "Stop 3: Engineering" in out, f"missing stop 3: {out}";

    # Ordering: welcome, then stops 1, 2, 3 in order.
    w = out.index("Welcome to the Corporate Tower Tour");
    s1 = out.index("Stop 1: Lobby");
    s2 = out.index("Stop 2: Marketing");
    s3 = out.index("Stop 3: Engineering");
    assert w < s1 < s2 < s3, f"wrong ordering: w={w} s1={s1} s2={s2} s3={s3}";
}

test "graph shape: root reaches three floors in chain order" {
    root ++> Floor(floor_num=1, department="Lobby")
        ++> Floor(floor_num=2, department="Marketing")
        ++> Floor(floor_num=3, department="Engineering");

    # Chain: only the first floor is a direct child of root.
    assert len([root-->]) == 1, f"root should have exactly 1 direct child, got {len([root-->])}";

    # Walk forward through the chain and collect every Floor node.
    first = [root-->][0];
    floors = [first];
    cur = first;
    children = [cur-->];
    while len(children) > 0 {
        cur = children[0];
        floors.append(cur);
        children = [cur-->];
    }

    assert len(floors) == 3, f"should reach 3 floor nodes, got {len(floors)}";
    assert floors[0].floor_num == 1 and floors[0].department == "Lobby", f"first floor wrong: {floors[0]}";
    assert floors[1].floor_num == 2 and floors[1].department == "Marketing", f"second floor wrong: {floors[1]}";
