"""Tests for the OrderAuditor walker: skip-invalid vs halt-on-fraud."""

import io;
import from contextlib { redirect_stdout }

# ---------- Test 1: a single valid order prints AUDIT ----------
test "single valid order produces AUDIT line" {
    root ++> Order(amount=42.0, valid=True, fraud=False);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();
    assert "[AUDIT] approved order amount=42.0" in out, f"missing AUDIT marker: {out!r}";
    assert "[SKIP]" not in out, f"valid order should not skip: {out!r}";
    assert "[HALT]" not in out, f"valid order should not halt: {out!r}";
}

# ---------- Test 2: invalid order is SKIPPED, walk continues ----------
test "invalid order is skipped but walk continues to later orders" {
    root ++> Order(amount=100.0, valid=True, fraud=False)
        ++> Order(amount=50.0, valid=False, fraud=False)
        ++> Order(amount=200.0, valid=True, fraud=False);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();
    assert "[AUDIT] approved order amount=100.0" in out, f"missing first AUDIT: {out!r}";
    assert "[SKIP] invalid order amount=50.0" in out, f"missing SKIP line: {out!r}";
    assert "[AUDIT] approved order amount=200.0" in out, f"walk must continue past invalid: {out!r}";
    assert "[HALT]" not in out, f"no fraud => no halt: {out!r}";
}

# ---------- Test 3: fraud order HALTs; orders after it never seen ----------
test "fraud order disengages and prevents visiting later orders" {
    root ++> Order(amount=100.0, valid=True, fraud=False)
        ++> Order(amount=999.0, valid=True, fraud=True)
        ++> Order(amount=10.0, valid=True, fraud=False);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();
    assert "[AUDIT] approved order amount=100.0" in out, f"pre-fraud order must be audited: {out!r}";
    assert "[HALT] fraud flagged on order amount=999.0" in out, f"missing HALT marker: {out!r}";
    # the post-fraud order must NOT appear because disengage halts the walk
    assert "amount=10.0" not in out, f"walk must halt on fraud, but later order was visited: {out!r}";
    # also: no SKIP since no invalid order exists
    assert "[SKIP]" not in out, f"unexpected SKIP: {out!r}";
}

# ---------- Test 4: fraud precedes invalid => invalid never printed, walk stops at fraud ----------
test "fraud halts walk even when invalid orders exist later in the chain" {
    root ++> Order(amount=999.0, valid=True, fraud=True)
        ++> Order(amount=50.0, valid=False, fraud=False)
        ++> Order(amount=10.0, valid=True, fraud=False);
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();
    assert "[HALT] fraud flagged on order amount=999.0" in out, f"missing HALT: {out!r}";
    assert "[SKIP]" not in out, f"invalid order must not be visited after halt: {out!r}";
    assert "amount=10.0" not in out, f"trailing order must not be visited: {out!r}";
}

# ---------- Test 5: graph shape sanity + multiple valid orders all audited ----------
test "all-valid chain audits every order, graph wiring is correct" {
    a = Order(amount=10.0, valid=True, fraud=False);
    b = Order(amount=20.0, valid=True, fraud=False);
    c = Order(amount=30.0, valid=True, fraud=False);
    root ++> a ++> b ++> c;

    # sanity-check the graph the test built (3 orders linked from root)
    n_orders = len([root-->]);
    assert n_orders == 1, f"root should have exactly one first Order child, got {n_orders}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();
    assert "[AUDIT] approved order amount=10.0" in out, f"missing 10.0 audit: {out!r}";
    assert "[AUDIT] approved order amount=20.0" in out, f"missing 20.0 audit: {out!r}";
    assert "[AUDIT] approved order amount=30.0" in out, f"missing 30.0 audit: {out!r}";
    assert "[SKIP]" not in out, f"no SKIP expected: {out!r}";
    assert "[HALT]" not in out, f"no HALT expected: {out!r}";
    # exactly three audit lines should be printed
    n_audits = out.count("[AUDIT]");
    assert n_audits == 3, f"expected 3 AUDIT lines, got {n_audits} in {out!r}";
}

