"""Test annex for the order auditor program."""

import io;
import from contextlib { redirect_stdout }

test "happy path: all valid non-fraud orders are audited" {
    root ++> Order(amount=10.0, valid=True, fraud=False)
        ++> Order(amount=20.0, valid=True, fraud=False)
        ++> Order(amount=30.0, valid=True, fraud=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = OrderAuditor();
        root spawn auditor;
    }
    out = buf.getvalue();

    assert "Order audit started" in out, f"missing start line: {out}";
    assert "[AUDIT] amount=10.0 valid — approved" in out, f"missing first audit: {out}";
    assert "[AUDIT] amount=20.0 valid — approved" in out, f"missing second audit: {out}";
    assert "[AUDIT] amount=30.0 valid — approved" in out, f"missing third audit: {out}";
    assert "[SKIP]" not in out, f"unexpected skip: {out}";
    assert "[HALT]" not in out, f"unexpected halt: {out}";
}

test "invalid orders are skipped but audit continues to later orders" {
    root ++> Order(amount=15.0, valid=True, fraud=False)
        ++> Order(amount=25.0, valid=False, fraud=False)
        ++> Order(amount=35.0, valid=True, fraud=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        auditor = OrderAuditor();
        res = root spawn auditor;
    }
    out = buf.getvalue();

    assert "[AUDIT] amount=15.0 valid — approved" in out, f"missing first audit: {out}";
    assert "[SKIP] amount=25.0 invalid — continuing" in out, f"missing skip: {out}";
    assert "[AUDIT] amount=35.0 valid — approved" in out, f"audit did not continue past skip: {out}";
    assert "[HALT]" not in out, f"unexpected halt: {out}";

    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        auditor2 = OrderAuditor();
        res2 = root spawn auditor2;
    }
    assert res2.skipped == 1, f"expected 1 skip, got {res2.skipped}";
    assert res2.audited == 2, f"expected 2 audited, got {res2.audited}";
}

test "fraud flag halts the walk on the spot, later orders not audited" {
    root ++> Order(amount=50.0, valid=True, fraud=False)
        ++> Order(amount=75.0, valid=True, fraud=False)
        ++> Order(amount=999.0, valid=True, fraud=True)
        ++> Order(amount=88.0, valid=True, fraud=False);

