    assert "[AUDIT] amount=50.0 valid — approved" in out, f"missing first audit: {out}";
    assert "[AUDIT] amount=75.0 valid — approved" in out, f"missing second audit: {out}";
    assert "[HALT] amount=999.0 flagged for fraud — stopping audit" in out, f"missing halt: {out}";

    assert "[AUDIT] amount=88.0" not in out, f"walk did not stop on fraud: {out}";
    assert "[SKIP] amount=88.0" not in out, f"walk did not stop on fraud: {out}";

    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
