"""Tests for OrderAuditor: skip invalid (continue) vs disengage on fraud."""

import io;
import from contextlib { redirect_stdout }

test "valid orders are audited and walk continues through them" {
    root ++> Order(amount=120, valid=True, fraud=False)
        ++> Order(amount=200, valid=True, fraud=False)
        ++> Order(amount=75, valid=True, fraud=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[AUDIT] valid order amount=120" in out, f"missing AUDIT 120: {out}";
    assert "[AUDIT] valid order amount=200" in out, f"missing AUDIT 200: {out}";
    assert "[AUDIT] valid order amount=75" in out, f"missing AUDIT 75: {out}";
    assert out.count("[AUDIT]") == 3, f"expected 3 audit lines, got: {out}";
    assert "[HALT]" not in out, f"no halt expected: {out}";
    assert "[SKIP]" not in out, f"no skip expected: {out}";
}

test "invalid order is skipped and traversal continues to later orders" {
    root ++> Order(amount=120, valid=True, fraud=False)
        ++> Order(amount=50, valid=False, fraud=False)
        ++> Order(amount=200, valid=True, fraud=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn OrderAuditor();
    }
    out = buf.getvalue();

    assert "[AUDIT] valid order amount=120" in out, f"missing AUDIT 120: {out}";
    assert "[SKIP] invalid order amount=50" in out, f"missing SKIP 50: {out}";
    assert "[AUDIT] valid order amount=200" in out, f"missing AUDIT 200 (walk should continue past skip): {out}";
    assert out.count("[AUDIT]") == 2, f"expected 2 audit lines: {out}";
    assert out.count("[SKIP]") == 1, f"expected 1 skip line: {out}";
    assert "[HALT]" not in out, f"no halt expected: {out}";
}

test "fraud order halts walk immediately and later orders are not visited" {
    root ++> Order(amount=120, valid=True, fraud=False)
        ++> Order(amount=999, valid=True, fraud=True)
        ++> Order(amount=75, valid=True, fraud=False);

