test "date night pass only shows 4.5+ restaurants" {
    root ++> Restaurant(name="Le Bernardin", cuisine="French", rating=4.8)
        ++> Restaurant(name="Sushi Nakazawa", cuisine="Japanese", rating=4.6)
        ++> Restaurant(name="Joe's Pizza", cuisine="Italian", rating=3.8)
        ++> Restaurant(name="Taco Truck", cuisine="Mexican", rating=3.9)
        ++> Restaurant(name="The Corner Cafe", cuisine="American", rating=3.2);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn RestaurantFinder(min_rating=4.5, pass_label="Date night");
    }
    out = buf.getvalue();

    assert "=== Date night (rating >= 4.5) ===" in out, f"missing date night header: {out}";
    assert "Le Bernardin" in out, f"expected Le Bernardin (4.8): {out}";
    assert "Sushi Nakazawa" in out, f"expected Sushi Nakazawa (4.6): {out}";
    assert "Joe's Pizza" not in out, f"Joe's Pizza (3.8) should be excluded: {out}";
    assert "Taco Truck" not in out, f"Taco Truck (3.9) should be excluded: {out}";
    assert "The Corner Cafe" not in out, f"Corner Cafe (3.2) should be excluded: {out}";
}

test "casual lunch pass shows 3.5+ but excludes below threshold" {
    root ++> Restaurant(name="Le Bernardin", cuisine="French", rating=4.8)
        ++> Restaurant(name="Sushi Nakazawa", cuisine="Japanese", rating=4.6)
        ++> Restaurant(name="Joe's Pizza", cuisine="Italian", rating=3.8)
        ++> Restaurant(name="Taco Truck", cuisine="Mexican", rating=3.9)
        ++> Restaurant(name="The Corner Cafe", cuisine="American", rating=3.2);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn RestaurantFinder(min_rating=3.5, pass_label="Casual lunch");
    }
    out = buf.getvalue();

    assert "=== Casual lunch (rating >= 3.5) ===" in out, f"missing casual lunch header: {out}";
    assert "Le Bernardin" in out, f"expected Le Bernardin (4.8): {out}";
    assert "Sushi Nakazawa" in out, f"expected Sushi Nakazawa (4.6): {out}";
    assert "Joe's Pizza" in out, f"expected Joe's Pizza (3.8): {out}";
    assert "Taco Truck" in out, f"expected Taco Truck (3.9): {out}";
    assert "The Corner Cafe" not in out, f"Corner Cafe (3.2) below 3.5 must be excluded: {out}";
}

test "min_rating is taken as a spawn parameter, not hardcoded" {
    root ++> Restaurant(name="A", cuisine="X", rating=2.0)
        ++> Restaurant(name="B", cuisine="Y", rating=5.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn RestaurantFinder(min_rating=4.0, pass_label="Strict");
    }
    out = buf.getvalue();

    assert "=== Strict (rating >= 4.0) ===" in out, f"header must reflect spawned min_rating: {out}";
    assert "B" in out and "A" not in out, f"only B (5.0) should match at threshold 4.0: {out}";

    buf2 = io.StringIO();
    with redirect_stdout(buf2) {
        root spawn RestaurantFinder(min_rating=1.0, pass_label="Loose");
    }
    out2 = buf2.getvalue();

    assert "=== Loose (rating >= 1.0) ===" in out2, f"second spawn must use its own label/threshold: {out2}";
    assert "A" in out2 and "B" in out2, f"both A and B must appear at threshold 1.0: {out2}";
}

test "each printed restaurant line includes name, cuisine and rating" {
    root ++> Restaurant(name="Sushi Nakazawa", cuisine="Japanese", rating=4.6)
        ++> Restaurant(name="Le Bernardin", cuisine="French", rating=4.8);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn RestaurantFinder(min_rating=4.0, pass_label="Check format");
    }
    out = buf.getvalue();

    assert "Sushi Nakazawa | Japanese | 4.6" in out, f"missing formatted Sushi line: {out}";
    assert "Le Bernardin | French | 4.8" in out, f"missing formatted Bernardin line: {out}";
}

test "no restaurant meets threshold yields only the header" {
    root ++> Restaurant(name="Diner", cuisine="American", rating=2.5)
        ++> Restaurant(name="Cart", cuisine="Hot dog", rating=1.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn RestaurantFinder(min_rating=4.5, pass_label="Empty pass");
    }
    out = buf.getvalue();

    assert "=== Empty pass (rating >= 4.5) ===" in out, f"header must still print even with no matches: {out}";
    assert "Diner" not in out, f"Diner must not appear: {out}";
    assert "Cart" not in out, f"Cart must not appear: {out}";
    lines = [l for l in out.split("\n") if l.strip() != ""];
    assert len(lines) == 1, f"expected only the header line, got: {out}";
}

