def build_graph() -> Root {
    r = root;
    r ++> Restaurant(name="Le Petit Bistro", cuisine="French", rating=4.8)
       ++> Restaurant(name="Taco Haven", cuisine="Mexican", rating=3.9)
       ++> Restaurant(name="Sushi Zen", cuisine="Japanese", rating=4.6)
       ++> Restaurant(name="Burger Barn", cuisine="American", rating=3.2)
       ++> Restaurant(name="Thai Garden", cuisine="Thai", rating=4.1);
