    with redirect_stdout(buf) {
        res = r spawn Finder(min_rating=4.5, occasion="Date Night");
    }
    out = buf.getvalue();
    assert "Date Night" in out, f"missing occasion header: {out}";
    assert "rating >= 4.5" in out, f"missing threshold header: {out}";
    assert "Le Petit Bistro" in out, f"expected Le Petit Bistro (4.8): {out}";
    assert "Sushi Zen" in out, f"expected Sushi Zen (4.6): {out}";
    assert "Taco Haven" not in out, f"Taco Haven (3.9) should be excluded: {out}";
    assert "Burger Barn" not in out, f"Burger Barn (3.2) should be excluded: {out}";
    assert "Thai Garden" not in out, f"Thai Garden (4.1) should be excluded: {out}";
    assert out.count("MATCH:") == 2, f"expected exactly 2 matches, got: {out}";
}

