"""Tests for the restaurant recommender: RestaurantFinder filters by spawn-time min_rating."""

import io;
import from contextlib { redirect_stdout }

test "date night pass at 4.5+ prints only high-rated restaurants" {
    root ++> Restaurant(name="Le Petit Bistro", cuisine="French", rating=4.8)
        ++> Restaurant(name="Tony's Pizza", cuisine="Italian", rating=3.8)
        ++> Restaurant(name="Sushi Haven", cuisine="Japanese", rating=4.6)
        ++> Restaurant(name="Quick Bites", cuisine="American", rating=3.2)
        ++> Restaurant(name="Garden Grill", cuisine="Mediterranean", rating=4.2);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn RestaurantFinder(min_rating=4.5, pass_label="Date night");
    }
    out = buf.getvalue();

    assert "--- Date night (min rating 4.5+) ---" in out, f"missing header: {out}";
    assert "[MATCH] Le Petit Bistro (French) rating=4.8" in out, f"missing Le Petit Bistro: {out}";
    assert "[MATCH] Sushi Haven (Japanese) rating=4.6" in out, f"missing Sushi Haven: {out}";
    assert "[MATCH] Tony's Pizza" not in out, f"Tony's Pizza should be excluded: {out}";
    assert "[MATCH] Quick Bites" not in out, f"Quick Bites should be excluded: {out}";
    assert "[MATCH] Garden Grill" not in out, f"Garden Grill (4.2) should be excluded: {out}";
}

test "casual lunch pass at 3.5+ prints a broader set including mid-rated" {
    root ++> Restaurant(name="Le Petit Bistro", cuisine="French", rating=4.8)
        ++> Restaurant(name="Tony's Pizza", cuisine="Italian", rating=3.8)
        ++> Restaurant(name="Sushi Haven", cuisine="Japanese", rating=4.6)
        ++> Restaurant(name="Quick Bites", cuisine="American", rating=3.2)
        ++> Restaurant(name="Garden Grill", cuisine="Mediterranean", rating=4.2);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn RestaurantFinder(min_rating=3.5, pass_label="Casual lunch");
    }
    out = buf.getvalue();

    assert "--- Casual lunch (min rating 3.5+) ---" in out, f"missing header: {out}";
    assert "[MATCH] Le Petit Bistro (French) rating=4.8" in out, f"missing Le Petit Bistro: {out}";
    assert "[MATCH] Tony's Pizza (Italian) rating=3.8" in out, f"missing Tony's Pizza: {out}";
    assert "[MATCH] Sushi Haven (Japanese) rating=4.6" in out, f"missing Sushi Haven: {out}";
    assert "[MATCH] Garden Grill (Mediterranean) rating=4.2" in out, f"missing Garden Grill: {out}";
    assert "[MATCH] Quick Bites" not in out, f"Quick Bites (3.2) should be excluded: {out}";
}

test "two successive spawns on the same graph produce independent filtered outputs" {
    root ++> Restaurant(name="Le Petit Bistro", cuisine="French", rating=4.8)
        ++> Restaurant(name="Tony's Pizza", cuisine="Italian", rating=3.8)
        ++> Restaurant(name="Sushi Haven", cuisine="Japanese", rating=4.6)
        ++> Restaurant(name="Quick Bites", cuisine="American", rating=3.2)
        ++> Restaurant(name="Garden Grill", cuisine="Mediterranean", rating=4.2);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn RestaurantFinder(min_rating=4.5, pass_label="Date night");
        root spawn RestaurantFinder(min_rating=3.5, pass_label="Casual lunch");
    }
    out = buf.getvalue();

    # Date night header and matches appear, and casual lunch header and matches appear.
    assert "--- Date night (min rating 4.5+) ---" in out, f"missing Date night header: {out}";
    assert "--- Casual lunch (min rating 3.5+) ---" in out, f"missing Casual lunch header: {out}";

    date_idx = out.find("--- Date night");
    casual_idx = out.find("--- Casual lunch");
    assert date_idx >= 0 and casual_idx > date_idx, f"order wrong: {out}";

    # Date night segment: Tony's (3.8) must not appear before Casual lunch header.
    date_segment = out[date_idx:casual_idx];
    assert "[MATCH] Tony's Pizza" not in date_segment, f"Tony's leaked into Date night: {date_segment}";
    assert "[MATCH] Quick Bites" not in date_segment, f"Quick Bites leaked into Date night: {date_segment}";

    # Casual lunch segment contains all >=3.5 except Quick Bites.
    casual_segment = out[casual_idx:];
    assert "[MATCH] Le Petit Bistro" in casual_segment, f"missing Le Petit: {casual_segment}";
    assert "[MATCH] Tony's Pizza" in casual_segment, f"missing Tony's: {casual_segment}";
    assert "[MATCH] Sushi Haven" in casual_segment, f"missing Sushi Haven: {casual_segment}";
    assert "[MATCH] Garden Grill" in casual_segment, f"missing Garden Grill: {casual_segment}";
    assert "[MATCH] Quick Bites" not in casual_segment, f"Quick Bites should be excluded: {casual_segment}";
}

test "boundary ratings are inclusive: equal-to min_rating counts as a match" {
    root ++> Restaurant(name="Exact", cuisine="X", rating=4.5)
        ++> Restaurant(name="JustBelow", cuisine="X", rating=4.499999)
        ++> Restaurant(name="WayAbove", cuisine="X", rating=5.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn RestaurantFinder(min_rating=4.5, pass_label="Boundary");
    }
    out = buf.getvalue();

    assert "[MATCH] Exact (X) rating=4.5" in out, f"exact-match must be included: {out}";
    assert "[MATCH] WayAbove (X) rating=5.0" in out, f"above must be included: {out}";
    assert "[MATCH] JustBelow" not in out, f"just-below must be excluded: {out}";
}

test "min_rating=0.0 acts as no filter and prints every restaurant" {
    root ++> Restaurant(name="A", cuisine="X", rating=0.0)
        ++> Restaurant(name="B", cuisine="Y", rating=2.5)
        ++> Restaurant(name="C", cuisine="Z", rating=5.0);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn RestaurantFinder(min_rating=0.0, pass_label="All");
    }
    out = buf.getvalue();

    assert "--- All (min rating 0.0+) ---" in out, f"missing header: {out}";
    assert "[MATCH] A (X) rating=0.0" in out, f"missing A: {out}";
    assert "[MATCH] B (Y) rating=2.5" in out, f"missing B: {out}";
    assert "[MATCH] C (Z) rating=5.0" in out, f"missing C: {out}";
}

