"""Tests for the restaurant recommender: spawn-time rating filter."""

import io;
import from contextlib { redirect_stdout }

test "date night pass only includes 4.5+ restaurants" {
    root ++> Restaurant(name="Le Petit Bistro", cuisine="French", rating=4.8)
        ++> Restaurant(name="Sushi Zen", cuisine="Japanese", rating=4.6)
        ++> Restaurant(name="Pizza Palace", cuisine="Italian", rating=3.9)
        ++> Restaurant(name="Taco Town", cuisine="Mexican", rating=3.7)
        ++> Restaurant(name="Burger Barn", cuisine="American", rating=3.2);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn RestaurantFinder(min_rating=4.5, pass_label="Date night");
    }
    out = buf.getvalue();

    # Header reflects both spawn-time args.
    assert "Date night" in out, f"missing pass label in header: {out}";
    assert "4.5" in out, f"missing min rating in header: {out}";

    # Only the two highest-rated restaurants should match.
    assert "Le Petit Bistro" in out, f"expected Le Petit Bistro (4.8) to match: {out}";
    assert "Sushi Zen" in out, f"expected Sushi Zen (4.6) to match: {out}";

    # Strictly below 4.5 must NOT appear.
    assert "Pizza Palace" not in out, f"Pizza Palace (3.9) must be excluded at min 4.5: {out}";
    assert "Taco Town" not in out, f"Taco Town (3.7) must be excluded at min 4.5: {out}";
    assert "Burger Barn" not in out, f"Burger Barn (3.2) must be excluded at min 4.5: {out}";

    # Walker should have visited all five restaurants regardless of filter
    # (inspect always advances), so reports/logged hits == 2.
    hits = [ln for ln in out.splitlines() if ln.startswith("  * ")];
    assert len(hits) == 2, f"expected 2 matches at min 4.5, got {len(hits)}: {out}";

    # Sanity: spawn returns the walker instance with our spawn-time fields.
    assert res.min_rating == 4.5, f"walker min_rating not propagated, got {res.min_rating}";
    assert res.pass_label == "Date night", f"walker pass_label not propagated, got {res.pass_label}";
}

test "casual lunch pass includes 3.5+ but excludes 3.2" {
    root ++> Restaurant(name="Le Petit Bistro", cuisine="French", rating=4.8)
        ++> Restaurant(name="Sushi Zen", cuisine="Japanese", rating=4.6)
        ++> Restaurant(name="Pizza Palace", cuisine="Italian", rating=3.9)
        ++> Restaurant(name="Taco Town", cuisine="Mexican", rating=3.7)
        ++> Restaurant(name="Burger Barn", cuisine="American", rating=3.2);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn RestaurantFinder(min_rating=3.5, pass_label="Casual lunch");
    }
    out = buf.getvalue();

    # Header uses the casual-lunch label and 3.5 threshold.
    assert "Casual lunch" in out, f"missing pass label in header: {out}";
    assert "3.5" in out, f"missing min rating in header: {out}";

    # All four restaurants at >= 3.5 should match.
    assert "Le Petit Bistro" in out, f"Le Petit Bistro (4.8) should match: {out}";
    assert "Sushi Zen" in out, f"Sushi Zen (4.6) should match: {out}";
    assert "Pizza Palace" in out, f"Pizza Palace (3.9) should match: {out}";
    assert "Taco Town" in out, f"Taco Town (3.7) should match: {out}";

    # 3.2 must be excluded.
    assert "Burger Barn" not in out, f"Burger Barn (3.2) must be excluded at min 3.5: {out}";

    hits = [ln for ln in out.splitlines() if ln.startswith("  * ")];
    assert len(hits) == 4, f"expected 4 matches at min 3.5, got {len(hits)}: {out}";
}

test "boundary rating exactly at threshold is included" {
    # Restaurant at exactly 4.0 should pass a 4.0 filter (>=).
    root ++> Restaurant(name="Edge Cafe", cuisine="Fusion", rating=4.0)
        ++> Restaurant(name="Below Edge", cuisine="Diner", rating=3.99);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn RestaurantFinder(min_rating=4.0, pass_label="Boundary");
    }
