    assert "Edge Cafe" in out, f"restaurant exactly at threshold must be included: {out}";
    assert "Below Edge" not in out, f"restaurant just below threshold must be excluded: {out}";
}

test "two spawns from same root do not interfere" {
    root ++> Restaurant(name="Le Petit Bistro", cuisine="French", rating=4.8)
        ++> Restaurant(name="Sushi Zen", cuisine="Japanese", rating=4.6)
        ++> Restaurant(name="Pizza Palace", cuisine="Italian", rating=3.9)
        ++> Restaurant(name="Taco Town", cuisine="Mexican", rating=3.7)
        ++> Restaurant(name="Burger Barn", cuisine="American", rating=3.2);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn RestaurantFinder(min_rating=4.5, pass_label="Date night");
        root spawn RestaurantFinder(min_rating=3.5, pass_label="Casual lunch");
    }
    out = buf.getvalue();

    # Both headers appear, in spawn order.
    date_idx = out.find("Date night");
    casual_idx = out.find("Casual lunch");
    assert date_idx != -1, f"missing Date night header: {out}";
    assert casual_idx != -1, f"missing Casual lunch header: {out}";
    assert date_idx < casual_idx, f"first spawn header should precede second: {out}";

    # Combined output must include every restaurant matched by either pass,
    # but never Burger Barn (below 3.5).
    assert "Le Petit Bistro" in out;
    assert "Sushi Zen" in out;
    assert "Pizza Palace" in out;
    assert "Taco Town" in out;
    assert "Burger Barn" not in out, f"Burger Barn (3.2) excluded from both passes: {out}";

    # Across both passes: 2 + 4 = 6 hits total.
    hits = [ln for ln in out.splitlines() if ln.startswith("  * ")];
    assert len(hits) == 6, f"expected 6 combined matches, got {len(hits)}: {out}";
}

