import io;
import from contextlib { redirect_stdout }

# Build a fresh dining graph for each test to exercise the Finder walker
# with different minimum-rating thresholds via spawn parameters.

test "date night pass finds high-rated restaurants" {
    root ++> Restaurant(name="Le Bistro", cuisine="French", rating=4.7)
        ++> Restaurant(name="Taco Town", cuisine="Mexican", rating=3.8)
        ++> Restaurant(name="Sushi Zen", cuisine="Japanese", rating=4.6)
        ++> Restaurant(name="Burger Barn", cuisine="American", rating=3.2);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Finder(min_rating=4.5, pass_label="Date Night");
    }
    out = buf.getvalue();

    # Header echoes the spawn-parameterized threshold and label.
    assert "Date Night" in out, f"missing label in output: {out}";
    assert "4.5" in out, f"missing min_rating echo: {out}";
    assert "===" in out, f"missing section banner: {out}";

    # Only the >= 4.5 restaurants should be listed.
    assert "Le Bistro" in out, f"expected Le Bistro (4.7) in: {out}";
    assert "Sushi Zen" in out, f"expected Sushi Zen (4.6) in: {out}";
    assert "French" in out, f"expected cuisine line: {out}";
    assert "Japanese" in out, f"expected cuisine line: {out}";

    # Below-threshold restaurants must NOT appear.
    assert "Taco Town" not in out, f"Taco Town (3.8) should be excluded: {out}";
    assert "Burger Barn" not in out, f"Burger Barn (3.2) should be excluded: {out}";
}

test "casual lunch pass finds a broader set" {
    root ++> Restaurant(name="Le Bistro", cuisine="French", rating=4.7)
        ++> Restaurant(name="Taco Town", cuisine="Mexican", rating=3.8)
        ++> Restaurant(name="Sushi Zen", cuisine="Japanese", rating=4.6)
        ++> Restaurant(name="Burger Barn", cuisine="American", rating=3.2);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Finder(min_rating=3.5, pass_label="Casual Lunch");
    }
    out = buf.getvalue();

    assert "Casual Lunch" in out, f"missing label in output: {out}";
    assert "3.5" in out, f"missing min_rating echo: {out}";

    # All restaurants with rating >= 3.5 should be listed.
    assert "Le Bistro" in out, f"expected Le Bistro: {out}";
    assert "Taco Town" in out, f"expected Taco Town: {out}";
    assert "Sushi Zen" in out, f"expected Sushi Zen: {out}";

    # Burger Barn (3.2) is below 3.5 and must not appear.
    assert "Burger Barn" not in out, f"Burger Barn (3.2) should be excluded: {out}";
}

test "spawn parameter changes threshold independently per pass" {
    root ++> Restaurant(name="Le Bistro", cuisine="French", rating=4.7)
        ++> Restaurant(name="Taco Town", cuisine="Mexican", rating=3.8)
        ++> Restaurant(name="Sushi Zen", cuisine="Japanese", rating=4.6)
        ++> Restaurant(name="Burger Barn", cuisine="American", rating=3.2);

    # Run both passes back-to-back and capture combined output.
    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn Finder(min_rating=4.5, pass_label="Date Night");
        root spawn Finder(min_rating=3.5, pass_label="Casual Lunch");
    }
    out = buf.getvalue();

    # Both banners present, in spawn order.
    pos_date = out.find("Date Night");
    pos_casual = out.find("Casual Lunch");
    assert pos_date != -1, f"missing Date Night banner: {out}";
    assert pos_casual != -1, f"missing Casual Lunch banner: {out}";
    assert pos_date < pos_casual, f"Date Night should run first: {out}";

    # Taco Town appears in Casual Lunch but not in Date Night.
    assert "Taco Town" in out, f"Taco Town must appear in Casual Lunch: {out}";
    # Burger Barn is excluded from both passes.
    assert "Burger Barn" not in out, f"Burger Barn below all thresholds: {out}";

    # The strict pass has at most as many `*` match lines as the loose pass.
    stars_date = out.split("Date Night", 1)[1].split("Casual Lunch", 1)[0].count("*");
    stars_casual = out.split("Casual Lunch", 1)[1].count("*");
    assert stars_date >= 1, f"Date Night must list >=1 restaurant: {out}";
    assert stars_casual >= 2, f"Casual Lunch must list >=2 restaurants: {out}";
    assert stars_date <= stars_casual, (
        f"strict pass ({stars_date}) should list <= loose pass ({stars_casual})"
    );
}

test "rating boundary is inclusive at the threshold" {
    # A restaurant sitting exactly at the minimum rating must still match.
    root ++> Restaurant(name="Edge Case", cuisine="Fusion", rating=3.5)
        ++> Restaurant(name="Just Below", cuisine="Diner", rating=3.4);

    buf = io.StringIO();
    with redirect_stdout(buf) {
