"""Tests for the alumni mentorship network finder."""

import io;
import from contextlib { redirect_stdout }

test "finds mentees since given year only" {
    root ++> Alumni(name="Alice", graduation_year=2010);
    root ++> Alumni(name="Bob", graduation_year=2014);
    root ++> Alumni(name="Carol", graduation_year=2016);
    root ++> Alumni(name="Dave", graduation_year=2019);

    alice = [root -->][0];
    bob = [root -->][1];
    carol = [root -->][2];
    dave = [root -->][3];

    alice +>:Mentor(since=2018):+> bob;
    alice +>:Mentor(since=2021):+> carol;
    bob +>:Mentor(since=2022):+> dave;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn MentorshipFinder(min_year=2020);
    }
    out = buf.getvalue();

    assert "Dave" in out, f"expected Dave (since 2022) in output, got: {out}";
    assert "Carol" in out, f"expected Carol (since 2021) in output, got: {out}";
    assert "Bob" not in out, f"Bob (since 2018) must be excluded when min_year=2020, got: {out}";
