    state_post_recovery +>:PeerLink:+> primary;
    state_post_recovery +>:PeerLink:+> joiner_a;
    state_post_recovery +>:PeerLink:+> joiner_b;
    state_steady +>:PeerLink:+> primary;
    state_steady +>:PeerLink:+> joiner_a;
    state_steady +>:PeerLink:+> joiner_b;

    return [primary, joiner_a, joiner_b, state_mid_clone, state_post_recovery, state_steady];
}

test "transient no peers during full_cluster_crash is tolerated" {
    root ++> ClusterState(label="mid-clone", peers_online=0, full_cluster_crash=True);
    state = [root -->][0];
    state +>:PeerLink:+> Member(name="mysql-0", role="primary", donating=True);
    state +>:PeerLink:+> Member(name="mysql-1", role="secondary", donating=False);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn StartupProbe();
    }
    out = buf.getvalue();

    assert res.failures == 0, f"probe should NOT count transient as failure, got failures={res.failures}";
    assert len(res.killed) == 0, f"no members should be killed during recovery, got {res.killed}";
    assert res.tolerated == 1, f"probe should tolerate the transient state once, got {res.tolerated}";
    assert "[WAIT]" in out, f"expected WAIT marker in output: {out}";
    assert "exit(1)" not in out, f"bootstrap must not exit(1) under recovery marker: {out}";
    assert "protecting clone donor" in out, f"donor protection message missing: {out}";
