test "transient no peers WITHOUT recovery marker kills members" {
    root ++> ClusterState(label="stranded", peers_online=0, full_cluster_crash=False);
    state = [root -->][0];
    state +>:PeerLink:+> Member(name="mysql-0", role="primary", donating=True);
    state +>:PeerLink:+> Member(name="mysql-1", role="secondary", donating=False);
    state +>:PeerLink:+> Member(name="mysql-2", role="secondary", donating=False);

