    assert len(res.killed) == 3, f"all 3 members must be SIGTERM'd, killed={res.killed}";
    assert "mysql-0" in res.killed and "mysql-1" in res.killed and "mysql-2" in res.killed,
        f"every member should be in killed list: {res.killed}";
    assert "[FATAL]" in out, f"FATAL marker expected without recovery bypass: {out}";
    assert "kubelet SIGTERM mysql-0" in out, f"primary kill line missing: {out}";
    assert "donor=True" in out, f"donor status should be reported on kill: {out}";
