    root ++> ClusterState(label="steady", peers_online=3, full_cluster_crash=False);
    state = [root -->][0];
    state +>:PeerLink:+> Member(name="mysql-0", role="primary", donating=False);
    state +>:PeerLink:+> Member(name="mysql-1", role="secondary", donating=False);
    state +>:PeerLink:+> Member(name="mysql-2", role="secondary", donating=False);

