    }
    out = buf.getvalue();

    assert res.failures == 0, f"healthy cluster must not increment failures: {res.failures}";
    assert res.tolerated == 0, f"healthy cluster must not be tolerated: {res.tolerated}";
    assert len(res.killed) == 0, f"no kills when peers reachable: {res.killed}";
    assert "[OK] steady" in out, f"OK marker missing on healthy state: {out}";
    assert "3 peers reachable" in out, f"peer count not reported: {out}";
