test "walker traverses multiple states and aggregates outcomes" {
    (primary, joiner_a, joiner_b, state_mid_clone, state_post_recovery, state_steady) = build_cluster();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn StartupProbe();
    }
    out = buf.getvalue();

    # mid-clone: peers=0, full_cluster_crash=True -> tolerated (1)
    # post-recovery & steady: peers=3 -> OK each (no failures, no tolerance)
    assert res.tolerated == 1, f"only the mid-clone state should be tolerated, got {res.tolerated}";
    assert res.failures == 0, f"no failures expected across full walk, got {res.failures}";
    assert len(res.killed) == 0, f"recovery marker must protect every member across all visited states: {res.killed}";

