test "loop behavior - repeated transient during recovery never accumulates failures" {
    root ++> ClusterState(label="mid-clone", peers_online=0, full_cluster_crash=True);
    state = [root -->][0];
    state +>:PeerLink:+> Member(name="mysql-0", role="primary", donating=True);
