}

node HqlCondition {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has kind: str = "ast";
    has field_name: str = "";
    has operator: str = "";
    has literal: str = "";
    has count_value: int = 0;
}

node HqlFact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has fact_kind: str = "";
    has ownership_kind: str = "";
    has lossy: bool = False;
}

edge RuleCondition {
    has position: int = 0;
}

edge ConditionChild {
    has position: int = 0;
}

edge SemanticRequirement {
    has required: bool = True;
}

edge RuleDefinition {
    has position: int = 0;
}

walker HqlCompiler {
    has visited_conditions: list[str] = [];

    can begin with Root entry {
        print("HQL compiler: lowering graph into canonical condition IR");
        visit [->:RuleDefinition:->];
    }

    can compile with HqlRule entry {
