import io;
import from contextlib { redirect_stdout }

test "lowers allocator rule and semantic facts" {
    allocator = HqlRule(
        title="memory.allocator_candidate",
        severity="info",
        evidence="candidate"
    );
    allocator_all = HqlCondition(title="allocator.all", kind="all");
    allocator_call = HqlCondition(
        title="allocator.call",
        kind="ast",
        field_name="callee",
        operator="==",
        literal="malloc"
    );
    ownership = HqlFact(
        title="allocator.ownership",
        fact_kind="summary-ownership",
        ownership_kind="allocate"
    );
    barrier = HqlFact(
        title="allocator.barrier",
        fact_kind="summary-barrier",
        lossy=True
    );

    root +>:RuleDefinition(position=1):+> allocator;
    allocator +>:RuleCondition(position=1):+> allocator_all;
    allocator_all +>:ConditionChild(position=1):+> allocator_call;
    allocator_all +>:SemanticRequirement(required=True):+> ownership;
    allocator_call +>:SemanticRequirement(required=False):+> barrier;

    assert len([root ->:RuleDefinition:->]) == 1, "rule definition edge missing";
    assert len([allocator ->:RuleCondition:->]) == 1, "rule condition edge missing";
    assert len([allocator_all ->:ConditionChild:->]) == 1, "condition child edge missing";
    assert len([allocator_all ->:SemanticRequirement:->]) == 1, "ownership edge missing";
    assert len([allocator_call ->:SemanticRequirement:->]) == 1, "barrier edge missing";
    assert ownership.lossy == False, f"ownership lossy flag was {ownership.lossy}";
    assert barrier.lossy == True, f"barrier lossy flag was {barrier.lossy}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn HqlCompiler();
    }
    out = buf.getvalue();

    assert "rule memory.allocator_candidate [info, candidate, HQL 0.3.1]" in out, f"missing rule output: {out}";
    assert "condition all:" in out, f"missing all condition: {out}";
    assert "condition ast: callee == malloc" in out, f"missing AST condition: {out}";
    assert "fact summary-ownership (allocate, retained)" in out, f"missing ownership fact: {out}";
    assert "fact summary-barrier (, lossy)" in out, f"missing barrier fact: {out}";
}

test "detects recursive condition cycles" {
    cycle_rule = HqlRule(title="anti_analysis.timing_check");
    cycle_all = HqlCondition(title="timing.all", kind="all");
    cycle_any = HqlCondition(title="timing.any", kind="any");
    timing_fact = HqlFact(
        title="timing.fact",
        fact_kind="timing-signal",
        ownership_kind="observe"
    );

    root +>:RuleDefinition(position=1):+> cycle_rule;
    cycle_rule +>:RuleCondition(position=1):+> cycle_all;
    cycle_all +>:ConditionChild(position=1):+> cycle_any;
    cycle_all +>:SemanticRequirement(required=True):+> timing_fact;
    cycle_any +>:ConditionChild(position=1):+> cycle_all;
    cycle_any +>:SemanticRequirement(required=True):+> timing_fact;

    assert cycle_rule.severity == "info", f"default severity was {cycle_rule.severity}";
    assert cycle_rule.evidence == "signal", f"default evidence was {cycle_rule.evidence}";
    assert cycle_rule.hql_version == "0.3.1", f"default HQL version was {cycle_rule.hql_version}";
    assert len([cycle_any ->:ConditionChild:->]) == 1, "cycle edge missing";
    assert timing_fact.lossy == False, f"timing fact lossy flag was {timing_fact.lossy}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn HqlCompiler();
    }
    out = buf.getvalue();

    assert "condition any:" in out, f"missing any condition: {out}";
    assert "cycle detected at condition timing.all; branch ignored" in out, f"cycle was not detected: {out}";
    assert "fact timing-signal (observe, retained)" in out, f"missing timing fact: {out}";
}

test "fails closed when a rule has no condition edge" {
    empty_rule = HqlRule(title="empty.rule");

    root +>:RuleDefinition(position=1):+> empty_rule;

    assert len([root ->:RuleDefinition:->]) == 1, "empty rule was not linked";
    assert len([empty_rule ->:RuleCondition:->]) == 0, "unexpected condition edge exists";
    assert empty_rule.available == True, f"default availability was {empty_rule.available}";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn HqlCompiler();
    }
    out = buf.getvalue();

    assert "rule empty.rule [info, signal, HQL 0.3.1]" in out, f"missing empty rule output: {out}";
    assert "condition ast:" not in out, f"unexpected AST branch: {out}";
    assert "condition all:" not in out, f"unexpected condition branch: {out}";
    assert "fact " not in out, f"unexpected fact traversal: {out}";
}

