    playable +>:NeedsRevision:note="brighter collectibles":+> revision;
    revision +>:Keeps:frozen_at="T+48h":+> cartridge;

    assert len([root-->]) == 1, f"got {len([root-->])}";
    assert playable in [prompt ->:Generates:->], f"playable edge missing";
    assert revision in [playable ->:NeedsRevision:->], f"revision edge missing";
    assert cartridge in [revision ->:Keeps:->], f"keep edge missing";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn QuickPlayRunner();
    }
