"""Wildcard type erasure: model the recursive bound lookup from Spoon issue #6802.

Erasing `? extends E` must use E's erasure; `? super X` erases to Object.
The dangerous lookup — resolving a parameter's bound back to an executable
which erases its wildcards again — is made safe with an explicit cycle guard,
since walkers have no built-in once-per-node visitation.
"""

node TypeRef {
    has name: str = "";
    has kind: str = "plain";       # plain | wildcard | param
    has bound: str = "";           # upper bound name for wildcards/params
    has lower_bounded: bool = False;

    def erase() -> str {
        if self.kind == "wildcard" and self.lower_bounded {
            return "Object";
        }
        if self.kind == "wildcard" and self.bound != "" {
            return self.bound;
        }
        return self.name;
    }
}

node Executable {
    has signature: str = "";
    has params: list[str] = [];
}

node TypeParam {
    has name: str = "";
    has owner: str = "";
}

edge BoundsTo { }        # TypeRef/TypeParam -> TypeRef : upper bound
edge Declares { }        # TypeParam -> TypeRef : declared usage
edge ParamOf { has pos: int = 0; }  # TypeRef -> Executable : parameter usage

walker Eraser {
    has visited: list[str] = [];
    has erasures: list[str] = [];

    def mark(key: str) -> bool {
        if key in self.visited {
            return False;
        }
        self.visited.append(key);
        return True;
    }

    can start with Root entry {
        visit [-->];
    }

    can erase_ref with TypeRef entry {
        # Cycle policy: never re-enter a reference already on the erasure stack.
        if not self.mark(f"ref:{here.name}:{here.kind}") {
            print(f"[cycle-guard] skipping repeat erasure of {here.name}");
            disengage;
        }
        erased = here.erase();
        self.erasures.append(f"{here.name} -> {erased}");
        print(f"erase {here.name} ({here.kind}) => {erased}");
        visit [-->] else { disengage; }
    }

    can inspect_exec with Executable entry {
        if not self.mark(f"exec:{here.signature}") {
            print(f"[cycle-guard] skipping repeat lookup of {here.signature}");
            disengage;
        }
        print(f"executable {here.signature} params={here.params}");
        visit [-->] else { disengage; }
    }

    can inspect_param with TypeParam entry {
        if not self.mark(f"param:{here.name}") {
            print(f"[cycle-guard] skipping repeat resolve of {here.name}");
            disengage;
        }
        print(f"type param {here.name} owned by {here.owner}");
        visit [-->] else { disengage; }
    }
}

with entry {
    # GenericMap<E>.entrySet() returning Set<Map.Entry<String, E>> wrapped in
    # TypeParameterErasureRecursion<W, U> whose unwrap cycle caused the overflow.
    e = TypeParam(name="E", owner="GenericMap");
    w = TypeParam(name="W", owner="TypeParameterErasureRecursion");
    u = TypeParam(name="U", owner="TypeParameterErasureRecursion");

    wildcard = TypeRef(name="? extends E", kind="wildcard", bound="E");
    super_wildcard = TypeRef(name="? super K", kind="wildcard", lower_bounded=True);
    entry_ref = TypeRef(name="Map.Entry<String,E>", kind="plain");
    unwrapped = TypeRef(name="U", kind="param", bound="Object");

    entry_set = Executable(signature="entrySet()", params=["Set<Map.Entry<String,E>>"]);
    unwrap_m = Executable(signature="unwrap(W)", params=["W"]);

    # Bound graph (acyclic): wildcards and params resolve through their bounds.
    wildcard +>:BoundsTo:+> e;
    e +>:Declares:+> unwrapped;
    unwrapped +>:ParamOf(pos=0):+> unwrap_m;
    super_wildcard +>:BoundsTo:+> super_wildcard;

    root ++> wildcard ++> entry_set ++> entry_ref;
    root ++> super_wildcard;
    root ++> w ++> u;
    root ++> unwrap_m;

    auditor = Eraser();
    root spawn auditor;
    print(f"erasures: {auditor.erasures}");
}

