    buf = io.StringIO();
    with redirect_stdout(buf) {
        rt = root;
        top = Task(name="top");
        left = Task(name="left");
        right = Task(name="right");
        bot = Task(name="bot");
        rt ++> top ++> left ++> right ++> bot;
