"""Detect mutually recursive nested function declarations with a cycle-safe walker."""

node Module {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node FunctionDecl {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has nested: bool = False;
    has cycle_detected: bool = False;
}

edge Contains {
    has relation: str = "";
}

edge Calls {
    has relation: str = "";
}

walker CycleDetector {
    has seen: list[str] = [];
    has cycle_found: bool = False;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_module with Module entry {
        print(f"module: {here.title}");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_function with FunctionDecl entry {
        if here.title in self.seen {
            here.cycle_detected = True;
            self.cycle_found = True;
            print(f"cycle detected at nested function {here.title}");
            disengage;
        } else {
            self.seen.append(here.title);
            print(f"visiting function {here.title}");
            visit [-->] else {
                disengage;
            }
        }
    }
}

with entry {
    catalog = Module(title="recursion demo", year=2026);

    outer = FunctionDecl(title="outer", year=1, nested=False);
    even = FunctionDecl(title="even", year=2, nested=True);
    odd = FunctionDecl(title="odd", year=3, nested=True);

    root +>:Contains(relation="module"):+> catalog;
    catalog +>:Contains(relation="top-level function"):+> outer;
    outer +>:Contains(relation="nested declaration"):+> even;
    outer +>:Contains(relation="nested declaration"):+> odd;
    even +>:Calls(relation="mutual recursion"):+> odd;
    odd +>:Calls(relation="mutual recursion"):+> even;

    root spawn CycleDetector();
}

