"""Test annex for the mutually recursive nested function detector."""

import io;
import from contextlib { redirect_stdout }


test "cycle detected on mutually recursive nested declarations" {
    root ++> Module(title="recursion demo", year=2026);
    catalog = [root -->][?:Module][0];
    outer = FunctionDecl(title="outer", nested=False);
    even = FunctionDecl(title="even", nested=True);
    odd = FunctionDecl(title="odd", nested=True);

    catalog +>:Contains(relation="top-level function"):+> outer;
    outer +>:Contains(relation="nested declaration"):+> even;
    outer +>:Contains(relation="nested declaration"):+> odd;
    even +>:Calls(relation="mutual recursion"):+> odd;
    odd +>:Calls(relation="mutual recursion"):+> even;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CycleDetector();
    }

    assert res.cycle_found, "expected cycle_found True on mutually recursive nested decls";

    even_node = [outer -->][?:FunctionDecl][0];
    odd_node = [outer -->][?:FunctionDecl][1];
    assert even_node.title in res.seen or odd_node.title in res.seen, f"expected at least one of the pair in seen, got {res.seen}";

    detected_count = len([f for f in [even_node, odd_node] if f.cycle_detected]);
    assert detected_count >= 1, f"expected at least one node flagged cycle_detected, got {detected_count}";

    out = buf.getvalue();
    assert "cycle detected" in out, f"missing cycle diagnostic in output: {out}";
    assert "visiting function" in out, f"expected traversal output: {out}";
}


test "no cycle on plain forward reference among nested declarations" {
    root ++> Module(title="forward ref demo", year=2026);
    catalog = [root -->][?:Module][0];
    outer = FunctionDecl(title="outer", nested=False);
    first = FunctionDecl(title="first", nested=True);
    second = FunctionDecl(title="second", nested=True);

    catalog +>:Contains(relation="top-level function"):+> outer;
    outer +>:Contains(relation="nested declaration"):+> first;
    outer +>:Contains(relation="nested declaration"):+> second;
    first +>:Calls(relation="forward ref"):+> second;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CycleDetector();
    }

    assert not res.cycle_found, f"forward-reference nest should not flag a cycle, got cycle_found={res.cycle_found}";
    assert "first" in res.seen, f"expected 'first' traversed, seen={res.seen}";
    assert "second" in res.seen, f"expected 'second' traversed, seen={res.seen}";
    assert not first.cycle_detected, "first should not be flagged";
    assert not second.cycle_detected, "second should not be flagged";
}


test "no cycle when only one of the nested pair calls the other (no back edge)" {
    root ++> Module(title="one-way demo", year=2026);
    catalog = [root -->][?:Module][0];
    outer = FunctionDecl(title="outer", nested=False);
    a = FunctionDecl(title="alpha", nested=True);
    b = FunctionDecl(title="beta", nested=True);

    catalog +>:Contains(relation="top-level function"):+> outer;
    outer +>:Contains(relation="nested declaration"):+> a;
    outer +>:Contains(relation="nested declaration"):+> b;
    a +>:Calls(relation="calls beta"):+> b;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CycleDetector();
    }

    assert not res.cycle_found, f"one-way nested call must not be flagged, got cycle_found={res.cycle_found}";
    assert not a.cycle_detected, "alpha should not be flagged";
    assert not b.cycle_detected, "beta should not be flagged";
}


test "mutual recursion at module top level only — outer is not nested" {
    root ++> Module(title="top-level demo", year=2026);
    catalog = [root -->][?:Module][0];
    a = FunctionDecl(title="alpha-top", nested=False);
    b = FunctionDecl(title="beta-top", nested=False);

    catalog +>:Contains(relation="top-level function"):+> a;
    catalog +>:Contains(relation="top-level function"):+> b;
    a +>:Calls(relation="mutual recursion"):+> b;
    b +>:Calls(relation="mutual recursion"):+> a;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CycleDetector();
    }

    assert res.cycle_found, f"mutual cycle between two reachable functions must be detected, got cycle_found={res.cycle_found}";
    assert "alpha-top" in res.seen, f"expected 'alpha-top' in seen={res.seen}";
    assert "beta-top" in res.seen, f"expected 'beta-top' in seen={res.seen}";
    assert a.cycle_detected or b.cycle_detected, "at least one of the cycle nodes should be flagged";

    out = buf.getvalue();
    assert "cycle detected" in out, f"missing cycle diagnostic: {out}";
}


test "walker disengages cleanly on empty graph" {
    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn CycleDetector();
    }
    assert not res.cycle_found, "empty graph must not produce a false cycle";
    assert len(res.seen) == 0, f"seen should be empty on no traversal, got {res.seen}";
}

