    );
    output_root +>:Contains:+> manifest;

    key = "vesedge_qc.json@out/good";
    managed_npy = Artifact(
        path="out/good/run.npy",
        output_root="out/good",
        record_key=key,
        managed=True
    );
    managed_csv = Artifact(
        path="out/good/nested/run.area_qc.csv",
        output_root="out/good",
        record_key=key,
        managed=True
    );
    manifest +>:RecordsArtifact:+> managed_npy;
    manifest +>:RecordsArtifact:+> managed_csv;

    unrelated_npy = Artifact(
        path="out/good/user.npy",
        output_root="out/good",
        managed=False
    );
    unrelated_csv = Artifact(
        path="out/good/user.area_qc.csv",
        output_root="out/good",
        managed=False
    );
    unrelated_png = Artifact(
        path="out/good/nested/user.area_qc.png",
        output_root="out/good",
        managed=False
    );
    unrelated_txt = Artifact(
        path="out/good/nested/notes.txt",
        output_root="out/good",
        managed=False
    );
    unrelated_npy +>:LocatedIn:+> output_root;
    unrelated_csv +>:LocatedIn:+> output_root;
    unrelated_png +>:LocatedIn:+> output_root;
    unrelated_txt +>:LocatedIn:+> output_root;

    validator = ManifestValidator();
    root spawn validator;
    cleaner = ManifestCleaner(invalid_keys=validator.invalid_keys);

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn cleaner;
    }

    assert validator.failures == 0, f"got {validator.failures}";
    assert validator.inspected == 2, f"got {validator.inspected}";
    assert managed_npy.deleted, f"got {managed_npy.deleted}";
    assert managed_csv.deleted, f"got {managed_csv.deleted}";
    assert not unrelated_npy.deleted, f"got {unrelated_npy.deleted}";
    assert not unrelated_csv.deleted, f"got {unrelated_csv.deleted}";
    assert not unrelated_png.deleted, f"got {unrelated_png.deleted}";
    assert not unrelated_txt.deleted, f"got {unrelated_txt.deleted}";
    assert cleaner.removed == 2, f"got {cleaner.removed}";
    assert cleaner.blocked == 0, f"got {cleaner.blocked}";
}

test "blocks malformed provenance before deletion" {
    output_root = OutputRoot(root_path="out/bad");
    root +>:Contains:+> output_root;

    manifest = QCManifest(
        output_root="out/bad",
        provenance_valid=False,
        overwrite_requested=True,
