import from contextlib { redirect_stdout }

test "replay creates only an exact verified witness" {
    view = ScientificView(
        view_id="view-a",
        namespace="atlas/view-a",
        head_generation=17
    );

    record = ScientificDispositionRecord(
        record_id="record-1",
        proposition_id="prop-7",
        scientific_use_id="use-3",
        view_id="view-a",
        view_head_generation=17,
        primary_label="accepted",
        reason_topology="candidate:admitted",
        policy_trace="policy-v1:accept",
        policy_profile="policy-v1",
        evaluator_profile="evaluator-v4",
        historical_cutoff=1700,
        evidence_count=1
    );

    evidence = EvidenceSnapshot(
        record_id="record-1",
        proposition_id="prop-7",
        scientific_use_id="use-3",
        view_id="view-a",
        view_head_generation=17,
        reason_topology="candidate:admitted",
        policy_trace="policy-v1:accept",
        policy_profile="policy-v1",
        evaluator_profile="evaluator-v4",
        historical_cutoff=1700,
        admitted=True
    );

    root +>:Candidate:+> record;
    record +>:ContainsEvidence:+> evidence;
    evidence +>:DeclaredView:+> view;

    root spawn ReplayVerifier();

    witnesses = [view ->:ReplayProduces:->];
    assert len(witnesses) == 1, f"expected one witness, got {len(witnesses)}";

    witness = witnesses[0];
    assert witness.record_id == "record-1", f"wrong record identity: {witness.record_id}";
    assert witness.view_id == "view-a", f"wrong view identity: {witness.view_id}";
    assert witness.view_head_generation == 17, f"wrong view head: {witness.view_head_generation}";
    assert witness.primary_label == "accepted", f"wrong label: {witness.primary_label}";
    assert witness.reason_topology == "candidate:admitted", f"wrong reason: {witness.reason_topology}";
    assert witness.policy_trace == "policy-v1:accept", f"wrong trace: {witness.policy_trace}";
    assert witness.policy_profile == "policy-v1", f"wrong policy: {witness.policy_profile}";
    assert witness.evaluator_profile == "evaluator-v4", f"wrong evaluator: {witness.evaluator_profile}";
    assert view in [witness ->:LiveView:->], "witness is not bound to its live view";
}

