        view_id="view-a",
        namespace="atlas/view-a",
        head_generation=17
    );

    record = ScientificDispositionRecord(
        record_id="record-2",
        proposition_id="prop-7",
        scientific_use_id="use-3",
        view_id="view-a",
        view_head_generation=17,
        primary_label="accepted",
        reason_topology="candidate:admitted|forged:reason",
        policy_trace="policy-v1:accept",
        policy_profile="policy-v1",
        evaluator_profile="evaluator-v4",
        historical_cutoff=1700,
        evidence_count=1
    );

    evidence = EvidenceSnapshot(
        record_id="record-2",
        proposition_id="prop-7",
        scientific_use_id="use-3",
        view_id="view-a",
        view_head_generation=17,
        reason_topology="candidate:admitted",
        policy_trace="policy-v1:accept",
        policy_profile="policy-v1",
        evaluator_profile="evaluator-v4",
        historical_cutoff=1700,
        admitted=True
    );

    root +>:Candidate:+> record;
    record +>:ContainsEvidence:+> evidence;
    evidence +>:DeclaredView:+> view;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn ReplayVerifier();
    }
    out = buf.getvalue();

    assert "[REPLAY FAIL] record-2: complete result mismatch" in out, f"topology mismatch was accepted: {out}";
    assert len([view ->:ReplayProduces:->]) == 0, "equal label bypassed reason verification";
}

