test "currentness is bound to the exact live view head" {
    view = ScientificView(
        view_id="view-a",
        namespace="atlas/view-a",
        head_generation=17
    );

    record = ScientificDispositionRecord(
        record_id="record-4",
        proposition_id="prop-7",
        scientific_use_id="use-3",
        view_id="view-a",
        view_head_generation=17,
        primary_label="accepted",
        reason_topology="candidate:admitted",
        policy_trace="policy-v1:accept",
        policy_profile="policy-v1",
        evaluator_profile="evaluator-v4",
        historical_cutoff=1700,
        evidence_count=1
    );

    evidence = EvidenceSnapshot(
        record_id="record-4",
        proposition_id="prop-7",
        scientific_use_id="use-3",
        view_id="view-a",
        view_head_generation=17,
        reason_topology="candidate:admitted",
        policy_trace="policy-v1:accept",
        policy_profile="policy-v1",
        evaluator_profile="evaluator-v4",
        historical_cutoff=1700,
        admitted=True
    );

    root +>:Candidate:+> record;
    record +>:ContainsEvidence:+> evidence;
    evidence +>:DeclaredView:+> view;

    root spawn ReplayVerifier();

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn CurrentnessChecker();
    }
    current_out = buf.getvalue();

    assert "[CURRENT] atlas/view-a: record-4 is current at H17" in current_out, f"valid currentness missing: {current_out}";

    view.head_generation = 18;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn CurrentnessChecker();
    }
    stale_out = buf.getvalue();

    assert "[STALE] atlas/view-a: record-4 was verified at H17, live H18" in stale_out, f"stale currentness missing: {stale_out}";

    view.head_generation = 17;
    view.view_id = "view-b";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        root spawn CurrentnessChecker();
    }
    wrong_view_out = buf.getvalue();

    assert "[STALE]" in wrong_view_out, f"wrong view identity was treated as current: {wrong_view_out}";
}

