test "invalidates organization caches after a sale mutation" {
    organization = Organization(
        title="MeperDonas",
        year=2024,
        slug="tenant-meperdonas"
    );
    sale = Sale(
        title="sale-mutated",
        year=2024,
        amount=125.50,
        sale_day="2024-06-12",
        mutated=True
    );
    financial_cache = ReportCache(
        title="financial:2024-06",
        year=2024,
        cache_scope="organization",
        range_days=30,
        stale_after_days=5
    );
    dashboard_cache = ReportCache(
        title="dashboard:2024-06",
        year=2024,
        cache_scope="organization",
        range_days=7,
        stale_after_days=2
    );

    organization +>:Contains(organization_scope="tenant-meperdonas"):+> sale;
    sale +>:Invalidates(
        dependency_kind="sales",
        organization_scope="tenant-meperdonas"
    ):+> financial_cache;
    sale +>:Invalidates(
        dependency_kind="sales",
        organization_scope="tenant-meperdonas"
    ):+> dashboard_cache;
    root ++> organization;

    res = root spawn CacheInvalidator(max_range_days=31);

    assert len([organization ->:Contains:->]) == 1, "organization should contain one sale";
    assert len([sale ->:Invalidates:->]) == 2, "sale should invalidate two caches";
    assert financial_cache.available == False, "financial cache should be invalidated";
    assert dashboard_cache.available == False, "dashboard cache should be invalidated";
    assert res.invalidated_count == 2, f"got {res.invalidated_count} invalidations";
}

test "skips report caches beyond the configured range bound" {
    organization = Organization(
        title="MeperDonas",
        year=2024,
        slug="tenant-meperdonas"
    );
    sale = Sale(
        title="sale-broad-range",
        year=2024,
        mutated=True
    );
    broad_cache = ReportCache(
        title="financial:all-history",
        year=2024,
        cache_scope="organization",
        range_days=90,
        stale_after_days=5
    );
    bounded_cache = ReportCache(
        title="dashboard:recent",
        year=2024,
        cache_scope="organization",
        range_days=7,
        stale_after_days=2
    );

    organization +>:Contains(organization_scope="tenant-meperdonas"):+> sale;
    sale +>:Invalidates(
        dependency_kind="sales",
        organization_scope="tenant-meperdonas"
    ):+> broad_cache;
    sale +>:Invalidates(
        dependency_kind="sales",
        organization_scope="tenant-meperdonas"
    ):+> bounded_cache;
    root ++> organization;

    res = root spawn CacheInvalidator(max_range_days=31);

    assert broad_cache.available == True, "broad-range cache should remain available";
    assert bounded_cache.available == False, "bounded cache should be invalidated";
    assert res.invalidated_count == 1, f"got {res.invalidated_count} invalidations";
}

