    has title: str = "Trusted runtime";
    has year: int = 0;
    has available: bool = True;
    has publication_authority: bool = True;
}

node CredentialSource {
    has title: str = "ChessEcho Keychain";
    has year: int = 0;
    has available: bool = False;
    has service_name: str = "com.chessecho.copilot.worker";
    has account_name: str = "copilot-worker";
    has credential_type: str = "fine-grained-pat";
    has worker_only: bool = True;
}

node Worker {
    has title: str = "Trusted-local worker";
    has year: int = 0;
    has available: bool = True;
    has authenticated: bool = False;
    has publication_authority: bool = False;
}

node Candidate {
    has title: str = "Candidate commit";
    has year: int = 0;
    has available: bool = True;
    has exact_sha: str = "";
    has independently_validated: bool = False;
}

edge Delegates {
    has purpose: str = "agent-agnostic execution";
}

edge InjectsWorkerToken {
    has purpose: str = "worker-only environment injection";
}

edge ProducesCandidate {
    has purpose: str = "local commit output";
}

walker BoundaryAudit {
    has steps: int = 0;
    has max_steps: int = 8;

    can begin with Root entry {
        print("Auditing trusted-local execution boundary");
        visit [-->] else {
            disengage;
        }
    }

    can audit_runtime with TrustedRuntime entry {
        if self.steps >= self.max_steps {
            print("Traversal depth limit reached");
            disengage;
        }
        self.steps += 1;
        print(f"runtime publication authority: {here.publication_authority}");
        visit [->:Delegates:->] else {
            disengage;
        }
    }

    can inspect_source with CredentialSource entry {
        if self.steps >= self.max_steps {
            print("Traversal depth limit reached");
            disengage;
        }
        self.steps += 1;
        print(f"credential service: {here.service_name}");
        print(f"credential account: {here.account_name}");
        print(f"worker-only capability: {here.worker_only}");
        visit [->:InjectsWorkerToken:->] else {
            disengage;
        }
    }

    can inspect_worker with Worker entry {
        if self.steps >= self.max_steps {
            print("Traversal depth limit reached");
            disengage;
        }
        self.steps += 1;
        print(f"worker authenticated: {here.authenticated}");
        print(f"worker publication authority: {here.publication_authority}");
        visit [->:ProducesCandidate:->] else {
            disengage;
        }
    }

    can inspect_candidate with Candidate entry {
        if self.steps >= self.max_steps {
            print("Traversal depth limit reached");
            disengage;
        }
        self.steps += 1;
        print(f"validated candidate SHA: {here.exact_sha}");
        print(f"independently validated: {here.independently_validated}");
    }
}

with entry {
    runtime = TrustedRuntime(
        title="Trusted runtime",
        publication_authority=True
    );
    source = CredentialSource(
        title="Exact Keychain source",
        available=True,
        worker_only=True
    );
    worker = Worker(
        title="Untrusted worker",
        authenticated=True,
        publication_authority=False
    );
    candidate = Candidate(
        title="Local candidate",
        exact_sha="abc123validated",
        independently_validated=True
    );

    root ++> runtime;
    runtime +>:Delegates(purpose="agent-agnostic execution"):+> source;
    source +>:InjectsWorkerToken(purpose="COPILOT_GITHUB_TOKEN only"):+> worker;
    worker +>:ProducesCandidate(purpose="local commit output"):+> candidate;

    root spawn BoundaryAudit();
}

