    plan +>:DependsOn(reason="source-before-distillation"):+> source;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DependencyResolver();
    }
    out = buf.getvalue();

    assert len([root-->]) == 1, f"expected one root child";
    assert len([plan ->:DependsOn:->]) == 1, f"expected one dependency";
    assert "dependency visit: distillation" in out, f"missing plan visit: {out}";
    assert "dependency visit: repository-scan" in out, f"missing source visit: {out}";
    assert "dependency leaf: repository-scan" in out, f"missing dependency leaf: {out}";
}

