import io;
import from contextlib { redirect_stdout }

test "audits owned repository and worktree topology" {
    run = ProviderRun(
        title="test run",
        run_key="run-test",
        state="owned"
    );
    repository = FixtureRepository(
        title="test repository",
        repository_key="repo-test",
        branch="main",
        object_format="sha1"
    );
    worktree = Worktree(
        title="test worktree",
        worktree_key="wt-test",
        path_label="owned-run-root/test-worktree",
        registered=True
    );

    root ++> run;
    run +>:OwnsRepository:+> repository;
    repository +>:Materializes:+> worktree;

    assert len([root-->]) == 1, f"root children: {len([root-->])}";
    assert run in [root-->], f"root does not own run";
    assert repository in [run ->:OwnsRepository:->], f"repository edge missing";
    assert worktree in [repository ->:Materializes:->], f"worktree edge missing";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        result = root spawn TopologyAuditor();
    }
    out = buf.getvalue();

    assert "auditing owned provider topology" in out, f"missing audit marker: {out}";
    assert "run run-test: owned" in out, f"missing run audit: {out}";
    assert "repository repo-test on main" in out, f"missing repository audit: {out}";
    assert "worktree wt-test: registered" in out, f"missing worktree audit: {out}";
}

test "detects cyclic operation dependencies" {
    run = ProviderRun(
        title="cycle run",
        run_key="run-cycle",
        state="owned"
    );
    first = Operation(
        title="first operation",
        operation_key="op-first",
        state="planned"
    );
    second = Operation(
        title="second operation",
        operation_key="op-second",
        state="reconciliation-required"
    );

    root ++> run;
    run +>:Schedules:+> first;
    first +>:DependsOn:+> second;
    second +>:DependsOn:+> first;

    assert first in [run ->:Schedules:->], f"scheduled operation missing";
    assert second in [first ->:DependsOn:->], f"second dependency missing";
    assert first in [second ->:DependsOn:->], f"cycle return edge missing";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        result = root spawn DependencyAuditor();
    }
    out = buf.getvalue();

    assert "auditing operation dependencies" in out, f"missing dependency marker: {out}";
    assert "operation op-first: planned" in out, f"missing first operation: {out}";
    assert "operation op-second: reconciliation-required" in out, f"missing second operation: {out}";
    assert "dependency cycle detected at op-first" in out, f"missing cycle report: {out}";
}

test "reports unregistered worktree and reconciliation state" {
    run = ProviderRun(
        title="recovery run",
        run_key="run-recovery",
        state="reconciliation-required"
    );
    repository = FixtureRepository(
        title="recovery repository",
        repository_key="repo-recovery",
        branch="main",
