import io;
import from contextlib { redirect_stdout }

test "preserve JSONC string content and clean installed files" {
    original = "{\"pattern\":\"comma,}\",\"bracket\":\"comma,]\",}";
    config = HostConfig(
        title="host-config",
        year=2026,
        available=True,
