    plugin +>:OwnsFile:+> owned;
    plugin +>:OwnsFile:+> shared;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn Installer();
    }
    out = buf.getvalue();

    assert res.configs_seen == 1, f"configs_seen was {res.configs_seen}";
    assert res.cleaned_files == 1, f"cleaned_files was {res.cleaned_files}";
    assert config.backup_bytes == original, f"backup was {config.backup_bytes}";
