    assert config.plugin_reference == False, f"plugin reference remained {config.plugin_reference}";
    assert owned.removed == True, f"owned file removed={owned.removed}";
    assert shared.removed == False, f"shared file removed={shared.removed}";
    assert "preserved backup and removed plugin reference" in out, f"missing config report: {out}";
    assert "removed plugin file cache" in out, f"missing cleanup report: {out}";
    assert "kept unrelated file shared" in out, f"missing unrelated-file report: {out}";
}

