import io;
import from contextlib { redirect_stdout }

test "mapped multi-hop proof preserves steps and description" {
    verbs = {
        "follow": "follows",
        "like": "liked",
        "contains": "contains"
    };
    anchor = GraphEntity(title="User_A", kind="user");
    user_b = GraphEntity(
        title="User_B",
        kind="user",
        incoming_edge_type="follow"
    );
    tweet_y = GraphEntity(
        title="Tweet_Y",
        kind="tweet",
        incoming_edge_type="like"
    );
    topic = GraphEntity(
        title="#AI",
        kind="topic",
        incoming_edge_type="contains"
    );
    candidate = GraphEntity(
        title="Tweet_Z",
        kind="tweet",
        incoming_edge_type="contains"
    );

    root ++> anchor;
    anchor +>:SocialLink(edge_type="follow"):+> user_b;
    user_b +>:SocialLink(edge_type="like"):+> tweet_y;
    tweet_y +>:SocialLink(edge_type="contains"):+> topic;
    topic +>:SocialLink(edge_type="contains"):+> candidate;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SocialProofExtractor(
            candidate_title="Tweet_Z",
            edge_verbs=verbs
        );
    }
    out = buf.getvalue();

    assert len(res.steps) == 4, f"expected four proof steps, got {len(res.steps)}";
    assert res.steps[0].source_title == "User_A", f"first source: {res.steps[0].source_title}";
    assert res.steps[0].verb == "follows", f"first verb: {res.steps[0].verb}";
    assert res.steps[3].target_title == "Tweet_Z", f"last target: {res.steps[3].target_title}";
    assert res.description == "User_A follows User_B, then User_B liked Tweet_Y, then Tweet_Y contains #AI, then #AI contains Tweet_Z", f"description: {res.description}";
    assert "Steps=4" in out, f"missing step count in report: {out}";
}

test "direct candidate produces the minimal empty-path proof" {
    candidate = GraphEntity(title="Tweet_Z", kind="tweet");
    root ++> candidate;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SocialProofExtractor(candidate_title="Tweet_Z");
    }
    out = buf.getvalue();

    assert len(res.steps) == 0, f"direct proof must have no steps, got {len(res.steps)}";
    assert res.description == "directly related", f"minimal proof: {res.description}";
    assert "Anchor=Tweet_Z, Candidate=Tweet_Z" in out, f"wrong endpoints: {out}";
    assert "directly related" in out, f"missing minimal description: {out}";
}

test "cycles stop with an explicit truncation marker" {
