    assert store in [root-->], "store is not linked from root";
    assert server in [store ->:RegistersServer:->], "server relationship missing";
    assert session in [server ->:HostsSession:->], "session relationship missing";
    assert record in [session ->:ContainsEntry:->], "entry relationship missing";
    assert len([server ->:HostsSession:->]) == 1, "unexpected session count";
}

test "auditor counts sessions and entries and reports status" {
    store = SessionStore(expanded_path="~/.mcp-studio/sessions/");
    server = McpServer(name="demo-server", version="1.0.0");
    first = McpSession(
        session_id="sess-001",
        server_name="demo-server",
        tags="regression",
        started_at=20250101
    );
    second = McpSession(
        session_id="sess-002",
        server_name="demo-server",
        tags="failed-replay",
        started_at=20250102,
        available=False
    );
    request = SessionEntry(sequence=1, kind="request", payload="tools/list");
    response = SessionEntry(sequence=2, kind="response", payload="200 OK");
    failed_request = SessionEntry(
        sequence=1,
        kind="request",
        payload="resources/read"
    );

    root ++> store;
    store +>:RegistersServer:+> server;
    server +>:HostsSession:+> first;
    server +>:HostsSession:+> second;
    first +>:ContainsEntry:+> request;
    first +>:ContainsEntry:+> response;
    second +>:ContainsEntry:+> failed_request;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn SessionAuditor(max_hops=8);
    }
    out = buf.getvalue();

    assert res.session_count == 2, f"session count: {res.session_count}";
    assert res.entry_count == 3, f"entry count: {res.entry_count}";
