import io;
import from contextlib { redirect_stdout }

test "dependency audit detects typed-edge cycles" {
    c1 = Case(
        case_id="C-001",
        subsystem="preprocessing"
    );
    c2 = Case(
        case_id="C-002",
        subsystem="diagnostics",
        valid_program=False
    );
    c3 = Case(
        case_id="C-003",
        subsystem="codegen"
    );

    root ++> c1;
    c1 +>:DependsOn(reason="preprocess before diagnostics"):+> c2;
    c2 +>:DependsOn(reason="diagnostics before code generation"):+> c3;
    c3 +>:DependsOn(reason="cycle probe"):+> c1;

    assert len([root -->]) == 1, f"unexpected root children: {len([root -->])}";
    assert c2 in [c1 ->:DependsOn:->], f"missing C-001 dependency";
    assert c3 in [c2 ->:DependsOn:->], f"missing C-002 dependency";
    assert c1 in [c3 ->:DependsOn:->], f"missing cycle edge";

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DependencyAuditor();
    }
    out = buf.getvalue();

    assert len(res.seen) == 3, f"audited cases: {res.seen}";
    assert "checking C-001 in preprocessing" in out, f"missing first audit: {out}";
    assert "checking C-002 in diagnostics" in out, f"missing second audit: {out}";
    assert "checking C-003 in codegen" in out, f"missing third audit: {out}";
    assert "cycle detected at case C-001" in out, f"missing cycle report: {out}";
}

test "fidelity audit reports invalid cases and artifact mismatches" {
    c1 = Case(
        case_id="C-001",
        subsystem="preprocessing",
        valid_program=True
    );
    c2 = Case(
        case_id="C-002",
        subsystem="diagnostics",
        valid_program=False
    );

    o1 = Observation(
        owner="preprocessing",
        normalized_match=True,
        authoritative=True
    );
    o2 = Observation(
        owner="diagnostics",
        normalized_match=False,
        authoritative=True
    );

    a1 = Artifact(
        artifact_kind="preprocessed",
        fingerprint="pp-c001",
        bytes_match=True,
        structure_match=True
    );
    a2 = Artifact(
        artifact_kind="object",
        fingerprint="obj-c002",
        bytes_match=False,
        structure_match=True
    );

    root ++> c1;
    root ++> c2;
    c1 +>:ObservedBy(channel="stdout/stderr"):+> o1;
    c2 +>:ObservedBy(channel="stdout/stderr"):+> o2;
    o1 +>:Captures(artifact_role="preprocessed output"):+> a1;
    o2 +>:Captures(artifact_role="emitted object"):+> a2;

    assert c2 in [root -->], f"invalid case is not reachable";
    assert o2 in [c2 ->:ObservedBy:->], f"diagnostic observation is missing";
    assert a2 in [o2 ->:Captures:->], f"object artifact is missing";
    assert a2.bytes_match == False, f"artifact mismatch was lost";
    assert a2.structure_match == True, f"artifact structure mismatch changed";

    buf = io.StringIO();
