import from contextlib { redirect_stdout }

test "accepts reviewed isolated handoff before reconciled integration" {
    plan = Plan(
        title="Kernel V2 isolated source delivery",
        delivery_target_branch="kernel-v2/architecture"
    );
    work = Work(
        title="WSL performance follow-through",
        source_branch="work-profile-and-remove-duplicate-exp",
        candidate_commit="d338b273b1d1fa0331cfd5baee5f72ebee6eac49",
        reviewed=True,
        integrated=False
    );
    receipt = SourceHandoff(
        title="Reviewed source-only handoff",
        isolated_ref="work-profile-and-remove-duplicate-exp",
        exact_commit="d338b273b1d1fa0331cfd5baee5f72ebee6eac49",
        reviewed=True,
        published=True,
        integrated=False
    );
    authority = IntegrationAuthority(
        title="Mac integration authority",
        owner="Mac",
        integrated_commit="d338b273b1d1fa0331cfd5baee5f72ebee6eac49",
        reconciled=True
    );

    root ++> plan;
    plan +>:PlanWork:+> work;
    work +>:Publishes:+> receipt;
    receipt +>:AwaitsIntegration:+> authority;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        res = root spawn DeliveryAuditor();
    }
    out = buf.getvalue();

    assert len([root-->]) == 1, f"unexpected root children: {len([root-->])}";
    assert work in [plan ->:PlanWork:->], f"missing PlanWork edge";
    assert receipt in [work ->:Publishes:->], f"missing Publishes edge";
    assert authority in [receipt ->:AwaitsIntegration:->], f"missing AwaitsIntegration edge";
    assert "source-only receipt accepted" in out, f"missing acceptance: {out}";
    assert "shared-target integration complete: False" in out, f"work was falsely integrated: {out}";
    assert "integration authority reconciled" in out, f"missing reconciliation: {out}";
}

test "rejects handoff that is not isolated from target branch" {
    plan = Plan(
        title="Target containment check",
        delivery_target_branch="kernel-v2/architecture"
    );
