    change +>:DependsOn(reason="candidate dependency"):+> candidate;
    candidate +>:DependsOn(reason="evidence dependency"):+> evidence;
    evidence +>:DependsOn(reason="source dependency"):+> source;

    assert len([root-->]) == 1, f"expected one root child, got {len([root-->])}";
    assert change in [root-->], f"root does not reach {change.title}";
    assert candidate in [change ->:DependsOn:->], f"missing candidate dependency";
