node Proposal {
    has title: str = "";
    has summary: str = "";
    has patch_layout: str = "";
    has target_version: int = 0;
    has accept: bool = False;
    has verdict: str = "pending";
    has year: int = 0;
    has available: bool = True;
}

edge Houses { }

edge PendingPatch { }

walker Compositor {
    can start with Root entry {
        visit [-->];
    }

    can preview_product with Product entry {
        label = "active" if here.available else "inactive";
        print(f"[{label}] product {here.title} ({here.year})");
        visit [->:Houses:->] else { disengage; }
    }

    can preview_screen with Screen entry {
        state = "live" if here.available else "hidden";
        print(f"  screen {here.title} [{state}] v{here.version} layout={here.layout}");
        visit [->:PendingPatch:->];
    }

    can preview_proposal with Proposal entry {
        print(f"    patch {here.title}: {here.summary} -> {here.patch_layout} "
              f"(target v{here.target_version}, verdict={here.verdict})");
    }
}

walker RevisionGate {
    has approved: int = 0;
    has rejected: int = 0;
    has stale: int = 0;
    has current_screen: Screen | None = None;

    can start with Root entry {
        visit [-->];
    }

    can scope_product with Product entry {
        visit [->:Houses:->] else { disengage; }
    }

    can review_screen with Screen entry {
        self.current_screen = here;
        visit [->:PendingPatch:->];
    }

    can decide with Proposal entry {
        screen = self.current_screen;
        if screen is None {
            disengage;
        }
        if here.verdict != "pending" {
            return;
        }
        if here.target_version != screen.version {
            here.verdict = "stale";
            self.stale += 1;
            print(f"STALE {here.title}: need v{here.target_version}, screen at v{screen.version}");
            return;
        }
        if here.accept {
            screen.layout = here.patch_layout;
            screen.version += 1;
            here.verdict = "approved";
            self.approved += 1;
            print(f"APPROVED {here.title}: layout={screen.layout} v{screen.version}");
        } else {
            here.verdict = "rejected";
            self.rejected += 1;
            print(f"REJECTED {here.title}: model unchanged layout={screen.layout}");
        }
    }
}

