"""Safe search indexing over a directory graph with a symlink cycle."""

node FsEntry {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has visited: bool = False;
}

node Directory(FsEntry) {
    has is_symlink: bool = False;
}

node File(FsEntry) {
    has size: int = 0;
}

edge Contains { }

walker SearchIndexer {
    has directory_count: int = 0;
    has file_count: int = 0;
    has skipped_symlinks: int = 0;
    has repeated_directories: int = 0;

    can start with Root entry {
        visit [->:Contains:->] else { disengage; }
    }

    can index with Directory entry {
        if here.is_symlink {
            self.skipped_symlinks += 1;
            print(f"skip symlink directory: {here.title}");
        } else {
            if here.visited {
                self.repeated_directories += 1;
                print(f"skip already visited directory: {here.title}");
            } else {
                here.visited = True;
                self.directory_count += 1;
                print(f"index directory: {here.title}");
                visit [->:Contains:->] else { disengage; }
            }
        }
    }

    can record with File entry {
        self.file_count += 1;
        print(f"index file: {here.title} ({here.size} bytes)");
    }
}

