    has rebuild_required: bool = False;
}

node Canon {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has owner_approved: bool = False;
}

edge Contains { }
edge Produces {
    has channel: str = "";
}
edge FeedsWorking {
    has relation: str = "";
}
edge PublishesCanon {
    has owner_gate: bool = False;
}
edge ReferencesSource { }

walker InvalidationAudit {
    has depth: int = 0;
    has max_depth: int = 5;
