    can inspect_working with WorkingModel entry {
        if self.source_revoked {
            here.available = False;
            here.rebuild_required = True;
        }
        print(f"working model: {here.title}, rebuild={here.rebuild_required}");
        self.depth += 1;
        visit [->:PublishesCanon:->] else {
            disengage;
        }
    }

    can inspect_canon with Canon entry {
        if self.source_revoked {
            here.available = False;
            here.owner_approved = False;
        }
        print(f"canon: {here.title}, available={here.available}, "
              f"approved={here.owner_approved}");
        self.depth += 1;
        visit [->:ReferencesSource:->] else {
            disengage;
        }
    }
}

