}

node Task {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has task_id: str = "";
    has invalidated: bool = False;
}

edge Hosts { }
edge Starts { }
edge Includes { }
edge DependsOn {
    has required: bool = True;
}

walker DependencyAudit {
    has seen_ids: list[str] = [];
    has execution_order: list[str] = [];
    has invalidated_ids: list[str] = [];
    has cycle_found: bool = False;

    can begin with Root entry {
        print("Auditing the agent run graph");
        visit [->:Hosts:->] else { disengage; }
    }

    can announce with Agent | Run entry {
        print(f"Entering {here.title}");
        visit [-->];
    }

    can order_task with Task entry {
        if here.task_id in self.seen_ids {
            self.cycle_found = True;
            print(f"Cycle guard: {here.task_id} was already reached");
            return;
        }

        self.seen_ids.append(here.task_id);
        visit [->:DependsOn:->] else { disengage; }

        if here.invalidated {
