            print(f"Invalidated task: {here.task_id}");
        } else {
            self.execution_order.append(here.task_id);
            print(f"Dependency-ready task: {here.task_id}");
        }
    }

    can summarize with Root exit {
        report {
            "execution_order": self.execution_order,
            "invalidated": self.invalidated_ids,
            "cycle_found": self.cycle_found
        };
    }
}

