        if here.state == "abandoned" {
            print(f"preserving historical worker identity for {here.task_id}");
            self.expected_repository = here.repository;
            self.expected_product = here.product;
            self.expected_logical_key = here.logical_key;
            visit [->:Supersedes:->] else {
