"""Retrospective draft review with typed relationships and cycle-safe walkers."""

node Retrospective {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has stage: str = "DISCUSS";
    has facilitator_name: str = "";
}

node ReviewItem {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has review_id: str = "";
    has kind: str = "DECISION";
    has review_status: str = "DRAFT";
    has review_decision: str = "HOLD";
    has owner_name: str = "";
    has due_date: str = "";
    has topic: str = "";
    has source: str = "";
}

node Participant {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has name: str = "";
}

edge Contains {
    has position: int = 0;
}

edge FacilitatedBy {
    has role: str = "cycle-facilitator";
}

edge OwnedBy {
    has role: str = "project-member";
}

edge RelatedDraft {
    has relation: str = "extracted-neighbor";
}

walker FacilitatorReview {
    has facilitator_name: str = "";
    has seen_ids: list[str] = [];
    has accepted_count: int = 0;
    has rejected_count: int = 0;
    has unresolved_count: int = 0;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can open with Retrospective entry {
        if (self.facilitator_name != here.facilitator_name) {
            print("review denied: facilitator mismatch");
            disengage;
        }
        if (here.stage != "DISCUSS") {
            print("review denied: retrospective is not in DISCUSS");
            disengage;
        }
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can review with ReviewItem entry {
        if (here.review_id in self.seen_ids) {
            print(f"cycle skipped at {here.review_id}");
            return;
        }
        self.seen_ids.append(here.review_id);

        if (here.review_status != "DRAFT") {
            print(f"{here.review_id} already resolved");
        } elif (here.kind == "ACTION" and here.owner_name == "") {
            print(f"{here.review_id} remains DRAFT: owner required");
            self.unresolved_count += 1;
            return;
        } elif (here.review_decision == "REJECT") {
            print(f"rejecting and deleting {here.review_id}");
            self.rejected_count += 1;
            del here;
            return;
        } else {
            here.review_status = "CONFIRMED";
            self.accepted_count += 1;
            print(f"confirmed {here.review_id} from {here.source}");
        }

        visit [->:RelatedDraft:->] else {
            disengage;
        }
    }
}

walker OwnershipAudit {
    has member_count: int = 0;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can scan with Retrospective entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can check with ReviewItem entry {
        if (here.review_status == "CONFIRMED" and here.owner_name != "") {
            visit [->:OwnedBy:->] else {
                disengage;
            }
        }
    }

    can verify with Participant entry {
        self.member_count += 1;
        print(f"confirmed owner: {here.name}");
    }
}

with entry {
    retrospective = Retrospective(
