import io;
import from contextlib { redirect_stdout }

test "facilitator confirms drafts and skips related cycles" {
    retrospective = Retrospective(
        title="Sprint review",
        year=2025,
        facilitator_name="Ari"
    );
    decision = ReviewItem(
        title="Adopt smaller releases",
        review_id="D-1",
        kind="DECISION",
        review_decision="ACCEPT",
        source="transcript:42"
    );
    action = ReviewItem(
        title="Publish checklist",
        review_id="A-1",
        kind="ACTION",
        review_decision="ACCEPT",
        owner_name="Mina",
        source="transcript:57"
    );
    summary = ReviewItem(
        title="Safer releases",
        review_id="S-1",
        kind="SUMMARY",
        review_decision="ACCEPT",
        source="generated-summary"
    );

    root ++> retrospective;
    retrospective +>:Contains(position=1):+> decision;
    retrospective +>:Contains(position=2):+> action;
    retrospective +>:Contains(position=3):+> summary;
    decision +>:RelatedDraft(relation="supports"):+> action;
    action +>:RelatedDraft(relation="summarizes"):+> summary;
    summary +>:RelatedDraft(relation="originates-from"):+> decision;

    reviewer = root spawn FacilitatorReview(facilitator_name="Ari");

    assert reviewer.accepted_count == 3, f"accepted={reviewer.accepted_count}";
    assert reviewer.rejected_count == 0, f"rejected={reviewer.rejected_count}";
    assert reviewer.unresolved_count == 0, f"unresolved={reviewer.unresolved_count}";
    assert len(reviewer.seen_ids) == 3, f"seen={reviewer.seen_ids}";
    assert decision.review_status == "CONFIRMED", f"decision={decision.review_status}";
    assert action.review_status == "CONFIRMED", f"action={action.review_status}";
    assert summary.review_status == "CONFIRMED", f"summary={summary.review_status}";
    assert action.source == "transcript:57", f"source={action.source}";
}

test "rejection deletes only the rejected draft and ownerless actions stay draft" {
    retrospective = Retrospective(
        title="Sprint review",
        year=2025,
        facilitator_name="Ari"
    );
    action = ReviewItem(
        title="Document rollback",
        review_id="A-2",
        kind="ACTION",
        review_decision="ACCEPT",
        source="transcript:61"
    );
    rejected = ReviewItem(
        title="Skip checks",
        review_id="D-2",
        kind="DECISION",
        review_decision="REJECT",
        source="transcript:64"
    );

    root ++> retrospective;
    retrospective +>:Contains(position=1):+> action;
    retrospective +>:Contains(position=2):+> rejected;

    reviewer = root spawn FacilitatorReview(facilitator_name="Ari");

    assert reviewer.accepted_count == 0, f"accepted={reviewer.accepted_count}";
    assert reviewer.rejected_count == 1, f"rejected={reviewer.rejected_count}";
    assert reviewer.unresolved_count == 1, f"unresolved={reviewer.unresolved_count}";
    assert action.review_status == "DRAFT", f"action={action.review_status}";
    assert action in [retrospective ->:Contains:->], "ownerless action was removed";
    assert len([retrospective ->:Contains:->]) == 1, "rejected draft remains connected";
}

test "only the assigned facilitator can review drafts" {
    retrospective = Retrospective(
        title="Sprint review",
        year=2025,
        facilitator_name="Ari"
    );
    decision = ReviewItem(
        title="Adopt smaller releases",
        review_id="D-3",
        kind="DECISION",
        review_decision="ACCEPT",
        source="transcript:70"
    );

    root ++> retrospective;
    retrospective +>:Contains(position=1):+> decision;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        reviewer = root spawn FacilitatorReview(facilitator_name="Bea");
    }
    out = buf.getvalue();

    assert "facilitator mismatch" in out, f"output={out}";
    assert reviewer.accepted_count == 0, f"accepted={reviewer.accepted_count}";
    assert decision.review_status == "DRAFT", f"decision={decision.review_status}";
}

test "completed retrospectives reject review writes" {
    retrospective = Retrospective(
        title="Closed review",
        year=2025,
        stage="COMPLETE",
        facilitator_name="Ari"
    );
    summary = ReviewItem(
        title="Final summary",
        review_id="S-4",
        kind="SUMMARY",
        review_decision="ACCEPT",
        source="generated-summary"
    );

    root ++> retrospective;
    retrospective +>:Contains(position=1):+> summary;

    buf = io.StringIO();
    with redirect_stdout(buf) {
        reviewer = root spawn FacilitatorReview(facilitator_name="Ari");
    }
    out = buf.getvalue();

    assert "not in DISCUSS" in out, f"output={out}";
    assert reviewer.accepted_count == 0, f"accepted={reviewer.accepted_count}";
    assert summary.review_status == "DRAFT", f"summary={summary.review_status}";
}

test "ownership audit follows confirmed owned actions" {
    retrospective = Retrospective(
        title="Sprint review",
        year=2025,
        facilitator_name="Ari"
    );
    action = ReviewItem(
        title="Publish checklist",
        review_id="A-5",
        kind="ACTION",
        review_status="CONFIRMED",
        owner_name="Mina"
    );
    decision = ReviewItem(
        title="Adopt smaller releases",
        review_id="D-5",
        kind="DECISION",
        review_status="CONFIRMED"
    );
    mina = Participant(title="Project member Mina", name="Mina");

    root ++> retrospective;
    retrospective +>:Contains(position=1):+> action;
    retrospective +>:Contains(position=2):+> decision;
    action +>:OwnedBy(role="project-member"):+> mina;

    auditor = root spawn OwnershipAudit();

    assert auditor.member_count == 1, f"owners_checked={auditor.member_count}";
}
